-- Sources: data/i18n/zhCN. Lore text adapted from warcraft.wiki.gg (CC BY-SA 4.0); the core add-on's src fields name the articles.
local P = LoreForeverPacks.Begin("LoreForever_Lang_zhCN")
P.entries["quest:97971"] = {n="Camping 101: Skinning",s="Camping 101: Skinning 指导冒险者如何将收集到的毛皮制作成实用的营地椅子，用于野外露营。在申达尔村的 Mendalass Tattermend 的指引下，剥皮师们学会了将采集技艺与野外生存及篝火休闲相结合。",h="Camping 101: Skinning 指导冒险者如何将收集到的毛皮制作成实用的营地椅子，用于野外露营。在申达尔村的 Mendalass Tattermend...",kw={"营地椅子","篝火","camping 101","毛皮","mendalass tattermend","申达尔村","剥皮","荒野"},ang={["profession:Cooking"]="烹饪与野外生存相辅相成；正如 Mendalass 所指出的，搭建一个合适的营地需要基础的篝火，这通常是由烹饪训练师传授的技能。"},sec={{t="野外舒适度",b="从被击败的野兽身上采集毛皮是艾泽拉斯各地的一项基本生存技能，但它的用途远不止于简单的护甲制作。通过 Camping 101: Skinning，采集者们学会了将他们的专业技能转向野外生存，制作一把便携式的营地椅子。在野外找个舒适的座位休息片刻，能让疲惫的冒险者在下一次战斗前恢复体力，保持巅峰作战状态。"},{t="申达尔村的教导",b="一旦冒险者证明了自己剥皮刀的熟练度，他们就会被派往申达尔村去见 Mendalass Tattermend，以掌握这个配方。Mendalass 会指导旅行者如何用收集到的毛皮组装耐用的座椅。然而，建立一个营地不仅仅需要家具：定居点不会容忍在城镇范围内搭建临时营地，而且没有噼啪作响的篝火，营地就不算真正完成——这项技能通常是向当地烹饪训练师学习的。"}},faq={{q="Camping 101: Skinning 是关于什么的？",a="Camping 101: Skinning 指引熟练的剥皮师前往申达尔村寻找 Mendalass Tattermend。通过完成此项训练，冒险者可以学会如何将收获的毛皮重新利用，制作成一把实用的营地椅子，用于野外休息和恢复。",al={"这是什么任务","camping 101 的目的","为什么要完成这个任务"}},{q="Mendalass Tattermend 是谁？",a="Mendalass Tattermend 是一位位于申达尔村的剥皮训练师。他教导熟练的剥皮师如何将采集到的毛皮缝制成舒适的野外露营座椅。",al={"mendalass 是谁","谁教授营地椅子","mendalass tattermend"}},{q="在哪里可以找到 Mendalass Tattermend？",a="Mendalass Tattermend 居住在申达尔村，冒险者必须前往那里展示他们的技能，并学习制作营地装备的艺术。",al={"mendalass 在哪里","申达尔村在哪里","我在哪里交任务"}},{q="这个任务教你制作什么物品？",a="剥皮师学会了配方，可以使用从被击败的野兽身上采集到的皮和毛皮来制作营地椅子，为在野外时提供一个舒适的休息座位。",al={"剥皮师制作什么","营地椅子配方","我能得到什么物品"}},{q="你可以在城镇内搭建营地吗？",a="城镇居民不赞成在定居点中间搭建营地。营地和营地椅子应该搭建在远离城市中心的荒野中。",al={"我能在城里露营吗","我在哪里可以搭营地","在哪里使用营地椅子"}},{q="搭建一个合适的营地还需要什么？",a="每一个合适的营地在完成前都需要一堆噼啪作响的篝火。尚未掌握生火技能的冒险者建议咨询烹饪训练师来学习基础知识。",al={"搭营地还需要什么","需要篝火","营地要求"}}},fp="21,267,20.446.0,33.502.0,36.232.0,28.185.0,40.147.0,44.170.0,34.158.0,44.189.0"}
P.entries["quest:97973"] = {n="Camping 101: Tailoring",s="《Camping 101: Tailoring》向裁缝们介绍了为野外营地制作专业装备的艺术。通过向Shen'dar Village的Taleen Shimmerthread展示技艺，裁缝们可以学会缝制一面鼓舞人心的阵营旗帜，以提振士气并维持营地状态。",h="《Camping 101: Tailoring》向裁缝们介绍了为野外营地制作专业装备的艺术。通过向Shen'dar Village的Taleen...",kw={"营地旗帜","露营","camping 101: tailoring","阵营旗帜","申达尔村","裁缝","taleen shimmerthread","专业技能"},ang={["profession:Tailoring"]="裁缝们学会制作鼓舞人心的阵营旗帜，这能提升营地士气并为野外的盟友补充活力。"},sec={{t="织布工对营地的贡献",b="《Camping 101: Tailoring》指导布甲工匠将他们的技艺扩展到简单的服装和包袋之外。在荒野中，生存不仅仅需要保暖的衣物；一个合适的营地往往决定了你能坚持多久。我们鼓励裁缝们寻求进阶指导，将布卷转化为团结与坚韧的象征。"},{t="Shen'dar Village的指导",b="该任务引导有抱负的裁缝前往Shen'dar Village，Taleen Shimmerthread将在那里提供露营工艺的指导。那些在裁缝技艺上达到足够熟练度的工匠可以学习制作阵营旗帜的方法。这种旗帜经过精心缝制，骄傲地插在营地中，不仅能作为激励人心的集合点，还能提升士气，让盟友们在接下来的挑战中保持活力。"}},faq={{q="什么是《Camping 101: Tailoring》？",a="《Camping 101: Tailoring》引导有潜力的裁缝去寻求野外工艺的专业指导。一旦你展示了足够的裁缝技艺，就可以学习如何为野外营地制作一面装饰性且鼓舞人心的阵营旗帜。",al={"这是什么任务","camping 101 tailoring任务","裁缝露营旗帜"}},{q="Taleen Shimmerthread是谁？",a="Taleen Shimmerthread是位于Shen'dar Village的一位裁缝专家。她指导技艺娴熟的工匠如何编织露营专用的裁缝物品，包括能提升营地士气的旗帜。",al={"taleen shimmerthread","谁教授裁缝旗帜","taleen shimmerthread在哪里"}},{q="Shen'dar Village在哪里？",a="Shen'dar Village是Taleen Shimmerthread居住的定居点。裁缝们会前往那里，接受关于如何将他们的布艺技艺应用到露营装备上的专业指导。",al={"shendar village在哪里","shendar village位置"}},{q="裁缝可以学习制作什么露营物品？",a="阵营旗帜是裁缝可以制作的一种露营物品。在任何战场或艰苦的远征中，保持灵感和士气至关重要，插上一面旗帜能为在营地休息的人们提供充满活力的氛围。",al={"阵营旗帜露营","裁缝为营地做什么","裁缝营地物品"}},{q="学习露营旗帜有什么要求？",a="你必须在Shen'dar Village向Taleen Shimmerthread展示你在裁缝专业上的熟练度，她才会教你编织阵营旗帜的图纸。",al={"如何学习阵营旗帜","裁缝露营旗帜要求"}},{q="为什么阵营旗帜在营地中很有价值？",a="士气和灵感在任何战役中都至关重要。裁缝们缝制阵营旗帜是为了展示忠诚，并提供一个能激发活力的焦点，支撑冒险者们度过艰苦的旅程。",al={"为什么制作阵营旗帜","露营旗帜士气"}}},fp="22,136,33.268.0,31.258.0,31.176.0,28.160.0,26.138.0,45.114.0,54.133.0,41.149.0"}
P.entries["quest:97977"] = {n="Nature's Call",s="Nature's Call是幽影谷的一个任务，树妖塔琳德拉试图找出当地的止松熊怪为何会突然反目，背弃与暗夜精灵长久以来的盟友关系。通过收集他们废弃营地中的雕刻图腾，冒险者们得以揭示正在泰达希尔蔓延的令人不安的精神腐蚀。",h="Nature's Call是幽影谷的一个任务，树妖塔琳德拉试图找出当地的止松熊怪为何会突然反目，背弃与暗夜精灵长久以来的盟友关系。通过收集他们废弃营地中的雕刻图腾，冒险者们得以揭示正在泰达希尔蔓延的令人不安的精神腐蚀。",kw={"熊怪","止松","小鬼","贪婪小鬼","nature's call","梦魇","幽影谷","塔琳德拉","泰达希尔","图腾"},ang={["class:Druid"]="德鲁伊能感知到自然平衡以及影响卡利姆多生物的精神腐蚀，这使得被梦魇驱动的熊怪图腾腐蚀成为一个令人担忧的动向。",["faction:Alliance"]="保卫泰达希尔的枝干对于保护这个新兴的暗夜精灵国度至关重要，也能确保他们新结识的联盟盟友在卡利姆多站稳脚跟。",["race:NightElf"]="止松熊怪曾是暗夜精灵长期的伙伴，因此他们堕落为敌对和疯狂的状态，对于泰达希尔的守卫者而言是一场极为私人的悲剧。"},sec={{t="调查幽影谷",b="Nature's Call是幽影谷的一个调查任务，由树妖塔琳德拉发布。她无法相信止松熊怪会无缘无故地抛弃与暗夜精灵数百年的友谊，因此请求旅行者们搜寻位于山谷西侧边缘、被熊怪匆忙遗弃的营地，以找回完好的雕刻图腾。"},{t="阴影与梦魇",b="解读找回的图腾揭示了一场悲惨的堕落。止松熊怪一直饱受反复出现的梦魇困扰，梦见某种即将毁灭他们的阴影正在逼近。久而久之，纯粹的恐惧逐渐转化为盲目的愤怒，扭曲了他们的心智，使他们将长久以来的精灵邻居视为他们所恐惧的那种阴影。塔琳德拉希望这些发现能揭示泰达希尔蔓延的不详征兆。"}},faq={{q="谁发布了Nature's Call任务？",a="塔琳德拉是一位在泰达希尔的幽影谷守护的树妖。由于担心当地止松熊怪突然表现出的敌意，她指引冒险者从他们废弃的营地中回收圣物，以调查他们疯狂的根源。",al={"谁发布了nature's call","塔琳德拉是谁","塔琳德拉位置"}},{q="为什么止松熊怪会变得充满敌意？",a="从止松图腾中回收的雕刻显示，熊怪开始遭受可怕的梦魇困扰，梦见一个威胁要毁灭他们的阴影。这种蔓延的恐惧逐渐扭曲成无法控制的偏执和狂怒，导致他们将古老的暗夜精灵盟友视为敌人。",al={"为什么止松熊怪发动攻击","为什么止松熊怪疯狂","止松熊怪发生了什么"}},{q="止松图腾在哪里？",a="较小的图腾可以在位于幽影谷西侧边缘的废弃止松熊怪营地中找到，不过在废墟中搜寻的小鬼和贪婪小鬼已经把其中一些散落到了周围的区域。",al={"止松图腾在哪里","寻找止松图腾","止松营地位置"}},{q="为什么玩家无法收集营地里较大的图腾？",a="塔琳德拉特别建议不要尝试回收营地中发现的较大图腾。作为一名树妖，她表示自己完全不知道该如何处理那种笨重的雕刻，更倾向于使用较小、便于携带的雕刻图腾。",al={"为什么忽略大型图腾","我可以拾取大型图腾吗","大型止松图腾"}},{q="谁是止松熊怪？",a="止松部族是泰达希尔原生的熊怪，曾与暗夜精灵作为和平的盟友共同生活。他们最近转变为具有攻击性的敌对势力，是由蔓延的梦魇引起的一种反常现象，而非源于古老的恶意。",al={"谁是止松熊怪","止松传说","止松熊怪是邪恶的吗"}},{q="图腾中提到的伟大阴影是什么？",a="雕刻中提到了一个困扰着熊怪梦境的未知“伟大阴影”。虽然这种黑暗影响的确切来源尚不清楚，但塔琳德拉希望解读他们的命运将有助于理清泰达希尔所受到的更广泛的腐蚀。",al={"止松阴影是什么","泰达希尔的阴影是什么","泰达希尔的梦魇"}}},fp="13,321,22.354.0,28.424.1,34.247.0,44.280.0,39.225.0,57.252.0,30.248.0,49.245.0"}
P.entries["quest:97979"] = {n="The Goddess Provides",s="“The Goddess Provides”是一项介绍Kaldorei的初始任务，核心在于领会Elune的赐福。该任务设定在“Long Vigil”结束后泰达希尔的枝桠间，教导年轻的暗夜精灵接受月神之母带来的月光指引与隐遁阴影。",h="“The Goddess Provides”是一项介绍Kaldorei的初始任务，核心在于领会Elune的赐福。该任务设定在“Long...",kw={"elune","goddess provides","海加尔山","kaldorei","long vigil","月神之母","影遁","泰达希尔"},ang={["class:Priest"]="Kaldorei中的牧师群体致力于侍奉“Mother Moon”，直接引导Elune的优雅作为指引的光辉与神圣的庇护。",["faction:Alliance"]="在海加尔山的战斗之后，暗夜精灵结束了长期的孤立并加入了联盟，将他们神圣的月亮力量贡献于共同防御。",["race:NightElf"]="作为群星之子，Kaldorei继承了Elune的直接赐福，利用月光揭示未见的道路，并利用隐蔽能力融入阴影之中。"},sec={{t="结束的守望",b="在大分裂后的数千年里，Kaldorei维持着孤独的“Long Vigil”，守护着卡利姆多，并保卫着海加尔山的神圣山巅。第三次战争的浩劫以及对世界之树的关键防御迫使这段古老的与世隔绝走向终结。如今，移居至泰达希尔庇护之下的枝桠间，暗夜精灵们面对着一个陌生的世界，通过与远方海洋彼岸的盟友结盟，踏上了艾泽拉斯更广阔的舞台。"},{t="月神之母的祝福",b="即便是在结盟对象更迭与居所变迁之时，Kaldorei认同感的根基依然植根于对“Mother Moon”Elune的崇拜。暗夜精灵从幼年起就被教导呼唤她的双重形态：指引战斗打击与澄清目标的辉光，以及掩盖自身于敌方视线之外的阴影。呼唤这些与生俱来的天赋，既是精神上的交流，也是为大树之外的危险所做的实践准备。"}},faq={{q="什么是“The Goddess Provides”？",a="“The Goddess Provides”是为栖居在泰达希尔枝桠间的年轻暗夜精灵准备的入门仪式。它指导Kaldorei识别并展示月亮女神Elune赋予他们的天赋赐福。",al={"什么是the goddess provides","the goddess provides任务"}},{q="任务中提到的女神是谁？",a="这位女神是Elune，也被Kaldorei尊称为“Mother Moon”。她是暗夜精灵文化与精神生活的核心神祇，被认为赐予其子民保护、澄明与潜行的月之祝福。",al={"女神是谁","谁是月神之母","暗夜精灵女神"}},{q="Elune赋予了Kaldorei什么天赋？",a="Elune赋予的优雅可以照亮战士的打击以确保命中，同时也赋予了他们融入周围阴影的能力，正如月亮在日食期间遮蔽太阳一般。",al={"elune给予什么天赋","elune种族技能","elune的力量"}},{q="什么是“Long Vigil”？",a="“Long Vigil”是暗夜精灵为守护卡利姆多而维持的数千年的警戒与孤立状态。在对燃烧军团的海加尔山关键防御战之后，这段时期宣告结束，促使Kaldorei最终开放了国界。",al={"什么是long vigil","为什么long vigil结束"}},{q="为什么暗夜精灵加入了联盟？",a="海加尔山的防御战终结了他们孤独的隐居生活，Kaldorei选择与海那边的凡人种族建立联系，加入了大联盟以求共同生存与结伴。",al={"为什么暗夜精灵加入联盟","kaldorei联盟"}},{q="这项指导在何处进行？",a="泰达希尔是位于卡利姆多北海岸外巨大的世界之树。第三次战争后，其高耸且受庇护的枝桠成为了暗夜精灵人民新的家园与圣所。",al={"泰达希尔在哪里","什么是泰达希尔"}}},fp="20,274,17.476.0,24.466.0,29.226.0,44.222.0,46.194.0,24.252.0,45.213.0,39.196.0"}
P.entries["quest:97985"] = {n="Thundering Hearts",s="一名研究憎恶制造奥秘的学者需要一颗巨大的心脏，目标是千针石林的雷霆蜥蜴Stormheart。",h="一名研究憎恶制造奥秘的学者需要一颗巨大的心脏，目标是千针石林的雷霆蜥蜴Stormheart。",kw={"憎恶","制造","心脏","stormheart","千针石林","雷霆蜥蜴","雷霆之心"},sec={{t="一颗巨大的心脏",b="这名学者研究了制造憎恶的笔记，认为此项工作需要一颗巨大的心脏。据说雷霆蜥蜴Stormheart在千针石林的峡谷边缘巡游，体型似乎正合适。学者提醒你，Stormheart可不好对付。"},{t="心脏",b="Stormheart的心脏仍带有电流脉动。学者说它看起来符合指定的尺寸，会被加入憎恶体内。"}},faq={{q="谁想要Stormheart的心脏？",a="一名研究憎恶制造奥秘的学者想要Stormheart的心脏，用来制造憎恶。",al={"谁需要这颗心脏","憎恶研究者","是谁派我来的"}},{q="Stormheart在哪里？",a="Stormheart在千针石林的峡谷边缘巡游。",al={"stormheart的位置","雷霆蜥蜴在哪里","stormheart在哪"}},{q="Stormheart是什么？",a="Stormheart是一只体型惊人的雷霆蜥蜴。",al={"stormheart是什么生物","大蜥蜴","雷霆蜥蜴"}},{q="为什么需要心脏？",a="学者的笔记指出，制造憎恶需要一颗巨大的心脏。",al={"为什么需要心脏","憎恶心脏","这颗心脏有什么用"}},{q="学者对这颗心脏了解多少？",a="学者说，这颗心脏仍有电流脉动，而且看起来符合笔记中指定的尺寸。",al={"心脏详情","带电的心脏","它有什么特别之处"}}},fp="17,98,13.218.0,9.163.1,31.89.0,20.61.0,19.50.0,22.75.0,46.115.0"}
P.entries["quest:98013"] = {n="Swelling Forces",s="Swelling Forces是一个任务，Arbal指挥古树之林的冒险者去猎杀盘踞在东北方废墟中日益壮大的Stormscale娜迦。这些受到诅咒的前上层精灵与阴险的Twilight's Hammer邪教结盟，威胁着林地。向他们拿起武器对于保护古老森林免遭进一步的破坏至关重要。",h="Swelling Forces是一个任务，Arbal指挥古树之林的冒险者去猎杀盘踞在东北方废墟中日益壮大的Stormscale娜迦。这些受到诅咒的前上层精灵与阴险的Twilight's...",kw={"arbal","古树之林","上层精灵","侍从","娜迦","女巫","stormscale","swelling forces","twilight's hammer"},ang={["faction:Alliance"]="保卫黑海岸和古树之林周围神圣森林的联盟军队，必须应对娜迦和Twilight's Hammer之间协同作战的前线。",["race:NightElf"]="在这些废墟中游荡的娜迦曾经是暗夜精灵的上层精灵同族。看到他们与黑暗邪教徒一起回来亵渎和掠夺古老的森林，这真是一种痛苦的背叛。"},sec={{t="沉没之城的毒蛇",b="在古树之林，Arbal带着深切的担忧注视着东北方的废墟。受到诅咒的上层精灵，已经变成了Stormscale部族的蛇形娜迦，占据了他们曾经辉煌文明的残骸。沉没的石块不再安静地承载着回忆，而是回荡着侵略大军滑行的脚步声。Arbal委派保卫者前往废墟，在他们的力量扩散到更广阔的森林之前，削减其不断增长的数量。"},{t="邪恶的联盟",b="Stormscale娜迦的出现不仅仅是简单的领土侵略。Arbal透露，这些扭曲的前上层精灵正在协助虚无主义的Twilight's Hammer邪教。对于这些生物来说，亵渎和掠夺曾经庇护过它们的森林——特别是在服务于邪恶、阴暗的主人时——是不可原谅的罪行。遏制他们的数量迫在眉睫，以防止该邪教及其蛇形盟友进一步加强对这片土地的控制。"}},faq={{q="谁发布了Swelling Forces任务？",a="Swelling Forces由Arbal发布，他指引古树之林的冒险者去对抗聚集在东北方废墟中的敌对娜迦势力。",al={"谁发布swelling forces","arbal任务发布者","arbal在哪里"}},{q="为什么在这个任务中要针对娜迦？",a="Stormscale娜迦已经占领了附近的废墟，并威胁着周围的林地。更令人担忧的是，他们似乎在协助Twilight's Hammer邪教，给他们曾经称之为家园的土地带来了暴力。",al={"为什么要杀娜迦","废墟里的娜迦","stormscale的威胁"}},{q="娜迦与这些废墟之间有什么联系？",a="正如Arbal所指出的，娜迦曾经是古代卡利姆多的上层精灵，遭受了可怕的诅咒。尽管他们曾经居住在这些宏伟的城市中，但现在他们已化身为扭曲的毒蛇，寻求征服和破坏。",al={"什么是stormscale娜迦","娜迦的起源","被诅咒的上层精灵"}},{q="娜迦与Twilight's Hammer有什么联系？",a="任务揭示了娜迦正在协助阴暗的Twilight's Hammer邪教。虽然他们的具体安排仍未可知，但Arbal警告说，他们的结盟只会给古老的森林带来进一步的毁灭和苦难。",al={"twilight's hammer娜迦","为什么娜迦与邪教合作"}},{q="Stormscale的势力聚集在哪里？",a="废墟位于古树之林的东北方。冒险者被派往那里，通过猎杀他们的侍从、女巫和战士来遏制日益壮大的Stormscale军队。",al={"废墟在哪里","去哪里找stormscale"}},{q="为什么Arbal认为娜迦的行为是不可原谅的？",a="对Arbal来说，听命于黑暗主人而掠夺自己的古老家园是绝对不可原谅的。上层精灵曾经拥有的任何高贵品质，都已经随着他们堕落入残酷和黑暗的联盟中而彻底消失了。",al={"为什么arbal痛恨娜迦","arbal眼中的不可原谅"}}},fp="15,191,27.366.0,18.316.1,36.132.0,46.182.0,54.180.0,55.141.0,38.133.0,56.181.0"}
P.entries["quest:98021"] = {n="Journey to Sentinel Hill",s="“前往哨兵岭”指引联盟的冒险者前往西部荒野动荡的农田地带，向哨兵岭的哨所报到。当地指挥官数月来一直向暴风城请求皇家增援，却始终杳无音讯，这让他们感到十分沮丧。因此，他们已经准备好让任何愿意帮忙的旅行者直接投入工作。",h="“前往哨兵岭”指引联盟的冒险者前往西部荒野动荡的农田地带，向哨兵岭的哨所报到。当地指挥官数月来一直向暴风城请求皇家增援，却始终杳无音讯，这让他们感到十分沮丧。因此，他们已经准备好让任何愿意帮忙的旅行者直接投入工作。",kw={"journey to sentinel hill","人民民兵","哨兵岭","瘦弱的精灵","暴风城","西部荒野"},ang={["faction:Alliance"]="西部荒野是一片急需支援的联盟领土，然而暴风城却将当地指挥官的增援请求置之不理，只能依靠任何出现的志愿者。",["race:NightElf"]="哨兵岭的边境指挥官可能会抱怨派来的是个“瘦弱的精灵”而不是久经沙场的暴风城步兵，但哨兵岭确实需要一切它能得到的援助。"},sec={{t="抵达边境",b="“前往哨兵岭”标志着冒险者踏入了饱受战火蹂躏的西部荒野地区。哨兵岭哨所是周围农田的主要防御堡垒，但其驻军却长期人手不足，且遭到皇家法庭的忽视。当旅行者前来提供援助时，当地指挥官根本无暇去质疑他们的身份，而是急切地想让任何愿意出力的人投入工作。"},{t="向暴风城恳求",b="数月以来，哨兵岭的领导层一直向暴风城请求军事增援，以确保该地区免受日益严重的威胁。王国的漠视迫使当地指挥官只能接受任何上门求助的人——即便这意味着要用一句冷嘲热讽来迎接刚抵达的冒险者，抱怨自己想要的是一支军队，结果却只等来了一个瘦弱的精灵。在西部荒野，乞丐是没资格挑肥拣瘦的。"}},faq={{q="什么是“前往哨兵岭”？",a="“前往哨兵岭”是一项联盟任务，指引冒险者前往西部荒野的边境领土。它向新人介绍了驻扎在哨兵岭的当地守卫，他们一直在向暴风城请求援助，却始终未能获得足够的正式增援。",al={"什么是前往哨兵岭","前往哨兵岭任务","哨兵岭任务"}},{q="为什么哨兵岭要寻求帮助？",a="驻扎在哨兵岭的军事领导层数月来一直恳求暴风城派遣增援部队，以处理困扰西部荒野的种种麻烦。当地领导层被迫依靠偶尔出现的个别冒险者，而不是正规部队。",al={"谁在向暴风城乞求援助","哨兵岭驻军","为什么哨兵岭需要帮助"}},{q="为什么任务文本提到了一个瘦弱的精灵？",a="在完成旅程后，指挥官会提到他们数月来一直恳求暴风城的援助，结果却只被派来了一个瘦弱的精灵。指挥官一边抱怨着乞丐没资格挑肥拣瘦，一边迅速决定让新到的冒险者立即投入工作。",al={"瘦弱的精灵语录","为什么是瘦弱的精灵","哨兵岭对精灵的评论"}},{q="为什么暴风城没有派遣合适的增援部队？",a="暴风城的皇家政府目前正分身乏术，焦头烂额，导致西部荒野等外围领土在很大程度上被忽视了。哨兵岭在几个月内多次发出求援呼吁，但官方的皇家支持始终未能落实，迫使当地指挥官只能依靠志愿者。",al={"为什么暴风城不帮助西部荒野","暴风城忽视西部荒野","暴风城对西部荒野的援助"}},{q="什么是哨兵岭？",a="哨兵岭是西部荒野人民民兵的核心军事哨所和堡垒。它是抵御肆虐该地区农田的无法无天之徒、迪菲亚盗贼和豺狼人的第一道防线。",al={"哨兵岭在哪里","什么是哨兵岭","哨兵岭位置"}},{q="到达哨兵岭后会发生什么？",a="一旦你在哨兵岭报到，当地守卫会毫不拖延地让你投入工作。冒险者的任务是帮助处理西部荒野平原和农田各处的诸多威胁。",al={"在西部荒野做什么","西部荒野后续任务","到达西部荒野后发生什么"}}},fp="24,224,23.270.0,18.284.0,33.163.0,37.169.0,45.167.0,48.129.0,22.155.0,42.151.0"}
P.entries["quest:98024"] = {n="Journey to the Crossroads",s="Journey to the Crossroads引导着刚从元素位面抵达的旅行者前往贫瘠之地那崎岖的草原。冒险者们被指派去向十字路口的索克报到，以协助部落军队应对严酷的前线。这对了解部落在卡利姆多所面临的致命威胁而言是一次必不可少的引导。",h="Journey to the...",kw={"贫瘠之地","十字路口","元素位面","部落","journey to the crossroads","索克"},ang={["faction:Horde"]="这次旅程引导刚抵达的勇士们为部落拿起武器，在卡利姆多崎岖的前线提供了一次烈火般的试炼。",["race:Skyborne"]="既然已从元素位面抵达艾泽拉斯，旅行者们被敦促不要小看凡世的冲突，并要在为部落的服务中证明自己的勇气。"},sec={{t="前线的召唤",b="在从元素位面旅途归来并抵达艾泽拉斯的旅行者们面对的是一个清醒的现实：凡人的冲突相比之下似乎微不足道，但部落所面临的危险却是实实在在的。在前线服役为那些寻求成长并在此过程中协助凡世领域的人们提供了一个至关重要的试炼场。"},{t="卡利姆多的十字路口",b="为了开始服役，冒险者们会被指引向西南方，进入贫瘠之地那片广袤且被太阳炙烤的平原。那里坐落着十字路口，这是一个至关重要的枢纽，也是一个关键的部落哨站，其引以为傲的守卫者们时刻都在应对着周遭的危险。直接向索克报到能让新人们融入到定居点的防御体系中。"}},faq={{q="索克是谁？",a="索克是驻扎在贫瘠之地十字路口的一位重要的部落权威人物。他负责监管当地的防御工作，并指挥冒险者们去协助解决威胁着定居点及其周边领土的诸多危险。",al={"索克是谁","十字路口领袖","索克在哪里"}},{q="十字路口是什么？",a="十字路口是坐落于贫瘠之地主要道路交汇处的一个中心部落哨站和贸易枢纽。这里被充满敌意的野生生物、半人马部落和野猪人劫掠者所包围，守卫者们需要不断的援助来确保重要补给线的安全。",al={"十字路口是什么","贫瘠之地十字路口","为什么要去十字路口"}},{q="贫瘠之地位于哪里？",a="贫瘠之地是一片广袤且干旱的草原，位于卡利姆多中部，杜隆塔尔的西南方。它是一片连接整个大陆上部落领土的重要广袤区域。",al={"贫瘠之地在哪里","贫瘠之地位置"}},{q="为什么任务提到了元素位面？",a="任务中提到旅行者最近刚从元素位面抵达。虽然超凡界的冲突看起来似乎宏大，但威胁凡世领域和部落的危险却是迫在眉睫且严峻的。",al={"元素位面抵达","为什么提到元素位面","从元素位面旅程"}},{q="Journey to the Crossroads的任务目的是什么？",a="该任务旨在指引新人们直接向十字路口的索克报到，让他们融入到部落的前线作战中，并通过光荣的服役提供了一条变得强大的途径。",al={"十字路口任务目的","为什么派往十字路口"}},{q="十字路口的居民面临着什么样的危险？",a="贫瘠之地持续面临着来自原生掠食者、游荡的半人马、野猪人战帮以及联盟入侵的侵略，这使得每一个哨站都成为了需要有能力的守卫者驻守的争夺据点。",al={"贫瘠之地有什么危险","贫瘠之地威胁"}}},fp="25,173,22.236.0,26.230.0,13.182.0,23.225.0,30.131.0,47.173.0,49.147.0,52.182.0"}
P.entries["quest:98025"] = {n="WANTED: Jai'vhanel",s="WANTED: Jai'vhanel 是由黑海岸奥伯丁村议会发布的联盟赏金任务。公告要求除掉名为“剑羽”的疯狂黑猫头鹰 Jai'vhanel，她开始袭击奥伯丁附近道路上的旅客。冒险者必须在亚米萨兰遗迹附近猎杀这只生物，并将她死亡的证明交给哨兵戈琳达·纳希恩。",h="WANTED: Jai'vhanel 是由黑海岸奥伯丁村议会发布的联盟赏金任务。公告要求除掉名为“剑羽”的疯狂黑猫头鹰...",kw={"亚米萨兰","奥伯丁","黑猫头鹰","黑海岸","戈琳达·纳希恩","jai'vhanel","剑羽","wanted: jai'vhanel"},ang={["class:Druid"]="暗夜精灵德鲁伊密切关注着黑海岸的野生动物，像 Jai'vhanel 这样高贵的鸟类突然陷入疯狂并产生攻击性，这是一种令人担忧的生态干扰。",["class:Hunter"]="这只被称为“剑羽”的凶猛漆黑猛禽，是黑海岸山区附近极具攻击性的追踪者，她的狩猎习惯变得极其不稳定且具有致命危险。",["faction:Alliance"]="奥伯丁村议会依靠联盟冒险者和暗夜精灵哨兵来保护黑海岸重要的沿海公路免受疯狂掠食者的侵害。"},sec={{t="路上的威胁",b="奥伯丁村议会发布的一则公告向黑海岸沿海道路的旅客发出警告，称存在严重的威胁。一只著名的当地猫头鹰 Jai'vhanel（绰号“剑羽”）突然陷入了疯狂。她不再待在茂密的荒野中，而是开始袭击奥伯丁附近的旅客和信使，将一只普通的林地掠食者变成了该定居点的严重危险。"},{t="议会的赏金",b="为了确保道路安全，议会悬赏捉拿 Jai'vhanel。猎手们被指示追踪这只黑羽猛禽到亚米萨兰遗迹以北、山脚下的狩猎场。猎手必须带回她身上的一根标志性黑羽，交给奥伯丁的哨兵戈琳达·纳希恩以核实猎杀成果并领取奖励。"}},faq={{q="Jai'vhanel 是谁？",a="Jai'vhanel，也被称为“剑羽”，是一只以浑身漆黑羽毛而闻名的巨型猫头鹰。她本是黑海岸森林中常见的野生生物，但现在已经陷入疯狂，并开始对旅客表现出强烈的攻击性。",al={"jaivhanel 是谁","jaivhanel 是什么","剑羽是谁"}},{q="为什么要悬赏 Jai'vhanel？",a="奥伯丁村议会之所以对 Jai'vhanel 发出正式悬赏，是因为她已经发疯并开始攻击奥伯丁附近主要道路上的旅客，对当地交通构成了严重威胁。",al={"为什么要猎杀 jaivhanel","为什么要悬赏 jaivhanel","为什么这只猫头鹰会发起攻击"}},{q="在哪里可以找到 Jai'vhanel？",a="人们最后一次见到 Jai'vhanel 是在黑海岸的古代亚米萨兰遗迹以北，她在东部山脉的山脚下徘徊。",al={"jaivhanel 在哪里","jaivhanel 的位置","在哪里找到剑羽"}},{q="是谁悬赏了 Jai'vhanel？",a="这份赏金是由奥伯丁村议会发布的，他们负责监督这个沿海定居点及周边道路的民事安全与当地福利。",al={"谁发布了悬赏","谁想要 jaivhanel 死"}},{q="谁负责领取 Jai'vhanel 的赏金？",a="赏金猎人必须出示 Jai'vhanel 的一根黑羽作为她死亡的证明，并交给驻守在奥伯丁镇的哨兵戈琳达·纳希恩。",al={"谁负责收取死亡证明","在哪里上交 jaivhanel 的羽毛","戈琳达·纳希恩悬赏"}},{q="需要什么证明才能领取赏金？",a="任何要求领取议会赏金的人都必须找回并出示 Jai'vhanel 身上的一根标志性黑羽，以证明这只疯狂的鸟已经被杀。",al={"jaivhanel 的死亡证明是什么","什么物品证明 jaivhanel 已死"}}},fp="18,379,20.436.0,20.388.0,18.249.0,36.208.0,30.132.0,36.150.0,39.154.0,41.148.0"}
P.entries["quest:98042"] = {n="It's All Fun and Games Until...",s="It's All Fun and Games Until... 是一个与提交给桑德里斯的一项令人深感不安的发现有关的任务。在辨认出这件古老邪恶之物那无法误认的标记后，桑德里斯安排将该圣物立即送往达纳苏斯进行深入研究。",h="It's All Fun and Games Until...",kw={"古老邪恶","ande'thoras-ethil","达纳苏斯","古老邪恶的标记","暗夜精灵","桑德里斯"},ang={["faction:Alliance"]="联盟冒险者将令人不安的发现带给暗夜精灵当局，有助于确保危险的圣物得到达纳苏斯学者的检查和控制。",["race:NightElf"]="这项调查直接触及了暗夜精灵对古老腐化的警惕，促使达纳苏斯立即介入。"},sec={{t="令人不安的报告",b="一项令人不安的发现促使冒险者前往寻找桑德里斯，就此事寻求建议。在听取了冒险者的报告并检查了所带来的东西后，桑德里斯陷入了沉思，他意识到了一些无法等闲视之的黑暗征兆。"},{t="古老邪恶的标记",b="在仔细检查此事后，桑德里斯辨认出该发现物上附着着无法误认的古老邪恶标记。意识到危险远远超出了当地发生的意外，桑德里斯决定立即将该圣物送往达纳苏斯，托付给首都的学者和祭司进行严格的研究和封印。"}},faq={{q="谁参与完成了此任务？",a="该任务是提交给桑德里斯并由他结束的，他会听取不安的冒险者的汇报，并在准备将其运走之前检查所提交的物品或证据。",al={"谁发布了its all fun and games until","桑德里斯任务","谁回收its all fun and games until"}},{q="为什么要把这个物体送到达纳苏斯？",a="桑德里斯确认该神器或发现物带有古老邪恶的标记。桑德里斯表示他会立刻将其送往达纳苏斯进行进一步研究，除此之外他没有透露更多信息。",al={"为什么送到达纳苏斯","达纳苏斯研究","达纳苏斯的古老邪恶"}},{q="桑德里斯所指的古老邪恶是什么？",a="桑德里斯确认该发现物带有古老邪恶的标记，尽管关于其确切起源的具体细节在暗夜精灵首都进行更深入的研究之前仍处于保密状态。",al={"古老邪恶是什么","古老邪恶标记的含义"}},{q="'Ande'thoras-ethil' 是什么意思？",a="'Ande'thoras-ethil' 是桑德里斯在你谈话结束时所说的一句达纳苏斯语，在他说了该发现物将被带到达纳苏斯之后。",al={"ande'thoras-ethil的含义","andethoras ethil暗夜精灵短语","达纳苏斯语告别桑德里斯"}},{q="任务完成后会发生什么？",a="在揭露了那古老的腐化后，桑德里斯准备将这件令人不安的圣物立即运往达纳苏斯，以便首都的学者们可以对其进行检查。",al={"its all fun and games until完成之后会发生什么","fun and games之后的下一个任务","to darnassus后续"}},{q="哪个阵营负责这项调查？",a="此事由达纳苏斯的领导层和像桑德里斯这样的暗夜精灵人物负责处理，重点在于提交给暗夜精灵当局的威胁。",al={"its all fun and games是联盟专属吗","谁能执行its all fun and games until"}}},fp="31,128,18.198.0,24.226.1,41.123.0,42.108.0,48.130.0,35.145.0,40.146.0,41.129.0"}
P.entries["quest:98046"] = {n="Crown of the Earth",s="Crown of the Earth 是达纳苏斯的一个任务，大德鲁伊范达尔·鹿盔在一次涉及一瓶水的咒语施法失败后，放弃了该仪式并由此开启了此任务。这位沮丧的大德鲁伊打发走了冒险者，命令其将 Drained Vessel 送往 Temple of the Moon 交给女祭司拉里亚进行处理。然而，女祭司在检查瓶子时发现里面还有些许残留的水，这不禁让人怀疑仪式失败的真正原因。",h="Crown of the Earth 是达纳苏斯的一个任务，大德鲁伊范达尔·鹿盔在一次涉及一瓶水的咒语施法失败后，放弃了该仪式并由此开启了此任务。这位沮丧的大德鲁伊打发走了冒险者，命令其将 Drained Vessel...",kw={"塞纳里奥议会","crown of the earth","达纳苏斯","排空的器皿","艾露恩","范达尔·鹿盔","拉里亚","玛法里奥","temple of the moon"},ang={["class:Druid"]="范达尔明确地将冒险者称为德鲁伊同僚，在将其赶走之前，他对仪式失败表现出了生硬的不耐烦。",["faction:Alliance"]="该任务展示了在玛法里奥·怒风缺席的情况下，卡利姆多主要的联盟主城达纳苏斯内部平静的领导层紧张局势。",["race:NightElf"]="这项差事揭示了达纳苏斯内部日常的压力，将范达尔·鹿盔尖刻的权威与 Temple of the Moon 中 The Sisterhood of Elune 的耐心奉献形成了鲜明对比。"},sec={{t="范达尔的沮丧",b="在达纳苏斯，大德鲁伊范达尔·鹿盔承担着玛法里奥·怒风缺席期间引导暗夜精灵的重任。在寻找答案的过程中，范达尔试图利用瓶中盛放的圣水进行咒语仪式。当仪式似乎毫无结果时，大德鲁伊的脾气爆发了。他认定这些水毫无用处，便言语尖刻地打发走冒险者，并指示他们将 Drained Vessel 送往南方的 Temple of the Moon，让那里的女祭司处理掉。"},{t="残留的水滴",b="在抵达 Temple of the Moon 后，女祭司拉里亚表现得非常温和，她让冒险者不必介意范达尔严厉的态度，毕竟他肩负着沉重的担子。然而当她检查瓶子时，她发现了大德鲁伊在匆忙中忽略的一件事：瓶中仍残留着几滴水。这一残留物引发了一种明显的可能性：范达尔的仪式并非因魔法本身有缺陷而失败，而是因为容器未被彻底清空。"}},faq={{q="谁发布了 Crown of the Earth 任务？",a="该任务由达纳苏斯的大德鲁伊范达尔·鹿盔发布。范达尔目前在玛法里奥·怒风缺席期间主持塞纳里奥议会，在一次涉及圣水的咒语未能得出他想要的答案后，他极其烦躁地指派了这项任务。",al={"谁开启了 crown of the earth","crown of the earth 任务发布者","范达尔任务"}},{q="你需要将 Drained Vessel 送到哪里？",a="你需要将 Drained Vessel 送交至达纳苏斯南部 Temple of the Moon 的女祭司拉里亚。范达尔命令你将其移交以便让艾露恩的女祭司们处理，他认为这个用过的容器已毫无用处。",al={"去哪里上交 drained vessel","drained vessel 上交","拉里亚在哪里"}},{q="为什么范达尔·鹿盔如此沮丧？",a="大德鲁伊范达尔·鹿盔在玛法里奥·怒风离职期间领导暗夜精灵和塞纳里奥议会，承受着巨大的压力。当他的魔法咒语毫无所获时，他的烦躁和傲慢使他大发雷霆，并迅速打发走了冒险者，而不是深入探究失败的原因。",al={"为什么范达尔生气","范达尔的态度","为什么范达尔不耐烦"}},{q="为什么范达尔的咒语失败了？",a="范达尔·鹿盔认为水本身缺乏任何有用的力量，但女祭司拉里亚在接过瓶子时注意到一个关键细节。瓶内仍有几滴水残留，这表明咒语之所以失败，可能仅仅是因为在仪式过程中瓶子未被完全清空。",al={"为什么咒语会失败","范达尔的仪式成功了吗","失败的咒语"}},{q="在这个任务中玛法里奥在哪里？",a="玛法里奥·怒风目前不在达纳苏斯，这使得塞纳里奥议会的领导权和对暗夜精灵的指导责任落在了大德鲁伊范达尔·鹿盔身上。这种缺席给范达尔带来了沉重的负担，这也加剧了他的易怒和对挫折的不耐烦。",al={"玛法里奥在哪里","为什么玛法里奥缺席","玛法里奥的状态"}},{q="女祭司拉里亚是谁？",a="女祭司拉里亚是一位驻扎在达纳苏斯 Temple of the Moon 的艾露恩信徒。她从冒险者手中接过了瓶子，在对范达尔沉重的职责表示同情的同时，敏锐地察觉到瓶中仍有残留的水。",al={"谁是拉里亚","女祭司拉里亚背景故事","拉里亚 temple of the moon"}}},fp="18,166,21.381.0,19.245.1,39.223.0,37.198.0,38.263.0,35.189.0,37.215.0,24.170.0"}
P.entries["quest:98065"] = {n="Crown of the Earth",s="Crown of the Earth 是一个达纳苏斯任务，冒险者需要将净化的 Moonwell Remnants 送交给高阶女祭司泰兰德·语风。该任务发生在 Temple of the Moon 内部，揭示了艾露恩之水的神圣意义，以及泰兰德与大德鲁伊范达尔·鹿盔之间日益紧张的政治关系。",h="Crown of the Earth 是一个达纳苏斯任务，冒险者需要将净化的 Moonwell Remnants 送交给高阶女祭司泰兰德·语风。该任务发生在 Temple of the Moon...",kw={"crown of the earth","达纳苏斯","艾露恩","范达尔·鹿盔","玛法里奥","月亮井残骸","temple of the moon","泰兰德·语风"},ang={["class:Druid"]="泰兰德对于大德鲁伊范达尔·鹿盔的尖锐言辞，凸显了在玛法里奥缺席的情况下，塞纳里奥议会内部日益增长的摩擦。",["class:Priest"]="服务于高阶女祭司泰兰德·语风，巩固了艾露恩的教士在引导和管理暗夜精灵社会中所扮演的重要角色。",["faction:Alliance"]="获得觐见达纳苏斯领袖的机会，可以让人一窥联盟主要首府之一所面临的内部政治压力。",["race:NightElf"]="直接运送神圣的月亮井水，凸显了卡多雷双重领导体制的现状，即夹在泰兰德的祭司体系与范达尔的德鲁伊体系之间。"},sec={{t="觐见高阶女祭司",b="在收集到神圣的 Moonwell Remnants 后，冒险者需要将这些受祝福的圣水转移到一个仪式容器中，并直接交给泰兰德·语风。艾露恩的高阶女祭司居住在达纳苏斯的 Temple of the Moon 高处，守护着这座城市，并为每一位进入其中的人提供女神的光芒。将这神圣之水交由她保管，被视为一种荣耀以及对艾露恩的虔诚表现。"},{t="领导层之间的紧张关系",b="在收到圣水残骸后，泰兰德对冒险者拯救这受祝福之水的行为表示了深深的感激，但她的思绪很快便转回了笼罩着达纳苏斯的政治紧张局势。在玛法里奥·怒风缺席期间，大德鲁伊范达尔·鹿盔接管了德鲁伊事务，但泰兰德明确表示，统治卡多雷是她个人的职责。尽管她敦促人们尊重鹿盔的职位，但这次交流揭示了 The Sisterhood of Elune 与塞纳里奥议会之间尖锐的摩擦。"}},faq={{q="什么是 Crown of the Earth？",a="Crown of the Earth 是达纳苏斯的一个任务，冒险者需要将一容器的 Moonwell Remnants 带给 Temple of the Moon 内的高阶女祭司泰兰德·语风。这标志着与暗夜精灵最高领袖直接交流的一个时刻。",al={"什么是 crown of the earth","crown of the earth 任务","任务 crown of the earth"}},{q="泰兰德·语风是谁？",a="泰兰德·语风是艾露恩的高阶女祭司，也是暗夜精灵的政治领袖。她在 Temple of the Moon 的上层俯瞰着达纳苏斯，肩负着在动荡时期引导她的人民这一重担。",al={"泰兰德·语风是谁","泰兰德在哪里","高阶女祭司泰兰德"}},{q="为什么要将 Moonwell Remnants 带给泰兰德？",a="Moonwell Remnants 是受艾露恩祝福的神圣之水。鉴于其神圣属性，必须将其转移至仪式容器中并带给泰兰德，以便她能代表女神接收并守护这些圣水。",al={"为什么要带 moonwell remnants 给泰兰德","什么是 moonwell remnants","达纳苏斯神圣之水"}},{q="泰兰德和范达尔·鹿盔之间有什么争端？",a="在玛法里奥·怒风缺席期间，大德鲁伊范达尔·鹿盔领导着德鲁伊，但泰兰德坚定地主张，管理达纳苏斯和领导卡多雷仍然是她自己的责任，她拒绝让德鲁伊的权威盖过艾露恩的祭司。",al={"泰兰德与范达尔的紧张关系","为什么泰兰德不喜欢鹿盔","范达尔对战泰兰德"}},{q="这个任务期间玛法里奥在哪里？",a="玛法里奥·怒风目前不在达纳苏斯，导致德鲁伊之间出现了领导空缺，大德鲁伊范达尔·鹿盔填补了这一空缺，这加剧了与泰兰德之间的政治紧张关系。",al={"玛法里奥在哪里","玛法里奥发生了什么","玛法里奥缺席"}},{q="Temple of the Moon 在哪里？",a="Temple of the Moon 位于达纳苏斯的中心。它是 The Sisterhood of Elune 的主要圣殿，泰兰德在主圣殿大厅正上方的上层接见来访者。",al={"temple of the moon 位置","temple of the moon 在哪里","在哪里可以找到泰兰德"}}},fp="18,247,32.385.0,22.423.1,27.198.0,27.228.0,49.181.0,57.244.0,37.193.0,32.185.0"}
P.entries["quest:98067"] = {n="Eyes of the Sentinels",s="“Eyes of the Sentinels”是一个达纳苏斯的任务，玩家需要协助哨兵达莉亚·阳刃在暗夜精灵主城的关键哨位部署魔法侦察猫头鹰。面对泰达希尔日益增长的不安局势，这种空中监视不仅加强了城市的防御，还让哨兵们有时间向艾露恩祈祷。",h="“Eyes of the...",kw={"塞纳里奥要塞","工匠区","达莉亚·阳刃","达纳苏斯","艾露恩","eyes of the sentinels","羽月","哨兵猫头鹰","泰达希尔","temple of the moon"},ang={["class:Hunter"]="部署侦察猫头鹰体现了典型的暗夜精灵侦察手段，即训练有素的野兽和天上的禽类守望者是女猎手感知的自然延伸。",["class:Priest"]="哨兵们强调，仅靠武器无法保护卡多雷；定期的祈祷和来自艾露恩的精神馈赠对于她们的守护工作至关重要。",["faction:Alliance"]="确保达纳苏斯的安全可以保障暗夜精灵的首都，并巩固联盟在卡利姆多北部的核心据点。",["race:NightElf"]="哨兵部队是暗夜精灵传统的常备军和守护者，她们将武技与艾露恩的神圣祝福及注视结合在一起。"},sec={{t="奉献与防御",b="在月神殿的神圣庇护所中，哨兵达莉亚·阳刃负责守护达纳苏斯。遵照珊蒂斯·羽月将军的谕令——即每一位战士都必须兼顾武技与精神奉献——达莉亚安排在城市的各个关键枢纽部署警觉的哨兵猫头鹰。承担这些日常职责让哨兵们在月亮女神面前获得了宝贵的祈祷与反思时间，同时也确保了卡多雷首都始终处于严密的防守之下。"},{t="守望达纳苏斯",b="泰达希尔上空弥漫着不安的气息，促使哨兵们加倍警惕。为了防范渗透和动乱，哨兵猫头鹰被部署在关键路口：北部的塞纳里奥要塞下方深处、镇中心的繁华银行、工匠区内的旅店，以及主城门处。在当地城卫的协助下，这些禽类哨兵化身为沉默的守护者，监视着每一位行走在世界之树街道上的人。"}},faq={{q="什么是“Eyes of the Sentinels”？",a="“Eyes of the Sentinels”是达纳苏斯的一项任务，冒险者通过在城市各处的关键位置部署哨兵猫头鹰，协助哨兵达莉亚·阳刃维持警惕，以应对迫在眉睫的威胁。",al={"eyes of the sentinels任务","什么是eyes of the sentinels","eyes of the sentinels概述"}},{q="谁是哨兵达莉亚·阳刃？",a="哨兵达莉亚·阳刃是一位驻守在达纳苏斯月神殿的卡多雷守护者，她负责监督当地的防御常规，并确保警觉的猫头鹰能守卫城市的关键通路。",al={"谁是达莉亚·阳刃","达莉亚·阳刃背景故事","哨兵达莉亚·阳刃"}},{q="为什么要将哨兵猫头鹰安置在达纳苏斯各处？",a="哨兵猫头鹰是警觉的空中哨兵，也是艾露恩赐予的神圣侦察者，使哨兵们能够监视达纳苏斯各处的关键聚集点和交通咽喉。",al={"为什么要放置哨兵猫头鹰","哨兵猫头鹰的作用","哨兵猫头鹰的目的"}},{q="哨兵猫头鹰被放置在哪里？",a="哨兵猫头鹰被部署在北部塞纳里奥要塞下方深处的入口、镇中心的达纳苏斯银行、工匠区的旅店以及城市大门处。",al={"猫头鹰放置点","猫头鹰在哪里","eyes of the sentinels地点"}},{q="为什么哨兵们在泰达希尔处于高度戒备状态？",a="哨兵达莉亚·阳刃指出，泰达希尔世界之树的各个地方都有些不对劲，这促使哨兵们加强监视，时刻准备应对潜伏的危险。",al={"为什么哨兵感到担忧","泰达希尔出了什么问题","泰达希尔的不安"}},{q="羽月将军在哨兵的日常职责中扮演什么角色？",a="珊蒂斯·羽月将军统领着哨兵部队，并确保她的女猎手们能够平衡武职责任与对月亮女神艾露恩的日常奉献和祈祷。",al={"羽月将军的角色","珊蒂斯·羽月与哨兵","羽月的祈祷准则"}}},fp="21,324,20.489.0,20.490.0,30.201.0,31.195.0,52.188.0,35.188.0,50.197.0,71.175.0"}
P.entries["quest:98069"] = {n="Stolen Freewind Supplies",s="乱风岗的Jandia需要从 harpy 手中夺回被盗物资。若没有下一批补给，岗哨很快就会短缺。",h="乱风岗的Jandia需要从 harpy 手中夺回被盗物资。若没有下一批补给，岗哨很快就会短缺。",kw={"商队","洞穴","悬崖","乱风岗","harpy","jandia","乱风岗被盗补给","补给"},sec={{t="失踪的补给",b="harpy 袭击了最后一支原定向乱风岗运送补给的商队。Jandia说，岗哨眼下的物资还够用，但若没有更多补给，这些物资撑不了多久。它们的巢穴在此处以西，沿着悬崖底部，还在上方的一个洞穴里。"}},faq={{q="谁需要这些补给？",a="乱风岗的Jandia需要找回被盗的补给。",al={"谁需要补给","jandia补给","乱风岗补给"}},{q="是谁抢走了商队的补给？",a="harpy 袭击了最后一支原定向乱风岗运送补给的商队。",al={"是谁偷了补给","harpy补给","harpy偷了什么"}},{q="harpy 的巢穴在哪里？",a="harpy 在乱风岗以西筑巢，巢穴位于悬崖底部和顶部的一个洞穴内。",al={"harpy在哪里","harpy洞穴","西边的harpy"}},{q="Jandia为什么需要找回这些补给？",a="乱风岗眼下的补给还够用，但若没有下一批补给，很快就会短缺。",al={"为何找回补给","乱风岗补给短缺","补给为何重要"}},{q="Jandia让你找回什么？",a="Jandia让你为乱风岗找回八份被盗的补给。",al={"需要多少补给","被盗物品","要带回什么"}}},fp="24,147,20.239.0,23.60.0,32.69.0,24.87.0,31.95.0,36.67.0"}
P.entries["quest:98070"] = {n="Stop the Screeching",s="尖啸峡谷的 harpy 袭击了前往乱风岗的补给商队。它们的袭击威胁着这些旅程能否继续。",h="尖啸峡谷的 harpy 袭击了前往乱风岗的补给商队。它们的袭击威胁着这些旅程能否继续。",kw={"商队","乱风岗","harpy","roguefeather","尖啸峡谷","尖啸 harpy","制止尖啸","补给","风语者"},sec={{t="商队危在旦夕",b="一名供应商担心，如果 harpy 继续袭击，商队就会停止前往乱风岗。你受托消灭 Screeching Harpy、Screeching Roguefeather Harpy 和 Screeching Windcaller。敢于穿越峡谷的商队仍面临危险。"},{t="通知供应商",b="解决 harpy 后，供应商会通知为乱风岗提供货物的人。商队在旅途中将少面对一种威胁。"}},faq={{q="商队为何遭到袭击？",a="最近几支经过尖啸峡谷的补给商队都遭到了 harpy 袭击。",al={"袭击商队的 harpy","harpy 为何袭击","商队遇袭"}},{q="如果袭击继续，会有什么危险？",a="供应商担心，如果袭击持续下去，就不会有商队敢前往乱风岗。",al={"为何保护商队","乱风岗补给","商队停运"}},{q="涉及哪些 harpy？",a="提到的 harpy 有 Screeching Harpy、Screeching Roguefeather Harpy 和 Screeching Windcaller。",al={"harpy 种类","尖啸 harpy","roguefeather 风语者"}},{q="harpy 在哪里？",a="这些 harpy 生活在尖啸峡谷。",al={"harpy 位置","尖啸峡谷 harpy","尖啸峡谷在哪里"}}},fp="19,137,16.250.0,17.163.1,36.89.0,40.89.0,27.96.0,22.38.0"}
P.entries["quest:98071"] = {n="Brewer's Trade",s="我们与丹加洛克的酿酒同族达成了一项交易，他们和任何人一样怀念法洛克家族的葡萄园。一箱法洛克特酿会被运往位于希尔斯布莱德丘陵东南部的堡垒，作为回报，我们将带回一袋他们的自酿啤酒花。",h="我们与丹加洛克的酿酒同族达成了一项交易，他们和任何人一样怀念法洛克家族的葡萄园。一箱法洛克特酿会被运往位于希尔斯布莱德丘陵东南部的堡垒，作为回报，我们将带回一袋他们的自酿啤酒花。",kw={"酿酒同族","丹加洛克","法洛克","法洛克特酿","希尔斯布莱德","自酿啤酒花","啤酒花","葡萄酒"},sec={{t="往昔的味道",b="法洛克葡萄酒最棒的陈酿大多早已被饮尽，但仍有一些法洛克特酿存放在地窖中。丹加洛克的酿酒同族也很怀念法洛克家族的葡萄园，因此我们与他们达成了一项交易。"},{t="丹加洛克的交换",b="将那箱酒运往东南方的丹加洛克，放在他们堡垒底部聚集处的壁炉旁。作为回报，你将带回一袋他们的自酿啤酒花。"}},faq={{q="这次交换交易了什么物品？",a="一箱从地窖运出的法洛克特酿葡萄酒，用于交换一袋他们的自酿啤酒花。",al={"我送的是什么","酿酒师的交易物品","法洛克葡萄酒"}},{q="在丹加洛克，酒需要被送到哪里？",a="你需要把它留在堡垒底部，也就是他们聚集处的壁炉旁。",al={"壁炉在哪里","丹加洛克交付地点","把酒留在哪里"}},{q="丹加洛克位于何处？",a="丹加洛克位于希尔斯布莱德丘陵的东南部。",al={"丹加洛克位置","丹加洛克在哪里"}},{q="法洛克一家是谁？",a="法洛克家族经营的葡萄园令人怀念。他们最棒的陈酿大多早已被饮尽，不过地窖里还剩有一些。",al={"法洛克家族","法洛克葡萄园"}}},fp="14,171,19.196.0,25.173.0,38.125.0,44.103.0,27.55.0,23.166.0"}
P.entries["quest:98072"] = {n="Crocs of the Sky",s="詹姆斯询问你是否拿到了鳞片，随后称赞你的天赋。如果你有一天不再冒险，他愿意给你安排工作。",h="詹姆斯询问你是否拿到了鳞片，随后称赞你的天赋。如果你有一天不再冒险，他愿意给你安排工作。",kw={"冒险","crocs of the sky","詹姆斯","鳞片","工作"},sec={{t="詹姆斯的提议",b="詹姆斯称你天赋过人，并邀请你在暂停冒险后回来找他。他开玩笑说，那时你可能年纪更大了。"}},faq={{q="谁在询问鳞片？",a="詹姆斯询问你是否拿到了鳞片。",al={"谁想要鳞片","给詹姆斯的鳞片"}},{q="詹姆斯怎么看我？",a="詹姆斯称你天赋过人。",al={"詹姆斯喜欢我吗","詹姆斯的看法"}},{q="詹姆斯提出了什么？",a="詹姆斯愿意在你暂停冒险后给你安排工作。",al={"詹姆斯的工作","工作提议"}}},fp="16,111,13.131.0,31.39.0,28.38.0,22.59.0"}
P.entries["quest:98094"] = {n="Scout Support",s="高级执行官达萨利亚派你将最新命令送给塔伦米尔以南的死亡猎手 Masoj。此行将助被遗忘者夺取这片土地的控制权。",h="高级执行官达萨利亚派你将最新命令送给塔伦米尔以南的死亡猎手 Masoj。此行将助被遗忘者夺取这片土地的控制权。",kw={"死亡猎手 masoj","丹加洛克","被遗忘者","前线间谍","高级执行官达萨利亚","奈杉德哨岗","支援斥候","塔伦米尔","最新命令"},sec={{t="给 Masoj 的命令",b="达萨利亚说，她信得过你，可以把情报交给前线间谍。她给了你一份最新命令，要送给 Masoj。他驻守在奈杉德哨岗以北、丹加洛克外的一处高地上。被遗忘者夺取这片土地控制权的计划仍在继续，Masoj 正等着接收命令。"}},faq={{q="是谁给了我命令？",a="高级执行官达萨利亚给了你一份最新命令，要送给死亡猎手 Masoj。",al={"谁派我去","达萨利亚的命令","交付人"}},{q="死亡猎手 Masoj 是谁？",a="死亡猎手 Masoj 是一名驻守在丹加洛克外、奈杉德哨岗以北的前线间谍。",al={"masoj 是谁","masoj"}},{q="我该去哪里找 Masoj？",a="Masoj 在塔伦米尔以南、奈杉德哨岗以北的一处高地上，位于丹加洛克外。",al={"masoj 的位置","masoj 在哪里","塔伦米尔以南"}},{q="我要带什么给 Masoj？",a="你带着一份给死亡猎手 Masoj 的最新命令。",al={"要送什么","给 masoj 的命令","包裹"}},{q="我为什么要送命令？",a="此行将助被遗忘者夺取这片土地的控制权。",al={"为什么找 masoj","计划是什么","被遗忘者的计划"}}},fp="13,164,16.293.0,23.71.0,26.87.0,22.96.0,28.48.0,27.72.0"}
P.entries["quest:98095"] = {n="Valuable Vantages",s="亡灵哨兵 Masoj 需要你在希尔斯布莱德丘陵周围恢复三处信号标记。蝙蝠骑手依靠这些地点，引导战略部队前往投放点。",h="亡灵哨兵 Masoj 需要你在希尔斯布莱德丘陵周围恢复三处信号标记。蝙蝠骑手依靠这些地点，引导战略部队前往投放点。",kw={"药剂师药瓶","蝙蝠骑手","亡灵哨兵 masoj","丹加洛克","敦霍尔德城堡","海岬","希尔斯布莱德丘陵","信号烽火","宝贵的制高点"},sec={{t="三座山峰",b="你带着药剂师药瓶，前往丹加洛克旁的山丘、敦霍尔德城堡上方的高原，以及希尔斯布莱德上方的海岬山脊。药瓶散发的气味会引回蝙蝠，帮助 Masoj 的高层指挥官引导部队穿过丘陵地带。"},{t="Masoj 的命令",b="Masoj 要你寻找破碎的空药瓶，并在三处地点重新布置信号。他称这项工作是以亡灵哨兵之名推进计划的一部分。"}},faq={{q="是谁要我放置药瓶？",a="亡灵哨兵 Masoj 要你恢复希尔斯布莱德丘陵周围的信号标记。",al={"谁提出了宝贵的制高点","masoj 药瓶","masoj 是谁"}},{q="为什么需要这些信号标记？",a="蝙蝠骑手利用信号点，引导战略部队前往投放点。",al={"蝙蝠为何需要标记","蝙蝠信号","信标有何用途"}},{q="我该把药瓶放在哪里？",a="三处地点分别是丹加洛克旁的山丘、敦霍尔德城堡上方的高原，以及希尔斯布莱德上方的海岬山脊。",al={"药瓶位置","山峰在哪里","三个药瓶放置点"}},{q="药瓶散发的气味有什么作用？",a="这些气味会发出信号，将蝙蝠引回指定的投放点。",al={"药瓶有什么用","蝙蝠气味","药瓶用途"}}},fp="17,169,11.261.0,14.164.0,36.86.0,35.80.0,27.119.0,27.57.0"}
P.entries["quest:981"] = {n="奥萨拉克斯之塔",s="这一差事标志着针对奥萨拉克斯之塔黑滩教派的战役取得了胜利。在消灭了黑海岸邪恶废墟中该教派的领导层后，冒险者将消息带往南方的灰谷，传达给净化者德尔格伦。这对联盟来说是一次至关重要的胜利，清除了古代暗夜精灵边境的恶魔腐蚀。",h="这一差事标志着针对奥萨拉克斯之塔黑滩教派的战役取得了胜利。在消灭了黑海岸邪恶废墟中该教派的领导层后，冒险者将消息带往南方的灰谷，传达给净化者德尔格伦。这对联盟来说是一次至关重要的胜利，清除了古代暗夜精灵边境的恶魔腐蚀。",kw={"奥萨拉克斯","灰谷","巴苏尔","教派","黑滩","黑海岸","德尔格伦","迈斯特拉岗哨"},ang={["class:Paladin"]="向净化者德尔格伦报告对圣骑士来说有着特殊的意义，他们与他有着共同的圣洁使命，即从世界上净化恶魔腐蚀和邪恶教派。",["faction:Alliance"]="消灭该教派保护了连接黑海岸和灰谷的陆路，确保联盟的侦察兵和旅行者免受恶魔伏击的安全。",["race:NightElf"]="对于暗夜精灵来说，净化奥萨拉克斯之塔消除了玷污他们神圣沿海森林的古代上层精灵遗迹中的污秽。"},sec={{t="切断威胁",b="奥萨拉克斯之塔在黑海岸北部矗立了数周，像是一道化脓的伤口，被狂热的黑滩教派及其阴影主人所占据。通过不懈的追踪、情报收集和激烈的冲突，该教派的行动被彻底瓦解。随着他们的术士被杀，黑暗仪式被破坏，黑海岸恶魔渗透的直接威胁终于得到了遏制。"},{t="向迈斯特拉岗哨报告",b="在教派领袖死亡后，巴苏尔·影击指引胜利者前往南方的灰谷迈斯特拉岗哨。净化者德尔格伦正在那里等待，他是圣光的忠实战士，负责监督针对奥萨拉克斯之塔邪恶占领者的十字军行动。传达教派覆灭的消息让区域防御者感到安心，同时也为这位勇士赢得了德尔格伦永恒的祝福和当之无愧的感激。"}},faq={{q="这个任务的目标是什么？",a="这个任务是漫长的奥萨拉克斯之塔任务线的最后一步。你只需要从塔附近前往灰谷的迈斯特拉岗哨，并将你的决定性胜利报告给净化者德尔格伦。",al={"奥萨拉克斯之塔目标","奥萨拉克斯之塔任务提交","981号任务在哪里提交"}},{q="净化者德尔格伦是谁？",a="净化者德尔格伦是一位驻扎在灰谷北部迈斯特拉岗哨的联盟勇士。他手握圣光，致力于在整个卡利姆多北部清除腐蚀并对抗像黑滩教派这样的恶魔威胁。",al={"谁是德尔格伦","德尔格伦背景故事","净化者德尔格伦"}},{q="巴苏尔·影击是谁？",a="巴苏尔·影击是一位在黑海岸奥萨拉克斯之塔附近执行任务的联盟特工。他与德尔格伦密切合作，监控教派的动向，并引导冒险者从内部瓦解这个黑暗集团。",al={"巴苏尔","巴苏尔背景故事","谁是巴苏尔·影击"}},{q="黑滩教派在塔里做了什么？",a="黑滩教派占据了奥萨拉克斯之塔的古代遗迹，以进行黑暗仪式、召唤恶魔实体，并扩大他们在黑海岸沿海地区的邪恶影响力。",al={"黑滩教派","奥萨拉克斯发生了什么","奥萨拉克斯之塔背景故事"}},{q="迈斯特拉岗哨位于哪里？",a="迈斯特拉岗哨是一个位于灰谷西北部的联盟哨所，就在沿大路从黑海岸过来的边界关卡以南。",al={"迈斯特拉岗哨位置","迈斯特拉岗哨在哪里","德尔格伦位置"}},{q="黑滩教派被彻底消灭了吗？",a="虽然他们在奥萨拉克斯之塔的领导层已被处决，主要的仪式已被破坏，但分散的教徒和残党仍然在卡利姆多偏僻的角落出没。然而，他们在黑海岸的有组织威胁已被粉碎。",al={"教派消失了吗","黑滩教派被摧毁","我们杀死了教派吗"}}},fp="22,202,16.358.0,24.388.0,31.201.0,28.248.0,29.205.0,56.189.0,32.129.0,52.228.0"}
P.entries["quest:98155"] = {n="Pristine Pesterhide Pelts",s="“Pristine Pesterhide Pelts”是一项代表克里斯蒂·格兰特（Kristy Grant）进行的任务，她是一位旅行者，正在千针石林寻找Pesterhide土狼那色彩鲜艳的毛皮。由于缺乏战斗训练，克里斯蒂依靠能干的冒险者来猎杀这些野兽并收集它们的毛皮。她的目标是将这些独特的皮毛运回无尽之海彼岸的暴风城，交给她的姐妹们，让她们将其制作成精致的服装和商品。",h="“Pristine Pesterhide Pelts”是一项代表克里斯蒂·格兰特（Kristy...",kw={"毛皮","狩猎","土狼","克里斯蒂·格兰特","pesterhide","暴风城","千针石林"},ang={["faction:Alliance"]="作为一位暴风城旅行者为她在首都从事工艺创作的家族提供供应的努力，这项任务凸显了联盟子民如何深入卡利姆多边境寻找异域材料。",["profession:Tailoring"]="从事布料和装饰性皮草工作的工匠们能够理解克里斯蒂姐妹们的雄心，她们试图将卡利姆多的野性毛皮转化为精致的服装。",["race:Human"]="克里斯蒂·格兰特体现了暴风城人类跨海远行、与王国内亲人保持密切联系的进取精神。"},sec={{t="姐妹的志向",b="远离暴风城繁华的鹅卵石街道，克里斯蒂·格兰特发现自己正穿行于千针石林那干旱、被阳光炙烤的峡谷底部。在观察当地野生动物时，她被本土Pesterhide土狼所披皮毛那令人惊叹的色泽和品质所吸引。克里斯蒂意识到这些独特的毛皮在东部王国几乎闻所未闻，于是她设想将一批毛皮运回故乡交给她的姐妹们。在她眼中，这些毛皮不仅是卡利姆多边境的一抹特色，更是原料，能经由家族中熟练的工匠之手，转化为真正非凡的物品。"},{t="盐碱平原与峡谷的猎人",b="尽管拥有工艺和贸易的眼光，克里斯蒂·格兰特并非战士，也没有面对峡谷中凶猛掠食者的战斗经验。Pesterhide土狼是凶残的群体食腐动物，游荡在参天平顶山下的尘土旷野中，这使得对于任何独自旅行的人来说，收获完整的毛皮都十分危险。为了在不危及自己生命的情况下获得五张无瑕的毛皮，克里斯蒂寻求路过千针石林的资深冒险者的帮助。这项任务需要冒险进入荒野，战胜那些领地意识极强的野兽，并仔细收集她家族在故乡进行工艺创作所需的毛皮。"}},faq={{q="谁是克里斯蒂·格兰特？",a="克里斯蒂·格兰特是一位来自暴风城王国的旅行者，目前正在卡利姆多游历。与穿行于千针石林的强硬士兵和雇佣兵不同，她承认自己没有任何战斗经验。相反，她依靠敏锐的观察力和对贵重工艺材料的独到眼光，雇佣能干的冒险者代她收集像土狼毛皮这样的货物。",al={"克里斯蒂·格兰特背景故事","谁发布了pristine pesterhide pelts任务","克里斯蒂·格兰特是谁"}},{q="什么是Pesterhide土狼？",a="Pesterhide土狼是原产于千针石林干旱峡谷底部和旷野的野生犬科掠食者。它们成群结队地在严酷的地形中游荡，进行狩猎和食腐。除了凶猛的本性外，它们还因其绚丽、色彩优美的皮毛而闻名，这些皮毛在沙漠岩石的映衬下显得格外显眼，吸引了过往裁缝和皮草商的注意。",al={"pesterhide土狼","千针石林的土狼","什么是pesterhide"}},{q="为什么克里斯蒂·格兰特想要这些毛皮？",a="克里斯蒂·格兰特想要收集完整的土狼毛皮，并将它们运回无尽之海彼岸的暴风城王国交给她的姐妹们。她对这些毛皮绚丽的色泽印象深刻，并相信她的姐妹们拥有将这些异域皮毛编织或剪裁成令人惊叹的成品所需的工艺。",al={"为什么要收集pesterhide毛皮","pesterhide毛皮的用途","克里斯蒂如何处理这些毛皮"}},{q="这些毛皮最终会去哪里？",a="在千针石林收集的毛皮最终将运往东部王国，具体来说是暴风城这座城邦。克里斯蒂打算将收获的毛皮运回无尽之海彼岸的故乡，这样她的姐妹们就可以使用那些在艾尔文森林或赤脊山等熟悉的林地中几乎无法获得的异域材料进行创作。",al={"毛皮被运往何处","运往暴风城的毛皮","谁获得了这些土狼毛皮"}},{q="为什么克里斯蒂不能自己猎杀土狼？",a="克里斯蒂·格兰特公开承认她完全没有任何战斗经验。千针石林的野兽极具攻击性且危险重重，特别是对于手无寸铁的工匠或旅行者而言。与其在游荡的土狼群面前冒受伤或死亡的风险，她雇佣熟练的流浪者来安全地猎杀这些动物。",al={"为什么克里斯蒂不能战斗","克里斯蒂·格兰特的战斗能力","为什么克里斯蒂需要帮助"}},{q="是什么让这些毛皮被称为“完整的”（Pristine）？",a="由于这些毛皮旨在供克里斯蒂在暴风城的姐妹们进行精细的工艺和时尚创作，普通的或破损的毛皮是不够的。只有未受损、完整的毛皮才能保留制作高质量服装所需的鲜艳色泽和质地，因此必须小心狩猎，并从野兽身上精心挑选出最好的样本。",al={"完整毛皮的含义","为什么需要完整的毛皮","pristine pesterhide pelts的质量"}}},fp="25,416,19.626.0,37.648.0,20.388.0,27.373.0,37.309.0,26.326.0,41.329.0,32.339.0"}
P.entries["quest:98189"] = {n="Return the Statuette",s="找回的雕像原本要送往米奈希尔港，却因一场悲剧而未能送达。有人请你将它交给米奈希尔城堡的斯托菲队长。",h="找回的雕像原本要送往米奈希尔港，却因一场悲剧而未能送达。有人请你将它交给米奈希尔城堡的斯托菲队长。",kw={"盲眼公主","斯托菲队长","米奈希尔港","米奈希尔城堡","米奈希尔雕像","雕像"},sec={{t="未完成的交付",b="这尊雕像原本要送到米奈希尔港，并由米奈希尔城堡的斯托菲队长签收。有人请你完成这次交付。"}},faq={{q="谁应该接收这尊雕像？",a="米奈希尔城堡的斯托菲队长应该签收米奈希尔雕像。",al={"谁接收雕像","雕像接收者","斯托菲队长交付"}},{q="这尊雕像原本要送到哪里？",a="这尊雕像原本要送往米奈希尔港。",al={"雕像送往何处","雕像目的地","米奈希尔雕像"}},{q="之前是谁带着它？",a="悲剧发生前，The Blind Princess 原本要送交这尊雕像。",al={"谁带着雕像","盲眼公主雕像","雕像交付"}},{q="我该做什么？",a="有人请你将米奈希尔雕像交给米奈希尔城堡的斯托菲队长。",al={"该做什么","归还雕像","雕像任务"}}},fp="20,134,22.156.0,38.82.0,39.59.0,27.79.0,26.84.0"}
P.entries["quest:98190"] = {n="A Friend of the Family",s="“家族之友”是一项紧急的快递任务，始于湿地的米奈希尔港。由于担心龙喉兽人等当地威胁，港口当局委托一位冒险者将无价的米奈希尔雕像直接送到暴风城的暴风城要塞，交给伯瓦尔·弗塔根公爵。",h="“家族之友”是一项紧急的快递任务，始于湿地的米奈希尔港。由于担心龙喉兽人等当地威胁，港口当局委托一位冒险者将无价的米奈希尔雕像直接送到暴风城的暴风城要塞，交给伯瓦尔·弗塔根公爵。",kw={"伯瓦尔","龙喉氏族","弗塔根","港口","米奈希尔","雕像","暴风城","泰瑞纳斯","湿地"},ang={["class:Paladin"]="“米奈希尔”这个名字让人想起白银之手骑士团的创始赞助人，因此保护这件遗物对任何圣光战士来说都是庄严的职责。",["faction:Alliance"]="运送这件遗物不仅是为了纪念历史悠久的北方联盟，还能防止它落入龙喉氏族的手中。",["race:Human"]="对于人类来说，守护米奈希尔王朝的一件文物，就是守护陨落的洛丹伦那份引以为傲却又充满悲剧色彩的记忆，同时也强化了暴风城作为最后伟大人类王国的职责。"},sec={{t="岌岌可危的港口",b="米奈希尔港是连接东部王国北部和南部的关键海上门户。该港口以洛丹伦已故国王泰瑞纳斯·米奈希尔二世的名字命名，孤立在危险的沼泽和充满敌意的敌人之中。随着当地威胁的增加，港口领导层认识到，与北方陨落王国相关的无价遗物无法在这样一个暴露的前哨站中得到安全保护。"},{t="龙喉氏族的威胁",b="湿地仍然盘踞着龙喉氏族的残党，这些野蛮的兽人以其黑暗的过去和无情的投机主义而闻名。鉴于他们就在附近且渴望征服，港口守卫担心龙喉氏族会不择手段地掠夺像米奈希尔雕像这样的历史珍宝，甚至可能为了自己的目的而亵渎或将这种象征武器化。"},{t="直接面见公爵",b="为了避免通过常规官僚或军事渠道造成的延误，快递员被指示完全绕过指挥链。遗物被直接发往暴风城要塞，交到年轻的安度因·乌瑞恩国王的摄政王——伯瓦尔·弗塔根公爵手中，坚信首都的领导层最能保护这份洛丹伦的遗产。"}},faq={{q="什么是米奈希尔雕像？",a="米奈希尔雕像是一件与洛丹伦王室血统和泰瑞纳斯·米奈希尔二世国王有关的珍贵传家宝。它代表了北方王国与联盟之间的历史纽带，使其成为了拾荒者和敌人的目标。",al={"米奈希尔遗物","雕像是什么","雕像背景"}},{q="为什么雕像不能留在米奈希尔港？",a="米奈希尔港位置偏远，四周环绕着充满敌意的沼泽、黑铁矮人、鱼人和敌对兽人。驻军认为该定居点过于脆弱，无法安全保护如此重要的遗物。",al={"为什么要转移雕像","米奈希尔港不安全吗"}},{q="龙喉氏族是谁，为什么他们想要它？",a="龙喉氏族是盘踞在湿地内的一支兽人派系。港口官员担心他们会不惜牺牲战士来掠夺享有盛誉的联盟遗物，并可能对其进行亵渎或恶意利用。",al={"龙喉氏族威胁","为什么兽人想要雕像"}},{q="为什么要将遗物直接交给伯瓦尔·弗塔根？",a="作为暴风城的摄政王和年轻的安度因国王的守护者，伯瓦尔·弗塔根公爵在首都拥有最高行政权力。直接交给他可以确保遗物绕过行政僵局，并获得最高级别的安全保障。",al={"为什么是伯瓦尔","为什么要绕过指挥链"}},{q="伯瓦尔·弗塔根公爵在哪里？",a="伯瓦尔·弗塔根公爵站在暴风城要塞的王座大厅里，与年幼的安度因·乌瑞恩国王在一起。",al={"伯瓦尔位置","伯瓦尔在哪里"}},{q="米奈希尔港与泰瑞纳斯国王有什么联系？",a="米奈希尔港是为了纪念泰瑞纳斯·米奈希尔二世国王而命名的，他在第三次战争中不幸去世之前，曾领导洛丹伦并在第二次战争期间支持洛丹伦联盟。",al={"为什么叫米奈希尔港","泰瑞纳斯·米奈希尔联系"}}},fp="22,175,19.297.0,20.229.0,24.276.0,31.211.0,48.161.0,46.186.0,51.192.0,43.100.0,49.159.0"}
P.entries["quest:98191"] = {n="A Friend of the Family",s="伯瓦尔·弗塔根公爵委托一位冒险者将一座珍贵的米奈希尔雕像送到Cathedral of Light。这座遗物描绘了洛丹伦已故的国王泰瑞纳斯·米奈希尔二世，它已经开始汇聚圣光之力。它被移交给格雷森·沙东布瑞克公爵，以在暴风城的精神中心进行永久保存。",h="伯瓦尔·弗塔根公爵委托一位冒险者将一座珍贵的米奈希尔雕像送到Cathedral of...",kw={"伯瓦尔","大教堂","洛丹伦","米奈希尔","沙东布瑞克","雕像","暴风城","泰瑞纳斯"},ang={["class:Paladin"]="对于一名圣骑士来说，守护一件带有圣光有形触感的泰瑞纳斯国王遗物，代表了对最初批准成立白银之手骑士团的统治者的深切敬意。",["class:Priest"]="在一尊简单的雕像中汇聚圣光能量，印证了洛丹伦信徒即使在王国物质毁灭之后，依然长存的精神遗产。",["faction:Alliance"]="泰瑞纳斯·米奈希尔二世国王是洛丹伦联盟的基石，这使得任何与他有关的文物都成为团结和纪念的宝贵象征。"},sec={{t="一份珍贵的纪念品",b="泰瑞纳斯·米奈希尔二世国王是第二次战争期间大联盟的缔造者，也是一位极具个人奉献精神的人。尽管他在人类诸王国中地位崇高，泰瑞纳斯却非常谦逊，并以不喜欢为自己树碑立传而闻名。由于他的个人抵触，很少有人委托制作他的肖像，而在洛丹伦遭受恐怖的毁灭和天灾军团的蹂躏后，幸存下来的就更少了。"},{t="神恩的触碰",b="当伯瓦尔·弗塔根公爵检查幸存的米奈希尔雕像时，他发现了远超简单工艺的东西。圣光本身已经开始在这尊雕像内汇聚，赋予其宁静的精神共鸣。伯瓦尔认为Stormwind Keep的皇宫对于这样一件神圣的物品来说并不是合适的圣所，于是他指示将其带过城市送到Cathedral of Light，交由圣骑士训练师格雷森·沙东布瑞克公爵保管。"}},faq={{q="泰瑞纳斯·米奈希尔二世国王是谁？",a="泰瑞纳斯·米奈希尔二世国王是洛丹伦王国的受人爱戴的统治者。在第二次战争期间，他召集了不同的人类国家，并与矮人、侏儒和高等精灵联手组建了大联盟，最终击败了兽人部落。他在自己王国的陷落中被杀。",al={"泰瑞纳斯·米奈希尔","泰瑞纳斯是谁","洛丹伦国王"}},{q="为什么泰瑞纳斯国王的雕像如此稀少？",a="尽管他享有崇高的声望并深受人民爱戴，泰瑞纳斯国王却以个人谦逊而闻名，不喜欢奢华的自我纪念碑。很少有雕像或纪念碑是以他的形象雕刻的，而且几乎没有在洛丹伦的天灾毁灭中幸存下来。",al={"为什么雕像很少","米奈希尔雕像的稀有度","为什么纪念碑很少"}},{q="为什么米奈希尔雕像会散发出圣光？",a="伯瓦尔注意到圣光似乎已经在雕像中汇聚。他称赞泰瑞纳斯是一位善良而虔诚的人，但并没有解释为什么这座特定的雕像会聚集圣光之力。",al={"为什么雕像有圣光","神圣雕像","汇聚的圣光"}},{q="格雷森·沙东布瑞克公爵是谁？",a="格雷森·沙东布瑞克公爵是一位白银之手骑士团的人类老兵圣骑士，也是Cathedral of Light内的一位杰出大师。他驻扎在Cathedral Square，负责训练有志向的圣骑士，并为暴风城的信徒监督圣职事务。",al={"沙东布瑞克是谁","格雷森的角色"}},{q="为什么伯瓦尔公爵要将雕像送到Cathedral of Light？",a="虽然伯瓦尔尊崇泰瑞纳斯作为联盟之父的角色，但雕像已经明显聚集了圣光之力。伯瓦尔认为，这种圣光的载体不属于Stormwind Keep的宫廷官僚，而应该在圣职教团的照看下存放在Cathedral of Light中。",al={"为什么要送到大教堂","为什么不留在stormwind keep"}},{q="Cathedral of Light位于何处？",a="Cathedral of Light俯瞰着Cathedral Square，位于暴风城的中心地带，处于Dwarven District、Trade District和Mage Quarter之间。它是南部王国圣光教会的主要圣所和礼拜中心。",al={"cathedral of light在哪里","cathedral square的位置"}}},fp="22,156,18.328.0,16.369.0,33.285.0,40.164.0,53.156.0,34.250.0,61.248.0,40.251.0"}
P.entries["quest:98197"] = {n="Spoils of War",s="瓦斯塔格·铁腭需要来自米奈希尔港的卡兹莫丹木材和铁料。这些找回的物资将帮助加固城镇防御，抵御龙喉氏族的进犯。",h="瓦斯塔格·铁腭需要来自米奈希尔港的卡兹莫丹木材和铁料。这些找回的物资将帮助加固城镇防御，抵御龙喉氏族的进犯。",kw={"龙喉氏族","卡兹莫丹铁料","卡兹莫丹木材","米奈希尔港","旧部落","战争掠夺品","城镇防御","瓦斯塔格·铁腭"},ang={["faction:Alliance"]="作为一名联盟旅者，你正在帮助加强城镇防御，抵御龙喉氏族。",["race:Dwarf"]="作为一名矮人，你或许会注意到，旧部落当年在此建造舰队，所用资源都是从卡兹莫丹掠夺而来。"},sec={{t="港口仓库",b="米奈希尔港最初是旧部落入侵希尔斯布莱德的集结地。他们在那里建造舰队，所用资源都是从卡兹莫丹掠夺而来，港口里至今还留有部分物资。瓦斯塔格请你把木材和铁料带给他，用来支援城镇防御。"},{t="新的补给",b="瓦斯塔格感谢你带来的物资。有了它们，城镇就不必只依赖塞拉摩或奥伯丁运来的补给。"}},faq={{q="瓦斯塔格需要从米奈希尔港找回什么？",a="瓦斯塔格请你从米奈希尔港找回卡兹莫丹木材和铁料。",al={"他需要什么","木材和铁料","港口物资"}},{q="为什么港口里会有卡兹莫丹的物资？",a="旧部落在米奈希尔港建造舰队，所用资源都是从卡兹莫丹掠夺而来。",al={"木材为何在港口","卡兹莫丹铁料","旧部落物资"}},{q="这些物资有什么用？",a="瓦斯塔格说，这些物资能在龙喉氏族进犯时帮助加强城镇防御。",al={"为何收集物资","防御","这些物资有何用"}},{q="瓦斯塔格·铁腭是谁？",a="瓦斯塔格·铁腭请你从米奈希尔港找回木材和铁料。",al={"瓦斯塔格是谁","瓦斯塔格","铁腭"}},{q="旧部落曾如何利用米奈希尔港？",a="旧部落建造米奈希尔港，将其作为海上入侵希尔斯布莱德的集结地。",al={"旧部落港口","米奈希尔港历史","入侵希尔斯布莱德"}},{q="瓦斯塔格为何欢迎这些补给？",a="有了这些物资，城镇就不必只依赖塞拉摩或奥伯丁运来的补给。",al={"为何道谢","塞拉摩补给","奥伯丁物资"}}},fp="13,133,13.272.0,12.129.1,44.76.0,42.86.0,36.92.0,23.73.0,44.91.0,40.90.0"}
P.entries["quest:982"] = {n="深不可测的海洋",s="“深海，浩瀚之洋”是一个联盟任务，由奥伯丁的高尔博德·钢手提供。玩家的任务是潜入村庄北侧的水域，从两艘沉没的暗夜精灵船只——“银色黎明号”和“迷雾面纱号”中找回私人锁箱。这两艘船都遭到了沿海鱼人的伏击，幸存的船员们正急于寻求一个了结。",h="“深海，浩瀚之洋”是一个联盟任务，由奥伯丁的高尔博德·钢手提供。玩家的任务是潜入村庄北侧的水域，从两艘沉没的暗夜精灵船只——“银色黎明号”和“迷雾面纱号”中找回私人锁箱。这两艘船都遭到了沿海鱼人的伏击，幸存的船员们正急于...",kw={"奥伯丁","黑海岸","深海浩瀚之洋","高尔博德·钢手","锁箱","迷雾面纱号","鱼人","沉船","银色黎明号"},ang={["faction:Alliance"]="奥伯丁船员们共同的悲痛展现了矮人与暗夜精灵在卡利姆多海岸之间紧密的航海合作。",["race:Dwarf"]="高尔博德·钢手展现了矮人缅怀阵亡同伴、在异乡港口支持其他船员的典型本能。",["race:NightElf"]="阵亡的船长们是服务于奥伯丁海上贸易的暗夜精灵航海家，找回他们的遗物是一项关乎祖先荣誉的任务。"},sec={{t="海岸悲剧",b="黑海岸外的水域变得越来越危险，不仅仅是因为暗流和天然暗礁，还有极具攻击性的沿海部落。“银色黎明号”和“迷雾面纱号”在前往奥伯丁港口的途中，被成群的鱼人淹没。两艘船都没能幸免于难，沉没在定居点北部的浅滩中。幸存的船员虽然逃到了岸上，但船只和船长的损失给港口笼罩上了一层沉重的阴影。"},{t="找回失落的记忆",b="驻扎在奥伯丁的矮人高尔博德·钢手主动承担起缅怀阵亡暗夜精灵船长的责任。尽管这些船只现在已是水下废墟，被当地鱼人当作战利品和巢穴，但船长们的锁箱仍锁在进水的船舱里。找回里面的航海日志和个人物品，可以让奥伯丁的幸存船员们妥善哀悼他们的指挥官，并让逝者的灵魂得到安息。"}},faq={{q="沉船位于哪里？",a="“银色黎明号”和“迷雾面纱号”的残骸都淹没在黑海岸外，就在奥伯丁码头的正北方。",al={"沉船位置","沉船地点","在哪里找到银色黎明号"}},{q="“银色黎明号”和“迷雾面纱号”发生了什么事？",a="两艘船在穿越大海前往奥伯丁的途中都遭到了鱼人的伏击。船员们被鱼人压制，两位船长不幸丧生，船只沉没在海底。",al={"船只是如何沉没的","为什么船只沉没","什么让迷雾面纱号沉没"}},{q="高尔博德·钢手是谁？",a="高尔博德·钢手是一位居住在暗夜精灵港口奥伯丁的矮人。他照顾着镇上的幸存船员，并委托冒险者找回失踪船长的遗物。",al={"谁提供深海浩瀚之洋任务","高尔博德·钢手背景故事"}},{q="锁箱里有什么？",a="锁箱里装着阵亡的暗夜精灵船长的个人物品和航海日志，这些都是在海难中幸存的船员们所珍视的物品。",al={"锁箱里有什么","船长锁箱内容物"}},{q="为什么幸存者如此在意这些遗物？",a="这些船长是备受尊崇的暗夜精灵航海家。找回他们的日志和遗物是对幸存船员的一种慰藉，据信这也有助于让逝者的灵魂得到安息。",al={"为什么要找回锁箱","为什么要帮助船长"}},{q="现在是什么生物占据了沉船？",a="废墟已被鱼人占领，它们将沉没的船体当作战利品，并在周围的水域游荡。",al={"什么在守卫沉船","沉船处的怪物"}}},fp="20,208,21.248.0,24.304.0,35.71.0,54.147.0,25.143.0,29.126.0,54.150.0,42.102.0"}
P.entries["quest:98208"] = {n="Bloom of the Heavens",s="“天之绽”涉及到寻回诺德尔，这是一种神圣的暗夜精灵花卉，必须在满月时于海加尔山采集。这朵花在暗夜精灵船只“飞鱼号”于米奈希尔港以南遭遇海难时遗失了，与其一同沉没的还有库尔提拉斯第三舰队的船只。现在，找回这朵花的任务落在了那些勇敢到足以面对盘踞在残骸中的鱼人的冒险者手中。",h="“天之绽”涉及到寻回诺德尔，这是一种神圣的暗夜精灵花卉，必须在满月时于海加尔山采集。这朵花在暗夜精灵船只“飞鱼号”于米奈希尔港以南遭遇海难时遗失了，与其一同沉没的还有库尔提拉斯第三舰队的船只。现在，找回这朵花的任务落在了...",kw={"奥伯丁","bloom of the heavens","飞鱼号","米奈希尔港","海加尔山","鱼人","诺德尔","赛蕾莎·暮语","泰达希尔","湿地"},ang={["faction:Alliance"]="遗失的飞鱼号在米奈希尔港海岸外遭遇灾难前，曾与库尔提拉斯第三舰队一同航行。",["profession:Herbalism"]="诺德尔是一种极其罕见的暗夜精灵花卉，必须在海加尔山顶的满月下培育，使其成为一种非凡的植物学奇观。",["race:NightElf"]="诺德尔代表了一种珍贵的来自海加尔山的植物圣物，是在暗夜精灵将家园迁往泰达希尔枝叶之前采集的。"},sec={{t="海加尔山的圣物",b="赛蕾莎·暮语从卡利姆多海岸的奥伯丁远道而来，前往米奈希尔港，试图打捞一件具有深厚文化意义的宝物。她寻找的货物是诺德尔，通用语称其为“天之绽”，这是一种神圣的花朵，在满月时采集于海加尔山之巅。对于如今居住在泰达希尔的流离失所的暗夜精灵来说，这些来自故土山脉的圣物是他们文化传承中无可替代的珍宝。"},{t="飞鱼号的命运",b="这朵花在许多个月前就已经遗失了。当时，暗夜精灵的“飞鱼号”船只在与库尔提拉斯第三舰队同行时，在米奈希尔港以南的岩石海岸遭遇海难。如今，这艘破损的船体残骸静静地躺在浅滩中，作为这场灾难的沉重纪念碑。更糟糕的是，凶猛的鱼人掠夺者占据了沉船残骸，它们极力守卫着这艘破船，并威胁着任何试图收回卡多雷货物的人。"}},faq={{q="什么是诺德尔？",a="诺德尔在达纳苏斯语中的意思是“天之绽”。它是对暗夜精灵具有重要意义的神圣花卉，在满月时从暗夜精灵的祖居地——海加尔山之巅采摘。",al={"什么是诺德尔","诺德尔花卉","什么是天之绽"}},{q="飞鱼号是什么？",a="飞鱼号是一艘与库尔提拉斯第三舰队同行的暗夜精灵船只。许多个月前，这艘船在湿地的米奈希尔港以南海岸遭遇海难，其珍贵的货物也随之散落。",al={"飞鱼号船只","哪艘船沉没了","库尔提拉斯第三舰队湿地"}},{q="赛蕾莎·暮语是谁？",a="赛蕾莎·暮语是一位暗夜精灵使者，她跨越海洋，从奥伯丁和泰达希尔的枝叶间来到米奈希尔港，专门为了替族人寻回这朵遗失的花朵。",al={"谁是赛蕾莎·暮语","米奈希尔港的任务发布者","米奈希尔的暗夜精灵"}},{q="沉船为什么危险？",a="凶猛的鱼人掠夺者已经侵占了米奈希尔港以南的海岸残骸，占领了飞鱼号的残骸，这使得赛蕾莎的打捞工作变得极其危险。",al={"为什么鱼人在残骸处","谁守卫着残骸","米奈希尔以南的残骸"}},{q="为什么诺德尔对暗夜精灵如此重要？",a="这朵花是在泰达希尔建立之前，于卡多雷曾经的家园——海加尔山之巅采摘的。由于其来源的特殊性和在满月下采摘的神圣仪式，它对暗夜精灵而言具有巨大的文化和情感价值。",al={"为什么这朵花很重要","赛蕾莎为什么想要诺德尔"}},{q="在哪里可以找到残骸？",a="飞鱼号的残骸位于湿地的米奈希尔港以南的海岸上，坐落在如今被敌对鱼人占领的岩石之中。",al={"残骸在哪里","花在哪里","湿地沉船地点"}}},fp="20,285,22.299.0,29.295.0,16.175.0,27.182.0,27.145.0,31.155.0,47.190.0,32.122.0"}
P.entries["quest:98209"] = {n="Bloom of the Heavens",s="“天界之花”是一次跨海旅程，旨在运送一种名为“诺德尔”的暗夜精灵奇迹植物遗物。人们认为它已经失传数代，但这一幸存的植株成为了艾露恩的恩典以及卡多雷在失去永生后依然坚韧不拔的强大象征。",h="“天界之花”是一次跨海旅程，旨在运送一种名为“诺德尔”的暗夜精灵奇迹植物遗物。人们认为它已经失传数代，但这一幸存的植株成为了艾露恩的恩典以及卡多雷在失去永生后依然坚韧不拔的强大象征。",kw={"奥伯丁","bloom of the heavens","黑海岸","达纳苏斯","艾露恩","米奈希尔港","诺德尔","塞莱萨","桑德里斯风歌","湿地"},ang={["faction:Alliance"]="这一任务连接了东部王国繁忙的联盟港口——米奈希尔港，以及横跨无尽之海后的卡利姆多北部的奥伯丁与达纳苏斯。",["profession:Herbalism"]="草药师和植物学家们一定会对诺德尔的失而复得感到欣喜，这是一种被认为失传已久、需要在达纳苏斯进行培育的神圣植物。",["race:NightElf"]="诺德尔是卡利姆多神圣遗产的珍贵遗存，也是艾露恩在卡多雷适应失去永生的过程中依然眷顾着他们的美好征兆。"},sec={{t="危险的回收",b="在湿地的沼泽中，塞莱萨成功回收了传说中的花朵——诺德尔，并抵御了当地凶猛鱼人的攻击。由于在惊险的逃脱后精疲力竭，她将这株寻回的植物托付给一位冒险者，让他将其带过无尽之海送往奥伯丁。从米奈希尔港出发的船只可以直达黑海岸，连接起东部王国与卡利姆多北部。"},{t="艾露恩恩典的征兆",b="当奥伯丁的桑德里斯·风歌长老收到诺德尔时，他感到无比震惊，因为他一直以为这株神圣的花朵早已永远消失了。对于在海加尔山之战后不得不接受失去永生这一代价的暗夜精灵来说，诺德尔的奇迹般幸存如同艾露恩降下的福泽，闪耀着光芒。桑德里斯准备将这株娇贵的植物送往达纳苏斯，以确保它能被妥善培育并传承给后代。"}},faq={{q="什么是诺德尔？",a="诺德尔是暗夜精灵认为早已失传的一种神圣植物。它在多年后被重新发现并幸存下来，使其成为艾露恩神圣眷顾的珍贵象征，也是大自然顽强生命力的见证。",al={"什么是诺德尔","诺德尔之花","神圣之花"}},{q="谁发布了“天界之花”这个任务？",a="该任务由位于湿地的塞莱萨发布。尽管遭到敌对鱼人的伏击和追击，她还是成功找回了这株神圣的花朵，但这次磨难使她精疲力竭，无法亲自完成余下的旅程。",al={"谁发布天界之花任务","湿地诺德尔任务发布者","湿地塞莱萨"}},{q="诺德尔需要被送往哪里？",a="诺德尔必须被送过大海，交给位于黑海岸沿岸的奥伯丁的桑德里斯·风歌长老。从米奈希尔港出发，旅客可以乘船直达奥伯丁。",al={"我该把诺德尔带到哪里","桑德里斯风歌位置","奥伯丁交付"}},{q="为什么诺德尔对暗夜精灵如此重要？",a="桑德里斯·风歌长老认为这株花朵的幸存是黑暗时期中极其罕见的希望灯塔。它神圣地提醒着人们艾露恩的恩典，以及卡多雷在第三次战争中牺牲了永生后依然坚韧不拔的精神。",al={"为什么诺德尔对暗夜精灵很重要","诺德尔背景故事","暗夜精灵永生诺德尔"}},{q="这朵花到达奥伯丁后会发生什么？",a="在奥伯丁收到这株花后，桑德里斯·风歌会安排将其安全地运往内陆的达纳苏斯，由那里的暗夜精灵植物学家和祭司进行精心的培育。",al={"诺德尔后续","诺德尔达纳苏斯","桑德里斯把诺德尔送到哪"}},{q="如何从米奈希尔港前往奥伯丁？",a="旅客可以搭乘停靠在湿地米奈希尔港的客船，该船会横跨无尽之海，直接抵达黑海岸的奥伯丁码头。",al={"如何从湿地前往奥伯丁","米奈希尔港前往奥伯丁的船","前往黑海岸的船"}}},fp="20,189,20.315.0,23.403.0,16.153.0,41.199.0,40.155.0,49.201.0,56.170.0,52.98.0"}
P.entries["quest:98219"] = {n="The Shamed Lieutenant",s="一名暴风城卫兵请你去南海镇探望法尔林·奥里涅尔中尉。他被调职是为了让他吸取教训，但卫兵仍希望他能有所作为。",h="一名暴风城卫兵请你去南海镇探望法尔林·奥里涅尔中尉。他被调职是为了让他吸取教训，但卫兵仍希望他能有所作为。",kw={"法尔林·奥里涅尔","希尔斯布莱德丘陵","法尔林中尉","米奈希尔港","南海镇","暴风城卫兵","蒙羞的中尉"},ang={["faction:Alliance"]="作为一名联盟旅人，你受托去探望一名在南海镇服役的暴风城城卫。"},sec={{t="前去探望",b="你已安全送达小雕像。如今，你的联系人请你去见法尔林·奥里涅尔中尉。这名城卫被调往希尔斯布莱德丘陵的南海镇。中尉的父亲曾是这名卫兵的朋友，他认为有人帮一把或许能让中尉受益。若你途经米奈希尔港，那里有船前往南海镇。"}},faq={{q="要我去见谁？",a="你要去见法尔林·奥里涅尔中尉，他是一名被调往南海镇的城卫。",al={"法尔林是谁","法尔林中尉","法尔林·奥里涅尔"}},{q="法尔林中尉在哪里？",a="法尔林·奥里涅尔中尉在希尔斯布莱德丘陵的南海镇。",al={"法尔林在哪里","法尔林的位置","南海镇中尉"}},{q="法尔林为何被调职？",a="卫兵说法尔林需要吸取教训，但没有进一步说明他被调职的原因。",al={"为何被调职","法尔林受罚","他为何在南海镇"}},{q="卫兵怎么认识法尔林？",a="法尔林的父亲曾是那名请你去探望他的卫兵的朋友。",al={"法尔林的父亲","他父亲是谁","卫兵与他的关系"}},{q="怎么去南海镇？",a="你可以乘坐从米奈希尔港出发的船前往南海镇。",al={"去南海镇的船","米奈希尔路线","怎么去那里"}},{q="以前有人探望过法尔林吗？",a="法尔林说，上个月有另一名暴风城卫兵来探望过他。",al={"上个月","其他访客","谁去探望法尔林"}}},fp="21,171,10.331.0,35.94.0,27.68.0,26.93.0,31.71.0,28.55.0,36.76.0"}
P.entries["quest:98245"] = {n="Razormaw Needling",s="“刃喉之针”是湿地的一项任务，在该任务中，Howin Kindfeather委托旅行者从当地的刃喉迅猛龙身上收集门齿。Howin打算用它们锋利的牙齿制作耐用的锥子，以便刺穿并缝合幼龙鳞片，从而制成抗火护甲。",h="“刃喉之针”是湿地的一项任务，在该任务中，Howin Kindfeather委托旅行者从当地的刃喉迅猛龙身上收集门齿。Howin打算用它们锋利的牙齿制作耐用的锥子，以便刺穿并缝合幼龙鳞片，从而制成抗火护甲。",kw={"黑铁","龙喉","howin kindfeather","恐龙岭","迅猛龙","刃喉门齿","razormaw needling","盐沫沼泽","湿地","幼龙鳞片"},ang={["faction:Alliance"]="确保防龙火装备的供给，有助于联盟对抗占据东部沼泽的龙类和龙喉部队的持续斗争。",["race:Dwarf"]="Howin Kindfeather与蛮锤矮人和铁炉堡矮人一样，对肆虐湿地和格瑞姆巴托的黑铁氏族和龙喉兽人怀有深切的仇恨。"},sec={{t="复仇工具",b="在湿地那潮湿的土地上，Howin Kindfeather对那些长期祸害该地区的敌人怀有深刻的仇恨：狡诈的黑铁矮人、残暴的龙喉兽人，以及他们带入战场、口吐烈焰的幼龙。为了反击并防备龙火，Howin致力于用幼龙鳞片制作防护护甲。然而，这些坚韧的兽皮在没有特殊制作工具的情况下，极难缝合在一起。"},{t="獠牙化作针",b="为了刺穿坚韧的幼龙皮，Howin需要比普通钢针更锋利、更坚固的工具，因为普通钢针在龙鳞上很容易弯曲或变钝。他将目光投向了潜伏在东北部恐龙岭和西北部盐沫沼泽的本地刃喉迅猛龙。刃喉迅猛龙因其致命且如针尖般锋利的牙齿而得名，完整的刃喉迅猛龙门齿是完美的锥子，可以刺穿坚硬的鳞片而不会在压力下破碎。"}},faq={{q="谁发布了任务“刃喉之针”？",a="Howin Kindfeather在湿地发布了这个任务。他深切痛恨黑铁矮人、龙喉氏族以及他们骑乘的幼龙，并试图用幼龙鳞片制作抗龙火护甲。",al={"谁发布了刃喉之针任务","howin kindfeather是谁","刃喉之针任务发布者"}},{q="为什么Howin Kindfeather需要刃喉迅猛龙的门齿？",a="Howin正在使用坚韧的幼龙鳞片制作防护护甲，但这种皮太厚，难以缝合。他需要刃喉迅猛龙锋利而坚固的门齿来制作一套足以刺穿鳞片而不会折断的锥子。",al={"为什么howin需要迅猛龙牙齿","刃喉迅猛龙门齿的用途","这些牙齿是用来做什么的"}},{q="刃喉迅猛龙在哪里？",a="刃喉迅猛龙在湿地有两处主要的狩猎场：位于东北部高地的恐龙岭，以及位于西北部靠近海岸的盐沫沼泽。",al={"在哪里可以找到刃喉迅猛龙","湿地刃喉迅猛龙位置","迅猛龙在哪里"}},{q="Howin Kindfeather用幼龙鳞片制作什么？",a="Howin正在将幼龙鳞片缝合成防护装备。这些鳞片能提供卓越的防御力来抵御烈焰吐息，从而在对抗龙类和龙喉氏族的幼龙时提供至关重要的保护。",al={"howin在制作什么护甲","湿地幼龙鳞片护甲","为什么要用幼龙鳞片"}},{q="为什么Howin憎恨黑铁矮人和龙喉氏族？",a="湿地和周围的山脉留下了黑铁氏族和龙喉兽人的深深创伤，这些兽人在第二次战争期间奴役了红龙。Howin痛恨这两个派系以及他们的飞行坐骑，并决心要一雪前耻。",al={"为什么憎恨黑铁和龙喉","howin的敌人","为什么howin憎恨龙喉氏族"}},{q="Howin把迅猛龙门齿变成了什么？",a="锥子是一种细长的尖头手工工具，用于在缝纫前在坚硬的兽皮和皮革上钻孔。通过将完整的迅猛龙门齿安装在手柄上，或者利用它们天然的锥度，Howin制作出了耐用的锥子，能够刺穿龙鳞而不会折断。",al={"什么是锥子","刃喉锥子","迅猛龙牙齿如何用作工具"}}},fp="17,157,20.291.0,16.280.0,38.212.0,50.198.0,39.116.0,55.165.0,49.209.0,46.173.0"}
P.entries["quest:98246"] = {n="Trying Times",s="“Trying Times”是湿地的一项联盟任务，冒险者需要协助矮人霍文·羽言。为了让他那脾气暴躁的狮鹫“低音喙”为接下来的任务做好准备，霍文需要收集十二枚从凶猛的剃刀鳄（Razormaw）迅猛龙那里获得的新鲜蛋。",h="“Trying Times”是湿地的一项联盟任务，冒险者需要协助矮人霍文·羽言。为了让他那脾气暴躁的狮鹫“低音喙”为接下来的任务做好准备，霍文需要收集十二枚从凶猛的剃刀鳄（Razormaw）迅猛龙那里获得的新鲜蛋。",kw={"低音喙","狮鹫","霍文·羽言","恐龙岭","剃刀鳄蛋","盐沫沼泽","trying times","湿地"},ang={["faction:Alliance"]="保持狮鹫的健康对于卡兹莫丹各地的联盟旅行和通讯至关重要，特别是在当地威胁危及区域安全的时候。",["race:Dwarf"]="矮人狮鹫骑士深知，一只脾气暴躁的狮鹫和任何敌人一样危险，因此在起飞前进行适当的喂养和照料是绝对必要的。",["race:Gnome"]="霍文幽默地指出，剃刀鳄迅猛龙蛋的蛋黄有侏儒脑袋那么大，这提供了一个生动但略显不敬的矮人度量衡。"},sec={{t="安抚饥饿的狮鹫",b="在湿地那阴暗辽阔的区域里，维持一匹能用的坐骑需要时刻保持警惕。与他的狮鹫“低音喙”一同工作的矮人霍文·羽言，在没能满足他伙伴那反复无常的胃口之前，绝不肯启程飞行。饥饿的狮鹫顽固、不可预测，而且容易暴起伤人，因此在沼泽地进行任何空中行动前，提供一顿正餐是首要条件。"},{t="剃刀鳄的赏金",b="在湿地，寻找可靠且未受污染的食物变得越来越困难。为了满足“低音喙”，霍文将目标对准了位于东北方向恐龙岭和西北方向盐沫沼泽中的本地剃刀鳄迅猛龙的巢穴。迅猛龙蛋以拥有如侏儒脑袋般大小的蛋黄而闻名，能为“低音喙”在面对该地区危险之前提供所需的充足且未受污染的食物。"}},faq={{q="霍文·羽言是谁？",a="霍文·羽言是一位在湿地照料一只名叫“低音喙”的狮鹫的矮人驯兽师。他派遣冒险者去收集新鲜的迅猛龙蛋来喂养他的伙伴，然后才会实施他的计划。",al={"霍文·羽言是谁","霍文·羽言 湿地","任务发布者 trying times"}},{q="“低音喙”是谁？",a="“低音喙”是霍文·羽言的狮鹫。据霍文所说，它在饥饿时会变得焦躁不安，甚至极度危险，如果不让它吃饱，骑乘或使用它都是不安全的。",al={"谁是低音喙","狮鹫低音喙","霍文的狮鹫"}},{q="霍文为什么需要迅猛龙蛋？",a="霍文专门寻找剃刀鳄迅猛龙蛋，是因为在湿地很难找到未受污染的食物，而这些蛋能提供巨大的、营养丰富的蛋黄，足以满足“低音喙”那惊人的胃口。",al={"为什么要迅猛龙蛋","为什么要喂狮鹫吃蛋","这些蛋是做什么用的"}},{q="在哪里可以找到剃刀鳄迅猛龙？",a="剃刀鳄迅猛龙栖息在湿地东北部的恐龙岭和西北部的盐沫沼泽。冒险者必须亲自深入这些巢穴以获取完好的蛋。",al={"剃刀鳄迅猛龙在哪里","去哪找剃刀鳄蛋","湿地迅猛龙位置"}},{q="为什么这些蛋必须完美无缺？",a="霍文坚持要求蛋不能有任何裂缝或瑕疵，以确保食物完全新鲜且未受污染，这样才能让“低音喙”保持健康和满足，而不是喂给它变质的残渣。",al={"为什么蛋必须完美","破碎的蛋 trying times"}},{q="霍文打算带“低音喙”做什么？",a="霍文提到他有一个涉及“低音喙”的更宏大的计划，但他坚持在狮鹫吃饱并冷静下来，足以在区域威胁中安全飞行之前，不对外透露细节。",al={"霍文的计划是什么","霍文和低音喙打算做什么"}}},fp="12,140,26.252.0,19.298.0,25.150.0,16.139.0,32.153.0,36.146.0,35.109.0,43.133.0"}
P.entries["quest:98247"] = {n="Shipping Label",s="Shipping Label是一个贴在艾泽拉斯贸易局所属补给箱上的已寻回货运标记。它指示信使前往位于赤脊山三角路口的贸易枢纽，并向旅行者介绍了该组织旗下的独立运输商网络。",h="Shipping Label是一个贴在艾泽拉斯贸易局所属补给箱上的已寻回货运标记。它指示信使前往位于赤脊山三角路口的贸易枢纽，并向旅行者介绍了该组织旗下的独立运输商网络。",kw={"艾泽拉斯贸易局","补给箱","货物配送","商人恩惠","赤脊山","shipping label","三角路口"},ang={["faction:Alliance"]="艾泽拉斯贸易局通过三角路口开展业务，依靠南方的联盟领地里的流动冒险者来回收流失货物并保障陆路运输路线的安全。"},sec={{t="流失的货物",b="这张破损的Shipping Label被发现贴在装满货物的补给箱上，标记着属于艾泽拉斯贸易局的货物。尽管预定的目的地和收件人信息已被撕毁，但上面清楚地指示发现货物的人将其送回或向该局位于赤脊山的贸易前哨报告。在正式文本旁边，有一张简陋的地图，勾勒出了通往三角路口交叉点的道路。"},{t="贸易局的枢纽",b="在三角路口的交叉点，艾泽拉斯贸易局的代表会积极招募旅行者成为独立信使。贸易局并不要求运输商签订严格的商业合同，而是运营着一个非正式网络，冒险者可以通过找回丢失的货物并完成沿途遗弃的配送任务来获得“商人恩惠”作为报酬。"}},faq={{q="什么是Shipping Label？",a="Shipping Label是一份在已寻回补给箱侧面发现的破损单据。虽然收件人的名字不见了，但标签上明确了这些货物属于艾泽拉斯贸易局，并指示发现它的人向他们位于三角路口的枢纽报告。",al={"什么是shipping label","shipping label任务","破损的shipping label"}},{q="什么是艾泽拉斯贸易局？",a="艾泽拉斯贸易局是一个负责组织该地区物流、贸易和货运的企业。他们维护着当地的贸易枢纽，用于回收丢失的货物，并雇佣无需长期合同的流动信使。",al={"谁是aca","艾泽拉斯贸易局","什么是艾泽拉斯贸易局"}},{q="艾泽拉斯贸易局的贸易枢纽位于哪里？",a="艾泽拉斯贸易局的贸易枢纽位于赤脊山的三角路口，战略性地坐落在连接艾尔文森林、暮色森林和湖畔镇的道路上。",al={"aca贸易枢纽在哪里","三角路口枢纽","在哪里提交shipping label"}},{q="什么是商人恩惠？",a="商人恩惠是一种由艾泽拉斯贸易局发给独立信使的专用代币或信用额。分支机构成员可以用它购买贸易局前哨提供的各种贸易商品和物流服务。",al={"什么是商人恩惠","商人恩惠","aca报酬"}},{q="如何成为艾泽拉斯贸易局的关联成员？",a="成为关联成员不需要正式合同、文书工作或长期承诺。艾泽拉斯贸易局仅要求信使协助归还或完成在世界各地发现的遗失货物。",al={"如何成为aca关联成员","加入aca","我需要合同吗"}},{q="交付标签后补给箱会怎样？",a="标签本身会促使贸易枢纽的代表询问其所附着的实体补给箱的情况，因为归还空置或已完成运输的货运容器对他们的贸易运作至关重要。",al={"补给箱会怎样","丢失的补给箱","他们需要补给箱吗"}}},fp="14,217,16.375.0,28.340.0,27.244.0,39.198.0,58.168.0,25.189.0,65.209.0,53.185.0"}
P.entries["quest:98248"] = {n="Shipping Label",s="在一个重新补给过的货运箱上发现了一份撕毁的派送单，上面指引信使前往贫瘠之地的一个区域商队枢纽。杜隆塔尔补给后勤部依赖四处游历的旅行者来寻回丢失的板条箱，并将文书送回他们位于十字路口以西的哨所。完成送达任务能够维护卡利姆多中部至关重要的供应链和商业贸易。",h="在一个重新补给过的货运箱上发现了一份撕毁的派送单，上面指引信使前往贫瘠之地的一个区域商队枢纽。杜隆塔尔补给后勤部依赖四处游历的旅行者来寻回丢失的板条箱，并将文书送回他们位于十字路口以西的哨所。完成送达任务能够维护卡利姆多...",kw={"板条箱","十字路口","杜隆塔尔补给后勤部","shipping label","贫瘠之地","贸易哨所"},ang={["faction:Horde"]="穿越贫瘠之地的部落冒险者经常会遇到杜隆塔尔补给后勤部的行动，帮助维护杜隆塔尔与卡利姆多中部之间至关重要的商业和供应线。"},sec={{t="一份迷失的派送单",b="这份撕毁的文件贴在一个刚补给过的货运板条箱上，上面写着杜隆塔尔补给后勤部的物流说明。虽然收件人的名字已经因为旅途磨损而难以辨认，但来源标题清晰地标明了这家在部落领地内运营的货运公司。文字旁边的一张粗略绘制的路线图引导着信使直奔该组织位于中部平原的集结地。"},{t="边境贸易",b="这则告示邀请旅行者将流失的集装箱、损坏的货物或打捞证明运送到他们位于十字路口正西方的贸易哨所。杜隆塔尔补给后勤部在贫瘠之地的严酷环境中运作，非常依赖独立的运输者和路人来寻回散落的货物，并向那些协助保持区域供应渠道顺畅的人提供报酬。"}},faq={{q="什么是Shipping Label？",a="这是一份贴在已补给好的板条箱上的文件，上面详细列出了杜隆塔尔补给后勤部的退还说明，指引丢失或空置的集装箱送回他们靠近十字路口的哨所。",al={"什么是shipping label","shipping label任务","撕毁的shipping label"}},{q="这个标签应该送到哪里？",a="标签指示信使将其交给驻扎在杜隆塔尔补给后勤部贸易枢纽的人员，该枢纽位于贫瘠之地，十字路口的正西方。",al={"shipping label应该送到哪里","谁需要shipping label","shipping label上交"}},{q="什么是杜隆塔尔补给后勤部？",a="杜隆塔尔补给后勤部是一家在杜隆塔尔和贫瘠之地运营的商业货运组织，负责部落领地内的货物运输、板条箱回收和物流支持。",al={"什么是杜隆塔尔补给后勤部","杜隆塔尔补给哨所"}},{q="这批货物最初的收件人是谁？",a="预期收件人的名字已经从标签上完全撕掉了，板条箱上只留下了退还说明和该公司的来源信息。",al={"板条箱原本是给谁的","板条箱收件人"}},{q="杜隆塔尔补给后勤部的贸易哨所在哪里？",a="根据标签上标注的指示和粗略地图，该哨所位于贫瘠之地十字路口定居点的正西方。",al={"贸易哨所在哪里","杜隆塔尔补给点十字路口位置"}},{q="杜隆塔尔补给后勤部会为归还板条箱的旅行者提供补偿吗？",a="是的，印刷的告示明确承诺，信使在将损坏的货物、标签或空板条箱送回枢纽后，其花费的时间和精力将得到补偿。",al={"他们会为归还的板条箱付费吗","杜隆塔尔补给补偿"}}},fp="14,255,18.294.0,17.312.0,27.184.0,36.111.0,37.170.0,45.123.0,64.93.0,76.116.0"}
P.entries["quest:98283"] = {n="Carnage",s="“屠戮者”是湿地的一项任务，由绿带草地的绿色守卫者雷希耶尔委派。雷希耶尔请求旅行者引诱并杀死屠戮者，这是一头疯狂的利刃爪迅猛龙首领，其因瘟疫引发的狂乱扰乱了该地区的自然秩序。",h="“屠戮者”是湿地的一项任务，由绿带草地的绿色守卫者雷希耶尔委派。雷希耶尔请求旅行者引诱并杀死屠戮者，这是一头疯狂的利刃爪迅猛龙首领，其因瘟疫引发的狂乱扰乱了该地区的自然秩序。",kw={"屠戮者","洛克莫丹","恐龙岭","利刃爪","绿色守卫者雷希耶尔","烂爪","绿带草地","湿地"},ang={["class:Druid"]="德鲁伊们对于湿地破碎的自然平衡与雷希耶尔有着同样的悲痛，在那里，疾病已将像屠戮者这样的掠食者扭曲成了毫无理智的恐怖存在。",["class:Hunter"]="猎人们明白，当一个掠食者首领因瘟疫引发的愤怒而丧失其本能，并开始捕食同类时，会构成怎样的危险。"},sec={{t="破碎的平衡",b="在湿地的沼泽中，自然秩序已开始破裂。利刃爪迅猛龙曾经扮演着重要的生态角色，防止荒野过度生长。现在，它们的种群等级被其可怕的首领、那头只被称为“屠戮者”的嗜血野兽所打破。屠戮者非但没有引导种群，反而给自己的同类带来了恐惧，它肆意屠杀，使当地的生态系统陷入混乱。"},{t="引诱首领",b="守护着绿带草地的绿色守卫者雷希耶尔认为，屠戮者已经屈服于依然困扰着该地区的邪恶腐化。为了将这头狂乱的野兽从藏身处引出，旅行者必须收集从洛克莫丹游荡下来的患病烂爪熊的恶性内脏。将这些腐肉放置在恐龙岭下方屠戮者的洞穴巢穴中，会激怒这只怪物发起攻击，从而让旅行者结束它的痛苦。"}},faq={{q="谁是屠戮者？",a="屠戮者是湿地利刃爪迅猛龙群中可怕的首领。这头野兽没有正常地领导它的族群，而是被疾病逼疯，所过之处只留下屠杀，甚至连它的迅猛龙同类都感到恐惧。",al={"谁是屠戮者","屠戮者迅猛龙","什么是屠戮者"}},{q="谁发布了“屠戮者”任务？",a="该任务由绿色守卫者雷希耶尔发布，他是一位驻扎在湿地绿带草地的守卫者，致力于恢复该地区被腐化的自然平衡。",al={"谁发布屠戮者任务","在哪里上交屠戮者任务","雷希耶尔湿地"}},{q="为什么要消灭屠戮者？",a="雷希耶尔寻求屠戮者的死亡，因为这头野兽已被一种非自然的疾病逼疯，破坏了利刃爪迅猛龙的自然等级制度，并摧毁了当地的生态。",al={"为什么要杀死屠戮者","为什么雷希耶尔想让屠戮者死"}},{q="如何引诱出屠戮者？",a="屠戮者是通过用在东北方恐龙岭下方发现的患病熊的恶性肉块和内脏作为诱饵，在其洞穴巢穴中引出的。",al={"如何召唤屠戮者","如何引诱屠戮者","屠戮者的洞穴在哪里"}},{q="雷希耶尔提到的患病熊是什么？",a="这些患病的熊是从洛克莫丹迁移下来的烂爪熊。在挥之不去的腐化影响下变得疯狂，它们被污染的肉体成为了引诱那只疯狂迅猛龙首领的有力诱饵。",al={"什么是烂爪熊","患病的熊来自哪里"}},{q="利刃爪迅猛龙最初在湿地扮演什么角色？",a="在正常情况下，利刃爪迅猛龙通过防止自然动植物过度生长来维持湿地的生态平衡。屠戮者的疯狂破坏了这一至关重要的角色。",al={"利刃爪扮演什么角色","为什么迅猛龙对湿地很重要"}}},fp="7,161,16.216.0,16.305.0,15.159.0,28.147.0,30.161.0,25.128.0,49.162.0,68.187.0"}
P.entries["quest:98286"] = {n="Camping 101: Enchanting",s="《露营指南：附魔》指引奥术修行者前往申达尔村，学习如何制造专业的野外装备。通过与纳萨兰娜·风歌交谈，经验丰富的附魔师可以学会制作一把附魔的鲁特琴，在营火旁娱乐同伴并振奋他们的士气。",h="《露营指南：附魔》指引奥术修行者前往申达尔村，学习如何制造专业的野外装备。通过与纳萨兰娜·风歌交谈，经验丰富的附魔师可以学会制作一把附魔的鲁特琴，在营火旁娱乐同伴并振奋他们的士气。",kw={"营火","露营","露营指南","附魔的鲁特琴","附魔","鲁特琴","纳萨兰娜·风歌","申达尔村"},sec={{t="炉火的慰藉",b="旅途生活需要的不仅仅是锋利的刀刃和口粮；休息和士气对于维持长期的远征至关重要。附魔师为营地生活带来了独特的魔法慰藉，利用他们对周围奥术的精通，在休息时间为旅行者提供精神支持。在艾泽拉斯各地的荒野营地中，附魔师的存在确保了疲惫的冒险者在重返险峻的道路之前，能够恢复体力和精神。"},{t="申达尔之歌",b="想要学习营地制造的精妙魔法，立志成为附魔师的人会被指引前往申达尔村。在那里，纳萨兰娜·风歌会指导合格的施法者制作附魔的鲁特琴。工匠必须首先证明自己在附魔方面的专注和熟练程度，纳萨兰娜才会分享如何制造一种能在星空下编织治愈旋律的乐器的秘密。"}},faq={{q="纳萨兰娜·风歌是谁？",a="纳萨兰娜·风歌是一位居住在申达尔村的导师。她教导熟练的从业者如何为野外营地制作特殊的专业物品，特别是为证明了自己工艺水平的附魔师制作附魔的鲁特琴。",al={"谁教授附魔的鲁特琴","谁是纳萨兰娜·风歌","纳萨兰娜·风歌在哪里"}},{q="申达尔村在哪里？",a="申达尔村是纳萨兰娜·风歌居住的定居点。在掌握了核心技能后，想要学习如何制作附魔的鲁特琴等露营装备的冒险者都会前往那里。",al={"申达尔村在哪里","如何找到申达尔村"}},{q="什么是附魔的鲁特琴？",a="附魔的鲁特琴是由附魔师制作的一种魔法露营乐器。它能在营火旁的休息时间提供娱乐和恢复士气，帮助旅行者调整心态，为面对前方野外的严酷挑战做好准备。",al={"附魔的鲁特琴有什么用","为什么要制作附魔的鲁特琴","露营鲁特琴"}},{q="学习配方有什么要求？",a="在纳萨兰娜·风歌教你如何制作附魔的鲁特琴之前，你必须先证明自己在附魔这一魔法艺术上的造诣。只有经验丰富的从业者才被信任能制作这些营地功能性附魔物品。",al={"露营指南附魔要求","什么时候可以学习附魔的鲁特琴"}},{q="为什么附魔师在野外营地很有价值？",a="附魔师为偏远的营地带来了微妙的实用性和魔法慰藉，因为普通的补给往往难以满足需求。通过为普通的营地工具注入魔法强化，他们帮助冒险者恢复精力、保持娱乐，并为旅途中可能遇到的突发危险做好准备。",al={"为什么露营者需要附魔师","附魔师露营福利"}},{q="其他专业可以制作露营物品吗？",a="是的，各行各业的工匠和采集者都会学习建造专用的露营工具。对于附魔师来说，这种专业的工艺表现为由申达尔村的纳萨兰娜·风歌教授的附魔的鲁特琴。",al={"还有其他露营物品吗","其他专业的营地制作"}}},fp="23,170,22.284.0,20.330.0,28.190.0,26.185.0,26.202.0,46.172.0,52.188.0,42.179.0"}
P.entries["quest:98291"] = {n="Death to the Dragonmaw",s="Howin Kindfeather请你在龙喉营地削弱龙喉兽人的兵力。他希望接近格瑞姆巴托，为蛮锤氏族夺回那里，或是了解更多情况。",h="Howin Kindfeather请你在龙喉营地削弱龙喉兽人的兵力。他希望接近格瑞姆巴托，为蛮锤氏族夺回那里，或是了解更多情况。",kw={"龙喉潜伏者","龙喉兽人","龙喉收复者","龙喉营地","龙喉缚魂者","格瑞姆巴托","howin kindfeather","蛮锤氏族"},sec={{t="龙喉营地",b="龙喉兽人聚集在撤退路线上，红龙曾在这里击溃过他们。Howin必须先削减他们的人数，才能接近格瑞姆巴托。他指给你东边的道路，让你沿路寻找他们。"}},faq={{q="Howin Kindfeather是谁？",a="Howin Kindfeather想重新进入格瑞姆巴托，为蛮锤氏族夺回那里，或者至少了解更多情况。",al={"howin是谁","howin这个人"}},{q="Howin为什么需要帮助？",a="Howin说，龙喉兽人正穿过龙喉营地行进。他必须先削减他们的人数，才能接近格瑞姆巴托。",al={"为什么帮howin","howin需要什么"}},{q="龙喉兽人在哪里？",a="龙喉兽人就在龙喉营地一带。Howin让你沿路向东寻找他们。",al={"龙喉兽人在哪","龙喉兽人位置"}},{q="我该找哪些人？",a="Howin提到了龙喉收复者、龙喉缚魂者和龙喉潜伏者。",al={"哪些兽人","龙喉兽人种类"}},{q="龙喉营地发生过什么？",a="红龙曾在龙喉营地击溃过龙喉兽人。",al={"龙喉兽人历史","为何撤退"}}},fp="22,166,17.202.0,25.120.0,25.131.0,29.98.0,22.84.0,35.66.0"}
P.entries["quest:98293"] = {n="Forced Disarmament",s="Forced Disarmament是湿地的一项联盟任务，要求冒险者从龙喉营地的龙喉氏族手中夺取武器储藏。通过收集三十捆军械，玩家可以阻止这些敌对兽人武装更多士兵用于未来的突袭。缴获的装备会被送往米奈希尔城堡的斯托菲队长处，以保卫该地区至关重要的港口。",h="Forced...",kw={"斯托菲队长","龙喉军械","龙喉氏族","龙喉营地","forced disarmament","米奈希尔港","米奈希尔城堡","湿地"},ang={["faction:Alliance"]="联盟军队将米奈希尔港视为跨越无尽之海的关键生命线，因此解除附近敌对氏族的武装是一项紧急的战略必要。",["race:Dwarf"]="来自铁炉堡的矮人守军负责维持米奈希尔城堡的驻军，致力于保卫卡兹莫丹的边界，防止陷于沼泽中的旧日敌人的侵袭。",["race:Orc"]="龙喉氏族代表了旧部落的一个四分五裂且执迷不悟的残余势力，他们暴力的好战行径使他们与卡利姆多的新部落领导层彻底隔绝。"},sec={{t="沼泽中的军械库",b="在湿地的沼泽地带，敌对的龙喉氏族开始在龙喉营地内囤积惊人数量的武器。如果不加遏制，这些物资将使这些叛变兽人能够武装起一波波新战士，并对邻近定居点发动毁灭性的袭击。解除他们营地的武装是对其后勤能力的直接打击，可以在他们的战团完成动员并走上战场之前，挫败任何预谋的攻势。"},{t="守卫沿海港口",b="米奈希尔港是连接卡兹莫丹、暴风城与海洋的主要门户，因此附近任何军事集结都是严重的威胁。斯托菲队长在米奈希尔城堡协调防御措施，密切监视着入侵城镇的敌对氏族和野兽。回收三十套龙喉军械不仅剥夺了兽人的基本军需品，还能为矮人驻军提供关于敌人准备情况的关键情报。"}},faq={{q="斯托菲队长是谁？",a="斯托菲队长是一位驻扎在米奈希尔城堡的矮人军官，负责保卫米奈希尔港和周边的湿地。面对来自敌对野兽、黑铁矮人破坏者以及龙喉氏族的持续压力，斯托菲积极指挥士兵和冒险者，在港口关键的补给线和港口设施被攻占之前压制附近的威胁。",al={"斯托菲","斯托菲是谁","米奈希尔城堡队长"}},{q="为什么需要解除龙喉氏族的武装？",a="龙喉氏族正在他们的营地中积极囤积武器，以装备新的战斗人员。如果任由他们不受阻挠地囤积军需品，他们的战团可能会压垮当地的联盟防御力量，并危及米奈希尔港。夺取三十捆武器直接阻碍了他们的后勤准备，并阻止更多的兽人士兵走上战场。",al={"为什么要夺取龙喉武器","龙喉军械的目的","解除龙喉武装"}},{q="龙喉营地位于哪里？",a="龙喉营地是龙喉兽人在湿地建立的一处据点，位于米奈希尔港外向东延伸的山脉方向。该氏族利用这一隐蔽的前哨站来集结兵力、储存武器，并对沼泽中的旅行者发动袭击。冒险者必须深入营地中心，回收他们囤积的武器。",al={"龙喉营地位置","龙喉营地在哪里","湿地龙喉营地"}},{q="什么是龙喉军械？",a="龙喉军械是龙喉氏族为了供给战士而锻造或掠夺的战斗装备、刀剑和补给缓存。这些武器代表了该氏族在当地的即时军事实力。斯托菲队长要求没收三十捆这些军需品，并带回米奈希尔城堡进行评估和处理。",al={"龙喉武器","什么是军械","龙喉装备"}},{q="龙喉氏族在25 ADP时是部落的一部分吗？",a="不是，湿地的龙喉氏族是一个独立的敌对派系，不听从萨尔酋长的号令。在第二次战争后，这些兽人依然忠于他们旧有的行事方式，对联盟怀有深仇大恨，并拒绝任何和平提议。因此，联盟守军和独立的旅行者都将他们视为致命的对手。",al={"龙喉氏族属于部落吗","龙喉氏族派系","龙喉萨尔"}},{q="为什么米奈希尔城堡会关注龙喉氏族？",a="米奈希尔城堡是保卫米奈希尔港的行政和军事要塞，而米奈希尔港是联盟在卡兹莫丹的主要海上枢纽。由于港口周边的湿地饱受沼泽野兽和好战兽人的侵扰，斯托菲队长不能允许像龙喉营地这样重装防守的据点在靠近王国码头和贸易路线的地方壮大。",al={"米奈希尔城堡龙喉威胁","为什么斯托菲在意","米奈希尔港防御"}}},fp="18,389,24.469.0,25.479.0,25.398.0,41.365.0,35.362.0,29.356.0,50.362.0,50.382.0"}
P.entries["quest:98297"] = {n="Stopping the Cycle",s="Howin Kindfeather完成试飞归来，带来了令人不安的消息：龙喉术士正在奴役一头红色龙人。蛮锤氏族绝不会让这种事再次发生。",h="Howin Kindfeather完成试飞归来，带来了令人不安的消息：龙喉术士正在奴役一头红色龙人。蛮锤氏族绝不会让这种事再次发生。",kw={"龙喉氏族","龙喉大门","howin kindfeather","红色龙人","终结循环","被制服的龙人","术士","蛮锤氏族"},sec={{t="大门前",b="Howin请你前往龙喉大门，对付那头被制服的龙人。他说，必须先杀死压制它的术士，这样它就能挣脱束缚。之后，你要结束它的痛苦。Howin希望你带上同伴；蛮锤氏族不会让龙喉氏族阻挡他们。"}},faq={{q="谁在请求帮助？",a="Howin Kindfeather请求你阻止龙喉氏族奴役一头红色龙人。",al={"谁需要帮助","howin的任务"}},{q="龙喉氏族在做什么？",a="一群龙喉术士正压制着一头红色龙人，试图奴役它。",al={"龙喉氏族在做什么","龙人为何被制服"}},{q="龙人在哪里？",a="那头被制服的龙人就在龙喉大门。",al={"龙人位置","被制服的龙人在哪里"}},{q="Howin要我做什么？",a="Howin要你杀死压制龙人的术士，然后结束它的痛苦。",al={"我该做什么","终结循环"}},{q="为什么Howin说蛮锤氏族不能容许这种事？",a="Howin说龙喉氏族正在奴役一头红色龙人，并坚称蛮锤氏族绝不会让他们阻挡自己。",al={"为何不能重蹈覆辙","蛮锤氏族的缘由"}}},fp="18,188,12.291.0,23.82.0,29.89.0,25.50.0,29.96.0,52.122.0"}
P.entries["quest:98298"] = {n="Arugal's Folly",s="Arugal's Folly 是银松森林中的一个被遗忘者任务，达拉尔·道恩维沃尔在此调查格雷迈恩之墙附近徘徊的狼人的真正起源。通过分析收集到的狼人残骸，达拉尔试图证明大法师阿鲁高只是一个冒牌货，他仅仅是束缚住了这些生物，而非召唤了他们的诅咒。",h="Arugal's Folly...",kw={"阿鲁高","arugal's folly","达拉尔·道恩维沃尔","格雷迈恩之墙","银松森林","瑟伯切尔","狼人碎片","狼人诅咒"},ang={["class:Mage"]="奥术修行者们可以欣赏达拉尔对阿鲁高所谓魔法诅咒的分析性解构，从而分辨出束缚附魔与传染性苦难之间的区别。",["faction:Horde"]="协助达拉尔·道恩维沃尔的部落冒险者们，帮助保护了银松森林免受猖獗的野蛮掠食者以及正屈服于苦难的邻近人类定居点的侵害。",["race:Undead"]="对于驻扎在瑟伯切尔的被遗忘者来说，理清银松森林中狼人爆发的本质，对于保护洛丹伦免受无法控制的野蛮威胁至关重要。"},sec={{t="揭穿大法师",b="驻扎在银松森林瑟伯切尔的被遗忘者法师达拉尔·道恩维沃尔，试图拆穿他竞争对手大法师阿鲁高的神秘面纱。在检查了附魔枷锁后，达拉尔断定阿鲁高缺乏足以显现或创造出困扰该地区的狼群的原始力量。相反，阿鲁高只是掌握了一些能够暂时束缚住这些野兽的低级附魔，这使得狼人野性传染的真正机制和起源依然是个未解之谜。"},{t="野兽入侵",b="为了寻求实证，达拉尔派遣冒险者前往南方的格雷迈恩之墙那令人生畏的防御工事。在周边的荒野中，凶猛的狼人已经开始攻击并感染附近的人类居民。通过斩杀这些贪婪的生物并取回解剖组织样本，调查员们为达拉尔提供了所需的直接物理标本，以分析这种苦难的生物学和魔法真相。"},{t="苦涩的辩解",b="在检查了收获的狼人残骸后，达拉尔兴高采烈地宣布他在学术声誉上战胜了阿鲁高，证实了这位大法师与苦难的起源毫无关系。然而，这一揭示对被遗忘者来说却带来了一个严峻的后果：如果阿鲁高从未发明过这种诅咒，那么他所制定的所谓补救措施和对策就完全是无用的，这使得狼人爆发的真正谜团依然完全未被解开。"}},faq={{q="谁发布了任务 Arugal's Folly？",a="该任务由达拉尔·道恩维沃尔发布并完成，他是一位驻扎在银松森林瑟伯切尔的奥术研究员兼被遗忘者法师。",al={"谁发布 arugal's folly","在哪里交 arugal's folly","arugal's folly 任务发布者"}},{q="为什么达拉尔·道恩维沃尔认为阿鲁高是个骗子？",a="达拉尔·道恩维沃尔断定大法师阿鲁高是个傲慢的骗子。达拉尔认为，阿鲁高仅仅拥有勉强能暂时束缚住狼人的魔法能力，而非创造或引发它们，从而将所谓的“阿鲁高的诅咒”揭露为一场骗局。",al={"达拉尔如何看待阿鲁高","阿鲁高是否制造了狼人","阿鲁高是骗子"}},{q="在哪里可以找到给达拉尔的狼人碎片？",a="为了完成任务，冒险者们需要向南穿过银松森林前往格雷迈恩之墙，凶猛的狼人就在当地人类定居点附近徘徊。击杀这些野兽即可获得达拉尔调查所需的狼人碎片。",al={"狼人碎片在哪里","格雷迈恩之墙狼人","arugal's folly 去哪里"}},{q="达拉尔找到了治愈狼人诅咒的方法吗？",a="此处并未发现补救方法。由于达拉尔发现阿鲁高最初并未创造出狼人苦难，因此阿鲁高调制的任何补救措施或反制法术都毫无用处，这使得被遗忘者不得不去别处寻找真正的解决方案。",al={"狼人诅咒能治愈吗","阿鲁高的补救措施有效吗","是否有狼人解药"}},{q="狼人的苦难是如何在格雷迈恩之墙附近传播的？",a="达拉尔指出，狼人的苦难似乎并非通过阿鲁高施展的某种宏大的奥术仪式或法术，而是通过身体接触和撕咬直接传播给格雷迈恩之墙附近的人类居民。",al={"诅咒如何传播","狼人传播给人类","谁正在被感染"}},{q="达拉尔在检查了狼人碎片后得出了什么结论？",a="检查被击杀狼人的解剖碎片向达拉尔证明了它们的诅咒与阿鲁高的法术毫无关系。虽然这证实了他竞争对手的魔法无能，但也证实了狼人诅咒仍然是一个活跃的、未被解释的威胁，且没有有效的解药。",al={"达拉尔从碎片中学到了什么","arugal's folly 结论","arugal's folly 剧情揭示"}}},fp="14,206,21.341.0,21.318.0,20.332.1,35.129.0,50.172.0,44.159.0,44.181.0,62.182.0,58.209.0"}
P.entries["quest:98299"] = {n="Stop the Spread",s="“阻止蔓延”是银松森林的一项任务，内容是遏制与大法师阿鲁高有关的狼人诅咒。当研究人员寻求阻止该痛苦的方法时，针对格雷迈恩之墙附近活着的人类难民的先发制人措施已被下达，以防止他们变成阿鲁高的仆从。",h="“阻止蔓延”是银松森林的一项任务，内容是遏制与大法师阿鲁高有关的狼人诅咒。当研究人员寻求阻止该痛苦的方法时，针对格雷迈恩之墙附近活着的人类难民的先发制人措施已被下达，以防止他们变成阿鲁高的仆从。",kw={"阿鲁高","诅咒","被遗忘者","格雷迈恩之墙","难民","银松森林","天降","stop the spread","狼人"},ang={["race:Human"]="聚集在紧闭的格雷迈恩之墙处的未感染人类难民，在被遗忘者研究人员看来是阿鲁高扩散诅咒的主要载体。",["race:Skyborne"]="天降的冒险者在执行格雷迈恩之墙附近的严酷遏制命令时，被直接警告要避免被咬伤。",["race:Undead"]="被遗忘者似乎对狼人痛苦具有独特的免疫力，这使得遏制行动在亡灵部队没有感染风险的情况下变得可行。"},sec={{t="银松森林的痛苦",b="在银松森林，狼人的祸害在叛逃的大法师阿鲁高的手中蔓延。虽然这种野性疾病传播背后的具体方法和机制在很大程度上仍然未知，但它对该领土构成的危险是不可否认的。研究人员正在积极努力了解这种魔法的本质，但他们目前的重点是防止阿鲁高聚集一支无法阻挡的野蛮追随者大军。"},{t="在格雷迈恩之墙的遏制",b="被遗忘者调查人员观察到，他们的亡灵生理结构使他们对狼人感染免疫。然而，活着的人类并没有这种天然的防御能力。在南部的边界，一大群人类难民绝望地聚集在紧闭的格雷迈恩之墙大门周围。由于担心这些毫无防备的幸存者会被咬伤并转化为阿鲁高的忠实奴隶，先发制人且残酷的遏制命令已被下达，要求在痛苦折磨他们之前清除这些聚集的人群。"}},faq={{q="任务“阻止蔓延”是关于什么的？",a="“阻止蔓延”是一项侧重于遏制蹂躏银松森林的狼人诅咒的任务。为了防止大法师阿鲁高获得新的仆从，部队被派遣去消灭格雷迈恩之墙附近的人类难民，以免他们屈服于这种痛苦。",al={"什么是阻止蔓延","阻止蔓延任务背景"}},{q="谁应该为银松森林的狼人负责？",a="大法师阿鲁高被认为应对银松森林内狼人的存在负责，无论是通过他蓄意的阴谋还是他魔法的不可预见后果。他日益壮大的狼群威胁着整个地区。",al={"谁传播了狼人诅咒","阿鲁高狼人关联"}},{q="被遗忘者会感染狼人诅咒吗？",a="根据当地被遗忘者的研究，狼人诅咒无法感染亡灵。这种免疫力使被遗忘者特工能够直面威胁，而不必担心变成阿鲁高的野兽仆从。",al={"被遗忘者能成为狼人吗","亡灵对狼人免疫吗"}},{q="为什么要在格雷迈恩之墙针对人类难民？",a="一大群人类难民聚集在紧闭的格雷迈恩之墙外。因为活着的人类容易受到阿鲁高诅咒的影响，他们被视为壮大狼人队伍的紧迫威胁。",al={"为什么杀害难民","格雷迈恩之墙难民"}},{q="狼人痛苦是如何传播的？",a="虽然已知狼人诅咒可以通过咬伤传播，但其传播的确切魔法和生物学机制仍处于银松森林研究人员的积极调查中。",al={"狼人如何传播","狼人诅咒传播"}},{q="有办法阻止或治愈狼人诅咒吗？",a="目前，尚无已知的治疗狼人痛苦的方法。研究人员正在试图发现一种治疗方法来阻止这种诅咒，但他们的当务之急仍然是积极的遏制。",al={"狼人诅咒能治愈吗","狼人疗法"}}},fp="15,307,25.434.0,23.511.1,40.259.0,48.223.0,40.203.0,59.218.0,38.201.0,48.189.0"}
P.entries["quest:983"] = {n="传声盒827号",s="嗡鸣箱827是侏儒维兹班恩·曲针在黑海岸沿岸建造的一系列实验性通讯中继站中的第一个。这些奇特的机械装置经常发生故障，依靠一种古怪的设计来运作，即利用当地野生动物的身体部位进行现场维修。修复这台沉默的机器可以让维兹班恩直接从奥伯丁测试他的远程语音网络。",h="嗡鸣箱827是侏儒维兹班恩·曲针在黑海岸沿岸建造的一系列实验性通讯中继站中的第一个。这些奇特的机械装置经常发生故障，依靠一种古怪的设计来运作，即利用当地野生动物的身体部位进行现场维修。修复这台沉默的机器可以让维兹班恩直接...",kw={"奥伯丁","嗡鸣箱827","蟹腿","黑海岸","侏儒工程学","礁蟹","潮滩蟹","维兹班恩·曲针"},ang={["profession:Engineering"]="使用有机几丁质和节肢动物的肢体来代替锻造的黄铜齿轮是典型的侏儒式即兴创作，牺牲了耐用性，换取了容易从当地获取的材料。",["race:Gnome"]="维兹班恩的装置代表了经典的侏儒式雄心，试图将技术连接带到一个从未见过电话或无线电的古老、狂野的土地上。",["race:NightElf"]="这些叮当作响、冒着烟的嗡鸣箱是卡利姆多神圣而阴郁的海岸上的一道诡异的风景，尽管奥伯丁的暗夜精灵们容忍了这位技师的实验。"},sec={{t="古老海岸上的侏儒创新",b="在造访奥伯丁期间，古怪的侏儒工程师维兹班恩·曲针试图用一系列被称为“嗡鸣箱”的远程声学中继站，来跨越狂野海岸间的漫长距离。这些装置上布满了操纵杆，专为远距离语音传输而设计，与黑海岸古老的废墟和阴郁的森林形成了鲜明的对比。然而，就像许多雄心勃勃的侏儒发明一样，它们长期处于不稳定状态，需要近乎不断的维护才能让内部齿轮正常运转。"},{t="生态维护",b="维兹班恩没有选择将精炼的铁齿轮和铜销运过荒野，而是采取了一种非传统的解决方案：他将每个嗡鸣箱都设计为使用从附近原生动物身上采集的部件进行维护。嗡鸣箱827位于奥伯丁以南的多雾海岸线上，其工程设计是利用当地潮滩蟹和礁蟹坚固的节肢腿来运作。将蟹腿放入接收料斗中，机器就会自动组装并恢复活力，通过扬声器广播维兹班恩遥远的声音。"}},faq={{q="什么是嗡鸣箱？",a="嗡鸣箱是一种由侏儒维兹班恩·曲针发明的远程语音通讯机器。它配备了操纵杆和内部机械，旨在将声音跨越黑海岸未经开发的广阔区域进行传输，使人们能够在数英里的距离外进行交谈。",al={"嗡鸣箱的作用","嗡鸣箱的目的","黑海岸侏儒装置"}},{q="为什么金属机器需要螃蟹腿来运行？",a="维兹班恩特意将每个嗡鸣箱设计为使用来自周围野生动物的有机部件作为临时替代零件。通过将嗡鸣箱827放置在蟹类栖息的海滩附近，他确保了旅行者可以使用几丁质的肢体代替稀有的机械金属进行紧急机械维修。",al={"为什么用蟹腿","蟹腿修理","为什么喂它腿"}},{q="嗡鸣箱827位于何处？",a="嗡鸣箱827位于黑海岸的海岸线上，就在奥伯丁沿海定居点以南不远处。",al={"嗡鸣箱827位置","嗡鸣箱827在哪里","寻找嗡鸣箱827"}},{q="维兹班恩·曲针是谁？",a="维兹班恩·曲针是一位住在奥伯丁旅店楼上的侏儒技师。他雄心勃勃、富有进取心，尽管他的原型机不断发生故障，但他仍试图在黑海岸建立一个互联的通讯网络。",al={"维兹班恩·曲针","谁制造了嗡鸣箱","奥伯丁侏儒"}},{q="我可以在哪里找到用于维修的蟹腿？",a="蟹腿可以从奥伯丁以南黑海岸海滩的沙地和浅滩上爬行的侏儒潮滩蟹和幼年礁蟹身上收集到。",al={"蟹腿位置","如何获得蟹腿","侏儒潮滩蟹"}},{q="修复嗡鸣箱827后会发生什么？",a="一旦将蟹腿喂入料斗，机器就会将其研磨到位，嗡嗡作响恢复活力，并转播来自奥伯丁的维兹班恩的声音。对成功感到满意的他，会立即要求你前往更远的海岸，去修理链条中的下一个装置——嗡鸣箱411。",al={"嗡鸣箱827之后","嗡鸣箱后续任务","嗡鸣箱827完成"}}},fp="11,235,36.349.0,22.410.0,18.189.0,47.198.0,29.67.0,27.169.0,45.165.0,42.226.1"}
P.entries["quest:98310"] = {n="Gleaning Our Future",s="勘察员维尔加发现了从戈阿兹之石上进一步探究的机会。四个体型更大的魔像刻有铭文，与石头缺失的部分相吻合。",h="勘察员维尔加发现了从戈阿兹之石上进一步探究的机会。四个体型更大的魔像刻有铭文，与石头缺失的部分相吻合。",kw={"ados","gleaning our future","戈阿兹之石","魔像心脏","golm","铭文","modr","neru","勘察员维尔加","湿地"},sec={{t="四处铭文",b="你找到了戈阿兹之石缺失的部分。维尔加指出了四个体型更大的魔像，它们分别名为Ados、Modr、Golm和Neru。他让你在每个魔像附近使用石头，再把它们的心脏带回来，希望能从中发现更多石头上的纹路。"},{t="隐约显现的文字",b="维尔加把心脏靠近戈阿兹之石时，一行新文字在微光中浮现：“血肉诅咒……他们终将失败。”他无法理解这句话的含义，想把石头带到安全的地方进一步研究。"}},faq={{q="维尔加想让我带回什么？",a="维尔加让你在每个魔像附近使用戈阿兹之石，然后带回Ados、Modr、Golm和Neru的心脏。",al={"维尔加想要什么","魔像心脏","带回心脏"}},{q="四个魔像在哪里？",a="Ados位于格瑞姆巴托附近的龙喉大门。Modr就在丹莫德以北。Golm位于格瑞姆巴托地下，在丹奥加兹以东。Neru在恶铁岭东北方的后面。",al={"ados modr golm neru在哪里","魔像位置","在哪里找到魔像"}},{q="维尔加为什么想要魔像的心脏？",a="这些魔像刻有与戈阿兹之石缺失部分相吻合的铭文，维尔加希望它们的心脏能揭示石头上的更多内容。",al={"为什么要心脏","心脏有什么用","戈阿兹之石碎片"}},{q="维尔加怎么看这些魔像？",a="维尔加怀疑这些构造体会比守护者更难对付。",al={"魔像是否强悍","维尔加的警告","魔像实力"}}},fp="19,125,17.250.0,11.239.1,40.112.0,26.188.0,39.134.0,38.64.0"}
P.entries["quest:98313"] = {n="For Further Study",s="史学家卡尼克正在铁炉堡等候一个与史诗之事有关的包裹。目前所见的一切都让进一步研究显得值得。",h="史学家卡尼克正在铁炉堡等候一个与史诗之事有关的包裹。目前所见的一切都让进一步研究显得值得。",kw={"for further study","hall of explorers","史学家卡尼克","铁炉堡","图书馆","维尔加圣物包裹"},sec={{t="卡尼克的图书馆",b="你受托将维尔加圣物包裹交给探险者大厅的史学家卡尼克。他通常在图书馆后面看书。"}},faq={{q="谁在等这个包裹？",a="史学家卡尼克正在铁炉堡探险者大厅等候维尔加圣物包裹。",al={"谁来收取","给谁的包裹"}},{q="我在哪里能找到卡尼克？",a="史学家卡尼克通常在铁炉堡探险者大厅图书馆的后面。",al={"卡尼克在哪里","卡尼克的位置"}},{q="我带着什么包裹？",a="你带着要交给史学家卡尼克的维尔加圣物包裹。",al={"什么包裹","圣物包裹"}},{q="为什么这件事需要进一步研究？",a="文本称此事非同寻常，并说目前所见的一切都让进一步研究显得值得，但没有提供更多细节。",al={"为什么研究","有什么特别之处"}}},fp="17,129,16.139.0,31.83.0,24.96.0,27.64.0,33.123.0"}
P.entries["quest:98319"] = {n="Secure the Mountain",s="“Secure the Mountain”是联盟的一个任务，旨在解决丹莫罗的灰色洞穴中温迪戈突然激增并泛滥成灾的问题。冒险者们需要进入被怪物占据的洞穴，找到一位鲁莽的矮人侦察兵科尼利厄斯，并为白须取回一份重要的报告。",h="“Secure the Mountain”是联盟的一个任务，旨在解决丹莫罗的灰色洞穴中温迪戈突然激增并泛滥成灾的问题。冒险者们需要进入被怪物占据的洞穴，找到一位鲁莽的矮人侦察兵科尼利厄斯，并为白须取回一份重要的报告。",kw={"科尼利厄斯","丹莫罗","灰色洞穴","登山者","secure the mountain","巨魔","温迪戈","白须"},ang={["faction:Alliance"]="确保白须收到情报报告，对于联盟军队维持边境安全以抵御本土山地威胁至关重要。",["race:Dwarf"]="夺回像灰色洞穴这样的洞穴，可以保护矮人登山者和旅行者免受那些侵占丹莫罗道路的温迪戈的伤害。"},sec={{t="泛滥的洞穴",b="驻守在冰冷山坡上的矮人侦察兵们面临着双重威胁。除了时刻存在的霜鬃巨魔威胁外，当地的温迪戈也开始疯狂繁衍，它们放弃了原本孤独的巢穴，成群结队地涌入北边的灰色洞穴。这些野蛮的野兽使山路对于巡逻队和信使来说变得极其危险。"},{t="鲁莽的英勇",b="一位名叫科尼利厄斯的侦察兵一头冲进了灰色洞穴，试图取回一份给白须的重要报告。他这种冲动的英勇行为导致他的同伴被困在外面，只能寻求能干的冒险者进入怪物密布的洞穴，找到那位鲁莽的矮人，并削减凶猛的温迪戈数量。"}},faq={{q="谁是科尼利厄斯？",a="科尼利厄斯是与任务发布者搭档的一名侦察兵或登山者。他因鲁莽的勇气而直接冲进了布满温迪戈的灰色洞穴，将同伴留在外面等待救援，以寻回他本人和白须的报告。",al={"科尼利厄斯是谁","矮人科尼利厄斯","科尼利厄斯在哪里"}},{q="什么是灰色洞穴？",a="灰色洞穴是位于登山者营地北侧的一个洞穴。虽然温迪戈通常只待在深山巢穴中，但最近它们却异常大量地涌入了该洞穴。",al={"什么是灰色洞穴","温迪戈在哪里","丹莫罗温迪戈洞穴"}},{q="为什么温迪戈在扩散？",a="温迪戈通常待在与世隔绝的洞穴里，但当地侦察兵注意到，它们已经开始在冰雪覆盖的山脊上大量繁殖并迅速蔓延，与当地的巨魔威胁一起构成了严重的隐患。",al={"为什么温迪戈在扩散","丹莫罗温迪戈问题","温迪戈像兔子一样繁衍"}},{q="谁是白须，他的报告是什么？",a="白须是一位权威人士或指挥官，正在等待一份关于山区状况的重要侦察报告。科尼利厄斯在鲁莽冲进洞穴之前，正携带着或试图确保这份报告的安全。",al={"谁是白须","白须的报告","森内尔·白须"}},{q="“Secure the Mountain”的目标是什么？",a="这是一项营救和清理任务，要求冒险者进入灰色洞穴，找到失踪的侦察兵科尼利厄斯，并清理洞穴中猖獗的温迪戈。",al={"什么是secure the mountain","secure the mountain任务目标"}},{q="巨魔是如何导致山区麻烦的？",a="当地侦察兵在山峰上已经面临着来自本土霜鬃巨魔的持续压力。突然激增的温迪戈为试图守卫山口的巡逻队制造了危险的双重威胁。",al={"丹莫罗的巨魔","巨魔威胁"}}},fp="19,179,13.227.0,14.179.0,17.179.0,25.147.0,31.167.0,41.112.0,40.92.0,54.139.0"}
P.entries["quest:98321"] = {n="Flintfire's Shipment",s="卡拉诺斯的Tognus Flintfire正面临严重的物资短缺，因为凶猛的温迪戈占领了他主要的矿石来源——灰色洞穴。矿工们在撤离时被迫丢下了装满矿石的板条箱，冒险者们受命找回这些遗失的货物，以维持当地熔炉的运转。",h="卡拉诺斯的Tognus Flintfire正面临严重的物资短缺，因为凶猛的温迪戈占领了他主要的矿石来源——灰色洞穴。矿工们在撤离时被迫丢下了装满矿石的板条箱，冒险者们受命找回这些遗失的货物，以维持当地熔炉的运转。",kw={"丹莫罗","flintfire","熔炉","灰色洞穴","卡拉诺斯","矿工","矿石","货物","tognus flintfire","温迪戈"},ang={["profession:Blacksmithing"]="找回Flintfire的货物对于确保卡拉诺斯的当地熔炉有充足的可加工金属供应至关重要。",["profession:Mining"]="遗失的货物由矿工在温迪戈袭击时撤离主要挖掘点所留下的重要矿石组成。",["race:Gnome"]="Tognus Flintfire特别欢迎愿意在丹莫罗从事繁重体力劳动的侏儒冒险者，并对他们的毅力表示真诚的赞赏。"},sec={{t="卡拉诺斯的物资危机",b="在冰雪覆盖的卡拉诺斯定居点，Tognus Flintfire的熔炉正面临严重的物资危机。在凶猛的温迪戈入侵挖掘现场后，该地区最富产、最可靠的矿石来源突然沉寂了。当地矿工在猝不及防的情况下遭到了这些凶猛捕食者的袭击，被迫立即放弃岗位，四散逃命，留下了散落在洞穴地面上、刚刚打包好的珍贵矿石板条箱。"},{t="深入灰色洞穴",b="这个被占领的矿坑名为灰色洞穴，位于卡拉诺斯以西。虽然Tognus很庆幸所有矿工都从那些凶猛野兽的口中平安逃脱，但停工却威胁到了当地铁匠铺的全面运作。与其等待武装远征队去清理洞穴，Tognus更希望寻求勇敢的冒险者潜入温迪戈的巢穴，收集那些滞留的板条箱，并将至关重要的矿石带回熔炉。"}},faq={{q="Tognus Flintfire是谁？",a="Tognus Flintfire是卡拉诺斯的一名矮人，依靠稳定的矿石运输来维持其熔炉的运作。在温迪戈占领了他主要的采矿洞穴并导致严重的物资短缺后，他招募旅行者去面对危险，取回那些被遗弃的板条箱。",al={"tognus flintfire是谁","tognus flintfire","任务发布者"}},{q="灰色洞穴位于何处？",a="灰色洞穴是位于丹莫罗卡拉诺斯以西的一个洞穴系统。它曾经是一个可靠的采矿点，现在却成了凶猛的温迪戈的巢穴，迫使任何想要寻找遗失矿石的人必须进入这片敌对区域。",al={"灰色洞穴在哪里","灰色洞穴位置","货物在哪里寻找"}},{q="采矿洞穴为何被废弃？",a="在敌对的温迪戈入侵并占领该地点之前，这个洞穴曾是当地矿工最可靠的矿石来源。工人们在绝望的撤离中被迫丢弃了设备和储备的货物，奇迹般地幸存了下来。",al={"矿工为何逃离","矿坑发生了什么","温迪戈袭击"}},{q="丢失的货物里有什么？",a="这些货物由矿工在被驱逐前打包进板条箱的开采矿石组成。没有这些材料，卡拉诺斯的当地金属加工和熔炉作业将陷入停滞。",al={"flintfire的货物是什么","板条箱里有什么","货物内容"}},{q="在袭击中是否有矿工受伤？",a="尽管温迪戈极其凶猛，但Tognus欣慰地表示，所有的矿工都设法平安逃出了灰色洞穴，只留下了他们的补给品和矿石。",al={"矿工生还了吗","矿工伤亡","温迪戈受害者"}},{q="货物被找回后会发生什么？",a="确保找回这些货物，能为Tognus Flintfire提供重启当地熔炉所需的原材料，而无需先清理整个被侵扰的洞穴。",al={"为什么需要矿石","找回后会发生什么","熔炉运转"}}},fp="20,302,27.462.0,31.435.0,24.270.0,34.235.0,34.255.0,37.209.0,42.189.0,46.204.0"}
P.entries["quest:98322"] = {n="Secure the Mountain",s="“Secure the Mountain”是丹莫罗卡拉诺斯的一项联盟任务。一位负责为铁炉堡搜集情报的当地官员在负责调查好斗的温迪戈的侦察兵失联后，派遣冒险者前往镇子西面查看山地巡逻队员格雷琴的情况。",h="“Secure the Mountain”是丹莫罗卡拉诺斯的一项联盟任务。一位负责为铁炉堡搜集情报的当地官员在负责调查好斗的温迪戈的侦察兵失联后，派遣冒险者前往镇子西面查看山地巡逻队员格雷琴的情况。",kw={"丹莫罗","矮人","铁炉堡","卡拉诺斯","山地巡逻队员格雷琴","secure the mountain","温迪戈","白须"},ang={["faction:Alliance"]="协助卡拉诺斯周围的当地矮人巡逻队加强了整个卡兹莫丹冰雪腹地的防御协调。",["race:Dwarf"]="丹莫罗的山地巡逻队员在雪山脊和危险的洞穴中保持着警惕的巡逻，可靠的侦察对于保障矮人定居点的安全至关重要。"},sec={{t="逾期的报告",b="一位卡拉诺斯的官员受命为铁炉堡的High Seat汇编当地的军事情报，但他的日常工作却被打断了。一支被派去评估附近温迪戈活动的山地巡逻队未能带回最新的消息。这位官员没有亲自去钻冰冷的洞穴，而是招募了有能力的旅行者前往镇子西面，去确认侦察兵们的状况。"},{t="西部山脊的麻烦",b="在卡拉诺斯西面找到山地巡逻队员格雷琴后，原本平静的区域监视工作变得令人担忧起来。格雷琴确认她收到了白须的询问，但她透露，周围山岩中的温迪戈骚乱远比最初的报告所显示的更加不稳定，这也为进一步深入附近的荒野进行侦察埋下了伏笔。"}},faq={{q="谁发布了“Secure the Mountain”任务？",a="该任务由卡拉诺斯的森内尔·白须发布，山地巡逻队员格雷琴称他为“老白须”。他的职责包括汇编关于当地荒野威胁的正式报告，并将其发送给铁炉堡的矮人领导层。",al={"谁发布了“secure the mountain”","“secure the mountain”任务发布者","谁开启了“secure the mountain”"}},{q="在哪里可以找到山地巡逻队员格雷琴？",a="山地巡逻队员格雷琴驻扎在丹莫罗的卡拉诺斯镇西面，负责监视附近山坡和洞穴中存在的当地温迪戈威胁。",al={"格雷琴在哪里","山地巡逻队员格雷琴的位置","寻找山地巡逻队员格雷琴"}},{q="任务发布者为什么要寻找山地巡逻队员格雷琴？",a="任务发布者负责将情报送回铁炉堡，但被派去调查当地温迪戈活动的侦察兵没能按时报告。由于进度落后，且为了避免危险的洞穴探索，他请求一位路过的冒险者去查看山地巡逻队员格雷琴的情况。",al={"为什么要派遣冒险者","为什么白须需要帮助","为什么要查看格雷琴的情况"}},{q="什么温迪戈问题正在威胁该地区？",a="温迪戈栖息在卡拉诺斯周围的岩石山脚和黑暗洞穴中。它们咄咄逼人的存在对旅行者和当地哨所构成了直接威胁，促使铁炉堡的侦察兵密切监视它们的动向。",al={"卡拉诺斯的温迪戈威胁","温迪戈在做什么","为什么会出现温迪戈问题"}},{q="抵达后山地巡逻队员格雷琴报告了什么？",a="在镇西找到山地巡逻队员格雷琴后，她确认收到了白须的询问，并严肃地指出，附近温迪戈的整个局势已经变得非常糟糕。",al={"格雷琴说了什么","“secure the mountain”任务交付","格雷琴报告的状况"}},{q="山地巡逻队员在卡拉诺斯周围扮演什么角色？",a="山地巡逻队员是铁炉堡矮人的主要边境守卫、追踪者和侦察部队，他们勘测丹莫罗各处的偏远隘口、黑暗洞穴和雪地小径，以保护像卡拉诺斯这样的城镇。",al={"谁是山地巡逻队员","铁炉堡山地巡逻队","山地巡逻队员的职责"}}},fp="19,263,17.400.0,28.377.1,40.242.0,40.162.0,55.298.0,45.217.0,51.195.0,47.205.0"}
P.entries["quest:98323"] = {n="Secure the Mountain",s="《Secure the Mountain》是一份代表登山者格雷琴递交给卡拉诺斯森内尔·白须的侦察报告。在一次前往附近洞穴的探险遭遇灾难性后果后，格雷琴断定该洞穴已经无法挽回，并拒绝再派遣任何侦察兵进入这个到处都是敌人的死亡陷阱。这项任务突显了铁炉堡的登山者们在日益增长的威胁中保卫丹莫罗安全的持续斗争。",h="《Secure the...",kw={"洞穴","科尼利厄斯","丹莫罗","卡拉诺斯","登山者格雷琴","登山者的报告","secure the mountain","森内尔·白须"},ang={["faction:Alliance"]="确保铁炉堡周围的高海拔山口的安全，对于维护联盟在卡兹莫丹冰雪要塞中的安全通行和防御至关重要。",["race:Dwarf"]="丹莫罗是铜须矮人的祖居之地，这使得登山者格雷琴的顽强坚守成为了一项保护她的族人免受周围威胁的重要努力。"},sec={{t="一份严峻的报告",b="登山者格雷琴驻扎在丹莫罗寒冷的峰顶，肩负着确保高海拔山口安全的职责。然而，最近一次对附近洞穴的突入表明，这片荒野远未平定。在评估了局势后，格雷琴认为该洞穴已经变成了一个彻头彻尾的死亡陷阱，充斥着敌对的怪物。与其冒着牺牲更多生命的风险，她选择坚守在斜坡上的岗位，决心守住防线，同时派遣一名信使去递交她的书面评估。"},{t="深渊中的损失",b="放弃继续深入该洞穴的决定是在付出惨重代价后做出的。在这场失败的侦察行动中，科尼利厄斯不幸遇难，他的牺牲让登山者格雷琴感到沉重。在承认当前条件下无法收复该洞穴后，她下令停止所有对地下隧道的进一步探索任务。她的工作重点从进攻性清理转向了防御性封锁，拒绝再让更多的侦察兵白白牺牲在这些潜伏在雪山峭壁下的凶残生物手中。"},{t="森内尔·白须的档案",b="在繁忙的卡拉诺斯定居点，森内尔·白须追踪着侵扰矮人领地的众多危险。在收到格雷琴那份严峻的评估报告后，白须对于洞穴完全失控的消息并没有感到多少惊讶。他默默接受了丹莫罗所面临的严峻现实，将格雷琴的信件收进了他那堆积如山的实地报告中。这些情报成为了铁炉堡在更广泛地记录和管理动荡边境的过程中，又一份发人深省的资料。"}},faq={{q="登山者格雷琴是谁？",a="登山者格雷琴是一名驻扎在丹莫罗冰雪荒野中的铁炉堡哨兵。她恪尽职守，拒绝在周围领土被判定安全之前离开她的高山岗位。在一次进入附近洞穴的致命侦察任务后，她写下了一份详细描述了敌方重兵把守的正式实地报告，并将其送往卡拉诺斯。",al={"格雷琴","登山者格雷琴背景故事","格雷琴是谁"}},{q="森内尔·白须是谁？",a="森内尔·白须是一位驻扎在卡拉诺斯镇的矮人官员。他负责收集情报并协调丹莫罗各地的本地安全行动，接收来自实地登山者们的派遣报告和侦察评估。当获悉危险的敌军入侵或失陷的洞穴时，他会将这些报告编入正式档案，以评估区域威胁等级。",al={"森内尔·白须","白须 卡拉诺斯","森内尔是谁"}},{q="科尼利厄斯是谁？",a="科尼利厄斯是参与探索山上那处受灾洞穴的一名同僚或侦察兵。登山者格雷琴怀着遗憾提到了他的悲惨命运，表明他是在那次不幸的侦察行动中阵亡的。他的死直接影响了格雷琴将洞穴判定为致命死亡陷阱的决定，并禁止任何人再在里面白白送命。",al={"科尼利厄斯","科尼利厄斯是谁","科尼利厄斯发生了什么","科尼利厄斯 secure the mountain"}},{q="山洞里发生了什么？",a="当侦察兵发现隧道完全被敌对的怪物占领后，对洞穴的探索宣告失败。这次任务导致了科尼利厄斯的悲剧性丧生。在这一严峻的发现之后，登山者格雷琴宣布该地下通道已无法挽回，并断定再派人进入无异于自杀，于是决定封锁或避开该区域。",al={"洞穴里有什么","为什么洞穴是死亡陷阱","洞穴无法挽回"}},{q="为什么格雷琴拒绝离开她的岗位？",a="登山者格雷琴非常重视她保护丹莫罗的誓言，并坚定地声明在山脉本身安全之前，她绝不会放弃自己的阵地。尽管她承认附近的洞穴太过危险而无法夺回，但她依然坚守在白雪皑皑的山巅，守卫着通道并保持警惕，同时将威胁的消息传回卡拉诺斯。",al={"为什么格雷琴要留下来","格雷琴的岗位","为什么要留在山上"}},{q="森内尔·白须对格雷琴的报告有何反应？",a="森内尔·白须对得知洞穴被彻底占领的消息几乎毫不惊讶，这表明这种敌对入侵在丹莫罗已成为太过常见的麻烦。比起表现出震惊，他冷静地接受了这个坏消息，并将格雷琴的书面报告收进他那堆积如山的笔记中，细致地记录着威胁到王国的种种危险。",al={"森内尔的反应","白须对报告的反应","森内尔做什么工作"}},{q="登山者在丹莫罗扮演什么角色？",a="登山者是铁炉堡警惕的边境侦察兵和守卫，在丹莫罗险峻的雪覆盖山峰、高海拔小径和山口进行巡逻。这些坚韧的矮人驻扎在远离温暖首都的地方，监控着敌对野兽的动向，侦察洞穴，并将重要情报传回卡拉诺斯这样的本地枢纽，以保护旅行者和定居点。",al={"铁炉堡登山者","什么是登山者","矮人登山者背景故事"}}},fp="19,408,13.521.0,20.537.1,26.515.0,28.375.0,24.401.0,18.390.0,35.405.0,43.359.0,53.378.0,49.403.0"}
P.entries["quest:98326"] = {n="Frosthowl",s="Frosthowl是丹莫罗的一项任务，要求冒险者从一只偷窃的温迪戈那里找回一袋被偷的鱼。这只野兽伏击了一位当地的矮人渔夫，并逃进了灰色洞穴的深处。",h="Frosthowl是丹莫罗的一项任务，要求冒险者从一只偷窃的温迪戈那里找回一袋被偷的鱼。这只野兽伏击了一位当地的矮人渔夫，并逃进了灰色洞穴的深处。",kw={"丹莫罗","frosthowl","冰冻湖泊","灰色洞穴","冰钓","paxton","被偷的鱼","温迪戈"},ang={["faction:Alliance"]="保护Brewnall和卡拉诺斯附近的冰雪小径和钓鱼点免受凶猛掠食者的侵害，是当地联盟冒险者义不容辞的责任。",["race:Dwarf"]="坚韧的矮人渔夫在丹莫罗的冰冻湖面上忍受着刺骨的严寒，这使得温迪戈的捕食性袭击成为了当地家园定居者和生计时刻面临的威胁。"},sec={{t="被盗的渔获",b="在丹莫罗冰冷的水域进行冰钓是一项艰苦而痛苦的工作。一位矮人渔夫和她的丈夫Paxton在冰封的湖面上冒着刺骨的寒风待了数日，才仅仅收获了一袋鱼。当名为Frosthowl的凶猛且咆哮着的温迪戈袭击营地并抢走他们全部的渔获逃进雪原时，他们的辛苦劳作瞬间化为乌有。"},{t="灰色洞穴中的吵闹鬼",b="Frosthowl并非普通的食腐动物；这头野兽以其震耳欲聋的咆哮声而闻名，这些吼声能震碎冰层并吓跑湖中稀少的鱼群。在抢走渔夫的补给袋后，这只流着口水的生物退回到了位于东南方向的灰色洞穴的黑暗隧道深处，留下了陷入困境的渔夫们，他们迫切希望有人能去对抗这只怪物并取回被盗的物品。"}},faq={{q="Frosthowl是谁？",a="Frosthowl是一只潜伏在丹莫罗的吵闹且极具攻击性的温迪戈。它以咆哮和恐吓冰封的水道而闻名，最近还袭击了一位当地的矮人渔夫，并抢走了她丈夫辛苦捕获的鱼。",al={"关于frosthowl","frosthowl是什么","frosthowl温迪戈"}},{q="在哪里可以找到Frosthowl？",a="Frosthowl躲在灰色洞穴的深处，这是一个位于Paxton捕鱼的冰冻湖泊东南方向的洞穴系统。",al={"frosthowl在哪里","frosthowl位置","温迪戈躲在哪里"}},{q="Frosthowl偷走了什么？",a="Frosthowl伏击了一位矮人渔夫，偷走了一整袋鱼，那是她丈夫Paxton在冰冻湖面上花了几天时间才捕获的。冒险者们受托去猎杀这只野兽并找回被盗的渔获。",al={"frosthowl偷了什么","为什么要击杀frosthowl","温迪戈拿走了什么"}},{q="Paxton是谁？",a="Paxton是一位矮人渔夫，他在冰封的湖面上花了数天时间试图捕获一些鱼。在Frosthowl偷走了他们唯一的一袋鱼之后，他的妻子委托路过的旅行者去追踪这只野兽。",al={"关于paxton","丹莫罗的paxton","渔夫paxton"}},{q="什么是灰色洞穴？",a="灰色洞穴是丹莫罗冰冻湖泊东南方一处已知的温迪戈巢穴，它是像Frosthowl这样的野兽用来囤积腐肉和被盗补给的黑暗巢穴。",al={"什么是灰色洞穴","灰色洞穴温迪戈巢穴","丹莫罗的温迪戈栖息地"}},{q="这头野兽为什么叫Frosthowl？",a="这只温迪戈被称为“吵闹鬼”，它那震耳欲聋的咆哮和嚎叫声在雪原上回荡，吓跑了鱼群，并让任何在冰湖上工作的人感到恐惧。",al={"frosthowl得名原因","为什么叫frosthowl","吵闹的温迪戈"}}},fp="9,205,13.383.0,33.394.0,17.220.0,29.135.0,25.209.0,14.211.0,25.197.0,33.187.0"}
P.entries["quest:98341"] = {n="The Great Windborne Cat Spirit",s="The Great Windborne Cat Spirit是一位来自泽弗拉斯（Zephras）国度的神圣导师，以塞琳南化身（Avatar of Saeyleenan）的形象出现在月光林地。它引导年轻的申多雷（shen'dorei）德鲁伊通过他们的灵性试炼，以便他们能掌握来自遥远故乡的风生猫形态。",h="The Great Windborne Cat Spirit是一位来自泽弗拉斯（Zephras）国度的神圣导师，以塞琳南化身（Avatar of...",kw={"猫形态","猫灵","德鲁伊试炼","月光林地","塞琳南","申多雷","风生猫","泽弗拉斯"},ang={["class:Druid"]="来自泽弗拉斯的德鲁伊通过与风生猫灵沟通来掌握他们的猫科形态，完成一项为他们独特的文化传承量身定制的仪式，而非采用传统的艾泽拉斯之道。",["race:Skyborne"]="被称为申多雷的逐天者德鲁伊在故乡泽弗拉斯的灵体引导下进行修行，而非采用艾泽拉斯本土的形态。"},sec={{t="来自泽弗拉斯的访客",b="在月光林地的神圣庇护所中，一个来自遥远泽弗拉斯国度的灵体出现在双桥南侧。这个自称为塞琳南化身的风生猫灵穿梭来到艾泽拉斯，旨在引导和教导那些准备解锁猫科变形形态的年轻申多雷德鲁伊。"},{t="风生形态的本质",b="虽然所有德鲁伊最终都会寻求猫科形态的智慧，但来自泽弗拉斯的德鲁伊所传承的传统与艾泽拉斯的原住民截然不同。申多雷德鲁伊并非采用艾泽拉斯野生猫科动物的形态，而是化身为他们故乡的风生掠食者。为了确保他们能领悟其灵性本质，塞琳南会亲自监督他们在月光林地的试炼。"}},faq={{q="The Great Windborne Cat Spirit是谁？",a="风生猫灵以塞琳南化身的形象显现，这是一种来自遥远故乡泽弗拉斯的灵体。它来到月光林地是为了教导和考验那些寻求获得其猫科形态的年轻申多雷德鲁伊。",al={"风生猫灵是谁","什么是塞琳南化身","塞琳南背景故事"}},{q="在哪里可以找到塞琳南化身？",a="该灵体的化身出现在月光林地的南部区域，位于双桥正南侧。",al={"月光林地猫灵位置","塞琳南化身所在地","风生猫位置"}},{q="为什么泽弗拉斯的德鲁伊要与不同的猫灵沟通？",a="因为申多雷德鲁伊起源于泽弗拉斯，他们的猫科形态反映的是故乡的风生灵体，而非艾泽拉斯本土的大型猫科动物。该灵体会亲自监督他们的试炼，以确保他们能正确掌握其精髓。",al={"为什么猫形态看起来不同","泽弗拉斯猫形态区别","为什么不用艾泽拉斯猫灵"}},{q="风生猫的试炼包含什么？",a="塞琳南化身会让受试者进行艾泽拉斯巨猫之灵的试炼，同时亲自介入监督，确认德鲁伊能够领悟风生灵体的独特本质。",al={"猫灵给予什么试炼","泽弗拉斯猫灵试炼","如何获得风生猫形态"}},{q="申多雷指的是什么？",a="塞琳南化身将受试者称为申多雷，以此表明他们源自泽弗拉斯，并将他们的传统和灵性习俗与艾泽拉斯的原住民区分开来。",al={"谁是申多雷","申多雷德鲁伊","申多雷是什么意思"}},{q="什么是泽弗拉斯？",a="泽弗拉斯是申多雷遥远的故乡。那里的原生动植物和灵体与艾泽拉斯明显不同，这使得其德鲁伊拥有独特的变形形态。",al={"什么是泽弗拉斯","泽弗拉斯在哪里","泽弗拉斯故乡"}}},fp="30,193,22.262.0,32.302.0,38.177.0,44.87.0,58.213.0,48.192.0,30.176.0,16.170.0"}
P.entries["quest:98362"] = {n="To Thunder Bluff",s="“To Thunder Bluff” 标志着一位年轻的牛头人德鲁伊从月光林地与塞纳里奥议会的交流中凯旋归来。在赢得了 The Great Cat Spirit 的青睐后，这位新学徒回到了长者高地，寻找图拉克·符文图腾，以掌握猫科变形的艺术。",h="“To Thunder Bluff” 标志着一位年轻的牛头人德鲁伊从月光林地与塞纳里奥议会的交流中凯旋归来。在赢得了 The Great Cat Spirit...",kw={"猫形态","德迪利特·星焰","德鲁伊","长者高地","the great cat spirit","月光林地","雷霆崖","图拉克·符文图腾"},ang={["class:Druid"]="这项仪式代表着你捕食本能的解锁，让你能够像图拉克·符文图腾所教导的那样，掌握潜行和利爪的技巧。",["faction:Horde"]="虽然塞纳里奥议会保持中立，但部落的德鲁伊必须回到他们的主城，以确保他们日益增长的力量能够为保卫同胞服务。",["race:Tauren"]="这段旅程强调了牛头人与塞纳里奥传统的重新连接，将来自神圣月光林地的教诲带回了雷霆崖的长者高地。"},sec={{t="从月光林地归来",b="在月光林地的神圣树林中向德迪利特·星焰和 The Great Cat Spirit 证明了自己的见识和价值后，年轻的德鲁伊必须将圣兽的祝福带回莫高雷。与这种原始力量的交流是德鲁伊训练中的一个关键里程碑，它将古老的暗夜精灵教义与牛头人自身的土灵传统联系了起来。"},{t="掌握猫形态",b="图拉克·符文图腾正在雷霆崖的长者高地之巅等待着你的归来。虽然德迪利特促成了你与圣兽本身的交流，但引导身体形态的转变还得依靠图拉克。在 The Great Cat Spirit 的祝福得到认可后，这位老训练师将传授化身为敏捷、捕食性的猫形态所需的神圣知识。"}},faq={{q="这个任务在哪里开始和结束？",a="该任务由月光林地的德迪利特·星焰发布。它指引旅行者回到雷霆崖的长者高地，与图拉克·符文图腾交谈。",al={"交任务的地方","谁发布 to thunder bluff","to thunder bluff 任务交接"}},{q="这个任务的目的是什么？",a="它作为德鲁伊猫之试炼的最终过渡阶段。在月光林地获得 The Great Cat Spirit 的祝福后，新学徒必须回到雷霆崖的导师身边，最终学会如何变身为猫形态。",al={"为什么要做 to thunder bluff","做 to thunder bluff 能得到什么","猫形态任务"}},{q="图拉克·符文图腾是谁？",a="图拉克·符文图腾是一位受人尊敬的牛头人德鲁伊长者，驻扎在雷霆崖的长者高地。他负责监督那些寻求与自然和谐相处并掌握变形形态的部落年轻德鲁伊的训练和入门仪式。",al={"图拉克·符文图腾背景故事","图拉克是谁"}},{q="德迪利特·星焰是谁？",a="德迪利特·星焰是一位隶属塞纳里奥议会的暗夜精灵守护者，他在月光林地的永夜港为到访的德鲁伊提供指导。他不顾阵营间的紧张关系，在古老的卡多雷传统与牛头人修行者之间架起了教义的桥梁。",al={"德迪利特·星焰的作用","月光林地的暗夜精灵"}},{q="The Great Cat Spirit 是什么？",a="The Great Cat Spirit 是一个古老的原始实体，深受德鲁伊的崇敬，它体现了捕食本能、潜行和敏捷。每一位寻求化身为猫形态的德鲁伊都必须通过试炼来赢得它的祝福，并理解它既顽皮又致命的双重本性。",al={"the great cat spirit 背景故事","猫之灵"}},{q="联盟德鲁伊有对应的任务吗？",a="有。暗夜精灵德鲁伊在月光林地进行类似的仪式，他们返回达纳苏斯向自己的导师报告，而不是前往莫高雷那风吹过的平顶山。",al={"to thunder bluff 的联盟版本","暗夜精灵猫形态任务交接"}}},fp="16,225,21.246.0,22.283.0,36.146.0,34.184.0,23.222.0,26.228.0,29.231.0,43.171.0"}
P.entries["quest:98372"] = {n="An Unfortunate End",s="暮色森林的阴影中躺着一名倒下的守夜人，他被一头身份不明的掠食者残忍撕咬。取回他冰冷手指间那支未点燃的火把，便能驱散周围的黑暗，揭示阴影中隐藏的一切。",h="暮色森林的阴影中躺着一名倒下的守夜人，他被一头身份不明的掠食者残忍撕咬。取回他冰冷手指间那支未点燃的火把，便能驱散周围的黑暗，揭示阴影中隐藏的一切。",kw={"不幸的结局","野兽","暮色森林","撕咬","守夜人","火把"},sec={{t="骇人的发现",b="一名倒下的守夜人成员静静躺在暮色森林昏暗的土地上，身上布满了凶猛搏斗留下的严重伤口和撕裂痕迹。这些狰狞的伤口表明，这名巡逻兵还没来得及逃脱，就遭到了一头巨兽的伏击。"},{t="黑暗中的光明",b="倒下的守卫僵硬的手指间紧握着一支未点燃的火把。将火把从他手中取走，便能得到一件对抗不断逼近的阴影的宝贵工具，照出暮色森林的浓重阴霾和其他黑暗小径中隐藏的事物。"}},faq={{q="这是谁的尸体？",a="这具倒下的尸体属于一名守夜人成员。守夜人负责巡逻暮色森林的黑暗道路和边境。这名守卫独自死在阴影之中，遭遇了暴力袭击。",al={"这具尸体是谁的","谁死在这里","死去的守夜人是谁"}},{q="是什么杀死了守卫？",a="他遭到一头大型野兽撕咬，尸体上留下了深深的伤口和狰狞的撕裂痕迹。袭击他的生物在他来得及自卫或照亮道路之前就制服了他。",al={"什么杀死了守夜人","守卫是怎么死的","是什么袭击了他"}},{q="火把为什么重要？",a="从守卫手中取下的未点燃火把可以照亮周围的阴霾，帮助游荡者揭开暮色森林及其外的土地上浓重黑暗所遮蔽的事物。",al={"火把有什么用","火把要怎么用","暮色森林火把用途"}}},fp="18,147,16.143.0,21.149.0,19.124.0,25.134.0,27.126.0"}
P.entries["quest:98386"] = {n="奥瑟尔伐木场",s="奥瑟尔伐木场是赤脊山的一个任务，由湖畔镇的工头奥斯洛提供。工头需要冒险者清除附近伐木场内危险的塔兰图拉毒蛛，以便工人们能安全地取回完成湖畔镇桥梁所需的木材。",h="奥瑟尔伐木场是赤脊山的一个任务，由湖畔镇的工头奥斯洛提供。工头需要冒险者清除附近伐木场内危险的塔兰图拉毒蛛，以便工人们能安全地取回完成湖畔镇桥梁所需的木材。",kw={"奥瑟尔伐木场","桥梁","工头奥斯洛","湖畔镇","伐木场","赤脊山","塔兰图拉毒蛛"},ang={["faction:Alliance"]="重建湖畔镇的基础设施对暴风城王国至关重要，但不断的威胁一直在分散用于桥梁建设的资源。"},sec={{t="木材瓶颈",b="工头奥斯洛为了维持湖畔镇桥梁的维修进度，可谓焦头烂额。面对敌对的黑石兽人、不断逼近的豺狼人部族以及止水湖沿岸好斗的鱼人，他的工人早已精疲力竭。最新的麻烦直接打击了他的供应链：位于东部的奥瑟尔伐木场被巨大的塔兰图拉毒蛛占领，导致该镇桥梁所需的木材供应中断。"},{t="清除虫害",b="伐木场里潜伏着毒蛛，堆积的木材完全无法使用。工头奥斯洛不敢冒险让工人们进入高等塔兰图拉毒蛛的巢穴，于是他雇佣有能力的冒险者去清除这些蛛形纲生物并摧毁它们的卵囊。虽然奥斯洛对奥瑟尔任由伐木场陷入混乱感到不满，但恢复木材供应比任何个人恩怨都更为重要。"}},faq={{q="工头奥斯洛是谁？",a="工头奥斯洛是负责修复和重建湖畔镇桥梁的石匠兼监工。他一直受到当地各种威胁的困扰，这些威胁延误了他的施工进度。",al={"工头奥斯洛是谁","赤脊山工头奥斯洛"}},{q="什么是奥瑟尔伐木场？",a="奥瑟尔伐木场位于赤脊山，湖畔镇以东。它为湖畔镇周边的建筑工程，包括桥梁工程在内，提供至关重要的木材供应。",al={"什么是奥瑟尔伐木场","奥瑟尔伐木场在哪里"}},{q="奥瑟尔是谁？",a="奥瑟尔是湖畔镇东部伐木场的所有者或经营者。据工头奥斯洛所述，奥瑟尔负责管理该场所，但目前他的伐木场已被蜘蛛侵扰。",al={"奥瑟尔是谁","奥瑟尔在哪里"}},{q="工头奥斯洛为什么要清理奥瑟尔伐木场？",a="在塔兰图拉毒蛛侵扰伐木场的情况下，工头奥斯洛无法安全地派遣工人去收集必需的木材。清除蜘蛛并摧毁它们的卵可以确保伐木场安全地恢复桥梁建设所需的木材供应。",al={"为什么要清理奥瑟尔伐木场","为什么要杀赤脊山的蜘蛛"}},{q="什么在侵扰奥瑟尔伐木场？",a="高等塔兰图拉毒蛛和蜘蛛卵囊侵扰了伐木场，这对任何被派去取回木材的工人来说都构成了严重威胁。",al={"奥瑟尔伐木场有什么蜘蛛","赤脊山蜘蛛"}},{q="工头奥斯洛要建造什么桥？",a="工头奥斯洛正在努力重建湖畔镇的桥梁，但他的进度屡屡被敌对的兽人、豺狼人、鱼人以及当地害虫造成的资源短缺所拖延。",al={"赤脊山的桥","湖畔镇大桥"}}},fp="13,164,22.273.0,24.355.0,21.131.0,22.156.0,14.133.0,50.191.0,32.111.0,45.153.0"}
P.entries["quest:98387"] = {n="Blackrock Blockade",s="“黑石封锁”是湖畔镇的治安官马瑞斯发布的一项联盟军事任务。为了应对止水湖东岸不断逼近的黑石兽人，镇卫兵旨在切断入侵者的补给并缴获他们的武器。",h="“黑石封锁”是湖畔镇的治安官马瑞斯发布的一项联盟军事任务。为了应对止水湖东岸不断逼近的黑石兽人，镇卫兵旨在切断入侵者的补给并缴获他们的武器。",kw={"破斧","blackrock blockade","黑石氏族","湖畔镇","治安官马瑞斯","赤脊山","石堡要塞"},ang={["class:Warrior"]="在与粗犷的黑石兽人进行近身遭遇战时，剥夺敌人的重型切肉刀和补给是边境作战的基本原则。",["faction:Alliance"]="从黑石先锋队缴获的每一件武器，都能为湖畔镇争取到宝贵的时间，毕竟这里必须在没有暴风城大量援助的情况下抵御敌军的进攻。"},sec={{t="消耗战",b="尽管黑石氏族已经大举入侵了赤脊山，但他们鲁莽地推进到联盟领土的行为已经让他们的后勤陷入了崩溃的边缘。由于被切断了常规的补给线，他们的先锋作战部队被迫在这片严酷的赤脊山丘陵中寻找生存资源。治安官马瑞斯深知，即使是凶猛的兽人，没有稳定的给养和钢铁武器也无法维持长久的战役。"},{t="切断前沿营地",b="位于石堡要塞南侧的兽人营地是黑石氏族进攻的矛头所在。通过突袭这些营地、搜刮物资储备并夺走他们窃取的武器，联盟守军希望能削弱先遣队的战斗力并摧毁他们的士气。"}},faq={{q="“黑石封锁”的目标是什么？",a="该任务旨在破坏石堡要塞以南黑石氏族的前沿营地。通过突袭他们的补给线、夺取食物并回收武器，湖畔镇守卫希望能断绝兽人的供给，以此减缓他们对赤脊山的攻势。",al={"什么是黑石封锁","黑石封锁目标","封锁目的"}},{q="谁发布了这项任务？",a="治安官马瑞斯，湖畔镇镇守卫的指挥官，负责监督赤脊山的防御并指挥破坏黑石氏族补给的行动。",al={"谁发布黑石封锁","任务发布者","治安官马瑞斯任务"}},{q="这些黑石营地位于何处？",a="目标战营位于赤脊山脉的东部丘陵，就在石堡要塞以南，与湖畔镇隔河相望。",al={"兽人在哪里","黑石营地位置","石堡营地在哪里"}},{q="为什么湖畔镇选择消耗战，而不是直接进攻？",a="湖畔镇守卫人手不足，且几乎没有从暴风城得到增援。这是一场消耗战：黑石兽人鲁莽地深入联盟领土，导致他们陷入了脆弱的境地，补给断绝，只能依赖周围的山区来获取资源，而大军是无法在饥肠辘辘的情况下作战的。",al={"为何饿死兽人","为何不直接攻击石堡","湖畔镇战略"}},{q="哪些武器正从兽人手中没收？",a="治安官马瑞斯希望缴获囤积在黑石营地中的武器和补给，让兽人失去他们的战争工具。",al={"需要什么物品","什么斧头","战损的斧头背景"}},{q="这些兽人是萨尔部落的成员吗？",a="不是。赤脊山的这些黑石兽人属于盘踞在黑石山的叛乱势力——黑石氏族（黑铁氏族/黑石氏族）。他们拒绝萨尔的领导，并且对联盟和新部落都抱有强烈的敌意。",al={"这些是部落兽人吗","黑石是部落吗","萨尔黑石氏族"}}},fp="18,153,18.235.0,26.195.0,43.189.0,27.122.0,46.129.0,67.209.0,49.128.0,46.188.0"}
P.entries["quest:98389"] = {n="A Light in the Darkness",s="这项任务由丧钟镇的Aramis Hammerhand提供，要求被遗忘者冒险者解救困在蛛网洞穴中新复活的亡灵。它突显了那些使用圣光的亡灵与深深不信任他们的民众之间微妙的关系。通过援助他们陨落的同胞，这些圣光修行者希望向希尔瓦娜斯和被遗忘者的大义证明他们的忠诚。",h="这项任务由丧钟镇的Aramis...",kw={"aramis hammerhand","丧钟镇","执行官阿伦","被遗忘者","圣光","蛛网洞穴","提瑞斯法林地","被网住的受害者"},ang={["class:Priest"]="对于引导圣光能量的被遗忘者来说，这项任务说明了在残留的凡人信仰与严酷的亡灵现实之间行走的微妙平衡。",["race:Undead"]="这项任务展示了被遗忘者复杂的内心挣扎，展示了个人如何克服自身刚复活的族群中的偏见。"},sec={{t="摇摇欲坠的信仰",b="圣光对亡灵来说是众所周知的痛苦与危险，然而一些被遗忘者保留了他们生前所使用的神圣魔法的联系。在丧钟镇，像Aramis Hammerhand这样的人物致力于证明他们的信仰并没有让他们背离自己的人民。为了消除人们对圣光修行者会把其他亡灵视为怪物而反戈一击的猜疑，他们积极利用自己的能力和同情心来守护同胞。"},{t="蛛网洞穴",b="在丧钟镇西北方坐落着蛛网洞穴，这是一个阴暗潮湿、爬满凶猛蜘蛛的洞穴。刚刚复活的亡灵，由于苏醒后的迷茫和缺乏自卫的智力，经常误入洞穴，最终被困在粘稠的蛛网中。解救这些不幸的被遗忘者具有双重目的：为黑暗女王挽救新兵，并向执行官阿伦这样的领袖证明，圣光修行者是被遗忘者的忠实仆人。"}},faq={{q="谁给予了任务“A Light in the Darkness”？",a="该任务由驻扎在提瑞斯法林地丧钟镇的圣光修行者Aramis Hammerhand给予。",al={"任务给予者","谁开启a light in the darkness","aramis hammerhand任务"}},{q="蛛网洞穴位于哪里？",a="蛛网洞穴位于提瑞斯法林地的山丘中，丧钟镇的西北方。",al={"蛛网洞穴位置","被蛛网困住的受害者在哪","洞穴在哪"}},{q="为什么被遗忘者不信任圣光的使用者？",a="圣光对亡灵之躯有极大的灼烧感和危险。许多被遗忘者担心任何使用圣光力量的人会将他们视为应当根除的畸形怪物，而不是应当接纳的同胞。",al={"为什么惧怕圣光","为什么被遗忘者讨厌圣骑士","被遗忘者对圣光的恐惧"}},{q="被困在蛛网里的受害者是谁？",a="茧里的受害者是刚刚苏醒、在找到方向前误闯蜘蛛洞穴的被遗忘者冒险者。",al={"谁被网住了","蛛网里有什么","被困的受害者"}},{q="执行官阿伦是谁，为什么Aramis想要打动他？",a="执行官阿伦负责监督丧钟镇的军事和民事秩序。对于希望顺利融入被遗忘者军队的圣光使用者来说，获得他的信任至关重要。",al={"谁是执行官阿伦","为什么阿伦很重要"}},{q="亡灵真的可以使用圣光吗？",a="是的，通过惊人的意志力和虔诚，一些亡灵保留了他们与圣光的联系，尽管引导这种力量会带来巨大的不适，且他们自身的社会也以怀疑的眼光审视他们。",al={"被遗忘者能用圣光吗","亡灵圣光背景故事"}}},fp="23,189,18.325.0,18.357.0,44.90.0,36.80.0,51.122.0,40.117.0,63.152.0,43.170.0"}
P.entries["quest:98391"] = {n="The Sisterhood of Elune",s="The Sisterhood of Elune是一个入门任务，引导冒险者前往达纳苏斯会见艾奎恩妮。作为暗夜精灵社会主要的精神权威，The Sisterhood of Elune需要外界迅速提供援助，以应对领地内日益严峻的挑战。",h="The Sisterhood of Elune是一个入门任务，引导冒险者前往达纳苏斯会见艾奎恩妮。作为暗夜精灵社会主要的精神权威，The Sisterhood of...",kw={"艾奎恩妮","达纳苏斯","艾露恩","女祭司","the sisterhood of elune","泰达希尔"},ang={["class:Priest"]="卡多雷文化中的祭司身份等同于对艾露恩的虔诚，而回应艾奎恩妮则直接与神殿的崇高传统相连。",["faction:Alliance"]="达纳苏斯作为卡利姆多联盟的重要首都，协助The Sisterhood of Elune能确保暗夜精灵精神与公民治理的稳定。",["race:NightElf"]="The Sisterhood of Elune是暗夜精灵社会与领导层的精神核心，对于任何星之子而言，回应她们的召唤是一项神圣的职责。"},sec={{t="首都的召唤",b="“The Sisterhood of Elune”是一份召唤令，指引冒险者前往暗夜精灵的首都达纳苏斯寻找艾奎恩妮。作为艾露恩信徒的代表，女祭司们经常会向可靠的勇士发出呼唤，请他们协助处理影响族人和圣地的紧急事务。"},{t="向艾奎恩妮报到",b="当你抵达达纳苏斯并找到艾奎恩妮后，她会为你如此迅速地赶到而深感欣慰。她的欢迎意味着你正式开始为The Sisterhood of Elune服务，也表明女祭司们正面临日益繁重的需求，需要来自她们隐修圈之外的可靠帮手。"}},faq={{q="艾奎恩妮是谁？",a="艾奎恩妮是服务于达纳苏斯城内The Sisterhood of Elune的一名特使和女祭司。她负责接待那些前来协助教团处理暗夜精灵所面临紧急事务的旅者。",al={"艾奎恩妮是谁","艾奎恩妮 达纳苏斯","艾奎恩妮在哪里"}},{q="什么是The Sisterhood of Elune？",a="The Sisterhood of Elune是一个古老的暗夜精灵女祭司组织，她们致力于侍奉月之女神艾露恩。作为卡多雷文化中的精神向导、治疗者和领袖，她们负责监督族人的精神福祉与防卫工作。",al={"什么是the sisterhood of elune","the sisterhood of elune成员","暗夜精灵女祭司"}},{q="我需要去哪里完成这个任务？",a="你必须前往泰达希尔之上的暗夜精灵伟大首都达纳苏斯。艾奎恩妮会在城中等你，为你传达代表The Sisterhood of Elune的简报。",al={"the sisterhood of elune任务交付","the sisterhood of elune任务地点","the sisterhood of elune去哪接"}},{q="为什么The Sisterhood of Elune需要援助？",a="艾奎恩妮指出，The Sisterhood of Elune需要迅速的外界援助，以应对达纳苏斯及周边暗夜精灵领地所面临的紧迫麻烦。与她交谈将解锁更多代表她们执行的任务。",al={"为什么the sisterhood of elune需要帮助","the sisterhood of elune困境","the sisterhood of elune需要什么援助"}},{q="部落角色可以接受这个任务吗？",a="不能。The Sisterhood of Elune是暗夜精灵领导层的核心，且完全与联盟保持一致。达纳苏斯是联盟首都，因此该任务仅限联盟冒险者接取。",al={"部落能接这个任务吗","部落能否完成the sisterhood of elune"}},{q="谁领导着The Sisterhood of Elune？",a="泰兰德·语风大祭司是The Sisterhood of Elune的精神领袖，也是卡多雷民族的最高统帅，她在达纳苏斯的Temple of the Moon指引着她的姐妹们。",al={"谁领导the sisterhood of elune","the sisterhood of elune领袖","泰兰德 the sisterhood of elune"}}},fp="23,262,21.297.0,27.292.0,22.215.0,32.239.0,45.187.0,36.224.0,42.189.0,34.199.0"}
P.entries["quest:98392"] = {n="Darkness in the Glade",s="Darkness in the Glade是由哨兵阿瑞尼亚·碎云领导的一项调查，旨在调查从神谕林地的鸟身人身上收集到的受污染的皮带。从鸟身人女族长身上找回的护身符证实，恶魔般的魔苔腐蚀已经在泰达希尔的枝干中扎根。",h="Darkness in the Glade是由哨兵阿瑞尼亚·碎云领导的一项调查，旨在调查从神谕林地的鸟身人身上收集到的受污染的皮带。从鸟身人女族长身上找回的护身符证实，恶魔般的魔苔腐蚀已经在泰达希尔的枝干中扎根。",kw={"阿瑞尼亚·碎云","arysa","darkness in the glade","魔苔","gaedress","鸟身人","hatescreech","神谕林地","泰达希尔"},ang={["class:Druid"]="魔苔污染野生动物和皮革纤维的迹象表明，一种非自然的腐蚀正在影响世界之树的自然平衡。",["faction:Alliance"]="哨兵碎云代表了达纳苏斯的军事警惕，致力于识别威胁联盟领土的恶魔污染。",["race:NightElf"]="邪能腐蚀通过神谕林地等神圣枝干的蔓延，直接打击了卡多雷培育和保护泰达希尔的努力。"},sec={{t="受污染的纤维",b="在神谕林地宁静的树冠下，哨兵阿瑞尼亚·碎云注意到当地的鸟身人族群有些不对劲。从这些生物身上回收的皮带显示出一种直接编织在材料中的非自然污秽。碎云怀疑这不是普通的野兽侵略，而是恶魔入侵，因此在向达纳苏斯发出警报之前，她需要确凿的证据。"},{t="确认腐蚀",b="碎云指挥勇士们前往西部的巢穴，击败了该族群的女族长：Hatescreech、Windmistress Gaedress和Witchmother Arysa。每一位领袖都携带一枚带有其力量明显痕迹的护身符。在检查这些石头时，哨兵发现宝石中包裹着邪恶的绿色旋涡，这证实了魔苔正在积极地扭曲鸟身人，并渗入神圣的枝干中。"}},faq={{q="Darkness in the Glade是什么？",a="Darkness in the Glade是由哨兵阿瑞尼亚·碎云在神谕林地指挥的一项任务。在注意到鸟身人皮带中存在非自然的污秽后，她派遣冒险者从鸟身人领袖那里找回护身符，以核实这种折磨的来源。",al={"darkness in the glade是什么","darkness in the glade任务"}},{q="谁提供了这个任务？",a="哨兵阿瑞尼亚·碎云提供了这项任务。她驻守在神谕林地，守护着泰达希尔的枝干，并调查居住在那里的鸟身人之间出现的异常骚动。",al={"谁发布了darkness in the glade","神谕林地任务发布者"}},{q="为什么阿瑞尼亚想要鸟身人领袖身上的护身符？",a="哨兵碎云在从普通鸟身人身上获取的皮带中发现了受污染的纤维，因此需要进一步的证据。她怀疑鸟身人领袖所携带的珠宝揭示了这种蔓延的腐蚀的真实性质和起源。",al={"为什么要击杀鸟身人领袖","为什么要获取护身符","鸟身人护身符的原因"}},{q="哪些鸟身人领袖持有护身符？",a="这些护身符属于筑巢于西部的三位杰出领袖：Hatescreech、Windmistress Gaedress和Witchmother Arysa。",al={"哪些鸟身人持有护身符","神谕林地的鸟身人领袖"}},{q="是什么导致了林地中的腐蚀？",a="这种腐蚀源于魔苔。当阿瑞尼亚检查找回的护身符时，她识别出宝石中邪恶的绿色旋涡，确认魔苔正在污染该地区。",al={"是什么在腐蚀鸟身人","绿色旋涡是什么","林地黑暗的起源"}},{q="这种腐蚀是否出现在其他地方？",a="是的，哨兵碎云指出，有报道称魔苔正在使环境变得对暗夜精灵不利，这种情况也出现在幽影谷以及世界之树的其他枝干上。",al={"其他地方的魔苔","幽影谷是否受到腐蚀"}}},fp="21,142,14.262.0,18.295.1,30.187.0,21.158.0,52.161.0,37.112.0,44.147.0,43.136.0"}
P.entries["quest:98393"] = {n="The Great Cat Spirit",s="The Great Cat Spirit 是一项神圣的德鲁伊任务，召唤修行者前往月光林地的永夜港，去见德迪利特·星焰。在已经掌握了熊的形态之后，德鲁伊们受到召唤，要在塞纳留斯大人的祝福下，开始他们探索荒野中猫之视角的旅程。",h="The Great Cat Spirit...",kw={"猫之形态","塞纳留斯","德迪利特·星焰","德鲁伊训练","月光林地","永夜港","the great cat spirit"},ang={["class:Druid"]="这次召唤标志着德鲁伊在熊之外扩展对荒野形态掌握能力的重要试炼。",["race:NightElf"]="月光林地是卡多雷德鲁伊回应塞纳留斯所传授的古老教诲的祖地。",["race:Tauren"]="牛头人德鲁伊在塞纳里奥议会的共同指导下，与他们的暗夜精灵同胞一同自由前往永夜港。"},sec={{t="月光林地的召唤",b="在证明了自己已经掌握了持久的熊之形态后，心怀抱负的德鲁伊们发现自己再次受到了召唤，前往神圣的月光林地。德迪利特·星焰长老向这片土地发出了呼唤，邀请弟子们来到宁静的避风港——永夜港，开始他们与自然融合的下一阶段。德鲁伊们施展独特的精神魔法跨越遥远的距离，聚集在塞纳里奥智慧那宁静的核心之地。"},{t="猫之视角",b="当你抵达永夜港后，德迪利特·星焰会向塞纳留斯大人祈祷，在欢迎这位日益成长的弟子时，召唤出一道微弱的力量光环。他揭示了拥抱猫之视角的时刻已经到来，这是一种荒野中富有掠食性和敏捷性的形态。正如之前的试炼一样，德迪利特将开启理解之路，但具体如何去体现并传承这种猫之精神，则完全取决于修行者自己。"}},faq={{q="是谁在 The Great Cat Spirit 中召唤你？",a="你的德鲁伊训练师代表德迪利特·星焰召唤你，他是一位驻扎在月光林地隐秘避风港——永夜港的长老导师。",al={"谁给予 the great cat spirit 任务","德迪利特·星焰召唤"}},{q="德迪利特·星焰在哪里？",a="德迪利特·星焰居住在月光林地的中心定居点永夜港，可以通过德鲁伊的传送魔法到达。",al={"德迪利特·星焰在哪里","德迪利特·星焰位置"}},{q="面见德迪利特·星焰的目的是什么？",a="德迪利特准备引导你与自然的猫之形态进行沟通并加以理解，在你学习了熊之道后，继续你的精神进阶。",al={"德迪利特教授什么","猫形态训练任务"}},{q="为什么德迪利特要祈求塞纳留斯大人？",a="德迪利特在迎接你时祈求塞纳留斯大人，以此向这位半神，也是最初教导凡人自然与变形秘密的德鲁伊教派守护者表达敬意。",al={"为何提到塞纳留斯大人","塞纳留斯提及德迪利特"}},{q="德鲁伊如何为这项召唤前往月光林地？",a="每当导师召唤时，德鲁伊们会利用他们与自然沟通的天生精神能力，直接传送至月光林地。",al={"如何前往月光林地","德鲁伊传送至月光林地"}},{q="这种形态与熊之形态有何关联？",a="德鲁伊教义通过不同的视角来接触自然。新手首先要掌握熊那持久的力量，然后再进阶到猫那敏捷的掠食者心态。",al={"猫形态与熊形态背景故事","先学熊形态"}}},fp="20,187,24.264.0,26.323.0,42.120.0,38.109.0,50.116.0,41.137.0,51.93.0,47.162.0"}
P.entries["quest:98397"] = {n="To Darnassus",s="To Darnassus 是暗夜精灵德鲁伊与 The Great Cat Spirit 沟通之旅的终点。在月光林地向德迪利特·星焰证明了自己之后，你将被送回塞纳里奥区，学习掌握变身为猎豹形态的技艺。",h="To Darnassus 是暗夜精灵德鲁伊与 The Great Cat Spirit 沟通之旅的终点。在月光林地向德迪利特·星焰证明了自己之后，你将被送回塞纳里奥区，学习掌握变身为猎豹形态的技艺。",kw={"猎豹形态","塞纳里奥区","德迪利特·星焰","great cat spirit","玛斯雷·驭熊者","月光林地","泰达希尔","to darnassus"},ang={["class:Druid"]="这个任务标志着你开始在阴影中狩猎，使你能够通过猎豹形态直接引导 The Great Cat Spirit 的力量。",["faction:Alliance"]="联盟德鲁伊从月光林地的中立领土返回达纳苏斯，加强了他们家园的魔法防御。",["race:NightElf"]="返回达纳苏斯是对世界之树泰达希尔下由塞纳里奥议会所守护的暗夜精灵传统的致敬。"},sec={{t="返回塞纳里奥区",b="在月光林地接受德迪利特·星焰的指引并与 The Great Cat Spirit 沟通后，有抱负的暗夜精灵德鲁伊必须回到泰达希尔。星焰承认你已经证明了自己是一名合格的学生，并指引你回到你的首席导师玛斯雷·驭熊者身边，他正在达纳苏斯的塞纳里奥区树荫下等你。"},{t="猎豹的本性",b="抵达达纳苏斯后，玛斯雷·驭熊者承认你已经领悟了 The Great Cat Spirit 的智慧。在他看来，每一代德鲁伊都要面对由这个古老实体所设定的试炼，它既顽皮又致命。随着你与它的连接建立，你的精神也已准备就绪，玛斯雷将传授你变身为优雅猎豹形态所需的最终仪式。"}},faq={{q="这个任务的目的是什么？",a="这个任务结束了你与 The Great Cat Spirit 的试炼。在月光林地完成德迪利特·星焰交给你的任务后，他会指引你回到达纳苏斯的玛斯雷·驭熊者身边，让他教你如何变身为猎豹形态。",al={"为什么要做这个任务","to darnassus 目的","猎豹形态任务"}},{q="是谁让你回到达纳苏斯的？",a="德迪利特·星焰是一位居住在月光林地圣地永夜港的资深德鲁伊，在你获得 The Great Cat Spirit 的祝福后，他会交给你这个任务。",al={"谁开始这个任务","任务给予者"}},{q="我在哪里可以找到玛斯雷·驭熊者？",a="玛斯雷·驭熊者驻扎在塞纳里奥区，这是位于泰达希尔上达纳苏斯西北区的德鲁伊圣所。",al={"玛斯雷位置","驭熊者在哪里"}},{q="The Great Cat Spirit 有什么意义？",a="The Great Cat Spirit 是一种古老而野性的自然之灵，代表着敏捷而致命的掠食者。德鲁伊必须在获准引导其形态之前，赢得它的青睐，并理解它那顽皮与致命并存的双重本性。",al={"猎豹之灵传说","什么是 great cat spirit"}},{q="所有德鲁伊完成的试炼都是一样的吗？",a="根据玛斯雷·驭熊者的说法，虽然所有德鲁伊都必须通过 The Great Cat Spirit 授予的试炼才能掌握其形态，但每一代试炼的具体内容各不相同。",al={"德鲁伊试炼是否相同","世代试炼"}},{q="非暗夜精灵可以接这个任务吗？",a="这个特定的任务是为返回达纳苏斯的联盟暗夜精灵德鲁伊准备的。牛头人德鲁伊遵循他们自己的道路，在访问月光林地后会向他们自己的训练师汇报。",al={"这是联盟专属吗","牛头人能做吗"}}},fp="12,205,21.309.0,21.309.0,34.201.0,32.138.0,39.103.0,49.198.0,44.150.0,36.174.0"}
P.entries["quest:98398"] = {n="The Oracle Tree",s="The Oracle Tree是一个任务，在该任务中，一名有前途的冒险者被指引去与一棵有感知力的古树进行交流。通过寻找这棵树刻意脱落的一块树皮，旅行者们可以收到它令人舒心的心灵感应信息，并为即将到来的更艰巨的任务做好准备。",h="The Oracle...",kw={"oracle tree","oracle tree树皮","有感知力的树","脱落的树皮","心灵感应","the oracle tree"},ang={["class:Druid"]="德鲁伊天生就能与有感知力的植物生命和古树的声音产生共鸣，使得与The Oracle Tree的交流成为他们对自然崇敬的一种延伸。"},sec={{t="召唤更伟大的使命",b="The Oracle Tree是一棵睿智且有感知力的树，它守护着周围的环境，并指引那些证明了自己的勇气的旅行者。当它在世界上需要代理人时，它会特意在附近脱落一片树皮。注意到这一点的人会被召唤上前，这标志着他们初步的任务已经完成，更伟大的责任正在等待他们。"},{t="通过树皮进行心灵沟通",b="The Oracle Tree不会用普通的物理声音说话。相反，检查那片落下的树皮可以让这棵树直接触及寻求者的心灵。它的存在平静而舒缓，像微风拂过树冠一样拂过听者的心灵，无需说出一个字就能传达思想和愿望。"}},faq={{q="什么是The Oracle Tree？",a="The Oracle Tree是一棵古老且有感知力的树，能够与附近的人进行心灵感应交流。当它希望传达信息或分配任务时，它会脱落一块树皮来吸引值得信赖的冒险者的注意。",al={"什么是oracle tree","oracle tree背景故事"}},{q="The Oracle Tree如何交流？",a="The Oracle Tree不是用可听见的声音说话，而是通过心灵感应来传达它的思想。任何检查掉落树皮的人都会听到一个平静、舒缓的声音进入他们的脑海，就像微风拂过树叶一样。",al={"oracle tree如何说话","oracle tree交流方式"}},{q="为什么要寻找The Oracle Tree的树皮？",a="当树有需要处理的目标或职责时，它会专门脱落一片树皮。检查树皮是接收这棵树心灵感应指导的焦点。",al={"为什么要寻找树皮","掉落树皮的目的"}},{q="是谁指引你前往The Oracle Tree？",a="一位一直在观察你成就的当地监督者或看护人，他们意识到未来有更伟大的职责等着你。注意到刚脱落的树皮，他们会指引你接近这棵树以接受它的指导。",al={"谁指引你去oracle tree","oracle tree任务发布者"}},{q="任务“The Oracle Tree”的目的是什么？",a="该任务开启了一名有成就的旅行者与这棵树本身之间的接触。通过寻找树皮，你开启心灵去倾听树的信息，并了解它需要完成什么更伟大的任务。",al={"oracle tree任务目标","oracle tree想要什么"}},{q="在哪里可以找到The Oracle Tree的树皮？",a="脱落的树皮位于The Oracle Tree附近的地面上，等待着感知力足够敏锐、能听到其信息的人去检查。",al={"在哪里找到oracle树皮","树皮位置"}}},fp="15,181,24.291.0,26.219.0,24.202.0,37.174.0,47.141.0,35.166.0,49.157.0,36.112.0"}
P.entries["quest:984"] = {n="熊怪的威胁",s="“威胁有多大？”是一个由奥伯丁的特伦希斯给予联盟的任务。在目睹了熊怪的疯狂在泰达希尔蔓延后，这位暗夜精灵德鲁伊派遣斥候调查黑海岸当地的熊怪定居点，以确认这种同样的黑暗腐蚀是否已经跨越了海洋。",h="“威胁有多大？”是一个由奥伯丁的特伦希斯给予联盟的任务。在目睹了熊怪的疯狂在泰达希尔蔓延后，这位暗夜精灵德鲁伊派遣斥候调查黑海岸当地的熊怪定居点，以确认这种同样的黑暗腐蚀是否已经跨越了海洋。",kw={"亚米萨兰","奥伯丁","腐蚀","黑海岸","熊怪","泰达希尔","特伦希斯","威胁"},ang={["class:Druid"]="熊怪与自然和古老的荒野之灵有着深刻的联系，这使得他们突然陷入腐蚀成为致力于修复卡利姆多平衡的德鲁伊们极度担忧的问题。",["faction:Alliance"]="作为联盟进入卡利姆多北部大陆的主要门户，保护奥伯丁免受旷野威胁对于地区安全和后勤保障至关重要。",["race:NightElf"]="对于卡多雷来说，目睹像熊怪这样古老的盟友在第三次大战争后不久就屈服于非理性的黑暗，既是一场痛苦的悲剧，也是对神圣土地的迫在眉睫的危险。"},sec={{t="跨海阴影",b="卡利姆多北部的暗夜精灵长期以来一直与当地的熊怪部落保持着友好或和平的关系。然而，第三次大战争之后，某种奇怪的腐蚀开始侵蚀泰达希尔熊怪的心智，导致他们对曾经的盟友进行暴力绑架和野蛮攻击。驻扎在奥伯丁的德鲁伊特伦希斯担心，这种险恶的折磨并非仅限于世界之树，而是正在黑海岸迷雾笼罩的海岸线上，在大陆部落中积极蔓延。"},{t="风暴前夕",b="对亚米萨兰遗迹附近一个熊怪营地的侦察证实了特伦希斯最糟糕的怀疑。那里的熊怪表现出反复无常、充满敌意的侵略性，带有与困扰北方地区相同的腐蚀迹象。他们距离奥伯丁非常近，这使得他们从一个和平的旷野邻居，变成了一个威胁到联盟定居点的紧急防御隐患。"}},faq={{q="特伦希斯是谁？",a="特伦希斯是一位驻扎在沿海避风港奥伯丁的暗夜精灵德鲁伊。由于泰达希尔各地不断传来暗夜精灵遭到疯狂熊怪袭击和俘虏的消息，他致力于监控并压制整个黑海岸出现的威胁。",al={"特伦希斯 任务给予者","谁给予 威胁有多大","特伦希斯 奥伯丁"}},{q="为什么黑海岸的熊怪变得充满敌意？",a="特伦希斯已经在黑海岸看到了腐蚀的迹象，并怀疑熊怪可能受到了影响，就像泰达希尔的一些熊怪一样。他要求对这些营地进行调查，因为他还没有掌握到广泛传播的证据。",al={"为什么熊怪发狂","黑海岸受腐蚀的熊怪","熊怪腐蚀"}},{q="受腐蚀的熊怪营地在哪里？",a="营地位于黑海岸中部内陆，就在古老的上层精灵遗迹亚米萨兰的北面，奥伯丁的东南方。",al={"营地位置","熊怪营地在哪里","威胁有多大 位置"}},{q="这与泰达希尔发生的事件有什么联系？",a="在泰达希尔，几只受腐蚀的熊怪绑架并伤害了暗夜精灵哨兵和平民。特伦希斯在寻求确认黑海岸大陆是否面临同样的危机时，提到了那些最近的救援行动。",al={"泰达希尔的联系","泰达希尔熊怪","为什么特伦希斯提到泰达希尔"}},{q="向特伦希斯汇报后会发生什么？",a="向奥伯丁的特伦希斯报告任何腐蚀迹象。你返回后，他会揭晓对调查结果的回应。",al={"后续任务","威胁有多大的后续","任务延续"}},{q="为什么暗夜精灵如此担心奥伯丁附近的熊怪营地？",a="奥伯丁是联盟在大陆上的主要港口和补给生命线。如果深陷腐蚀、充满敌意的部落驻扎在触手可及的地方，贸易道路、侦察小队和城镇本身都将变得极易受到突然袭击。",al={"对奥伯丁的威胁","为什么关心熊怪"}}},fp="17,227,22.371.0,17.273.1,17.194.0,50.218.0,42.132.0,45.202.0,47.96.0,68.180.0"}
P.entries["quest:98403"] = {n="Twisted Hatred",s="Twisted Hatred是泰达希尔的一个任务，旨在揭露梅伦纳斯领主背后的操纵者。冒险者们前往多兰纳尔西北方的大断崖，去直面邪恶的塞索尔，并在他那邪恶的阴谋蔓延至树冠之前消灭他那些被腐化的蜘蛛。",h="Twisted Hatred是泰达希尔的一个任务，旨在揭露梅伦纳斯领主背后的操纵者。冒险者们前往多兰纳尔西北方的大断崖，去直面邪恶的塞索尔，并在他那邪恶的阴谋蔓延至树冠之前消灭他那些被腐化的蜘蛛。",kw={"被玷污的蛛木蜘蛛","大断崖","多兰纳尔","梅伦纳斯领主","成熟的魔苔","萨特","塔隆凯·捷根","泰达希尔","twisted hatred","邪恶的塞索尔"},ang={["class:Druid"]="泰达希尔的自然蛛形纲生物被扭曲成污秽的巢群，这破坏了自然平衡，需要塞纳里奥保卫者们将其净化。",["faction:Alliance"]="协助塔隆凯·捷根可以保护多兰纳尔定居点，使其免受萨特阴谋在联盟位于卡利姆多的主要避难所中的蔓延。",["race:NightElf"]="泰达希尔是卡多雷复兴的新生心脏，大断崖本土野生动物中滋生的恶魔腐化，是对你们族人的直接侮辱与威胁。"},sec={{t="阴影中的操纵者",b="梅伦纳斯领主并非孤身一人行事的发现，揭示了泰达希尔荒野下涌动着更黑暗的暗流。在梅伦纳斯的身后站着邪恶的塞索尔，这位盘踞在此的萨特在森林的阴影中操纵着一切，企图破坏世界之树宁静的枝叶。"},{t="大断崖的污秽巢群",b="邪恶的塞索尔在多兰纳尔西北方一处名为大断崖的隐秘飞地中安身，并将注意力转向了泰达希尔本土的蛛形纲生物。通过将当地的蛛木蜘蛛扭曲成污秽的野兽，这名萨特试图将它们的毒液武器化，用于险恶的恶魔阴谋。塔隆凯·捷根派遣冒险者去猎杀这些巢群，并在腐化进一步蔓延之前夺取塞索尔手中的成熟的魔苔。"}},faq={{q="谁是邪恶的塞索尔？",a="邪恶的塞索尔是一名邪恶的萨特，他在泰达希尔策划着腐化。他指挥着梅伦纳斯领主，并将巢穴设在大断崖，通过扭曲本土蜘蛛并利用成熟的魔苔来包藏他险恶的阴谋。",al={"谁是塞索尔","邪恶的塞索尔","谁是那个萨特"}},{q="大断崖位于何处？",a="大断崖是泰达希尔上多兰纳尔西北方森林深处的一处隐秘区域，邪恶的塞索尔和他的污秽巢群就栖居于此。",al={"大断崖在哪里","大断崖位置","在哪里找到塞索尔"}},{q="为什么泰达希尔的蜘蛛会被玷污？",a="被玷污的蛛木蜘蛛是泰达希尔本土的蜘蛛，它们被邪恶的塞索尔所腐化。这名萨特扭曲了它们的心智和生理结构，意图收集它们的毒液来执行一个肮脏的恶魔计划。",al={"为什么蜘蛛会变异","什么是被玷污的蛛木蜘蛛","被玷污的蛛木蜘蛛背景"}},{q="谁是塔隆凯·捷根？",a="塔隆凯·捷根是一名驻扎在泰达希尔多兰纳尔村的暗夜精灵守卫，他会委派冒险者去铲除周围森林中的恶魔颠覆活动。",al={"谁发布了这个任务","塔隆凯在哪里","塔隆凯·捷根的作用"}},{q="什么是成熟的魔苔？",a="成熟的魔苔是邪恶的塞索尔所携带的一种具有腐蚀性的植物样本，塔隆凯·捷根试图寻找它，以进一步揭开这名萨特的真实动机以及他在泰达希尔正在进行的勾当。",al={"成熟的魔苔","为什么要收集魔苔","什么是魔苔"}},{q="梅伦纳斯领主是如何卷入其中的？",a="梅伦纳斯领主的所作所为并非出于孤立的恶意，而是在邪恶的塞索尔明确指使下进行的，这揭露了在泰达希尔内部运作的一个有组织的萨特阴谋。",al={"梅伦纳斯的关联","谁是梅伦纳斯领主","梅伦纳斯与塞索尔"}}},fp="14,273,18.291.0,31.408.1,26.227.0,27.169.0,43.188.0,27.178.0,28.194.0,30.171.0"}
P.entries["quest:98404"] = {n="The Great Windborne Cat Spirit",s="The Great Windborne Cat Spirit是摆在德鲁伊新秀面前，关于狡诈与潜行的神圣试炼。受试者必须进入附近的Stormrage Barrow Den，在避开敌对、狂怒的灵魂的同时寻回三件古代圣物。通过这项灵性仪式，证明了受试者掌握了猫科动物潜行、凶猛和狡诈的美德，从而获得驾驭猫形态的祝福。",h="The Great Windborne Cat Spirit是摆在德鲁伊新秀面前，关于狡诈与潜行的神圣试炼。受试者必须进入附近的Stormrage Barrow...",kw={"saeyleenan的化身","猫形态","德鲁伊试炼","狂怒的灵魂","利爪圣物","尖牙圣物","静影圣物","saeyleenan","stormrage barrow den","the great windborne cat spirit"},ang={["class:Druid"]="对于学习引导野猫敏捷、潜行和捕食本能的德鲁伊来说，这项仪式是一个重要的里程碑。在灵魂赋予其变形祝福之前，必须证明自己具备狡诈和凶猛的特质。",["race:NightElf"]="Stormrage Barrow Den承载着最显赫的暗夜精灵德鲁伊家族之一的名字。探索其深处能让卡多雷修行者直接与古代兽穴遗产以及他们人民的祖先灵魂相连。"},sec={{t="狡诈与潜行试炼",b="为了汲取The Great Cat Spirit的力量，志向者必须证明他们拥有捕食者的气质。与猫科动物达成真正的和谐需要理解狡诈与耐心，并要在受困时展现出爆发性的凶猛。灵魂不会轻易将天赋赐予那些仅是索求力量的人；相反，它会考验寻觅者是否能像荒野中的猫科猎手那样思考、行动和打击。唯有展现出这些内在特质，新秀才有望获得化身为猫的权利。"},{t="Stormrage Barrow Den",b="这项考验会将寻觅者送入附近Stormrage Barrow Den的阴暗之中，它位于灵魂化身的东面。在这些地下大厅深处存放着三件神圣信物：尖牙圣物、利爪圣物和静影圣物。然而，获取它们绝非易事。这座兽穴已然充斥着狂怒的灵魂，它们会对视野中的任何入侵者进行猛烈攻击。为了在洞穴中生存并抵达圣物所在地，寻觅者不能仅依靠蛮力，而必须在黑暗中小心潜行。"},{t="Saeyleenan的化身",b="这场试炼的核心是Saeyleenan的化身，这是The Great Windborne Cat Spirit与年轻新秀沟通的实体显现。考虑到未经训练的寻觅者缺乏老练捕食者那种与生俱来的潜行能力，兽穴入口处的一座雕像会提供暂时的隐匿祝福。那些成功避开狂乱灵魂并带回全部三件圣物的人，证明了他们已经领悟了捕食者的课程。作为回报，化身会认可他们的资格，并赋予他们化身为猫形态所需的祝福。"}},faq={{q="谁是The Great Windborne Cat Spirit？",a="The Great Windborne Cat Spirit是一位野性守护者，指引年轻的德鲁伊掌握猫科动物变形术。它通过Saeyleenan的化身显现，体现了狡诈、潜行和凶猛这些核心的捕食者美德。它并不会随意赋予其形态，而是通过神圣试炼来考验志向者，以确保他们尊重猫科动物的捕食本能与天性。",al={"the great windborne cat spirit","saeyleenan是谁","cat spirit背景故事"}},{q="什么是Saeyleenan的化身？",a="Saeyleenan的化身是The Great Windborne Cat Spirit的实体存在与发言人。化身位于Stormrage Barrow Den的西面，负责监督该地区的德鲁伊试炼。它指派寻觅者执行找回被盗或隐藏的兽穴圣物的任务，并评估新秀是否展现出足够的潜行和狡诈来赢得猫科动物的祝福。",al={"saeyleenan的化身","saeyleenan的化身是谁","saeyleenan npc"}},{q="试炼需要哪些圣物？",a="试炼需要从Stormrage Barrow Den内找回三件特定的圣物：尖牙圣物、利爪圣物和静影圣物。这些神器共同象征着定义猫灵形态的核心物理武器与难以捉摸的潜行能力，证明了新秀对捕食者每一面的敬畏。",al={"三件圣物","利爪圣物","stormrage barrow den圣物"}},{q="Stormrage Barrow Den位于何处？",a="Stormrage Barrow Den位于Saeyleenan的化身东面。这些地下室是德鲁伊试炼的试验场，存放着三件神圣圣物。新秀必须深入这些黑暗的大厅，同时避开在隧道中游荡的危险的狂怒灵魂。",al={"stormrage barrow den位置","barrow den在哪里","哪里寻找圣物"}},{q="为什么狂怒的灵魂在守卫兽穴？",a="Stormrage Barrow Den已被强大的狂怒灵魂所占据，它们会攻击视野中的任何活体入侵者。这些敌对实体并非自愿的守卫者，而是兽穴内活跃的危险，这迫使德鲁伊志向者必须利用狡诈与潜行来取回圣物，而不是进行直接战斗。",al={"灵魂为何狂怒","barrow den的狂怒灵魂","barrow den守卫"}},{q="寻觅者如何潜行穿过狂怒的灵魂？",a="立在Stormrage Barrow Den入口处的一座石像会给予寻觅者暂时的潜行祝福。由于年轻的新秀尚未获得自身固有的猫形态或潜行能力，这种防护附魔使他们能够未被察觉地溜过警惕的敌对灵魂，从而获取圣物。",al={"如何在barrow den潜行","石像潜行增益","如何避开狂怒灵魂"}},{q="完成试炼后会获得什么奖励或祝福？",a="在交回尖牙圣物、利爪圣物和静影圣物后，Saeyleenan的化身会认为寻觅者有资格获得The Great Windborne Cat Spirit的祝福。这项仪式标志着新秀对猫科动物真实本性的理解，赋予他们化身为捕食者形态所需的灵性认可。",al={"试炼奖励","从cat spirit获得什么","cat spirit的祝福"}}},fp="30,237,32.343.0,24.379.0,24.452.0,38.263.0,33.273.0,39.281.0,42.213.0,48.273.0,46.264.0,61.320.0"}
P.entries["quest:98407"] = {n="Show of Force",s="Show of Force是赤脊山的一项联盟防御任务，由菲尔顿副队长发布。为了阻止在湖畔镇附近不断逼近的豺狼人族群，冒险者们受命猎杀豺狼人剥皮者并收集它们的尖刺项圈，以震慑这些试图侵入人类定居点的生物。",h="Show of Force是赤脊山的一项联盟防御任务，由菲尔顿副队长发布。为了阻止在湖畔镇附近不断逼近的豺狼人族群，冒险者们受命猎杀豺狼人剥皮者并收集它们的尖刺项圈，以震慑这些试图侵入人类定居点的生物。",kw={"菲尔顿副队长","豺狼人剥皮者","豺狼人","湖畔镇","赤脊山","show of force","尖刺项圈"},ang={["class:Warrior"]="豺狼人只屈服于直接而彻底的暴力——这使得直接的前线武力镇压成为打破它们防线的理想方法。",["faction:Alliance"]="湖畔镇是联盟在南部东部王国最靠东的堡垒之一；确保其边界免受野兽侵袭对于区域稳定至关重要。",["race:Human"]="赤脊山的农场主和镇民是暴风城的臣民，他们处于极其危险的境地，没有任何保护，只能依靠他们的同胞来击退这些狂野的掠夺者。"},sec={{t="大胆的侵袭",b="赤脊山长期以来一直庇护着狂野的豺狼人部落，但它们现在变得愈发猖狂。豺狼人劫掠小队不再只是在崎岖的丘陵高处与世隔绝，而是在距离湖畔镇和外围人类家园极其危险的地方建立了营地。随着暴风城的军事力量捉襟见肘，无法为农村边境提供援军，当地当局必须依靠过往的冒险者来保卫边境，防止这些侵袭小队聚集胆量袭击城镇本身。"},{t="它们的语言",b="菲尔顿副队长深知豺狼人是残忍且毫无组织的生物，除了绝对的武力压制外，它们几乎什么都不怕。要迫使它们退回荒野，外交手段或折中办法毫无用处。菲尔顿试图打击它们最凶猛的先锋——豺狼人剥皮者——并收获它们的尖刺项圈，作为支配地位的冷酷证明。通过击溃它们的前线战士并展示它们的失败战利品，湖畔镇的守卫者希望以此威慑幸存的族群，让它们撤回高地。"}},faq={{q="谁提供了这个任务？他们位于哪里？",a="该任务由菲尔顿副队长提供，他是一名驻扎在赤脊山湖畔镇附近外围的城镇守卫。",al={"任务发布者","菲尔顿副队长位置","谁发布show of force"}},{q="为什么豺狼人会逼近湖畔镇？",a="豺狼人是极具侵略性的机会主义者，它们会不断试探自己的边界。由于湖畔镇在防守上面临压力，且几乎没有得到暴风城的军事援助，豺狼人变得胆大妄为，直接在人类定居点外建立了狩猎营地。",al={"豺狼人为何攻击","赤脊山豺狼人威胁","为什么豺狼人靠得这么近"}},{q="为了这个任务，需要击败哪些敌人？",a="该任务的目标是豺狼人剥皮者，它们是当地豺狼人族群中更危险、更具侵略性的突击战士，佩戴着沉重的尖刺项圈。",al={"哪些豺狼人","需要击杀什么怪物","豺狼人剥皮者"}},{q="为什么菲尔顿副队长特别想要尖刺项圈？",a="豺狼人依靠残酷的等级制度和原始力量生存。夺取剥皮者的尖刺项圈是一种直接的力量展示，旨在恐吓幸存的豺狼人，迫使它们撤回山丘。",al={"为什么要尖刺项圈","项圈的用途","为什么要拿走项圈"}},{q="暴风城能提供士兵来对付豺狼人吗？",a="暴风城在很大程度上任由赤脊山自生自灭。由于王国国内局势动荡且各处兵力短缺，暴风城几乎没有派遣任何增援部队，迫使当地副队长不得不依靠独立的勇士。",al={"暴风城对赤脊山的援助","为什么没有暴风城军队","守卫在哪里"}},{q="豺狼人通常在赤脊山的什么地方扎营？",a="豺狼人营地散布在止水湖周围的丘陵和低矮山脊上，以及通往东部石堡区域的道路沿线。",al={"豺狼人营地","在哪里找到豺狼人","赤脊山豺狼人位置"}}},fp="13,133,19.351.0,23.327.0,49.102.0,49.172.0,50.108.0,56.124.0,55.135.0,52.109.0"}
P.entries["quest:98423"] = {n="The Treaty of Understanding",s="谅解条约是一块古老的矮人石板，详细记载了三锤之战后铜须部族与蛮锤部族之间达成的历史性和平协议。这件文物从地底深处被发掘出来，并被带到了国王麦格尼·铜须面前，它不仅保存了矮人历史上关键的一刻，也突显了黑铁部族因这场和平协议被排斥在外而留下的深刻裂痕。",h="谅解条约是一块古老的矮人石板，详细记载了三锤之战后铜须部族与蛮锤部族之间达成的历史性和平协议。这件文物从地底深处被发掘出来，并被带到了国王麦格尼·铜须面前，它不仅保存了矮人历史上关键的一刻，也突显了黑铁部族因这场和平协议...",kw={"黑铁部族","铁炉堡","madoran bronzebeard","magni bronzebeard","和平条约","谅解条约","三锤之战","蛮锤部族"},ang={["faction:Alliance"]="铜须矮人和蛮锤矮人之间历史性的和平，奠定了他们在现代大联盟中合作的基础。",["race:Dwarf"]="这块石板是矮人和解的有形记录，展示了你的先祖们如何在争夺山脉的战争结束后，放下了他们的宿怨。"},sec={{t="矮人的一件和解遗物",b="Recovered from deep within an ancient vault, the Treaty of Understanding is a historic stone tablet documenting the formal cessation of hostilities between dwarven clans. Dating to the turbulent aftermath of the War of the Three Hammers, it represents the moment peace was forged between the Bronzebeard and Wildhammer clans after the Bronzebeards secured control of Ironforge mountain."},{t="未签署的和平",b="当这块被找回的石板呈现在国王麦格尼·铜须面前时，他认出这是他的祖先，第一位铁炉堡铜须国王Madoran Bronzebeard的作品。虽然这份文件上有铜须和蛮锤领袖的签名，但显然缺少了黑铁部族的印记，这也成了黑铁部族与他们的山中同胞之间持久裂痕的永久见证。"}},faq={{q="什么是谅解条约？",a="谅解条约是一块从深层金库中发掘出来的古老矮人石板。它记录了三锤之战结束后，铜须部族与蛮锤部族之间达成的正式和平协议。",al={"什么是谅解条约","条约石板","这是什么条约"}},{q="谁制定了该条约？",a="该条约是在三锤之战结束后，由第一位在三部族争夺铁炉堡控制权后统治铁炉堡的铜须国王Madoran Bronzebeard在位期间起草的。",al={"谁写了谅解条约","谁制作了谅解条约","谁起草了条约"}},{q="黑铁部族为什么没有签署该条约？",a="在铜须部族夺取了铁炉堡的控制权后，黑铁部族拒绝接受和平。因此，只有铜须部族和蛮锤部族签署了该协议，导致黑铁部族被孤立并怀恨在心。",al={"为什么黑铁没有签署","黑铁签署了条约吗","黑铁不在条约上"}},{q="谁对谅解条约感兴趣？",a="这块石板被送到了铁炉堡High Seat的国王麦格尼·铜须手中，他将其视为先祖Madoran和矮人历史上无价的遗物。",al={"谁想要这个条约","我把谅解条约交给谁","在哪里上交条约"}},{q="什么是三锤之战？",a="三锤之战是铜须、蛮锤和黑铁这三个矮人部族之间为争夺铁炉堡的控制权而进行的一场残酷内战。铜须部族最终获胜，夺取了铁炉堡，而其他部族则被赶走。",al={"什么是三锤之战","矮人内战","三锤战争"}},{q="Madoran Bronzebeard是谁？",a="Madoran Bronzebeard是国王麦格尼·铜须的祖先，也是三个矮人部族内战后，第一位统治铁炉堡的铜须国王。",al={"madoran bronzebeard是谁","madoran bronzebeard","麦格尼的祖先madoran"}}},fp="27,406,33.386.0,18.411.0,36.252.0,23.210.0,47.215.0,49.162.0,38.254.0,28.166.0"}
P.entries["quest:98424"] = {n="Fizsprockets Notizen",s="摩林·云行者正在风​​险投资公司矿洞寻找 Fizsprocket 笔记本剩余的页面。这些磨损的笔记记载着关于该公司在此地区阴谋的重要信息。",h="摩林·云行者正在风​​险投资公司矿洞寻找 Fizsprocket 笔记本剩余的页面。这些磨损的笔记记载着关于该公司在此地区阴谋的重要信息。",kw={"血蹄村","fizsprocket","矿洞","摩林·云行者","笔记本","页面","风险投资公司"},sec={{t="遗失的页面",b="你在 Fizsprocket 的口袋里找到了折叠的页面。摩林正在血蹄村等候你从风险投资公司矿洞带回剩余的页面，笔记本中的信息或许能为接下来的行动指明方向。"}},faq={{q="我在找哪些页面？",a="你要寻找的是监工 Fizsprocket 笔记本剩余的页面。",al={"fizsprocket 笔记","笔记本页面","遗失的笔记"}},{q="其余笔记在哪里？",a="剩余的页面在风险投资公司矿洞里。",al={"页面在哪里","风险投资公司矿洞","笔记本位置"}},{q="谁想要这些页面？",a="摩林·云行者正在血蹄村等候这些页面。",al={"谁需要笔记","摩林的请求","把页面交给谁"}},{q="Fizsprocket 的笔记本里写了什么？",a="这本笔记记载着关于风险投资公司及其在此地区阴谋的重要信息。",al={"笔记内容","fizsprocket 笔记本","风险投资公司信息"}}},fp="20,158,17.257.0,28.77.0,32.48.0,20.65.0,36.96.0"}
P.entries["quest:98427"] = {n="Schluss damit!",s="摩林·云行者警告说，伐木机器人能以惊人的速度砍倒整片森林。他请你返回东北方的矿洞，阻止它再砍倒一棵树。",h="摩林·云行者警告说，伐木机器人能以惊人的速度砍倒整片森林。他请你返回东北方的矿洞，阻止它再砍倒一棵树。",kw={"血蹄村","大地母亲的子民","mechanoroderschlüssel","矿洞","摩林·云行者","东北方","伐木机器人","树木"},ang={["race:Tauren"]="作为一名牛头人，摩林关心庇护大地母亲子民的林地，也关心家园附近幼小族人的安危。"},sec={{t="家园的威胁",b="摩林听说了书页中描述的伐木机器人。这种机器砍倒整片森林的速度远胜斧头和人力。庇护大地母亲子民多年的林地，短短几天便可能消失。他请你召集盟友，返回东北方的矿洞，确保机器不再砍倒树木。请将Mechanoroderschlüssel带给血蹄村的摩林。"}},faq={{q="摩林要我做什么？",a="摩林请你召集盟友，返回东北方的矿洞，阻止伐木机器人继续砍树。",al={"摩林想要什么","摩林的请求","伐木机器人任务"}},{q="伐木机器人为何构成威胁？",a="摩林说，伐木机器人砍倒整片森林的速度远胜斧头和人力，还会摧毁庇护大地母亲子民的林地。",al={"为何阻止伐木机器人","伐木机器人的威胁","伐木机器人能做什么"}},{q="摩林要我去哪里？",a="摩林请你返回东北方的矿洞。",al={"矿洞在哪里","东北方的矿洞","要返回哪里"}},{q="我要带什么东西交给摩林？",a="将Mechanoroderschlüssel交给血蹄村的摩林·云行者。",al={"摩林要什么物品","mechanoroderschlüssel","交给摩林的钥匙"}},{q="摩林·云行者是谁？",a="摩林·云行者请你阻止伐木机器人砍伐牛头人家园附近的树木。",al={"摩林是谁","摩林·云行者","摩林这个人"}}},fp="18,186,16.385.0,30.116.0,29.148.0,31.54.0,30.76.0,26.89.0"}
P.entries["quest:98430"] = {n="Die Langläufer",s="斥候Perith Stormhoof受凯恩·血蹄派遣，在与豺狼人谋求和平时遭遇暴力，如今被困在Bleachmane Rock。救出他对凯恩和牛头人至关重要。",h="斥候Perith Stormhoof受凯恩·血蹄派遣，在与豺狼人谋求和平时遭遇暴力，如今被困在Bleachmane Rock。救出他对凯恩和牛头人至关重要。",kw={"bleachmane rock","凯恩·血蹄","豺狼人","长跑者","和平尝试","perith stormhoof","雷霆崖"},ang={["race:Tauren"]="身为牛头人，你正在帮助凯恩·血蹄信任的斥候，他的任务关系到牛头人。"},sec={{t="身陷险境的斥候",b="凯恩·血蹄派Perith Stormhoof前去接触定居于此的豺狼人。作为凯恩的长跑者之一，Perith不能透露完整任务。和平尝试遭到暴力回应，他担心若留到夜里，豺狼人会把他吃掉。请帮助他逃离Bleachmane Rock，并前往雷霆崖向凯恩报告他已平安脱险。"},{t="凯恩的谢意",b="得知Perith平安无事，凯恩如释重负。他称这名斥候是自己最信任的人，并表示这项任务意义重大。凯恩感谢你冒着生命危险救他，说你为牛头人做出的贡献远超你的想象。"}},faq={{q="Perith Stormhoof是谁？",a="Perith Stormhoof是凯恩·血蹄的长跑者之一，也就是这位酋长的斥候。",al={"perith是谁","stormhoof斥候","长跑者是谁"}},{q="Perith为何在Bleachmane Rock？",a="凯恩派Perith去接触定居于那里的豺狼人，但Perith不能透露完整任务。",al={"perith为何在那里","bleachmane rock","perith的任务"}},{q="和平尝试发生了什么？",a="豺狼人以暴力回应了长跑者的和平尝试，Perith因此陷入险境。",al={"豺狼人和平","perith为何被困","与豺狼人讲和"}},{q="凯恩要我做什么？",a="请帮助Perith逃离Bleachmane Rock，并告诉雷霆崖的凯恩他已平安无事。",al={"帮助perith","stormhoof的任务","救他出去"}}},fp="15,183,17.357.0,17.239.1,24.87.0,33.99.0,34.97.0,30.101.0"}
P.entries["quest:98435"] = {n="Thunderhorns Bericht",s="穆尔请你将 Thunderhorn 的报告送到雷霆崖，交给大德鲁伊 Hamuul Runetotem。长者们需要知道你的帮助取得了什么成果。",h="穆尔请你将 Thunderhorn 的报告送到雷霆崖，交给大德鲁伊 Hamuul Runetotem。长者们需要知道你的帮助取得了什么成果。",kw={"长者高地","hamuul runetotem","莫高雷","报告","泉水","牛头人","雷霆崖","thunderhorn"},sec={{t="报告",b="你把 Thunderhorn 的报告交给了位于雷霆崖东部的长者高地的 Hamuul。他说，莫高雷的泉水滋养着牛头人，也滋养着他们赖以获取食物、衣物和陪伴的动物。"}},faq={{q="谁需要 Thunderhorn 的报告？",a="雷霆崖的大德鲁伊 Hamuul Runetotem 需要 Thunderhorn 的报告。",al={"谁收报告","给 hamuul 的报告","thunderhorn 的报告"}},{q="Hamuul Runetotem 在哪里？",a="Hamuul 位于雷霆崖东部的长者高地。",al={"hamuul 在哪里","hamuul 的位置","寻找 hamuul"}},{q="这份报告为何重要？",a="莫高雷的泉水滋养着牛头人，也滋养着他们赖以获取食物、衣物和陪伴的动物。",al={"报告为何重要","泉水有何用处","莫高雷的泉水"}},{q="Hamuul 对泉水有何评价？",a="Hamuul 说，泉水滋养着牛头人，也滋养着他们所依赖的动物。",al={"hamuul 说了什么","泉水与动物"}}},fp="20,151,10.220.0,33.73.0,26.53.0,27.106.0,39.79.0"}
P.entries["quest:98459"] = {n="A Lack of Virtue",s="“A Lack of Virtue”是一个送信任务，讲述了两名玩牌的水手——“半鱼”汤姆和巴特·潮汐水手之间经久不息的小摩擦。旅行者们带着一份包裹好的礼物跨越海洋来到米奈希尔港，却意外卷入了两人关于“少女的贞洁号”是如何得来的互相指控之中。",h="“A Lack of...",kw={"a lack of virtue","巴特·潮汐水手","少女的贞洁号","米奈希尔港","扑克","塔纳利斯","汤姆·半鱼","汤姆的礼物","湿地"},ang={["faction:Alliance"]="路过米奈希尔港的联盟旅行者经常会遇到正在对船员咆哮的巴特·潮汐水手，这使得送信成为了在等待横跨无尽之海的交通工具时的一个小插曲。"},sec={{t="苦涩的积怨",b="“A Lack of Virtue”的核心是两位老练的海上赌徒之间尖锐的竞争：汤姆·半鱼和巴特·潮汐水手。汤姆招募过往的旅行者将一个包裹送过海面交给米奈希尔港的巴特，以此作为对这位前同伴尖酸刻薄的嘲弄。一路上，汤姆警告说巴特根本不是真正的海员，而是一个曾经靠在牌局中出老千来买下船只指挥权的演员。"},{t="摊牌",b="当在米奈希尔港的码头上收到“汤姆的礼物”时，巴特·潮汐水手一听到他这位老相识的名字就勃然大怒。巴特立即反唇相讥，发誓说出老千的其实是汤姆，而且只有在他们的牌局将“半鱼”踢出去之后，他才赢得了足够的金币买下“少女的贞洁号”。尽管脾气爆发，巴特还是很快控制住了自己，为对送信人发火表示了歉意，并欢迎旅行者来到港口。"}},faq={{q="巴特·潮汐水手是谁？",a="巴特·潮汐水手是停靠在米奈希尔港的“少女的贞洁号”的自封船长。据他的老相识汤姆·半鱼所说，巴特原本是一名演员，他是用玩牌赢来的钱买下了这艘船——尽管两人都指责对方玩牌出老千。",al={"巴特·潮汐水手是谁","巴特·潮汐水手背景故事","少女的贞洁号的船长是谁"}},{q="汤姆·半鱼是谁？",a="汤姆·半鱼是巴特·潮汐水手的一位老相识，他给旅行者一份礼物，让他们带过海面交给巴特。他怀着对这位船长的强烈积怨，声称巴特是个骗子、吝啬鬼，还是个玩牌的老千。",al={"半鱼是谁","汤姆·半鱼是谁","谁发布了a lack of virtue任务"}},{q="“少女的贞洁号”是什么？",a="“少女的贞洁号”是一艘停靠在湿地米奈希尔港的船只。巴特·潮汐水手声称这是无尽之海最棒的船，尽管汤姆·半鱼贬损说这艘船航行的最远距离也就像塔纳利斯的一块石头那么远。",al={"什么是少女的贞洁号","少女的贞洁号船只","少女的贞洁号在哪里"}},{q="“汤姆的礼物”是什么？",a="“汤姆的礼物”是汤姆·半鱼寄给米奈希尔港巴特·潮汐水手的一个包裹。虽然送货人不知道里面的具体内容，但收到礼物后，巴特立即就汤姆本人打扑克出老千的问题破口大骂。",al={"什么是汤姆的礼物","汤姆的礼物里面有什么","为什么巴特对汤姆的礼物感到生气"}},{q="到底是谁在打扑克时出老千？",a="两位水手都激烈地指责对方出老千。汤姆·半鱼坚称巴特是个只靠出老千赢牌买船的演员，而巴特则声称只有在将汤姆踢出他们的牌局之后，他才名正言顺地赢得了自己的船只。",al={"谁在打扑克时出老千","巴特打扑克时出老千了吗","汤姆打扑克时出老千了吗"}},{q="如何将礼物送到米奈希尔港？",a="旅行者可以乘坐跨越无尽之海的船只到达湿地的米奈希尔港。任务发布者指出，一班直达船在米奈希尔港有停靠。",al={"如何前往米奈希尔港","前往米奈希尔港的船"}}},fp="16,307,15.452.0,18.486.1,22.281.0,21.231.0,28.229.0,19.251.0,30.269.0,47.179.0"}
P.entries["quest:98461"] = {n="Unrequited Love",s="Unrequited Love是联盟的一项送信任务，起始于Darkshore岸边的奥伯丁。Hollee请求搭乘船只前往米奈希尔港的旅人将一封私人信件交给塔雷尔·石纹，他是她曾经的考古学同学，她至今对他怀有默默的爱慕。",h="Unrequited Love是联盟的一项送信任务，起始于Darkshore岸边的奥伯丁。Hollee请求搭乘船只前往米奈希尔港的旅人将一封私人信件交给塔雷尔·石纹，他是她曾经的考古学同学，她至今对他怀有默默的爱慕。",kw={"奥伯丁","darkshore","考古","hollee","霍莉的便笺","米奈希尔港","merrin","塔雷尔·石纹","unrequited love","wetlands"},ang={["faction:Alliance"]="这次运送将Darkshore的联盟港口奥伯丁与Wetlands的米奈希尔港直接连接起来，连通了卡利姆多和东部王国。",["race:Dwarf"]="塔雷尔·石纹和Hollee都有考古背景，这是矮人传统和Azeroth学术研究的核心职业。"},sec={{t="跨海传书",b="在Darkshore多雾的海岸边，海港小镇奥伯丁，Hollee注视着登上前往东部王国船只的旅人。她寻求路人的帮助来联系一位老同学塔雷尔·石纹，在毕业将他们分隔在不同的大陆之前，他们曾一起学习多年的考古技艺。"},{t="未诉说的情感",b="虽然Hollee深情地回忆起塔雷尔敏锐的头脑和考古技能，但一提到他的妻子Merrin，她的神情就会变得不自然。尽管相隔遥远且他已婚，Hollee还是将一封私人信件托付给了一位冒险者，请求他们前往米奈希尔港附近寻找塔雷尔，以确认他是否平安。"}},faq={{q="谁发布了Unrequited Love任务？",a="Hollee在Darkshore的沿海定居点奥伯丁发布了这个任务。她请求搭乘前往米奈希尔港船只的旅人将一封私人便笺交给一位老同学。",al={"谁发布了unrequited love","奥伯丁的任务发布者"}},{q="塔雷尔·石纹是谁？",a="塔雷尔·石纹是一位考古学家，也是Hollee以前的同学。学业结束后，他被派往Wetlands，现在和他的妻子Merrin一起在米奈希尔港附近工作。",al={"塔雷尔·石纹是谁","塔雷尔相关传说"}},{q="Merrin是谁？",a="Merrin是塔雷尔·石纹的妻子。Hollee在提到她时显得犹豫不决且眉头紧锁，这揭示了尽管塔雷尔已经结婚，她对他仍有挥之不去、未得到回应的感情。",al={"merrin是谁","塔雷尔的妻子"}},{q="为什么任务叫Unrequited Love？",a="这个标题指的是Hollee对塔雷尔·石纹那份默默的情感。尽管他们作为亲密的同学一起学习考古，但塔雷尔娶了Merrin，留下了Hollee在远隔重洋的奥伯丁独自思念。",al={"unrequited love任务内容","为什么叫unrequited love"}},{q="塔雷尔·石纹在哪里？",a="塔雷尔·石纹可以在Wetlands的米奈希尔港附近找到，这里与Darkshore隔着无尽之海。从奥伯丁出发的客船可以将旅人直接送达港口码头。",al={"在哪里找到塔雷尔·石纹","塔雷尔所在的wetlands"}},{q="这个任务要传送什么物品？",a="你被要求携带霍莉的便笺去交给塔雷尔·石纹，以确认他在Wetlands的近况并传达她的私人信息。",al={"你要送什么","hollee的信"}}},fp="15,272,24.318.0,17.299.0,37.180.0,25.188.0,14.182.0,40.208.0,35.183.0,37.134.0"}
P.entries["quest:98463"] = {n="Talk of the Town",s="一位友好的酒保指引那些渴望热闹聚会的旅客前往位于荆棘谷的藏宝海湾。如果想要寻找更狂野的同伴，则被告知去Salty Sailor Tavern寻找尼克斯拉克斯·菲拉马克。",h="一位友好的酒保指引那些渴望热闹聚会的旅客前往位于荆棘谷的藏宝海湾。如果想要寻找更狂野的同伴，则被告知去Salty Sailor Tavern寻找尼克斯拉克斯·菲拉马克。",kw={"藏宝海湾","地精酒馆","尼克斯拉克斯·菲拉马克","salty sailor tavern","荆棘谷","talk of the town"},sec={{t="柜台间的消息",b="消息在酒保和顾客之间流传得很快，并且传得很远。一位友好的酒保透漏了哪里正在酝酿真正的骚乱，指引任何寻找更狂野场面的人前往藏宝海湾。"},{t="咸水帆船",b="目的地是Salty Sailor Tavern，这是一间由地精在熙熙攘攘的荆棘谷中经营的热闹场所。在那里，尼克斯拉克斯·菲拉马克为每一位走进店里的客人斟满酒杯。"}},faq={{q="这会带你到哪里？",a="这会带你前往荆棘谷，直达地精经营的港口城镇藏宝海湾。",al={"我要去哪里","目的地","藏宝海湾指引"}},{q="在藏宝海湾应该去找谁？",a="你被指引去Salty Sailor Tavern寻找尼克斯拉克斯·菲拉马克，他会在那里为大家斟满酒杯。",al={"要拜访谁","尼克斯拉克斯是谁","尼克斯拉克斯·菲拉马克"}},{q="为什么要让人跑那么远去荆棘谷？",a="酒保总能从客人的闲谈中听到各种流言，据说Salty Sailor Tavern有着附近最狂野的庆祝活动，无论是否由地精管理。",al={"为什么去咸水帆船","为什么要前往藏宝海湾","为什么有此推荐"}}},fp="16,221,25.271.0,16.199.0,21.84.0,42.117.0,51.166.0"}
P.entries["quest:985"] = {n="熊怪的威胁",s="“威胁有多大？”是一个联盟任务，由奥伯丁的暗夜精灵特伦希斯提供。在已经侦察过镇子南面的敌对黑木熊怪营地后，冒险者被派去消灭受腐化的探路者和风语者，以免他们的疯狂威胁到定居点。",h="“威胁有多大？”是一个联盟任务，由奥伯丁的暗夜精灵特伦希斯提供。在已经侦察过镇子南面的敌对黑木熊怪营地后，冒险者被派去消灭受腐化的探路者和风语者，以免他们的疯狂威胁到定居点。",kw={"奥伯丁","黑木","黑海岸","魔苔","熊怪","格里姆克劳","探路者","特伦希斯","风语者"},ang={["class:Druid"]="德鲁伊对此悲剧感触尤深，因为熊怪的困境反映了森林在魔苔污染下所遭受的持续痛苦。",["faction:Alliance"]="奥伯丁是联盟在黑海岸的重要港口据点，因此清除附近的敌对营地对于确保该地区的安全至关重要。",["race:NightElf"]="对于暗夜精灵来说，清理黑木熊怪是一种痛苦的悲哀；与熊怪数百年的亲族关系因第三次战争残留的恶魔枯萎病而破碎。"},sec={{t="必要的清理",b="在对奥伯丁南部进行初步侦察后，哨兵部队判定黑木熊怪对黑海岸的难民和守卫者构成了直接威胁。特伦希斯指派有战斗能力的旅行者直接突袭他们的营地，消灭黑木探路者和风语者，以打破他们的攻势。"},{t="受腐化者的悲剧",b="暗夜精灵传统上将熊怪视为精神上的亲族和荒野的历史盟友。然而，魔苔和恶魔污染在卡利姆多北部的恶性蔓延导致黑木部落陷入疯狂。由于目前没有已知的补救措施可以恢复熊怪的神智，奥伯丁的守卫者们将暴力视为防止无辜死亡的冷酷必要手段。"},{t="格里姆克劳的到来",b="在向特伦希斯汇报清理任务后，一只名叫格里姆克劳的白熊冲进奥伯丁，奔向那名暗夜精灵。它的到来标志着蹂躏海岸线的野生动物和腐化问题出现了紧急的新进展，开启了奥伯丁防御工作的下一阶段。"}},faq={{q="特伦希斯为什么要消灭黑木熊怪？",a="奥伯丁南部的黑木部落已经堕入腐化，变得暴力且失去理智。由于他们的营地对定居点构成了迫在眉睫的威胁，且目前尚未发现针对这种腐化的治疗方法，特伦希斯下令发动先发制人的打击以确保奥伯丁的安全。",al={"为什么要消灭黑木熊怪","熊怪清理的原因","特伦希斯的熊怪任务"}},{q="黑木熊怪营地在哪里？",a="营地位于奥伯丁以南，沿着黑海岸的沿海森林，坐落在黑木部落聚集的受腐化树木之中。",al={"黑木熊怪的位置","探路者和风语者在哪里","黑海岸的熊怪营地"}},{q="格里姆克劳是谁？",a="格里姆克劳是一只与黑海岸荒野调查相关的白熊。",al={"奥伯丁的白熊","熊格里姆克劳"}},{q="是什么导致熊怪发疯？",a="熊怪受到了魔苔和第三次战争后残留的恶魔腐化的毒害。蹂躏黑海岸的黑暗能量扭曲了它们的心智和身体，驱使原本爱好和平的部族陷入无法控制的狂暴之中。",al={"为什么熊怪会发疯","黑海岸熊怪的腐化","是什么腐化了黑木部落"}},{q="为什么暗夜精灵不愿杀害熊怪？",a="熊怪和暗夜精灵分享着数千年的友谊和对自然的崇敬。对暗夜精灵来说，杀死它们就像是在屠杀自己的荒野兄弟，但腐化让他们别无选择。",al={"暗夜精灵与熊怪","为什么要哀悼熊怪"}},{q="“威胁有多大？”任务的第一阶段和第二阶段有什么区别？",a="第一个任务通过要求你定位并观察黑木营地来测试侦察能力。第二个任务则是一项直接的战斗任务，在威胁确认后，旨在削减营地中的探路者和风语者数量。",al={"“威胁有多大”的组成部分","“威胁有多大”的区别"}}},fp="17,188,16.285.0,24.309.0,18.289.1,54.201.0,44.144.0,16.81.1,39.186.0,47.189.0,79.168.0"}
P.entries["quest:98512"] = {n="Al'Aketh Assassins",s="Al'Aketh Assassins 是一个要求消灭一群危险杀手的任务。冒险者需要协助一名斥候消除威胁，并获得将要在给瓦拉纳尔的报告中提到的正式表彰。",h="Al'Aketh Assassins 是一个要求消灭一群危险杀手的任务。冒险者需要协助一名斥候消除威胁，并获得将要在给瓦拉纳尔的报告中提到的正式表彰。",kw={"奥拉凯斯","刺客","杀手","任务","报告","瓦拉纳尔"},ang={["class:Rogue"]="面对像奥拉凯斯这样的致命杀手，需要具备同样致命的专注力和冷酷的精准度。"},sec={{t="致命威胁",b="Al'Aketh Assassins 在野外构成了致命威胁，当地斥候称他们为冷酷的杀手。他们无情的效率和协同作战的能力，使得任何与他们的冲突对当地斥候和旅行者来说都极其危险。处理他们的存在需要迅速果断的行动，以免他们先发制人。"},{t="向瓦拉纳尔报告",b="在消灭了敌对的奥拉凯斯部队后，一名盟军特工对你在面对如此危险的对手时幸存下来表示深感欣慰。为了感谢你及时的干预，这名斥候承诺将在发往瓦拉纳尔的官方报告中正式记录你的英勇援助。"}},faq={{q="什么是 Al'Aketh Assassins？",a="Al'Aketh Assassins 是一个任务，要求冒险者消灭一支致命的奥拉凯斯部队。他们构成的威胁十分严重，需要立即干预并提交正式报告。",al={"什么是 alaketh assassins","什么是这个任务","alaketh assassins 任务"}},{q="谁是奥拉凯斯刺客？",a="奥拉凯斯刺客被描述为冷酷的杀手，他们以协同作战的危险突击部队形式活动。他们致命的作风使他们成为野外严重的威胁。",al={"谁是奥拉凯斯","谁是奥拉凯斯刺客","奥拉凯斯杀手"}},{q="瓦拉纳尔是谁？",a="瓦拉纳尔是位于岛屿东南边缘的定居点，也是维和人员的基地。这名斥候计划在返回瓦拉纳尔时，将你的协助记录在报告中。",al={"谁是瓦拉纳尔","什么是瓦拉纳尔","向瓦拉纳尔报告"}},{q="为什么必须处理奥拉凯斯刺客？",a="奥拉凯斯刺客对该地区的特工和旅行者构成了致命且迫在眉睫的危险。消灭他们对于保护盟军并确保生存是必要的。",al={"为什么对付奥拉凯斯","为什么要击杀奥拉凯斯刺客","奥拉凯斯威胁"}},{q="处理完这些刺客后会发生什么？",a="在与刺客的冲突结束后，这名斥候准备向瓦拉纳尔报告，并承认了你在行动中提供的关键援助。",al={"alaketh assassins 之后发生了什么","下一个任务 alaketh","向瓦拉纳尔报告任务"}},{q="谁承认了你在击败刺客时提供的帮助？",a="该任务涉及一名驻扎在野外监视敌对势力动向的盟军特工。感谢你对致命刺客的干预，这名斥候记录了你的贡献，以供指挥部参考。",al={"谁发布了 alaketh assassins","谁是这名斥候","斥候报告瓦拉纳尔"}}},fp="18,115,15.226.0,21.140.0,27.120.0,31.102.0,16.133.0,46.130.0,46.78.0,53.115.0"}
P.entries["quest:98545"] = {n="Leonid's Letter",s="Leonid's Letter 是一个送信任务，指引旅行者深入幽暗城。由于与希尔瓦娜斯·风行者（Sylvanas Windrunner）过去的紧张关系，Leonid本人不愿进入被遗忘者首都，因此雇佣了一名中立的信使，将一封信送给驻扎在贸易区（Trade Quarter）的旧识地精 Glix Xizzix。",h="Leonid's Letter 是一个送信任务，指引旅行者深入幽暗城。由于与希尔瓦娜斯·风行者（Sylvanas...",kw={"黑暗女王","glix xizzix","leonid","失物招领","纳克萨玛斯","密封的信","希尔瓦娜斯","trade quarter","幽暗城"},ang={["faction:Horde"]="代表外来者进入被遗忘者首都，让部落冒险者可以轻松使用幽暗城贸易区的设施。",["race:Undead"]="Leonid 与黑暗女王的历史使他无法亲自踏入幽暗城，这突显了独立亡灵与希尔瓦娜斯忠诚者之间的政治紧张局势。"},sec={{t="外来者的差事",b="Leonid需要一名信使将一封密封的信件送到幽暗城的一位熟人手中。由于与希尔瓦娜斯·风行者过去存在的摩擦和紧张关系，Leonid选择不亲自踏入被遗忘者首都的大厅，而是委托一名路过的中立人员，在不引起警报的情况下通过城市守卫。"},{t="贸易区的旧识",b="收信人是 Glix Xizzix，一个在幽暗城贸易区做生意的机会主义地精。收到信件后，Glix 回忆起与 Leonid 一起在天灾军团的要塞纳克萨玛斯（Naxxramas）阴影下生存的往事。虽然对 Leonid 承诺的报酬感到惊讶和恼火，但 Glix 还是勉强从粗心的亡灵客户留下的失物招领中支付了酬金。"}},faq={{q="Leonid 是谁，为什么他不愿进入幽暗城？",a="Leonid 是一位经验丰富的士兵，与各派势力保持着微妙的关系。由于与希尔瓦娜斯·风行者之间复杂的过往，他避免直接进入幽暗城，而是依靠路过的冒险者为他送信给熟人。",al={"谁给了leonid的信","leonid bartholomew","leonid任务给予者"}},{q="Glix Xizzix 是谁？",a="Glix Xizzix 是一名驻扎在繁华的幽暗城贸易区的地精。他似乎在理发服务处附近经营，保留着健忘的亡灵顾客留下的失物招领。",al={"glix xizzix在哪里","谁是glix xizzix","幽暗城地精理发师"}},{q="Leonid 与黑暗女王之间有什么历史？",a="Leonid 承认他与被遗忘者的女妖之王希尔瓦娜斯·风行者之间有着“相当丰富的过往”。为了避免激怒她或她的守卫，他雇佣中立的第三方来处理他在城内的事务。",al={"leonid与黑暗女王的历史","leonid和希尔瓦娜斯"}},{q="Leonid 和 Glix 是怎么认识的？",a="Glix 记得 Leonid 是在对抗天灾军团的激烈战争中久经沙场的退伍军人，并回忆起可怕的要塞纳克萨玛斯向他们倾泻毁灭的岁月。",al={"glix xizzix与leonid和纳克萨玛斯","glix和leonid怎么认识的"}},{q="为什么 Glix 用失物招领中的物品作为报酬？",a="Leonid 告诉信使 Glix 会乐意给小费，但 Glix 并没有做出这种承诺。尽管不情愿，这位地精还是提供了从沙龙的失物招领中搜集到的、由健忘的被遗忘者客户遗留下的奇特小饰品。",al={"glix的任务奖励","为什么是失物招领"}},{q="这封信被送到了哪里？",a="这封信被带到了被遗忘者的首都幽暗城，直接送到了商人、工匠和地精在皇家药剂师学会和城市守卫的注视下进行交易的贸易区。",al={"leonid的信送到哪里","贸易区送信"}}},fp="15,315,20.328.0,33.404.0,47.259.0,19.218.0,44.236.0,39.175.0,51.231.0,30.227.0"}
P.entries["quest:98574"] = {n="Hallowed Memorandum",s="“神圣备忘录”是一份书面传唤，指示寒脊山谷中初出茅庐的侏儒牧师前往安威玛尔拜见布兰斯托克·卡德尔。它标志着他们精神修行的开始，将圣光描绘成一个非常适合侏儒的智力和好奇心的哲学谜题。",h="“神圣备忘录”是一份书面传唤，指示寒脊山谷中初出茅庐的侏儒牧师前往安威玛尔拜见布兰斯托克·卡德尔。它标志着他们精神修行的开始，将圣光描绘成一个非常适合侏儒的智力和好奇心的哲学谜题。",kw={"安威玛尔","布兰斯托克·卡德尔","寒脊山谷","丹莫罗","侏儒牧师","hallowed memorandum","圣光"},ang={["class:Priest"]="这份备忘录标志着寒脊山谷正式牧师教学的开始，向新晋的治疗者介绍了圣光的哲学。",["race:Gnome"]="接近圣光的侏儒在精神学习中带来了敏锐的智力和好奇心，将神圣的奥秘视为与信仰一起思考的谜题。"},sec={{t="前往安威玛尔的传唤",b="当在寒脊山谷协助盟友时，有前途的侏儒见习生会收到“神圣备忘录”，这是一份指导他们前往安威玛尔寻找布兰斯托克·卡德尔的入门信件。作为精神学习的号召，这张便条邀请有抱负的牧师开始他们在丹莫罗的正式教导。"},{t="信仰之谜",b="在出示备忘录后，布兰斯托克·卡德尔欢迎这位新手加入。他解释说，钻研圣光并非一项死板的技术工艺，而是一个需要好奇心、敏锐智力以及智力与情感和谐统一的深奥谜题。通过沉思和实践，学生们学会将这些神圣的奥秘引导为恢复性的修补和神圣的惩戒。"}},faq={{q="是谁寄送了“神圣备忘录”？",a="这份备忘录是由你在寒脊山谷附近协助时的一位当地盟友转交的，它源自居住在安威玛尔内的牧师训练师布兰斯托克·卡德尔。",al={"谁给了我备忘录","谁发送了神圣备忘录","便条从哪里来"}},{q="布兰斯托克·卡德尔是谁？",a="布兰斯托克·卡德尔是一位驻扎在寒脊山谷安威玛尔内的矮人牧师训练师。他指导初出茅庐的牧师了解圣光，并利用神圣的力量来治愈伤口或打击邪恶。",al={"布兰斯托克是谁","布兰斯托克·卡德尔 安威玛尔"}},{q="侏儒是如何看待圣光的？",a="布兰斯托克解释说，侏儒的好奇心和智力是理解圣光的天然途径。他鼓励人们将其视为一个结合了思想与情感的哲学谜题，而不是将其作为一种严格的技术工艺来对待。",al={"侏儒可以成为牧师吗","侏儒与圣光的联系","侏儒如何看待圣光"}},{q="布兰斯托克教导了关于圣光的什么内容？",a="布兰斯托克将圣光描述为不仅仅是一门精确的技术学科，而是一个谜题，它通过结合个人的思想和内在情感来提供实际的祝福和人生课程。",al={"根据布兰斯托克的说法什么是圣光","圣光之谜 布兰斯托克"}},{q="布兰斯托克提供哪些技能教导？",a="一旦牧师开始理解圣光，布兰斯托克就会提供指导，教导如何将这种力量直接引导为防御性的治疗祈祷和对邪恶者的神圣打击，以此换取微薄的捐赠。",al={"布兰斯托克教什么","牧师训练师能教什么"}},{q="在哪里可以找到布兰斯托克·卡德尔？",a="安威玛尔是位于丹莫罗寒脊山谷中心地带的中央堡垒和欢迎大厅，为矮人和来访的侏儒提供训练师和避难所。",al={"安威玛尔在哪里","布兰斯托克位置"}}},fp="19,298,21.309.0,20.398.0,33.184.0,25.205.0,38.246.0,42.193.0,45.208.0,37.168.0"}
P.entries["quest:98575"] = {n="Tainted Tablet",s="Tainted Tablet是试炼谷的一项初始任务，指引有志向的施法者前往大兽穴寻找纳托克。它展现了杜隆塔尔术士们务实而谨慎的思想，尽管过去留下了挥之不去的耻辱，但他们仍试图驾驭虚空来铸就自己的命运。",h="Tainted Tablet是试炼谷的一项初始任务，指引有志向的施法者前往大兽穴寻找纳托克。它展现了杜隆塔尔术士们务实而谨慎的思想，尽管过去留下了挥之不去的耻辱，但他们仍试图驾驭虚空来铸就自己的命运。",kw={"杜隆塔尔","纳托克","虚空","tainted tablet","大兽穴","试炼谷","术士"},ang={["class:Warlock"]="Tainted Tablet标志着杜隆塔尔的新手术士们正式被引荐给他们的训练师纳托克，并敦促他们驾驭虚空，而不是恐惧它。",["faction:Horde"]="虽然萨尔领导的新部落对恶魔腐化心存戒备，但潜伏在大兽穴等地方的施法者宣称，他们可以安全地驾驭虚空力量，从而为他们的人民确保未来。",["race:Orc"]="鉴于恶魔契约在德拉诺留下的灾难性遗产，练习邪能魔法在兽人中仍然备受争议，这迫使杜隆塔尔的术士们不得不保持秘密与大胆。"},sec={{t="黑暗的召唤",b="Tainted Tablet是传送给刚抵达试炼谷并开始旅程的见习施法者的一条铭文信息。这块石板经由不安的营地看守人之手，传达了纳托克的召唤，这位术士训练师在大兽穴的阴影角落里安了家。信件邀请读者放下普通的部落职责，去探索更深层、被禁忌的魔法洪流。"},{t="驾驭虚空",b="在回应召唤后，纳托克坦率地谈到了兽人和虚空之间动荡的历史。他认为，强者应当掌控自己的命运，而不是因为羞耻或恐惧而放弃这些不稳定的能量。在他眼中，当传统的酋长们举步维艰时，能够以狡诈手段驾驭虚空实体的施法者将会脱颖而出。然而，由于恐惧者往往会轻易攻击他们无法理解的事物，他警告说，必须时刻严加守护这种力量。"}},faq={{q="什么是Tainted Tablet？",a="Tainted Tablet是传达给试炼谷见习施法者的一份书面召唤。它指示他们去寻找他们的职业训练师纳托克，他就在大兽穴内等候。",al={"什么是tainted tablet","tainted tablet任务","石板的目的"}},{q="谁发送了Tainted Tablet？",a="这块石板由纳托克发送，他是一位驻扎在试炼谷大兽穴内的兽人术士训练师。他用它来向新来的见习施法者介绍自己，并邀请他们接受指导。",al={"谁写了石板","纳托克是谁","谁发送了石板"}},{q="在哪里可以找到纳托克？",a="纳托克居住在大兽穴内，这是一处隐藏在试炼谷中的洞穴，人们在那里远离视线地练习黑魔法和专业技能。",al={"纳托克在哪里","大兽穴在哪里","如何找到纳托克"}},{q="为什么纳托克警告要严加守护你的力量？",a="纳托克告诫说，普通人会恐惧他们无法理解的力量，并经常在恐慌中反击。由于兽人在过去深受恶魔腐化的苦难，术士们必须守护好他们的技艺，并谨慎行事。",al={"为什么术士要隐藏","为什么守护力量","为什么术士要保密"}},{q="纳托克对练习邪能魔法有什么看法？",a="纳托克认为，当传统的领导者举步维艰时，那些掌握了虚空实体的人能够开辟自己的道路，掌握权力来塑造他们人民的命运，而不是成为命运的奴隶。",al={"纳托克的目标是什么","纳托克的哲学","为什么要使用虚空力量"}},{q="谁给了你Tainted Tablet？",a="试炼谷的一位当地任务发布者传递了这块石板，他公开承认对邪能施法者感到不安，但同时也认识到传递纳托克的召唤是必要的。",al={"谁递交了石板","谁把石板交给我"}}},fp="14,197,14.271.0,21.390.0,27.144.0,28.150.0,26.129.0,50.243.0,46.197.0,33.140.0"}
P.entries["quest:98576"] = {n="Glyphic Parchment",s="Glyphic Parchment 是发给在“试炼谷”的法师新手的入门召唤函。这份书面信函由“高内克”转交，指引新手前往“大兽穴”附近的巨魔法师训练师“迈安”处，开始他们的奥术修行。",h="Glyphic Parchment 是发给在“试炼谷”的法师新手的入门召唤函。这份书面信函由“高内克”转交，指引新手前往“大兽穴”附近的巨魔法师训练师“迈安”处，开始他们的奥术修行。",kw={"奥术","杜隆塔尔","glyphic parchment","高内克","法师","迈安","大兽穴","试炼谷"},ang={["class:Mage"]="这封信标志着你正式被认可为一名 A Student of the Arcane，指引你前往“迈安”处开始学习并扩充你的法术书。",["faction:Horde"]="“试炼谷”的导师制确保了即使是奥术这种不稳定的技艺，也能通过纪律来培养，从而加强部落的未来。",["race:Troll"]="“迈安”代表了“暗矛巨魔”日益发展的奥术传统，她贡献出自己的宇宙见解来指导同胞巨魔和盟军新兵。"},sec={{t="学习的召唤",b="虽然新兵要在“杜隆塔尔”的当地害虫面前证明他们的身体素质，但那些拥有奥术天赋的人不能仅仅依靠蛮力。“高内克”会递交一份刻有符文的书面通知，指示法师新手去找“迈安”，由她负责部落新兵早期的魔法指导。"},{t="奥术之道",b="“迈安”驻扎在“大兽穴”入口外，磨练着年轻施法者的志向。她不主张鲁莽地释放原始魔法，而是强调耐心、时机和深思熟虑的智慧。在她的指导下，新手学会将宇宙视为可以编织的纤细丝线，而不是任其爆发的狂暴风暴。"}},faq={{q="谁寄出了 Glyphic Parchment？",a="这份羊皮纸是由位于“试炼谷”的“大兽穴”附近的法师训练师“迈安”发送的。“高内克”保管着这封信，一旦法师新手开始他们的试炼，他就会将其交给他们。",al={"谁写了 glyphic parchment","谁发送了这个","羊皮纸作者"}},{q="在哪里可以找到“迈安”？",a="“迈安”位于“杜隆塔尔”的“试炼谷”，和其他职业导师一起驻扎在“大兽穴”的入口外。",al={"迈安在哪里","迈安的位置","寻找迈安"}},{q="这个任务的目的是什么？",a="它旨在向法师新手介绍他们的职业训练师。与“迈安”对话将开启你对奥术艺术的正规指导，从而解锁新法术和基础训练。",al={"glyphic parchment有什么用","为什么要进行这个任务","任务目标"}},{q="“迈安”对魔法的哲学理念是什么？",a="“迈安”认为奥术魔法需要智慧、克制和审慎的耐心。一位有效的法师不会冲动行事，而是会仔细观察，并在精确的时刻以适当的反应进行攻击。",al={"迈安教什么","迈安的背景故事"}},{q="为什么一位巨魔会在“试炼谷”训练法师？",a="“试炼谷”欢迎年轻的兽人和“暗矛巨魔”加入部落。“暗矛巨魔”施法者，比如“迈安”，贡献出她们的智慧和对宇宙力量的掌控来教导初出茅庐的修行者。",al={"为什么有巨魔法师","巨魔与奥术","兽人地区的巨魔训练师"}},{q="谁把羊皮纸交给玩家？",a="“高内克”是位于“试炼谷”中央营地的主要试炼监督者，当你完成早期任务并返回他身边时，他会把羊皮纸交给你。",al={"谁给予了 glyphic parchment","高内克的任务"}}},fp="17,193,18.283.0,21.309.0,32.116.0,26.102.0,34.173.0,37.139.0,54.173.0,41.138.0"}
P.entries["quest:98581"] = {n="Archaic Rune",s="Archaic Rune是丹莫罗为新手矮人萨满提供的入门任务。这块神圣的石板上灌注了来自远古蛮锤铭文的元素之力，向年轻的入门者们展示了他们的元素传承。将这块石头送到安威玛尔的提奥·蛮锤手中，标志着他们正式开始学习大地、空气、火焰和水的之道。",h="Archaic...",kw={"安威玛尔","archaic rune","铜须","寒脊山谷","元素","萨满","提奥·蛮锤","蛮锤氏族"},ang={["class:Shaman"]="Archaic Rune代表了矮人萨满精神旅程的第一步，验证了他们的元素共鸣，并将他们引向其首位导师。",["faction:Alliance"]="蛮锤导师将萨满艺术带到丹莫罗扩大了联盟的精神修行，使元素传统与圣光之道得以并存。",["race:Dwarf"]="这枚符文标志着矮人氏族间一次重要的文化交流，蛮锤矮人与寒脊山谷的铜须同胞分享了他们古老的精神传统。"},sec={{t="古老的铭文",b="寒脊山谷的冒险新手在安威玛尔附近协助当地盟友后，会发现Archaic Rune。这块石头上刻有蛮锤氏族风格的独特文字，并且可以清晰地感受到其中充盈着远古的元素力量。这枚符文不仅是一件石刻遗物，更是一次元素试炼：只有那些对原始灵魂有着天生共鸣的人，才能解读其风化表面上镌刻的文字。对于那些能够解读这些文字的人来说，它提供了明确的指引，让他们前往附近矮人哨站寻求正式的教导。"},{t="丹莫罗的蛮锤智慧",b="在安威玛尔的大厅内，蛮锤萨满提奥·蛮锤接收了这块铭文石。世世代代以来，萨满元素之术主要由生活在风蚀山峰间的蛮锤氏族所保存。如今，这些传统已开始在铁炉堡和丹莫罗的铜须矮人中扎根。提奥·蛮锤成为了两个矮人文化之间的重要桥梁，他欢迎那些展现出与元素沟通天赋的年轻入门者，并为他们提供关于大地、空气、火焰和水之道的正式教导。"}},faq={{q="什么是Archaic Rune？",a="Archaic Rune是一块刻有古老蛮锤文字并灌注了元素之力的古代石板。它被分发给寒脊山谷中前途无量的新冒险者，作为对其精神潜力的初步考验。如果一名入门者拥有能够解读符文的内在感应，这就证实了他们召唤萨满之道的使命，并指引他们前往安威玛尔寻找训练师。",al={"archaic rune任务","这个符文是什么","archaic rune物品"}},{q="是谁雕刻了Archaic Rune？",a="符文上的铭文是采用蛮锤氏族的传统风格雕刻的。它由居住在安威玛尔内的蛮锤萨满提奥·蛮锤发出，他利用这块刻字石来识别并联系那些拥有与元素灵魂先天连接的新晋入门者。",al={"谁制作了archaic rune","符文起源","蛮锤符文制造者"}},{q="提奥·蛮锤是谁？",a="提奥·蛮锤是一名蛮锤矮人，也是驻扎在寒脊山谷安威玛尔内的萨满训练师。他来到丹莫罗是为了帮助分享其氏族祖传的萨满教义给铜须矮人，指导新的修行者学习大地、火焰、水和空气之道。",al={"提奥·蛮锤是谁","安威玛尔提奥·蛮锤","安威玛尔萨满训练师"}},{q="为什么蛮锤的教义要与铜须矮人分享？",a="虽然萨满艺术在过去很长一段时间里传统上一直由蛮锤氏族保存和守护，但这些元素修行之法最近也已转交到铜须矮人手中并开始普及。像提奥·蛮锤这样的导师挺身而出，教导铁炉堡的矮人如何与元素灵魂沟通并向其致敬。",al={"为什么矮人会成为萨满","铜须蛮锤萨满","矮人萨满背景故事"}},{q="我应该把Archaic Rune带到哪里？",a="符文必须交给位于寒脊山谷安威玛尔主营地内的提奥·蛮锤。向他呈交符文展示了你引导元素的能力，并能开启你后续基础萨满法术的训练。",al={"哪里交还archaic rune","archaic rune交还","寻找提奥·蛮锤"}},{q="解读符文意味着什么？",a="Archaic Rune中灌注了古代矮人文字的元素能量。只有对元素力量有着天生共鸣的入门者才能破译其文字。成功解读它证明了冒险者拥有成为真正萨满的自然天赋和精神准备。",al={"为什么我能读懂符文","符文含义","解读archaic rune"}}},fp="12,371,22.600.0,31.566.0,25.392.0,28.298.0,23.292.0,67.343.0,33.257.0,35.290.0"}
P.entries["quest:986"] = {n="失踪的主人",s="“失踪的主人”这一任务要求联盟冒险者收集材料，以协助寻找在黑海岸荒野中失踪的暗夜精灵沃科尔。奥伯丁的特伦希斯提出要编织一件附魔伪装斗篷来保护救援者，这需要从海岸最凶猛的月夜猛虎身上获取毛皮。",h="“失踪的主人”这一任务要求联盟冒险者收集材料，以协助寻找在黑海岸荒野中失踪的暗夜精灵沃科尔。奥伯丁的特伦希斯提出要编织一件附魔伪装斗篷来保护救援者，这需要从海岸最凶猛的月夜猛虎身上获取毛皮。",kw={"失踪的主人","奥伯丁","黑海岸","优质月夜猛虎毛皮","格里姆克劳","月夜猛虎","特伦希斯","沃科尔","急弯河"},ang={["class:Druid"]="德鲁伊们定能领会特伦希斯对月夜猛虎自然潜行能力的尊重，并将其野性本质转化为保护性的伪装。",["class:Hunter"]="猎人们会理解沃科尔与格里姆克劳之间的羁绊，以及追踪和猎杀黑海岸的雌雄猛虎所需的高超技巧。",["race:NightElf"]="搜寻沃科尔的过程，体现了暗夜精灵在黑海岸那未受开垦的荒野中，守护族人和野生伙伴的职责。"},sec={{t="深入荒野的搜寻",b="在追踪黑海岸沿岸的威胁时，奥伯丁的特伦希斯对沃科尔及其伙伴格里姆克劳的安危感到担忧。由于该地区充斥着好斗的掠食者和受到腐蚀的野生动物，深入南部地区向来极其危险。特伦希斯没有贸然派遣毫无防备的侦察兵，而是制定了一个计划：制作一件灌注了野性幻象的防护斗篷。"},{t="狮群之皮",b="为了编织一件能够迷惑黑海岸野兽的斗篷，普通的兽皮是不够的。特伦希斯需要专门从成年的雄性或雌性月夜猛虎身上获取优质月夜猛虎毛皮。这些强大的大猫在奥伯丁南部的林地，靠近急弯河一带游荡，一直延伸到灰谷的森林边缘。"},{t="精细的魔法",b="成品斗篷利用月夜猛虎的皮毛和自然附魔，让穿着者在搜寻沃科尔时能不受阻碍地穿过敌对区域。然而，特伦希斯警告说，这种幻象十分脆弱：进行剧烈活动或战斗会打破附魔，使搜寻者暴露在外。"}},faq={{q="沃科尔是谁？",a="沃科尔是一位在黑海岸南部荒野失踪的暗夜精灵侦察兵或追踪者。他的伙伴格里姆克劳和奥伯丁的特伦希斯正在寻找他的下落，从而引发了这次搜寻任务。",al={"沃科尔是谁","沃科尔背景故事","失踪的主人沃科尔"}},{q="谁提供了这个任务？",a="特伦希斯，一位驻扎在黑海岸奥伯丁定居点的暗夜精灵，在冒险者协助他处理了早先的当地问题后，便提供了这个任务。",al={"任务发放者","失踪的主人任务领取","特伦希斯位置"}},{q="在哪里可以找到雄性和雌性月夜猛虎？",a="这些成年的月夜猛虎在黑海岸南部游荡，特别是在急弯河河岸附近，以及更南边接近灰谷边界的地方。",al={"优质月夜猛虎毛皮位置","哪里寻找月夜猛虎","急弯河猫科动物"}},{q="这件斗篷有什么作用？",a="特伦希斯打算制作一件附魔斗篷，将穿着者隐藏起来，使其免受黑海岸敌对野兽的攻击，从而能够在不频繁引发战斗的情况下寻找沃科尔。",al={"斗篷有什么作用","特伦希斯斗篷","斗篷附魔"}},{q="为什么特伦希斯需要特定的毛皮？",a="特伦希斯说他需要五张优质毛皮，这些毛皮必须取自雄性或雌性月夜猛虎，这样才有足够的材料来制作斗篷。",al={"为什么是雄性和雌性猛虎","为什么要优质毛皮"}},{q="这种伪装斗篷有限制吗？",a="是的。特伦希斯警告说，这种附魔很脆弱。与他人交谈是允许的，但剧烈的互动或战斗会迅速驱散幻象。",al={"幻象会失效吗","斗篷限制"}}},fp="13,197,23.292.0,18.247.0,14.262.0,14.150.0,21.105.0,49.135.0,30.155.0,39.87.0,43.148.0"}
P.entries["quest:98601"] = {n="A Difficult Path",s="“A Difficult Path”标志着被遗忘者圣骑士在丧钟镇正式开始训练。在处理了从墓穴中爬出来的无脑亡灵后，新觉醒的圣光勇士会被指引去见教堂里的Aramis Hammerhand，去面对在亡灵之躯中使用圣光之力的痛苦现实。",h="“A Difficult Path”标志着被遗忘者圣骑士在丧钟镇正式开始训练。在处理了从墓穴中爬出来的无脑亡灵后，新觉醒的圣光勇士会被指引去见教堂里的Aramis...",kw={"a difficult path","aramis hammerhand","祝圣卷轴","丧钟镇","被遗忘者圣骑士","圣光","暗影牧师萨维斯","提瑞斯法林地"},ang={["class:Paladin"]="这个任务代表了被遗忘者圣骑士的基础试炼，它将圣光之力定义为并非轻松的祝福，而是一场关于纪律和耐力的痛苦磨砺。",["race:Undead"]="对于被遗忘者来说，召唤圣光证明了虔诚与纪律可以在肉体死亡后依然存在，即使这种魔法会灼烧引导它的容器。"},sec={{t="一份发臭的卷轴",b="当一名刚刚苏醒的被遗忘者圣骑士清理完墓穴外的野性亡灵后，暗影牧师萨维斯会递交一份意想不到的物品。这份祝圣卷轴散发出的圣光能量如此强烈，以至于这位暗影牧师明显退缩了，并直截了当地让持有者走开。对于一个信奉暗影与腐朽的修行者来说，圣光本身的气息就像火焰一样灼人。"},{t="圣火的试炼",b="在丧钟镇那座饱经摧残的教堂里，坐镇着被遗忘者圣骑士训练师Aramis Hammerhand。其他种族可以自然且愉悦地运用圣光，但亡灵若想召唤圣光，则必须忍受灼烧般的剧痛。Aramis并未试图减轻这种痛苦：通过腐烂的躯体引导圣光之力是一种纯粹的折磨，但他要求他的弟子拥抱这种痛苦，而不是退缩，将其作为一种淬炼他们新得决心的熔炉。"}},faq={{q="为什么暗影牧师萨维斯不喜欢这份卷轴？",a="暗影牧师萨维斯致力于暗影魔法的研究，并保护着他的亡灵同胞。祝圣卷轴散发着纯粹的圣光能量，这从本质上对亡灵躯体有害，且会让暗影的修行者感到深深的不安。",al={"萨维斯 圣光卷轴","为什么萨维斯感到不安","暗影牧师对卷轴的反应"}},{q="被遗忘者真的能在不死亡的情况下使用圣光吗？",a="被遗忘者可以通过纯粹的意志力和信仰来运用圣光，但这会给他们带来剧烈的痛苦，尤其是在引导圣光治疗自己或他人时。这需要极强的精神耐力来维持引导。",al={"被遗忘者圣骑士背景故事","亡灵使用圣光","圣光会伤害被遗忘者吗"}},{q="谁是Aramis Hammerhand？",a="Aramis Hammerhand是驻扎在丧钟镇教堂的圣骑士训练师。他指导刚复活的被遗忘者圣骑士，教导他们如何在亡灵状态下忍受使用圣光的剧痛，并将其锻造成有效的武器。",al={"谁是aramis hammerhand","丧钟镇圣骑士训练师","aramis的角色"}},{q="这个任务在哪里进行？",a="任务开始于丧钟镇中心空地上的暗影牧师萨维斯，并在几步之遥的村庄废弃教堂内结束，Aramis Hammerhand就在那里。",al={"a difficult path在哪里","任务地点","丧钟镇教堂在哪里"}},{q="我必须阅读祝圣卷轴才能完成任务吗？",a="不需要，阅读卷轴并非完成目标的必要条件；直接与教堂内的Aramis Hammerhand交谈即可推进你的训练。",al={"阅读祝圣卷轴","是否需要阅读卷轴","跳过阅读卷轴"}},{q="为什么这条道路被称为“艰难的”？",a="这个名字反映了被遗忘者圣骑士残酷的修行之路。当圣光的其他战士从信仰中获得安慰与慰藉时，亡灵圣骑士每次施放祝福或打击敌人时，都必须忍受炽热的圣火在死尸躯体中奔涌的痛苦。",al={"为什么是艰难的道路","任务名称的含义"}}},fp="16,235,16.285.0,25.388.0,49.174.0,54.180.0,25.165.0,33.155.0,63.124.0,35.216.0"}
P.entries["quest:98738"] = {n="Blessings of the Great Windborne Cat Spirit",s="Blessings of the Great Windborne Cat Spirit 是一项成年礼任务，标志着受训者在与 Zephras 的 The Great Cat Spirit 交流后的回归。在吸收了野猫的潜行、速度和凶猛之后，受训者向 Dendrite 展示他们新觉醒的光环，以接受进一步的精神指导。",h="Blessings of the Great Windborne Cat Spirit 是一项成年礼任务，标志着受训者在与 Zephras 的 The Great Cat Spirit...",kw={"blessings of the great windborne cat spirit","猫形态","dendrite","德鲁伊","大猫灵","shen'dorei","潜行","zephras"},ang={["class:Druid"]="这个任务标志着掌握猫科掠食本能的一个重要里程碑，赋予了德鲁伊与猫沟通并化身为猫所需的潜行、速度和凶猛。",["race:Skyborne"]="灵魂特别认出受训者是年轻的 shen'dorei，并在他们学习驾驭野性力量时，从 Zephras 提供风与影的指引。"},sec={{t="与风之灵的沟通",b="Blessings of the Great Windborne Cat Spirit 标志着与 Zephras 的 The Great Cat Spirit 进行神圣沟通的顶峰。在寻找到这位风之守护者并赢得其青睐后，受训者回到 Dendrite 身边，展示他们已经内化了野猫的狡黠、掠食者的潜行和凶猛。"},{t="Dendrite 的教导",b="在获得祝福后展示自己时，Dendrite 会进行微妙的身体动作来解读受训者新觉醒的光环。Dendrite 感应到编织在他们灵魂中的猫科动物本能，承认这位候选人终于准备好集中精神，呼唤猫的真正形态。"}},faq={{q="什么是 Blessings of the Great Windborne Cat Spirit？",a="Blessings of the Great Windborne Cat Spirit 是一项成年礼任务，受训者在寻找并获得 The Great Cat Spirit 的祝福后，回到 Dendrite 身边完成他们的精神交流。",al={"这个任务是什么","猫的祝福任务","猫灵任务"}},{q="谁是 Dendrite？",a="Dendrite 是一位导师，他派遣受训者去与 The Great Cat Spirit 沟通。在他们返回后，他会引导仪式手势来感知这种转变，确认受训者是否已经吸收了引导猫科动物天性所需的潜行、速度和狡黠。",al={"谁是dendrite","dendrite背景"}},{q="谁是 The Great Cat Spirit？",a="The Great Cat Spirit 是位于 Zephras 的古老守护灵。它在受训者返回继续接受指导之前，会将精神恩惠、风的速度和掠食者的潜行赐予值得的受训者。",al={"什么是猫灵","大风之猫灵"}},{q="Zephras 位于何处？",a="Zephras 是 The Great Cat Spirit 的家园，也是有前途的受训者前往寻求建议、接受风与影的祝福并学习猫科形态基础知识的地方。",al={"zephras在哪里","猫灵位置"}},{q="为什么灵魂称呼受训者为 shen'dorei？",a="The Great Cat Spirit 直接称呼受训者为年轻的 shen'dorei，这指出了寻求与自然之灵交流并掌握野性变形的修行者的祖先传承。",al={"谁是shendorei","年轻的shendorei"}},{q="猫灵的祝福赋予了什么？",a="这种祝福赋予了猫科形态的狡黠、速度和潜行。在获得祝福后，受训者获得了 Dendrite 的认可，可以集中他们内心的凶猛并呼唤猫的真正本性。",al={"祝福赋予什么","猫灵祝福效果"}}},fp="43,231,35.196.0,22.218.0,52.119.0,16.223.0,28.184.0,25.181.0,55.193.0,47.203.0"}
P.entries["quest:98815"] = {n="Highland Hides",s="Highland Hides是由詹姆斯·哈洛兰委托的一份探险合同，他是一位在米奈希尔港工作的制皮师。为了从高地多雾的山地沼泽中寻求优质的材料，哈洛兰用精制的皮革制品来交换丛林迅猛龙坚韧的皮。",h="Highland Hides是由詹姆斯·哈洛兰委托的一份探险合同，他是一位在米奈希尔港工作的制皮师。为了从高地多雾的山地沼泽中寻求优质的材料，哈洛兰用精制的皮革制品来交换丛林迅猛龙坚韧的皮。",kw={"highland hides","高地","詹姆斯·哈洛兰","米奈希尔港","迅猛龙皮","制皮师","丛林迅猛龙","湿地"},ang={["class:Hunter"]="进入高地山地沼泽的猎人们会发现丛林迅猛龙这样的可怕野兽，它们坚韧的皮需要精准的追踪和干净利落的狩猎技巧。",["faction:Alliance"]="米奈希尔港是湿地的一个主要联盟港口，像詹姆斯·哈洛兰这样的商人们就在这里为前往周围危险沼泽的旅行者提供装备。"},sec={{t="制皮师的机会",b="詹姆斯·哈洛兰是一位在米奈希尔港口小镇工作的熟练制皮师，他一直在留意异域的制作材料。当听说有一支探险队正在高地探索被遗忘的遗迹时，哈洛兰没怎么去关注古代历史，反而更在意那些在山地沼泽中潜行的凶猛野兽。他敏锐地察觉到了这些野生动物的商业和制作价值，于是委托勇敢的冒险者深入迷雾笼罩的山峰，带回上等的毛皮。"},{t="高地的野兽",b="在高地潜伏的动物群中，丛林迅猛龙是以适应崎岖沼泽地形而闻名的掠食者。它们坚韧且纹理独特的皮深受工匠的喜爱，可用于专业的皮革加工。哈洛兰指派旅行者追踪这些生物，并带回四张完好的皮，他将用这些皮为自己工作室的作品制作精致的细节装饰和边缘饰品。"}},faq={{q="詹姆斯·哈洛兰是谁？",a="詹姆斯·哈洛兰是一位驻扎在米奈希尔港的当地制皮师和工匠。他从事皮革和油脂加工，寻找来自湿地和周围高地的奇异野兽的优质皮，以此来制作精美的饰边和护甲。",al={"谁发布了highland hides任务","詹姆斯·哈洛兰是谁","米奈希尔港的制皮师"}},{q="为什么詹姆斯·哈洛兰需要这些皮？",a="哈洛兰寻求丛林迅猛龙的皮，是因为它们出色的耐用性和纹理。他认为这些是他经手过的最好的皮革之一，并用它们为皮制品的饰边增添了惊人的细节。",al={"highland hides的用途","为什么詹姆斯需要迅猛龙皮","迅猛龙皮的用途"}},{q="在哪里可以找到丛林迅猛龙？",a="丛林迅猛龙栖息在高地的山地沼泽中，潜伏在探险队目前正在考察的古代遗迹附近的崎岖荒野中。",al={"丛林迅猛龙在哪里","丛林迅猛龙位置","迅猛龙在哪里"}},{q="哈洛兰提到的遗迹是什么？",a="高地拥有一处被遗忘的遗迹，目前正由一支探险队进行调查。虽然像哈洛兰这样的工匠关注的是野生动物，但学者和探险家们却深入研究了该地区的古代秘密。",al={"高地有什么遗迹","高地探险遗迹","谁在探索高地"}},{q="这次狩猎是为团队准备的吗？",a="哈洛兰建议带上装备精良的同伴。高地的山地沼泽栖息着凶猛的野生动物，这使得针对丛林迅猛龙这类掠食者的狩猎对于孤身一人的旅行者来说危机四伏。",al={"highland hides是否危险","highland hides需要组队吗","做highland hides需要同伴吗"}},{q="詹姆斯·哈洛兰提供什么交易？",a="为了换取四张原始的丛林迅猛龙皮，哈洛兰会提供他工作室定制的优质皮制品，让冒险者可以选择一件适合他们旅程的装备。",al={"哈洛兰交易什么","highland hides奖励背景"}}},fp="14,272,22.488.0,23.393.0,22.231.0,41.212.0,35.172.0,36.217.0,34.216.0,40.187.0"}
P.entries["quest:98824"] = {n="Prehistoric Prism",s="Prehistoric Prism是一个探索任务，引导冒险者将一件多面的泰坦圣物从湿地运送到铁炉堡。受勘察员维尔加所托，这件圣物被捐赠给了位于探险者大厅的高级探险家麦格拉斯，以推进探险者协会对古代守护者的研究。",h="Prehistoric Prism是一个探索任务，引导冒险者将一件多面的泰坦圣物从湿地运送到铁炉堡。受勘察员维尔加所托，这件圣物被捐赠给了位于探险者大厅的高级探险家麦格拉斯，以推进探险者协会对古代守护者的研究。",kw={"hall of explorers","高级探险家麦格拉斯","铁炉堡","prehistoric prism","勘察员维尔加","泰坦圣物","奥达曼","湿地"},ang={["faction:Alliance"]="捐赠发现的古代宝藏能直接丰富铁炉堡著名的探险者大厅的学术收藏。",["race:Dwarf"]="找回真正的泰坦圣物是矮人身份认同的核心，也是探险者协会揭示其制造者起源这一使命的关键。"},sec={{t="古老的发现",b="在勘测湿地时，勘察员维尔加发现了一件非凡的文物，其刻面上装饰着复杂的守护者铭文。这位矮人勘察员认识到，如此具有历史意义的发现应当交到学者手中，因此他极力敦促立即将其运送到矮人主城铁炉堡。维尔加希望这次发现能被正式编入目录，确保冒险者在圣物鉴定过程中获得应有的功绩。"},{t="博物馆的馈赠",b="在探险者大厅那充满传奇色彩的大厅内，高级探险家麦格拉斯代表探险者协会接收了这件圣物。这位首席考古学家对圣物上真实的制造者印记赞叹不已，并指出光线穿过其打磨过的刻面时呈现出的折射效果，让他回想起了自己早年在奥达曼挖掘时所见到的奇观。捐赠这件文物能将其妥善保存以供研究，从而扩充探险者协会不断增长的泰坦遗产记录。"}},faq={{q="谁发布了Prehistoric Prism任务？",a="勘察员维尔加在湿地鉴定了圣物刻面上发现的类似泰坦的铭文后，指引你将其送往铁炉堡。",al={"谁发布了prehistoric prism","prehistoric prism起始地点","prehistoric prism任务发布者"}},{q="你在哪里交付Prehistoric Prism？",a="你将这件圣物交付给位于铁炉堡探险者大厅的高级探险家麦格拉斯，他非常乐意将其收入博物馆的藏品中。",al={"prehistoric prism交付对象","prehistoric prism交付地点","prehistoric prism完成情况"}},{q="Prehistoric Prism是什么类型的文物？",a="这是一件古老的多面文物，带有明显的守护者印记。当被光照亮时，光线在其晶体结构中舞动的方式，令人想起在奥达曼出土的圣物。",al={"什么是prehistoric prism","prehistoric prism是否属于泰坦","什么是该圣物"}},{q="为什么探险者大厅对这个棱镜感兴趣？",a="探险者协会积极收集和编目泰坦起源的真迹。高级探险家麦格拉斯认为，这种级别的文物对于增进世界知识和理解古代历史至关重要。",al={"为什么麦格拉斯想要它","为什么要捐赠棱镜","探险者大厅棱镜"}},{q="这个棱镜与奥达曼有何关联？",a="在检查了文物的折射效果和守护者标记后，高级探险家麦格拉斯将其闪烁的光芒与他在奥达曼进行的第一次考古挖掘中所研究的圣物进行了比较。",al={"奥达曼是否与该棱镜有关","奥达曼联系","棱镜奥达曼"}},{q="你的名字会被记录在博物馆的目录中吗？",a="勘察员维尔加和高级探险家麦格拉斯确保你找回圣物的功绩被正式认可，并记录在探险者协会的历史档案中。",al={"prehistoric prism目录","你会被记录在案吗","历史功绩棱镜"}}},fp="17,165,20.384.0,20.365.0,38.139.0,43.133.0,47.169.0,53.172.0,37.166.0,54.133.0"}
P.entries["quest:98895"] = {n="Darkspear Islands Clash",s="Darkspear Islands Clash 是联盟的一项军事征召令，号召勇士们防守关键阵地，抵御凶猛的暗矛突袭者。如果前线得不到及时的支援，联盟将面临彻底失去这片争议群岛的风险。",h="Darkspear Islands Clash 是联盟的一项军事征召令，号召勇士们防守关键阵地，抵御凶猛的暗矛突袭者。如果前线得不到及时的支援，联盟将面临彻底失去这片争议群岛的风险。",kw={"联盟","战场","准将","暗矛群岛","darkspear islands clash","暗矛突袭者","荣誉印记"},ang={["class:Paladin"]="联盟的圣职战士们带着坚定的决心投入到激烈的冲突中，响应号召，保卫联盟的生命，击退敌对势力。",["class:Warrior"]="前线战士在抵御凶猛的巨魔突袭者时承受着巨大的压力，他们用铁的纪律和战场上的英勇扭转了战局。",["faction:Alliance"]="联盟最高指挥部依靠勇士志愿者来加强前线对抗暗矛突袭者，并保卫群岛上的战略阵地。"},sec={{t="争议前线",b="为了争夺暗矛群岛的控制权，联盟与好战的暗矛突袭者战团之间爆发了公开战争。联盟指挥官警告称，若无紧急援军，他们在群岛的立足点将会失守，因此发出了战斗征召，号召有能力的勇士前来抵挡敌人的攻势。"},{t="英勇的证明",b="联盟指挥层依靠那些愿意直接奔赴前线的实战勇士。为了确保纪律并嘉奖真正的英雄主义，指挥官要求战士们带回暗矛群岛荣誉印记，以此作为他们战斗服役的切实证明，表彰那些扭转战局的人。"}},faq={{q="什么是 Darkspear Islands Clash？",a="Darkspear Islands Clash 是由负责前线战事的联盟军官发布的一项军事征召令。联盟勇士的任务是与暗矛突袭者交战，并通过从战斗中收集荣誉印记来证明自己的贡献。",al={"什么是 darkspear islands clash","冲突任务","暗矛群岛之战"}},{q="谁是暗矛突袭者？",a="暗矛突袭者是争夺暗矛群岛控制权的巨魔战团。他们咄咄逼人的攻势威胁到了联盟在该地区的立足点，迫使最高指挥部发出紧急援军请求。",al={"谁是暗矛突袭者","暗矛突袭者敌人","我们在暗矛群岛对抗谁"}},{q="为什么联盟要在暗矛群岛作战？",a="联盟试图守住暗矛群岛的战略领土，防止该地区完全落入巨魔的控制之下。如果失去这片阵地，将危及联盟在这一争议海域的影响力和安全。",al={"为什么联盟在暗矛群岛作战","为什么要在这里作战","联盟暗矛战争"}},{q="谁来发布并完成这项任务？",a="一名驻扎在战场之外的联盟准将负责监督部队调动，并接收返程勇士提交的战场服役证明。",al={"谁发布 darkspear islands clash","谁收取暗矛荣誉印记","联盟准将位置"}},{q="什么是暗矛群岛荣誉印记？",a="荣誉印记是颁发给在前线表现出英勇和积极参与战斗的战士的军事代币。向联盟准将提交三枚此类印记，即是证明你战场贡献的确凿证据。",al={"什么是荣誉印记","暗矛群岛荣誉印记","如何证明前线服役"}},{q="如果联盟失败，会有什么后果？",a="如果没有迅速的增援，联盟在暗矛群岛的阵地将无法承受暗矛突袭者无情的压力而全面崩溃。守住群岛可以防止敌方部队确立对整个群岛的统治地位。",al={"如果联盟输掉暗矛群岛会发生什么","为什么需要紧急援助","失去暗矛群岛"}}},fp="23,242,17.337.0,14.308.0,32.280.0,30.215.0,54.233.0,38.161.0,42.236.0,39.257.0"}
P.entries["quest:98896"] = {n="Darkspear Islands Clash",s="Darkspear Islands Clash呼吁战士们集结同伴，击败那些争夺群岛的敌对暗矛突袭者。持续不断的战斗需要协同行动，以遏制敌人对争议岛屿链的入侵。",h="Darkspear Islands Clash呼吁战士们集结同伴，击败那些争夺群岛的敌对暗矛突袭者。持续不断的战斗需要协同行动，以遏制敌人对争议岛屿链的入侵。",kw={"冲突","暗矛群岛","暗矛突袭者","群岛冲突","集结","小规模冲突","巨魔突袭者"},ang={["faction:Horde"]="这是联盟一方为暗矛群岛进行的战斗，这些位于卡利姆多海岸外的神圣巨魔群岛一直被部落占据，以抵御所有外来者。",["race:Troll"]="对于巨魔冒险者来说，这份联盟指令所针对的暗矛突袭者正是沃金的族人，他们正在保卫自己部族的神圣岛屿。"},sec={{t="战火中的群岛",b="Darkspear Islands Clash代表了在争议不断的暗矛群岛内进行的一次主动军事推进。部署到该战区的部队被敦促坚守阵地，抵御一波又一波持续在海滩和内陆地区发动小规模冲突的暗矛突袭者。这场冲突并非孤立事件，而是确保在群岛中据点领土的持久战役的一部分。"},{t="集结前线",b="前线的指挥官们强调了组织和兵力对于战胜顽强突袭者的必要性。生存和胜利取决于将附近的盟友集结成一支有凝聚力的部队，这支部队必须有能力抵御反击、击溃筑防的突袭小队，并打破他们对争议岛屿据点的控制。"}},faq={{q="什么是Darkspear Islands Clash？",a="Darkspear Islands Clash是一项任务，呼吁冒险者们在暗矛群岛持续不断的冲突中集结盟友，并对敌对的暗矛突袭者发起进攻。",al={"任务简述","darkspear islands clash摘要","冲突任务信息"}},{q="这场战斗发生在什么地方？",a="这场小规模冲突发生在暗矛群岛各地，这是一片因激烈的领土争夺和持续的海上冲突而闻名的群岛。",al={"战斗发生地","暗矛群岛位置","冲突地点"}},{q="谁是暗矛突袭者？",a="暗矛突袭者是部落在暗矛群岛的巨魔守卫，这些群岛是沃金部族的神圣岛屿。指令要求战斗人员在他们争夺岛屿领土时击败他们。",al={"敌方是谁","对抗目标","暗矛突袭者目标"}},{q="为什么必须为这场冲突集结部队？",a="冲突需要召集和集结盟军部队，以抵御持续的反击并击破敌方突袭者的防线。",al={"为什么要集结部队","任务目标","如何完成冲突"}},{q="为什么暗矛群岛的战斗会持续不断？",a="部落和联盟在这些岛屿据点的争夺中陷入了僵局：部落将这里作为神圣的巨魔领地进行守卫，而联盟则试图在卡利姆多海岸外建立一个据点。",al={"为何开战","岛屿冲突原因","群岛战斗起因"}},{q="是谁在指挥这次交战的部队？",a="该指令由奥特兰克山脉的联盟准将发布，敦促地面士兵毫不动摇地向前推进。",al={"任务发布者","冲突任务发布人","冲突指挥官"}}},fp="23,244,22.393.0,23.328.0,36.187.0,33.138.0,30.209.0,42.141.0,53.198.0,42.147.0"}
P.entries["quest:99"] = {n="阿鲁高的愚行",s="“阿鲁高的愚行”是一项危险的调查任务，旨在探究困扰焚木村的诅咒。达拉尔·道恩维沃尔派遣部落特工从村民身上获取附魔镣铐，以解读大法师阿鲁高扭曲的杰作。解开这些束缚，就能揭示让这个定居点处于狼人阴影之下的悲剧魔法。",h="“阿鲁高的愚行”是一项危险的调查任务，旨在探究困扰焚木村的诅咒。达拉尔·道恩维沃尔派遣部落特工从村民身上获取附魔镣铐，以解读大法师阿鲁高扭曲的杰作。解开这些束缚，就能揭示让这个定居点处于狼人阴影之下的悲剧魔法。",kw={"阿鲁高","arugal's folly","达拉尔·道恩维沃尔","月怒狼人","焚木镣铐","焚木村","银松森林","瑟伯切尔"},ang={["class:Mage"]="对于奥术修行者来说，阿鲁高的镣铐是一个冷酷的提醒，告诫他们当肯瑞托的魔法与异界召唤的野兽混合时，可能会陷入何等的疯狂。",["faction:Horde"]="获得这些镣铐打破了阿鲁高对通往格雷迈恩之墙南下道路的神秘控制。",["race:Undead"]="被遗忘者以冰冷的着迷和无情的实用主义看待焚木村，渴望拆除阿鲁高的附魔以确保银松森林南部的安全。"},sec={{t="焚木村的双重生活",b="瑟伯切尔以南是焚木村，这是一个处于诡异存在状态的定居点。在白昼的阳光下，居民们像普通人类农民一样过着恐惧而封闭的生活。然而，当黄昏降临森林时，他们的人类形态就会撕裂，变成野蛮的月怒狼人，在阿鲁高的支配下在街上游荡。达拉尔·道恩维沃尔试图解开导致这种昼夜恐怖的精确奥术束缚。"},{t="粉碎镣铐",b="为了分析束缚焚木村的附魔，道恩维沃尔需要从变身的城镇居民身上直接取得附魔的“焚木镣铐”。这些枷锁并非简单的铁制品，它们震颤着阿鲁高失败结界的残余魔法。通过研究其奥术构成，这位被遗忘者法师希望理解这种野兽般变形的机制，并设法最终打倒影牙城堡的那位叛逃大法师。"}},faq={{q="为什么焚木村的人在晚上会变成狼人？",a="大法师阿鲁高在焚木村施加了扭曲的附魔。白天，他的咒语维持着人类的幻象或沉睡状态，但夜幕降临会导致城镇居民在他的控制下变身为月怒狼人。",al={"焚木村昼夜","焚木村诅咒","为什么白天是人晚上是狼"}},{q="什么是“焚木镣铐”？",a="它们是被诅咒的焚木村居民所佩戴的附魔束缚。阿鲁高将它们作为他控制该镇魔法的一部分，而达拉尔·道恩维沃尔则利用其残余能量来研究这一诅咒。",al={"焚木镣铐","阿鲁高镣铐"}},{q="达拉尔·道恩维沃尔是谁？",a="达拉尔·道恩维沃尔是一位驻扎在银松森林瑟伯切尔的被遗忘者法师。他负责领导被遗忘者对大法师阿鲁高召唤的狼人进行的魔法调查。",al={"达拉尔·道恩维沃尔背景故事","瑟伯切尔的任务发放者是谁"}},{q="完成这个任务能治愈焚木村吗？",a="不能。取回的镣铐为达拉尔·道恩维沃尔提供了理解阿鲁高魔法所需的奥术见解，但诅咒依然让焚木村处于永恒的折磨之中。",al={"焚木村可以被治愈吗","焚木村的人民会被治愈吗"}},{q="阿鲁高是如何控制村民的？",a="通过鲁莽的附魔和附魔镣铐，阿鲁高将村民束缚在他的意志之下，强迫他们变成守护他影牙城堡领地入口的野兽形态。",al={"阿鲁高与焚木村的联系","阿鲁高如何控制他们"}},{q="完成“阿鲁高的愚行”任务线后会发生什么？",a="此项任务标志着“阿鲁高的愚行”系列任务的最终章。所收集的情报使被遗忘者能够全面评估影牙城堡的威胁，并策划阿鲁高的垮台。",al={"阿鲁高的愚行之后","阿鲁高的愚行结局"}}},fp="14,205,26.329.0,23.356.1,64.164.0,31.212.0,24.160.0,48.140.1,38.161.0,61.157.1"}
P.entries["quest:990"] = {n="灰谷之旅",s="“前往灰谷”是一项联盟的旅程任务，指引经验丰富的冒险者从黑海岸向南进入灰谷的原始森林。哨兵塞拉伊前来奥伯丁寻求援助，并指派旅行者前往阿斯特兰纳镇向莱恩·狼行者报到，当地的哨兵正努力对抗蔓延的腐蚀。",h="“前往灰谷”是一项联盟的旅程任务，指引经验丰富的冒险者从黑海岸向南进入灰谷的原始森林。哨兵塞拉伊前来奥伯丁寻求援助，并指派旅行者前往阿斯特兰纳镇向莱恩·狼行者报到，当地的哨兵正努力对抗蔓延的腐蚀。",kw={"灰谷","阿斯特兰纳","黑海岸","暗夜精灵","莱恩·狼行者","哨兵塞拉伊","前往灰谷"},ang={["faction:Alliance"]="作为一名联盟勇士，响应阿斯特兰纳的呼唤可以加强与暗夜精灵的联系，并巩固该阵营在卡利姆多北部的核心立足点。",["race:NightElf"]="对于暗夜精灵来说，这段旅程是回归卡利姆多的神圣中心地带，响应姐妹们的呼唤，保护古老圣地免受非自然腐烂的侵蚀。"},sec={{t="离开海岸",b="响应了哨兵塞拉伊在奥伯丁发出的援助请求后，旅行者们将告别阴郁灰暗的海岸和阴影笼罩的遗迹。哨兵认可那些拥有自保能力的强大战士和侦察兵，并直接指引他们前往暗夜精灵林地领土的中心地带。在解决了黑海岸的地方威胁后，注意力转向了从南方入侵的更严峻的危机。"},{t="通往阿斯特兰纳的路",b="向南的道路沿着一条古老的暗夜精灵之路蜿蜒而行，穿过灰谷茂密的古老树冠。驻扎在阿斯特兰纳的哨兵指挥官莱恩·狼行者发出了紧急的增援呼吁。在恶魔的玷污、猖獗的野生动物以及对祖地的外部入侵之间，阿斯特兰纳的哨兵们兵力不足，需要外部援助来维持对这片神圣森林的控制。"}},faq={{q="是谁让你踏上这段旅程？",a="哨兵塞拉伊，一位被莱恩·狼行者派往奥伯丁寻求帮助的暗夜精灵哨兵，指引你向南前往阿斯特兰纳。",al={"任务发布者","谁开启前往灰谷任务","塞拉伊"}},{q="莱恩·狼行者是谁？",a="莱恩·狼行者是常驻阿斯特兰纳的首席哨兵指挥官，负责组织灰谷的防御，并协调各方努力以遏制侵蚀森林的腐化。",al={"莱恩","狼行者","阿斯特兰纳领袖"}},{q="为什么要派冒险者去灰谷？",a="灰谷的古老森林正屈服于蔓延的腐化和日益增加的外部威胁。当地的暗夜精灵哨兵已不堪重负，迫切需要有能力的盟友来协助阿斯特兰纳的市民和保卫者。",al={"为什么去灰谷","灰谷发生了什么","灰谷腐化"}},{q="黑海岸和灰谷之间的道路安全吗？",a="哨兵塞拉伊特别建议紧贴大路行走。偏离路径深入森林会使旅行者暴露在徘徊于荒野边缘的凶猛掠食者、萨特和敌对势力面前。",al={"道路安全","灰谷道路安全吗"}},{q="到达阿斯特兰纳后我该做什么？",a="在直接向莱恩·狼行者报到后，她建议与阿斯特兰纳各处的其他居民和保卫者交谈，因为他们中有许多人需要即时的帮助来处理当地的危机。",al={"在阿斯特兰纳做什么","到达阿斯特兰纳"}},{q="这项任务适合什么等级的冒险者？",a="这段旅程通常标志着在19级左右从黑海岸毕业，将中级冒险者带入灰谷这个更广阔且充满争夺的前线。",al={"什么等级","等级要求"}}},fp="17,168,17.330.0,21.328.0,27.126.0,24.154.0,44.198.0,49.151.0,44.178.0,46.166.0"}
P.entries["quest:99046"] = {n="The Lost Runner",s="The Lost Runner是一项搜寻哨兵艾露亚·影叶的任务，她是一位从The Oracle Tree出发、逾期未归的信使学徒。这项任务至关重要，因为这棵神圣之树与达纳苏斯的长老们之间的联络对于暗夜精灵的领导层来说必不可少。",h="The Lost Runner是一项搜寻哨兵艾露亚·影叶的任务，她是一位从The Oracle...",kw={"森林议会","达纳苏斯","艾露亚·影叶","神谕林地","the oracle tree","哨兵","the lost runner"},ang={["faction:Alliance"]="维护泰达希尔境内安全畅通的道路和通讯线路，有助于保障达纳苏斯和联盟领土的稳定。",["race:NightElf"]="确保古老的The Oracle Tree与达纳苏斯领导层之间的安全通讯，对于卡多雷的安全和精神指引至关重要。"},sec={{t="神谕者的信使",b="森林议会在泰达希尔受人尊敬的神谕林地中驻扎了一支哨兵小队。这棵树负责向暗夜精灵的长老们传达神圣的信息，并依靠忠诚的信使沿着蜿蜒的林间道路将这些信件送回达纳苏斯。确保这些信件安全送达，对于卡多雷的指引和统治至关重要。"},{t="逾期的信使",b="来自The Oracle Tree的信息传递时间并不固定，但如果信使久久未现身，这种异常的沉默会引起警觉。最近一次任务落在了哨兵艾露亚·影叶身上，她还是一名正在接受训练的学徒。她的上级担心她在路上遭遇了不幸，因此指示旅行者搜寻通往神谕林地的西向道路，以确定她的下落。"}},faq={{q="迷失的信使是谁？",a="失踪的信使是哨兵艾露亚·影叶，她是一位正在受训的暗夜精灵哨兵，任务是将来自The Oracle Tree的信息送往达纳苏斯。",al={"谁是迷失的信使","失踪的哨兵","谁是艾露亚"}},{q="什么是The Oracle Tree？",a="The Oracle Tree是位于神谕林地的一棵古树，它会定期向达纳苏斯的暗夜精灵长老传达信息，需要驻扎的哨兵安全地进行传递。",al={"什么是the oracle tree","神谕林地的目的","为什么要有来自the oracle tree的信息"}},{q="艾露亚·影叶要去哪里？",a="艾露亚原本应该出现在连接达纳苏斯和神谕林地的西向道路上，信使经常往返于该路段，传递来自该树的交流信息。",al={"艾露亚要去哪里","艾露亚的路线","迷失的信使位置"}},{q="是谁将哨兵驻扎在The Oracle Tree？",a="森林议会指派了一支哨兵分遣队前往The Oracle Tree，以确保信息能够安全、迅速地传达给达纳苏斯的长老们。",al={"谁派哨兵去the oracle tree","什么是森林议会"}},{q="为什么她的失踪令人担忧？",a="虽然来自The Oracle Tree的信息传递频率不固定，但她的缺席时间已经长得反常，考虑到她学员的身份，这引起了她上级的担忧。",al={"为什么她的延误不寻常","神谕多久发送一次信息"}},{q="这项搜寻任务的目标是什么？",a="你需要沿着通往神谕林地的西向小路前进，搜寻哨兵艾露亚·影叶，找出是什么延误了她的行程。",al={"在the lost runner中要做什么","the lost runner任务目标"}}},fp="15,238,24.380.0,18.378.0,23.164.0,24.189.0,36.160.0,47.157.0,29.162.0,37.141.0"}
P.entries["quest:99047"] = {n="Not Dead Yet",s="“Not Dead Yet”是Eralya发出的紧急呼救，她是一名受了致命伤的暗夜精灵，在前往The Oracle Tree的灾难性任务后被发现。她被凶残的鹰身人袭击，恳求过路人将她巡逻队遭遇的命运转达给多兰纳尔的Byancie。这凸显了泰达希尔林间小径上日益逼近的致命威胁。",h="“Not Dead Yet”是Eralya发出的紧急呼救，她是一名受了致命伤的暗夜精灵，在前往The Oracle...",kw={"byancie","多兰纳尔","eralya","鹰身人","not dead yet","the oracle tree","泰达希尔"},ang={["faction:Alliance"]="当外勤侦察兵被阻断并陷入重围时，探索泰达希尔的联盟冒险者受命将紧急消息带回多兰纳尔这样的定居点前哨。",["race:NightElf"]="倒下的信使Eralya和她的姐妹们是在泰达希尔服役的哨兵。目睹暗夜精灵守卫在神圣的The Oracle Tree附近遭到鹰身人伏击，这直接揭示了这片巨枝之上日益严重的威胁。"},sec={{t="遭到伏击的巡逻队",b="“Not Dead Yet”是泰达希尔荒野中的绝望呼救，故事围绕Eralya展开，她是一名受了伤的暗夜精灵信使，被发现时正流血不止，生命垂危。她与姐妹们一同被派往神圣的The Oracle Tree执行一项关键任务，但在途中遭到了入侵的鹰身人的暴力伏击并被屠戮。援军无望，且体力迅速衰竭，Eralya只能委托过路的旅行者将紧急消息带回安全地带。"},{t="呼唤多兰纳尔",b="Eralya大口喘着气，并不时咳血，她恳求玩家将她的报告带给附近多兰纳尔村的Byancie。那些盘踞在泰达希尔巨枝之上的鹰身人变得越来越大胆和具有攻击性，对那些试图穿越林间小径的独行信使和哨兵构成了致命威胁。传递Eralya的求救信息能确保多兰纳尔定居点在更多生命逝去之前，获知关于The Oracle Tree伏击事件的消息。"}},faq={{q="Eralya是谁？",a="Eralya是一名在前往The Oracle Tree执行任务途中遭到伏击的暗夜精灵哨兵或信使。她生命垂危，咳血不止，恳求过路的冒险者在她的生命走到尽头之前，带去关于她小队命运的消息。",al={"eralya是谁","eralya任务","垂死的暗夜精灵"}},{q="什么是The Oracle Tree？",a="The Oracle Tree是位于泰达希尔神谕林地的一处古老地标。Eralya和她的姐妹们在前往那里的途中，带着一封紧急信件时被敌方压制。",al={"什么是the oracle tree","神谕林地之树","eralya要去哪里"}},{q="Eralya和她的巡逻队发生了什么事？",a="Eralya和她的姐妹们遭到了盘踞在泰达希尔枝叶间的鹰身人的伏击并被其压制。这些生物蜂拥而至，屠戮了巡逻队，并将Eralya打成重伤。",al={"谁袭击了eralya","谁伏击了她","eralya为什么在流血"}},{q="Byancie是谁？",a="Byancie是驻扎在暗夜精灵村庄多兰纳尔的一名联络人。Eralya急切地要求将鹰身人伏击和巡逻队困境的消息直接带给Byancie。",al={"byancie是谁","byancie在哪里","byancie 多兰纳尔"}},{q="Eralya的消息必须送到哪里？",a="多兰纳尔是位于泰达希尔幽影谷以南道路旁的主要暗夜精灵村庄。Byancie居住在那里，负责接收报告并协调当地的防御工作。",al={"消息送到哪里","eralya的传信","多兰纳尔在哪里"}},{q="执行任务的其他姐妹们发生了什么事？",a="Eralya的暗夜精灵哨兵同伴在凶残的鹰身人突袭中失散或阵亡。由于看不到援军，Eralya担心她的姐妹中无人能从这场屠杀中幸免。",al={"eralya的姐妹们发生了什么","哨兵巡逻队姐妹"}}},fp="12,332,18.433.0,18.460.0,14.233.0,24.184.0,39.196.0,15.178.0,41.186.0,50.188.0"}
P.entries["quest:99048"] = {n="A Missing Hand",s="A Missing Hand是杜隆塔尔的一项任务，内容涉及Shattered Hand侦察兵Heglan Shadeeye的突然失踪。她原本的任务是负责监视提拉加德城堡。在她的常规情报报告突然中断后，一位调查员被派去寻找她的岗哨，以查明究竟是什么让她噤声。",h="A Missing Hand是杜隆塔尔的一项任务，内容涉及Shattered Hand侦察兵Heglan...",kw={"a missing hand","杜隆塔尔","heglan shadeeye","潜行者","侦察兵","shattered hand","提拉加德城堡"},ang={["class:Rogue"]="Shattered Hand是部落隐秘的脊梁和情报公会。调查一名失踪特工的情况，足以证明他们的实地监视任务有多么危险。",["faction:Horde"]="监视提拉加德城堡的库尔提拉斯残余势力对于杜隆塔尔的安全至关重要，而一名侦察兵无法解释的失踪，预示着奥格瑞玛家门口可能存在着尚未察觉的威胁。",["race:Orc"]="杜隆塔尔是新近稳固的兽人领土，让一名特工在附近人类居住者的眼皮底下失踪，引起了对王国安全的高度警惕。"},sec={{t="沉默的报告",b="A Missing Hand的起因是人们对Shattered Hand侦察兵Heglan Shadeeye日益增长的担忧。她被派驻在杜隆塔尔，从远处监视占领提拉加德城堡的敌对人类驻军，但她持续的情报报告却毫无预兆地中断了。她的上级怀疑人类士兵是否真的成功发现并抓获了她，担心是有意想不到且更危险的威胁介入了。冒险者们被派往城堡以北寻找她的岗哨，以确定这次中断仅仅是通讯延迟，还是有更可怕的事情发生。"},{t="寒冷的小屋",b="到达提拉加德城堡以北指定的观察哨后，搜寻工作以悲剧告终。Heglan冰冷的尸体躺在一间破败小屋的碎片之中。留下的实物证据表明，袭击者并非人类，这留下了一个令人不安的疑问：究竟是什么生物或实体在如此靠近部落领土的地方击杀了一名训练有素的特工？散落在残骸附近的线索暗示了一种必须被揭开的陌生威胁。"}},faq={{q="什么是A Missing Hand任务？",a="A Missing Hand是杜隆塔尔的一项任务，冒险者需要寻找Shattered Hand侦察特工Heglan Shadeeye，她原本驻扎在提拉加德城堡以北，但她的常规情报报告突然中断了。",al={"a missing hand是什么","a missing hand任务概览"}},{q="Heglan Shadeeye是谁？",a="Heglan Shadeeye是一名Shattered Hand特工，任务是从附近的有利位置秘密监视提拉加德城堡。她的监视报告突然中断，促使人们对她的下落展开调查。",al={"heglan是谁","heglan shadeeye在哪里","失踪的侦察兵"}},{q="Heglan Shadeeye发生了什么事？",a="这正是本任务要查明的内容。她从提拉加德城堡以北的岗哨发回的报告毫无预警地中断了，派你去执行任务的人怀疑人类士兵并没有抓获她，而是担心有更危险的事情正在发生。",al={"heglan shadeeye发生了什么","heglan死了吗","heglan的命运"}},{q="什么是Shattered Hand？",a="在现代部落中，Shattered Hand是一个由隐秘特工、刺客和间谍组成的组织。他们执行秘密监视和情报行动，以保护部落领土。",al={"什么是shattered hand","shattered hand是什么组织"}},{q="提拉加德城堡的人类杀害了Heglan吗？",a="她的上级对此表示怀疑。尽管Heglan一直在监视占领提拉加德城堡的敌对库尔提拉斯人类，但委派你任务的人不相信他们能抓住她，并担心有更危险的事情在发生。",al={"是人类杀了heglan吗","是提拉加德的士兵杀了她吗"}},{q="为什么要监视提拉加德城堡？",a="提拉加德城堡是敌对的库尔提拉斯水兵和士兵占据的据点，威胁着杜隆塔尔的海岸。Heglan被派驻在附近以密切关注他们的行动，并将情报传回部落。",al={"为什么heglan要监视提拉加德城堡","提拉加德城堡监视"}}},fp="14,289,14.588.0,12.461.1,33.223.0,23.220.0,33.218.0,27.202.0,45.228.0,37.212.0"}
P.entries["quest:99049"] = {n="Threat from Below",s="Threat from Below是一个部落任务，核心内容是调查杜隆塔尔东海岸发生的一起暴力伏击事件。在哨兵赫格兰·暗眼于她的哨岗遭遇猛烈的小规模袭击后，冒险者必须检查这片受损区域，寻找袭击者的线索。发现的实物证据揭示了一个直接威胁到剃刀岭防线的入侵隐患。",h="Threat from...",kw={"杜隆塔尔","赫格兰·暗眼","部落","娜迦","奥戈尼尔·魂痕","剃刀岭","斥候","threat from below"},ang={["faction:Horde"]="调查海岸线对于杜隆塔尔的防御至关重要，能保护年轻的部落国度免受沿海边境侧翼打击的威胁。",["race:Orc"]="兽人防卫者认为针对斥候赫格兰·暗眼的伏击是对他们定居家园不可容忍的入侵，要求立即进行调查和反击。",["race:Troll"]="暗矛巨魔非常了解娜迦的狡诈本性，他们此前曾在无尽之海面对过海巫和水生恐怖生物。"},sec={{t="杜隆塔尔海岸的伏击",b="杜隆塔尔海岸发生的一场暴力小规模战斗留下了破碎的地面，引起了部落防卫者们的即刻警觉。破碎之手斥候赫格兰·暗眼在她的哨岗执行守望任务时，遭到了未知敌人的伏击。交战地点的情况清晰地表明，赫格兰进行了激烈的反击并重创了袭击者。由于敌对势力在东海岸长驱直入，部落冒险者们奉命调查这片受损的营地，仔细搜寻地面的线索，并查明袭击斥候的究竟是何种敌人。"},{t="娜迦威胁",b="搜寻残骸后发现了破碎的旗帜和一截异样兵器的残片，这些都属于蛇形生物——娜迦。这些邪恶的水生生物似乎是从艾萨拉一路沿杜隆塔尔海岸向南潜行，企图建立一个掠夺性的据点。对于驻扎在剃刀岭的守军来说，这一发现标志着危机将至。该定居点南面受困于提拉加德城堡的人类入侵者，西面又有野猪人的威胁，无法承受来自北方的新一轮海上攻势，否则将面临彻底崩溃的风险。"}},faq={{q="什么是Threat from Below？",a="Threat from Below是杜隆塔尔的一项任务，部落冒险者需在任务中调查针对斥候赫格兰·暗眼的伏击。在沿着海岸线发现暴力战斗的痕迹后，玩家需在受扰的地面上搜寻不明袭击者留下的线索。随后，回收的文物将被直接送往剃刀岭的奥戈尼尔·魂痕处，以评估该地区面临的军事危险。",al={"threat from below任务","什么是threat from below","threat from below概览"}},{q="赫格兰·暗眼是谁？",a="赫格兰·暗眼是一名破碎之手斥候，她曾在一座位于提拉加德城堡北侧的小屋中执行监视任务，守护部落的核心领地。在执行任务期间，她在海岸的观测点遭到了伏击。营地遭受的严重破坏表明她曾与袭击者进行过激烈的战斗，这引起了剃刀岭定居点领导层的紧急质询。",al={"赫格兰·暗眼","赫格兰是谁","赫格兰·暗眼背景故事"}},{q="谁袭击了赫格兰·暗眼？",a="赫格兰·暗眼遭到了沿杜隆塔尔海岸向南移动的娜迦的伏击。从交战现场回收的实物证据，特别是那面独特的旗帜和那块断裂的刀刃，证实了这次袭击是由这些蛇形生物实施的。战斗的惨烈程度也让袭击者自身负了伤。",al={"谁伏击了赫格兰","赫格兰的袭击者","什么袭击了赫格兰·暗眼"}},{q="奥戈尼尔·魂痕是谁？",a="奥戈尼尔·魂痕是驻扎在杜隆塔尔中部剃刀岭的一位著名兽人长官。他的职责是组织该地区的防御并协调部落斥候，负责监督有关敌对入侵的情报。当赫格兰·暗眼失去联络时，奥戈尼尔依靠返回的斥候和冒险者来识别袭击者并保障定居点的安全。",al={"奥戈尼尔是谁","奥戈尼尔·魂痕","剃刀岭的奥戈尼尔"}},{q="为什么娜迦对剃刀岭构成威胁？",a="剃刀岭已经面临着南面深根蒂固的库尔提拉斯人类海军，以及西面敌对野猪人的巨大军事压力。如果娜迦在北面的东海岸建立永久的滩头阵地，部落前哨将面临被夹击的风险，导致其有限的驻军过度分散，并切断横跨杜隆塔尔的增援路线。",al={"为什么娜迦在这里很危险","娜迦对剃刀岭的威胁","剃刀岭娜迦威胁"}},{q="袭击的娜迦来自哪里？",a="回收的军事残骸表明，娜迦是从北方水域沿海岸南下的，很可能源自艾萨拉或无尽之海的架层。通过利用水道避开内陆巡逻队，这些水生入侵者在杜隆塔尔防卫者组织起防线之前，便迅速袭击了孤立的海岸观测哨。",al={"娜迦来自哪里","杜隆塔尔的娜迦起源","娜迦如何到达杜隆塔尔"}}},fp="17,381,27.563.0,18.564.1,26.391.0,23.367.0,29.310.0,23.374.0,40.379.0,39.355.0"}
P.entries["quest:99050"] = {n="The Great Tree Provides",s="“大树的馈赠”是多兰纳尔的一个任务，拜安希在任务中寻求帮助以遏制威胁埃拉莉亚的危险疾病。玩家通过采集泰达希尔湖泊中的露水鞭笞者嫩叶并收集基本补给品，来帮助配制一种急救药膏。",h="“大树的馈赠”是多兰纳尔的一个任务，拜安希在任务中寻求帮助以遏制威胁埃拉莉亚的危险疾病。玩家通过采集泰达希尔湖泊中的露水鞭笞者嫩叶并收集基本补给品，来帮助配制一种急救药膏。",kw={"疾病","拜安希","露水鞭笞者嫩叶","多兰纳尔","埃拉莉亚","治疗药膏","奥拉密斯湖","泰达希尔","the great tree provides","涌泉湖"},ang={["class:Druid"]="德鲁伊们很欣赏泰达希尔植物中蕴含的天然修复特性，他们倾向于依赖像鞭笞者嫩叶这样的原生植物，而不是人工合成的制剂。",["profession:Herbalism"]="采集露水鞭笞者嫩叶等原生植物材料来酿制强效治疗药膏，对于经验丰富的草药师来说是本能般的技能。",["race:NightElf"]="泰达希尔的草药疗法反映了卡多雷的信仰，即他们的世界之树养育并保护着他们，为突发的疾病提供了生命之药。"},sec={{t="与时间赛跑",b="在多兰纳尔的森林村庄里，拜安希一直照料着当地暗夜精灵的健康。当埃拉莉亚在泰达希尔野外遭遇危险疾病的消息传来时，拜安希立刻着手准备急救治疗。如果不能快速配制出药膏来遏制病情，埃拉莉亚将无法支撑到被送回村庄接受正式治疗。"},{t="慷慨的世界之树",b="即使在危机时刻，卡多雷依然信任泰达希尔的慷慨馈赠。拜安希求助于这棵充满生命的世界之树来寻找疗法，她寻找着生长在南面奥拉密斯湖和西北面涌泉湖附近的露水鞭笞者嫩叶。将这些叶片与简单的玻璃瓶中的清凉的泉水混合，就能得到遏制疾病所需的救命药物。"}},faq={{q="“大树的馈赠”是什么？",a="“大树的馈赠”是多兰纳尔的一项紧急任务，由拜安希发布。她试图配制一种修复药膏，以在无法进行后续治疗前遏制威胁埃拉莉亚的疾病。",al={"大树的馈赠是什么","大树的馈赠任务","拜安希任务"}},{q="拜安希是谁？",a="拜安希是一位居住在泰达希尔多兰纳尔村的暗夜精灵治疗者或药剂师，致力于照料病人并利用当地植物配制天然药物。",al={"谁是拜安希","拜安希多兰纳尔","任务发布者拜安希"}},{q="埃拉莉亚是谁？她发生了什么事？",a="埃拉莉亚是一位身处多兰纳尔外、目前病情正在迅速恶化的受难者。拜安希需要一种紧急药膏来使她的情况稳定下来，以便将其安全送回城里接受全面治疗。",al={"谁是埃拉莉亚","埃拉莉亚怎么了","埃拉莉亚疾病"}},{q="哪里可以找到露水鞭笞者嫩叶？",a="露水鞭笞者嫩叶生长在多兰纳尔正南方的奥拉密斯湖，以及西北方向的涌泉湖及其河流周围的鞭笞者身上。",al={"哪里找到露水鞭笞者嫩叶","露水鞭笞者嫩叶位置","泰达希尔鞭笞者嫩叶"}},{q="配制药膏需要什么材料？",a="拜安希需要六片从本土鞭笞者身上采集的露水鞭笞者嫩叶、一个空瓶以及清凉的泉水来调配这种急救药膏。",al={"拜安希需要什么材料","多兰纳尔药膏材料","大树的馈赠物品"}},{q="在哪里可以获得空瓶和清凉的泉水？",a="空瓶和清凉的泉水都可以直接从多兰纳尔定居点的杂货或贸易补给品商人处购买。",al={"哪里获取瓶子和泉水","多兰纳尔空瓶","多兰纳尔清凉的泉水"}}},fp="23,183,19.267.0,24.258.0,32.152.0,15.138.0,39.157.0,35.139.0,51.102.0,63.91.0"}
P.entries["quest:99051"] = {n="Threat from Below",s="Threat from Below是一项防御任务，旨在清除附近建立营地的侵略性娜迦侦察兵。通过打击侦察部队并收集它们的脊鳍，冒险者们的目标是将这些蛇形入侵者赶回北方，保卫该地区。",h="Threat from Below是一项防御任务，旨在清除附近建立营地的侵略性娜迦侦察兵。通过打击侦察部队并收集它们的脊鳍，冒险者们的目标是将这些蛇形入侵者赶回北方，保卫该地区。",kw={"步兵","娜迦","娜迦脊鳍","侦察兵","蛇渣","脊鳍","threat from below"},ang={["faction:Horde"]="任务发布者动员部落步兵观察是否有漏网之鱼，这使其成为部落领地针对逼近的娜迦侦察兵的一次主动防御行动。"},sec={{t="蛇形入侵",b="Threat from Below旨在应对因娜迦侦察兵入侵而日益严重的边境骚乱。这些蛇形袭击者开始在附近建立前进营地，迫使当地防卫力量在入侵者稳固立足之前发动打击。冒险者们受命清除侦察部队，并带回娜迦脊鳍作为营地已被摧毁的证据。"},{t="保卫边境",b="这并非蛇人第一次滋扰该地区，当地指挥官明确表示绝不容忍它们的存在。在对它们的侦察营地进行打击后，目标是将任何幸存的娜迦赶回北方，并派遣警惕的部落步兵守卫，以防漏网之鱼或突如其来的伏击。"}},faq={{q="什么是Threat from Below？",a="Threat from Below是一项部落任务，任务要求冒险者们消灭开始在附近建立营地的娜迦侦察兵。为了确保入侵被阻止，玩家必须杀死这些逼近的蛇人并收集娜迦脊鳍作为任务完成的证明。",al={"什么是threat from below","threat from below任务"}},{q="命令中提到的蛇是指谁？",a="“蛇”或“蛇渣”指的是娜迦，这是一种两栖蛇形类人生物，它们从海岸或水底深处浮出，侦察当地的防线。",al={"蛇是指谁","threat from below里的蛇"}},{q="为什么要消灭娜迦侦察兵？",a="这些营地表明这是一种有组织的侦察活动，而非偶然游荡的生物。当地指挥官要求迅速反击，以便在入侵者发动更大规模袭击或进一步扎根之前将它们赶走。",al={"为什么要杀娜迦侦察兵","娜迦的动机"}},{q="为什么要收集娜迦脊鳍？",a="被割下的脊鳍是侦察营地已被发现并拆除的无可辩驳的实物证据，证实了边境沿线的直接压力已经解除。",al={"为什么要收集脊鳍","娜迦的证据"}},{q="娜迦预计会撤退到哪里？",a="在交付脊鳍后，指挥官表示希望这次打击能将娜迦赶回北方，并指派步兵监视是否有漏网之鱼或可疑动向。",al={"娜迦会去哪里","娜迦撤往北方"}},{q="侦察兵被杀后由谁负责警戒？",a="部落步兵受命负责监视该区域，以确保没有漏网之鱼，并防止娜迦尝试任何进一步的入侵。",al={"谁负责监视娜迦","步兵监视娜迦"}}},fp="17,245,20.379.0,20.334.0,26.262.0,43.157.0,39.231.0,33.178.0,39.179.0,43.143.0"}
P.entries["quest:99052"] = {n="Threat from Below",s="“Threat from Below”是一项部落悬赏任务，要求冒险者们前往杜隆塔尔的北部海岸，猎杀一头危险的海洋巨人。击败这样一个巨大的海岸泰坦，不仅能保卫附近的海岸线，还能赢得杜隆塔尔勇士们的尊敬。",h="“Threat from Below”是一项部落悬赏任务，要求冒险者们前往杜隆塔尔的北部海岸，猎杀一头危险的海洋巨人。击败这样一个巨大的海岸泰坦，不仅能保卫附近的海岸线，还能赢得杜隆塔尔勇士们的尊敬。",kw={"血与雷","海岸怪物","杜隆塔尔","部落任务","北部海岸","海洋巨人","threat from below"},ang={["class:Warrior"]="在近战中面对一个庞大的海洋巨人是一场残酷的武力耐力考验，是对抗海岸上最强大的蛮兽之一的证明。",["faction:Horde"]="在杜隆塔尔海岸线上击杀海洋巨人，消除了一个潜伏在部落心脏地带门户附近的危险巨兽。",["race:Orc"]="兽人的荣誉感崇尚正面面对泰坦般的强敌，并以“血与雷”的战吼回应压倒性的力量。"},sec={{t="北部海岸线",b="在杜隆塔尔的北部海岸线，无尽之海的海水拍打着锯齿状的沙滩和岩石岸边。虽然这里通常只有普通的食腐动物和螃蟹出没，但北部海岸却潜藏着更致命的威胁：一个庞大的海洋巨人在浅滩徘徊，威胁着任何试图在部落这片干旱新家园的沿海水域旅行或获取资源的人。"},{t="波涛泰坦",b="海洋巨人是巨大的蛮兽，能够轻易摧毁长船，并用巨大的拳头碾碎战士。对于年轻的冒险者来说，击杀它们绝非易事；能终结这个波涛中的巨兽，足以在兽人中赢得极高的尊敬，并伴随着在干红色的峭壁间回荡的传统战吼——“血与雷”的庆祝。"}},faq={{q="“Threat from Below”是什么任务？",a="“Threat from Below”是一项交给部落勇士的任务，要求他们追踪并击败在杜隆塔尔北部海岸徘徊的巨型海洋巨人，并带回证明以完成任务。",al={"什么是threat from below","threat from below任务","杜隆塔尔海洋巨人任务"}},{q="在哪里可以找到海洋巨人？",a="这头海洋巨人在杜隆塔尔北部海岸的水域和岸边徘徊。",al={"海洋巨人在哪里","杜隆塔尔海洋巨人位置","threat from below位置"}},{q="海洋巨人是什么样的生物？",a="海洋巨人是巨大的、古老的海岸巨兽，它们被创造出来的目的是疏浚海洋并塑造艾泽拉斯的海岸线。很少有流浪者能在与它们的直接对抗中幸存。",al={"什么是海洋巨人","海洋巨人背景故事","谁是海洋巨人"}},{q="为什么要消灭海洋巨人？",a="如此巨大规模的生物在杜隆塔尔附近游荡，对海岸边的旅行者、渔民以及部落营地构成了严重的威胁。",al={"为什么要杀海洋巨人","海洋巨人危险吗","对杜隆塔尔的威胁"}},{q="任务发布者所说的“血与雷”是什么意思？",a="“血与雷”是传统的兽人战斗口号，旨在赞颂尚武精神、勇猛，以及在对抗危险对手并获得胜利后的荣耀。",al={"血与雷的含义","兽人问候语血与雷"}},{q="完成任务需要什么证明？",a="该任务要求从北部海岸带回这头海洋巨人被击杀的切实物理证明，以确认这一庞然大物已被消灭。",al={"threat from below任务证明","成就证明"}}},fp="17,246,22.365.0,20.340.0,36.172.0,29.92.0,37.170.0,45.156.0,54.152.0,44.150.0"}
P.entries["quest:99053"] = {n="Escaping Ban'ethil",s="“逃离班奈希尔”是泰达希尔地下兽穴中的一项营救任务。哨兵莱尼莎·暮花在向沉睡的德鲁伊传递信息时被好战的棘木熊怪俘虏，她必须被安全护送回地面，并向多兰纳尔报告平安。",h="“逃离班奈希尔”是泰达希尔地下兽穴中的一项营救任务。哨兵莱尼莎·暮花在向沉睡的德鲁伊传递信息时被好战的棘木熊怪俘虏，她必须被安全护送回地面，并向多兰纳尔报告平安。",kw={"班奈希尔兽穴","多兰纳尔","escaping ban'ethil","熊怪","棘木","卡多雷","凯拉·星歌","莱尼莎·暮花","the oracle tree","泰达希尔"},ang={["class:Druid"]="班奈希尔兽穴本应是沉睡的德鲁伊与翡翠梦境沟通的圣所，它被野蛮的熊怪占领，这对塞纳里奥的保护者来说是一场紧急危机。",["faction:Alliance"]="保护达纳苏斯和泰达希尔需要协助哨兵，对抗被腐化的本土野生生物和部族日益增长的敌意。",["race:NightElf"]="哨兵莱尼莎·暮花是并肩作战的战友，她被困在根须之下，这违背了暗夜精灵与泰达希尔广阔星空和林冠之间的神圣纽带。"},sec={{t="根须下的伏击",b="哨兵莱尼莎·暮花受“The Oracle Tree”委派，前去向在班奈希尔兽穴中休息的德鲁伊传达一条紧急信息。这项原本例行的信使任务却演变成了一场灾难，因为她发现这些地下密室已被好战的棘木熊怪完全占据。她在撤退前被截断去路并遭到伏击，被关押在阴暗的隧道中。她本以为自己难逃一死，直到一位冒险者介入，护送她回到了地面。"},{t="安全返回多兰纳尔",b="对于卡多雷哨兵来说，兽穴的地下阴暗处是一个既不自然又令人厌恶的牢笼，这里远离了艾露恩那令人慰藉的星光，也远离了泰达希尔的广阔天空。从深渊中被救出后，莱尼莎逃回了文明世界，关于她生还的消息也传到了多兰纳尔。在那里，哨兵凯拉·星歌得知好友生还的消息后如释重负，并嘉奖了那些帮助她战友保卫卡多雷人民的冒险者。"}},faq={{q="谁是哨兵莱尼莎·暮花？",a="哨兵莱尼莎·暮花是一位驻扎在泰达希尔的暗夜精灵哨兵。她受“The Oracle Tree”委派，前去向在班奈希尔兽穴中休息的德鲁伊传达一条至关重要的信息，但她在深入地下时遭到了棘木熊怪的伏击并被俘虏。",al={"谁是莱尼莎·暮花","莱尼莎·暮花","谁被困在兽穴里"}},{q="哨兵莱尼莎为什么会进入班奈希尔兽穴？",a="她受“The Oracle Tree”的正式委派，去向在班奈希尔兽穴中沉睡的德鲁伊传达一条信息。当她到达地下兽穴时，还没来得及传达信件，就发现那里已经被敌对的熊怪占领了。",al={"莱尼莎为什么去班奈希尔","莱尼莎的任务是什么","the oracle tree 的消息"}},{q="是谁俘虏了哨兵莱尼莎？",a="她被居住在兽穴中的棘木熊怪俘虏了。这些好战且充满敌意的部族在她逃脱前将其伏击，并拖入了深处，这让她担心自己会成为他们的下一顿盘中餐。",al={"谁俘虏了莱尼莎","班奈希尔里有什么熊怪","棘木熊怪"}},{q="什么是班奈希尔兽穴？",a="班奈希尔兽穴是位于泰达希尔的一处地下圣所，位于多兰纳尔以西。传统上，这里是在地底开凿出的暗夜精灵德鲁伊进行深度沟通时的休憩之所，但现在已被腐化的棘木熊怪所占据。",al={"班奈希尔兽穴在哪里","什么是班奈希尔兽穴","泰达希尔兽穴"}},{q="谁是哨兵凯拉·星歌？",a="哨兵凯拉·星歌是一位驻扎在多兰纳尔村的暗夜精灵哨兵。她是莱尼莎·暮花的挚友，正急切地等待着莱尼莎逃脱并安全返回的消息。",al={"谁是凯拉·星歌","在哪里交还“逃离班奈希尔”","多兰纳尔哨兵"}},{q="为什么莱尼莎厌恶身处地下？",a="虽然德鲁伊会利用兽穴进行神圣的沉睡，但许多暗夜精灵哨兵和战士非常不喜欢被困在地下。卡多雷文化珍视广阔的夜空、艾露恩的星光，以及森林树冠的庇护，而不是地下的隧道。",al={"为什么暗夜精灵不喜欢兽穴","地底不属于卡多雷"}}},fp="18,283,26.512.0,23.504.0,36.266.0,52.249.0,30.236.0,29.245.0,30.201.0,42.281.0"}
P.entries["quest:99073"] = {n="Easing Suffering",s="Easing Suffering是泰达希尔的一项任务，其核心内容是为哨兵埃拉莉亚·叶影提供紧急援助，她正躺在通往The Oracle Tree的道路上，饱受一种剧毒腐烂病的折磨。玩家必须争分夺秒地将鞭水愈膏送到她身边，以缓解她的痛苦，让她临终前的气息得到安宁。",h="Easing Suffering是泰达希尔的一项任务，其核心内容是为哨兵埃拉莉亚·叶影提供紧急援助，她正躺在通往The Oracle...",kw={"easing suffering","埃拉莉亚·叶影","鞭水愈膏","the oracle tree","腐烂病","哨兵埃拉莉亚","泰达希尔"},ang={["faction:Alliance"]="在达纳苏斯的家园道路上援助倒下的暗夜精灵哨兵，有助于守住对抗泰达希尔枝干上日益增长的腐化的脆弱前线。",["race:NightElf"]="哨兵埃拉莉亚·叶影是你的一位同胞，在泰达希尔靠近The Oracle Tree的荒野中，她染上了一种剧毒的腐化。为她提供慰藉，是对哨兵为族人所尽职责的尊崇。"},sec={{t="与腐烂病的赛跑",b="哨兵埃拉莉亚·叶影正躺在通往The Oracle Tree的道路上，深受一种迅速蔓延、不断恶化的腐烂病折磨。为了阻止她痛苦地走向死亡，必须在病情完全恶化之前，尽快将新鲜调制的鞭水愈膏送到她身边。"},{t="阴影中的安宁",b="虽然救治她的人怀疑鞭水愈膏是否有能力彻底根除这种枯萎病，但使用它能迅速平复埃拉莉亚那沉重而含混的呼吸。尽管她能否存活仍是个未知数，但这种治疗确实在她最黑暗的时刻给予了她安宁。"}},faq={{q="哨兵埃拉莉亚·叶影是谁？",a="哨兵埃拉莉亚·叶影是一位暗夜精灵卫兵，人们在通往The Oracle Tree的路上发现了她，当时她正饱受疾病的折磨。她被一种极具侵略性的溃烂腐病击倒，被发现时已失去行动能力，生命垂危。",al={"埃拉莉亚是谁","埃拉莉亚·叶影","哨兵埃拉莉亚是谁"}},{q="什么是鞭水愈膏？",a="鞭水愈膏是一种配制好的药剂，用于缓解哨兵埃拉莉亚所患的剧毒腐烂病引起的剧烈疼痛。虽然不能确定是否能彻底治愈，但它能缓解她的痛苦。",al={"什么是鞭水愈膏","鞭水愈膏","药膏能否治愈腐烂病"}},{q="哨兵埃拉莉亚能从这种疾病中幸存吗？",a="这种药膏缓解了哨兵埃拉莉亚的呼吸，带给她暂时的安宁，但她究竟能否完全康复，还是会屈服于缠身已久的腐烂病，仍不确定。",al={"埃拉莉亚能否幸存","埃拉莉亚是否痊愈","埃拉莉亚死了吗"}},{q="在哪里可以找到哨兵埃拉莉亚·叶影？",a="哨兵埃拉莉亚·叶影位于通往The Oracle Tree的道路旁，处于泰达希尔古老的区域内。",al={"the oracle tree在哪里","通往the oracle tree的路","埃拉莉亚的位置"}},{q="哨兵埃拉莉亚患了什么病？",a="埃拉莉亚患有一种极具侵略性且不断恶化的腐烂病，这种病在她体内迅速蔓延。这种污染的确切来源尚不明确，但它发作迅速，且随时间推移毒性越来越强。",al={"是什么导致了埃拉莉亚的疾病","什么是腐烂病","埃拉莉亚的病痛"}},{q="为什么要急着送达药膏？",a="腐烂病在埃拉莉亚体内迅速溃烂并加剧。必须争分夺秒，因为每耽误一刻，她就离被痛苦和腐化彻底吞噬更近一步。",al={"为什么要急送药膏","为什么要争分夺秒救埃拉莉亚"}}},fp="16,154,22.200.0,20.222.1,34.154.0,24.157.0,44.135.0,46.89.0,39.144.0,43.165.0"}
P.entries["quest:99079"] = {n="Longwalker Malah",s="远行者玛拉是一位失踪的牛头人侦察兵，她代表血蹄村被派往勘查莫高雷的东部边境。作为直接听命于大酋长的精英远行者，她在出发三天后未能按时归来，这引发了寻找她的紧急行动，以确保她的生存以及山谷的安全。",h="远行者玛拉是一位失踪的牛头人侦察兵，她代表血蹄村被派往勘查莫高雷的东部边境。作为直接听命于大酋长的精英远行者，她在出发三天后未能按时归来，这引发了寻找她的紧急行动，以确保她的生存以及山谷的安全。",kw={"贝恩·血蹄","血蹄村","羽毛法杖","longwalker malah","远行者组织","玛拉·长风","莫高雷","牛头人侦察兵"},ang={["class:Hunter"]="猎人们尊重远行者所需的野外追踪技能和耐力，他们徒步巡逻莫高雷的最边缘地带。",["faction:Horde"]="协助血蹄村的领导层寻找失踪的边境侦察兵，有助于保护莫高雷免受入侵部落领地的外部威胁。",["race:Tauren"]="远行者是受人尊敬的侦察兵，直接听命于大酋长凯恩·血蹄，因此他们的安全是所有牛头人在文化和战术上都极为关注的问题。"},sec={{t="大酋长的双眼",b="远行者是舒哈鲁人的耳目，他们因不知疲倦的步伐和野外生存技巧而闻名于平原。这些精英侦察兵直接宣誓效忠于大酋长凯恩·血蹄，他们的任务是穿越广阔的领土以收集情报并传递重要信息。虽然他们最终只效忠于大酋长，但年轻的贝恩·血蹄偶尔也会请求他们的协助，以保护血蹄村及其周边的牧场。"},{t="消失在边境",b="远行者玛拉·长风被派往监视莫高雷的东部边境，进行一次例行的三天侦察任务。当她未能按计划返回血蹄村时，村里的领导层感到十分担忧。鉴于远行者掌握着重要情报，且莫高雷边境峭壁处处潜藏危险，人们呼吁侦察兵和乐于助人的旅行者去寻找她的踪迹并确认她的安全。玛拉可以通过她所属组织的传统标志来辨认：一条仪式头带和一根羽毛法杖。"}},faq={{q="谁是远行者玛拉？",a="远行者玛拉·长风是一位受人尊敬的牛头人侦察兵，效忠于大酋长。她被派往莫高雷东部边境附近执行侦察任务，随身携带着代表她所属组织标志的传统头带和羽毛法杖。",al={"谁是玛拉","玛拉背景故事","远行者玛拉身份"}},{q="什么是远行者？",a="远行者是牛头人人民最信任的精英侦察兵和信使。他们的首要忠诚直接对大酋长负责，不过其他部落领袖（例如年轻的贝恩·血蹄）偶尔也会请求他们的帮助，以获取关键的边境情报。",al={"什么是远行者","谁是远行者","牛头人侦察兵"}},{q="为什么要寻找远行者玛拉？",a="玛拉被派去勘查莫高雷的东部边缘，原定三天内返回。当她未能归来时，血蹄村的人们开始担心她在巡逻崎岖边境时遇到了麻烦。",al={"为什么玛拉失踪了","玛拉任务原因","玛拉去了哪里"}},{q="在哪里可以找到玛拉？",a="远行者玛拉被派往莫高雷的东部边境，经过血蹄村向边界山脊进发。寻找她的旅行者必须搜索村庄以东的边境地带。",al={"玛拉在哪里","玛拉位置","寻找玛拉"}},{q="如何辨认远行者玛拉？",a="玛拉可以通过远行者的标志性服饰来辨认：一条独特的头带和一根她所属尊贵组织侦察兵所携带的高大羽毛法杖。",al={"玛拉外观","如何辨认玛拉","远行者装备"}},{q="贝恩·血蹄为什么会与远行者有往来？",a="虽然远行者只向大酋长凯恩·血蹄汇报，但他的儿子贝恩负责血蹄村的当地事务，偶尔会请求他们的追踪专长来监视边境活动并确保山谷的安全。",al={"贝恩角色","为什么贝恩参与其中","贝恩·血蹄侦察兵"}}},fp="16,324,25.502.0,27.554.0,24.243.0,25.268.0,43.230.0,25.192.0,38.160.0,53.249.0"}
P.entries["quest:99080"] = {n="Vertreibt sie",s="贝恩·血蹄要你把加拉克半人马赶出村庄的小路。击败他们，孩子们便能多一分安全。",h="贝恩·血蹄要你把加拉克半人马赶出村庄的小路。击败他们，孩子们便能多一分安全。",kw={"贝恩·血蹄","半人马","孩子","加拉克人","掠夺者赫拉克","斥候","村庄"},ang={["race:Tauren"]="作为一名牛头人，贝恩称这场流血冲突是你们族人独有的荣耀。"},sec={{t="加拉克人",b="贝恩要你杀死六名加拉克半人马和四名加拉克斥候，然后把掠夺者赫拉克的头带给他。村庄的安危岌岌可危。"},{t="村庄的宽慰",b="贝恩听见最后一名半人马倒下，奔袭也随之停歇。他称这一天是村庄的大胜，并说孩子们比以往任何时候都更需要安全感。"}},faq={{q="是谁让我赶走加拉克人？",a="贝恩·血蹄要你对付加拉克半人马和斥候，并把掠夺者赫拉克的头带给他。",al={"是谁交代的","贝恩的任务"}},{q="贝恩想让我做什么？",a="贝恩要你杀死六名加拉克半人马和四名加拉克斥候，然后把掠夺者赫拉克的头带给他。",al={"要做什么","加拉克任务"}},{q="掠夺者赫拉克是谁？",a="掠夺者赫拉克就是贝恩要你带回首级的那个加拉克人。",al={"赫拉克是谁","掠夺者的头"}},{q="这对村庄为何重要？",a="贝恩说，胜利能让村里的孩子获得他们比以往任何时候都更需要的安全感。",al={"为何帮助村庄","孩子安全"}}},fp="13,135,9.145.0,20.171.1,35.110.0,29.109.0,27.68.0,36.96.0"}
P.entries["quest:99081"] = {n="Schwieriges Unterfangen",s="战士英雄 Wildrunner需要 Langläuferin Malah保管的报告。新出现的半人马营地表明，一小股劫掠者已进入莫高雷；必须报告她的死讯。",h="战士英雄 Wildrunner需要 Langläuferin Malah保管的报告。新出现的半人马营地表明，一小股劫掠者已进入莫高雷；必须报告她的死讯。",kw={"baine","血蹄村","半人马营地","战士英雄 wildrunner","langläuferin malah","malah","莫高雷","schwieriges unterfangen"},ang={["race:Tauren"]="作为一名牛头人，你将半人马劫掠者潜入莫高雷的消息带给战士英雄 Wildrunner。"},sec={{t="Malah的报告",b="你将 Langläuferin Malah的报告带给血蹄村的战士英雄 Wildrunner。他想知道 Malah遭遇了什么，以及是谁杀了她。报告带来了令人忧心的消息，必须立刻送到 Baine那里。"}},faq={{q="谁想要 Malah的报告？",a="血蹄村的战士英雄 Wildrunner想要 Langläuferin Malah的报告。",al={"谁需要这份报告","wildrunner的报告","我该把报告交给谁"}},{q="报告涉及什么？",a="报告涉及 Langläuferin Malah遭遇了什么，以及是谁杀了她。",al={"malah遭遇了什么","malah的报告","malah为何死去"}},{q="箭矢指向的方向有什么？",a="一座新出现的半人马营地位于 Malah中箭时箭矢似乎射来的方向。",al={"新半人马营地","半人马营地","劫掠者从哪里来"}},{q="营地说明了什么？",a="营地的活动表明，一小股劫掠者已经潜入莫高雷。",al={"半人马劫掠","莫高雷的劫掠者","营地意味着什么"}},{q="谁需要听到这个消息？",a="战士英雄 Wildrunner说，必须立刻通知 Baine。",al={"通知baine","wildrunner通知baine","谁会接到通知"}}},fp="23,220,14.214.0,25.81.0,29.76.0,35.99.0,27.72.0,27.61.0"}
P.entries["quest:99082"] = {n="The High Chieftain",s="凯恩·血蹄的儿子派你前往雷霆崖，请求觐见他的父亲。你为族人挺身而战，赢得了认可。",h="凯恩·血蹄的儿子派你前往雷霆崖，请求觐见他的父亲。你为族人挺身而战，赢得了认可。",kw={"觐见","凯恩·血蹄","半人马","大酋长","牛头人","萨尔","雷霆崖"},ang={["race:Tauren"]="身为牛头人，你在保卫族人后受命前去拜见凯恩·血蹄。他曾与萨尔并肩作战，努力夺回平原。"},sec={{t="酋长的功绩",b="凯恩·血蹄曾与年轻的大酋长萨尔并肩作战，努力从半人马手中夺回这片平原。身为大酋长，他能够认可你在保卫族人时所立下的功劳。"}},faq={{q="我奉命去见谁？",a="有人请你去觐见雷霆崖的高阶督军凯恩·血蹄。",al={"高阶督军是谁","请求觐见凯恩","拜见凯恩"}},{q="我为什么要去雷霆崖？",a="你保卫族人时展现出的勇气赢得了认可，因此你受命请求觐见凯恩·血蹄。",al={"为何前往雷霆崖","凯恩想要什么","与凯恩会面"}},{q="谁协助夺回了平原？",a="凯恩·血蹄和年轻的大酋长萨尔率领众人，努力从半人马手中夺回平原。",al={"谁与半人马作战","萨尔和凯恩","夺回平原"}},{q="凯恩在哪里？",a="凯恩·血蹄在雷霆崖的中央高地。",al={"大酋长在哪里","凯恩的位置","寻找凯恩"}}},fp="18,136,20.180.0,27.98.0,32.121.0,30.102.0,16.54.0"}
P.entries["quest:991"] = {n="莱恩的净化",s="“莱恩的净化”始于莱恩·狼行者请求冒险者追踪她失踪的朋友泰罗尼恩。为了寻找平息灰谷各地猖獗的熊怪侵略的方法，泰罗尼恩动身前往法拉希姆湖寻找一颗魔法宝石。",h="“莱恩的净化”始于莱恩·狼行者请求冒险者追踪她失踪的朋友泰罗尼恩。为了寻找平息灰谷各地猖獗的熊怪侵略的方法，泰罗尼恩动身前往法拉希姆湖寻找一颗魔法宝石。",kw={"灰谷","法拉希姆","熊怪","宝石","鱼人","莱恩","泰罗尼恩","狼行者"},ang={["faction:Alliance"]="抵达阿斯特兰纳的联盟新兵很快就会了解到，灰谷的神圣林地正受到充满敌意的野生野兽、熊怪和入侵鱼人的围攻。",["race:NightElf"]="泰罗尼恩的失踪对暗夜精灵来说又是沉重的一击，他们本就为了治愈灰谷并保护神龛免受腐蚀而疲于奔命。"},sec={{t="朋友的牵挂",b="莱恩·狼行者在阿斯特兰纳与哨兵部队并肩作战，保卫灰谷免受日益严重的威胁。泰罗尼恩是她最亲密的伙伴之一，他自告奋勇去寻找能有效防御那些愈发暴躁的熊怪部落的方法。当他多日未归时，莱恩深感忧虑，但又因坚守岗位而无法脱身，只能在担忧中饱受煎熬。"},{t="权杖探寻",b="泰罗尼恩追寻着关于一根由已故邪恶法师铸造的强大权杖的传言，相信其魔法能够平息熊怪的怒火。为了修复这件神器，他需要一颗隐藏在位于西侧山脉附近法拉希姆湖一座暗夜精灵神龛中的附魔宝石。不幸的是，这片宁静的水域最近已经被凶猛的鱼人部落占领。"},{t="法拉希姆湖的悲剧",b="沿着泰罗尼恩的踪迹来到法拉希姆湖中的岛屿，展现在眼前的是一幅凄惨的景象。泰罗尼恩没能活着离开这片水域；他的尸体倒在神龛上，身上布满了鱼人武器和利爪留下的深深伤痕，他的探寻也就此画上了终点。"}},faq={{q="莱恩·狼行者是谁？",a="莱恩·狼行者是一位隶属于灰谷哨兵部队的暗夜精灵，驻扎在阿斯特兰纳。她负责监督各项防御工作，以保护森林免受入侵敌人的侵害。",al={"莱恩","莱恩是谁","任务发布者"}},{q="泰罗尼恩是谁？",a="泰罗尼恩是莱恩·狼行者的挚友，他曾寻求古代魔法的解决方案来拯救森林。他相信一根附魔权杖能够平息被腐蚀的熊怪，于是只身前往搜集所需的部件。",al={"泰罗尼恩是谁","泰罗尼恩背景","失踪的朋友"}},{q="泰罗尼恩在哪里失踪的？",a="泰罗尼恩失踪于法拉希姆湖，这片水域位于灰谷西侧山脉脚下，现已被充满敌意的鱼人占领。",al={"泰罗尼恩在哪里","泰罗尼恩位置","法拉希姆湖"}},{q="为什么泰罗尼恩要寻找一颗宝石？",a="这颗宝石是充能一根由已故邪恶法师制作的魔法权杖所需的关键组件。泰罗尼恩希望利用权杖的力量来遏制狂暴熊怪的攻击。",al={"什么宝石","为什么需要宝石","泰罗尼恩的宝石"}},{q="泰罗尼恩遭遇了什么？",a="自从他前往法拉希姆湖后，莱恩就再也没有他的消息。顺着他的足迹便能发现他的结局。",al={"泰罗尼恩怎么死的","杀害泰罗尼恩的凶手","谁杀了泰罗尼恩"}},{q="为什么熊怪要攻击灰谷？",a="灰谷的熊怪在第三次战争后屈服于恶魔的腐蚀与疯狂，导致原本爱好和平的部落转而对他们往日的盟友发动了无休止的暴力攻击。",al={"熊怪攻击","为什么熊怪如此狂暴","熊怪疯狂"}}},fx={["82e89856"]={q="莱恩·狼行者为什么要找到特罗尼斯？",a="特罗尼斯是莱恩·狼行者信赖多年的老友，他曾挺身而出，帮助哨兵对抗暴怒的熊怪。他离开去寻找一根魔棒和一颗宝石，希望借此阻止那些族人遭受的袭击，却再也没有回来。莱恩十分担心他的安危，也迫切想知道他是否找到了能帮助这片饱受蹂躏土地的东西。",al={"莱恩为什么要找特罗尼斯","莱恩·狼行者的动机","为什么寻找特罗尼斯"}}},fp="17,245,18.364.0,22.353.0,24.268.1,24.182.0,16.210.0,29.155.0,34.185.0,25.98.1,41.194.0"}
P.entries["quest:99101"] = {n="Our Ancient Enemy",s="Malah的报告送到了贝恩·血蹄手中，他的回应十分严峻。他说，此事必将得到回应。",h="Malah的报告送到了贝恩·血蹄手中，他的回应十分严峻。他说，此事必将得到回应。",kw={"古老的敌人","贝恩·血蹄","malah","our ancient enemy","报告"},faq={{q="谁收到了Malah的报告？",a="贝恩·血蹄收到了Malah的报告。",al={"谁收到报告","贝恩报告","malah的报告"}},{q="贝恩对这份报告怎么说？",a="读完报告后，贝恩说，此事必将得到回应。",al={"贝恩的反应","贝恩说了什么","报告回应"}},{q="谁把报告带给了贝恩？",a="你把Malah的报告带给了贝恩·血蹄。",al={"带来malah报告","谁送来报告","给贝恩的报告"}}},fp="17,102,28.40.0,37.75.0,32.44.0"}
P.entries["quest:99108"] = {n="Sparring Match",s="Sparring Match是一项由格斗训练师唐·石蹄监管的入门试炼。该试炼旨在测试所有新兵，无论其职业或背景如何。它要求冒险者击败三名竞技场新兵或其他的决斗者，以证明他们在正面交锋中的实力。",h="Sparring Match是一项由格斗训练师唐·石蹄监管的入门试炼。该试炼旨在测试所有新兵，无论其职业或背景如何。它要求冒险者击败三名竞技场新兵或其他的决斗者，以证明他们在正面交锋中的实力。",kw={"竞技场","战斗训练","决斗","新兵战士","比武","sparring match","唐·石蹄"},ang={["class:Warrior"]="虽然唐·石蹄无法对非战士职业进行其特定学科的训练，但他的比武场强调了战士的哲学：战斗的基本功、勇气以及磨砺个人的战斗决心对任何冒险者都有益处。",["race:Tauren"]="唐·石蹄使用传统的牛头人短语，比如“磨砺犄角”来描述对一个人实力的考验，并欢迎任何愿意切磋的对手进入比武竞技场，无论他们的出身如何。"},sec={{t="切磋场地",b="由资深训练师唐·石蹄监管，Sparring Match邀请各路冒险者进入竞技场来测试自己的实力。尽管唐明确表示欢迎那些并非战士职业的人，但他坚持认为，武艺纪律和正面战斗能为这个危险世界中的任何旅行者提供通用的智慧。"},{t="磨砺犄角",b="在唐·石蹄的竞技场里，出身和武器偏好的区别都不重要。无论是使用剑、弓还是法术，挑战者都需要击败三名自愿的对手——无论是训练中的新兵战士还是进行决斗的其他冒险者——来证明自己的战斗准备情况。完成这些战斗后，你将赢得唐的尊重，并获得用于处理战斗伤口的绷带。"}},faq={{q="唐·石蹄是谁？",a="唐·石蹄是一位监管当地比武竞技场的格斗训练师。即使对于那些并非战士职业的人，唐也会提供格斗指导，并邀请有潜力的冒险者在与新兵或自愿同僚的正面战斗中测试自己的实力。",al={"唐·石蹄是谁","唐·石蹄背景故事","任务发布者"}},{q="唐·石蹄对Sparring Match有什么要求？",a="这项试炼要求在竞技场内击败三名对手——可以是进行决斗的其他自愿冒险者，也可以是在唐·石蹄指导下驻扎在那里的新兵战士。其目的是为了展示在正面战斗中的准备情况和武艺能力。",al={"sparring match目标","sparring match怎么做","与谁战斗"}},{q="为什么战士训练师要训练其他职业？",a="唐·石蹄认为，每一位冒险者，无论其挥舞的是刀剑、长弓还是魔法，都能从正面战斗中受益。在他的竞技场里，出身和特定的职业纪律远不如测试自我和磨砺战斗决心来得重要。",al={"非战士职业可以做吗","为什么其他职业要进行比武","不是战士"}},{q="Sparring Match在哪里进行？",a="比赛就在唐·石蹄面前的露天比武竞技场内进行，新兵们在那里进行训练，而自愿的挑战者也可以在平等的条件下互相切磋。",al={"在哪里对抗新兵","竞技场位置","比武场在哪里"}},{q="我能和玩家决斗而不是对战新兵战士吗？",a="可以。唐·石蹄接受你击败竞技场中训练的新兵战士，也接受你通过正式决斗击败其他冒险者，他只关心你是否在与自愿的对手对抗来测试自己的能力。",al={"我可以和玩家决斗吗","为了任务与玩家决斗","新兵战士还是玩家"}},{q="当你完成比赛时，唐·石蹄会说什么？",a="当你证明了自己的实力并击败三名对手后，唐会认可你的技巧，并对新一代的冒险者寄予希望，同时提供医疗补给来让你处理伤口，为前方的艰难旅途做好准备。",al={"sparring match奖励","唐给什么奖励"}}},fp="14,280,20.350.0,20.393.0,22.269.0,56.247.0,50.262.0,41.171.0,58.204.0,57.198.0"}
P.entries["quest:99123"] = {n="Lost in the Shadows",s="“Lost in the Shadows”是一个任务，内容是营救Pal'juh，一位鲁莽的猎人，她独自闯入了危险之中。对她的营救凸显了荒野追踪者在原始的攻击性和耐心的潜行之间所必需的微妙平衡。",h="“Lost in the Shadows”是一个任务，内容是营救Pal'juh，一位鲁莽的猎人，她独自闯入了危险之中。对她的营救凸显了荒野追踪者在原始的攻击性和耐心的潜行之间所必需的微妙平衡。",kw={"猎人","lost in the shadows","pal'juh","迅猛龙","老虎"},ang={["class:Hunter"]="该任务强调了一项基本的猎人纪律：耐心，像老虎一样潜行，而不是像饥饿的迅猛龙那样鲁莽冲锋。",["race:Troll"]="Pal'juh的名字和性情反映了年轻的Darkspear猎人，他们在掌握克制力之前就急于在荒野中证明自己的实力。"},sec={{t="鲁莽的斥候",b="“Lost in the Shadows”涉及寻找并营救Pal'juh，她是一位才华横溢但脾气火爆的猎人，独自闯入了敌对领地。她不愿等待支援，结果陷入了困境，需要外界的帮助才能确保安全返回。"},{t="狩猎的耐心",b="在Pal'juh获救后，她的监督者们指出，虽然她作为斥候和追踪者的潜力不可否认，但她像迅猛龙一样横冲直撞，而不是像老虎那样耐心地潜行。这次幸存下来的经历严酷地提醒了人们荒野的无情本质。"}},faq={{q="Pal'juh是谁？",a="Pal'juh是一位前途无量的年轻猎人，以独自闯入危险地带而闻名。虽然很有天赋，但她因行事鲁莽而声名狼藉，经常发现自己被野兽和荒野困住或淹没。",al={"pal'juh是谁","pal'juh背景故事","pal'juh"}},{q="在“Lost in the Shadows”任务期间发生了什么？",a="在“Lost in the Shadows”中，Pal'juh独自外出，再次陷入了麻烦。需要一位冒险者去追踪她，并在她受到严重伤害之前提供援助。",al={"lost in the shadows发生了什么","lost in the shadows任务背景","lost in the shadows故事"}},{q="为什么任务给予者说Pal'juh表现得更像迅猛龙而不是老虎？",a="这个比喻指的是狩猎技巧和纪律。迅猛龙在没有谨慎和预见的情况下猛烈扑击，而老虎则等待、耐心地潜行，并以精确和深谋远虑的狡诈进行攻击。",al={"为什么是迅猛龙和老虎","像迅猛龙而不像老虎的含义","猎人 迅猛龙 老虎"}},{q="谁负责接收“Lost in the Shadows”的报告？",a="任务以一位导师或同伴的结语告终，他足够了解Pal'juh并预料到了她的鲁莽，表达了对有人介入营救这位固执的追踪者感到欣慰。",al={"谁接收lost in the shadows任务","lost in the shadows任务给予者"}},{q="Pal'juh从这次不幸的冒险中吸取教训了吗？",a="多亏了外界的干预，Pal'juh才度过了这次磨难，尽管她的监督者们仍然在密切关注她是否会真正吸取独自外出带来的危险教训。",al={"pal'juh吸取教训了吗","pal'juh还好吗"}},{q="Pal'juh被认为是一位熟练的猎人吗？",a="她被认为是一位有前途的猎人，拥有充足的天赋和勇气，但她的导师警告说，在追踪危险猎物时，单纯的直觉无法取代战术上的耐心。",al={"pal'juh是优秀的猎人吗","pal'juh技能"}}},fp="19,237,16.263.0,20.278.0,15.204.0,52.175.0,74.211.0,48.179.0,53.179.0,39.182.0"}
P.entries["quest:99127"] = {n="A Net Disaster",s="“A Net Disaster”是艾尔文森林的一项任务，围绕着水晶湖的一次异常骚乱展开。由于垂钓一无所获，甚至连浅滩里的小鱼都不见了踪影，探险者们被派去检查过夜设置的陷阱。被毁坏的陷阱显示，附近充满敌意的入侵者正在大肆破坏当地的渔具。",h="“A Net...",kw={"a net disaster","水晶湖","艾尔文森林","鱼类储备","捕鱼陷阱","lee","鱼人","麻烦制造者"},ang={["faction:Alliance"]="水晶湖坐落在艾尔文森林的中心地带，因此当地的动荡直接威胁到了支持联盟领土核心区域的生计和补给。"},sec={{t="水晶湖的困境",b="在艾尔文森林的水晶湖，当地渔民面临着渔获量急剧下降的惊人状况。空钩并不罕见，但当连浅滩里的小鱼都消失不见时，日常垂钓就变成了一个严重的谜团。为了尽可能挽回损失，他们设置了过夜陷阱，希望能捕到一些基本的鱼获。"},{t="损坏的陷阱与邻近的麻烦",b="拉出没入水中的陷阱后发现，问题不在于运气不佳，而是赤裸裸的破坏行为。湖岸边充满敌意的邻近生物毁坏了陷阱，如果不加以制止，这将威胁到当地渔民的生计。"}},faq={{q="什么是“A Net Disaster”？",a="“A Net Disaster”是一项设定在艾尔文森林水晶湖的任务。当地渔民发现鱼儿不再上钩，甚至连小鱼也消失了，这促使人们对过夜陷阱展开调查。",al={"什么是a net disaster","a net disaster任务","水晶湖a net disaster"}},{q="你在哪里检查捕鱼陷阱？",a="捕鱼陷阱位于水晶湖的深水区，是由Lee在夜间放置的，目的是在常规垂钓失败时维持鱼类的储备。",al={"陷阱在哪里","a net disaster位置","水晶湖陷阱"}},{q="谁是Lee？",a="Lee是水晶湖的一名当地渔民，他连夜设置了陷阱，以帮助在鱼儿不再正常上钩时确保鱼类储备。",al={"谁是lee","渔夫lee"}},{q="水晶湖的鱼发生了什么事？",a="鱼类已经完全从水面消失了，连一条小鱼都看不见。检查发现，过夜陷阱已经被附近的麻烦制造者毁坏了。",al={"水晶湖的鱼怎么了","为什么水晶湖没有鱼","水晶湖空空如也"}},{q="最后提到的邻近麻烦制造者是谁？",a="任务发布者指的是入侵水晶湖的新的邻近麻烦制造者。在水晶湖的水域和岸边，好斗的鱼人已经建立了营地，并对当地的野生动物和渔具造成了破坏。",al={"谁是附近的麻烦制造者","a net disaster的麻烦制造者","谁破坏了陷阱"}},{q="为什么鱼类的缺乏对渔民来说是个大问题？",a="任务发布者的生计直接依赖于水晶湖的鱼类资源。随着陷阱受损和捕获量归零，如果不停止这种破坏，他们将面临破产的威胁。",al={"为什么任务发布者很在意","水晶湖渔业"}}},fp="14,338,31.310.0,39.280.1,23.215.0,39.146.0,11.137.0,42.192.0,55.231.0,61.191.0"}
P.entries["quest:99128"] = {n="Slimy Menace",s="“Slimy Menace”讲述了艾尔文森林中水晶湖沿岸日益严重的鱼人滋扰问题。这些极具攻击性的生物威胁要耗尽湖中的鱼类资源，并危及附近的居民，需要迅速采取行动以控制它们的数量。",h="“Slimy Menace”讲述了艾尔文森林中水晶湖沿岸日益严重的鱼人滋扰问题。这些极具攻击性的生物威胁要耗尽湖中的鱼类资源，并危及附近的居民，需要迅速采取行动以控制它们的数量。",kw={"水晶湖","艾尔文森林","鱼","闪金镇","鱼人","slimy menace"},ang={["faction:Alliance"]="保卫水晶湖的湖岸可以保护艾尔文当地的渔民和闪金镇附近的旅行者免受鱼人的袭击。",["race:Human"]="对于艾尔文森林的居民来说，鱼人的侵扰直接威胁着他们的水道、食物来源以及附近定居点的安全。"},sec={{t="水晶湖的麻烦",b="在水晶湖的东岸，一群极具攻击性的鱼人建立了立足点。这些野蛮的半水生生物长着锋利的牙齿，脾气暴躁，将原本平静的水域变成了危险的捕食场。当地居民的生计严重依赖于这个湖泊，但鱼人的出现现在威胁到了任何胆敢在此捕鱼或靠近水边的人。"},{t="无尽的滋扰",b="除了对旅行者造成的直接威胁外，如果任由这些鱼人繁衍，它们会吃光湖里的每一条鱼。削减它们的数量可以给当地水域带来急需的喘息之机，尽管它们那怪异、回荡的鸣叫声依然时刻提醒着人们它们的顽强。即使被驱散，鱼人也能迅速补充兵力，确保对湖岸保持警惕成为一项持续的必要工作。"}},faq={{q="“Slimy Menace”任务是关于什么的？",a="“Slimy Menace”是一项关于居住在水晶湖远岸的侵略性鱼人群体的本地任务。如果不加控制，这些两栖生物会吞食当地的鱼类，并威胁任何试图在附近工作或旅行的人。",al={"什么是slimy menace","slimy menace任务信息","slimy menace概述"}},{q="这个任务的事件发生在哪里？",a="这一骚乱发生在艾尔文森林的水晶湖，一群鱼人聚集在对岸的湖边。它们的出现破坏了湖泊的自然生态，并对当地居民构成了危险。",al={"水晶湖的鱼人在哪里","水晶湖位置","事件发生地点"}},{q="为什么要清理水晶湖的鱼人？",a="鱼人正在迅速消耗湖中的鱼类资源，同时用它们残暴的脾气和锋利的牙齿恐吓周围地区。清理它们的队伍有助于保护湖泊的渔业，并暂时阻止它们的扩张。",al={"为什么要杀死水晶湖的鱼人","鱼人吃鱼","鱼人有什么问题"}},{q="清理鱼人能彻底解决问题吗？",a="清理鱼人只能提供暂时的缓解。正如任务完成时所提到的，鱼人的繁殖和重组速度惊人，确保了尽管有最初的损失，它们的数量也会迅速恢复。",al={"鱼人永远消失了吗","我们消灭了鱼人吗","水晶湖的鱼人会回来吗"}},{q="是谁请求协助处理“Slimy Menace”？",a="该任务由一名关心水晶湖状况的艾尔文当地居民发布。他们对鱼人不安的鸣叫声和贪婪的食欲感到苦恼，因此请求冒险者削减这些生物的数量以保护渔场。",al={"谁发布了slimy menace","slimy menace任务发布者"}},{q="是什么让鱼人成为如此大的威胁？",a="鱼人被描述为残暴、脾气暴躁的两栖生物，长着锋利的牙齿，并发出臭名昭著的喉音。它们聚集在湖岸，极具攻击性地保卫领地，并袭击任何过于靠近它们捕食地点的生物。",al={"鱼人是什么样的","水晶湖鱼人的习性"}}},fp="12,255,23.409.0,22.433.0,37.239.0,45.220.0,47.247.0,58.213.0,40.227.0,37.257.0"}
P.entries["quest:99129"] = {n="A Man About a Murloc",s="“A Man About a Murloc”是一个委托，由一名叫杰森的渔夫发出，他深受当地鱼人的困扰，他的鱼货经常被鱼人抢走。杰森派遣冒险者去咨询雷米，一个当地的怪人，他对这些生物怀有深深的怨恨，并有着自己的盘算。",h="“A Man About a Murloc”是一个委托，由一名叫杰森的渔夫发出，他深受当地鱼人的困扰，他的鱼货经常被鱼人抢走。杰森派遣冒险者去咨询雷米，一个当地的怪人，他对这些生物怀有深深的怨恨，并有着自己的盘算。",kw={"a man about a murloc","艾尔文森林","鱼","杰森","鱼人","雷米"},ang={["faction:Alliance"]="像湖岸和码头这样的当地定居点经常遭受鱼人的入侵，使艾尔文森林及附近联盟领地的居民和卫兵倍感压力。"},sec={{t="水域危机",b="一位叫杰森的当地渔夫对鱼人抢劫他鱼货的行为感到厌倦。由于知道雷米同样憎恨这些两栖生物，杰森指引旅行者去咨询雷米，看看他是否想出了什么有效的办法将它们从水域中驱逐出去。"},{t="雷米的报复",b="当被问及此事时，雷米发泄着他的不满，称当地卫兵拒绝理会他关于鱼人威胁的持续警告。雷米没有等待官方的援助，而是准备了自己针对这些生物的报复措施，并招募能干的旅行者来协助他的计划。"}},faq={{q="谁发布了“A Man About a Murloc”这个任务？",a="当地渔夫杰森派遣冒险者执行此任务，寻求阻止鱼人抢夺他鱼货的方法。",al={"谁发布了a man about a murloc","谁开启了a man about a murloc","杰森鱼人任务"}},{q="雷米是谁？",a="雷米是一位以不断抱怨和警告鱼人威胁而闻名的居民，杰森向他咨询对抗鱼人的实际方案。",al={"雷米是谁","艾尔文森林的雷米","雷米在哪里"}},{q="为什么杰森要咨询雷米？",a="鱼人一直在侵扰杰森的捕鱼点并偷窃他的鱼，这促使他寻求外部帮助来保护他的生计。",al={"为什么杰森需要帮助","杰森 鱼 鱼人","杰森的鱼人问题"}},{q="雷米打算如何对付鱼人？",a="雷米声称镇上的卫兵无视他的警告，因此他制定了自己针对这些生物的报复计划，并需要冒险者协助收集材料。",al={"雷米的点子","雷米的计划是什么","雷米鱼人计划"}},{q="为什么卫兵没有处理鱼人的问题？",a="根据雷米的说法，他曾多次尝试向当地卫兵警告日益严重的鱼人威胁，但他们拒绝认真对待他的警告。",al={"艾尔文森林的卫兵与鱼人","为什么卫兵不帮助雷米","雷米的卫兵警告"}},{q="和雷米交谈后会发生什么？",a="与雷米的交谈直接引出了他反击当地鱼人的个人计划，从而引发了后续代表他进行的任务。",al={"a man about a murloc指向哪里","a man about a murloc之后","雷米之后的下一个任务"}}},fp="20,273,20.278.0,18.288.0,41.127.0,24.148.0,36.139.0,44.176.0,46.155.0,36.135.0"}
P.entries["quest:99130"] = {n="An Enticing Offer",s="“An Enticing Offer”是一项旨在利用用有毒的duskweed调制的诱饵来驱赶入侵鱼人的当地计划。通过直接从附近的农田收割这种有害杂草，该计划在协助当地农户的同时，也建立了针对海岸害虫的威慑。",h="“An Enticing Offer”是一项旨在利用用有毒的duskweed调制的诱饵来驱赶入侵鱼人的当地计划。通过直接从附近的农田收割这种有害杂草，该计划在协助当地农户的同时，也建立了针对海岸害虫的威慑。",kw={"an enticing offer","duskweed","jason","鱼人诱饵","鱼人","有毒诱饵"},ang={["class:Hunter"]="追踪者和驯兽师应注意duskweed的毒性，因为如果误食，由此制成的诱饵会对家养野兽和狩猎伙伴构成严重威胁。",["profession:Herbalism"]="熟悉当地植物的采集者会认识到duskweed的双重性质，这种讨人厌的杂草在调制强效诱饵时需要小心处理其有毒花瓣。"},sec={{t="一举两得的方案",b="对付鱼人泛滥通常需要更有创意的害虫防治手段，而不是无休止的正面冲突。“An Enticing Offer”提出了一种巧妙的解决方案，可以一举解决两个当地难题：制作一种掺有duskweed的特制诱饵，以阻止鱼人侵入定居点，同时在此过程中清除邻近农田中的杂草。"},{t="Duskweed的特性",b="这种合剂的核心成分是duskweed，一种困扰附近农田的顽固野生杂草。大量duskweed的花瓣中含有对大多数野兽有害的强力毒素。通过直接从受困扰的农户那里收集这种杂草，既能清除田地里肆虐的害虫植物，其有毒的产物又能为训练鱼人种群远离此地提供必要的原材料。"},{t="水域诱饵",b="虽然所得的合剂制备起来相对简单，但duskweed无差别的毒性使得处理它具有一定的危险性。家畜和宠物必须严格远离成品混合物，任务发布者临走前还提醒确保当地的熟人，也就是那个叫Jason的人，不会把这种刺鼻的诱饵当成食物。"}},faq={{q="任务“An Enticing Offer”是什么？",a="“An Enticing Offer”是一项旨在应对当地鱼人威胁，同时协助附近农户的任务。它涉及收集材料来调制一种专门用来驱赶这些生物的特殊有毒诱饵。",al={"什么是an enticing offer","这个任务是什么"}},{q="Duskweed是什么？",a="Duskweed是一种侵扰当地农田的常见杂草。虽然它通常被视为一种农业害虫，但其花瓣在大量堆积时对大多数动物有毒，这使得它在被浓缩成诱饵后成为一种有效的害虫威慑物。",al={"什么是duskweed","duskweed植物","duskweed的效果"}},{q="这种鱼人诱饵是如何起作用的？",a="该计划是制作注入了有毒duskweed花瓣的诱饵。目标不是常规的消灭，而是让诱饵变得足够令人不快或有害，从而训练当地的鱼人种群避开该区域。",al={"诱饵是如何起作用的","鱼人毒饵","为什么要制作诱饵"}},{q="Jason是谁？",a="Jason是一位因为鱼人骚扰而把你派去找Remy的渔夫。一旦有毒的duskweed诱饵制作完成，Remy嘱咐要告诉Jason千万别吃它。",al={"jason是谁","不要让jason吃掉它","关于诱饵给jason的警告"}},{q="这种鱼人诱饵对其他生物有危险吗？",a="是的。虽然它是针对鱼人的，但大量duskweed花瓣对大多数动物都有毒。任务发布者特别提醒，必须让家养宠物和狩猎伙伴远离这种混合物。",al={"duskweed诱饵有危险吗","宠物误食诱饵"}},{q="为什么说收集duskweed是双赢的？",a="Duskweed会疯狂入侵耕地，让当地农户头疼不已。收集这种杂草来酿制诱饵既能清理农田，又能同时提供击退鱼人所需的材料。",al={"为什么要帮助农户","双赢局面"}}},fp="17,283,18.401.0,22.404.0,18.369.0,36.216.0,17.240.0,40.208.0,13.152.0,48.210.0,47.224.0"}
P.entries["quest:99131"] = {n="Baited for Success",s="“Baited for Success”的任务内容是协助当地渔夫Jason Mathers处理棘手的鱼人骚扰问题。通过与Remy合作准备一种定向毒饵，Mathers希望能清理航道，从而安全地恢复捕鱼生意。",h="“Baited for Success”的任务内容是协助当地渔夫Jason Mathers处理棘手的鱼人骚扰问题。通过与Remy合作准备一种定向毒饵，Mathers希望能清理航道，从而安全地恢复捕鱼生意。",kw={"baited for success","钓鱼","jason mathers","鱼人","毒饵","remy"},ang={["class:Rogue"]="使用定制毒药作为控制麻烦鱼人的害虫防治手段，体现了一种务实、低调的解决问题方式。",["faction:Alliance"]="确保水域安全并恢复渔业等当地贸易，可以在减少鱼人威胁的同时，维持定居点的物资供应。"},sec={{t="渔夫的困境",b="Jason Mathers依靠开阔水域维持渔业贸易，但一群极具攻击性的鱼人扰乱了他的工作。由于无法安全地出售渔获，他试图寻找一种解决方法来清除该地区的生物。Remy介入并制作了一种专门的毒饵，旨在减少当地的鱼人数量，以便恢复正常的捕鱼作业。"},{t="定向解决方案",b="Remy准备了这种有毒混合物，并承诺会告知正确的使用方法，确保毒药只会针对鱼人，而不会污染鱼类。收到消息后，Mathers计划在当天晚些时候去收集混合物，希望它最终能清理水域并恢复他的生计。"}},faq={{q="是谁为Jason Mathers准备了诱饵？",a="Remy为Jason Mathers准备了专用诱饵，并承诺在Mathers当天晚些时候过来时，向他说明其正确的使用方法。",al={"谁发布baited for success","remy诱饵任务","谁制作了诱饵"}},{q="为什么Jason Mathers需要这种诱饵？",a="Jason Mathers是一位渔夫，由于当地鱼人的存在，他难以出售自己的渔获。这种毒饵旨在捕杀鱼人，同时又不伤害他打算捕捞和出售的鱼类。",al={"为什么jason mathers需要诱饵","mathers渔业生意","为什么使用毒饵"}},{q="毒饵会伤害鱼类吗？",a="Mathers特别提到了他对鱼类可能会误食毒饵的担忧。该计划依赖于毒药只针对鱼人而不伤害鱼类的特性，这样Mathers就能恢复他的生计。",al={"诱饵对鱼类安全吗","毒饵会杀死鱼类吗"}},{q="这项任务在哪里完成？",a="这项任务是通过直接将更新带回给Jason Mathers来完成的，让他知道Remy的准备工作正在进行中。",al={"在哪里交付baited for success","baited for success任务终点"}},{q="鱼人对Mathers构成了什么威胁？",a="鱼人扰乱了当地的捕鱼水域，使得像Mathers这样的渔夫在鱼人数量减少之前，无法正常谋生或谋生存在危险。",al={"为什么在这里消灭鱼人","mathers的鱼人问题"}},{q="Mathers在收到Remy的消息后有什么打算？",a="一旦消息送达，Mathers决定在当天晚些时候去找Remy领取毒饵，并接受关于如何安全部署它的指导。",al={"交付信息后会发生什么","mathers拿到了诱饵吗"}}},fp="18,253,21.332.0,19.287.1,40.131.0,38.184.0,37.189.0,29.127.0,43.148.0,49.152.0"}
P.entries["quest:99134"] = {n="Discipline",s="“纪律”是提瑞斯法林地的一项任务，由执行官塞加德发布。由于对当地死亡卫士驻军的能力感到不满，塞加德委托外来的冒险者对那些懈怠的亡灵哨兵施以体罚。",h="“纪律”是提瑞斯法林地的一项任务，由执行官塞加德发布。由于对当地死亡卫士驻军的能力感到不满，塞加德委托外来的冒险者对那些懈怠的亡灵哨兵施以体罚。",kw={"黑暗女王","死亡卫士","纪律","执行官塞加德","被遗忘者","激励棒","提瑞斯法林地","亡灵"},ang={["faction:Horde"]="被遗忘者指挥官们冷酷的手段展现了部落北部领地在生活和治理上那严苛且不留情面的现实。",["race:Undead"]="对于被遗忘者来说，军事纪律关乎种族的生存。屈服于冷漠的哨兵会危及整个提瑞斯法林地。"},sec={{t="在亡灵状态下强制执行秩序",b="死亡卫士构成了被遗忘者在洛丹伦的军事脊梁，但脱离了巫妖王的铁腕意志也带来了一些并发症：冷漠、疲劳和玩忽职守。像执行官塞加德这样的监工对于松懈的纪律几乎没有耐心，尤其是考虑到血色十字军和天灾军团的威胁正在提瑞斯法林地的边界徘徊。为了让部队保持敏锐，军官们依靠钝器和强硬的监督来维持军事战备状态。"},{t="执行官的账簿",b="执行官塞加德故意聘请独立的行动者，而不是驻军内部的士兵来执行惩罚。利用执行官的“激励棒”，外来者提醒玩忽职守的死亡卫士，在为黑暗女王服务时，生存需要绝对的警惕。那些玩忽职守的人很快就会明白，亡灵的身份并不能让他们逃脱惩罚。"}},faq={{q="谁发布了“纪律”任务？",a="“纪律”任务由执行官塞加德发布，他是一位驻扎在提瑞斯法林地的严苛的被遗忘者军官，负责监督区域防御，并要求部队绝对服从。",al={"纪律任务发布者","谁开启纪律任务","执行官塞加德任务"}},{q="执行官塞加德为什么要惩罚死亡卫士？",a="塞加德认为他指挥下的死亡卫士能力不足且缺乏应有的动力。因为自满威胁着被遗忘者在提瑞斯法林地的生存，他实施严厉的纪律，以震慑哨兵，使其保持警觉。",al={"为什么要惩罚死亡卫士","为什么要激励死亡卫士","塞加德惩罚死亡卫士的原因"}},{q="为什么塞加德使用冒险者而不是其他士兵？",a="塞加德指出，作为一个尚未成为死亡卫士一员的外来者，你还没有机会让他失望。",al={"为什么要我执行纪律","塞加德为什么使用外来者"}},{q="什么是执行官的“激励棒”？",a="执行官的“激励棒”是执行官塞加德提供的一种惩戒工具。它被用来对驻扎在提瑞斯法林地各处的懒散死亡卫士进行痛苦的训诫。",al={"执行官的激励棒","什么是执行官的激励棒"}},{q="如果你拒绝塞加德的命令会发生什么？",a="塞加德警告说，犹豫或拒绝会导致你的名字被记入他的账簿，标记你为下一个被他人惩戒的目标。",al={"塞加德的威胁","账簿威胁"}},{q="被遗忘者如何看待痛苦？",a="塞加德认为痛苦是他死后仅存的少数乐趣之一。他对于惩罚的热衷反映了他严酷的性格。",al={"亡灵是否会感到痛苦","被遗忘者痛苦背景"}}},fp="10,182,26.389.0,21.304.0,31.130.0,54.180.0,61.101.0,33.125.0,42.123.0,30.123.0"}
P.entries["quest:99141"] = {n="Patience",s="“耐心”是提瑞斯法林地执行官塞加德所分配的一项任务，要求为黑暗女王保持严明的军事纪律。由于常规战场报告逾期未交，塞加德派遣一名冒险者从附近的亡灵卫兵以及一个不同寻常的哨兵那里收集最新的报告。这项任务突显了被遗忘者领地内所执行的那种严苛、不妥协的纪律。",h="“耐心”是提瑞斯法林地执行官塞加德所分配的一项任务，要求为黑暗女王保持严明的军事纪律。由于常规战场报告逾期未交，塞加德派遣一名冒险者从附近的亡灵卫兵以及一个不同寻常的哨兵那里收集最新的报告。这项任务突显了被遗忘者领地内所...",kw={"布瑞尔","黑暗女王","亡灵卫兵","迪林格尔","戈多","克里斯托夫","耐心","静水池","提瑞斯法林地","塞加德"},ang={["faction:Horde"]="这项任务让到访的部落盟友得以一窥希尔瓦娜斯·风行者的军官们在整个提瑞斯法执行的那种冷酷、高度纪律化的指挥结构。",["race:Undead"]="对于新解放的被遗忘者来说，执行塞加德的命令强化了洛丹伦残酷的生存现实：对黑暗女王的绝对忠诚，以及对失败的零容忍。"},sec={{t="执行黑暗女王的意志",b="执行官塞加德负责指挥提瑞斯法林地的当地防务，他不容许任何疏忽。在塞加德看来，效忠希尔瓦娜斯女士必须时刻保持绝对的效率。当常规战场派遣报告没能按时送达他的哨岗时，他将其视为一次不可接受的失职，而非简单的延迟。他并没有离开岗位去亲自调查，而是派新来的被遗忘者特工去纠正那些玩忽职守的下属，确保边境依然稳固。"},{t="林地的哨兵",b="这些派遣任务涉及到驻守在布瑞尔周围关键观察点的哨兵。亡灵卫兵迪林格尔负责监视西边的墓地，那里经常有不法亡灵和天灾军团的残党在活动。在东边，亡灵卫兵克里斯托夫负责看守一处哨所，守卫着通往洛丹伦王城和东部道路的入口。而在他们之中最不寻常的要数戈多，一个在静水池附近游荡的庞大缝合怪，其单纯的思维让他去进行军事记录显得非常荒谬。"}},faq={{q="执行官塞加德是谁？",a="执行官塞加德是一名高级被遗忘者军官，负责维持提瑞斯法林地布瑞尔周边的秩序和防御。他直接向效忠于希尔瓦娜斯女士的指挥层负责，并要求他所监管的所有部队必须完美地执行任务。",al={"塞加德","谁是塞加德","执行官塞加德职责"}},{q="为什么塞加德要派冒险者去收集报告？",a="几名战场哨兵没能按时提交预定的报告。塞加德没有耐心等待，也不愿离开他的中央哨岗，于是他雇佣新获得自由的被遗忘者去乡野间找回那些逾期的派遣报告。",al={"为什么要完成耐心任务","为什么要收集报告"}},{q="戈多是谁，为什么他会有报告？",a="戈多是一个在静水池西边游荡的缝合怪。塞加德像对待其他战场哨兵一样期待从他那里得到状态报告，尽管在收到报告后，这位执行官很快意识到期待一个缝合怪写出书面情报是一个尴尬的判断失误。",al={"戈多","为什么缝合怪会有报告","谁是戈多"}},{q="亡灵卫兵迪林格尔在哪里？",a="亡灵卫兵迪林格尔驻扎在布瑞尔西侧，守卫着当地的墓地，监视徘徊的天灾活动和新复活的尸体。",al={"迪林格尔位置","找到迪林格尔","迪林格尔在哪里"}},{q="亡灵卫兵克里斯托夫驻扎在哪里？",a="亡灵卫兵克里斯托夫驻扎在布瑞尔以东道路旁的哨所，守卫入口以防入侵者，并监视路上的交通。",al={"克里斯托夫位置","找到克里斯托夫","克里斯托夫在哪里"}},{q="当戈多的报告被上交后会发生什么？",a="执行官塞加德承认期待一个缝合怪写出一份连贯的书面报告是一个愚蠢的错误。他默默接受了结果，并要求你将这次尴尬的疏忽仅限于你和他之间知道。",al={"戈多报告的结果","戈多书写"}}},fp="8,160,30.356.0,23.434.0,23.189.0,54.182.0,43.199.1,38.122.0,38.107.0,46.185.1"}
P.entries["quest:99142"] = {n="Tomb Weed",s="Tomb Weed是提瑞斯法林地的一项炼金任务，由药剂师助理霍兰德发布。霍兰德一直在改良野生的厄运草并将其重新种植在闹鬼的巴尼尔农场，这种被培育出的强力新样本意外地吸引了当地的天灾军团。",h="Tomb Weed是提瑞斯法林地的一项炼金任务，由药剂师助理霍兰德发布。霍兰德一直在改良野生的厄运草并将其重新种植在闹鬼的巴尼尔农场，这种被培育出的强力新样本意外地吸引了当地的天灾军团。",kw={"巴尼尔农场","厄运草","戈多","药剂师助理霍兰德","皇家药剂师学会","提瑞斯法林地","tomb weed"},ang={["profession:Herbalism"]="Tomb Weed展示了人工炼金操纵如何能从根本上改变像厄运草这样枯萎草药的特性和行为。",["race:Undead"]="药剂师助理霍兰德的研究表明，被遗忘者药剂师们一直致力于将提瑞斯法枯萎的植物群重塑为定制的炼金工具。"},sec={{t="霍兰德的培育",b="药剂师助理霍兰德并不满足于仅仅为皇家药剂师学会采集原生草药；他有着自己的宏大抱负。通过收集厄运草并对其进行细微的炼金改造，他将这些草药重新种植在巴尼尔农场的土壤中，培育出了一种他命名为Tomb Weed的进化样本。霍兰德将这种混合植物视为他工作的核心，也是他个人命运的前兆。"},{t="意外的吸引力",b="虽然霍兰德预料到了炼金效力，但将Tomb Weed移植到巴尼尔农场产生了意想不到的副作用。在枯萎的田野中游荡的天灾军团残余对这种茁壮成长的植物表现出了不可思议的普遍吸引力。霍兰德依靠路过的旅行者来突破这些入侵的亡灵并收获成熟的作物，以便他能继续他的实验。"}},faq={{q="什么是Tomb Weed？",a="Tomb Weed是由药剂师助理霍兰德培育的一种经炼金改良的厄运草变种。他采集原生的厄运草，用化学试剂对其进行改造，并将其种植在巴尼尔农场枯萎的土壤中。",al={"什么是tomb weed","tomb weed背景故事","tomb weed植物"}},{q="药剂师助理霍兰德是谁？",a="霍兰德是皇家药剂师学会的一员，在提瑞斯法林地工作。他雄心勃勃，经常被像憎恶戈多这样的助手弄得心烦意乱，霍兰德进行私人园艺和炼金实验，旨在提升自己的地位。",al={"霍兰德是谁","药剂师助理霍兰德","药剂师霍兰德"}},{q="Tomb Weed种植在哪里？",a="霍兰德将他改良的作物种植在巴尼尔农场，这是一处位于提瑞斯法林地东部的废弃庄园，现已陷入枯萎和荒废之中。",al={"去哪里找tomb weed","tomb weed位置","巴尼尔农场的杂草"}},{q="为什么天灾军团会被Tomb Weed吸引？",a="霍兰德观察到，游荡在巴尼尔农场中毫无意识的天灾军团似乎本能地被这种改良植物所吸引，尽管他不知道原因；他只是觉得这很奇怪。",al={"为什么天灾军团想要tomb weed","天灾军团被tomb weed吸引","天灾军团的反应"}},{q="Tomb Weed与普通厄运草有何不同？",a="厄运草是一种在布瑞尔墓地北部的乱葬岗附近自然生长的植物。Tomb Weed是在霍兰德的指导下，将厄运草进行人工炼金改造并选择性地重新种植在农场土壤中而产生的。",al={"厄运草与tomb weed的区别","厄运草和tomb weed的差异"}},{q="霍兰德提到的戈多是谁？",a="戈多是被遗忘者制造的一只游荡的憎恶，在提瑞斯法林地的道路上徘徊，通常被霍兰德分配一些对他迟钝的大脑来说很困难的简单任务。",al={"戈多是谁","戈多行踪","戈多提瑞斯法"}}},fp="9,166,21.342.0,21.262.0,18.163.0,33.248.0,25.137.0,43.132.0,48.180.0,34.171.0"}
P.entries["quest:99143"] = {n="Bottles and Baubles",s="Bottles and Baubles 是一个任务，其核心逻辑有些古怪：既然鱼人长得像鱼，那它们的思维一定也像鱼。冒险者被派往附近的鱼人营地，搜寻那些闪闪发光的垃圾和废弃的小玩意，一位急切的垂钓者可以将它们制成鱼饵。",h="Bottles and Baubles 是一个任务，其核心逻辑有些古怪：既然鱼人长得像鱼，那它们的思维一定也像鱼。冒险者被派往附近的鱼人营地，搜寻那些闪闪发光的垃圾和废弃的小玩意，一位急切的垂钓者可以将它们制成鱼饵。",kw={"鱼饵","bottles and baubles","钓鱼","假饵","鱼人","鱼人营地","闪亮垃圾"},sec={{t="鱼类逻辑与海岸拾荒",b="Bottles and Baubles 从一个非常奇特的海洋生物学理论开始：既然鱼人是类鱼生物，它们的思维方式一定和深海中游动的鱼类一样。基于这种逻辑，一位古怪的垂钓者断言，任何能吸引鱼人目光的好奇之物，也一定能引诱饥饿的鱼儿上钩。冒险者们受命前往附近的鱼人营地，搜刮它们的囤积物，收集闪闪发光的废弃垃圾，以验证这一假说。"},{t="闪亮的小玩意作为鱼饵",b="沿海水道和河岸上的鱼人是臭名昭著的拾荒者，它们在小屋周围杂乱地堆积着明亮的石头、贝壳、抛光的玻璃碎片和金属残渣。翻找这些泥泞的堆积物，可以找到各种各样闪闪发光的废品，机会主义的渔夫可以将它们制成简陋的假饵和闪光片。一旦收回并上交，这些奇怪的杂物足以让冒险者获得一套入门钓鱼用品。"}},faq={{q="为什么要从鱼人那里收集垃圾？",a="任务发布者认为，既然鱼人长得像鱼，它们的思维也一定和鱼一样。基于“吸引鱼人的东西也能吸引水底的鱼”这一理论，冒险者们被派往鱼人营地搜刮饰品和闪亮的废品，将其改造成鱼饵。",al={"为什么要收集垃圾","bottles and baubles有什么用","鱼人闪亮垃圾"}},{q="哪里可以找到闪亮的垃圾？",a="闪亮的垃圾散落在附近的鱼人营地周围。鱼人是臭名昭著的拾荒者，它们会在海岸线和水道沿岸囤积闪闪发光的碎片、废弃的饰品和玻璃，这些可以直接从它们的地盘上获取。",al={"在哪里找到垃圾","鱼人营地位置","如何获得闪亮垃圾"}},{q="谁发布了这个任务，他们想要什么？",a="该任务由一位当地的垂钓者委托，他正想储备一些假饵和鱼饵。虽然他对鱼人心理学的理论有些古怪，但他会用多余的垂钓装备奖励热心的拾荒者，以鼓励新手们学习这门手艺。",al={"谁发布了bottles and baubles","任务发布者是谁","任务交还"}},{q="鱼人真的像鱼一样思考吗？",a="尽管任务发布者有这种推理，但鱼人是两栖的部落类人生物，而不是简单的无脑鱼类。然而，就像许多生物和捕食者一样，它们天生会被闪闪发光的物品、抛光的贝壳和明亮的小玩意所吸引，从而形成了恰好包含闪亮材料的囤积堆。",al={"鱼人像鱼一样思考吗","鱼人的智力","鱼人真的是鱼吗"}},{q="鱼人的垃圾将如何被用作鱼饵？",a="收集到的垃圾包括反光玻璃、金属碎片和抛光的零碎物件。这位垂钓者打算将这些反光碎片制成假饵和临时鱼饵，希望它们的光泽能模仿小鱼，或者引起觅食鱼类的好奇。",al={"闪亮垃圾的用途","闪亮垃圾是鱼饵吗","鱼人垃圾能当鱼饵吗"}},{q="任务发布者提供什么奖励？",a="在带回足够多合适的闪亮碎片后，任务发布者会交出他以前的个人垂钓用品。这些基础工具和补给旨在帮助有抱负的渔夫们站稳脚跟，并在水边试手。",al={"bottles and baubles的奖励是什么","你能得到什么","钓鱼用品奖励"}}},fp="19,280,35.496.0,24.470.0,45.303.0,30.252.0,42.241.0,36.299.0,41.262.0,43.233.0"}
P.entries["quest:99144"] = {n="Seeking Refuge",s="Seeking Refuge是提瑞斯法林地的一项任务，内容是营救班达里安堡的使者Bareth Dawnstone，他被囚禁在Crusader's Outpost。他的挣扎凸显了一个非传统教派的出现，该教派尽管受到了当地狂热分子的严重偏见，却依然虔诚于圣光。将他逃脱的消息安全传回布瑞尔，为这个初生的圣所确立了至关重要的联系。",h="Seeking Refuge是提瑞斯法林地的一项任务，内容是营救班达里安堡的使者Bareth Dawnstone，他被囚禁在Crusader's...",kw={"班达里安堡","bareth dawnstone","布瑞尔","crusader's outpost","十字军","圣光","seeking refuge","shari stilwell","索利丹农场","提瑞斯法林地"},ang={["class:Paladin"]="圣骑士们可以留意一下Crusader's Outpost的狂热分子与Bareth Dawnstone之间的对比：前者怀着仇恨运用圣光，而后者追求仁慈与保护。",["class:Priest"]="牧师们会发现班达里安堡的哲学非常迷人，因为尽管周围对亡灵施法者存在偏见，其成员仍在追求纯粹的冥想和圣光的指引。",["faction:Horde"]="确保班达里安堡和布瑞尔之间的信使安全，可以确保新兴的中立或盟友教派在提瑞斯法林地站稳脚跟，以对抗敌对的十字军。",["race:Undead"]="依然崇敬圣光的被遗忘者既面临来自活人狂热分子的敌意，也面临来自怀疑论同胞的敌意，这使得班达里安堡不断壮大的兄弟会成为了一个罕见的圣所。"},sec={{t="危险的旅程",b="Seeking Refuge讲述了班达里安堡隐秘修道院派遣的信使Bareth Dawnstone的惊险旅程。在前往布瑞尔与Shari Stilwell商议的途中，Bareth在Crusader's Outpost被狂热的战士拦截并俘虏。尽管他的亡灵身份招致了仇恨，但Bareth对圣光的虔诚始终如一，他唯一的渴望就是逃离折磨者，并确保他的信息送达目的地。"},{t="复仇与虔诚",b="Bareth的被囚突显了笼罩在提瑞斯法林地的痛苦意识形态分歧。Crusader's Outpost的狂热分子通过复仇的愤怒和教条式的正义来引导圣光，将Bareth的存在视为一种冒犯。相比之下，Dawnstone将圣光视为保护和内在纯洁的源泉，他感叹捕获者的残忍扭曲了他所珍视的神圣教义。"},{t="山崖上的圣所",b="逃脱后，Bareth在布瑞尔向Shari Stilwell确认了安全。Stilwell透露，他们的修道会仍在索利丹农场西北部的山崖上扎根。失去像Dawnstone这样有前途的修行者，对他们年轻的团体来说将是沉重的打击，该团体向任何寻求真正精神指引的旅行者敞开大门。"}},faq={{q="Bareth Dawnstone是谁？",a="Bareth Dawnstone是班达里安堡的一位圣光信徒。在前往布瑞尔传递信息的途中，他遭到了厌恶他这一类的狂热十字军的伏击并被监禁。尽管他身为亡灵，但他仍冥想圣光，并努力利用圣光进行保护。",al={"bareth dawnstone是谁","bareth dawnstone背景故事","dawnstone"}},{q="谁俘虏了Bareth Dawnstone，为什么？",a="驻扎在Crusader's Outpost的狂热分子在从班达里安堡通往布瑞尔的路上伏击了Bareth Dawnstone。他感叹道，他的捕获者内心怀着强烈的仇恨运用圣光，扭曲了他所冥想的仁慈美德，并迫害那些他们视为憎恶之物的人。",al={"谁俘虏了bareth dawnstone","crusader's outpost捕获者","他为何被俘"}},{q="Shari Stilwell是谁？",a="Shari Stilwell是驻扎在被遗忘者城镇布瑞尔的修道会代表。她接待旅行者，并与从班达里安堡派遣的使者进行协调，欢迎任何寻求圣光指引的人。",al={"shari stilwell是谁","stilwell 布瑞尔","shari 布瑞尔"}},{q="什么是班达里安堡？",a="班达里安堡是一座隐秘的修道院，位于提瑞斯法林地的索利丹农场西北部的山崖上。它是一个蓬勃发展的宗教教派的圣所和训练场，致力于对圣光的纯粹冥想和研究。",al={"什么是班达里安堡","班达里安堡在哪里","索利丹西北部的修道院"}},{q="为什么Bareth的捕获者会对他的种族有意见？",a="Bareth Dawnstone提到了“我仅存的血液”，并承认了针对他这一类的偏见，这表明他是一位圣光的亡灵修行者。提瑞斯法的狂热十字军鄙视所有亡灵，拒绝相信他们的意图或虔诚可能是纯洁的。",al={"为什么他们仇恨他这类人","亡灵使用圣光","bareth我仅存的血液"}},{q="班达里安堡驻扎的是什么样的教派？",a="驻扎在班达里安堡的教派是一个年轻、不断发展的修道兄弟会，正在提瑞斯法的山崖上扎根。与附近充满仇恨的十字军不同，他们宣扬和平的冥想和保护，并向任何寻求圣光真正指引的人敞开大门。",al={"班达里安堡的教派是什么","班达里安堡僧侣","班达里安信仰"}}},fp="14,381,18.460.0,25.409.0,23.384.0,24.289.0,39.284.0,22.241.0,23.253.0,49.282.0,46.265.0"}
P.entries["quest:99152"] = {n="As Above, So Below",s="“As Above, So Below”是班达里安堡的破击者希尔达发布的一项任务，旨在应对影谷下方潜藏的天灾军团渗透。通过回收那些仍带有新鲜复生魔法气息的骸骨，保卫者们试图弄清楚亡灵是如何在城镇下方悄无声息地聚集起来的。",h="“As Above, So Below”是班达里安堡的破击者希尔达发布的一项任务，旨在应对影谷下方潜藏的天灾军团渗透。通过回收那些仍带有新鲜复生魔法气息的骸骨，保卫者们试图弄清楚亡灵是如何在城镇下方悄无声息地聚集起来的。",kw={"as above so below","班达里安堡","发光的骸骨","破击者希尔达","复生魔法","天灾军团","影谷","玷污者"},ang={["class:Mage"]="法师们会注意到附着在发光骸骨上的残留复生魔法，这暗示了隐藏在城镇下方的特定死灵技术。",["class:Paladin"]="圣骑士将任何未被察觉的天灾势力视为迫在眉睫的危险，因此调查影谷下方的复生魔法是一项紧迫的职责。",["class:Priest"]="受过反亡灵训练的牧师们对于在定居点下方滋生的黑暗复生艺术感到十分忧虑。"},sec={{t="隐秘的威胁",b="在班达里安堡，破击者希尔达负责监督防御者们针对周边险境进行的严格训练。尽管地表的目光都集中在西南方向动荡不安的影谷定居点——那里有一个被称为“玷污者”的敌对势力频繁制造事端——但在视线之外，更大的危险已经扎根。在城镇下方的阴暗地窖中，一股未被察觉的天灾力量正在积蓄，如果任其发展，随时可能对堡垒发动突袭。"},{t="地窖中的魔法",b="希尔达不愿让毫无经验的学员盲目闯入地下墓穴，因此派遣经验丰富的冒险者直接进入影谷下方的地窖。这不仅仅是一次清剿行动，其首要目标是收集情报：回收那些仍带有残留复生魔法的骸骨残骸。研究这些微弱发光的骨头，能让防御者们有机会破解这种黑暗死灵术是如何在眼皮底下悄然运作的。"}},faq={{q="什么是“As Above, So Below”？",a="“As Above, So Below”是破击者希尔达委派的一项任务，旨在调查潜伏在影谷定居点下方的天灾军团势力。在班达里安堡的学员们接受操练的同时，一位冒险者被派往城镇下方收集复生的骸骨样本。",al={"什么是 as above so below","as above so below 任务"}},{q="是谁发布了“As Above, So Below”任务？",a="破击者希尔达是班达里安堡一位严苛的教官，负责训练新兵。她坚韧且不妥协，对指挥下的任何人都有严格的要求，她宁愿新兵躺着被抬回来，也不愿他们空手而归。",al={"谁发布了 as above so below","谁是破击者希尔达","任务发布者希尔达"}},{q="影谷位于哪里？",a="影谷位于班达里安堡的西南方。虽然地表的麻烦主要源于一个名为“玷污者”的团体，但其地下的地窖中却隐藏着更阴险的亡灵侵害。",al={"影谷在哪里","影谷位置"}},{q="潜伏在影谷下方的是什么威胁？",a="影谷下方的地窖已被复生的亡灵所占据。如果放任不管，这股隐藏的天灾势力随时可能引发一场针对附近班达里安堡的全面暴乱。",al={"影谷下方的地窖是什么","影谷地窖中的天灾军团","影谷下方的威胁"}},{q="希尔达为什么需要微弱发光的骸骨？",a="希尔达需要那些仍带有复生魔法残留气息的骸骨。通过研究这些发光的残骸，防御者们希望能够理解死灵法师是如何在未被发现的情况下策划这场暴乱的。",al={"为什么要收集发光的骸骨","微弱发光骸骨的用途","复生魔法骸骨"}},{q="影谷的“玷污者”是谁？",a="“玷污者”是一个活跃在影谷地表的敌对势力。尽管他们对该地区构成了现实威胁，但希尔达认为城镇下方隐藏的天灾巢穴才是更加危险的敌人。",al={"谁是玷污者","影谷的玷污者"}}},fp="18,203,17.307.0,20.376.1,27.213.0,39.229.0,28.136.0,37.139.0,42.155.0,36.137.0"}
P.entries["quest:99153"] = {n="The One That Got Away",s="The One That Got Away 是一个由 Ephram Barbaro 发布的任务，旨在追踪一名从纳克萨玛斯残骸附近的冲突中逃脱的邪教徒。这名逃犯带着一块活跃的聚焦水晶碎片逃进了影谷下方，该水晶碎片可能会强化亡灵或使其复活。",h="The One That Got Away 是一个由 Ephram Barbaro...",kw={"水晶碎片","邪教徒","ephram barbaro","聚焦水晶","纳克萨玛斯","影谷","the one that got away"},ang={["class:Paladin"]="发誓要清除死灵威胁的圣骑士会意识到任由天灾军团聚焦水晶保持活跃的危险性，特别是那些能够复活或增强地下亡灵的碎片。",["class:Priest"]="熟悉对抗黑暗魔法的牧师们明白，如果不及时回收和净化，亵渎的圣物可能会腐蚀周围的区域。"},sec={{t="影中的逃犯",b="在纳克萨玛斯战役的残骸周围与邪教徒发生冲突后，消息很快在队伍中传开了。Ephram Barbaro 在得知一名落单的邪教徒带着一块活跃的天灾军团聚焦水晶碎片潜逃出包围圈后，开始寻找有能力的冒险者。"},{t="影谷之下的威胁",b="情报显示这名逃跑的邪教徒逃进了影谷下方的地下通道。这块碎片仍然蕴含着黑暗的死灵能量，据推测它要么正在复活亡灵，要么在增强潜伏在地下深处的敌对势力。Barbaro 指派冒险者去追踪并收回这块隐藏的水晶，以免其力量引发更大的灾难。"}},faq={{q="谁发布了任务 The One That Got Away？",a="该任务由 Ephram Barbaro 发布，他在听闻你之前处理纳克萨玛斯战役残骸附近邪教徒的事迹后联系了你。",al={"谁发布了 the one that got away","谁开启了这个任务","the one that got away 任务发布者"}},{q="什么是聚焦水晶碎片？",a="这是由一名逃脱的邪教徒带走的天灾军团聚焦水晶的残留碎片。Ephram Barbaro 指出它仍然具有力量，并且正在影谷下方复活亡灵或增强现有亡灵的力量。",al={"什么是水晶碎片","水晶有什么用","为什么水晶很危险"}},{q="水晶碎片在哪里？",a="根据 Ephram Barbaro 的情报，那名逃亡的邪教徒带着圣物逃到了影谷下方，并将其藏在了地下的某个地方，其力量正不断从中渗出。",al={"水晶藏在哪里","影谷水晶位置","哪里寻找水晶碎片"}},{q="谁是“The One That Got Away”（漏网之鱼）？",a="这个称号指的是一名在纳克萨玛斯战役残骸的冲突后成功溜走的邪教徒，他们带走了一块活跃的聚焦水晶碎片。",al={"谁带着水晶逃跑了","持有水晶的邪教徒","the one that got away 含义"}},{q="当你把水晶交给 Ephram Barbaro 时会发生什么？",a="在归还回收的水晶碎片后，Ephram Barbaro 会称赞你的速度，并表示是时候进行处理这一情况时他最喜欢的部分了。",al={"归还水晶后发生什么","交付 the one that got away","ephram barbaro 最喜欢的部分"}},{q="Ephram Barbaro 是如何认识你的？",a="Ephram 提到消息在队伍中传得很快，特别提到了之前在纳克萨玛斯战役残骸周围对付邪教徒的工作。",al={"纳克萨玛斯战役残骸邪教徒","ephram 是怎么认识你的","the one that got away 前置条件"}}},fp="21,192,25.263.0,29.262.0,42.123.0,38.192.0,38.108.0,31.132.0,59.133.0,39.144.0"}
P.entries["quest:99156"] = {n="Rear Guard Patrol",s="Rear Guard Patrol 是亡灵卫兵林奈在提瑞斯法林地发布的一项关键防御任务。巡逻队员的任务不仅仅是击退漫无目的游荡的食尸鬼，还要搜寻并消灭撕裂者。这只缝合怪一直在毒蛛峡谷附近徘徊，它本不该越过亡灵壁垒。",h="Rear Guard Patrol 是亡灵卫兵林奈在提瑞斯法林地发布的一项关键防御任务。巡逻队员的任务不仅仅是击退漫无目的游荡的食尸鬼，还要搜寻并消灭撕裂者。这只缝合怪一直在毒蛛峡谷附近徘徊，它本不该越过亡灵壁垒。",kw={"缝合怪","亡灵壁垒","亡灵卫兵林奈","rear guard patrol","撕裂者","提瑞斯法林地","毒蛛峡谷"},ang={["faction:Horde"]="确保提瑞斯法东部边境的安全，可以保证供给亡灵壁垒和幽暗城的补给线不会受到流浪恐怖生物的威胁。",["race:Undead"]="被遗忘者无法承受两线作战的代价；任何在他们防线后方游荡的天灾构装体，对其王国而言都是一种生存威胁。"},sec={{t="边境的缺口",b="亡灵壁垒是提瑞斯法林地与西瘟疫之地恐怖势力之间唯一的坚固屏障。被遗忘者军队的战略完全建立在严格的单线战争基础上。如果这些毫无理智的亡灵溜到了防线后方，供给前线的补给线可能会瞬间被切断。虽然偶尔会有流浪的幽灵或食尸鬼绕过路障，但有报告称一只缝合怪正在林地中游荡，这标志着防御工作的严重失败。"},{t="撕裂者的威胁",b="那只名为撕裂者的游荡怪物被发现正笨重地在毒蛛峡谷附近移动，位于亡灵壁垒的前沿堡垒后方。缝合怪是巨大的杀戮机器，由尸体和黑暗死灵法术缝合而成。它们不可能在毫无察觉的情况下穿过严密防守的关隘，这让亡灵卫兵林奈对于这个生物如何穿过防御圈感到非常不安。林奈要求取得撕裂者的心脏，以此作为其被彻底消灭的终极证明。"}},faq={{q="谁提供了 Rear Guard Patrol 这个任务？",a="巡逻指令由亡灵卫兵林奈发布，她是提瑞斯法林地的一名被遗忘者亡灵卫兵，直接向执行官塞加德汇报。",al={"谁发布 rear guard patrol","rear guard patrol 任务发布者","谁发布了这个任务"}},{q="撕裂者是什么？",a="撕裂者是一只流窜的缝合怪，被发现在毒蛛峡谷附近的东部林地游荡，位于前沿防线后方。",al={"谁是撕裂者","撕裂者是什么","撕裂者背景"}},{q="为什么缝合怪出现在毒蛛峡谷附近如此令人担忧？",a="缝合怪是巨大的构装体，制造它们需要黑暗死灵法术和繁重的劳作。在不知不觉中穿过戒备森严的亡灵壁垒理应是不可能的，这意味着在被遗忘者的防线后方存在一个令人震惊的缺口，或是一条未被发现的通道。",al={"为什么撕裂者是个大麻烦","为什么缝合怪在这里很危险","亡灵壁垒缺口"}},{q="这头野兽通常在哪里出没？",a="目击报告显示，撕裂者一直在提瑞斯法林地东部的树林和空地中游荡，就在毒蛛峡谷附近。",al={"撕裂者在哪里","撕裂者位置","去哪里找缝合怪"}},{q="完成巡逻需要什么证明？",a="亡灵卫兵林奈需要撕裂者的心脏来验证这只巨大的怪物已被永久消灭。",al={"我该给林奈带什么","任务提交物品","撕裂者死亡证明"}},{q="谁负责监管亡灵壁垒的防御？",a="任务中没有提到亡灵壁垒的指挥官。亡灵卫兵林奈听命于她在布瑞尔的上级执行官塞加德，后者会接收她因成功抵御天灾军团而获得的嘉奖。",al={"谁负责亡灵壁垒","林奈的上级","执行官塞加德"}}},fp="17,176,24.399.0,21.356.1,39.116.0,16.119.0,53.186.0,33.103.0,44.108.0,40.165.0"}
P.entries["quest:99158"] = {n="Dawn in the Mountains",s="Dawn in the Mountains是一个任务，要求将一箱圣烛运送给雾松避难所的加文神父。作为银色黎明的一名温和的牧师，加文维护着这个山中避难所，旨在治愈和慰藉疲惫的旅人，而非通过武力进行战争。",h="Dawn in the Mountains是一个任务，要求将一箱圣烛运送给雾松避难所的加文神父。作为银色黎明的一名温和的牧师，加文维护着这个山中避难所，旨在治愈和慰藉疲惫的旅人，而非通过武力进行战争。",kw={"银色黎明","dawn in the mountains","加文神父","圣烛","雾松避难所","牧师","避难所"},ang={["class:Priest"]="加文神父体现了牧师更温和、更具修复力的道路，他选择关怀旅人和包扎伤口，而不是在银色黎明的前线挥舞武器。",["faction:Alliance"]="向雾松避难所这样的银色黎明庇护所提供物资，有助于在危险且充满争议的山地地形中开展中立的人道主义工作。",["faction:Horde"]="银色黎明接受援助并提供避难所，不论其立场如何，这使得加文神父的这类前哨站成为荒野中罕见的安全港湾。"},sec={{t="群峰中的庇护所",b="尽管许多银色黎明的成员拿起武器去清除艾泽拉斯的邪恶恐怖，但有些人选择了圣光更温和的召唤。加文神父是一位居住在崎岖山野中的牧师，他远离了刀剑，全心全意地致力于治愈伤痛和照料疲惫之人。他利用一处废弃的建筑，将其改造成了雾松避难所，为面对高海拔山口危险的旅人们提供了一个安全的驻足点。"},{t="为了圣光的蜡烛",b="在山中维护一个与世隔绝的避难所需要持续的维护和务实的奉献。为了维持他的神职工作并保持灯火和祭坛常亮，加文神父依赖远方盟友的慈善。一箱圣烛的运抵确保了这座避难所能在无情的荒野中继续作为光明、温暖和希望的灯塔。"}},faq={{q="谁是加文神父？",a="加文神父是银色黎明的一名牧师，驻扎在群山之中。与许多圣职人员拿起武器对抗邪恶不同，加文主要致力于治愈伤痛、慰藉旅人，并在雾松避难所提供庇护。",al={"谁是加文神父","加文神父的背景故事","雾松避难所的牧师是谁"}},{q="什么是雾松避难所？",a="雾松避难所是由加文神父建立的供山中旅人休憩的站点。他翻新了荒野中的一栋旧建筑，创造了一个宁静的庇护所，流浪者可以在此恢复体力、休息并接受治疗。",al={"什么是雾松避难所","雾松避难所在哪里","雾松避难所的背景故事"}},{q="什么是银色黎明？",a="银色黎明是一个致力于在艾泽拉斯全境搜寻并摧毁邪恶与非自然威胁的圣职组织，同时也为那些在困苦之地的挣扎求生者提供援助与慰藉。",al={"什么是银色黎明","银色黎明的宗旨","谁是银色黎明"}},{q="为什么加文神父需要一箱圣烛？",a="这箱圣烛旨在补充加文神父在雾松避难所的物资。在圣职事奉和偏远的避难所中，这些祝圣过的蜡烛对于宗教仪式、祈祷以及为疲惫的旅人照亮避难所至关重要。",al={"为什么要蜡烛","圣烛的用途","运送一箱圣烛"}},{q="加文神父会像其他银色黎明成员一样拿起武器吗？",a="加文神父更倾向于治愈和庇护旅人，而不是拿起武器。尽管银色黎明以对抗黑暗的武装十字军闻名，但加文通过同情心、好客和精神关怀来服务该组织。",al={"加文神父会战斗吗","加文神父是战士吗"}},{q="任务Dawn in the Mountains的目的是什么？",a="该任务要求前往山区的旅人将一箱圣烛直接运送给雾松避难所的加文神父，以支持他那简朴的山中庇护所。",al={"谁发布了这个任务","dawn in the mountains通向哪里"}}},fp="21,253,24.429.0,21.363.0,20.261.0,26.218.0,24.210.0,54.244.0,62.223.0,55.176.0"}
P.entries["quest:99159"] = {n="Finding Warmth",s="Finding Warmth是一项朴素的差事，核心是为温暖的炉火添柴。由于主人忙于其他事务，旅人受托收集木柴，以便让寻求温暖的灵魂能得到慰藉。完成任务可以维持炉火不灭，并开启后续的差事。",h="Finding Warmth是一项朴素的差事，核心是为温暖的炉火添柴。由于主人忙于其他事务，旅人受托收集木柴，以便让寻求温暖的灵魂能得到慰藉。完成任务可以维持炉火不灭，并开启后续的差事。",kw={"finding warmth","木柴","炉火","圣光","温暖","木材"},sec={{t="温暖的炉火",b="Finding Warmth是一项为了维持温暖炉火而进行的简单琐事。任务发布者随时保持炉火通明，以温暖任何路过的灵魂，但日益繁重的责任使他们无暇亲自收集燃料。通过代为收集木柴，旅人们确保了炉火能为任何寻求庇护与慰藉的人继续燃烧。"},{t="照看炉火",b="并非所有从周边收集的木料都能立即燃烧。运回后，太潮湿而无法点燃的木头会被放在一边晾干，而干燥的木材则会立即投入火中。主人对这及时的帮助感到满意，并迅速转向其他仍需关注的紧迫事务。"}},faq={{q="任务Finding Warmth的内容是什么？",a="Finding Warmth是一项当地任务，要求冒险者收集木柴以维持温暖的炉火。任务发布者通常会亲自照看火堆，但由于忙于其他紧迫的杂务，不得不寻求外界的帮助。",al={"finding warmth任务","什么是finding warmth","finding warmth木柴"}},{q="为什么需要这些木柴？",a="这些木柴用于维持一个开放的炉火，为路过的旅人和当地居民提供温暖与慰藉。收集木柴原本是一项普通的琐事，但由于主人忙于其他职责而耽搁了。",al={"为什么需要木材","木柴 finding warmth","炉火 木柴"}},{q="带来的湿木柴会怎么样？",a="收集到的一些原木在送达时可能太潮湿或太湿而无法立即燃烧。任务发布者会将潮湿的部分放在一边晾干，同时使用干燥的木材立即添火。",al={"finding warmth 湿木头","潮湿的木柴"}},{q="是什么样的人发布这个任务的？",a="虽然主人的具体身份未作详细说明，但他们那句“愿圣光指引你的任务”表明，这是一个根植于对圣光的信仰或敬畏的人，他们提供开放的炉火来温暖每一个灵魂。",al={"谁发布finding warmth","finding warmth 愿圣光指引你"}},{q="完成Finding Warmth后还有更多任务吗？",a="是的。在交付木柴后，主人提到手头还有其他任务，如果旅人愿意进一步帮忙，他们需要一双能干的手。",al={"finding warmth后的更多任务","finding warmth后续"}},{q="谁可以在这个炉火旁休息？",a="主人保持炉火燃烧，是为了给任何路过、可能需要从寒冷或疲惫的旅途中得到片刻休憩的人提供庇护、慰藉和温暖。",al={"炉火 开放 灵魂","开放的炉火 finding warmth"}}},fp="14,309,18.337.0,16.324.0,39.254.0,27.200.0,40.195.0,37.219.0,53.160.0,30.157.0"}
P.entries["quest:99160"] = {n="Rime's Wrath",s="Rime's Wrath 是一个专注于平息小型冰元素危险爆发的任务。由于不知如何和平地安抚这些充满攻击性的霜冻之灵，消灭它们成为了保障地区安全的必要手段。",h="Rime's Wrath 是一个专注于平息小型冰元素危险爆发的任务。由于不知如何和平地安抚这些充满攻击性的霜冻之灵，消灭它们成为了保障地区安全的必要手段。",kw={"元素","冰霜","冰元素","小型冰元素","安抚","rime's wrath"},ang={["class:Mage"]="冰霜法师研究冰霜魔法的原始塑形与召唤，这使得狂野的小型冰元素成为了一种引人入胜却又难以驾驭的元素力量展示。",["class:Shaman"]="萨满祭司致力于理解并与元素之灵沟通，但这些敌对的冰霜实体显然超出了和平安抚的范畴，只能通过武力予以平息。"},sec={{t="苦涩的显现",b="Rime's Wrath 涉及处理局部小型冰元素涌动的问题。这些由刺骨严寒构成的元素之灵已成为该地区切实存在的危险，必须迅速采取干预措施，以免它们的寒气进一步蔓延或伤害过往行人。这并非有组织的突袭，而是一种针对狂暴、敌对元素显现的遏制手段。"},{t="无法安抚",b="虽然理想的结果是安抚那些狂躁的霜冻之灵，但安抚它们所需的知识遥不可及。由于没有实际可行的和平手段，且这些元素之灵变得日益危险，剩下的唯一选择便是消灭它们，以保护周边地区。"}},faq={{q="什么是 Rime's Wrath？",a="Rime's Wrath 是一个要求消灭构成直接威胁的小型冰元素的任务。由于不知晓或无法使用和平手段来平息这些狂躁的元素之灵，直接动武成为了维持安全的唯一选择。",al={"什么是 rime's wrath","rime's wrath 任务","rime's wrath 概述"}},{q="为什么必须消灭小型冰元素？",a="这些小型冰元素变得过于不稳定且危险，不能放任不管。虽然和平安抚是首选，但缺乏让它们平静下来的知识，因此消灭它们成为了必要的手段。",al={"为什么要消灭冰元素","为什么要与它们战斗","不能安抚这些元素吗"}},{q="是谁要求消灭这些元素的？",a="该任务由一位关心控制局势的人发起，他本希望和平地安抚这些元素之灵。由于缺乏安抚它们所需的奥术或精神知识，他只能求助于冒险者来消除威胁。",al={"谁发布了 rime's wrath","谁想要消灭这些元素","任务发布者是谁"}},{q="这些元素可以和平解决吗？",a="任务发布者指出，安抚它们超出了他的认知范围。元素之灵有时可以被平衡或安抚，但若没有相关的专业知识，它们的攻击性使得除了战斗之外别无他法。",al={"冰元素可以被安抚吗","安抚冰元素","为什么不平息元素"}},{q="小型冰元素是什么样的生物？",a="小型冰元素是不稳定的冰霜元素显现。尽管被归类为小型元素之灵，但如果任其自由游荡，它们周围的严寒和攻击性仍会对旅行者和当地居民造成危险。",al={"什么是小型冰元素","冰元素的危险性","小型冰元素有多强"}},{q="处理这些元素的结果是什么？",a="在击败十个小型冰元素后，眼前的危险便被平息了。任务发布者感叹暴力是必要的手段，因为他也意识到放任不管风险实在太大。",al={"rime's wrath 之后会发生什么","rime's wrath 结局"}}},fp="12,226,22.367.0,16.307.0,21.246.0,53.217.0,47.232.0,53.212.0,48.224.0,51.192.0"}
P.entries["quest:99161"] = {n="Rime's Wrath",s="在一场山崩过后，一个异常巨大的元素生物Avala出现了，并开始引发诡异的天气突变和二次山崩。一名观察者委托冒险者去猎杀该元素生物并获取它的核心，以确保该区域的安全。击败这个生物可以恢复山坡的稳定，并保护旅行者免受致命的寒冬之灾。",h="在一场山崩过后，一个异常巨大的元素生物Avala出现了，并开始引发诡异的天气突变和二次山崩。一名观察者委托冒险者去猎杀该元素生物并获取它的核心，以确保该区域的安全。击败这个生物可以恢复山坡的稳定，并保护旅行者免受致命的寒...",kw={"avala","avala核心","元素生物","元素核心","rime's wrath","山崩","天气","冬季"},ang={["class:Paladin"]="圣骑士肩负着保护旅行者和平民免受突发灾难的职责。任务给予者在任务完成后祈求圣光的祝福，以感谢冒险者避免了不必要的死亡。",["class:Shaman"]="萨满祭司认识到像Avala这样不受约束的元素生物所构成的危险，其动荡的存在扭曲了当地的天气并撼动着岩石。平息这些躁动的生物对于恢复元素之间的和谐至关重要。"},sec={{t="山崩的余波",b="这些骚乱始于一次突如其来的山崩，山崩动摇了山口，为元素生物的活动打开了通道。在浮现出的众多生物中，有一个特殊的元素生物脱颖而出，以其巨大的体型和原始的力量凌驾于同类之上。警觉的任务给予者为它起了个非正式的绰号“Avala”。这个强大的实体不仅仅是一个令人望而生畏的存在，它还直接加剧了局部的天气动荡，并使周围的悬崖变得不稳定。它的存在对任何试图通过该地区的人来说都是一种直接的威胁，因为不稳定的地面和突如其来的严寒使正常的通行变得致命。"},{t="平息Avala",b="由于认识到Avala对地形的影响所带来的日益严重的危险，有人发出了号召，要求在更多的塌方造成伤亡之前消灭这头野兽。击杀该生物需要同时面对它的元素狂暴和它所制造的恶劣环境，最终还要取回它的核心作为其死亡的明确证据。随着Avala被击败，其生命之心被收回，剧烈的天气变化随之平息，这使周围的山口恢复了一定的安全，并保护未来的旅行者免受不必要的灾难。"}},faq={{q="什么是Rime's Wrath？",a="Rime's Wrath是一个任务，要求冒险者消灭Avala。这是一个在突然的山崩后显现的、巨大且危险的元素生物。通过猎杀该元素生物并回收其核心，冒险者终结了威胁着山口旅行者的反常天气干扰和反复发生的山崩。",al={"rimes wrath","什么是rimes wrath","rime's wrath任务"}},{q="Avala是谁，或者是什么？",a="Avala是一个在重大山崩后浮现的特别巨大的元素生物。Avala比它的元素同类体型更大，它主动在区域内引发突然的天气变化、严寒以及危险的二次地震。“Avala”这个名字是监视山口的观察者给它起的。",al={"什么是avala","avala是谁","avala元素生物"}},{q="为什么要摧毁Avala？",a="Avala持续存在导致不可预知的天气紊乱和小型山崩，使周围的山坡变得不稳定。如果不加制止，这个元素生物对冬季气候和地形的超自然影响将有引发进一步塌方的风险，并导致穿越山口的旅行者发生可避免的死亡。",al={"为什么要击杀avala","击杀avala的原因","为什么要摧毁avala"}},{q="完成Rime's Wrath需要什么证据？",a="冒险者必须在战斗中击败该生物后取回Avala的核心。将此元素核心交给任务给予者，证实该威胁已被彻底消除，区域气候可以恢复正常。",al={"avala的证明","掉落什么物品","avala核心证明"}},{q="Avala最初是如何出现的？",a="Avala是在一场扰乱该地区的最初山崩后出现的。它在塌方后的余波中与其他元素生物一同出现，由于其体型和元素力量，很快确立了自己是其中最突出、最危险的生物。",al={"avala从何而来","avala起源","avala如何生成"}},{q="谁提供了Rime's Wrath这个任务？",a="该任务由驻扎在危险山口附近的一名当地观察者提供，他密切监视着山崩和元素生物的出现。在任务完成后，这位观察者会祈求圣光的祝福，他试图通过招募有能力的勇士来消灭Avala，以防止不必要的死亡。",al={"谁给予rimes wrath任务","rimes wrath任务给予者"}},{q="Avala被击败后会发生什么？",a="一旦Avala被杀且其核心被带回，由该生物的存在所引发的剧烈天气变化和局部震动便会减弱。任务给予者会赐予圣光的祝福和奖励，并指出该地区对未来的旅行者来说已经变得更加安全。",al={"avala死后发生什么","rimes wrath完成","rimes wrath之后"}}},fp="12,362,25.601.0,14.552.0,21.328.0,21.309.0,36.333.0,46.235.0,27.265.0,34.315.0,37.275.0"}
P.entries["quest:99162"] = {n="Treacherous Cold",s="Treacherous Cold 是在丹莫罗险峻的高峰上，于毁灭性的冰雪崩塌后进行的一项救援工作。冒险者受命寻回阵亡铁炉堡登山者的铭文步枪，以确认他们的身份，并给予其家人慰藉。",h="Treacherous Cold 是在丹莫罗险峻的高峰上，于毁灭性的冰雪崩塌后进行的一项救援工作。冒险者受命寻回阵亡铁炉堡登山者的铭文步枪，以确认他们的身份，并给予其家人慰藉。",kw={"雪崩","丹莫罗","铁炉堡","登山者","步枪","山体滑坡","treacherous cold"},ang={["class:Hunter"]="登山者在冰冻荒野中依靠他们值得信赖的步枪，将名字刻在木质枪托上，这样他们的身份和功绩便永远不会被遗忘。",["faction:Alliance"]="回收阵亡登山者的装备，能确保铁炉堡给予那些为了守护高地而牺牲挚亲的家庭一份慰藉。",["race:Dwarf"]="丹莫罗的山峰是矮人的家园，但即便是老练的登山者也可能在高地山道上丧命于突发的雪崩和充满敌意的元素手中。"},sec={{t="群峰之险",b="丹莫罗崎岖的雪崖对旅行者和士兵来说始终是一种危险。即使是经验丰富的铁炉堡登山者也可能在突如其来的雪崩和坠落的冰层中措手不及，而新兵更是在毫无预警的寒冬袭击中丧命。"},{t="严酷的搜救",b="当山体滑坡掩埋了巡逻队，搜寻险峻地形便成了一场严酷的与时间赛跑。该地区加剧的元素活动使得彻底的救援行动困难重重，迫使侦察兵招募勇敢的漫步者，在雪堆中寻找失踪的登山者，并在大雪将其永远掩盖之前取回他们的铭文步枪。"},{t="刻字的枪托",b="每一位铁炉堡登山者都会将自己的名字刻在步枪的枪托上，作为在最严酷环境下的永久身份标识。通过从雪堆中找回这些武器，搜寻者能确保阵亡者得到确认，且他们受人尊崇的事迹能被铁炉堡的家人知晓。"}},faq={{q="什么是 Treacherous Cold？",a="Treacherous Cold 是一项任务，旨在搜寻被突如其来的雪崩困住的登山者，并回收他们的制式步枪。",al={"什么是 treacherous cold","treacherous cold 任务"}},{q="为什么要收集登山者的步枪？",a="登山者会将名字直接刻在步枪的枪托上。在极寒的雪堆中，遗体可能已被掩埋或无法找回，取回他们的武器能让铁炉堡确认阵亡者身份并通知其家人。",al={"为什么收集步枪","登山者步枪","为什么要拿走他们的枪"}},{q="谁在雪中遇难了？",a="在丹莫罗巡逻的新手登山者特别容易受到突发雪崩、坠冰和高海拔地区极端天气的影响。",al={"受害者是谁","谁在丹莫罗失踪了"}},{q="为什么之前没有进行搜寻？",a="虽然任务发布者通常会在雪崩后进行救援和搜寻工作，但丹莫罗最近的元素动荡使得深入山道执行任务变得过于危险，无法独自应对。",al={"为什么任务发布者不能去寻找","为什么需要冒险者"}},{q="步枪被回收后会怎样？",a="回收的步枪会被收集并送回铁炉堡，当地官方会确保这些个人武器归还给阵亡登山者的家属。",al={"步枪会被送去哪里","回收的步枪有什么用途"}},{q="丹莫罗的高海拔山道为何如此危险？",a="丹莫罗的高海拔地区充斥着严寒、致盲的雪崩和不稳定的悬崖。再加上动荡的元素活动，即使是训练有素的矮人巡逻队也可能迅速倒在恶劣的环境下。",al={"丹莫罗有多危险","丹莫罗的危险因素"}}},fp="16,294,19.299.0,13.352.0,16.314.0,25.162.0,43.245.0,30.153.0,45.210.0,42.172.0,54.203.0"}
P.entries["quest:99191"] = {n="A Donation of Wool",s="高阶会正在接受毛料捐赠。捐赠六十块即可获得高阶会的完全认可。",h="高阶会正在接受毛料捐赠。捐赠六十块即可获得高阶会的完全认可。",kw={"捐赠","高阶会","认可","六十块","毛料"},sec={{t="一份值得珍视的礼物",b="高阶会正在接受毛料捐赠，六十块足以满足当前所需。此项委托的捐赠接收者现在可以收下你的毛料；这笔捐赠将使你获得高阶会的完全认可。"}},faq={{q="高阶会需要什么？",a="高阶会正在接受毛料捐赠，六十块足以满足当前所需。",al={"高阶会毛料","捐赠什么","毛料捐赠"}},{q="我该捐赠多少毛料？",a="捐赠六十块毛料即可获得高阶会的完全认可。",al={"需要多少毛料","六十块毛料","毛料数量"}},{q="谁可以接收捐赠？",a="此项委托的捐赠接收者可以收下你的六十块毛料。",al={"谁接收毛料","捐赠接收者","捐赠毛料"}},{q="捐赠能给我带来什么？",a="捐赠六十块毛料即可获得高阶会的完全认可。",al={"毛料认可","高阶会声望","捐赠收益"}}},fp="18,113,13.168.0,30.72.0,34.77.0,26.53.0,27.81.0"}
P.entries["quest:99196"] = {n="A Donation of Wool",s="塑风者正在收取毛料捐赠。捐出六十块毛料，即可获得他们对你慷慨之举的充分认可。",h="塑风者正在收取毛料捐赠。捐出六十块毛料，即可获得他们对你慷慨之举的充分认可。",kw={"捐赠","认可","六十块","塑风者","毛料"},sec={{t="毛料赠礼",b="塑风者接受毛料捐赠。准备好捐赠时，他们的代表可以收下你带来的六十块毛料。"}},faq={{q="塑风者想要什么？",a="塑风者正在收取毛料捐赠。",al={"塑风者捐赠","他们收什么毛料"}},{q="我该捐多少毛料？",a="捐赠六十块毛料，即可获得塑风者的充分认可。",al={"需要多少毛料","六十块毛料"}},{q="捐赠毛料能得到什么？",a="捐赠六十块毛料，可获得塑风者对你慷慨之举的充分认可。",al={"毛料捐赠结果","塑风者认可"}},{q="他们的代表现在能收下毛料吗？",a="如果你随身带着六十块毛料并准备捐赠，他们的代表就可以收下。",al={"现在捐毛料","捐赠布料"}}},fp="18,99,14.115.0,29.51.0,34.69.0,36.88.0,43.99.0"}
P.entries["quest:992"] = {n="加基森水业公司",s="加基森的高级勘探员菲兹杜瑟正在为加基森水业公司招聘一名临时初级勘探员。由于游牧民占领了公司的水井，他交给你一个探水装置，让你去流沙岗哨附近的水潭取样。",h="加基森的高级勘探员菲兹杜瑟正在为加基森水业公司招聘一名临时初级勘探员。由于游牧民占领了公司的水井，他交给你一个探水装置，让你去流沙岗哨附近的水潭取样。",kw={"探水装置","菲兹杜瑟","加基森","加基森水业公司","流沙岗哨","塔纳利斯"},sec={{t="急需水源的公司",b="游牧民占领了加基森水业公司的所有水井，因此公司必须寻找更多免费的水源。高级勘探员菲兹杜瑟相信沙漠中还有水源，只是需要足够聪明的人先行勘探，他希望能有一名临时初级勘探员来提供帮助。"},{t="在流沙岗哨取样",b="你领到一个未使用的探水装置，并被派往流沙岗哨附近的水潭。水潭位于加基森的正西方，祖尔法拉克南面，在那里可以看见附近的巨魔。你的目标是用探水装置取一瓶水样，并将装有水样的装置带回给菲兹杜瑟。"},{t="回到菲兹杜瑟身边",b="当你回来时，菲兹杜瑟听说你遭到了某种恶毒的爬虫生物伏击，并承认确实不断有报告称，奇怪的虫形生物正在吸干沙漠里的水。菲兹杜瑟起初以为这只是胡言乱语，多半是那些游牧民惹的麻烦，但现在真相大白了。"}},faq={{q="是谁在加基森提供勘探工作？",a="高级勘探员菲兹杜瑟，他正在为加基森水业公司招聘一名临时初级勘探员。",al={"谁提供加基森水业调查任务","加基森水业调查任务发布者","菲兹杜瑟是谁"}},{q="为什么加基森水业公司要寻找新的水源？",a="游牧民占领了公司所有的水井，因此它需要寻找其他免费的水源。",al={"为什么要进行水质调查","为什么加基森需要水"}},{q="需要取样的水潭在哪里？",a="在流沙岗哨附近的水潭，它位于加基森正西方，祖尔法拉克南面，在那里可以看见附近的巨魔。",al={"水潭在哪里","流沙岗哨水潭位置","在哪里使用探水装置"}},{q="提供了什么工具来进行采集？",a="一个探水装置，你可以在水潭处用它来采集水样。",al={"探水装置","使用什么物品"}},{q="接下来要做什么？",a="这开启了后续任务链，接下来是调查腐化之巢。",al={"接下来是什么任务","加基森水业调查任务链"}}},fp="22,248,26.288.0,28.285.0,22.304.1,40.110.0,59.88.0,40.126.0,47.73.0,23.72.0"}
P.entries["quest:99260"] = {n="Fillion's Mission",s="Fillion's Mission 讲述了一次勘察行动后的余波，该行动旨在绘制眺望台立石的元素流图。所收集的数据原本旨在为往返于天空之墙与艾泽拉斯之间的破空船规划安全的航线，但侦察员的伤残却使整个计划陷入了危机。",h="Fillion's Mission 讲述了一次勘察行动后的余波，该行动旨在绘制眺望台立石的元素流图。所收集的数据原本旨在为往返于天空之墙与艾泽拉斯之间的破空船规划安全的航线，但侦察员的伤残却使整个计划陷入了危机。",kw={"elaadrin evengale","元素位面","fillion","瞰台立石","破空船","天空之墙","瓦拉纳尔","塑风者"},ang={["class:Mage"]="遵循至高法师计划的奥术师们将会理解，驾驶破空船穿过位面乱流所需的精细魔法计算是何等重要。",["race:Skyborne"]="这个任务直接触及了你们的族人在派系摩擦中努力建立往返于天空之墙与艾泽拉斯之间安全航线的挣扎。"},sec={{t="危险的任务",b="Fillion 被派遣前往眺望台立石收集关于元素能量流的关键读数。这些读数构成了操纵破空船往返于天空之墙与艾泽拉斯之间所需的计算基础。在经历了一场迫切需要救援的磨难后，Fillion 发现自己无法完成任务，而那些重要数据也被认为已经丢失。由于受伤无法继续任务，他指引救命恩人去向至高法师报告。"},{t="瓦拉纳尔的位面纷争",b="在瓦拉纳尔定居点，至高法师 Elaadrin Evengale 收到了 Fillion 生还的报告，感到一丝宽慰，但同时也为丢失的研究感到惋惜。没有可靠的导航数据，开辟穿梭于元素位面的安全通道面临着极大的困难。更糟糕的是，有报告称敌对的塑风者已经获得了他们自己的位面通行手段，却拒绝分享，将派系私利置于集体福祉之上。"}},faq={{q="Fillion 是谁？",a="Fillion 是至高法师派遣的一名特使或侦察员，负责从眺望台立石收集关于元素能量流的重要读数。在被一名冒险者救出后，他因身体过于虚弱而无法完成最初的任务。",al={"fillion 是谁","fillion 背景故事","fillion 魔兽世界"}},{q="至高法师 Elaadrin Evengale 是谁？",a="Elaadrin Evengale 是驻扎在瓦拉纳尔的至高法师。他指导着安全穿越元素位面的工作，并协调位面数据的回收，以保障往返于天空之墙与艾泽拉斯之间的旅行。",al={"至高法师是谁","elaadrin evengale","elaadrin 是谁"}},{q="为什么 Fillion 的数据如此重要？",a="这些数据记录了在眺望台立石收集到的元素能量流。这对于通过数学计算来安全引导破空船穿越元素位面到达艾泽拉斯至关重要，否则船只将会被摧毁。",al={"为什么数据很重要","fillion 丢失了什么数据","元素数据 天空之墙"}},{q="塑风者是谁？",a="塑风者是一个据称已经掌握了自己位面旅行方法的派系。根据 Evengale 至高法师的说法，他们由于教条式的傲慢而极力保守这一秘密，而不是为了族人的共同利益而分享它。",al={"塑风者是谁","塑风者传说","塑风者竞争对手"}},{q="什么是破空船？",a="破空船是专门设计用于在元素位面中飞行的船只。引导它们需要精确的元素能量流读数；否则，尝试在天空之墙与艾泽拉斯之间驾驶它们将会导致灾难性的后果。",al={"什么是破空船","破空船"}},{q="奥拉凯斯是谁？",a="奥拉凯斯是 Evengale 至高法师所提及的一个敌对或受轻视的派系。他直接将塑风者那种自私和教条的行为与他们相提并论。",al={"奥拉凯斯是谁","奥拉凯斯","奥拉凯斯传说"}}},fp="17,156,21.350.0,25.364.1,15.191.0,42.176.0,36.167.0,24.212.0,20.159.0,21.140.0"}
P.entries["quest:993"] = {n="丢失的主人",s="收集到精良的月夜猛虎皮后，你带着完成的附魔月夜猛虎斗篷前往黑海岸的荒野，寻找失踪的暗夜精灵沃科尔。在忠诚的白熊格里姆爪的指引下，你必须追踪这名受伤的哨兵，以免他在被敌对的熊怪杀害前遭遇不测。",h="收集到精良的月夜猛虎皮后，你带着完成的附魔月夜猛虎斗篷前往黑海岸的荒野，寻找失踪的暗夜精灵沃科尔。在忠诚的白熊格里姆爪的指引下，你必须追踪这名受伤的哨兵，以免他在被敌对的熊怪杀害前遭遇不测。",kw={"奥伯丁","黑海岸","熊怪","格里姆爪","月夜猛虎斗篷","夜刃豹","特伦希斯","沃科尔"},ang={["class:Hunter"]="看着格里姆爪在道路上穿行以寻找救援沃科尔的行为，突显了卡利姆多训练有素的野兽所具备的卓越智慧与忠诚。",["faction:Alliance"]="奥伯丁依靠像沃科尔这样的哨兵来监视黑海岸熊怪部落日益严重的腐蚀，这使得营救他成为前哨站的一项重要优先事项。",["race:NightElf"]="格里姆爪为寻找主人沃科尔的援助而表现出的坚定忠诚，展现了暗夜精灵哨兵与其动物伙伴之间的羁绊。"},sec={{t="林中的灯塔",b="特伦希斯在奥伯丁缝制好附魔月夜猛虎斗篷后，寻找失踪哨兵沃科尔的工作便正式开始了。他的熊伙伴格里姆爪回到了定居点南面的道路上，时刻守候着特伦希斯派来的盟友。只要向这头忠诚的野兽打个招呼，旅行者就能直接离开大路，前往沃科尔藏身的洞穴。"},{t="隐匿于暗影",b="沃科尔在被当地受腐蚀的熊怪打成重伤后，躲进了一个洞穴中。他被困在此处且伤势严重，只能完全依靠潜行和格里姆爪的机智来避免被彻底包围。附魔斗篷为他提供了必要的隐蔽和希望，让他得以计划撤离，尽管他的伤势使他在返回奥伯丁的旅途中处于岌岌可危的状态。"}},faq={{q="沃科尔是谁？",a="沃科尔是一名常驻黑海岸的暗夜精灵哨兵，在靠近敌对熊怪营地冒险时失踪。他在冲突中受了重伤，设法爬进了附近的一个洞穴，而他的伙伴熊格里姆爪则外出寻找援助。",al={"沃科尔背景故事","失踪的主人是谁"}},{q="如何找到沃科尔的藏身处？",a="格里姆爪守在奥伯丁南面的道路旁。向这头野兽挥手示意，让他知道你是特伦希斯派来的帮手，格里姆爪便会径直跑向沃科尔疗伤的隐秘洞穴。",al={"沃科尔在哪里","寻找沃科尔的洞穴","如何跟随格里姆爪"}},{q="附魔月夜猛虎斗篷的用途是什么？",a="特伦希斯用精良的月夜猛虎皮制作斗篷并附上魔法，以提供短暂但强大的潜行效果。它的魔法能让你在搜寻沃科尔的过程中不被黑海岸的生物发现，之后斗篷会交给沃科尔。",al={"月夜猛虎斗篷","斗篷魔法"}},{q="是谁袭击了沃科尔？",a="沃科尔在黑海岸游荡时遭到了受腐蚀的熊怪部落的伏击并负伤。尽管他设法躲过了直接的杀戮，但伤势使他无法在无人协助的情况下独自回到奥伯丁。",al={"谁伤害了沃科尔","为什么沃科尔在流血"}},{q="找到沃科尔后会发生什么？",a="沃科尔收到附魔斗篷后会喘口气，并请求你协助他逃离荒野。你可以选择引导他通过潜行悄悄离开，或是凭借武力杀出一条通往熊怪群的道路。",al={"沃科尔后续任务","失踪的主人任务后续"}}},fp="13,163,21.328.0,18.286.1,14.220.0,37.165.0,55.205.0,20.164.0,34.198.1"}
P.entries["quest:994"] = {n="杀出重围",s="“以武脱困”是黑海岸的一项联盟任务，在任务中，冒险者需要通过正面战斗帮助沃科尔突破周围的威胁。在杀出重围到达大路并与他忠实的伙伴格里姆爪重聚后，玩家将返回奥伯丁向特伦希斯报告沃科尔已安全逃脱的消息。",h="“以武脱困”是黑海岸的一项联盟任务，在任务中，冒险者需要通过正面战斗帮助沃科尔突破周围的威胁。在杀出重围到达大路并与他忠实的伙伴格里姆爪重聚后，玩家将返回奥伯丁向特伦希斯报告沃科尔已安全逃脱的消息。",kw={"奥伯丁","黑海岸","护送","格里姆爪","塞拉伊","特伦希斯","沃科尔"},ang={["faction:Alliance"]="协助当地斥候加深了年轻的联盟与暗夜精灵之间的纽带，证明了该阵营在保卫卡利姆多北部边境方面的价值。",["race:NightElf"]="营救像沃科尔这样的斥候对于卡多雷在黑海岸那岌岌可危的控制权至关重要，那里野兽、腐蚀和外来入侵者正威胁着他们祖传的林地。"},sec={{t="直接的脱困之路",b="当被困在黑海岸危险的荒野中时，潜行并非总是首选。面对危险，暗夜精灵沃科尔采取了一种简单粗暴的策略：直接杀出一条血路，穿过周围的敌对生物以求生。沃科尔没有试图悄无声息地溜走，而是依靠武力开辟了一条通往大路的直行通道。"},{t="路上的重逢",b="安全抵达大道让沃科尔得以与他的忠诚熊伙伴格里姆爪重聚，格里姆爪一直守在路边等待着他。逃出生天后，沃科尔在准备接下来的旅程时，敦促冒险者直接向奥伯丁的特伦希斯汇报。传达沃科尔安全的消息不仅让暗夜精灵领导层感到安心，也立即引起了哨兵塞拉伊的注意，这指向了南方灰谷正在酝酿的更深层的麻烦。"}},faq={{q="沃科尔是谁？",a="沃科尔是黑海岸的一名暗夜精灵斥候或护林人，他与他的伙伴格里姆爪一同失踪了。在接受特伦希斯委托的冒险者找到他后，他需要帮助以摆脱敌对的野生生物和危险的地形。",al={"沃科尔身份","谁是沃科尔","沃科尔黑海岸"}},{q="格里姆爪是谁？",a="格里姆爪是沃科尔忠诚的熊伙伴。在沃科尔被困期间，格里姆爪一直独自待在路边，并作为沃科尔逃生路线上的汇合点。",al={"格里姆爪","沃科尔的熊","沃科尔的宠物"}},{q="特伦希斯为什么关心沃科尔的回归？",a="特伦希斯负责统筹奥伯丁的斥候行动和当地的防御工作。追踪失踪的盟友并评估沿海岸的威胁，对于维持暗夜精灵在局势不断动荡的黑海岸的控制权至关重要。",al={"特伦希斯沃科尔","为什么帮助沃科尔","特伦希斯任务"}},{q="完成该任务后会发生什么？",a="向奥伯丁的特伦希斯报告沃科尔已安全撤离。随后任务线将引导至“前往灰谷”。",al={"以武脱困之后","what comes next","沃科尔的下一个任务"}},{q="有其他方式来完成沃科尔的护送任务吗？",a="是的。在营救沃科尔时，冒险者可以选择不同的方式：通过“以武脱困”正面杀出重围，或者利用潜行引导他悄悄避开危险。",al={"以武脱困的其他方法","通过潜行脱困","沃科尔的选择"}},{q="该任务在更宏大的剧情中起什么作用？",a="确保沃科尔的生还起到了连接黑海岸局部冲突与暗夜精灵领地更大规模区域防御的桥梁作用，并直接开启了灰谷的任务。",al={"沃科尔剧情","黑海岸到灰谷任务线"}}},fp="20,160,16.238.0,19.323.1,14.228.0,16.146.0,46.166.0,41.98.1,52.91.0,52.124.1"}
P.entries["quest:99411"] = {n="Kyle's Gone Missing!",s="Kyle's Gone Missing!是血蹄村的一个当地任务，阿哈布·麦蹄请求过往的冒险者寻找他那走失的爱犬——“狂暴的”凯尔。喂给这只饥饿的小狗一块嫩陆行鸟肉可以平息他的脾气，并确保他能平安回家。",h="Kyle's Gone Missing!是血蹄村的一个当地任务，阿哈布·麦蹄请求过往的冒险者寻找他那走失的爱犬——“狂暴的”凯尔。喂给这只饥饿的小狗一块嫩陆行鸟肉可以平息他的脾气，并确保他能平安回家。",kw={"阿哈布·麦蹄","血蹄村","凯尔","“狂暴的”凯尔","kyle's gone missing!","莫高雷","平原陆行鸟","嫩陆行鸟肉"},ang={["faction:Horde"]="协助血蹄村的当地村民处理日常事务，可以加强与舒哈鲁的联系，帮助他们在定居和保卫家园时获得支持。",["race:Tauren"]="阿哈布·麦蹄是血蹄村的居民，这桩私事成了在莫高雷牧场中一种常见的社区互助行为。"},sec={{t="丢失的猎犬",b="在血蹄村，长者阿哈布·麦蹄正在为他那走失的宠物——“狂暴的”凯尔而担忧。虽然这个头衔对局外人来说可能听起来很吓人，但凯尔其实是阿哈布珍视的小狗，他溜到了莫高雷的草原上。阿哈布请求路过此地的旅行者追踪他那不听话的伙伴，并提供一顿丰盛的餐食来安抚他狂野的性情。"},{t="一个简单的办法",b="平息凯尔的怒火需要一块嫩陆行鸟肉，这种肉取自游荡在莫高雷的敏捷平原陆行鸟。拿出这顿美食可以满足饥饿的小狗，抚平他狂暴的情绪，并引导他安全地回到血蹄村和感激他的主人身边。"}},faq={{q="阿哈布·麦蹄是谁？",a="阿哈布·麦蹄是居住在莫高雷血蹄村的一位牛头人长者。他非常疼爱自己的宝贝狗凯尔，每当凯尔离家太远时，阿哈布就会求助于过往的冒险者，请他们帮忙找到并喂食这只走失的犬类。",al={"阿哈布·麦蹄","阿哈布 莫高雷","任务发布者 凯尔"}},{q="“狂暴的”凯尔是谁？",a="凯尔是阿哈布·麦蹄心爱的犬类宠物，被称为“狂暴的”凯尔。尽管他的头衔听起来很凶猛，但他其实是阿哈布珍视的伙伴，只需喂他嫩陆行鸟肉就能平息他的怒火并将他引诱回来。",al={"凯尔是谁","凯尔 狗","“狂暴的”凯尔"}},{q="这个任务发生在哪里？",a="血蹄村是一个位于莫高雷中心地带的牛头人定居点，在雷霆崖的南面。它是当地部落、商人和牧民的重要聚集地。",al={"血蹄村在哪里","血蹄村位置"}},{q="为什么凯尔需要嫩陆行鸟肉？",a="凯尔对游荡在莫高雷的平原陆行鸟身上切下的鲜肉情有独钟。提供嫩陆行鸟肉可以平息这只饥饿猎犬的怒火，并说服他安全地回到阿哈布身边。",al={"为什么需要嫩陆行鸟肉","陆行鸟肉 凯尔","如何安抚凯尔"}},{q="为什么凯尔被称为“狂暴的”？",a="凯尔在当地被称为“狂暴的”，当他走失或饥饿时就会在平原上徘徊。一旦有耐心的旅行者为他提供食物，他的狂暴状态就会消退。",al={"为什么凯尔会狂暴","凯尔生气"}},{q="在哪里可以找到凯尔？",a="凯尔在莫高雷血蹄村周围的开阔平原上徘徊。旅行者通常会通过搜索附近的草原找到他，直到能为他提供一顿食物。",al={"凯尔位置","凯尔在哪里"}}},fp="20,253,15.366.0,15.260.0,22.227.0,25.209.0,32.181.0,39.190.0,32.149.0,24.168.0"}
P.entries["quest:995"] = {n="偷偷溜走",s="“通过潜行逃脱”是一个发生在黑海岸的联盟护送任务。在熊怪巢穴深处找到被困的暗夜精灵斥候沃科尔后，玩家将协助他避开敌对野兽，安全抵达目的地，随后向奥伯丁的特伦希斯报告。",h="“通过潜行逃脱”是一个发生在黑海岸的联盟护送任务。在熊怪巢穴深处找到被困的暗夜精灵斥候沃科尔后，玩家将协助他避开敌对野兽，安全抵达目的地，随后向奥伯丁的特伦希斯报告。",kw={"灰谷","奥伯丁","黑海岸","护送","熊怪","潜行","特伦希斯","沃科尔"},ang={["class:Rogue"]="潜行者们很欣赏沃科尔的战术直觉，即绕过固守的敌人，而不是在鲁莽的正面交锋中浪费时间和鲜血。",["faction:Alliance"]="成功救出沃科尔，向奥伯丁的暗夜精灵领导层证明了非卡多雷的联盟盟友可以被委以荒野行动的重任。",["race:NightElf"]="对于暗夜精灵来说，帮助沃科尔巩固了重要的斥候网络，这些斥候守护着卡利姆多遭受侵扰的森林，而腐蚀正从那些被腐化的兽穴和巢穴中不断向外蔓延。"},sec={{t="被困的斥候",b="沃科尔被派遣深入黑海岸，调查该地区日益严重的威胁，却最终被困在了一处熊怪洞穴中。他因寡不敌众且与大路隔绝，不得不依靠一名路过的盟友来协调撤离，赶在敌对的熊怪发现他潜逃之前逃离。"},{t="谨慎的撤离",b="沃科尔没有选择自杀式的正面突围，而是采取了谨慎的行动。他依靠阴影和审慎的走位，悄然滑过洞穴中那些被腐蚀的生物。因为深知速度与安静至关重要，沃科尔在离开洞穴入口后便与救援者分道扬镳，独自先行奔跑，并指示救命恩人在奥伯丁定居点与其汇合。"},{t="向奥伯丁报告",b="在回到奥伯丁后，玩家向特伦希斯传达了救援的消息。特伦希斯是一位负责协调保护这片多灾多难海岸线的暗夜精灵领袖。特伦希斯认为沃科尔的平安归来证明了只要纪律严明、通力合作，就能够抵御黑海岸及其周边荒野中不断蔓延的黑暗。"}},faq={{q="沃科尔是谁？",a="沃科尔是一名暗夜精灵斥候，他为了执行上级的任务深入了黑海岸的荒野。他在一个敌对的熊怪巢穴中被困，直到被一名联盟冒险者救出。",al={"沃科尔背景故事","沃科尔是谁","沃科尔黑海岸"}},{q="为什么沃科尔在离开洞穴后独自跑掉？",a="沃科尔指出，一旦离开洞穴狭窄的通道，他独自一人行动会更快。他指示冒险者在奥伯丁重聚，而不是在开阔的道路上一同前行。",al={"为什么沃科尔要离开","沃科尔分开行动"}},{q="特伦希斯是谁？",a="特伦希斯是一位驻扎在奥伯丁的知名暗夜精灵协调员。他负责监督当地的侦查工作，并组织应对威胁黑海岸的腐蚀力量和敌对生物。",al={"特伦希斯奥伯丁","特伦希斯是谁"}},{q="这次救援发生在什么地方？",a="救援行动始于一处熊怪洞穴，该洞穴位于黑海岸荒凉且充满争端的森林深处，远离安全的奥伯丁。",al={"沃科尔洞穴位置","沃科尔洞穴在哪里"}},{q="完成这个任务后会发生什么？",a="在确认沃科尔安全并向特伦希斯汇报后，玩家会被指引前往下一个阶段，向南前往灰谷，执行任务“前往灰谷的跋涉”。",al={"通过潜行逃脱后是什么任务","沃科尔后的下一个任务"}},{q="这次救援中，除了潜行还有其他选择吗？",a="沃科尔提供了另一种方案：冒险者可以选择不通过潜行溜走，而是通过战斗，以纯粹的武力杀出重围，这是另一种以战斗为核心的护送选择。",al={"武力逃脱","沃科尔的其他任务","潜行与武力"}}},fp="22,149,17.224.0,16.199.0,22.259.0,14.170.0,52.167.0,17.171.0,34.99.0,41.143.0,50.133.0"}
P.entries["quest:997"] = {n="德纳兰的泥土",s="“德纳兰的泥土”是一项从多兰纳尔定居点向南前往宁静的奥拉密斯湖的差事。塞拉尔·刃叶请求旅行者将一批迟到的稀有富含养分的泥土送交给她的植物学同事德纳兰，他正在研究这棵新的世界之树的枝干和植物。",h="“德纳兰的泥土”是一项从多兰纳尔定居点向南前往宁静的奥拉密斯湖的差事。塞拉尔·刃叶请求旅行者将一批迟到的稀有富含养分的泥土送交给她的植物学同事德纳兰，他正在研究这棵新的世界之树的枝干和植物。",kw={"达纳苏斯","德纳兰","多兰纳尔","奥拉密斯湖","稀土","塞拉尔·刃叶","泰达希尔","树人"},ang={["class:Druid"]="德鲁伊与德纳兰的研究工作有着天然的亲和力，因为追踪泰达希尔植物群的生长和平衡对于守护这根新枝干上的自然至关重要。",["profession:Herbalism"]="草药师会很欣赏德纳兰的湖畔休憩处，因为他的实验中心在于了解这棵新生的世界之树所独有的、脆弱且正在萌芽的植物生命。",["race:NightElf"]="对于从幽影谷出来的暗夜精灵来说，协助塞拉尔和德纳兰是让他们初步了解维持泰达希尔所需的更广泛的守护工作。"},sec={{t="多兰纳尔的信使",b="当旅行者途经多兰纳尔向南前往奥拉密斯湖时，塞拉尔·刃叶会拦住他们，请他们帮一个过期的忙。她的同行研究员德纳兰从达纳苏斯订购了一批特殊的稀土，用于支持他正在进行的植物学研究。这批货物在运输途中延误了，最近才抵达多兰纳尔。塞拉尔不想让这些肥沃的泥土变质或闲置，因此她寻找一位乐于助人的信使，愿意沿着森林小径把东西送到德纳兰的湖边营地。"},{t="培育泰达希尔",b="德纳兰在奥拉密斯湖东岸设有一个孤立的工作站，他在那里观察泰达希尔的树苗生态系统是如何扎根的。泰达希尔还很年轻，在海加尔山之战后迅速生长，其植物群的表现也出人意料。德纳兰利用独特的土壤混合物和样本来测试岛上树人及原生植物的生命力和行为，因此这批新鲜的稀土对于他的实验至关重要。"}},faq={{q="谁是德纳兰？",a="德纳兰是一位暗夜精灵研究员和草药师，他在奥拉密斯湖东岸建立了营地。他致力于研究、培育泰达希尔独特的植物群，并对其进行实验。",al={"德纳兰背景故事","德纳兰是谁","德纳兰npc"}},{q="塞拉尔·刃叶在哪里？",a="塞拉尔·刃叶居住在多兰纳尔，这是泰达希尔中部主要的暗夜精灵前哨站，她在那里协调研究物资并协助穿梭于枝干间的旅行者。",al={"塞拉尔·刃叶位置","塞拉尔在哪里"}},{q="稀土是用来做什么的？",a="这批货物包含了从首都达纳苏斯寄来的经过特殊富养的泥土。德纳兰依靠它来培育实验性植被，并测试像树人这样的泰达希尔原生树苗如何应对多样的生长条件。",al={"德纳兰为什么需要泥土","稀土用途"}},{q="奥拉密斯湖在哪里？",a="奥拉密斯湖位于多兰纳尔以南，是一片坐落在泰达希尔南侧根部之间宁静的水域。",al={"奥拉密斯湖位置","如何前往奥拉密斯湖"}},{q="为什么货物会迟到？",a="这批包裹必须从达纳苏斯运出，在沿着泰达希尔蜿蜒的道路运输过程中遇到了未指明的延误，最后才到达多兰纳尔的配送中心。",al={"为什么泥土会迟到","延误的包裹"}},{q="运送这些泥土会有什么后续？",a="收到这些稀有泥土后，德纳兰会招募信使帮助他在湖岸收集树人幼芽和种子，从而开启一系列更深入的植物学实地研究。",al={"德纳兰泥土后续任务","what comes next"}}},fp="15,159,22.321.0,22.382.0,15.171.0,33.156.0,32.199.0,23.71.0,26.120.0,40.159.1"}
P.entries["quest:cutting-teeth"] = {n="小试身手",s="“小试身手”是新兵抵达杜隆塔尔的试炼谷后所面临的最初考验。监督者高内克会指派新兵去削减在附近仙人掌农场出没的花斑野猪的数量，以测试他们的基本战斗准备情况。在这一简单的成人礼中幸存下来，证明了立志成为战士或施法者的新兵拥有效忠部落所必需的骨气。",h="“小试身手”是新兵抵达杜隆塔尔的试炼谷后所面临的最初考验。监督者高内克会指派新兵去削减在附近仙人掌农场出没的花斑野猪的数量，以测试他们的基本战斗准备情况。在这一简单的成人礼中幸存下来，证明了立志成为战士或施法者的新兵拥有...",kw={"贫瘠之地","野猪","小试身手","杜隆塔尔","高内克","部落","花斑野猪","新兵","试炼谷"},ang={["faction:Horde"]="每一位踏入杜隆塔尔的年轻勇士都必须从最底层做起，证明部落的未来建立在鲜血与汗水之上，而非不劳而获的声望。",["race:Orc"]="兽人文化将实际的生存和尚武荣誉置于一切之上；即便是卑微的野猪清理工作，也是迈向成年、服务萨尔新国家的庄严第一步。",["race:Troll"]="随着暗矛部族与他们的兽人盟友一同重建家园，年轻的巨魔斥候和巫医也必须在杜隆塔尔残酷的捕食者中证明自己的自立能力。"},sec={{t="骨气的衡量",b="试炼谷从不纵容虚荣的幻想。虽然年轻的新兵可能梦想着在贫瘠之地追逐巨兽，或是战场上赢得荣耀，但监督者高内克却以更为脚踏实地的事物开始对他们的评估。削减山谷农场周围的花斑野猪是作为一项基础评估：它能确保新兵知道如何挥舞武器或施放法术，能够应对野兽的攻击，并具备在最初的小规模战斗中存活下来的必要常识。"},{t="驯服红尘",b="除了考验新手外，猎杀花斑野猪对这个红色沙漠定居点还有实际的民生用途。这些野蛮的猪群在营地北面和东北面的泥土农场游荡，刨食仙人掌地，威胁着在杜隆塔尔贫瘠土壤中培育出的稀缺物资。通过派遣有志之士去清除它们，营地既控制了当地的害虫，又将年轻的兽人和巨魔锻造成了保卫这个新生国家的称职守卫。"}},faq={{q="为什么高内克派遣新兵去对付野猪，而不是更大的野兽？",a="正如高内克自己承认的那样，活着的新兵对部落来说远比死了的更有用。虽然贫瘠之地有着强大的科多兽和捕食者，但派遣未经考验的新手去对付它们只会导致不必要的牺牲。野猪提供了一种可靠的基本战斗能力测试，而不会造成无谓的伤亡。",al={"为什么要打野猪","为什么要杀野猪","高内克野猪狩猎"}},{q="花斑野猪位于哪里？",a="花斑野猪在试炼谷中心空地北面和东北面的灌木丛和泥土农场中刨食。",al={"野猪位置","野猪在哪里","寻找花斑野猪"}},{q="“小试身手”这个短语有什么意义？",a="这个短语指的是在某一技艺或职业中获得最初的实践经验。对于部落的未来卫士来说，这标志着从木桩训练和空谈转向在真实的生存斗争中见血。",al={"小试身手是什么意思","小试身手的含义"}},{q="谁指派了这项试炼？",a="这项任务由高内克指派，他是一位驻扎在试炼谷中心的监督者，负责评估并指导进入杜隆塔尔训练场的新兵。",al={"谁给予小试身手任务","小试身手任务发布者","高内克试炼"}},{q="这就完成了试炼谷的训练吗？",a="不。高内克警告说，猎杀野猪仅仅是热身而已。完成这项任务后，紧接着就是更危险的挑战，包括对抗人形入侵者和收集山谷的重要资源。",al={"这是最后一个任务吗","小试身手之后是什么"}},{q="为什么野猪会在山谷中造成问题？",a="这些野猪在当地的泥土农场和灌木丛中横冲直撞，危及工人，并消耗着像仙人掌果实这样维持营地生存的少数几种坚韧作物。",al={"野猪困扰","试炼谷野猪"}}},fp="13,261,21.397.0,19.311.0,67.260.0,36.116.0,55.215.0,23.164.0,56.163.0,46.159.0"}
P.entries["quest:galgar-s-cactus-apple-surprise"] = {n="戈加尔的清凉果",s="“戈加尔的仙人掌果”是年轻的战士和新手在炎热的试炼谷中必须完成的一项简单任务。为了从杜隆塔尔酷热难耐的考验中获得解脱，兽人戈加尔会雇佣旅行者收集野生的仙人掌果，以便他制作那道著名的清凉果。这项任务能让新兵们学会如何在荒凉的土地上采集资源并生存下去。",h="“戈加尔的仙人掌果”是年轻的战士和新手在炎热的试炼谷中必须完成的一项简单任务。为了从杜隆塔尔酷热难耐的考验中获得解脱，兽人戈加尔会雇佣旅行者收集野生的仙人掌果，以便他制作那道著名的清凉果。这项任务能让新兵们学会如何在荒凉...",kw={"仙人掌","仙人掌果","杜隆塔尔","食物","采集","戈加尔","部落","试炼谷"},ang={["faction:Horde"]="每一个踏入试炼谷的新兵都会很快了解到，忍受杜隆塔尔那惩罚般的烈日是他们训练的一部分，与战斗同等重要。",["profession:Cooking"]="戈加尔的菜肴突显了将坚硬、带刺的沙漠植物转化为滋养食物和清凉点心所需的足智多谋。",["race:Orc"]="定居杜隆塔尔意味着必须适应干旱的景观，而由原生仙人掌制成的简单菜肴代表了兽人在新家园中繁衍生息的实用能力。"},sec={{t="在赤色荒野中生存",b="试炼谷那赤红的土地以无情而闻名。在严苛的战斗演练和针对当地野兽的残酷试炼之间，疲惫和脱水接踵而至。对于那些迈出作为部落保卫者第一步的年轻兽人和暗矛巨魔来说，学会就地取材与挥舞斧头一样重要。生长在山谷各处的仙人掌结出的成熟果实富含水分，能让人从令人窒息的沙漠烈日下获得即时的慰藉。"},{t="山谷佳肴",b="驻扎在训练场内的戈加尔已将当地的采集工作转化为一门艺术。他那著名的“清凉果”在山谷居民中颇具传奇色彩，因为它能让人在酷暑中迅速降温，效果比跳进河水里还要好。通过雇佣热切的新兵采集附近仙人掌上的带刺果实，戈加尔既保证了厨房的供应，又能确保新来的流浪者不会饿着肚子踏上杜隆塔尔的旅程。"}},faq={{q="戈加尔是谁？",a="戈加尔是一名驻扎在杜隆塔尔试炼谷中的兽人居民。他没有监督正式的战斗演练，而是将时间花在准备降温的补给品和诸如他那著名的清凉果之类的美食上，以帮助新兵抵御沙漠的酷热。",al={"戈加尔是谁","戈加尔背景故事","谁发布仙人掌果任务"}},{q="什么是清凉果？",a="这是一种受欢迎的当地甜点和清凉零食，由戈加尔使用从荒野沙漠仙人掌上采集的新鲜仙人掌果制作而成。它因能在杜隆塔尔灼热的阳光下提供快速的解脱和至关重要的水分而受到学员们的推崇。",al={"清凉果食物","什么是清凉果","戈加尔的食谱"}},{q="仙人掌果在哪里可以找到？",a="仙人掌果生长在散布于试炼谷红色悬崖和峡谷各处的开花仙人掌根部的地面上，通常成簇分布。",al={"仙人掌果在哪里","寻找仙人掌果","如何获得仙人掌果"}},{q="为什么戈加尔要求新兵收集它们？",a="试炼谷内酷热难耐，而戈加尔无法离开岗位去亲自在沙漠中游荡。他提出与任何愿意前往灌木丛中为他收集原材料的过路新手分享他珍贵的成品。",al={"为什么要采集仙人掌果","戈加尔为什么需要果子"}},{q="这个任务与更大的故事情节有关联吗？",a="没有。这是一个独立的采集任务，旨在让新兵在完成部落的初步试炼时，熟悉从当地环境中收集资源。",al={"是否有任务线","清凉果后续","清凉果之后是什么"}},{q="为什么在试炼谷中采集很重要？",a="杜隆塔尔是一片由干旱岩石和灌木丛开垦出来的严酷而无情的土地。部落领袖们认为，学会利用杜隆塔尔稀缺的自然资源生存，是任何想要在更广阔的世界中经受考验的人所必备的基础训练。",al={"为什么要采集","杜隆塔尔生存"}}},fp="30,167,24.363.0,17.366.0,14.212.0,30.216.0,30.145.0,44.216.0,46.128.0,50.185.0"}
P.entries["quest:lazy-peons"] = {n="懒惰的苦工",s="工头塔兹利尔受够了试炼谷的劳工在工作时打瞌睡。他将他那沉重的木棒交给年轻的新兵，并指派他们去试炼谷各处管教偷懒的苦工，以确保重要的木材能持续运往杜隆塔尔的定居点。",h="工头塔兹利尔受够了试炼谷的劳工在工作时打瞌睡。他将他那沉重的木棒交给年轻的新兵，并指派他们去试炼谷各处管教偷懒的苦工，以确保重要的木材能持续运往杜隆塔尔的定居点。",kw={"木棒","杜隆塔尔","工头塔兹利尔","偷懒的苦工","木材","苦工","试炼谷"},ang={["faction:Horde"]="杜隆塔尔的每一个前哨站都依赖于这些苦工采集的木材，因此最基本的劳工纪律也是集体生存的关键。",["race:Orc"]="对于成年的年轻兽人来说，管教自己族人的劳动力是他们上的第一课，让他们了解在荒野中开创一个国家所需的残酷现实和实际纪律。",["race:Troll"]="与盟友并肩训练的暗矛巨魔们亲眼目睹了这种兽人建筑风格中特有的蛮力和管理上的无奈。"},sec={{t="烈日下的偷懒者",b="在杜隆塔尔干旱的平原上建立新家园需要大量的木材、石料和艰苦的体力劳动。大部分负担都落在了苦工阶层身上——他们是兽人中缺乏武艺的一群，但却是部落勤劳的脊梁。不幸的是，对于工头塔兹利尔来说，试炼谷炙热的天气和繁重的劳动让这些劳工很容易溜到树荫下打个非法的小盹。"},{t="迅速的叫醒服务",b="为了避免生产停滞，工头塔兹利尔采取了一种非常直接的管理策略：使用工头的木棒。他将这件钝器纪律工具交给新来的部落新兵，并派他们穿过谷底，去敲醒那些正在睡觉的劳工。被惊醒的苦工们晕头转向地赶回去砍木头，因为他们明白在杜隆塔尔的生存之战中，懒汉是没有立足之地的。"}},faq={{q="苦工们为什么会打瞌睡？",a="在杜隆塔尔烈日的炙烤下采集沉重的木材是一项残酷而耗费体力的工作。如果没有监工在旁边盯着，苦工们经常会溜到大树底下休息。",al={"为什么苦工会偷懒","正在睡觉的苦工","工作时睡觉的苦工"}},{q="工头塔兹利尔是谁？",a="工头塔兹利尔是驻扎在试炼谷的一名兽人监工。他管理着负责采集木材和部落新建设所需物资的劳动团队。",al={"塔兹利尔","谁给予偷懒的苦工任务"}},{q="什么是工头的木棒？",a="这是一根由工头塔兹利尔使用的重皮短棍，用来管教偷懒的劳工。在头上迅速敲一下足以唤醒睡觉的苦工，且不会造成永久性伤害。",al={"木棒","苦工木棍","木棒工具"}},{q="苦工在部落中扮演什么角色？",a="苦工代表了兽人社会的劳动阶层。虽然他们身体强壮，但被认为不适合参加军事战争，而是充当建筑工、矿工和伐木工，为部落的战争机器和定居点提供燃料。",al={"兽人苦工的角色","什么是苦工","苦工阶层"}},{q="我去哪里寻找睡觉的苦工？",a="他们遍布试炼谷，在大兽穴的南北两边都能找到。去那些枝叶茂密的大树底下找，那是劳工们躲避阳光的地方。",al={"偷懒苦工的位置","偷懒的苦工在哪里","寻找睡觉的苦工"}},{q="苦工被唤醒后会发生什么？",a="当你把木棒还给工头塔兹利尔后，他会派你去干另一件杂活：从附近的一个深洞里找回他丢失的矿工锄。",al={"完成偷懒的苦工之后","偷懒的苦工后续任务","苦工任务之后的下一个任务"}}},fp="10,151,19.299.0,20.210.0,33.141.0,25.134.0,32.173.0,37.204.0,35.150.0,42.117.1"}
P.entries["quest:sarkoth"] = {n="萨科斯",s="在试炼谷南侧的一处高地上潜伏着萨科斯，这是一只异常凶猛的蝎虫，它那带毒的蜇刺已将一位年轻的暗矛猎人逼入死亡的边缘。在树下受伤濒死的巨魔哈纳祖恳求一位路过的勇士杀掉这只野兽，并取回它残缺的螯，以此挽回自己的荣誉。",h="在试炼谷南侧的一处高地上潜伏着萨科斯，这是一只异常凶猛的蝎虫，它那带毒的蜇刺已将一位年轻的暗矛猎人逼入死亡的边缘。在树下受伤濒死的巨魔哈纳祖恳求一位路过的勇士杀掉这只野兽，并取回它残缺的螯，以此挽回自己的荣誉。",kw={"暗矛","杜隆塔尔","哈纳祖","残缺的螯","萨科斯","蝎虫","试炼谷"},ang={["faction:Horde"]="在试炼谷这种残酷的环境中，向倒下的同伴伸出援手正是萨尔的部落致力于培养的共同力量的体现。",["race:Orc"]="兽人们理解在没有胜利的情况下死去的痛苦；为哈纳祖复仇赋予了一位未经考验的斥候勇士般的满足感，即看到他的敌人被击败。",["race:Troll"]="对于暗矛部族的同胞而言，响应哈纳祖的恳求是亲情的庄严职责，确保族人的英勇表现得到认可，而不是消逝在杜隆塔尔的风沙之中。"},sec={{t="荣誉之事",b="试炼谷中的试炼旨在磨练部落的年轻勇士，但残酷的荒漠却很少给予第二次机会。当年轻的巨魔斥候哈纳祖在追踪谷中带毒的本土生物时，他遇到了一只比其他同类大得多、也更致命的蝎虫。尽管他成功发起了一次重击，毁掉了它的一只螯，但萨科斯的尾巴还是刺入了哈纳祖的胸口，让他倒在干燥的红土上鲜血直流。在面对生命的终点时，他唯一的愿望就是这只野兽不要活得比他更久。"},{t="高地恐怖",b="萨科斯在俯瞰试炼谷南端的高耸平原上游荡。这只怪兽以哈纳祖攻击留下的破碎螯为标志，盘踞在高高的山脊上，攻击任何胆敢攀爬岩石小径的人。杀掉这只生物并将它伤痕累累的螯带回给哈纳祖，能给这位受伤的斥候带来一些苦涩的慰藉——这证明了他最后那次绝望的攻击确实重创了怪物，让它最终得以被除掉。"}},faq={{q="我在哪里可以找到萨科斯？",a="萨科斯在哈纳祖倒下的地方南面的高地顶部游荡。要找到它，请寻找一条盘旋在峡谷岩壁上的土坡路，那只巨大的蝎虫就在山脊上漫步。",al={"萨科斯位置","萨科斯在哪里","如何到达萨科斯那里"}},{q="谁是哈纳祖？",a="哈纳祖是一位正在试炼谷进行狩猎试炼的年轻暗矛巨魔。他被萨科斯抓伤并中了毒，正瘫倒在一棵树下，绝望地寻找冒险者在他伤重不治前为他复仇。",al={"哈纳祖","濒死的巨魔 试炼谷","萨科斯任务发布者"}},{q="为什么哈纳祖想要萨科斯的螯？",a="在战斗中，哈纳祖在被刺中前发起了猛烈的一击，震碎了萨科斯的螯。取回那只残缺的螯不仅是怪物已死的证明，也能让哈纳祖感到自豪，因为他知道他最后的战斗并非完全徒劳。",al={"为什么需要萨科斯的螯","残缺的螯 证明","哈纳祖 荣誉"}},{q="哈纳祖会死于毒素吗？",a="虽然身受重伤且对自己眼中的失败感到苦涩，但除掉萨科斯给了哈纳祖足够的希望，让他能够派遣你去大兽穴寻求医疗援助，而不是在那棵树下等待死亡。",al={"哈纳祖是否幸存","哈纳祖 命运","哈纳祖死了吗"}},{q="萨科斯与其他蝎虫有什么不同？",a="与在低处谷底匆忙爬行的普通蝎虫工兵不同，萨科斯体型明显更大、更具攻击性，并且带有近期战斗的明显痕迹，包括一只受损的螯。",al={"萨科斯 区别","为什么萨科斯很特别","蝎虫首领 杜隆塔尔"}},{q="杀掉萨科斯后的后续任务是什么？",a="一旦你将萨科斯的螯带回给哈纳祖，他会敦促你尽快赶回大兽穴，将他的困境告知营地领导者，并在他的毒伤导致致命后果之前带回援助。",al={"萨科斯之后的任务","哈纳祖 下一步","回到大兽穴 任务"}}},fp="7,254,17.426.0,18.339.0,25.126.0,16.214.0,38.183.0,33.149.1,49.133.0,49.160.1"}
P.entries["quest:your-place-in-the-world"] = {n="起点",s="这个简单的成年仪式标志着年轻的勇士踏前一步，誓言效忠部落。该任务由试炼谷的卡尔图克发布，旨在将未经考验的新兵直接送往高内克处，开始他们的基础战斗训练。这代表了在杜隆塔尔这片严酷土地上，迈向荣誉与生存的第一步。",h="这个简单的成年仪式标志着年轻的勇士踏前一步，誓言效忠部落。该任务由试炼谷的卡尔图克发布，旨在将未经考验的新兵直接送往高内克处，开始他们的基础战斗训练。这代表了在杜隆塔尔这片严酷土地上，迈向荣誉与生存的第一步。",kw={"cutting teeth","杜隆塔尔","高内克","部落","卡尔图克","新兵","试炼谷","大酋长"},ang={["faction:Horde"]="杜隆塔尔的每一位年轻部落新兵都必须在以大酋长的名义拿起武器之前，证明他们拥有捍卫这个新兴国家的勇气。",["race:Orc"]="对于兽人来说，成年并前往试炼谷报到是一个深刻的文化里程碑，其核心是个人荣誉和战斗准备。",["race:Troll"]="在与兽人盟友一同在杜隆塔尔定居后，暗矛巨魔与他们的兄弟们一起在这里训练，以建立团结并实现共同生存。"},sec={{t="Coming of Age在杜隆塔尔",b="在试炼谷干旱的峡谷中，年轻的兽人和暗矛巨魔必须证明自己的价值，才能踏入外面的世界。在大酋长萨尔的领导下，生活需要力量、警惕和纪律。卡尔图克评估着每一位渴望上阵的新兵，适度地浇灭他们想要与恶魔和巨龙肉搏的梦想，引导他们承担现实的职责。新兵们在这里开始他们的训练，在获得荣耀之前先学会谦逊。"},{t="向高内克报到",b="在距离卡尔图克几步之遥的地方，坐着高内克，这是一位驻扎在篝火旁的粗鲁老兵。高内克以怀疑的眼光评估着这些刚到的新兵，经常抱怨营地里补给匮乏。然而，他的职责是通过严格的试炼来磨练这些初出茅庐的战士，首先就是清除威胁营地补给的当地害虫。"}},faq={{q="这个任务的目的是什么？",a="它作为试炼谷年轻新兵的入门成年仪式。它正式让你加入部落服役，并将你介绍给高内克，由他为你指派第一次真正的战斗任务。",al={"为什么要做这个任务","部落的首个任务","你的世界定位"}},{q="卡尔图克是谁？",a="卡尔图克是一位驻扎在试炼谷入口处的兽人监工。他负责迎接进行成年仪式的新兵，观察他们的情况，并将他们引导至营地内合适的训练师和领导者那里。",al={"卡尔图克的职责","谁发布这个任务"}},{q="高内克是谁？",a="高内克是一位经验丰富的部落训练师，坐在试炼谷的篝火旁。他的任务是测试新来的新兵，并在允许他们离开峡谷之前将他们磨练成合格的士兵。",al={"高内克的职责","高内克在哪里"}},{q="这个任务接下来会引导到哪里？",a="向高内克报到后，将立即开启“Cutting Teeth”试炼，新兵们会被送往泥地中去猎杀斑点野猪，以证明他们基本的战斗能力。",al={"下一个任务是什么","你的世界定位之后的任务"}},{q="为什么要将新兵留在试炼谷？",a="试炼谷是杜隆塔尔内一处隐蔽且受保护的峡谷，旨在训练、评估并淘汰新兵，以免他们在遇到更广阔领地中致命的野兽、野猪人和敌方侦察兵时丧命。",al={"为什么要在试炼谷","为什么要从这里开始"}},{q="这个任务在兽人和巨魔之间有区别吗？",a="年轻的兽人和暗矛巨魔都在试炼谷一起开始他们的训练，并从卡尔图克那里接到同样的入伍征召。",al={"巨魔入门任务","兽人入门任务"}}},fp="23,206,24.396.0,19.308.0,34.179.0,15.164.0,14.184.0,32.154.0,46.192.0,47.127.0"}
P.entries["subzone:addle-s-stead"] = {n="腐草农场",s="腐草农场是位于暮色森林西南部的一处废弃农庄，静静地坐落在乌鸦岭以南那阴暗的森林深处。尽管最初的农场主早已逃离，但这里已成为迪菲亚潜行者的一处隐秘补给站。",h="腐草农场是位于暮色森林西南部的一处废弃农庄，静静地坐落在乌鸦岭以南那阴暗的森林深处。尽管最初的农场主早已逃离，但这里已成为迪菲亚潜行者的一处隐秘补给站。",kw={"腐草农场","迪菲亚","迪菲亚潜行者","暮色森林","乌鸦岭"},ang={["class:Rogue"]="这座隐秘的前哨站显示出迪菲亚组织是多么深入地潜入各个领地，将他们的特工埋藏在暮色森林阴暗的帷幕之下。",["faction:Alliance"]="对于追踪失踪的瓦里安·乌瑞恩国王的联盟调查员来说，这座破败的农舍里保存着迪菲亚潜行者留下的至关重要的阴谋案卷。"},sec={{t="黑暗中的前哨",b="像散布在暮色森林各处的许多被遗忘的家园一样，腐草农场在黑暗与废墟笼罩该地区后逐渐荒废。这里并没有空置太久，而是被迪菲亚潜行者改作他用。迪菲亚的特工们在农场周边游荡，潜伏在破败的农舍内，并将补给品藏在谷仓里，利用暮色森林西南部阴影的掩护，躲避守夜人和暴风城当局的耳目。"},{t="国王失踪之谜",b="迪菲亚潜行者在此的存在已不仅是简单的劫掠。腐草农场充当了一个作战安全屋，保存着兄弟会的重要机密记录。将该地区的阴谋分子与瓦里安·乌瑞恩国王失踪事件联系起来的关键文件和案卷都可以追溯到这片土地上，这使得这座毫不起眼的破败农场成为了揭开联盟内部叛乱阴谋的关键线索。"}},faq={{q="腐草农场在哪里？",a="腐草农场位于暮色森林西南部，坐落在乌鸦岭镇的正南面，沃古尔食人魔山的西侧。",al={"腐草农场位置","腐草农场在哪里","寻找腐草农场"}},{q="现在是谁控制着腐草农场？",a="该农庄目前被迪菲亚潜行者重兵占据，包括夜行者、夜刃刺客和附魔师，他们将旧农舍和谷仓当作一处偏远的藏身点。",al={"谁在腐草农场","腐草农场怪物","腐草农场敌人"}},{q="为什么这座农场被废弃了？",a="和暮色森林的大部分地区一样，当森林陷入黑暗、野兽和亡灵的诅咒之中时，原住居民纷纷逃离，导致该农场被遗弃。",al={"农场发生了什么","addle是谁","为什么腐草农场荒废了"}},{q="是什么让联盟的冒险者来到腐草农场？",a="在暮色森林追踪线索的联盟冒险者有时会被派往腐草农场，搜查这座迪菲亚据点，寻找一份重要的案卷。",al={"为什么去腐草农场","腐草农场任务","暮色森林失踪的国王"}}},fp="13,186,21.286.0,35.298.1,31.122.0,37.138.0,26.127.0,50.136.1"}
P.entries["subzone:agama-gor"] = {n="阿迦玛戈",s="阿迦玛戈是位于南贫瘠之地的一处大型刺鬃野猪人营地，坐落在从陶拉祖营地向西前往莫高雷的道路正北方。它是附近部落哨站的心头大患，充满了敌对的野猪人，它们拼死守卫着这片崎岖的领地。",h="阿迦玛戈是位于南贫瘠之地的一处大型刺鬃野猪人营地，坐落在从陶拉祖营地向西前往莫高雷的道路正北方。它是附近部落哨站的心头大患，充满了敌对的野猪人，它们拼死守卫着这片崎岖的领地。",kw={"阿迦玛戈","贫瘠之地","血岩碎片","刺鬃","陶拉祖营地","碎牙","野猪人"},ang={["faction:Horde"]="陶拉祖营地的安全取决于对阿迦玛戈的刺鬃野猪人的有效压制，因此消灭它们的战士是路过此地的部落守卫者的优先任务。",["race:Tauren"]="阿迦玛戈坐落在通往大门和莫高雷的道路上，其劫掠者对牛头人的补给线和朝圣者构成了长期的威胁。"},sec={{t="刺鬃要塞",b="阿迦玛戈横跨南贫瘠之地尘土飞扬的平原，是好战的刺鬃野猪人部落的防御定居点。这里距离陶拉祖营地极近，野猪人在当地维持着密集的荆棘网、茅屋和粗糙的图腾。它们庞大的存在对往来于贫瘠之地和莫高雷青草山丘之间的旅人构成了严重威胁，促使部落的斥候和猎人必须对它们进行持续不断的遏制战。"},{t="血岩碎片与流放者",b="除了部落与野猪人之间普遍的敌意之外，阿迦玛戈还是被称为“血岩碎片”的神秘绯红色矿石的主要来源。这些地质矿物在栖息于村庄的刺鬃野猪人身上可以找到，是被关押在陶拉祖营地的野猪人流放者碎牙所珍视的物品。在与阿迦玛甘的神圣本质相关的古老信仰驱使下，冒险者们经常突袭阿迦玛戈，收集这些碎片并用它们换取强大的部落护符。"}},faq={{q="阿迦玛戈是什么地方？",a="阿迦玛戈是南贫瘠之地的一处大型刺鬃野猪人定居点。它位于从陶拉祖营地向西通往莫高雷的主路正北方。",al={"阿迦玛戈概览","这个野猪人营地是什么","陶拉祖附近的野猪人营地"}},{q="为什么这里的刺鬃野猪人如此敌对？",a="野猪人认为，所有受过倒下的野猪半神阿迦玛甘触碰过的土地都理应属于它们。因此，刺鬃野猪人将陶拉祖营地附近的牛头人和兽人视为侵犯它们祖传土地的不速之客。",al={"为什么野猪人会攻击","野猪人的敌意","为什么刺鬃野猪人如此愤怒"}},{q="在阿迦玛戈能找到什么？",a="阿迦玛戈各处的刺鬃野猪人经常携带血岩碎片——这些充斥着原始力量的结晶沉积物可以交给陶拉祖营地的被流放野猪人碎牙进行交易。",al={"在这里能获得什么","阿迦玛戈掉落物品","为什么要杀这里的刺鬃野猪人"}},{q="碎牙是谁？他与这个地方有什么关系？",a="碎牙是一只被囚禁在陶拉祖营地牢笼里的被流放野猪人。它对自己的族人怀恨在心，只要部落冒险者能从阿迦玛戈的旧日同类身上带来血岩碎片，它就乐于为他们提供防护护符。",al={"与碎牙的关系","谁是碎牙","陶拉祖的猪人囚犯"}}},fp="9,181,24.267.0,22.317.0,18.143.0,49.192.0,31.163.0,56.202.0"}
P.entries["subzone:agamand-family-crypt"] = {n="阿加曼德家族墓穴",s="阿加曼德家族墓穴坐落在阿加曼德磨坊北侧的山丘中，是提瑞斯法最富有的农场主家族之一的古老安息地。如今，这里已被达戈尔队长率领的天灾军团占据，墓穴遭到破坏，沉睡的祖先被复活，成为了毫无心智的恐怖怪物。",h="阿加曼德家族墓穴坐落在阿加曼德磨坊北侧的山丘中，是提瑞斯法最富有的农场主家族之一的古老安息地。如今，这里已被达戈尔队长率领的天灾军团占据，墓穴遭到破坏，沉睡的祖先被复活，成为了毫无心智的恐怖怪物。",kw={"阿加曼德家族墓穴","阿加曼德磨坊","达戈尔队长","墓穴","陵墓","天灾军团","骷髅","提瑞斯法林地"},ang={["race:Undead"]="对于被遗忘者来说，达戈尔队长对墓穴的占领是天灾军团在提瑞斯法的一种不可容忍的存在，不仅亵渎了死者，还威胁到了幽暗城的北部边境。"},sec={{t="不安的先祖",b="在第三次战争之前，阿加曼德家族在提瑞斯法林地北部拥有广阔的地产，并将他们的先辈埋葬在这座山坡陵墓中。当瘟疫摧毁王国时，这座墓穴落入了天灾军团的走狗——达戈尔队长的魔爪之中。达戈尔并没有让这个富有家族的先人们安息，而是利用黑暗通灵术唤醒了墓穴中的骷髅和充满怨恨的幽灵，将这片神圣的墓地变成了一个位于被遗忘者领地边缘的侵略性天灾据点。"}},faq={{q="阿加曼德家族墓穴在哪里？",a="墓穴开凿在提瑞斯法林地北部的山坡上，位于阿加曼德磨坊的正北方。",al={"阿加曼德墓穴位置","墓穴在哪里","如何找到阿加曼德墓穴"}},{q="现在是谁控制着这座墓穴？",a="这座陵墓由天灾军团的仆从达戈尔队长把守，他策划了墓穴内的黑暗魔法并指挥着那些复活的死尸。",al={"阿加曼德墓穴里有什么人","墓穴首领","达戈尔队长"}},{q="我会在墓穴里遇到什么？",a="墓穴里充满了被唤醒的骷髅和不安的阿加曼德先祖之灵。在黑暗魔法的驱使下，这些复仇心切的亡灵会攻击任何踏入墓穴的人。",al={"墓穴敌人","阿加曼德墓穴里有什么","阿加曼德墓穴怪物"}},{q="墓穴里的亡灵是被遗忘者的盟友吗？",a="不是。里面的生物是听命于达戈尔队长的天灾奴仆，因此它们对被遗忘者和生者旅行者都怀有敌意。",al={"他们是被遗忘者吗","阿加曼德墓穴友好度","为什么要攻击亡灵"}}},fp="20,242,18.414.0,42.104.0,33.79.0,39.142.0,57.120.0"}
P.entries["subzone:agamand-mills"] = {n="阿加曼德磨坊",s="阿加曼德磨坊是一处位于提瑞斯法林地北部高地的庞大农场与风车群。这里曾是富有的阿加曼德家族引以为傲的庄园，如今却已荒废，成为了该地区最大的天灾军团据点。",h="阿加曼德磨坊是一处位于提瑞斯法林地北部高地的庞大农场与风车群。这里曾是富有的阿加曼德家族引以为傲的庄园，如今却已荒废，成为了该地区最大的天灾军团据点。",kw={"阿加曼德","阿加曼德家族墓穴","阿加曼德磨坊","达格尔队长","德夫林·阿加曼德","格雷戈尔·阿加曼德","天灾军团","提瑞斯法林地"},ang={["race:Undead"]="对于被遗忘者而言，收复阿加曼德磨坊不仅是战术上的需要，更是对天灾军团的私人复仇，以及像库勒曼·法席恩这样的前庄园仆从清算旧账的时刻。"},sec={{t="分裂的家族",b="富有的阿加曼德家族在提瑞斯法北部建立了一套庞大的磨坊网络。当第三次战争爆发，天灾军团席卷洛丹伦时，族长格雷戈尔·阿加曼德拒绝逃离，他加固了庄园，并说服了他的家臣和劳工坚守阵地。他们的补给和石墙本可以支撑住，但他们最小的儿子德夫林·阿加曼德背叛了自己的血脉。德夫林屠杀了庄园的守卫，并将行尸走肉放进了寝室。从内部瓦解后，剩余的防御者被消灭，整个家族也加入了毫无意识的亡灵行列。"},{t="腐朽的堡垒",b="如今，阿加曼德磨坊已成为提瑞斯法林地中最根深蒂固的天灾军团堡垒，对被遗忘者的领地构成了直接威胁。腐朽的风车在布满尸妖、僵尸和骷髅怪的田野上空转动。在庄园地下，达格尔队长在深处的阿加曼德家族墓穴中指挥着驻军，练习着死灵法术，复活了一代又一代的阿加曼德先祖。在布瑞尔，执政官塞弗伦和死亡卫士们正积极发起战役，试图在天灾军团进军幽暗城之前清理磨坊，清除那里的天灾势力。"}},faq={{q="为什么阿加曼德磨坊会被天灾军团占领？",a="当天灾军团蹂躏洛丹伦时，阿加曼德家族加固了他们的庄园，试图抵御亡灵大军。然而，最小的儿子德夫林·阿加曼德背叛了家族，打开大门迎接天灾军团，导致庄园内的所有人都被屠杀并复活。",al={"阿加曼德磨坊发生了什么","为什么磨坊里有亡灵","阿加曼德磨坊背景故事"}},{q="现在是谁控制着这些磨坊？",a="这座庄园是天灾军团的一个地区前哨站，由达格尔队长领导。达格尔在戒备森严的阿加曼德家族墓穴深处活动，利用黑暗魔法将先祖的尸体复活为新的士兵。",al={"谁领导着阿加曼德磨坊","提瑞斯法的天灾领袖","谁负责磨坊"}},{q="为什么被遗忘者关心这个地方？",a="这些磨坊代表了提瑞斯法林地中残存的天灾军团无意识部队的最大聚集地。如果任其发展，达格尔队长的部队将威胁到布瑞尔，并可能切断通往南方幽暗城的道路。",al={"为什么布瑞尔要攻击阿加曼德","被遗忘者对阿加曼德磨坊的兴趣"}},{q="阿加曼德家族是谁？",a="他们曾是洛丹伦一个富有的地主家族，拥有提瑞斯法北部境内的磨坊和周边农田。如今，其复活后的后裔——包括格雷戈尔、尼莎、瑟曼和德夫林——正作为毫无意识的奴仆在庄园里游荡。",al={"阿加曼德家族是谁","阿加曼德家族血统","格雷戈尔·阿加曼德"}}},fp="13,173,15.586.0,16.500.0,42.247.0,33.157.0,42.201.0,27.235.0"}
P.entries["subzone:agmond-s-end"] = {n="埃格蒙德的营地",s="埃格蒙德的营地是位于荒芜之地南部丘陵中的一处废弃矮人挖掘场。这里曾经是一处充满希望的勘探点，由勘探员埃格蒙德领导，但在穴居怪破土而出并 overrun 了营地、杀害了领队之后，这里变成了一座屠宰场。",h="埃格蒙德的营地是位于荒芜之地南部丘陵中的一处废弃矮人挖掘场。这里曾经是一处充满希望的勘探点，由勘探员埃格蒙德领导，但在穴居怪破土而出并 overrun 了营地、杀害了领队之后，这里变成了一座屠宰场。",kw={"埃格蒙德","埃格蒙德的营地","荒芜之地","挖掘场","勘探员","迷失者塞尔杜林","穴居怪"},ang={["race:Dwarf"]="这座营地严酷地提醒着人们，在没有足够军事支援的情况下挖掘古老的大地是有多么危险。"},sec={{t="恐怖的挖掘场",b="和荒芜之地干旱地区中的许多地点一样，埃格蒙德的营地最初是一项矮人企图发掘古代遗物并深入探索大地埋藏历史的冒险。当野蛮的穴居怪从周围的裂隙中涌出并淹没矿工时，那个梦想戛然而止。埃格蒙德本人在袭击中被杀，这个地点因此得名。今天，这座被毁的挖掘场仍然完全被石库穴居怪所占据，破碎的板条箱和废弃的工具依然留在它们当初掉落的地方。"},{t="孤独的邻居",b="在被毁的挖掘场附近坐落着一座孤零零的营地，居住着迷失者塞尔杜林，一位理智早已丧失的矮人。他是少数几个愿意在这处注定的毁灭之地附近的南部沙漠中冒险的人之一。"}},faq={{q="埃格蒙德是谁？",a="埃格蒙德是一位矮人勘探员，他领导了一次进入荒芜之地南部的挖掘行动。他的勘探工作在地下穴居怪出现并屠杀了包括他在内的整个探险队后，以灾难告终。",al={"埃格蒙德是谁","埃格蒙德背景故事"}},{q="什么生物居住在埃格蒙德的营地？",a="这座被毁的挖掘场被敌对的穴居怪彻底占据，它们屠杀了矮人矿工，并将被毁的营地及周围的岩架据为己有。",al={"埃格蒙德的营地的怪物","谁住在这里"}},{q="谁住在埃格蒙德的营地附近？",a="一位名为迷失者塞尔杜林的矮人隐士在附近的南部丘陵中维持着一个营地，警惕地注视着这片荒凉的土地。",al={"附近的npc","塞尔杜林的位置"}},{q="为什么矮人最初要在这里挖掘？",a="矮人勘探员经常在荒芜之地进行勘探，以寻找泰坦遗物、古代遗迹和丰富的矿脉，尽管许多此类探险队都低估了潜伏在地下的野蛮生物。",al={"为什么矮人要挖掘","挖掘的目的"}}},fp="12,266,21.475.0,17.215.0,15.181.0,36.158.0,28.137.0,49.204.0"}
P.entries["subzone:aku-mai-s-lair"] = {n="Aku'mai's Lair",s="Aku'mai's Lair是黑暗深渊中最深、最黑暗的洞穴。它位于Moonshrine Sanctum之后，这个被淹没的空洞是阿库麦尔的巢穴，这是一只被尊为上古之神仆从的恐怖多头蛇。",h="Aku'mai's Lair是黑暗深渊中最深、最黑暗的洞穴。它位于Moonshrine Sanctum之后，这个被淹没的空洞是阿库麦尔的巢穴，这是一只被尊为上古之神仆从的恐怖多头蛇。",kw={"aku'mai's lair","阿库麦尔","黑暗深渊","多头蛇","moonshrine sanctum","纳迦","上古之神","暮光之锤"},ang={["class:Druid"]="从阿库麦尔的水下巢穴中散发出的邪恶变异和非自然腐蚀，对卡利姆多的自然水道和野兽构成了严重的破坏。",["race:NightElf"]="对于暗夜精灵来说，看到一座被亵渎的艾露恩神庙最终沦为邪恶上古之神孽种的肮脏巢穴，是对神圣的灰谷土地不可容忍的玷污。"},sec={{t="深渊之心",b="Aku'mai's Lair被封印在Moonshrine Sanctum之后，代表了席卷黑暗深渊的腐蚀的顶峰。要进入洞穴，必须通过点燃纳迦雕像两旁的四个火盆来进行黑暗仪式，从而唤醒誓死保卫入口的守护者。在这些沉重的双开门之后是一个不见天日的洪水淹没的洞穴。在这里，暮光之锤教徒和入侵的纳迦聚集在一起，崇拜着阿库麦尔——一只被认为是上古之神活仆从的古老三头多头蛇。"},{t="毁灭的先驱",b="阿库麦尔在巢穴中的存在使其成为了暮光之锤末日计划的焦点。教徒们将这只巨兽视为预示着黑暗时代的到来，认为它的出现和持续的滋养将预示着囚禁他们古老神祇的地底监狱的破碎。在献祭供品的滋养和黑魔法的狂热守护下，这个地下水潭成为了古老邪恶试图重返卡利姆多的阴森象征。"}},faq={{q="Aku'mai's Lair位于哪里？",a="Aku'mai's Lair位于灰谷黑暗深渊洞穴群的最深处，就在Moonshrine Sanctum的封印之门后面。",al={"aku'mai's lair在哪里","如何到达阿库麦尔的房间","aku'mai's lair位置"}},{q="如何打开通往Aku'mai's Lair的大门？",a="通往巢穴的双开门需要通过点燃Moonshrine Sanctum内环绕纳迦雕像的四个仪式火盆，并击败被召唤出来保护它们的生物波次来解锁。",al={"打开aku'mai's lair大门","如何解锁aku'mai's lair","点燃阿库麦尔火盆"}},{q="这个洞穴里栖息着什么？",a="该洞穴栖息着阿库麦尔，这是一只被远古黑暗力量污染的巨大三头多头蛇，也是上古之神的仆从。",al={"aku'mai's lair里有什么","aku'mai's lair里栖息着什么","aku'mai's lair的头目"}},{q="为什么暮光之锤教派在这里进行崇拜？",a="暮光之锤将阿库麦尔尊为上古之神的仆从，其教徒们相信增强这头野兽的力量将有助于带回上古之神统治世界的时代。",al={"为什么教徒崇拜阿库麦尔","暮光之锤与aku'mai's lair","为什么暮光之锤在这里"}}},fp="14,190,19.370.0,17.394.0,32.135.0,44.178.0,31.121.0,50.166.0"}
P.entries["subzone:aldrassil"] = {n="奥达希尔",s="奥达希尔是位于泰达希尔东北部幽影谷中心地带的巨大枝树和定居点。作为年轻卡多雷的主要避难所和训练场，它那雕琢出的树洞中安置着训练师、商人和当地的领导者。",h="奥达希尔是位于泰达希尔东北部幽影谷中心地带的巨大枝树和定居点。作为年轻卡多雷的主要避难所和训练场，它那雕琢出的树洞中安置着训练师、商人和当地的领导者。",kw={"奥达希尔","巨树","卡多雷","暗夜精灵起始","幽影谷","泰达希尔","特纳隆·雷拳"},ang={["class:Druid"]="奥达希尔展示了卡多雷对活体建筑的偏好，它们由活木塑形而成，且没有破坏森林的平衡。",["race:NightElf"]="对于许多年轻的卡多雷来说，奥达希尔雕刻出的树洞和坡道是他们对城市生活的第一记忆，也是他们早期训练的基础。"},sec={{t="幽影谷之心",b="奥达希尔高耸于幽影谷僻静的山谷之上，既是年轻暗夜精灵踏入世界第一步时的避难所，也是他们的市政中心。这座古老植被的巨大树干被建筑所环绕，蜿蜒的坡道通向各处的职业训练师和工匠，并最终到达高处的栖木，特纳隆·雷拳就在那里统筹整个幽影谷的防务。当世界之树泰达希尔横跨地平线时，奥达希尔提供了一处安全、稳固的树冠，新手们在此学习技艺，随后才踏入卡利姆多动荡的荒野。"}},faq={{q="奥达希尔是什么？",a="奥达希尔是位于泰达希尔东北部幽影谷中心的一棵巨大的空心树和定居点。它是年轻暗夜精灵聚集在一起获取训练、物资和指导的起始避难所。",al={"奥达希尔树","奥达希尔是什么","幽影谷大树"}},{q="谁领导着奥达希尔的定居点？",a="特纳隆·雷拳从他位于奥达希尔顶端的栖木上统筹幽影谷，协调山谷的防御，并指导新觉醒的卡多雷。",al={"谁领导奥达希尔","奥达希尔领袖","特纳隆·雷拳位置"}},{q="这里有哪些服务？",a="这棵树为年轻的暗夜精灵战士、潜行者、德鲁伊、猎人和牧师提供了职业训练师，此外还有当地的补给商人、护甲商和任务发布者，以满足山谷的直接需求。",al={"奥达希尔的训练师","奥达希尔商人","奥达希尔里有什么"}}},fp="9,175,19.386.0,18.177.0,38.140.0,32.164.0"}
P.entries["subzone:alexston-farmstead"] = {n="阿历克斯顿农场",s="阿历克斯顿农场是西部荒野中一座荒废的农场，杂草丛生，到处都是失控的收割守卫。这里曾经是暴风城首席建筑师巴隆斯·阿历克斯顿儿时的家，如今像这片谷仓地区的大部分地方一样，已沦为废墟。",h="阿历克斯顿农场是西部荒野中一座荒废的农场，杂草丛生，到处都是失控的收割守卫。这里曾经是暴风城首席建筑师巴隆斯·阿历克斯顿儿时的家，如今像这片谷仓地区的大部分地方一样，已沦为废墟。",kw={"阿历克斯顿","建筑师","巴隆斯","指南针","农场","收割守卫","西部荒野"},ang={["faction:Alliance"]="这座农场不仅提醒着人们，暴风城那些杰出大脑亦出身于勤劳朴实的根基，也反映了联盟在保护自身边境时所面临的持续斗争。"},sec={{t="衰败的家园",b="阿历克斯顿农场坐落在西部荒野干旱的平原上，是王国疏于治理的又一个惨痛见证。像邻近的地产一样，当乡村地区匪患爆发时，农场的看护人便弃之而去。如今，田地已荒芜，留下来照料庄稼的机械收割守卫也已失控，疯狂地攻击任何靠近这座荒废农舍的人。"},{t="卑微的出身",b="尽管农场现状凄凉，它却与暴风城最显赫的公民之一有着渊源。巴隆斯·阿历克斯顿，那位参与设计了重建后的暴风城部分区域的建筑大师，年轻时曾在这片田地上劳作。他在动荡开始前很久就离开了农场，前往首都从事石匠和建筑行业，只留下了关于他早年生活的一件纪念品，藏在废墟之中。"}},faq={{q="谁拥有阿历克斯顿农场？",a="这座农场以暴风城建筑师巴隆斯·阿历克斯顿的家族命名。巴隆斯年幼时曾在这里耕作，后来前往首都投身于建筑事业。",al={"谁拥有这座农场","阿历克斯顿农场主","这是谁的农场"}},{q="为什么农场会被废弃？",a="像西部荒野的大部分地区一样，该农场是在迪菲亚潜行者引发的大规模动荡和匪患之后被废弃的。由于王国无法提供保护，农民们被迫逃离，任由家园腐朽。",al={"为何废弃","阿历克斯顿农场发生了什么","谁摧毁了农场"}},{q="为什么这里的机械稻草人会攻击人？",a="机械收割守卫最初是被制造出来用于耕作和保护庄稼免受食腐动物侵害的。在农民逃离后，由于无人维护，它们的内部发条装置发生故障，导致它们对任何活着的生物都变得极具攻击性。",al={"为何收割守卫会攻击","敌对的稻草人","收割傀儡敌对"}},{q="农舍里有什么隐藏的东西吗？",a="巴隆斯·阿历克斯顿在农舍里留下了一件他年轻时的个人指南针。在暴风城做事的旅行者有时会被要求从这座荒废的家园中取回它。",al={"这里的任务","农场里的战利品","巴隆斯的物品"}}},fp="18,140,18.275.0,12.250.0,32.141.0,26.192.0,52.204.0,46.176.0"}
P.entries["subzone:algaz-station"] = {n="奥加兹岗哨",s="奥加兹岗哨是一座位于洛克莫丹西北部的矮人军事哨所，就在丹奥加兹防守严密的关口正南方。哨所的巡山人把守着通往北方隧道的入口，保护过往旅客并监视通往沼泽地的边境。",h="奥加兹岗哨是一座位于洛克莫丹西北部的矮人军事哨所，就在丹奥加兹防守严密的关口正南方。哨所的巡山人把守着通往北方隧道的入口，保护过往旅客并监视通往沼泽地的边境。",kw={"奥加兹岗哨","丹奥加兹","gothor brumn","铁炉堡","洛克莫丹","巡山人卡尔·雷矛","巡山人","北门小径"},ang={["faction:Alliance"]="对于往返于洛克莫丹和北部沼泽地之间的联盟冒险者来说，这座哨所提供了一个安全的集结地和维修站。",["race:Dwarf"]="对于矮人旅行者而言，奥加兹岗哨是铁炉堡势力范围的熟悉标志，确保了国王的公路时刻受到守卫，免受来自山脉威胁的侵扰。"},sec={{t="监视北门小径",b="奥加兹岗哨位于北门小径正东方，丹奥加兹正南方，是铁炉堡王国的关键战略观察点。一队矮人巡山人在此长期驻守，确保洛克莫丹与北方低地之间这条至关重要的道路畅通无阻，以供贸易和军队通行。鉴于周边丘陵地区常有威胁，从游荡的野兽到入侵的穴居人，这里为疲惫的旅人在冒险穿越山间隧道之前提供了休憩、维修和武力支援。"}},faq={{q="奥加兹岗哨是什么地方？",a="这是位于洛克莫丹西北部的一座铁炉堡军事哨所。它作为警卫站和中转站，供巡逻通往丹奥加兹的山口的巡山人使用。",al={"这是什么地方","奥加兹岗哨的用途","谁在管理奥加兹岗哨"}},{q="这个哨所的名字从何而来？",a="它的名字源于丹奥加兹，即位于哨所正北方，连接洛克莫丹与沼泽地的巨大矮人关口和隧道系统。",al={"为什么叫奥加兹岗哨","与丹奥加兹的关系","名字含义"}},{q="谁驻扎在奥加兹岗哨？",a="这座哨所由矮人巡山人把守，其中包括巡山人卡尔·雷矛，以及像护甲商Gothor Brumn这样的后勤人员，他为旅客提供现场维修服务。",al={"谁在这里","奥加兹岗哨的npc","巡山人卡尔·雷矛的位置"}}},fp="13,155,26.435.0,22.165.0,36.149.0,34.116.0"}
P.entries["subzone:altar-of-storms-burning-steppes"] = {n="风暴祭坛 (燃烧平原)",s="风暴祭坛坐落在燃烧平原的锯齿状山崖中，是一座专门用于邪能仪式和恶魔之力的黑暗纪念碑。黑石氏族的术士们占据了这个险恶之地，在黑石塔的阴影下施展邪恶魔法。它散发的黑暗光环吸引了来自艾泽拉斯各地的暗影法术追求者。",h="风暴祭坛坐落在燃烧平原的锯齿状山崖中，是一座专门用于邪能仪式和恶魔之力的黑暗纪念碑。黑石氏族的术士们占据了这个险恶之地，在黑石塔的阴影下施展邪恶魔法。它散发的黑暗光环吸引了来自艾泽拉斯各地的暗影法术追求者。",kw={"风暴祭坛","黑石","燃烧平原","邪能","gorzeeki wildeyes","mor'zul bloodbringer","术士"},ang={["class:Warlock"]="风暴祭坛及其附近的隐士Mor'zul Bloodbringer和Gorzeeki Wildeyes，是术士们寻找召唤恐惧战马所需材料和仪式的关键渠道。",["race:Orc"]="这座祭坛令人不快地提醒着人们旧部落的黑暗历史，当时古尔丹的暗影议会使用类似的邪恶神龛，将黑暗巫术注入食人魔和士兵体内。"},sec={{t="阴影与火焰的遗产",b="风暴祭坛建于早期的战争期间，用于引导腐蚀性的邪能魔法，它是一座黑暗契约的阴森纪念碑。在燃烧平原，充满敌意的黑石氏族术士控制着这片土地，进行神秘的仪式并汲取恶魔力量。附近，隐士Gorzeeki Wildeyes和他的导师Mor'zul Bloodbringer的营地俯瞰着这里，叛逆的修行者们研究着其狂暴的能量，并为寻求更强大黑暗力量的野心勃勃的施法者们调制高难度的仪式。"}},faq={{q="风暴祭坛是什么？",a="这是一座被腐蚀的石质纪念碑，用于黑暗邪能仪式和引导恶魔能量。它建于旧部落战争时期，至今仍是黑石术士利用黑暗力量的核心枢纽。",al={"风暴祭坛背景故事","这个祭坛是什么","燃烧平原祭坛"}},{q="现在是谁控制着这座祭坛？",a="属于黑石兽人氏族的敌对术士和侍僧占据了祭坛周围的区域，执行黑暗仪式并守卫着该地点，抵御入侵者。",al={"风暴祭坛里有什么人","风暴祭坛的敌人","谁住在这里"}},{q="Gorzeeki Wildeyes是谁？",a="Gorzeeki Wildeyes是一位古怪的黑暗艺术地精学者，他和他的导师Mor'zul Bloodbringer一起住在俯瞰祭坛的山丘上。他协助那些寻求掌握更强大恶魔契约的强大术士。",al={"gorzeeki wildeyes","山上的兽人","gorzeeki是谁"}}},fp="33,324,28.524.0,28.203.0,33.181.0,25.235.0"}
P.entries["subzone:alterac-mountains"] = {n="奥特兰克山脉",s="奥特兰克山脉是一片崎岖的雪冠山岭，耸立在希尔斯布莱德那连绵起伏的牧场之上。这里曾是一个骄傲的人类王国的核心，如今山坡上只剩下废弃的定居点、强盗派系和危险的荒野，鲜有旅客敢于在无人护卫的情况下踏足此地。",h="奥特兰克山脉是一片崎岖的雪冠山岭，耸立在希尔斯布莱德那连绵起伏的牧场之上。这里曾是一个骄傲的人类王国的核心，如今山坡上只剩下废弃的定居点、强盗派系和危险的荒野，鲜有旅客敢于在无人护卫的情况下踏足此地。",kw={"奥特兰克","石拳","希尔斯布莱德","山脉","匹瑞诺德","斯坦恩布莱德","辛迪加"},ang={["class:Rogue"]="山口充满了辛迪加特工和雇佣来的杀手，使这些山丘成为了考验生存能力和反间谍能力的绝佳场所。",["faction:Alliance"]="对于联盟而言，奥特兰克是背叛带来的痛苦纪念碑，匹瑞诺德的背信弃义在第二次战争中险些将人类推入毁灭的深渊。"},sec={{t="一个陨落的王国",b="在这些山丘陷入混乱的很久以前，这些高地组成了奥特兰克这个主权国家，它是源自古老阿拉索的七个王国之一。然而，这一遗产在第二次战争中破碎了，当时奥特兰克国王艾登·匹瑞诺德与旧部落达成了秘密协议，允许兽人军队穿过山峰，以换取其王国的安全。洛丹伦联盟发现了这场背叛并废黜了匹瑞诺德，使得该地区陷入了军事管制和领土争端的破碎状态。"},{t="荒野与强盗",b="第三次战争的浩劫过后，群山完全陷入了无法无天的境地。该国被剥夺了继承权的贵族们结成辛迪加，以斯坦恩布莱德的废墟为基地，企图通过破坏和暗杀夺回他们失去的领土。在占据着破碎首都的残暴石拳食人魔、四处劫掠的豺狼人，以及达拉然周围破碎的魔法废墟之间，奥特兰克的山径依然是洛丹伦最危险的通路之一。"}},faq={{q="过去是哪个王国统治这些山脉的？",a="在阿拉索帝国分裂后，奥特兰克人类王国统治了这些山脉数代之久。它的首都坐落在最高峰之间，扼守着通往洛丹伦、达拉然和阿拉希高地的道路，直到其在第二次战争中陨落。",al={"谁拥有奥特兰克","奥特兰克是什么","奥特兰克王国历史"}},{q="奥特兰克为何沦为废墟？",a="在第二次战争期间，奥特兰克国王艾登·匹瑞诺德通过协助部落背叛了洛丹伦联盟。当叛国罪行败露后，联盟军队摧毁了奥特兰克的军队并废黜了王室。由于没有了合法统治者，加上随后第三次战争的破坏，这个国家最终坍塌成了一片废墟。",al={"奥特兰克发生了什么","谁摧毁了奥特兰克","奥特兰克废墟背景故事"}},{q="潜伏在山丘中的辛迪加是什么人？",a="辛迪加是一个由前奥特兰克贵族及其仆从组成的法外组织。在艾登·匹瑞诺德的领导下，他们雇佣强盗、刺客和流氓雇佣兵来破坏该地区的局势，企图通过暴力手段复辟他们的王国。",al={"谁是辛迪加","辛迪加是什么","为什么奥特兰克有强盗"}},{q="什么威胁游荡在雪峰之上？",a="勇敢攀登山坡的旅客必须与残暴的石拳食人魔、成群的高地豺狼人、拾荒的狗头人以及巡逻在山径上的投机取巧的辛迪加强盗周旋。",al={"奥特兰克有什么生物","奥特兰克怪物","奥特兰克的威胁"}}},fx={e4635e9a={q="奥特兰克山脉是什么地方？",a="奥特兰克山脉是一片崎岖、终年积雪的山脉，横亘在洛丹伦中部，位于希尔斯布莱德丘陵以北。这里曾是人类王国奥特兰克的领土，山上遍布设防的城市、山间要塞和偏远山谷。如今王国已分崩离析，城镇在风雪中化为废墟，冰封的山峰成了残余流亡者、交战部族和掠食怪物的战场。",al={"奥特兰克山脉是什么","奥特兰克山脉传说","奥特兰克地区概况"}},["858b3945"]={q="如今谁统治奥特兰克山脉？",a="没有合法政权统治奥特兰克山脉。奥特兰克王国在第二次战争中背叛盟友后覆灭，天灾军团的进攻又扫荡了残存的秩序。如今，辛迪加——由佩瑞诺德家族后裔领导、失去领地的人类贵族和亡命之徒——声称对这些废墟拥有祖传权利。然而，他们还在与凶残的碎脊食人魔、四处游荡的亡灵，以及盘踞在高山山谷中的霜狼兽人激烈争斗。",al={"谁控制奥特兰克","谁住在奥特兰克山脉","奥特兰克的领导者"}}},fp="17,274,14.492.0,22.502.0,42.266.0,24.302.0,43.246.0,36.195.0"}
P.entries["subzone:alterac-mountains-classic"] = {n="Alterac Mountains (Classic)",s="奥特兰克山脉是一片崎岖、阴云密布的高地，位于希尔斯布莱德丘陵的北面，地势陡峭，终年积雪，山峰险峻。这里曾经是人类王国奥特兰克和学术圣地达拉然的所在地，如今大部分地区已沦为废墟，残暴的Crushridge食人魔、贵族出身的强盗以及奥特兰克山谷的敌对军队在此争斗不休。",h="奥特兰克山脉是一片崎岖、阴云密布的高地，位于希尔斯布莱德丘陵的北面，地势陡峭，终年积雪，山峰险峻。这里曾经是人类王国奥特兰克和学术圣地达拉然的所在地，如今大部分地区已沦为废墟，残暴的Crushridge食人魔、贵族出身的...",kw={"奥特兰克山脉","奥特兰克山谷","crushridge食人魔","达拉然","洛丹米尔","奥特兰克废墟","斯坦恩布莱德","syndicate","高地"},ang={["class:Rogue"]="在边境一个僻静的山谷中坐落着拉文霍德庄园，这是由乔拉齐·拉文霍德公爵领导的盗贼和刺客公会的历史总部。",["faction:Alliance"]="联盟在哈格丁中尉的带领下在这些冰冷的丘陵中维持着一个前哨站，招募坚定的战士以增援奥特兰克山谷中的雷矛卫队。"},sec={{t="破碎的高地",b="奥特兰克山脉耸立在希尔斯布莱德低地之上，是一片充斥着雨水、松树和高海拔积雪的严酷之地。这里曾经由三大主要人类势力所主导——奥特兰克山王国、魔法王国达拉然以及坚固的城镇斯坦恩布莱德，但后来由于背叛和战争，这一地区分崩离析。如今，奥特兰克的废墟首都被Crushridge食人魔盘踞，斯坦恩布莱德被不法之徒占据，而在达拉然的残垣断壁中，幸存的法师们正不知疲倦地试图修复他们毁灭的圣所。"},{t="强盗、野兽与战争",b="除了在冻伤的山脊上潜伏的本地山狮和雪人之外，这片高地还被绝望的凡人派系所争夺。Syndicate——由失去土地的落魄人类贵族转变成的强盗——在旧庄园和山麓营地中挥舞着利刃，不断伏击并与入侵的食人魔发生冲突。与此同时，通往高耸山峰的深谷成为了雷矛远征军和霜狼氏族之间为了争夺奥特兰克山谷隐秘区域而展开的血腥战争的集结地。"}},faq={{q="奥特兰克王国发生了什么？",a="奥特兰克在第二次战争期间陷入了耻辱，当时它的统治者，国王Aiden Perenolde，背叛了联盟并协助部落。战争结束后，该王国被解散。由于缺乏领导，它的城市土崩瓦解，斯坦恩布莱德沦为废墟，而它的首都则被残暴的Crushridge食人魔所占领。",al={"奥特兰克为何沦为废墟","谁统治奥特兰克","奥特兰克的陨落"}},{q="山里的Syndicate强盗是谁？",a="Syndicate是一个由前奥特兰克贵族及其随从组成的不法组织。在奥特兰克背叛后，他们失去了土地、地位和财富，为了夺回他们认为属于自己的土地，他们开始从事间谍、暗杀和公路抢劫活动。",al={"syndicate是什么","奥特兰克为何有盗贼","奥特兰克强盗"}},{q="湖岸边巨大的紫色圆顶是什么？",a="今天达拉然上方没有圆顶。在第三次战争期间，这座城市被恶魔领主Archimonde夷为平地后，幸存的肯瑞托法师在废墟上竖起了一道紫色的护盾，但他们在重建早期就将其移除了，现在他们正在空地上重建他们那被毁坏的塔楼。",al={"奥特兰克的紫色泡泡","什么是达拉然圆顶","达拉然魔法护盾"}},{q="如何前往奥特兰克山脉？",a="旅行者通常从希尔斯布莱德丘陵步行进入，沿着塔伦米尔北部的道路或南海镇北部的道路前行。或者，大胆的游泳者可以从银松森林的岸边或Undercity的郊区向东南横跨洛丹米尔湖。",al={"如何前往奥特兰克","奥特兰克入口","通往奥特兰克的道路"}}},fp="27,359,20.533.0,24.503.0,40.308.0,47.304.0,50.280.0,35.283.0"}
P.entries["subzone:alther-s-mill"] = {n="奥瑟尔伐木场",s="奥瑟尔伐木场是一座破败的伐木场，坐落在赤脊山中，位于湖畔镇东北方向崎岖的山丘之间。这里曾是当地建筑商极为重要的木材来源，但在被废弃后，这里已沦为各种野兽和掠食者的巢穴。对于前往石堡方向的冒险者来说，这些破旧的建筑是标志着安全边境终点的阴森地标。",h="奥瑟尔伐木场是一座破败的伐木场，坐落在赤脊山中，位于湖畔镇东北方向崎岖的山丘之间。这里曾是当地建筑商极为重要的木材来源，但在被废弃后，这里已沦为各种野兽和掠食者的巢穴。对于前往石堡方向的冒险者来说，这些破旧的建筑是标志着...",kw={"奥瑟尔伐木场","湖畔镇","开锁","伐木场","赤脊山","蜘蛛","石堡"},ang={["class:Rogue"]="联盟的恶棍们很熟悉奥瑟尔伐木场，因为盗贼组织将伐木场里散落的遗忘储物箱和偏僻的场地当作静谧的训练场，用来练习精细的开锁技术。",["faction:Alliance"]="这座废弃的伐木场是暴风城边境驻军捉襟见肘的又一个鲜明写照，宝贵的工业设施就这样在湖畔镇的眼皮底下破败荒废。"},sec={{t="一座被遗弃的边境伐木场",b="在赤脊山遭到掠食者入侵和兽人袭击之前，奥瑟尔伐木场曾因木材贸易而熙熙攘攘，为湖畔镇及周边定居点的建设提供了充足的原材料。它坐落在止水湖东北方向一片安静的林地中，便于就近获取山区的木材资源。随着暴风城王国内动荡加剧，黑石氏族从石堡高地南下，当地的伐木工被迫放弃了这里，任由干枯的木质建筑和水车逐渐腐朽。"},{t="阴影与残骸",b="随着人类工人的离去，伐木场里开始滋生巨大的狼蛛、食腐秃鹫和投机取巧的掠夺者。穿越这里前往东部山口的旅人必须小心翼翼地绕开它那阴暗的边缘。近年来，一些暗影中的不法分子和小偷也利用这座废弃的营地，将废弃的储物箱和隐蔽的角落作为练习非法开锁技巧和秘密交易的场所，以此避开湖畔镇守卫的耳目。"}},faq={{q="什么是奥瑟尔伐木场？",a="奥瑟尔伐木场是一座位于赤脊山，湖畔镇东北方向的废弃伐木场。它曾为周边定居点砍伐和加工木材，直到日益严重的野外威胁迫使其被废弃。",al={"奥瑟尔伐木场","这是什么地方","奥瑟尔伐木场过去是什么"}},{q="为什么伐木场会被废弃？",a="随着第一次和第二次战争后区域防御力量的减弱，巨大的蜘蛛等凶猛野兽以及黑石兽人的入侵，使得边境作业对于普通劳工而言变得过于危险，如果没有皇家军队的保护已无法维持。",al={"为什么被废弃","谁废弃了奥瑟尔伐木场","伐木工发生了什么"}},{q="什么生物会在伐木场附近徘徊？",a="伐木场地面及周围的灌木丛中主要盘踞着巨大的山地狼蛛、食腐秃鹫和游荡的掠食者，还有在石堡和止水湖之间往来的流窜强盗。",al={"奥瑟尔伐木场的敌人","伐木场的生物","这里有什么生物"}},{q="为什么潜行者要来奥瑟尔伐木场？",a="这里偏僻且堆满杂物的环境使其成为联盟潜行者理想的练习场，他们的训练师会指引他们到这里练习开启锁住的步兵箱，并获取宝贵的盗贼认证。",al={"潜行者伐木场任务","奥瑟尔伐木场开锁","盗贼认证"}}},fp="13,251,26.356.0,17.390.0,22.192.0,26.207.0,36.182.0,34.181.0"}
P.entries["subzone:ambermill"] = {n="安伯米尔",s="安伯米尔是位于银松森林东南部的一座加固人类定居点，坐落在洛丹米尔湖的西南方。这里曾经是一个安静的伐木村庄，如今被达拉然的幸存法师和学徒占据。他们的存在构成了被遗忘者疆域南部边境上一个危险的人类反抗前哨。",h="安伯米尔是位于银松森林东南部的一座加固人类定居点，坐落在洛丹米尔湖的西南方。这里曾经是一个安静的伐木村庄，如今被达拉然的幸存法师和学徒占据。他们的存在构成了被遗忘者疆域南部边境上一个危险的人类反抗前哨。",kw={"安伯米尔","达拉然","肯瑞托","魔网","暗影牧师奥利斯特","银松森林"},ang={["class:Mage"]="这个定居点证明了肯瑞托在天灾军团和燃烧军团摧毁达拉然之后，试图恢复其影响力的努力。",["faction:Horde"]="对于被遗忘者的特工来说，安伯米尔是银松森林中仅存的少数人类反抗据点之一，它威胁着南部的后勤补给，并藏有危险的奥术秘密。"},sec={{t="达拉然的堡垒",b="第三次战争前，安伯米尔只是一个无足轻重的安静伐木小镇。在洛丹伦陷落后的混乱时期，肯瑞托的幸存法师们迁入并加固了该定居点。达拉然的法术抄写员、咒术师和学徒们如今巡视着这里的建筑和马厩，将安伯米尔用作对抗亡灵的前沿堡垒。"},{t="汲取魔网能量",b="肯瑞托对安伯米尔的兴趣远不止于简单的领土防御。这个村庄直接坐落在一个休眠的魔网能量节点之上。监视该镇的被遗忘者间谍和死亡猎手发现，达拉然的法师们正试图重新激活这个枢纽，以进行大规模的奥术工作。如果成功，涌动的魔法力量可能会威胁到被遗忘者对银松森林那脆弱的控制，从而促使暗影牧师奥利斯特和死亡猎手们在磨坊各处策划破坏活动、窃取肯瑞托文件并执行暗杀行动。"}},faq={{q="为什么达拉然的法师要占据银松森林的一个村庄？",a="在第三次战争中达拉然遭到毁灭后，幸存的肯瑞托部队迁入安伯米尔，建立了一个人类反抗军的前哨。被遗忘者的特工们正在调查他们的活动。",al={"为什么法师在这里","谁控制着安伯米尔","肯瑞托 银松森林"}},{q="安伯米尔一直是达拉然的一部分吗？",a="不。在第三次战争前，安伯米尔只是一个微不足道的伐木村庄。达拉然的法师是在天灾军团攻陷洛丹伦之后才迁入并将其加固的。",al={"安伯米尔历史","谁拥有安伯米尔"}},{q="为什么被遗忘者想要攻击安伯米尔？",a="安伯米尔是银松森林中一个加固的人类反抗中心。被遗忘者将这里得到达拉然支持的部队及其秘密奥术工作视为对自己该地区统治的威胁。",al={"被遗忘者 安伯米尔","为什么要杀掉安伯米尔的法师"}},{q="死亡猎手在安伯米尔搜寻什么？",a="被遗忘者的死亡猎手从俘虏的人类囚犯口中得知，安伯米尔的法师们保存着详细记录达拉然秘密计划和军事意图的机密文件，这使得该定居点成为了秘密渗透和窃取行动的首要目标。",al={"安伯米尔文件","mennet carkad 安伯米尔"}}},fp="9,251,20.287.0,21.485.1,58.202.0,37.149.0,45.182.0,54.237.0"}
P.entries["subzone:amberstill-ranch"] = {n="冻石农场",s="冻石农场是一处宁静的矮人宅邸，坐落在通往洛克莫丹的雪道旁，位于古博拉采掘场的正北方。这里是铁炉堡著名的山羊的主要繁育与训练基地。冒险者们来到农场购买坚韧的矮人坐骑、学习骑术，或是帮助这个家庭保护它们的牲畜免受当地掠食者的侵害。",h="冻石农场是一处宁静的矮人宅邸，坐落在通往洛克莫丹的雪道旁，位于古博拉采掘场的正北方。这里是铁炉堡著名的山羊的主要繁育与训练基地。冒险者们来到农场购买坚韧的矮人坐骑、学习骑术，或是帮助这个家庭保护它们的牲畜免受当地掠食者的...",kw={"冻石","坐骑商人","山羊","农场","骑术训练师","雪靴兔","瓦加什","雅琳"},ang={["faction:Alliance"]="冻石家族培育出的强壮山羊为联盟提供了可靠的寒带骑兵，非常适合在崎岖的山地地形中作战。",["race:Dwarf"]="对于矮人冒险者来说，这里是一个值得骄傲的文化基石，年轻的英雄们可以在此获得他们的第一只巴拉克·托尔山羊坐骑。"},sec={{t="山羊的家园",b="冻石农场坐落于丹莫罗的岩架旁，因培育出东部王国中最强壮的山羊而在卡兹莫丹享有盛誉。冻石家族经营着这里的马厩和围场，训练这些步履稳健的野兽在险峻的雪道和陡峭的高山悬崖上穿行。除了提供骑乘坐骑和家养牲畜外，这个家族还经常要应对山丘中凶猛的野兽，尤其是被新鲜兽群的气味吸引而来的游荡温迪戈。"}},faq={{q="冻石农场因何出名？",a="该农场是联盟繁育巴拉克·托尔山羊的中心枢纽。矮人和受人尊敬的联盟勇士来到这里，学习山羊骑术并向当地的马厩管理员购买坐骑。",al={"冻石农场用途","为什么访问冻石农场","冻石山羊"}},{q="非矮人种族可以在这里购买坐骑吗？",a="按照传统，山羊是专门为那些了解其固执脾性的矮人骑手准备的。其他联盟种族的成员只有在赢得了铁炉堡的绝对信任并获得崇拜声望后，才能学习骑术并购买它们。",al={"非矮人购买山羊","人类购买山羊","山羊坐骑要求"}},{q="农场面临哪些威胁？",a="兽群不断受到从冰冻悬崖上下来的饥饿温迪戈的威胁。在周边高地徘徊的最臭名昭著的掠食者是瓦加什，这是一只经常袭击脆弱牲畜的巨大温迪戈。",al={"冻石农场危险","温迪戈威胁","瓦加什任务"}},{q="在农场还能获得其他东西吗？",a="年轻的雅琳·冻石饲养了一群家养雪靴兔，并乐意将装在笼子里的兔子卖给那些在旅途中寻找宠物伙伴的旅行者。",al={"冻石兔子","雪靴兔宠物","雅琳·冻石"}}},fp="16,171,25.325.0,35.172.0,37.200.0,33.184.0,42.127.0"}
P.entries["subzone:ameth-aran"] = {n="亚米萨兰",s="亚米萨兰是黑海岸南部的一处古代遗迹，曾经是一座繁荣的城市，艾萨拉女王的在上层精灵在这里研习奥术魔法。当大分裂摧毁了古代世界时，这座城市也随之覆灭。如今，其残破的柱廊徘徊着在此丧生的精灵的复仇之魂。",h="亚米萨兰是黑海岸南部的一处古代遗迹，曾经是一座繁荣的城市，艾萨拉女王的在上层精灵在这里研习奥术魔法。当大分裂摧毁了古代世界时，这座城市也随之覆灭。如今，其残破的柱廊徘徊着在此丧生的精灵的复仇之魂。",kw={"亚米萨兰","阿奈雅·晨行者","阿斯利库斯·纳拉辛","巴莎兰","塞瑞利恩·白爪","黑海岸","上层精灵","坦莎·月刃"},ang={["class:Druid"]="德鲁伊将这些遗迹视为黑海岸上一道未愈合的伤疤，折磨的灵魂滞留于此，扰乱了荒野的自然平衡。",["race:NightElf"]="对于暗夜精灵来说，亚米萨兰是导致大分裂的上层精灵阶级的傲慢与背叛的冷酷纪念碑。"},sec={{t="法师之城",b="在大分裂之前，亚米萨兰及其姊妹定居点巴莎兰是古代海岸线上上层精灵影响力的双子中心。在艾萨拉女王的恩宠下，统治阶级致力于毫无节制的奥术实验。这座城市在奥萨拉克斯之塔的法师阿斯利库斯·纳拉辛的遥控下繁荣发展，直到永恒之井灾难性的崩塌撕裂了卡多雷帝国。"},{t="背叛与永恒的折磨",b="当世界开始分崩离析时，阿斯利库斯·纳拉辛回到了亚米萨兰，承诺用强大的护盾魔法拯救惊恐的臣民。然而法师并没有保护他们，反而实施了可怕的背叛，以赋予他们永恒保存为残酷幌子，窃取了他们的生命力来供养自己的灵魂宝石。亚米萨兰因大灾变和黑暗魔法而破碎。如今，它的土地上游荡着痛苦的上层精灵幽灵，在他们被谋杀的一万年后仍无法安息。"}},faq={{q="亚米萨兰发生了什么？",a="亚米萨兰在卡多雷帝国的最后日子里就已经是一片废墟，它在一万年前的大分裂中，随着永恒之井的破碎而被摧毁。遗迹中至今徘徊着在此丧生的上层精灵的灵魂。",al={"亚米萨兰为何成为废墟","亚米萨兰历史","亚米萨兰的陷落"}},{q="游荡在遗迹里的幽灵是谁？",a="它们是在大分裂前居住在这座城市并研习奥术魔法的上层精灵的躁动灵魂。由于无法安息，它们在痛苦和愤怒中徘徊在破碎的石块之间。",al={"亚米萨兰的幽灵","亚米萨兰的亡魂","黑海岸的上层精灵幽灵"}},{q="阿奈雅·晨行者是谁？",a="阿奈雅·晨行者是亚米萨兰的居民，也是塞瑞利恩·白爪的爱人。她在分裂期间城市陷落时丧生，她的灵魂一直被束缚在遗迹中，直到塞瑞利恩寻求外援最终让她的灵魂得到解脱。",al={"阿奈雅·晨行者","塞瑞利恩的爱人","亚米萨兰的迷失之爱"}},{q="遗迹中发现的石板是什么？",a="遗迹中刻有记载亚米萨兰历史及其陷落经过的古代石板。哨兵坦莎·月刃曾试图解读它们以便向塞纳里奥议会提交一份历史报告，但敌对的幽灵迫使她只能依靠过往的旅行者。",al={"亚米萨兰石板","亚米萨兰的符文石","亚米萨兰陷落的石板"}}},fp="10,278,19.423.0,28.440.1,28.239.0,39.192.0,25.224.1,46.242.0"}
P.entries["subzone:andorhal"] = {n="Andorhal",s="Andorhal曾经是洛丹伦北部繁荣的农业中心，在第三次战争期间，它成为了王国毁灭的中心。克尔苏加德正是在这里用亡灵瘟疫污染了谷物，将恐怖散布到了整个地区。如今，这座破败的城镇仍牢牢地掌握在天灾军团的铁腕统治之下。",h="Andorhal曾经是洛丹伦北部繁荣的农业中心，在第三次战争期间，它成为了王国毁灭的中心。克尔苏加德正是在这里用亡灵瘟疫污染了谷物，将恐怖散布到了整个地区。如今，这座破败的城镇仍牢牢地掌握在天灾军团的铁腕统治之下。",kw={"andorhal","谷物","粮仓","克尔苏加德","瘟疫之地","天灾军团","乌瑟尔"},ang={["class:Paladin"]="Andorhal是一片被白银之手鲜血浸染的神圣土地；乌瑟尔·光明使者和他的忠诚骑士们正是在这里对阿尔萨斯进行了悲剧性的最后抵抗。",["race:Undead"]="对于被遗忘者来说，Andorhal的田野是对他们起源的痛苦提醒，这里标志着The Cult of the Damned策划终结他们凡人生命的地方。"},sec={{t="瘟疫的中心",b="在第三次战争之前，Andorhal是东威尔德繁荣的粮仓，它收集来自整个洛丹伦的谷物，并将其向东分发到壁炉谷和斯坦索姆。正是因为这种庞大的分销网络，克尔苏加德和The Cult of the Damned选择了Andorhal作为他们恐怖阴谋的舞台。通过用亡灵瘟疫污染谷物箱，教派将王国的粮仓变成了坏死的引擎，在王室意识到威胁之前，无数公民就已经被感染了。"},{t="白银之手的覆灭",b="阿尔萨斯·米奈希尔王子和Jaina Proudmoore最初在这里对抗并杀死了克尔苏加德，但这名通灵师的死亡并非终点。当阿尔萨斯作为天灾军团的勇士从诺森德归来时，他进军回到Andorhal夺回了克尔苏加德的遗骸。乌瑟尔·光明使者和白银之手的残部为了保卫泰瑞纳斯国王的骨灰盒，进行了绝望的最后抵抗。圣骑士们被击溃，乌瑟尔被他曾经的学生杀害，这座伟大的定居点也沦为了一片被枯萎病笼罩的天灾据点。"}},faq={{q="为什么Andorhal在瘟疫的历史中如此重要？",a="Andorhal是洛丹伦北部主要的农业分销枢纽。克尔苏加德利用了这条供应链，用亡灵瘟疫侵染了粮仓，并将受到污染的收成沿着国王之路直接运往斯坦索姆和周边城镇。",al={"瘟疫是如何在这里开始的","安多哈尔谷物瘟疫","为什么andorhal很重要"}},{q="现在是谁控制着Andorhal？",a="不死的天灾军团牢牢控制着安多哈尔废墟。骷髅哨兵、通灵师和食尸鬼在焦黑的街道上游荡，守卫着他们在西瘟疫之地最初胜利的震中。",al={"谁统治着andorhal","andorhal的天灾军团","谁负责andorhal"}},{q="乌瑟尔·光明使者死在这里吗？",a="是的。在洛丹伦王城陷落后，乌瑟尔和他的圣骑士们在Andorhal郊外保护着装有泰瑞纳斯国王骨灰的瓮。阿尔萨斯袭击了护送队伍以夺取骨灰瓮来存放克尔苏加德的遗骸，最终在路上与他的导师决斗并将其杀害。",al={"乌瑟尔在哪里去世","乌瑟尔在andorhal的死亡","阿尔萨斯在这里杀了乌瑟尔吗"}}},fp="8,321,25.521.0,27.529.0,53.272.0,32.206.0,36.273.0"}
P.entries["subzone:angerfang-encampment"] = {n="怒牙营地",s="怒牙营地是龙喉氏族在湿地中部的主要据点。在酋长纳克罗什·碎颅的领导下，这些叛乱的兽人将这座庞大的营地作为进攻基地，以此威胁附近的矮人定居点，并策划摧毁米奈希尔港。",h="怒牙营地是龙喉氏族在湿地中部的主要据点。在酋长纳克罗什·碎颅的领导下，这些叛乱的兽人将这座庞大的营地作为进攻基地，以此威胁附近的矮人定居点，并策划摧毁米奈希尔港。",kw={"怒牙营地","龙喉氏族","米奈希尔港","纳克罗什","碎颅","斯托菲","湿地","维尔加"},ang={["class:Warlock"]="营地内的黑暗影卫携带着导能魔棒，这是完成《卡巴尔法典》所记载的契约所必需的器物。",["faction:Alliance"]="对于米奈希尔港的守卫者而言，怒牙营地是一个明显且迫在眉睫的威胁；摧毁纳克罗什的战旗并取下他的头颅，对于保卫沿海贸易路线至关重要。"},sec={{t="沼泽中的堡垒",b="怒牙营地坐落在湿地中部的泥沼之中，是龙喉氏族在该地区势力的堡垒核心。与那些在沼泽中游荡的零散劫掠小队不同，这个营地拥有防御严密的栅栏、岗哨，以及一支由战士、白骨卫士和效忠旧传统的黑暗施法者组成的强大军队。从这里开始，龙喉氏族向整个沼泽地投射军事力量，沿路劫掠旅行者，并威胁附近的矮人挖掘场，如维尔加挖掘场。"},{t="纳克罗什的野心",b="该营地由酋长纳克罗什·碎颅指挥，他是臭名昭著的术士耐克鲁斯之子，后者曾于格瑞姆巴托奴役了红龙军团。纳克罗什怀着对联盟的刻骨仇恨，集结了投石车并竖起了战旗，准备对米奈希尔港发动全面进攻。联盟在港口城市的指挥官察觉到了这场迫在眉睫的围攻，派遣勇士深入怒牙营地内部，夺取他们的战旗，摧毁他们的战争机器，并取得纳克罗什的头颅，以防他的攻势将港口淹没在火海之中。"}},faq={{q="谁统治着怒牙营地？",a="该营地由酋长纳克罗什·碎颅统治，他是臭名昭著的龙喉氏族术士耐克鲁斯·碎颅之子。纳克罗什在营地深处的指挥帐篷内指挥着区域性的劫掠小队，并策划着对米奈希尔港的征服。",al={"谁领导怒牙营地","怒牙营地首领","这里由谁负责","纳克罗什营地"}},{q="这里的兽人是萨尔部落的盟友吗？",a="不是。这里的龙喉氏族仍然独立于萨尔的新部落之外。他们坚守着旧部落的黑暗传统，对联盟和部落的旅行者都保持敌意。萨尔的战士视他们为野蛮的弃民，甚至为了获取护甲制造材料而猎杀他们。",al={"龙喉氏族属于部落吗","怒牙营地对部落友好吗","怒牙营地是萨尔部落的一部分吗"}},{q="为什么联盟致力于摧毁这个营地？",a="斯托菲队长和米奈希尔港的矮人守卫发现，纳克罗什已经在怒牙营地集结了投石车和庞大的部队，准备轰炸并征服港口。联盟采取先发制人的攻击，在围攻开始前将其粉碎。",al={"为什么要攻击怒牙营地","斯托菲队长怒牙营地","为什么要杀死纳克罗什"}},{q="为什么术士要寻找这个营地？",a="怒牙营地的龙喉氏族中的黑暗施法者携带着导能魔棒，这是那些寻求完成《卡巴尔法典》的恶魔术法修行者们梦寐以求的黑暗仪式器具。",al={"怒牙营地术士任务","湿地卡巴尔法典","怒牙营地导能魔棒"}}},fp="20,205,21.339.0,19.441.1,35.215.0,45.263.0,52.232.0,41.172.0"}
P.entries["subzone:anvilmar"] = {n="安威玛尔",s="安威玛尔是位于丹莫罗寒脊山谷积雪深处的一处坚固的矮人前哨站。它以一座巨大的石制熔炉为中心，是年轻的铜须矮人和流离失所的侏儒难民开始冒险时的主要训练场和集结点。",h="安威玛尔是位于丹莫罗寒脊山谷积雪深处的一处坚固的矮人前哨站。它以一座巨大的石制熔炉为中心，是年轻的铜须矮人和流离失所的侏儒难民开始冒险时的主要训练场和集结点。",kw={"安威玛尔","寒脊山谷","丹莫罗","熔炉","霜鬃","莫迪姆斯·安威玛尔","新手区域"},ang={["race:Dwarf"]="对于矮人来说，安威玛尔代表着踏入世界之旅的开始，它可能承载着曾经统治过统一矮人王国的古代至高王的名字。",["race:Gnome"]="在诺莫瑞根陷落后在此避难的侏儒们，找到了坚毅的矮人盟友、温暖的炉火以及准备帮助他们适应冰封荒野的导师。"},sec={{t="寒脊的炉火",b="安威玛尔坐落在寒脊山谷北部的峭壁之中，是矮人坚韧不拔的象征。这座坚固的石砌建筑群以一座轰鸣的中央熔炉为核心，驻扎着职业训练师、补给商人和经验丰富的山地登山队员，他们在将新兵派往更广阔的王国之前会对其进行训练。尽管被高耸的雪堆所庇护，该定居点依然时刻警惕着敌对的霜鬃巨魔和在冰封山谷中徘徊的凶猛野兽。"},{t="铁与巨魔的传承",b="这个定居点的名字很可能取自至高王莫迪姆斯·安威玛尔，这位古代君主曾在三锤之战前统治着所有的矮人氏族。如今，这里的驻军依然保持警惕，确保熔炉之火长明，以抵御山谷中的巨魔和野兽。"}},faq={{q="安威玛尔是什么？",a="安威玛尔是位于丹莫罗寒脊山谷北部的一处矮人据点和定居点。它是新招募的矮人和侏儒冒险家最初的集结地和训练中心。",al={"什么是安威玛尔","安威玛尔位置","安威玛尔概况"}},{q="它为什么叫安威玛尔？",a="该前哨站可能以至高王莫迪姆斯·安威玛尔或安威玛尔血统命名。莫迪姆斯在三锤之战前统治着矮人氏族，但该定居点的命名并未得到证实。",al={"安威玛尔是谁","安威玛尔名字来源","名字含义"}},{q="安威玛尔面临什么威胁？",a="该前哨站面临着盘踞在寒脊山谷峭壁上的土著霜鬃巨魔，以及狼群和温迪戈等危险的当地野生动物带来的持续威胁。",al={"安威玛尔敌人","谁攻击安威玛尔","安威玛尔面临的威胁"}},{q="可以在这里学习专业技能吗？",a="虽然安威玛尔拥有一座适合锻造和熔炼的轰鸣熔炉，但这里并没有常驻的专业技能训练师。年轻的新兵必须深入丹莫罗，前往卡拉诺斯或铁炉堡等地，才能正式学习制作技艺。",al={"安威玛尔的专业技能","安威玛尔熔炉","安威玛尔锻造"}}},fp="8,189,23.363.0,27.219.0,17.151.0,25.178.0,32.114.0,31.167.0"}
P.entries["subzone:apothecarium"] = {n="Apothecarium",s="Apothecarium是幽暗城的西南区，也是皇家药剂师学会的总部。在这些充满毒气的实验室中，被遗忘者炼金术士在大药剂师法拉尼尔的领导下不知疲倦地工作，调制致命的瘟疫、毒素和人造恐怖生物。这里是幽暗城生物研究的黑暗核心，对于希尔瓦娜斯女士针对生者与天灾军团的战役至关重要。",h="Apothecarium是幽暗城的西南区，也是皇家药剂师学会的总部。在这些充满毒气的实验室中，被遗忘者炼金术士在大药剂师法拉尼尔的领导下不知疲倦地工作，调制致命的瘟疫、毒素和人造恐怖生物。这里是幽暗城生物研究的黑暗核心，...",kw={"憎恶","炼金术","apothecarium","法拉尼尔","新瘟疫","皇家药剂师学会","希尔瓦娜斯","幽暗城"},ang={["profession:Herbalism"]="植物学家为皇家药剂师学会的邪恶蒸馏师提供从北部王国废墟中收集的稀有枯萎植物。",["race:Undead"]="对于被遗忘者来说，Apothecarium是他们生存的熔炉，生产着在洛丹伦抵御压倒性强敌所必需的化学武器和缝合武器。"},sec={{t="恐怖之室",b="Apothecarium位于这座地下首都的西南平台，是一座布满冒泡大锅、解剖台和刺鼻化学烟雾的迷宫。在大药剂师法拉尼尔的领导下，皇家药剂师学会利用该区来加深他们对死亡和腐朽的理解。在这里，炼金术士和外科医生进行组织移植、活体解剖和制造强大的憎恶的实验。在希尔瓦娜斯·风行者女士的授意下，他们的最高目标是研制出一种能够彻底根除洛丹伦大陆上残余的天灾军团和人类的全新瘟疫。"},{t="被遗忘者炼金术中心",b="除了宏大的军事野心外，该区还是东部王国部落进行实用炼金术和草药学的首要中心。无论是学徒还是大师，都会聚集在有毒的运河边蒸馏药剂、研究植物枯萎病，并向资深从业者请教。"}},faq={{q="Apothecarium的用途是什么？",a="Apothecarium是皇家药剂师学会的研究和制造部门。在这里，被遗忘者炼金术士酿造实验性毒药、精炼The New Plague、制造憎恶，并教授从业者炼金术和草药学。",al={"apothecarium的用途","这里发生了什么","为什么会有apothecarium"}},{q="谁领导着Apothecarium？",a="该区及其研究人员由大药剂师法拉尼尔领导，他是皇家药剂师学会的首席科学家，在希尔瓦娜斯·风行者女王的全力授权和支持下运作。",al={"apothecarium领导者","谁在管理apothecarium","法拉尼尔 幽暗城"}},{q="皇家药剂师学会试图创造什么？",a="他们的主要努力是培育一种致命的The New Plague，旨在彻底消灭巫妖王的天灾军团以及在洛丹伦境内挑战被遗忘者领土的任何人类抵抗力量。",al={"被遗忘者瘟疫研究","新瘟疫 幽暗城","他们正在酿造什么"}},{q="玩家可以在这里学习专业技能吗？",a="是的。该区是首都炼金术士和草药学家的主要枢纽，沿途的步道和房间里都有高级专业训练师。",al={"apothecarium训练师","幽暗城的炼金术","幽暗城草药学训练师"}}},fp="12,270,18.474.0,26.232.0,34.215.0,27.196.0,54.197.0,35.145.0"}
P.entries["subzone:ariden-s-camp"] = {n="埃瑞丁营地",s="埃瑞丁营地是一处废弃的营地，坐落在穿过逆风小径的小路北侧。它在卡拉赞的阴影中逐渐腐朽，在荒凉的峡谷风声中显得怪异而安静，格格不入。往返于暮色森林和悲伤沼泽的旅人经过这里时往往感到不安，不禁猜测是谁曾经在此扎营。",h="埃瑞丁营地是一处废弃的营地，坐落在穿过逆风小径的小路北侧。它在卡拉赞的阴影中逐渐腐朽，在荒凉的峡谷风声中显得怪异而安静，格格不入。往返于暮色森林和悲伤沼泽的旅人经过这里时往往感到不安，不禁猜测是谁曾经在此扎营。",kw={"埃瑞丁","埃瑞丁营地","逆风小径","暮色森林","卡拉赞","麦迪文","悲伤沼泽"},ang={["class:Mage"]="对于奥术学者来说，这座荒废的营地令人不安地提醒着人们卡拉赞是多么近在咫尺；很少有人能在麦迪文的塔楼附近久留。",["class:Rogue"]="有人在东部王国最恐怖的尖塔下扎营，却再也没有回来取走他们的物品。要么是极其野心勃勃，要么是愚不可及。"},sec={{t="静谧的营地",b="这个破败的营地紧挨着连接暮色森林与悲伤沼泽的峡谷道路北侧的岩壁，看起来就像一个被凡人长久遗弃的普通中转站。然而，在逆风小径压抑的阴霾中，没有任何事物能不被黑暗魔法所侵蚀。无论谁将这里命名为埃瑞丁营地，也无论其主人在卡拉赞周边寻求怎样的财富，这条路径上挥之不去的恐怖早已将其吞噬，只留下风化的布匹、冰冷的灰烬，以及一段永久的谜团。"}},faq={{q="埃瑞丁营地在哪里？",a="埃瑞丁营地位于逆风小径，坐落在连接西侧暮色森林和东侧悲伤沼泽的主路北侧，距离卡拉赞不远。",al={"埃瑞丁营地位置","埃瑞丁营地在哪里","逆风小径营地"}},{q="营地现在有任何活跃的威胁吗？",a="营地所在的空地此刻十分安静，显得诡异而寂静，尽管逆风小径本身潜伏着致命的逆风食人魔、幽灵幻象，以及在卡拉赞附近筑巢的邪恶飞禽。",al={"埃瑞丁营地危险吗","埃瑞丁营地的怪物"}}},fp="13,335,19.475.0,31.171.0,51.201.0"}
P.entries["subzone:astranaar"] = {n="阿斯特兰纳",s="阿斯特兰纳是位于灰谷中部的主要暗夜精灵定居点，它坐落于一座宁静的湖心岛上，横跨了古老的林间道路。作为联盟在该地区行动的核心，它为面对来自充满敌意的熊怪、萨特以及部落威胁的旅行者们提供了重要的庇护所。",h="阿斯特兰纳是位于灰谷中部的主要暗夜精灵定居点，它坐落于一座宁静的湖心岛上，横跨了古老的林间道路。作为联盟在该地区行动的核心，它为面对来自充满敌意的熊怪、萨特以及部落威胁的旅行者们提供了重要的庇护所。",kw={"灰谷","阿斯特兰纳","卡利姆多","暗夜精灵","莱恩·狼行者","哨兵","刺鬃熊怪"},ang={["faction:Alliance"]="阿斯特兰纳是联盟在灰谷充满争端的荒野中行动时的指挥所和主要后勤枢纽。",["race:NightElf"]="对于卡多雷来说，阿斯特兰纳是他们位于卡利姆多中部古老家园的核心堡垒，保护着神圣的林地免受森林中日益增长的威胁。"},sec={{t="森林之心",b="阿斯特兰纳坐落在森林湖泊中央的一座岛屿上，是灰谷中最大的暗夜精灵定居点。通过横跨水面的木制人行桥与陆地相连，这座城镇居住着守卫林地的哨兵、牧师和工匠。除了提供旅店、商人和专家级制皮师等基本便利设施外，它高耸的平台还设有一位飞行管理员，提供前往卡利姆多各地前哨站的角鹰兽交通服务。"},{t="受围困的堡垒",b="尽管这里水波宁静、灯火阑珊，但阿斯特兰纳始终处于随时备战的状态。莱恩·狼行者等当地领袖协调着巡逻和防御行动，以应对从北方入侵、遭到腐蚀的刺鬃熊怪，他们担心这些熊怪可能会对定居点发起直接突袭。"}},faq={{q="阿斯特兰纳提供什么服务？",a="阿斯特兰纳为联盟旅行者提供全套便利设施，包括旅店、杂货商、专家级制皮训练师，以及连接灰谷和卡利姆多各地关键前哨站的飞行管理员。",al={"阿斯特兰纳便利设施","阿斯特兰纳有什么","阿斯特兰纳飞行管理员"}},{q="湖对岸的墓地里埋葬着谁？",a="这个时代的记载中没有提到谁安息在那里。墓地位于城镇对面的湖畔，墓碑深藏着它们秘密。",al={"阿斯特兰纳墓地","瓦斯坦·鹿盔之墓","谁葬在这里"}},{q="为什么阿斯特兰纳的哨兵对当地的熊怪感到担忧？",a="北方的刺鬃熊怪受到了黑暗与腐蚀力量的影响。哨兵莱恩·狼行者担心，如果不加以遏制，它们日益增长的侵略性将助长它们对阿斯特兰纳本身发起公开袭击的野心。",al={"刺鬃熊怪威胁","为什么要对抗熊怪","莱恩·狼行者任务"}},{q="部落玩家可以安全地访问阿斯特兰纳吗？",a="不能。阿斯特兰纳是一个防御森严的联盟据点，由全副武装的暗夜精灵哨兵守卫，他们会攻击视线范围内的部落成员。",al={"阿斯特兰纳对部落友好吗","部落在阿斯特兰纳"}}},fp="9,237,19.362.0,21.287.0,41.157.0,47.119.0,68.175.0,41.114.0"}
P.entries["subzone:auberdine"] = {n="奥伯丁",s="奥伯丁是一座位于黑海岸阴沉海岸线上的暗夜精灵沿海港口城镇，它是联盟在卡利姆多北部的主要海上门户。在阴云密布的天空和松树覆盖的峭壁之下，它连接着泰达希尔的岛屿家园与东部王国，同时作为抵御蔓延荒野的行政避难所。",h="奥伯丁是一座位于黑海岸阴沉海岸线上的暗夜精灵沿海港口城镇，它是联盟在卡利姆多北部的主要海上门户。在阴云密布的天空和松树覆盖的峭壁之下，它连接着泰达希尔的岛屿家园与东部王国，同时作为抵御蔓延荒野的行政避难所。",kw={"奥伯丁","船","黑海岸","码头","卡多雷","灯塔","港口","哨兵","桑德里斯·风歌"},ang={["faction:Alliance"]="这座港口是联盟向卡利姆多北部进行旅行和补给的命脉，确保了暴风城、铁炉堡和达纳苏斯之间物流的稳定。",["race:NightElf"]="对于从泰达希尔出发的卡多雷来说，奥伯丁是第一个真正意义上的大陆枢纽，古老的传统在这里与年轻联盟盟友那奇特的习俗和繁忙的工业相遇。"},sec={{t="通往卡利姆多北部的门户",b="奥伯丁坐落在无尽之海的海岸边，是现代黑海岸唯一成功存续下来的大型定居点。与泰达希尔那些隐世的树顶城市不同，奥伯丁面向外界，是联盟在北方最繁忙的港口。往返于此和东部王国的常规航线连接着暴风城港口，并经由南海镇通往米奈希尔港，而当地的渡轮则通往世界之树下的鲁瑟兰村。由于其贸易地位，奥伯丁比传统的精灵飞地有着更浓郁的多元文化气息；游客们会发现，灯火照亮了铺石的街道，外来商人们（包括矮人和侏儒）穿梭在低矮的拱形木屋之间。"},{t="备受困扰的避难所",b="在长者桑德里斯·风歌和奥伯丁村议会的治理下，该镇与当地的哨兵共同协调黑海岸的防御工作。尽管这里是重要的贸易枢纽，但达纳苏斯的枝头却很少提及奥伯丁的名字，因为那里的记忆还沉浸在天崩地裂中逝去的大城市中。该镇长期忍受着严重的区域性威胁：好战的鱼人在海岸线上袭击渔船，腐化的黑木熊怪从南方压境，而从费伍德森林渗出的邪恶魔法更是骚扰着当地的野生生物。"}},faq={{q="奥伯丁的船只去往何处？",a="这里的码头连接着卡利姆多北部与更广阔的联盟世界。一个码头停靠着通往泰达希尔之基——鲁瑟兰村的渡轮，而其他码头则停靠着横跨无尽之海、前往暴风城港口的大型远洋船只，并经由希尔斯布莱德丘陵的南海镇，前往湿地的米奈希尔港。",al={"奥伯丁船只","船只去向","奥伯丁交通"}},{q="谁统治着奥伯丁？",a="奥伯丁由长者桑德里斯·风歌与奥伯丁村议会共同管理。该定居点的防御由哨兵部队负责，当地的指挥官是哨兵戈琳达·纳希恩。",al={"奥伯丁领导人","谁在负责","村议会"}},{q="为什么会有矮人和人类居住在暗夜精灵的城镇里？",a="因为奥伯丁是联盟在卡利姆多北部的核心港口，外国商人、工匠和旅行者首先抵达这里。矮人们建立了一座当地的铁匠铺，为往来的船只和旅客提供服务，这使得该镇与传统的暗夜精灵定居点相比，显得异常多元且热情。",al={"奥伯丁的非精灵族裔","为什么这里有矮人"}},{q="为什么达纳苏斯的暗夜精灵看不起奥伯丁？",a="桑德里斯·风歌称奥伯丁是一个谦卑的地方，其名字从不被达纳苏斯的枝头提及。大多数卡多雷只记得天崩地裂所夺走的东西，即亚米萨兰和巴莎兰的繁荣，而奥伯丁至今仍笼罩在它们的阴影之下。",al={"达纳苏斯与奥伯丁的隔阂","奥伯丁被遗忘者"}}},fp="9,213,28.448.0,19.484.0,35.294.0,20.153.0,60.262.0,57.250.0"}
P.entries["subzone:azurelode-mine"] = {n="碧玉矿洞",s="碧玉矿洞是一座由联盟运作的活跃铁矿，坐落在希尔斯布莱德丘陵的西南山丘中。矿洞由南海镇的民兵把守，并由人类劳工开采。这里源源不断出产的矿石支撑着当地人类对抗塔伦米尔的被遗忘者的战争行动。",h="碧玉矿洞是一座由联盟运作的活跃铁矿，坐落在希尔斯布莱德丘陵的西南山丘中。矿洞由南海镇的民兵把守，并由人类劳工开采。这里源源不断出产的矿石支撑着当地人类对抗塔伦米尔的被遗忘者的战争行动。",kw={"碧玉矿洞","工头邦兹","希尔斯布莱德丘陵","希尔斯布莱德矿工","铁矿","南海镇"},ang={["faction:Horde"]="打击碧玉矿洞会切断南海镇的新鲜铁矿供应，直接支持了被遗忘者在丘陵地区的攻势。",["profession:Mining"]="碧玉矿洞内部的隧道和周围的山脊拥有丰富的铁矿沉积，尽管联盟矿工对内部进行了严密的守卫。"},sec={{t="丘陵的矿脉",b="碧玉矿洞位于开阔农田的西南方，就在南海镇的西边。长期以来，它一直开采着沿海地区矿产丰富的山脊。如今，人类矿工在工头邦兹的注视下在地下深处劳作，挖掘铁矿，为在这个地区对抗幽暗城的联盟防御者锻造武器和盔甲。"},{t="至关重要的军事目标",b="由于碧玉矿洞提供了南海镇驻军和城镇民兵所需的大部分原铁，它直接成为了部落的目标。塔伦米尔将目标对准了这里的工人和守卫，试图切断维持希尔斯布莱德人类据点的补给线。"}},faq={{q="谁控制着碧玉矿洞？",a="碧玉矿洞由联盟控制，并由隶属于南海镇和希尔斯布莱德镇的人类矿工运作，工头邦兹负责现场监督。",al={"谁管理碧玉矿洞","碧玉矿洞阵营","谁拥有碧玉矿洞"}},{q="为什么这座矿洞对部落很重要？",a="这座矿洞为南海镇和当地联盟民兵的军械库提供了至关重要的铁矿。塔伦米尔的领导层将矿工和监工视为目标，旨在瘫痪人类在丘陵地区的武器生产。",al={"为什么要攻击碧玉矿洞","希尔斯布莱德矿洞之战","部落对矿洞的兴趣"}},{q="碧玉矿洞一直是希尔斯布莱德的一部分吗？",a="那个时代的记载并没有说明在希尔斯布莱德之前是谁占据了这些山丘。如今，这座矿洞是由来自希尔斯布莱德农场的矿工在工头邦兹的带领下开采的。",al={"格雷迈恩之墙历史","碧玉矿洞曾属于吉尔尼斯吗","吉尔尼斯矿洞"}},{q="这里开采什么金属？",a="矿洞主要为附近的人类军械库生产铁矿石。",al={"碧玉矿洞有什么矿石","碧玉矿洞资源"}}},fp="14,149,22.283.0,23.219.0,28.136.0,39.192.0,44.149.0,27.69.0"}
P.entries["subzone:bael-dun-digsite"] = {n="巴尔丹挖掘场",s="巴尔丹挖掘场是一处深入莫高雷西缘山脉的矮人挖掘点。这处采石场由来自巴尔莫丹的勘探员卡兹戈姆的团队建立，当地牛头人认为这是对他们祖居之地的直接亵渎，也是对地母神的侮辱。",h="巴尔丹挖掘场是一处深入莫高雷西缘山脉的矮人挖掘点。这处采石场由来自巴尔莫丹的勘探员卡兹戈姆的团队建立，当地牛头人认为这是对他们祖居之地的直接亵渎，也是对地母神的侮辱。",kw={"巴尔莫丹","巴尔丹","贝恩·血蹄","挖掘场","矮人","地母神","探险者协会","莫高雷"},ang={["faction:Alliance"]="尽管巴尔丹的矿工们是出于对历史发现的真诚渴望，但他们过度深入了部落的主权领土，从而与当地人引发了激烈的摩擦。",["race:Tauren"]="对莫高雷西部山丘的侵入性破坏使得巴尔丹成为对地母神的直接侮辱，必须采取果断行动，保护祖传土地免受外来亵渎。"},sec={{t="山丘上的入侵",b="巴尔丹挖掘场位于莫高雷西部的山坡上，是总部位于南贫瘠之地巴尔莫丹的矮人探险者协会远征队的最南端据点。矮人勘探员们毫不关心领土边界或新定居部落的精神传统，他们带着镐、铲和爆破粉末来到这里，想要挖掘埋藏在平原之下的古老泰坦遗物。"},{t="保卫地母神",b="血蹄氏族将这种侵略性的采掘视为对地母神的直接攻击。贝恩·血蹄起初主张谨慎行事，并试图警告这些闯入者离开，但矮人们断然拒绝放弃他们的壕沟。牛头人认为外交手段已经失败，决定摧毁远征队的工具，并将矿工们强行驱逐出去，以免他们毁灭性的挖掘进一步破坏莫高雷的神圣土地。"}},faq={{q="为什么矮人在莫高雷进行挖掘？",a="这些勘探员隶属于总部位于南贫瘠之地巴尔莫丹的矮人远征队。在探险者协会发掘古老文物和泰坦遗产的任务驱动下，他们无视牛头人的主权，只要他们的仪器显示可能有遗物存在的地方，他们就会建立前哨站。",al={"为什么矮人会在这里","莫高雷的矮人","巴尔丹矮人"}},{q="血蹄氏族对该挖掘场有何反应？",a="牛头人将此行动视为对地母神不可容忍的伤害。在矮人拒绝了早先和平离开的警告后，贝恩·血蹄和村落领袖们派遣战士摧毁了矿工的工具，并将这些闯入者赶出了莫高雷。",al={"牛头人的看法","贝恩的反应","牛头人对挖掘场的反应"}},{q="巴尔丹和巴尔莫丹之间有什么联系？",a="巴尔丹是一个卫星挖掘点，直接由位于南贫瘠之地山脊对面的巴尔莫丹要塞和主要挖掘点建立。",al={"巴尔莫丹的关联","这些矮人来自哪里"}},{q="为什么牛头人没有直接与远征队进行谈判？",a="贝恩·血蹄起初寻求外交解决方案，并向远征队领导人发出了正式警告。然而，矮人们将莫高雷视为无主荒野，完全无视牛头人的精神关切，这使得武力成为了氏族唯一的选择。",al={"牛头人是否尝试过和平","与矮人的外交"}}},fp="16,218,22.393.0,26.346.0,35.270.0,52.237.0,55.129.0,59.195.0"}
P.entries["subzone:bael-dun-keep"] = {n="巴尔丹城堡",s="巴尔丹城堡是一座气势雄伟的矮人防御工事，俯瞰着南贫瘠之地的巴尔莫丹发掘场。在双辫将军的指挥下，这座堡垒成为了联盟在该地区备受争议的据点，使其与周围的部落领地陷入了激烈的冲突之中。",h="巴尔丹城堡是一座气势雄伟的矮人防御工事，俯瞰着南贫瘠之地的巴尔莫丹发掘场。在双辫将军的指挥下，这座堡垒成为了联盟在该地区备受争议的据点，使其与周围的部落领地陷入了激烈的冲突之中。",kw={"巴尔莫丹","巴尔丹城堡","巴尔丹","探险者协会","加恩·石塔","双辫将军","haggis boatmurder","南贫瘠之地"},ang={["faction:Alliance"]="这座城堡是你在南贫瘠之地的主要军事据点，保卫着探险者协会的重要发现，抵御着敌对部落势力的侵扰。",["race:Tauren"]="巴尔丹城堡矗立在从石塔部族手中掠夺的神圣土地上，这时刻提醒着我们联盟对你们家园的侵犯，这是一种莫大的侮辱。"},sec={{t="卡利姆多的一座矮人要塞",b="巴尔丹城堡由矮人建筑师Haggis Boatmurder设计建造，是铁炉堡在南贫瘠之地驻军的军事核心。这座堡垒高耸于巴尔莫丹广阔的发掘壕沟之上，保护着在此搜寻远古泰坦神器的勘探员和考古学家。由于配备了大量的铁制武器和火炮，其驻军始终保持警惕，确保了矮人补给线的安全，并将联盟的军事力量直接投射到卡利姆多的腹地。"},{t="流血冲突的焦点",b="巴尔丹城堡及其毗邻的挖掘现场并非和平建立，它迫使当地的石塔牛头人部族离开了祖居之地。如今，巴尔丹成为了贫瘠之地一个日益紧张的冲突焦点。附近的部落哨站视这座堡垒为赤裸裸的军事入侵，而加恩·石塔则对入侵者发动了一场个人的复仇战争。在愤愤不平的牛头人、投机取巧的斥候，以及像陶拉祖营地这样心怀戒备的哨站之间，这座城堡始终面临着突袭和破坏的威胁。"}},faq={{q="谁控制着巴尔丹城堡？",a="这座堡垒由效忠于联盟和铁炉堡探险者协会的矮人战士驻守，由坚定的指挥官双辫将军统领。",al={"谁管理巴尔丹城堡","谁领导巴尔丹","双辫将军"}},{q="为什么要在南贫瘠之地建造巴尔丹城堡？",a="它的建立是为了保卫巴尔莫丹。这是一场大规模的考古探险，旨在发掘卡利姆多的泰坦圣物以及矮人的古老起源。",al={"矮人为何出现在贫瘠之地","巴尔丹城堡的目的","矮人为何在此建造"}},{q="当地的牛头人为什么要攻击巴尔丹城堡？",a="发掘场和堡垒迫使当地的石塔牛头人离开了他们的祖居之地。像加恩·石塔这样的幸存者寻求复仇，并渴望消灭这些矮人入侵者。",al={"加恩·石塔的复仇","牛头人为何仇视巴尔丹","石塔部族的血仇"}},{q="这座堡垒的建筑师是谁？",a="矮人的建筑记录显示，这座堡垒是由Haggis Boatmurder设计并建造的。",al={"谁建造了巴尔丹城堡","haggis boatmurder","巴尔丹设计图"}}},fp="13,279,32.455.0,25.432.0,27.141.0,51.158.0,49.183.0,38.112.0"}
P.entries["subzone:bael-modan"] = {n="巴尔莫丹",s="巴尔莫丹是一座位于南贫瘠之地的矮人防御前哨和考古发掘场。这座防御森严的设施由寻找古代泰坦遗物的矮人挖掘者所建立，因驱逐了当地的石塔牛头人而引发了激烈的冲突。",h="巴尔莫丹是一座位于南贫瘠之地的矮人防御前哨和考古发掘场。这座防御森严的设施由寻找古代泰坦遗物的矮人挖掘者所建立，因驱逐了当地的石塔牛头人而引发了激烈的冲突。",kw={"巴尔莫丹","巴尔丹","贫瘠之地挖掘","费格雷","加恩·石塔","石塔","众月之泪","孪辫"},ang={["race:Dwarf"]="这座发掘场代表了探险者协会发掘泰坦历史的无情驱动力，尽管其指挥官的高压手段已经为他们招致了当地部族的激烈仇恨。",["race:Tauren"]="巴尔莫丹就像贫瘠之地上一道未愈合的伤口，建立在石塔部族圣地的废墟之上。帮助加恩·石塔复仇是关乎部族荣誉的事情。"},sec={{t="发掘出的秘密与流血事件",b="巴尔莫丹由防御森严的巴尔丹城堡、一系列巨大的攻城大炮、直升机停机坪以及一个深邃的露天挖掘坑组成。矮人勘探者来到卡利姆多，坚信红土地下埋藏着一处古代泰坦设施。然而，他们的爆破作业直接摧毁了属于石塔牛头人的圣地。矮人探险队没有选择协商，而是用枪炮和炸药将石塔牛头人从他们的祖居地驱逐出去，使得幸存的族人四散奔逃，满怀怨恨。"},{t="发掘遗物的代价",b="这次发掘出来的不仅仅是历史建筑。矮人挖掘者最近发现了一件名为众月之泪的古器，这件遗物会导致接触它的人产生偏执和疯狂。一名被流放的勘探者被流放的费格雷完全屈服于它的影响，当这块石头回到他手中时，他被扭曲成了一只穴居人。在致命的遗物和门外寻求报复的愤怒牛头人之间，这座矮人营地一直处于危险之中。"}},faq={{q="为什么矮人在贫瘠之地挖掘？",a="矮人们正在寻找埋藏在卡利姆多地下的古代泰坦建筑和遗物。他们的挖掘工作是旨在揭开矮人种族起源的更大规模探险的一部分，他们相信这与地下的泰坦研究设施有关。",al={"为什么矮人在这里","巴尔莫丹的目的","矮人在挖掘什么"}},{q="以前住在这里的牛头人怎么样了？",a="这片土地最初属于石塔部族，他们将这里的山丘视为圣地。当矮人到来时，他们使用炸药炸开了发掘场，屠杀或驱逐了居住在此的牛头人，并摧毁了他们的村庄。",al={"石塔牛头人","谁住在巴尔莫丹","牛头人村庄"}},{q="加恩·石塔是谁？",a="加恩·石塔是石塔部族为数不多的幸存者之一。在寻求和平解决的尝试失败后，他在巴尔莫丹门外的道路旁扎营，并征召部落的旅者去破坏矮人的飞行器，杀死那些摧毁他族人家园的军官。",al={"加恩","加恩任务发放者"}},{q="什么是众月之泪？",a="众月之泪是一件由挖掘者发现的神秘的古器。它会使接触它的凡人发疯，并使被流放的矮人费格雷沉迷于夺回它。",al={"众月之泪遗物","费格雷古器"}}},fp="10,189,31.427.0,29.400.1,39.182.0,50.208.0,23.254.0,30.168.1"}
P.entries["subzone:bal-lal-ruins"] = {n="巴拉尔废墟",s="巴拉尔废墟是位于荆棘谷西北海岸的古代古拉巴什巨魔废墟，就在格罗姆高营地以北。这些摇摇欲坠的石基俯瞰着暗礁海那浑浊的水域，目前被敌对的血顶巨魔所占据。",h="巴拉尔废墟是位于荆棘谷西北海岸的古代古拉巴什巨魔废墟，就在格罗姆高营地以北。这些摇摇欲坠的石基俯瞰着暗礁海那浑浊的水域，目前被敌对的血顶巨魔所占据。",kw={"巴拉尔废墟","血顶","格罗姆高","古拉巴什","荆棘谷","暗礁海"},ang={["faction:Horde"]="巴拉尔废墟位于格罗姆高营地沿岸不远处，血顶巨魔在此盘踞，对沿着海岸线巡逻的部落构成了持续的安全威胁。",["race:Troll"]="对于效忠部落的暗矛巨魔来说，像巴拉尔这样的地方令人清醒地看到了古代古拉巴什荣耀的残骸，而这里却被同样被无尽嗜血蒙蔽双眼的表亲部落所占据。"},sec={{t="暗礁上摇摇欲坠的前哨站",b="巴拉尔废墟坐落在格罗姆高营地以北的海岸线上，是破碎的古拉巴什帝国的又一遗迹。这里曾是统治艾泽拉斯南部的宏伟巨魔文明的一部分，如今已沦为布满青苔的石墙和破裂的砖石。废墟紧邻暗礁海，提供了一个俯瞰险恶海岸浅滩的高处视野。今天，好战的血顶巨魔占据了这里，拼命保卫着祖先饱经风霜的遗迹，抵御入侵者。"}},faq={{q="谁控制着巴拉尔废墟？",a="这些废墟目前由血顶氏族的成员占据，他们积极守卫领土，抵御外来者、旅行者和竞争对手。",al={"谁住在这里","巴拉尔废墟怪物","谁在巴拉尔废墟"}},{q="巴拉尔废墟位于哪里？",a="你可以在荆棘谷的西北海岸找到它们，位于格罗姆高营地正北方，俯瞰着暗礁海。",al={"巴拉尔废墟位置","巴拉尔废墟在哪里","如何找到巴拉尔废墟"}},{q="这些废墟有什么历史？",a="像荆棘谷中散布的大多数石制建筑一样，巴拉尔废墟可以追溯到古拉巴什帝国在分裂成相互交战的丛林巨魔部落之前的时代。",al={"巴拉尔背景故事","巴拉尔废墟历史","谁建造了巴拉尔废墟"}}},fp="13,269,31.527.0,27.153.0,36.151.0,33.193.0"}
P.entries["subzone:balia-mah-ruins"] = {n="巴里亚曼废墟",s="巴里亚曼废墟是位于荆棘谷北部，覆盖着苔藓的古老古拉巴什定居点遗迹。它位于格罗姆高营地以东的河对岸，这些破碎的石阶目前被敌对的裂颅者巨魔部落所占据并守护着。",h="巴里亚曼废墟是位于荆棘谷北部，覆盖着苔藓的古老古拉巴什定居点遗迹。它位于格罗姆高营地以东的河对岸，这些破碎的石阶目前被敌对的裂颅者巨魔部落所占据并守护着。",kw={"巴里亚曼","古拉巴什","废墟","裂颅者","荆棘谷"},ang={["faction:Horde"]="由于位置就在格罗姆高营地的河对岸，巴里亚曼的敌对裂颅者对部落的侦察兵和补给线构成了持续的周边威胁。",["race:Troll"]="对于暗矛巨魔来说，行走在这些古老的石台之上，不仅会让他们想起祖先曾经共有的辉煌古拉巴什文明，也会让他们想起那场撕裂了丛林巨魔社会的黑暗派系斗争。"},sec={{t="破碎的遗产",b="和散布在丛林中的许多石砌建筑一样，巴里亚曼是曾经统治了东部王国南部大部分地区的庞大古拉巴什帝国留下的遗迹。在古老的首都陷落后，古拉巴什的领土分裂成了许多交战的派系。如今，这些废墟成为了裂颅者部落的据点，他们拼死捍卫着这些石台，抵御着游荡的野兽、来自莫什奥格食人魔山的食人魔，以及任何胆敢过河的外来者。"}},faq={{q="巴里亚曼废墟位于何处？",a="这些废墟坐落在荆棘谷北部，位于部落据点格罗姆高营地东南方向的河对岸，莫什奥格食人魔山的西南方。",al={"巴里亚曼位置","巴里亚曼在哪里","巴里亚曼废墟地图"}},{q="目前是谁在控制这些废墟？",a="这些废墟目前被裂颅者部落占据，这是一个敌对的丛林巨魔派系，正大肆守卫着这些古老的石台。",al={"谁住在巴里亚曼","巴里亚曼有什么怪物","巴里亚曼敌人"}},{q="巴里亚曼的历史是什么？",a="该建筑群建于古拉巴什帝国鼎盛时期。在帝国崩溃后，遗址陷入荒废，最终被丛林植被和幸存的巨魔部落所重新占据。",al={"巴里亚曼背景故事","谁建造了巴里亚曼"}},{q="巴里亚曼的裂颅者是否与其他巨魔营地有关联？",a="是的。裂颅者部落在整个荆棘谷北部和中部维持着多个营地和废墟，并与血顶等敌对部落进行着持续不断的领土战争。",al={"荆棘谷的裂颅者","巴里亚曼裂颅者"}}},fp="15,283,20.498.0,38.164.0,33.148.0,33.200.0,67.205.0"}
P.entries["subzone:balnir-farmstead"] = {n="巴尼尔农场",s="巴尼尔农场是提瑞斯法林地东部的一处废弃庄园，位于洛丹伦废墟的东北方。这里曾经是巴尼尔家族经营的农场，如今土地已荒废，并被那些溜过亡灵壁垒的游荡天灾所侵占。",h="巴尼尔农场是提瑞斯法林地东部的一处废弃庄园，位于洛丹伦废墟的东北方。这里曾经是巴尼尔家族经营的农场，如今土地已荒废，并被那些溜过亡灵壁垒的游荡天灾所侵占。",kw={"巴尼尔","农场","金鱼草","提瑞斯法"},ang={["class:Mage"]="被遗忘者法师被派遣到这片荒芜的土地上采集幸存的巴尼尔金鱼草，通过研究它们来侦测天灾军团挥之不去的魔法污染。",["race:Undead"]="对于被遗忘者来说，这座农场不仅是他们失去洛丹伦的痛苦提醒，也是一个挥之不去的安全隐患，因为来自瘟疫天灾的天灾军团会从这里溜过亡灵壁垒。"},sec={{t="瘟疫前的农场",b="世世代代以来，巴尼尔家族都在提瑞斯法东部的连绵丘陵中经营着他们的家园，而他们花园里的金鱼草至今仍在废墟中绽放。第三次战争期间，当天灾军团横扫洛丹伦时，农场被攻陷，这里的人们也随之丧生，只留下了腐朽的建筑。"},{t="荒凉与天灾的渗透",b="第三次战争之后，这些废墟成了溜过亡灵壁垒的无脑天灾的立足点。被遗忘者死亡卫士警惕地监视着农场，而幽暗城的法师们则从花园里采集幸存的金鱼草，以测试瘟疫腐蚀在土壤中渗透的深度。"}},faq={{q="为什么巴尼尔农场很重要？",a="它坐落在提瑞斯法的东部入口处，就在亡灵壁垒后方。溜过防御者的天灾军团会聚集在这里，而其金鱼草花园则让被遗忘者法师能够测量瘟疫在提瑞斯法扩散的程度。",al={"巴尼尔农场的重要性","为什么要前往巴尼尔农场"}},{q="瘟疫发生前是谁住在农场里？",a="这座农场属于巴尼尔家族，他们以自己的名字命名了这里。当第三次战争期间天灾军团横扫提瑞斯法时，他们便已丧生，如今只有亡灵行走在这些田野之上。",al={"谁拥有巴尼尔农场","巴尼尔家族"}},{q="为什么被遗忘者现在要监视这个农场？",a="无脑的天灾军团经常从瘟疫之地溜过亡灵壁垒并聚集在农场，威胁着提瑞斯法的东部入口。此外，幽暗城的学者们研究着花园中依然生长的顽强金鱼草，以测量瘟疫污染的扩散情况。",al={"为什么被遗忘者关心巴尼尔","rear guard patrol背景故事","巴尼尔金鱼草"}}},fp="16,166,24.270.0,35.277.0,38.236.0,45.189.0,45.268.0"}
P.entries["subzone:ban-ethil-barrow-den"] = {n="班奈希尔兽穴",s="班奈希尔兽穴是一处神圣的地下圣所，位于泰达希尔的根系之中。这座洞穴群最初是为沉睡的利爪德鲁伊所建的安息之所，但近来却陷入了混乱。被腐蚀的棘木熊怪占领了这些洞穴，将这片宁静的沉睡之地变成了一个危险而疯狂的兽穴。",h="班奈希尔兽穴是一处神圣的地下圣所，位于泰达希尔的根系之中。这座洞穴群最初是为沉睡的利爪德鲁伊所建的安息之所，但近来却陷入了混乱。被腐蚀的棘木熊怪占领了这些洞穴，将这片宁静的沉睡之地变成了一个危险而疯狂的兽穴。",kw={"班奈希尔","兽穴","利爪德鲁伊","翡翠梦境","熊怪","棘木部族","泰达希尔"},ang={["class:Druid"]="班奈希尔是塞纳里奥议会的神圣之地，它是为了在利爪德鲁伊与翡翠梦境沟通时保护他们而专门建造的。",["race:NightElf"]="被腐蚀的棘木熊怪对班奈希尔的占领，是一个令人担忧的迹象，表明这种正在折磨他们的新家园泰达希尔的疾病正在加剧。"},sec={{t="被玷污的圣所",b="兽穴是暗夜精灵德鲁伊进行沉睡的圣地，他们在沉睡时会将灵魂投射到翡翠梦境中。班奈希尔兽穴专门用于庇护进行自然交流的利爪德鲁伊。兽穴分为上下两层地下洞穴，曾经充满了宁静的冥想与深奥的沉思魔法。然而，席卷泰达希尔野生生物的腐蚀并没有放过棘木熊怪，它们入侵了这里，将原本空旷的大厅变成了坚固的巢穴。"},{t="棘木熊怪的入侵",b="在世界之树蔓延的神秘腐蚀令棘木部族陷入疯狂，他们驱逐或威胁了班奈希尔内沉睡的德鲁伊。如今，这些熊怪凶猛地守卫着蜿蜒的隧道，对任何靠近的暗夜精灵都充满敌意。对于泰达希尔的保卫者来说，夺回这座兽穴是一项迫在眉睫的任务，这不仅是为了击退敌对的熊怪，更是为了保护困在深处那些脆弱的德鲁伊和神圣的遗物。"}},faq={{q="什么是班奈希尔兽穴？",a="班奈希尔兽穴是暗夜精灵在泰达希尔开凿的一处地下空洞。它旨在为沉睡的利爪德鲁伊提供庇护，让他们在灵魂游历翡翠梦境时不受打扰。",al={"班奈希尔是什么","班奈希尔兽穴的作用","这个洞穴是什么"}},{q="为什么班奈希尔兽穴里会有熊怪？",a="棘木熊怪成为了泰达希尔生物所遭受的扩散性腐蚀的受害者。它们变得充满敌意且具有领地意识，入侵了兽穴，赶走了看守者，并威胁到了沉睡的德鲁伊。",al={"棘木熊怪为什么在班奈希尔","兽穴里的熊怪","谁占领了班奈希尔"}},{q="兽穴分为哪些区域？",a="洞穴群分为两个主要的相连层级：靠近入口通道的上层兽穴，以及深入地下根系的下层兽穴。",al={"班奈希尔的布局","上层兽穴和下层兽穴","班奈希尔的层级"}},{q="为什么兽穴对德鲁伊如此重要？",a="兽穴为那些进行长期深层沉睡、将意识投射到翡翠梦境中的德鲁伊提供了安全可靠的物理庇护所，因为他们在沉睡期间的肉体长达数年甚至数十年都处于无防备状态。",al={"德鲁伊为什么要睡在兽穴里","德鲁伊兽穴的背景故事","翡翠梦境与兽穴"}}},fp="20,264,19.453.0,23.371.0,29.172.0,51.178.0,40.128.0,43.183.0"}
P.entries["subzone:ban-ethil-hollow"] = {n="班尼希尔山谷",s="班尼希尔山谷是一条崎岖的峡谷，切入了连接多兰纳尔和达纳苏斯的主干道以南的林地。它已成为受腐蚀、具有攻击性的熊怪的危险避风港，对旅行者构成了持续的威胁。峡谷深处隐匿着班奈希尔兽穴的入口。",h="班尼希尔山谷是一条崎岖的峡谷，切入了连接多兰纳尔和达纳苏斯的主干道以南的林地。它已成为受腐蚀、具有攻击性的熊怪的危险避风港，对旅行者构成了持续的威胁。峡谷深处隐匿着班奈希尔兽穴的入口。",kw={"伏击","班奈希尔兽穴","班尼希尔山谷","达纳苏斯","多兰纳尔","熊怪","峡谷","泰达希尔"},ang={["class:Druid"]="山谷隐藏着班奈希尔兽穴的入口，这是一片神圣的土地，德鲁伊传统上在此休息以与翡翠梦境交流，如今却受到狂暴野生动物的威胁。",["race:NightElf"]="看到熊怪在多兰纳尔和达纳苏斯之间的道路旁发疯，这是泰达希尔病情加重的严峻迹象，需要年轻的哨兵和德鲁伊介入。"},sec={{t="危险的峡谷",b="班尼希尔山谷坐落在多兰纳尔和达纳苏斯之间的大道旁，它尖锐地提醒着人们，泰达希尔的枝叶并非完全安全。受困扰世界之树的怪异疾病影响而发疯的熊怪们，在整个岩石斜坡上寻找藏身之处。他们经常跟踪附近的小路，等待伏击粗心的信使和游荡的哨兵。峡谷深处是班奈希尔兽穴的入口，那里沉睡的德鲁伊和古老的隧道正面临着外面疯狂野兽的侵扰。"}},faq={{q="班尼希尔山谷位于何处？",a="班尼希尔山谷位于泰达希尔中部，就在多兰纳尔村和达纳苏斯主城之间主干道的南侧。",al={"班尼希尔山谷位置","班尼希尔山谷在哪里","寻找班尼希尔山谷"}},{q="为什么这里的熊怪怀有敌意？",a="泰达希尔各处的熊怪已经屈服于一种正在蔓延的腐蚀和疯狂，这种腐蚀和疯狂正笼罩着世界之树的野生动物。这些部族不再像历史上那样与暗夜精灵和平共处，而是变得极具领地意识且暴力成性。",al={"为什么熊怪发疯","班尼希尔敌对熊怪","班尼希尔熊怪攻击"}},{q="峡谷尽头的班奈希尔兽穴里有什么？",a="班奈希尔兽穴是一个地下建筑群，历史上一直被暗夜精灵德鲁伊用来进入深度睡眠并与翡翠梦境交流。然而，随着山谷中腐蚀的加剧，兽穴已变成了一块危险之地。",al={"兽穴里有什么","班奈希尔兽穴","班尼希尔山谷中的兽穴"}},{q="山谷上方的道路安全吗？",a="主干道通常有暗夜精灵哨兵巡逻，但来自班尼希尔山谷的熊怪经常从峡谷窜出来伏击旅行者。往返于多兰纳尔和达纳苏斯之间的旅行者应保持警惕。",al={"道路安全吗","熊怪伏击","去达纳苏斯的道路安全吗"}}},fp="16,158,17.464.0,34.111.0,34.194.0,66.210.0,44.167.0"}
P.entries["subzone:bandarion-keep"] = {n="班达里安堡",s="班达里安堡是一座与泰尔之守护（Tyr's Watch）有关的防御工事，坐落在提瑞斯法林地西部边缘，靠近耳语森林。这座哨站以加瑞克·班达里安（Garek Bandarion）的名字命名，是林地边境上的一道孤立堡垒，时刻应对着林区中挥之不去的威胁。守军不仅要抵御敌对的海岸鱼人，还要面对游荡的狂热者和不稳定的亡灵。",h="班达里安堡是一座与泰尔之守护（Tyr's Watch）有关的防御工事，坐落在提瑞斯法林地西部边缘，靠近耳语森林。这座哨站以加瑞克·班达里安（Garek...",kw={"班达里安","班达里安堡","加瑞克·班达里安","乔林·克罗格","提瑞斯法","泰尔之守护","耳语森林"},ang={["class:Paladin"]="对于直面冰冷亡灵现实的圣光战士而言，班达里安堡既是避难所，也是警示：一些无法调和圣光与亡灵身份的圣骑士已经崩溃，并开始对自己的被遗忘者同胞挥刀相向。",["race:Undead"]="这座堡垒矗立在提瑞斯法西部的边缘，证明了被遗忘者不仅要时刻警惕天灾军团和血色十字军，还必须提防自身内部的动荡。"},sec={{t="西境堡垒",b="班达里安堡坐落在提瑞斯法林地西部，靠近隐秘的耳语森林，是遗忘者的一座孤哨。该要塞以加瑞克·班达里安的名字命名，与泰尔之守护有着紧密的联系。尽管地理位置偏远且环境严酷，距离幽暗城的繁华庭院甚远，但像乔林·克罗格（Jorin Croge）这样的军需官仍在勤恳工作，以确保存货充足。"},{t="四面受敌",b="驻守此堡绝非安逸的差事。哨站时刻面临着种种威胁：附近水域有邪鳍鱼人（Vile Fin murloc）的突袭，血色十字军的试探性小规模骚扰，以及在阴影中蹒跚游荡、失去理智的天灾奴仆。更糟糕的是内部的危机：一些难以适应“被遗忘者”这一亡灵形态的圣骑士陷入了疯狂，竟将武器挥向了自己的同胞。"}},faq={{q="班达里安堡位于何处？",a="班达里安堡位于提瑞斯法林地遥远的西侧荒野，靠近神秘的耳语森林。",al={"班达里安堡位置","班达里安堡在哪里","如何找到班达里安堡"}},{q="班达里安堡是以谁的名字命名的？",a="这座要塞是以加瑞克·班达里安的名字命名的，他与驻扎在那里的组织有着密切的联系。",al={"谁是班达里安","加瑞克·班达里安","班达里安堡名称由来"}},{q="什么是泰尔之守护？",a="泰尔之守护与班达里安堡以及驻守此地的被遗忘者圣骑士息息相关；班达里安堡被视为泰尔之守护的堡垒，这两个名字经常被互换使用。",al={"泰尔之守护","什么是泰尔之守护"}},{q="有哪些危险威胁着这座堡垒？",a="堡垒的守军经常需要击退邪鳍鱼人，与血色十字军的狂热者交战，消灭游荡的无脑天灾，并镇压那些丧失理智且攻击同伴的不稳定被遗忘者圣骑士。",al={"谁在攻击班达里安堡","班达里安堡的威胁","班达里安敌人"}}},fp="14,167,31.276.0,21.340.0,32.75.0,35.44.0,20.169.0,31.210.0"}
P.entries["subzone:baradin-bay"] = {n="巴拉丁海湾",s="巴拉丁海湾是位于卡兹莫丹、湿地、阿拉希高地和洛丹伦南部海岸之间的广阔水域。在第二次战争期间，这里曾有库尔提拉斯强大的海军进行严密的巡逻，而如今，其水域深处隐藏着险恶的暗礁、沉没的战舰以及充满敌意的水生掠食者。",h="巴拉丁海湾是位于卡兹莫丹、湿地、阿拉希高地和洛丹伦南部海岸之间的广阔水域。在第二次战争期间，这里曾有库尔提拉斯强大的海军进行严密的巡逻，而如今，其水域深处隐藏着险恶的暗礁、沉没的战舰以及充满敌意的水生掠食者。",kw={"巴拉丁海湾","水下暗礁","大漩涡之海","库尔提拉斯","失落的舰队","米奈希尔港","南海镇","湿地"},ang={["faction:Alliance"]="巴拉丁海湾是连接卡兹莫丹的联盟行动与其在阿拉希和希尔斯布莱德的前哨站的海上生命线，尽管航海风险和沉没的残骸使得每一次航行都充满危险。",["race:Human"]="对于人类，特别是那些追溯血统至库尔提拉斯或洛丹伦的人来说，这片海湾是神圣而阴郁的土地，它是第二次战争水手们的葬身之地。"},sec={{t="战略水道",b="巴拉丁海湾南邻丹莫罗海岸，北接洛丹伦海岸，是连接东部王国各港口的重要海上通道。海湾的重要锚点包括湿地的米奈希尔港和希尔斯布莱德丘陵的南海镇等繁忙港口。然而，航行于此危机四伏：浅滩、参差不齐的礁石，以及鱼人、鳄鱼和深海鲨鱼等危险生物，时刻威胁着水手和旅行者。"},{t="舰队的坟墓",b="在第二次战争期间，巴拉丁海湾见证了激烈的海军冲突，当时库尔提拉斯舰队与部落在此交战。如今，这些战斗的残酷遗迹仍散布在海岸和海底。库尔提拉斯第三舰队（当地人称为失落的舰队）的残骸半沉在湿地海岸边，而其他船只则沉入了水下暗礁。敌对的灵魂、投机的打捞者和贪婪的海兽现在出没在这些腐朽的木质废墟周围的水域中。"}},faq={{q="巴拉丁海湾沿岸有哪些主要港口？",a="海湾沿岸最著名的定居点是位于湿地的米奈希尔港和位于希尔斯布莱德丘陵的南海镇，它们维持着跨海的重要海军运输。",al={"巴拉丁海湾港口","巴拉丁海湾的港口","巴拉丁海湾通向哪里"}},{q="为什么海湾沿岸有这么多沉船？",a="湿地海岸沿线的残骸是第二次战争期间被摧毁的库尔提拉斯第三舰队，即失落的舰队。其他船只则沉没在阿拉希海岸外危险的水下暗礁上。",al={"湿地沉船","为什么这里有沉船","失落的舰队起源"}},{q="在巴拉丁海湾的水域中会遇到什么威胁？",a="浅水区到处都是极具攻击性的鱼人与沼泽鳄鱼，而深水区则充满了掠食性蟹类、鲨鱼以及溺水水手们不安的灵魂。",al={"巴拉丁海湾怪物","巴拉丁海湾的鱼人","在巴拉丁海湾游泳安全吗"}},{q="哪些领土与巴拉丁海湾接壤？",a="巴拉丁海湾被丹莫罗西北部、湿地的沼泽海岸、阿拉希高地的悬崖以及希尔斯布莱德南部和吉尔尼斯的海岸所环绕。",al={"哪些区域与巴拉丁海湾接壤","巴拉丁海湾地理"}}},fp="11,233,20.248.0,23.307.0,47.140.0,55.175.0,55.136.0,37.113.0"}
P.entries["subzone:bashal-aran"] = {n="巴莎兰",s="巴莎兰是一座位于黑海岸北部、奥伯丁东侧的古老上层精灵遗迹。在大分裂之前，这里曾是亚米萨兰的繁华姊妹城市。如今，这座遗迹中爬满了以残留奥术能量为食的恶魔萨特和格罗尔，而一位孤独的精灵鬼魂则被困在数世纪前的诅咒中。",h="巴莎兰是一座位于黑海岸北部、奥伯丁东侧的古老上层精灵遗迹。在大分裂之前，这里曾是亚米萨兰的繁华姊妹城市。如今，这座遗迹中爬满了以残留奥术能量为食的恶魔萨特和格罗尔，而一位孤独的精灵鬼魂则被困在数世纪前的诅咒中。",kw={"亚米萨兰","阿斯特利安","阿斯瑞克斯·纳拉辛","巴莎兰","黑海岸","德斯瑞尔","格罗尔","上层精灵","萨特"},ang={["class:Mage"]="束缚阿斯特利安的月石结界展现了上层精灵法术恐怖的持久性和威力。",["race:NightElf"]="巴莎兰是一座悲剧性的纪念碑，提醒着人们正是那种鲁莽的奥术傲慢导致了古老卡多雷帝国的毁灭，并为恶魔的腐化铺平了道路。"},sec={{t="破碎的姊妹城市",b="在大分裂将古老的卡利姆多大陆摧毁的一万年前，艾萨拉女王将她宠信的上层精灵子民安置在巴莎兰和亚米萨兰这两座姊妹城镇中。在强大的法师阿斯瑞克斯·纳拉辛的治理下，这些城市曾拥有辉煌的集市和供奉艾露恩的神殿。当永恒之井坍塌时，那场大灾变将两座定居点夷为平地。由于某些早已被时间遗忘的原因，阿斯瑞克斯利用他的奥术造诣，将他的副手、法师阿斯特利安束缚在巴莎兰的一枚月石印记中。即便在肉体消亡后，阿斯特利安的灵魂依然被禁锢在这座破败的神殿里。"},{t="恶魔出没",b="在现代，巴莎兰崩塌的石块被一群邪恶的非法占有者所占据：德斯瑞尔萨特和调皮的格罗尔。这些被腐化的生物受到依附在古老砖石上的残余魔法的吸引，贪婪地吸食着这些残留的能量以强化他们的邪恶法术。尽管它们成群结队地盘踞在残破的庭院中，恐吓着黑海岸林间小路上的旅人，但这些恶魔却对阿斯特利安永恒守望的中央神殿敬而远之。"}},faq={{q="巴莎兰在被毁之前是什么地方？",a="巴莎兰是艾萨拉女王在大分裂前为她宠信的上层精灵贵族建立的一座宏伟的卡多雷城市。它与姊妹城市亚米萨兰一起，由法师领主阿斯瑞克斯·纳拉辛统治。",al={"巴莎兰历史","谁建造了巴莎兰","这片遗迹是什么"}},{q="在神殿中游荡的鬼魂是谁？",a="那个灵魂是阿斯特利安，一位受人尊敬的上层精灵战士法师，他曾负责管理巴莎兰和亚米萨兰。他神秘地遭到了背叛，并被总督阿斯瑞克斯·纳拉辛用一枚月石印记束缚于此，即便在凡身死后，依然承受着囚禁之苦。",al={"阿斯特利安是谁","巴莎兰鬼魂","为什么会有鬼魂"}},{q="为什么萨特会居住在遗迹中？",a="萨特和格罗尔被古老上层精灵留下的强大奥术能量残余吸引到了巴莎兰。它们以这些挥之不去的魔法散溢为食，以增强它们邪恶的恶魔魔法。",al={"为什么这里有萨特","德斯瑞尔萨特背景","巴莎兰的格罗尔"}},{q="巴莎兰与亚米萨兰有何关联？",a="巴莎兰和亚米萨兰是在艾萨拉女王统治下共同治理的姊妹城市。在大分裂将两地摧毁前，阿斯特利安曾频繁往返于两座定居点之间，处理民众的需求。",al={"亚米萨兰联系","黑海岸的姊妹城市","亚米萨兰巴莎兰"}}},fp="11,172,21.572.0,19.356.0,45.202.0,38.280.0,36.164.0,42.201.0"}
P.entries["subzone:bathran-s-haunt"] = {n="巴斯兰鬼屋",s="巴斯兰鬼屋是坐落在灰谷西北部、佐拉姆海岸以东的一处古代卡多雷遗迹。最近，被遗忘者药剂师及其卫兵占领了这片区域，搜集当地植物用于他们的炼金研究，导致周围的林地逐渐枯萎。",h="巴斯兰鬼屋是坐落在灰谷西北部、佐拉姆海岸以东的一处古代卡多雷遗迹。最近，被遗忘者药剂师及其卫兵占领了这片区域，搜集当地植物用于他们的炼金研究，导致周围的林地逐渐枯萎。",kw={"灰谷","巴斯兰的头发","巴斯兰鬼屋","被遗忘者","草药学","卡多雷遗迹","奥迪拉兰废墟","佐拉姆海岸"},ang={["profession:Herbalism"]="这些遗迹在植物学上是独一无二的，因为它是巴斯兰的头发这种因其罕见的药用价值而备受追捧的草药的唯一已知栖息地。",["race:NightElf"]="巴斯兰鬼屋的被遗忘者营地是对卡多雷遗产的暴行，亡灵入侵者亵渎了古老的精灵石结构，并破坏了这片神圣的土地。"},sec={{t="古老森林中的荒芜避难所",b="在奥迪拉兰废墟的北面，破碎的暗夜精灵柱石矗立在茂密的灰谷枝叶掩映之中。这里曾经是一处宁静的卡多雷遗迹，如今却笼罩在被遗忘者的阴影之下。在残破的大理石之间，亡灵药剂师及其打手设置了一间粗陋的露天实验室。他们的存在本身就破坏了这片古老的土地：青草枯萎成了病态的棕色，鲜艳的花朵凋零，随着他们有条不紊地采摘珍稀的林地药材进行实验，一种不自然的腐败正在这片林地中蔓延。"},{t="巴斯兰的头发的采集",b="这些遗迹的主要吸引力在于巴斯兰的头发，这是一种独特的药用草药，只在这些特定的石头间扎根。虽然暗夜精灵和联盟侦察兵视被遗忘者的存在为对神圣精灵土地的邪恶亵渎，但这些亡灵正勤勉地工作，以提取这种植物的强大药效。部落对这种化合物的植物产量有着既得利益，尽管被遗忘者秘密的手段以及由此产生的土地腐化引起了局外人和盟友的一致怀疑。"}},faq={{q="巴斯兰鬼屋位于哪里？",a="巴斯兰鬼屋坐落在灰谷的西北部，位于奥迪拉兰废墟的正北方，在佐拉姆海岸的内陆东侧。",al={"巴斯兰鬼屋在哪里","巴斯兰鬼屋位置","如何前往巴斯兰鬼屋"}},{q="被遗忘者为什么会在这里？",a="被遗忘者药剂师在遗迹中建立了一个营地和实验室，以采集和研究森林中独特的植物生命，最著名的是一种被称为巴斯兰的头发的珍稀药用植物。",al={"亡灵在灰谷做什么","为什么被遗忘者在巴斯兰鬼屋","被遗忘者在巴斯兰的目的"}},{q="什么是巴斯兰的头发？",a="巴斯兰的头发是一种独特的、有价值的草药，具有强大的修复功效，仅生长在巴斯兰鬼屋摇摇欲坠的石结构周围。",al={"巴斯兰的头发草药","什么是巴斯兰的头发","巴斯兰草药"}},{q="为什么遗迹周围的土地正在枯死？",a="被遗忘者长期存在并进行炼金活动，已经腐化了周边区域，导致青草枯萎变黄，娇嫩的林地花朵凋零。",al={"为什么这里的草是棕色的","巴斯兰鬼屋的枯萎病","为什么土地正在腐烂"}}},fp="15,186,38.450.0,29.385.0,33.118.0,26.173.0,23.151.0,41.132.0"}
P.entries["subzone:bay-of-storms"] = {n="风暴海湾",s="风暴海湾是一片广阔而汹涌的海湾，切入了艾萨拉崎岖的东部悬崖。它那翻腾的海水掩盖了古老的废墟、水下洞穴以及危险的海洋生物，使得沿此海岸航行变得危机四伏。",h="风暴海湾是一片广阔而汹涌的海湾，切入了艾萨拉崎岖的东部悬崖。它那翻腾的海水掩盖了古老的废墟、水下洞穴以及危险的海洋生物，使得沿此海岸航行变得危机四伏。",kw={"艾萨拉","风暴海湾","无尽之海","赫塔拉的巢穴","鳞须海龟洞穴","亚考兰神殿"},ang={["profession:Cooking"]="风暴海湾那动荡且深邃的海水在卡利姆多海岸寻求稀有且珍贵的深海渔获的海岸渔民中非常出名。"},sec={{t="风暴海岸",b="风暴海湾向着无尽之海敞开，构成了艾萨拉大部分引人注目的海岸地理。这里绝非宁静的港湾，其动荡的水域和岩石暗礁是危险野生动物和古老水生威胁的家园。在其水域内外分布着诸多地标，例如沉没的亚考兰神殿、赫塔拉的巢穴的珊瑚礁，以及鳞须海龟洞穴，使得这片海湾绝大多数时候被普通水手所避开，反而是海岸怪物的领地。"}},faq={{q="风暴海湾位于哪里？",a="风暴海湾位于艾萨拉的东部边缘，直接通向卡利姆多海岸外的无尽之海。",al={"风暴海湾位置","风暴海湾在哪里","海湾在哪里"}},{q="海湾内有哪些著名地标？",a="海湾内包含几处著名的海岸特征，包括亚考兰神殿、被称为赫塔拉的巢穴的礁石，以及隐藏着的鳞须海龟洞穴。",al={"风暴海湾地标","风暴海湾里有什么","风暴海湾兴趣点"}},{q="为什么在海湾航行很危险？",a="狂暴的浪潮、尖锐的锯齿状岩石以及充满敌意的水生生物使得海湾对过往船只来说十分凶险，而且此处几乎没有海岸文明可以提供救援。",al={"风暴海湾安全吗","为什么危险","海湾危险因素"}}},fp="13,238,19.462.0,35.117.0,42.165.0,37.168.0"}
P.entries["subzone:bear-s-head"] = {n="熊头",s="熊头是艾萨拉东南部悬崖边上一处隐蔽的山区。该地因居住在崎岖高地上的木喉熊怪聚落而得名，是他们通往北方大型家园的前哨站，正下方则是大法师克希雷姆的悬崖圣所。",h="熊头是艾萨拉东南部悬崖边上一处隐蔽的山区。该地因居住在崎岖高地上的木喉熊怪聚落而得名，是他们通往北方大型家园的前哨站，正下方则是大法师克希雷姆的悬崖圣所。",kw={"大法师克希雷姆","艾萨拉","熊头","熊怪","木喉","乌索兰"},ang={["class:Mage"]="俯瞰熊头的高耸悬崖是大法师克希雷姆的居所，他是一位强大而古怪的施法者，那些寻求进阶训练的奥术修行者常常会来寻找他。"},sec={{t="熊怪前哨与崖顶魔法",b="熊头坐落于艾萨拉的东南部，因其高地上建立的未受腐蚀的木喉熊怪营地而得名。这些简朴的定居点是连接北方乌索兰和木喉要塞这些主要熊怪巢穴的边远营地。在这片区域高耸的悬崖顶端，坐落着克希雷姆之塔，这是一处古怪的圣所，大法师克希雷姆和他的一小群学徒在这里进行奥术研究，远离海岸线其他纷乱地区的喧嚣，在此静静隐居。"}},faq={{q="这个区域为什么叫熊头？",a="该地区以其丘陵地带建立的木喉熊怪村庄命名。这些熊族在此维持着活跃的营地，作为他们在卡利姆多北部的据点的前哨站。",al={"熊头名称由来","为什么叫熊头","熊头含义"}},{q="哪些熊怪居住在熊头？",a="该区域居住着木喉部族。与卡利姆多各地受恶魔腐蚀的其他许多熊怪部族不同，木喉部族在很大程度上抵御了这种污染，并与他们位于乌索兰和木喉要塞的主要聚落保持着联系。",al={"熊头的熊怪","熊头木喉","这里是什么熊怪部族"}},{q="熊头上方悬崖上的塔是什么？",a="那座悬崖上的尖塔属于大法师克希雷姆。他是一位古怪的人类法师，在艾萨拉隐居钻研学问，身边跟随着几名学徒和高等精灵同僚。",al={"熊头上方的塔","谁住在那座塔里","克希雷姆之塔"}}},fp="11,312,36.510.0,36.215.0,35.262.0,50.194.0"}
P.entries["subzone:beezil-s-wreck"] = {n="比吉尔的飞艇残骸",s="比吉尔的飞艇残骸位于尘泥沼泽的泥潭深处，是一艘不幸坠毁的地精飞艇遗址。这艘破碎的飞船位于Tabetha's Farm以东，其货舱内散落着补给品和不稳定的工程部件，吸引了许多拾荒者。",h="比吉尔的飞艇残骸位于尘泥沼泽的泥潭深处，是一艘不幸坠毁的地精飞艇遗址。这艘破碎的飞船位于Tabetha's Farm以东，其货舱内散落着补给品和不稳定的工程部件，吸引了许多拾荒者。",kw={"比吉尔","比吉尔的飞艇残骸","尘泥沼泽","瑟夫隆","塔贝萨","飞艇坠毁"},ang={["profession:Engineering"]="一艘地精飞艇扭曲的残骸中存放着不稳定的机械部件，尤其是任何技师都垂涎的瑟夫隆助推器。",["race:Gnome"]="检查竞争对手地精航空业那冒烟的遗骸，令人清醒地意识到非侏儒飞行设计中固有的危险。"},sec={{t="灾难性的着陆",b="隐藏在Tabetha's Farm以东潮湿泥泞之中的，是一架地精飞艇的残骸，被称为比吉尔的飞艇残骸。这艘飞艇在飞越卡利姆多向南运送货物的途中，不幸坠入了沼泽。虽然残骸在纠缠的芦苇丛中依然冒着烟，但它那古怪的船长比吉尔似乎已经从沼泽中消失了，只留下散落的板条箱和发出滴答声的机器，在盐水中慢慢腐烂。"},{t="泥潭中的打捞",b="尽管环境恶劣，坠机现场仍然是投机冒险家的首要目标。这艘飞艇携带了一批不稳定的货物，特别是那些在撞击中幸存下来的瑟夫隆助推器和沉重的板条箱。那些敢于涉水穿过周围野兽群的拾荒者，往往冒着生命危险试图在腐蚀性的沼泽水彻底毁掉这些货物之前，夺取剩余的失落补给。"}},faq={{q="什么是比吉尔的飞艇残骸？",a="比吉尔的飞艇残骸是一艘地精飞艇的坠毁地点，位于尘泥沼泽深处，Tabetha's Farm的正东方。这艘飞艇在穿过沼泽运送货物时坠毁了。",al={"比吉尔的飞艇残骸","尘泥沼泽坠毁的飞艇","这个残骸是什么"}},{q="飞行员比吉尔在哪里？",a="在坠机现场附近找不到飞行员比吉尔的踪影。他是逃入了险恶的荒野，还是完全逃离了这片沼泽，对于那些搜寻船体的人来说，这仍然是一个谜。",al={"比吉尔在哪里","谁是比吉尔","比吉尔的位置"}},{q="飞艇运载了什么贵重货物？",a="这艘飞艇装载了贸易货物和不稳定的地精技术，包括瑟夫隆助推器。这些贵重的工程组件使该地点成为冒险者和打捞者频繁光顾的目标。",al={"飞艇里有什么","瑟夫隆助推器","残骸货物"}}},fp="14,263,20.440.0,19.403.0,23.186.0,27.189.0,46.203.0"}
P.entries["subzone:beggar-s-haunt"] = {n="乞丐鬼屋",s="乞丐鬼屋是一座废弃的暴风城侦察塔，坐落在暮色森林东北部的山坡上，靠近通往逆风小径的山路。它最初是为监视王国东部边界而建，现在却成了被遗忘者深入联盟领地进行渗透的前哨站。",h="乞丐鬼屋是一座废弃的暴风城侦察塔，坐落在暮色森林东北部的山坡上，靠近通往逆风小径的山路。它最初是为监视王国东部边界而建，现在却成了被遗忘者深入联盟领地进行渗透的前哨站。",kw={"药剂师浮斯廷","乞丐鬼屋","死亡猎手扎瑞杜斯","暮色森林","骑士之穴","侦察塔","暴风城卫兵"},ang={["faction:Alliance"]="被遗忘者特工驻扎在紧邻主路的一座旧暴风城侦察塔内，这是部落在夜色镇家门口进行渗透的一个令人担忧的信号。",["race:Undead"]="对于被遗忘者的行动人员来说，这个隐蔽的前哨站为他们深入南方人类领地提供了一个罕见而危险的立足点。"},sec={{t="阴影中的瞭望塔",b="乞丐鬼屋矗立在密斯特曼托庄园东侧多雾的山丘之上，曾经是一座由暴风城卫兵驻守的活跃观察哨，负责保卫王国东部的入口。随着该地区陷入暮色森林的阴霾，王国巡逻队撤回了夜色镇，这座石塔便遭到了遗弃。今天，它所占据的战略制高点有着更加险恶的用途：被遗忘者的特工，包括皇家药剂师协会的成员和死亡猎手，利用这座破败的据点在联盟的眼皮底下进行研究并监视该地区。"},{t="骑士之穴与被遗忘的亡者",b="塔后有一条陡峭蜿蜒的小路，通向一个名为骑士之穴的僻静水潭和瀑布。这里有一座无名坟墓，两侧矗立着两尊不祥的兜帽石像，酷似黑暗之门两侧的守护者雕像。附近的埋葬地，包括一名无名士兵的墓地，诉说着在被遗忘者进驻这座瞭望塔之前，这条边境线上曾经发生的被遗忘的冲突。"}},faq={{q="为什么被遗忘者会出现在乞丐鬼屋？",a="来自幽暗城的特工，包括皇家药剂师协会的药剂师浮斯廷和死亡猎手扎瑞杜斯，已经占据了这座废弃的瞭望塔。从这里，他们可以监视联盟的动向，并悄悄地在遥远的南方进行实验。",al={"谁在乞丐鬼屋","为什么部落在这里","乞丐鬼屋的亡灵"}},{q="这座塔最初是被遗忘者建造的吗？",a="不是。这座塔是由暴风城王国建造的侦察前哨。当当地防御薄弱，该地区沦为暮色森林后，暴风城卫兵就放弃了它，使其空置，直到被遗忘者的侦察兵占据了这里。",al={"谁建造了乞丐鬼屋","乞丐鬼屋的历史","这是联盟的塔吗"}},{q="塔后面那座奇怪的坟墓是什么？",a="鬼屋后的小路下方是骑士之穴，这是一个僻静的瀑布水潭，里面有一座无名坟墓，周围环绕着与黑暗之门两侧纪念碑风格相同的兜帽守护者雕像。",al={"骑士之穴的雕像","塔后的坟墓","暮色森林的黑暗之门雕像"}},{q="乞丐鬼屋对联盟的旅行者怀有敌意吗？",a="是的。驻扎在塔里的被遗忘者都是经验丰富的特工，任何游荡到他们山坡据点附近的联盟冒险者都会遭到他们的攻击。",al={"他们会攻击我吗","乞丐鬼屋的守卫","乞丐鬼屋安全吗"}}},fp="14,182,27.414.0,38.363.0,41.226.0,48.190.0,43.171.0,48.135.0"}
P.entries["subzone:beren-s-peril"] = {n="博伦的巢穴",s="博伦的巢穴是位于银松森林安伯米尔西南方岩石山丘中一处隐蔽的山洞。这里是忠于死灵法师图勒·鸦爪的亡灵天灾残党所盘踞的堡垒，他们正密谋对抗附近的被遗忘者。",h="博伦的巢穴是位于银松森林安伯米尔西南方岩石山丘中一处隐蔽的山洞。这里是忠于死灵法师图勒·鸦爪的亡灵天灾残党所盘踞的堡垒，他们正密谋对抗附近的被遗忘者。",kw={"奥利斯特","安伯米尔","博伦的巢穴","鸦爪苦工","天灾军团","瑟伯切尔","银松森林","图勒·鸦爪"},ang={["faction:Horde"]="保卫银松森林崎岖的山路意味着必须在亡灵残党的巢穴切断瑟伯切尔与南方领土之间的补给线之前将其肃清。",["race:Undead"]="博伦的巢穴中的鸦爪爪牙是天灾军团残留影响的痛苦提醒，他们威胁着瑟伯切尔的安全，需要希尔瓦娜斯的忠诚者们迅速而无情地将其铲除。"},sec={{t="山丘中的隐患",b="博伦的巢穴隐蔽在安伯米尔西南方的高耸峭壁之中，由一个昏暗的洞穴和一条远离主干道的蜿蜒山径组成。第三次战争的浩劫过后，叛变的死灵法师图勒·鸦爪指挥的一群亡灵天灾残党在此建立了防御据点。鸦爪的奴仆们——摄政者、守卫和苦工——没有向黑暗女王屈服，也没有撤退到北方，而是聚集于此，秘密筹划对被遗忘者据点瑟伯切尔发动袭击。被遗忘者的侦察兵发现了他们的踪迹，这片寂静的悬崖随即变成了一个活跃的战场，部落的特工被派往此处，旨在阻止这场袭击发生之前消除威胁。"}},faq={{q="什么是博伦的巢穴？",a="它位于银松森林中安伯米尔的西南方，是介于中央公路和通往安伯米尔的支路之间的一处洞穴及周边山坡通道。",al={"博伦的巢穴","博伦的巢穴在哪里","博伦的巢穴洞穴"}},{q="谁控制着博伦的巢穴？",a="该洞穴被忠于死灵法师图勒·鸦爪的亡灵天灾所占据，其中包括鸦爪守卫、苦工和摄政者。",al={"谁住在博伦的巢穴","博伦的巢穴的敌人","鸦爪亡灵"}},{q="为什么被遗忘者在意这个地点？",a="被遗忘者的侦察兵发现躲藏在博伦的巢穴内的亡灵正在集结部队，准备对瑟伯切尔发动攻击，这促使暗影牧师奥利斯特下令对他们进行先发制人的打击。",al={"奥利斯特博伦的巢穴","为什么要攻击博伦的巢穴","瑟伯切尔威胁"}},{q="谁是图勒·鸦爪？",a="图勒·鸦爪是活跃在银松森林的一名强大的死灵法师，他控制着零散而充满敌意的无脑天灾爪牙，并利用博伦的巢穴和芬里斯城堡等地点威胁该地区。",al={"图勒·鸦爪","图勒银松森林"}}},fp="13,102,28.541.0,22.143.0,27.110.0,45.155.0,23.190.0"}
P.entries["subzone:bitter-reaches"] = {n="痛苦海岸",s="痛苦海岸是艾萨拉东北部一片崎岖且饱受风霜的荒野。这里几乎未受文明涉足，崎岖的悬崖间徘徊着捕食性的野兽和巨大的山岭巨人。",h="痛苦海岸是艾萨拉东北部一片崎岖且饱受风霜的荒野。这里几乎未受文明涉足，崎岖的悬崖间徘徊着捕食性的野兽和巨大的山岭巨人。",kw={"艾萨拉","痛苦海岸","奇美拉","角鹰兽","山岭巨人","山鼠草","软泥怪"},ang={["class:Hunter"]="痛苦海岸的悬崖巢穴是绝佳的狩猎场，这里生活着许多原始海岸特有的野生角鹰兽和极具攻击性的奇美拉。",["profession:Herbalism"]="痛苦海岸饱受风霜的高地是艾萨拉为数不多能生长珍贵山鼠草的地方，但你必须与奇美拉和巨人搏斗才能采集到它们。"},sec={{t="危险的海岸边境",b="痛苦海岸占据了艾萨拉东北部的悬崖，是一片俯瞰无尽之海、荒凉且未被驯服的岩石地带。成群的野生角鹰兽和双头奇美拉在高处筑巢，而酸性软泥怪则从寒冷的地面中渗出。沿着北部的高脊，巨大的山岭巨人占据了这些斜坡，驱逐了弱小的生物，使这片冰冷的区域成为了孤身旅者的致命险境。"},{t="峭壁上的植物",b="尽管这里寒风凛冽，掠食者横行，但这片崎岖的地貌却孕育着稀有的高山植物。稀疏的山鼠草丛顽强地依附在岩壁和风口上，这使得这片危险的地带偶尔也值得那些敢于避开巨人和领地意识极强的奇美拉、勇于冒险的草药师们涉足。"}},faq={{q="痛苦海岸在哪里？",a="痛苦海岸构成了艾萨拉的东北部区域，覆盖了海湾上方的高大海岸悬崖和山脊。",al={"痛苦海岸位置","痛苦海岸在哪里","痛苦海岸艾萨拉"}},{q="这里生活着哪些生物？",a="该地区是领地意识极强的角鹰兽、双头奇美拉和软泥怪的家园。高耸的山岭巨人在北部边界游荡。",al={"痛苦海岸怪物","痛苦海岸有什么生物","痛苦海岸的怪物"}},{q="为什么这里会有山岭巨人？",a="古老的山岭巨人栖息在艾萨拉北部的高峰和边缘地带，划定了属于自己的领地，并将大部分当地野生动物从它们的活动范围内驱逐出去。",al={"艾萨拉山岭巨人","为什么痛苦海岸有巨人"}},{q="在痛苦海岸能找到什么有价值的资源？",a="像山鼠草这样的稀有高海拔草药可以零星地在岩石露头和山脊线上找到。",al={"痛苦海岸草药","痛苦海岸采集"}}},fp="14,191,28.480.0,18.331.0,29.120.0,25.132.0,35.178.0,51.124.0"}
P.entries["subzone:black-channel-marsh"] = {n="黑水沼泽",s="黑水沼泽是一片位于湿地西南部阴暗泥泞的沼泽，紧邻通往米奈希尔港的主干道。这片潮湿的土地上到处都是极具攻击性的迅猛龙，对于在沿海低地穿行的粗心旅客和物资补给员来说，构成了直接的威胁。",h="黑水沼泽是一片位于湿地西南部阴暗泥泞的沼泽，紧邻通往米奈希尔港的主干道。这片潮湿的土地上到处都是极具攻击性的迅猛龙，对于在沿海低地穿行的粗心旅客和物资补给员来说，构成了直接的威胁。",kw={"黑水沼泽","沼泽","米奈希尔港","迅猛龙","湿地"},ang={["class:Hunter"]="对于那些想要驯服或追踪湿地凶猛迅猛龙的猎人来说，这片沼泽提供了一个就在大路旁、充满危险的试炼场。",["faction:Alliance"]="这条走廊是将米奈希尔港与卡兹莫丹其他地区连接起来的重要生命线，使得迅猛龙的入侵成为困扰旅行者的顽疾。"},sec={{t="米奈希尔大道的危机",b="黑水沼泽横跨主干道西南部的沼泽低地，在前往米奈希尔港的商队司机和信使中臭名昭著。虽然高架的道路给人一种安全的错觉，但停滞的水道和茂密的芦苇丛中栖息着极具领地意识的迅猛龙群。饥饿的野兽经常闯入交通要道，伏击那些偏离道路哪怕一两步的新兵和疲惫的旅人。"}},faq={{q="黑水沼泽在哪里？",a="黑水沼泽位于湿地的西南角，紧邻通往米奈希尔港的主要道路南侧。",al={"黑水沼泽在哪里","黑水沼泽位置","湿地黑水"}},{q="为什么这片沼泽被认为对旅行者很危险？",a="沼泽中布满了迅猛龙的巢穴。因为这些捕食者沿着沼泽边缘捕猎，它们经常潜行到路边，让毫无戒心的旅行者和低等级的冒险者措手不及。",al={"为什么很危险","黑水沼泽中的威胁","路上的迅猛龙"}},{q="谁经常经过这里？",a="联盟信使、矮人商人和往返于铁炉堡与米奈希尔港码头之间的旅行者经常经过这条紧邻沼泽的道路。",al={"谁使用这条路","这里的旅行者"}}},fp="19,171,26.373.0,37.117.0,53.145.0,36.144.0"}
P.entries["subzone:blackchar-cave"] = {n="黑炭谷",s="黑炭谷是一处神秘且被封闭的洞穴，隐藏在灼热峡谷的西南方岩壁中，靠近黑石山的山脚。它的入口被无法通过的碎石和岩块堵住了。",h="黑炭谷是一处神秘且被封闭的洞穴，隐藏在灼热峡谷的西南方岩壁中，靠近黑石山的山脚。它的入口被无法通过的碎石和岩块堵住了。",kw={"黑炭谷","黑石山","封闭的洞穴","灼热峡谷"},sec={{t="一处封闭的入口",b="黑炭谷隐藏在靠近黑石山通道的炽热岩壁之中，原本可能是深邃洞穴入口的地方，现在却是一堵严实的石墙。沉重的碎石和焦黑的矿渣堵住了入口，使得任何人都无法探索深埋在山根底下的隧道。周围荒凉的地形被灰烬和岩浆灼烧过，对于流浪者来说这里没有任何安身之处。"}},faq={{q="你能进入黑炭谷吗？",a="不能。黑炭谷的入口完全被坍塌的岩石、灰烬和碎石封死了。里面没有可以探索的开放内部空间。",al={"黑炭谷是否开放","进入黑炭谷","黑炭谷内部"}},{q="黑炭谷位于什么地方？",a="它位于灼热峡谷的西南角，坐落在靠近通往黑石山通道的岩石山麓旁。",al={"黑炭谷位置","黑炭谷在哪里"}}},fp="14,199,18.416.0,33.139.0,32.137.0"}
P.entries["subzone:blackfathom-deeps"] = {n="黑暗深渊",s="黑暗深渊是一处被淹没的地下神殿遗迹，埋藏在灰谷西北海岸的佐拉姆海岸之下。这里曾经是一座供奉月亮女神艾露恩的辉煌殿堂，但如今其被淹没的大厅已被纳迦、萨特和邪恶的暮光之锤教派所占据。",h="黑暗深渊是一处被淹没的地下神殿遗迹，埋藏在灰谷西北海岸的佐拉姆海岸之下。这里曾经是一座供奉月亮女神艾露恩的辉煌殿堂，但如今其被淹没的大厅已被纳迦、萨特和邪恶的暮光之锤教派所占据。",kw={"阿库麦尔","黑暗深渊","深渊","加摩拉","克尔里斯","萨利维丝","暮光之锤","佐拉姆海岸"},ang={["faction:Horde"]="对于部落来说，深渊的位置距离佐拉姆加前哨站近得令人不安；聚集在佐拉姆海岸的教徒和纳迦对该前哨站的守卫者构成了不可忽视的威胁。",["race:NightElf"]="对于卡多雷来说，这座古老神殿的亵渎是一件深重的伤痛，他们哀悼曾经神圣的艾露恩祭坛及其月亮井被虚空教徒和纳迦所玷污。"},sec={{t="从艾露恩的神殿到至暗深渊",b="在一万年前大分裂摧毁古老的卡利姆多之前，这座建筑群是一座供奉月亮女神艾露恩的神殿，并配有属于自己的月亮井。当永恒之井崩塌时，这座圣殿沉入海浪之下，人们一度认为它永远消失了。历经数千年，海岸线的退缩和地壳的变动使得其遗迹部分淹没在灰谷的悬崖之下。"},{t="阿库麦尔与邪教",b="近年来，一股上古之神的腐蚀力量从大地深处渗出，玷污了神殿内神圣的月亮井，而作为上古之神仆从的恐怖三头多头蛇阿库麦尔也从水中苏醒。在梦游者克尔里斯的指挥下，暮光之锤教派在被淹没的废墟中建立了一个据点。他们与萨利维丝率领的纳迦以及四处游荡的萨特一起，为了力量而将无辜者献祭给阿库麦尔。"}},faq={{q="黑暗深渊最初是为何而建？",a="它原本是一座供奉月亮女神艾露恩的暗夜精灵神殿，中心有一口神圣的月亮井，在大分裂期间沉入波涛之下。",al={"黑暗深渊历史","黑暗深渊是什么","黑暗深渊神殿"}},{q="为什么暮光之锤教派会在这里？",a="暮光之锤来到这里是为了崇拜阿库麦尔，这是一头原始的多头蛇，也是一位上古之神的仆从。在梦游者克尔里斯的领导下，教派成员为了换取黑暗力量，将无辜者献祭给这头野兽。",al={"为什么邪教徒在黑暗深渊","暮光之锤黑暗深渊","克尔里斯的目标"}},{q="入口在哪里？",a="入口隐藏在佐拉姆海岸沿线的洞穴废墟中，位于灰谷最西北的海岸上。冒险者必须穿过淹没的房间和充满敌意的纳迦前哨站，才能到达神殿的入口。",al={"黑暗深渊在哪里","黑暗深渊位置","如何进入黑暗深渊"}},{q="加摩拉是谁？",a="加摩拉是一只巨大的疯狂海龟，潜伏在神殿某个被淹没洞穴的小岛上，会攻击任何靠近的入侵者。",al={"巨型海龟首领","加摩拉背景故事","黑暗深渊乌龟"}}},fp="17,183,36.436.0,20.385.1,48.144.0,39.177.0,30.197.0,17.149.0"}
P.entries["subzone:blackrock-mountain"] = {n="黑石山",s="黑石山是一座高耸于燃烧平原和灼热峡谷之间的巨大活火山。它源于炎魔拉格纳罗斯那毁天灭地的召唤仪式，其深处盘踞着古老的矮人石工、交战的军队以及闷烧的恐怖存在。",h="黑石山是一座高耸于燃烧平原和灼热峡谷之间的巨大活火山。它源于炎魔拉格纳罗斯那毁天灭地的召唤仪式，其深处盘踞着古老的矮人石工、交战的军队以及闷烧的恐怖存在。",kw={"黑石山","黑石塔","燃烧平原","奥格瑞姆毁灭之锤","拉格纳罗斯","灼热峡谷","暗炉城","索瑞森"},ang={["faction:Horde"]="对于现代部落而言，黑石塔是他们过去在Doomhammer统治下遭受奴役与血腥岁月的象征，如今那里被拒绝接受萨尔领导的叛变兽人所占据。",["race:Dwarf"]="这座山代表了矮人历史上最黑暗的篇章：黑铁矮人悲剧性的愚行，不仅让他们失去了自由，还在东部王国的土地上留下了难以磨灭的伤痕。"},sec={{t="大灾变般的起源",b="Blackrock Mountain did not exist until the climax of the War of the Three Hammers two and a half centuries ago. Facing annihilation by the united armies of Ironforge and the Wildhammer clan, Sorcerer-Thane Thaurissan reached into the depths of the earth for a weapon. His reckless spell shattered the dimensional barriers and summoned Ragnaros the Firelord into Azeroth. The resulting apocalypse tore the Redridge range apart, gouging out the Searing Gorge and Burning Steppes while thrusting a colossal volcano into the sky. Thaurissan perished in the blast, and the surviving Dark Iron clan was bound into eternal servitude to the Firelord, carving their capital, Shadowforge City, deep within the mountain's roots."},{t="灰烬与鲜血的堡垒",b="在第一次和第二次战争期间，这座山脉有了新的严酷意义。在洗劫暴风城后，Orgrim Doomhammer肃清了暗影议会，并将黑石塔变成了部落的要塞首都。今天，这座山依然是残酷的战场：黑铁矮人和他们的元素主人占据着炽热的深渊，而叛变的黑石氏族兽人、龙人和他们的黑暗主人则盘踞在上方的高塔中。"}},faq={{q="黑石山是如何形成的？",a="它形成于大约250年前的三锤之战期间。索瑞森大帝为了击败敌对的矮人氏族，不顾一切地试图释放地下的深层能量，却意外地召唤了炎魔拉格纳罗斯，引发了一场创造了这座火山的末日爆炸。",al={"黑石山的起源","谁建造了黑石山","火山如何形成"}},{q="为什么它叫黑石山？",a="那个时代的记载并没有说明是谁最先为这座山命名。它的名字与黑石氏族兽人相同：Orgrim Doomhammer的部落在第二次战争期间将黑石塔作为首都，而黑石氏族的残党至今仍盘踞在塔中。",al={"黑石名字由来","以黑石氏族命名"}},{q="谁目前控制着黑石山？",a="这座山正处于一场残酷的冲突之中。受奴役的黑铁矮人在拉格纳罗斯的统治下控制着暗炉城的地下大厅，而黑石氏族的残党和黑龙人则统治着黑石塔的上层堡垒。",al={"谁住在黑石山","谁统治黑石山"}},{q="哪些地区通过黑石山连接？",a="黑石山的内部通道和锁链是连接北面的灼热峡谷和南面的燃烧平原的直接通道。",al={"如何通过黑石山","黑石山连接的地区"}}},fp="18,264,20.717.0,24.433.0,35.292.0,35.258.0,42.259.0,46.154.0"}
P.entries["subzone:blackrock-pass"] = {n="黑石小径",s="黑石小径是一条连接赤脊山北侧悬崖与燃烧平原干旱荒地的山间通道。穿过一扇厚重的铁门，这里标志着宁静的人类腹地与黑铁矮人和黑石兽人危险战区之间的陡然分界。对于任何徒步向北跋涉的疲惫旅人来说，这里是一道艰险且危险的边境线。",h="黑石小径是一条连接赤脊山北侧悬崖与燃烧平原干旱荒地的山间通道。穿过一扇厚重的铁门，这里标志着宁静的人类腹地与黑铁矮人和黑石兽人危险战区之间的陡然分界。对于任何徒步向北跋涉的疲惫旅人来说，这里是一道艰险且危险的边境线。",kw={"黑石兽人","黑石小径","燃烧平原","边境","大门","湖畔镇","赤脊山"},ang={["faction:Alliance"]="对于赤脊山的守卫者和暴风城王国来说，黑石小径是他们永久的恐惧来源，因为它为黑石兽人提供了一条直通南方人类领地的道路。"},sec={{t="焦灼的门槛",b="黑石小径开凿在犬牙交错的山脊之上，是赤脊山与燃烧平原之间的陆路通道。一条坚固的铁门矗立在这片多岩的边界上，将南方山谷中田园诗般的森林与湖泊，与彼端的火山废墟分隔开来。跨过这条界线，就意味着离开了受湖畔镇苦战中的民兵所保护的田园土地，进入了一片布满了火元素、龙人和敌对兽人战帮的开阔荒原。除非是为了前往黑石山那阴影笼罩之地，否则很少有人会徒步穿越此地。"}},faq={{q="黑石小径通往哪里？",a="Blackrock Pass connects the northern border of Redridge Mountains directly into the southern perimeter of the Burning Steppes. It is one of the direct overland gateways linking the southern Alliance territories to the foothills of Blackrock Mountain.",al={"黑石小径通向哪里","黑石小径目的地","从赤脊山到燃烧平原的路径"}},{q="从湖畔镇来的旅行者穿越小径安全吗？",a="不安全。小径以北的土地远比赤脊山周边的丘陵更为致命。燃烧平原上充斥着凶残的黑石兽人、巨大的火元素和黑龙幼龙，对于低等级冒险者和普通过路人来说，这里极其危险。",al={"我可以穿过黑石小径吗","黑石小径危险吗","黑石小径等级要求"}},{q="谁控制着黑石小径？",a="暴风城和部落都没有完全控制这条小径。它依然是一个充满争议、防御薄弱的咽喉要道，两侧不断有黑石兽人和野兽侵袭，山下赤脊山的镇守卫兵对此深感恐惧。",al={"谁拥有黑石小径","黑石小径的卫兵","黑石小径阵营控制权"}}},fp="14,409,20.586.0,31.250.0,58.290.0,28.240.0"}
P.entries["subzone:blackrock-stronghold"] = {n="黑石要塞",s="黑石要塞是一个戒备森严的营地，开凿在燃烧平原北部的岩架之中，位于黑石山入口正外方。它是黑石兽人及其在黑手氏族旗帜下盟友的主要前线驻地。",h="黑石要塞是一个戒备森严的营地，开凿在燃烧平原北部的岩架之中，位于黑石山入口正外方。它是黑石兽人及其在黑手氏族旗帜下盟友的主要前线驻地。",kw={"黑石氏族","黑石要塞","燃烧平原","黑手氏族","雷德·黑手"},ang={["faction:Alliance"]="这座要塞是第二次战争的残酷写照，坐落在距离暴风城王国北部边界仅一步之遥的地方。",["faction:Horde"]="对于萨尔的部落来说，黑石氏族代表了旧部落那段可耻的遗产——一群拒绝荣誉与和平、嗜血且腐化的残党。"},sec={{t="黑手氏族的驻地",b="该要塞蔓延在黑石山下方焦灼的丘陵地带，是黑石氏族在燃烧平原的主要地面基地。与萨尔的部落不同，这些兽人固守着他们好战的遗产，效忠于雷德·黑手以及盘踞在上方黑石塔内的龙人。"},{t="黑石塔前线",b="该要塞既是外部防御工事，也是向赤脊山及邻近人类领土发动进攻的集结地。这座堡垒时刻监视着通往该山的南部入口，挑战任何敢于穿越这片荒芜之地的挑战者。"}},faq={{q="什么是黑石要塞？",a="这是一座位于燃烧平原北部、黑石山外的军事要塞，作为黑石兽人氏族的外部驻地。",al={"这是什么地方","黑石要塞 燃烧平原","什么是黑石要塞"}},{q="这里的兽人对萨尔的部落友好吗？",a="不。黑石要塞的兽人属于黑手氏族，由雷德·黑手领导。他们拒绝萨尔的领导，对联盟和新部落都抱有敌意。",al={"这是部落吗","黑石兽人是部落吗","对部落友好吗"}}},fp="20,275,26.299.0,29.280.0,29.166.0,45.173.0"}
P.entries["subzone:blackthorn-ridge"] = {n="黑棘山",s="黑棘山是一片崎岖、荆棘丛生的山谷，隐藏在贫瘠之地南部，就在剃刀沼泽的正北方。这片区域到处是好斗的刺鬃野猪人，它们守卫着自己带刺的聚落。在高处的山脊之上坐落着兽人萨满布莱恩的营地，守护着一池格外纯净的山泉。",h="黑棘山是一片崎岖、荆棘丛生的山谷，隐藏在贫瘠之地南部，就在剃刀沼泽的正北方。这片区域到处是好斗的刺鬃野猪人，它们守卫着自己带刺的聚落。在高处的山脊之上坐落着兽人萨满布莱恩的营地，守护着一池格外纯净的山泉。",kw={"贫瘠之地","黑棘山","布莱恩","纯净之水","野猪人","剃刀沼泽","刺鬃"},ang={["class:Shaman"]="对于寻求布莱恩指导、希望在严酷干燥的平原中领悟自然水元素纯净之道的部落年轻萨满来说，这座山脊是一处重要的朝圣之地。",["faction:Horde"]="盘踞在山脊上的刺鬃野猪人威胁着穿过南贫瘠之地前往千针石林的部落补给线，这要求往来的商队必须保持时刻警惕。"},sec={{t="荆棘丛生的堡垒",b="黑棘山坐落在剃刀沼泽高耸的藤蔓附近，遍布着浓密而尖锐的荆棘丛。刺鬃野猪人将此地视为祖传领地，利用这些天然屏障伏击外来者，并以此为基地向南贫瘠之地发起突袭。尽管危险重重，旅行者们还是会寻找隐居的兽人萨满布莱恩，他住在山脊上方的一个营地里，守护着一口因其极佳的清澈度和精神纯净度而闻名整个卡利姆多的泉水。"}},faq={{q="黑棘山在哪里？",a="黑棘山位于贫瘠之地的最南端，正好处于围绕着剃刀沼泽的巨大荆棘丛之北，陶拉祖营地之南。",al={"黑棘山位置","黑棘山在哪里","如何找到黑棘山"}},{q="谁住在黑棘山？",a="山谷底部满是敌对的刺鬃野猪人。在荆棘丛上方高耸的岩石栖息处，住着兽人萨满布莱恩，他守护着附近的那个山泉。",al={"黑棘山住着谁","黑棘山的居民","黑棘山野猪人"}},{q="布莱恩营地下方的水池有什么特别之处？",a="尽管被干旱的平原和野猪人荆棘丛所带来的腐化所包围，但隐藏在山脊下的这口水池却拥有异常纯净、清澈的水，这使其成为了萨满祭司进行仪式的一处神圣的自然焦点。",al={"布莱恩水池","黑棘山之水","黑棘山泉水"}}},fp="16,184,22.429.0,26.124.0,30.162.0,45.191.0"}
P.entries["subzone:blackwolf-river"] = {n="黑狼河",s="黑狼河是一条发源于峭壁湖，流经石爪山脉的狂风峭壁的水道。它曾经是一条清澈的山间溪流，但如今其水质已因荆棘谷地精激进的伐木和工业运作而遭到严重污染。",h="黑狼河是一条发源于峭壁湖，流经石爪山脉的狂风峭壁的水道。它曾经是一条清澈的山间溪流，但如今其水质已因荆棘谷地精激进的伐木和工业运作而遭到严重污染。",kw={"黑狼河","峭壁湖","伐木","污染","石爪山脉","荆棘谷地精","狂风峭壁"},ang={["class:Druid"]="荆棘谷地精的木材开采作业对黑狼河的亵渎，是对塞纳里奥议会以及所有尊崇卡利姆多原始水域的人们的一种严重冒犯。",["race:Tauren"]="看到土地受损，水源被这些唯利是图的入侵者玷污，更加坚定了牛头人清除石爪山脉这种鲁莽工业毒害的决心。"},sec={{t="工业径流",b="黑狼河从峭壁湖流出，穿过狂风峭壁的盆地。这条本应纯净的高山支流，却成为了地精无节制开采的牺牲品。随着荆棘谷地精利用重型机械和圆锯清理周边的林地，淤泥、石油和伐木废料源源不断地渗入河水之中。这条被破坏的河流生动地展示了商业掠夺对石爪山脉荒野的威胁。"}},faq={{q="黑狼河的发源地和流向在哪里？",a="这条河流从高山之巅的峭壁湖流出，蜿蜒穿过狂风峭壁的伐木盆地。",al={"黑狼河源头","黑狼河在哪里","黑狼河位置"}},{q="为什么河水会被污染？",a="荆棘谷地精在整个狂风峭壁地区进行大规模的森林砍伐和机械伐木作业。他们蒸汽机械产生的径流、废料以及清理伐木产生的垃圾直接排入了水道。",al={"黑狼河为什么脏","黑狼河污染","荆棘谷地精污染"}},{q="目前是谁在河流沿岸运作？",a="荆棘谷地精占据了河岸，尽管遭到当地野生生物和原住民的抵制，他们仍利用周边的山谷进行重型木材采伐和机械作业。",al={"谁控制了黑狼河","黑狼河有哪些人","黑狼河附近的敌人"}}},fp="15,164,17.274.0,46.89.0,32.123.0,43.161.0"}
P.entries["subzone:blackwood-den"] = {n="黑木洞穴",s="黑木洞穴是一个被腐蚀的熊怪营地，坐落在黑海岸南部边缘，靠近灰谷的边界。这里曾经是一处宁静的住所，但如今洞穴和周围的营地已与黑木部族的其他成员一样陷入了疯狂。一位名叫沃科尔的暗夜精灵侦察兵被困在洞穴中，正等待着来自奥伯丁的援助。",h="黑木洞穴是一个被腐蚀的熊怪营地，坐落在黑海岸南部边缘，靠近灰谷的边界。这里曾经是一处宁静的住所，但如今洞穴和周围的营地已与黑木部族的其他成员一样陷入了疯狂。一位名叫沃科尔的暗夜精灵侦察兵被困在洞穴中，正等待着来自奥伯丁的...",kw={"灰谷","奥伯丁","黑木洞穴","黑木据点","黑海岸","熊怪","沃科尔"},ang={["class:Druid"]="德鲁伊们哀悼着熊怪的堕落，他们曾经是荒野坚定的守护者，而黑木洞穴的疯狂被视为卡利姆多被污染这一本质的又一痛苦症状。",["race:NightElf"]="对于奥伯丁的暗夜精灵来说，黑木部族因腐蚀而堕落是一件悲剧，将沃科尔从他们的魔爪中救出是一项紧迫的职责，以确保他们的人民在南部道路上的安全。"},sec={{t="被腐蚀的据点",b="黑木洞穴位于黑海岸与灰谷交界的南部边缘，由错综复杂的简陋营地和一座岩石洞穴组成。居住在这里的黑木熊怪已经屈服于席卷该地区的普遍腐蚀，对外界变得极其敌对。在洞穴深处，暗夜精灵沃科尔被困在这里，处境危险，急需从奥伯丁派遣的侦察兵和旅行者提供协助。"}},faq={{q="什么是黑木洞穴？",a="黑木洞穴是一个熊怪聚落和洞穴综合体，位于黑海岸的最南部，靠近灰谷边界。它是被腐蚀的黑木熊怪部族的据点。",al={"什么是黑木洞穴","黑木据点","黑木洞穴在哪里"}},{q="谁被困在黑木洞穴里？",a="洞穴里困着沃科尔，他是一名被困在敌后的暗夜精灵。遇到他的旅行者必须与奥伯丁的盟友配合，组织逃生并引导他安全离开洞穴。",al={"谁被困在洞穴里","谁是沃科尔","黑木洞穴里的精灵"}},{q="为什么这里的熊怪怀有敌意？",a="黑木熊怪已成为第三次战争后蔓延在黑海岸和卡利姆多的黑暗腐蚀的受害者。这种折磨使他们陷入了疯狂，导致他们攻击视线内的任何外来者。",al={"为什么黑木熊怪具有攻击性","黑木熊怪是邪恶的吗","黑海岸受腐蚀的熊怪"}}},fp="13,263,22.312.0,22.149.0,40.160.0,34.166.0"}
P.entries["subzone:blackwood-lake"] = {n="黑木湖",s="黑木湖是位于东瘟疫之地南部的一片受污染的水域，到处都是充满敌意且腐化的元素生物。这片区域被战争与悲剧的记忆所笼罩，银色黎明在此处设有一座小型前线营地，守护着这片土地。",h="黑木湖是位于东瘟疫之地南部的一片受污染的水域，到处都是充满敌意且腐化的元素生物。这片区域被战争与悲剧的记忆所笼罩，银色黎明在此处设有一座小型前线营地，守护着这片土地。",kw={"黑木","达隆郡","元素生物","霍古斯","湖泊","瘟疫之地"},ang={["class:Paladin"]="黑木湖周围受污染的水域和腐朽的气息，鲜明地展现了导致洛丹伦自然元素腐化的枯萎病，需要圣光的净化。",["race:Human"]="对于洛丹伦的人类来说，黑木湖是一个苦涩的提醒，让他们想起天灾军团是何等彻底地毒害了这片王国的腹地。"},sec={{t="被污染的记忆",b="和东维尔德的大部分地区一样，黑木湖也受到了猖獗的亡灵瘟疫的毒害。患病且污秽的水元素在浑浊的湖面下翻涌，攻击任何靠近岸边的人。"},{t="逝者的遗物",b="湖中还埋藏着达隆郡之战留下的阴森遗物。根据《达隆郡全史》等当地史料记载，天灾军团督军毁灭者霍古斯的头颅在被砍下后，被投入了黑木湖污浊的深处。附近，一名银色黎明军医正在一个小型的先遣哨站照料伤兵，在天灾军团的破坏阴影下艰难地维持着士兵们的生命。"}},faq={{q="什么生物潜伏在黑木湖中？",a="湖中遍布着被腐化的水元素。和瘟疫之地大部分的淡水一样，湖水受到了死灵法术径流和污秽的影响，将当地的灵魂扭曲成了狂暴且带有毒性的实体。",al={"水里有什么","湖中怪物","黑木湖中的元素生物"}},{q="银色黎明为什么驻扎在湖边？",a="银色黎明在湖边维持着一个小型的野战营地，一名银色黎明军医在那里照料受伤的步兵。它是为在达隆郡和附近天灾军团据点之间的道路上巡逻作战的部队所设立的紧急救护站。",al={"银色黎明营地","银色黎明军医","为什么这里有士兵"}},{q="什么达隆郡遗物被埋在黑木湖中？",a="根据《达隆郡的历史》记载，在达隆郡之战中作为主要天灾军团首领之一的毁灭者霍古斯，在被击败后，他的头颅被投入了湖水深处。",al={"毁灭者霍古斯的头颅","湖中的任务物品","达隆郡的历史湖泊"}}},fp="14,243,17.215.0,20.414.1,38.219.0,45.229.0,51.203.0"}
P.entries["subzone:bladefist-bay"] = {n="刃拳海湾",s="刃拳海湾是杜隆塔尔东部沿海的一段崎岖海岸，就在Gates of Orgrimmar外。这座海湾以卡加斯·刃拳的名字命名，面向无尽之海，周围有嶙峋的悬崖和附近的艾萨拉南岸。",h="刃拳海湾是杜隆塔尔东部沿海的一段崎岖海岸，就在Gates of Orgrimmar外。这座海湾以卡加斯·刃拳的名字命名，面向无尽之海，周围有嶙峋的悬崖和附近的艾萨拉南岸。",kw={"海湾","刃拳","杜隆塔尔","无尽之海","卡加斯","奥格瑞玛","shattered hand","骷髅石"},ang={["class:Rogue"]="Shattered Hand作为Horde的盗贼和刺客公会，在奥格瑞玛的阴影中运作，这使得这片海岸对隐秘行动人员来说有着一种静谧的共鸣。",["race:Orc"]="这座海湾承载着卡加斯·刃拳这个引以为傲而又残酷的名字，提醒着人们Shattered Hand氏族在Draenor所经历的试炼。"},sec={{t="无尽之海边的一座海湾",b="刃拳海湾沿着杜隆塔尔的东北边缘延伸，直接通向广阔的无尽之海。它两侧是岩石峭壁和危险的浪潮，位于奥格瑞玛主城的东面。正北方向，艾萨拉古老的红色悬崖和废墟在水对面隐约可见，使这座海湾成为了杜隆塔尔重要的海上边界。"},{t="Shattered Hand的阴影",b="这座海湾是为了纪念卡加斯·刃拳，他是著名的Shattered Hand氏族酋长，在Draenor旧Horde的试炼中，他砍下了自己的手并换成了一把利刃。这座海湾靠近骷髅石等地点（邪教徒和隐秘的潜行者网络在那里暗中活动），这呼应了这位赋予海湾名字的酋长所领导的氏族那种凶猛而无情的传统。"}},faq={{q="刃拳海湾是以谁的名字命名的？",a="这座海湾是以卡加斯·刃拳的名字命名的，他是传说中的Shattered Hand氏族酋长，因将断手换成致命的镰刀利刃而闻名。",al={"谁是刃拳","刃拳的名字由来","卡加斯刃拳海湾"}},{q="刃拳海湾位于哪里？",a="它位于杜隆塔尔的东北海岸，就在奥格瑞玛正门的东面，隔水与南边的艾萨拉相对。",al={"刃拳海湾位置","刃拳海湾在哪里","如何前往刃拳海湾"}},{q="刃拳海湾周围潜伏着什么威胁？",a="海岸线紧邻骷髅石，这是一个臭名昭著的洞穴，窝藏着术士、恶魔和邪恶的火刃氏族邪教徒。",al={"刃拳海湾的危险","刃拳海湾的敌人"}},{q="为什么这座海湾有时被称为垃圾堆？",a="那个时代的记录并没有这样称呼它。刃拳海湾只是奥格瑞玛东部杜隆塔尔海岸的一段岩石区域，向北隔水眺望艾萨拉。",al={"垃圾堆","刃拳漂浮物","海洋垃圾湾"}}},fp="13,176,22.306.0,28.330.0,33.155.0,31.124.0,39.117.0,46.146.0"}
P.entries["subzone:bloodfen-burrow"] = {n="鲜血沼泽墓穴",s="鲜血沼泽墓穴是位于尘泥沼泽西南部的一个洞穴，里面挤满了凶猛的迅猛龙。这些野兽占据了洞穴和周围的空地，彻底摧毁了一处曾经试图在这片湿地中生存的定居点遗迹。",h="鲜血沼泽墓穴是位于尘泥沼泽西南部的一个洞穴，里面挤满了凶猛的迅猛龙。这些野兽占据了洞穴和周围的空地，彻底摧毁了一处曾经试图在这片湿地中生存的定居点遗迹。",kw={"鲜血沼泽墓穴","鲜血沼泽迅猛龙","科泰罗的谜题","尘泥沼泽","迅猛龙洞穴"},ang={["class:Hunter"]="这里筑巢的鲜血沼泽迅猛龙是凶猛敏捷的野兽，非常适合那些寻找耐用、具有攻击性的沼泽同伴的猎人。"},sec={{t="掠食者的巢穴",b="鲜血沼泽墓穴坐落在尘泥沼泽的西南部，是该地区充满攻击性的鲜血沼泽迅猛龙的主要巢穴。洞口和周围的洼地到处都是迅猛龙群，它们被这处隐蔽的裂缝以及沼泽提供的丰富猎场所吸引。入口外散落着废墟和未知的定居点残骸，这冷酷地提醒着人们谁才是沼泽内部真正的主宰。旅行者们还私下传言，一位名叫科泰罗的冒险海盗将他的一条藏宝谜题线索留在了这个致命的巢穴中。"}},faq={{q="鲜血沼泽墓穴里住着什么？",a="这个墓穴被鲜血沼泽迅猛龙所占据。它们在洞穴内和周围的空地上建立了密集的筑巢地，攻击任何胆敢擅闯它们领地的愚蠢之徒。",al={"谁住在这里","鲜血沼泽墓穴迅猛龙","鲜血沼泽墓穴有什么怪物"}},{q="洞穴外面的废墟是什么？",a="洞穴外躺着一处无法辨认的定居点遗迹。迅猛龙摧毁了这个定居点，但其居住者的身份和命运并无记载。",al={"尘泥沼泽废墟定居点","谁建造了鲜血沼泽墓穴附近的棚屋","洞穴外的废墟"}},{q="为什么冒险者要搜寻鲜血沼泽墓穴？",a="除了猎杀凶猛的沼泽迅猛龙外，正在破解科泰罗的谜题的探险家们也必须冒险进入墓穴。这位海盗将他的一条谜题线索藏在了洞穴阴暗的深处。",al={"科泰罗的谜题鲜血沼泽","鲜血沼泽墓穴宝藏","鲜血沼泽墓穴任务"}}},fp="15,244,18.594.0,30.208.0,36.158.0,47.202.1"}
P.entries["subzone:bloodhoof-village"] = {n="血蹄村",s="血蹄村是一处位于莫高雷石牛湖畔的牛头人中心定居点。它以血蹄部族命名，是年轻的猎人和勇士从纳拉其营地出发前往雷霆崖途中遇到的第一个主要聚集点。在贝恩·血蹄的领导下，村庄协调着平原各地的本地防御、贸易和传统仪式。",h="血蹄村是一处位于莫高雷石牛湖畔的牛头人中心定居点。它以血蹄部族命名，是年轻的猎人和勇士从纳拉其营地出发前往雷霆崖途中遇到的第一个主要聚集点。在贝恩·血蹄的领导下，村庄协调着平原各地的本地防御、贸易和传统仪式。",kw={"贝恩·血蹄","血蹄村","纳拉其营地","科多兽","莫高雷","石牛湖","扎尔曼·双月"},ang={["faction:Horde"]="这个宁静的定居点是莫高雷南部平原与部落首都雷霆崖之间重要的中转站和后勤枢纽。",["race:Tauren"]="对于年轻的牛头人来说，进入血蹄村标志着他们从少年步入更广泛的部族责任和精神成熟的真正第一步。"},sec={{t="平原之心",b="血蹄村坐落在清澈的石牛湖畔，是莫高雷中部繁荣的商业、手工艺和庆典中心。在纳拉其营地完成试炼的年轻牛头人会来到这里，在继续前往雷霆崖的巨型台地之前磨练他们的技艺。这里也是耐心饲养野生科多兽作为坐骑的驯兽师们的家园。"},{t="领导与仪式",b="该地区的日常管理和防御工作由大酋长凯恩·血蹄之子，贝恩·血蹄负责。在他的注视下，勇士们被派遣去保卫草原，抵御狂暴的野生动物、刺背野猪人的入侵以及荆棘谷地精带来的阴影威胁。除了贝恩之外，像扎尔曼·双月这样的精神向导也在此照料着部族的内心生活，指引新手完成诸如幻象试炼之类的神圣旅程。"}},faq={{q="谁领导着血蹄村？",a="大酋长凯恩·血蹄之子，贝恩·血蹄领导着该定居点，并指挥其抵御针对中部平原的威胁。",al={"村庄领袖","贝恩·血蹄位置","谁负责血蹄村"}},{q="这里举行什么重大仪式？",a="像扎尔曼·双月这样的精神导师会指引年轻的牛头人完成传统的幻象试炼，这是通往成年之路必不可少的精神旅程。",al={"幻象试炼","精神试炼","扎尔曼·双月任务"}},{q="这个定居点以生产什么而闻名？",a="血蹄村是驯化和训练平原野生科多兽作为坐骑的主要枢纽。",al={"牛头人坐骑","科多兽驯化","血蹄战鼓"}},{q="旅行者在这里完成任务后去哪里？",a="一旦他们在莫高雷中部的任务完成，旅行者通常会被指引向北前往牛头人的主城——雷霆崖。",al={"血蹄村之后","离开血蹄村后去哪里","下一个枢纽"}}},fp="17,220,19.324.0,20.357.0,28.144.0,36.157.0,43.92.0,55.114.0"}
P.entries["subzone:bloodtooth-camp"] = {n="血牙营地",s="血牙营地是位于灰谷中部的一处充满敌意、遭受腐蚀的熊怪营地，坐落在弗伦河以西。在酋长兰·血牙的带领下，这些曾经爱好和平的生物已陷入黑暗的疯狂，攻击任何靠近的人。该营地是联盟斥候旨在净化周边林地的主要目标。",h="血牙营地是位于灰谷中部的一处充满敌意、遭受腐蚀的熊怪营地，坐落在弗伦河以西。在酋长兰·血牙的带领下，这些曾经爱好和平的生物已陷入黑暗的疯狂，攻击任何靠近的人。该营地是联盟斥候旨在净化周边林地的主要目标。",kw={"灰谷","血牙营地","弗伦河","熊怪","克罗格","莱恩的净化","兰·血牙"},ang={["faction:Alliance"]="对于联盟冒险者来说，血牙营地是一个局部的腐蚀热点，威胁着灰谷南部树林和月亮井的安全。",["race:NightElf"]="暗夜精灵将兰·血牙部族的疯狂状态视为他们古老祖地所遭受的严重腐蚀所导致的悲剧性征兆。"},sec={{t="被腐蚀的巢穴",b="血牙营地坐落在南部月亮井的西南方、弗伦河以西，是灰谷日益腐朽的残酷写照。居住在此的熊怪曾与卡利姆多的神圣荒野息息相关，但挥之不去的精神腐蚀已经吞噬了他们的部落。在兰·血牙的指挥下，他们带着狂暴的敌意守护着粗陋的定居点，无论是过往的旅行者还是暗夜精灵守卫都会遭到他们的袭击。"},{t="净化森林",b="由于兰·血牙的团伙对附近的圣地构成了直接威胁，联盟哨兵及其盟友无法对此营地坐视不管。作为恢复森林和谐努力的一部分，即协助莱恩·狼行者的净化工作，克罗格指引冒险者潜入营地，除掉兰·血牙并消灭他那凶残的保镖。"}},faq={{q="血牙营地位于何处？",a="血牙营地位于灰谷中部，弗伦河正西方，就在南部月亮井的西南方。",al={"血牙营地位置","血牙营地在哪里","寻找血牙营地"}},{q="为什么这里的熊怪带有敌意？",a="和灰谷各处的许多熊怪部落一样，血牙部族已成为荒野中挥之不去的黑暗恶魔腐蚀的受害者。这使他们陷入疯狂，并对所有外来者表现出无尽的攻击性。",al={"为什么血牙熊怪会攻击人","血牙腐蚀","这里的熊怪是邪恶的吗"}},{q="谁领导着血牙营地的熊怪？",a="营地由兰·血牙统治，他是一位凶猛的酋长，与他的私人保镖团一同指挥着当地的熊怪。",al={"血牙营地首领","兰·血牙","谁领导血牙营地"}},{q="为什么联盟会派遣斥候来这里？",a="在莱恩的净化工作期间，被流放的熊怪克罗格指引联盟勇士突袭该营地，消灭兰·血牙，并消除他那被腐蚀的追随者对该地区构成的威胁。",al={"血牙营地任务","为什么击杀兰·血牙","克罗格任务"}}},fp="15,233,15.324.0,20.264.1,33.110.0,34.171.0,42.74.0,39.194.0"}
P.entries["subzone:bloodvenom-falls"] = {n="血毒瀑布",s="血毒瀑布是一道高耸、污浊的瀑布，从费伍德森林北部腐化的悬崖上倾泻而下。它那充满毒素的流水汇入了血毒河，将恶魔滋生的腐化带下山脉，一直蔓延到下游的土地。",h="血毒瀑布是一道高耸、污浊的瀑布，从费伍德森林北部腐化的悬崖上倾泻而下。它那充满毒素的流水汇入了血毒河，将恶魔滋生的腐化带下山脉，一直蔓延到下游的土地。",kw={"血毒瀑布","血毒河","腐化","黑海岸","费伍德森林","软泥怪","瀑布","急弯河"},ang={["class:Druid"]="血毒瀑布受污染的水流对塞纳里奥议会来说是一个苦涩的景象，它成为了将费伍德森林的邪恶疾病带入下方土地的主要通道。",["race:NightElf"]="对于暗夜精灵来说，看到血毒瀑布汇入黑海岸那条受污染的急弯河，是对其祖居地和海岸避难所的直接威胁。"},sec={{t="腐化的源头",b="血毒瀑布从费伍德森林的峭壁上倾泻而下，是卡利姆多古老森林所遭受的最为触目惊心的创伤之一。这里原本是一道纯净的山涧，但在第三次战争期间，受到恶魔魔法和燃烧军团残党的侵蚀，水流变成了一种充满毒性的污泥。瀑布直接汇入血毒河，蜿蜒流经费伍德森林的中心地带。此后，这股被污染的湍流冲下山坡，在黑海岸变成了污秽的急弯河，将枯萎与凋零带到了费伍德森林那早已受损的边界之外。"},{t="生态毒害",b="来自血毒瀑布的恶性径流不仅仅是让河床变色，它还在扭曲所触及的一切。瀑布喷溅出的水雾周围，沼泽岸边滋生出了扭曲的树妖、病态的野兽和充满攻击性的软泥怪。对于试图遏制费伍德森林腐化的德鲁伊和典狱官来说，这道瀑布是一个令人心寒的警示，提醒着人们卡利姆多北部的水源在其源头处依然深受重创。"}},faq={{q="血毒瀑布的水流向何处？",a="瀑布直接汇入血毒河。这条河流穿过费伍德森林，随后从山上倾泻而下进入黑海岸，在那里变成了受到腐蚀的急弯河。",al={"血毒河的流向","血毒瀑布河流路径","水流向哪里排放"}},{q="为什么瀑布会被腐蚀？",a="在第三次战争期间，燃烧军团的恶魔魔法渗透了该地区，腐化了费伍德森林的野生林地。滋养瀑布的泉水和高山溪流吸收了这种邪能枯萎，使水变成了有毒的淤泥。",al={"为什么血毒瀑布是绿色的","为什么水被毒化了","是什么腐蚀了血毒瀑布"}},{q="瀑布的腐化会影响其他区域吗？",a="是的。水流从费伍德森林倾泻而下，越过西部的山脊进入黑海岸，形成了被污染的急弯河，并将腐化蔓延至海岸方向。",al={"费伍德森林是否污染了黑海岸","它如何影响黑海岸","黑海岸河流污染"}},{q="血毒瀑布的水可以被净化吗？",a="塞纳里奥议会一直在寻找净化费伍德森林的方法，但河水中蕴含的恶魔污染量巨大且浸透深重，使得治愈这道瀑布成为了一项极其艰巨且尚未解决的任务。",al={"德鲁伊能修复血毒瀑布吗","血毒瀑布可以净化吗","清理瀑布"}}},fp="16,219,17.560.0,17.381.0,48.179.0,31.240.0,52.164.0,47.203.0"}
P.entries["subzone:bloodvenom-post"] = {n="血毒岗哨",s="血毒岗哨是一处偏远的部落定居点，坐落在费伍德森林西部的岩石峭壁上，俯瞰着黑海岸。其牛头人风格的建筑和牛头人卫兵在这个饱受恶魔污染和野生生物腐化侵蚀的地区提供了一个立足点。",h="血毒岗哨是一处偏远的部落定居点，坐落在费伍德森林西部的岩石峭壁上，俯瞰着黑海岸。其牛头人风格的建筑和牛头人卫兵在这个饱受恶魔污染和野生生物腐化侵蚀的地区提供了一个立足点。",kw={"血毒岗哨","血毒河","黑海岸悬崖","费伍德森林","部落岗哨","牛头人"},ang={["faction:Horde"]="作为部落在费伍德森林中唯一的坚固避风港，这座营地在极其充满敌意的荒野中提供了安全、住所和行动基地。",["race:Tauren"]="牛头人勇士驻守在此，旨在研究燃烧军团造成的环境破坏，并对抗正在摧毁这片土地自然之灵的腐化。"},sec={{t="危险的立足点",b="血毒岗哨隐藏在黑海岸上方的高耸悬崖边，沿着费伍德森林主干道旁受腐化的血毒河南岸前行即可到达。这座营地采用传统的牛头人帐篷、图腾和岗哨建造，为在凋零森林中探索的部落成员提供了一个至关重要的行动基地。在这里，侦察兵追踪着不断逼近的恶魔势力，研究水域中蔓延的腐化，并试图监控那些因燃烧军团残留力量而变异的敌对野生生物。"},{t="纵览山脊的目光",b="除了观察费伍德森林受到污染的荒野，营地还直接坐落在悬崖边，可以俯瞰黑海岸的北部。其孤立的位置有着双重作用：既能让部落部队随时了解暗夜精灵在西海岸沿线的动向，又能避开穿梭于森林中央道路的联盟巡逻队。"}},faq={{q="血毒岗哨位于何处？",a="血毒岗哨隐藏在费伍德森林中部的西侧山脊上。若要从南北走向的主路前往那里，需沿着血毒河南岸向西走，沿一条蜿蜒绕过岩石山坡的小径前进。",al={"寻找血毒岗哨","如何前往血毒岗哨","血毒岗哨指引"}},{q="谁控制着这座岗哨？",a="血毒岗哨是一座由牛头人守卫、并采用传统牛头人建筑风格的部落岗哨。",al={"谁负责管理血毒岗哨","血毒岗哨阵营"}},{q="为什么这座岗哨叫血毒？",a="它得名于邻近的血毒河，由于渗入森林的恶魔腐化，河水已被玷污并带有毒性。",al={"为什么叫血毒","血毒名称含义"}},{q="这里的侦察兵面临什么威胁？",a="岗哨面临着来自费伍德森林本土腐化生物的持续压力，包括狂暴的豹、受污染的软泥怪和扭曲的树人，此外还有该区域内暗影议会和燃烧军团残党的恶魔威胁。",al={"血毒的敌人","什么袭击血毒岗哨"}}},fp="15,243,21.534.0,21.345.0,33.232.0,26.90.0,33.146.0,37.244.0"}
P.entries["subzone:bloodvenom-river"] = {n="血毒河",s="血毒河是一条穿过费伍德森林中心地带的肮脏水道，这条河流充满了导致这座古老森林枯萎的恶魔腐蚀。其腐臭的河水顺流而下，穿过山脉进入黑海岸，演变成了被污染的急弯河。",h="血毒河是一条穿过费伍德森林中心地带的肮脏水道，这条河流充满了导致这座古老森林枯萎的恶魔腐蚀。其腐臭的河水顺流而下，穿过山脉进入黑海岸，演变成了被污染的急弯河。",kw={"血毒河","腐蚀","黑海岸","费伍德森林","软泥怪","被污染的水","急弯河"},ang={["class:Druid"]="血毒河是卡利姆多神圣森林遭到亵渎的明证，它将邪能腐蚀带到了各个地区，昭示着自然亟需恢复。",["race:NightElf"]="对于卡多雷而言，眼看着他们祖先林地的水流通过急弯河毒害了黑海岸，这时刻提醒着他们燃烧军团留下的伤痛挥之不去。"},sec={{t="腐蚀之脉",b="血毒河贯穿了费伍德森林被腐蚀的核心地带，成为了这片土地精神与物质衰败的开放式导管。河岸边充斥着邪恶的软泥怪、变异的野兽，以及燃烧军团入侵后留下的肮脏径流。河道中的腐蚀性极强，足以污染远超费伍德森林本身的土地，并作为急弯河向西流向黑海岸的沿海森林。"}},faq={{q="为什么河流会被腐蚀？",a="这条河流流经费伍德森林中心，那是一片古老的暗夜精灵森林，在第三次大战期间深受燃烧军团恶魔魔法的扭曲。腐蚀彻底渗透进土地和水流中，将河流变成了充满有毒淤泥和坏死软泥的导管。",al={"血毒河污染","为什么水是绿色的","费伍德森林河流毒素"}},{q="血毒河的流向是怎样的？",a="这条河穿过费伍德森林受污染的山谷，随后穿过山脉流入黑海岸。在山脊之外，其被腐蚀的水流以急弯河的名义继续向下游奔涌。",al={"血毒河路径","它流向哪里","流向黑海岸的河流"}},{q="河岸边生活着哪些生物？",a="水域和泥泞的河岸边栖息着有毒的软泥怪、扭曲的野生动物，以及被致命的恶魔枯萎病所吸引或创造出来的腐化掠食者。",al={"血毒河野生动物","血毒河附近的怪物","河流中的怪物"}}},fp="16,261,20.435.0,27.281.0,37.206.0,41.151.0"}
P.entries["subzone:bluefen"] = {n="蓝色沼泽",s="蓝色沼泽是一片湿漉漉的沼泽地，位于尘泥沼泽北部，紧邻蕨墙村以东。这里不仅潜伏着极具攻击性的湿地掠食者，也成为了塞拉摩渗透者监控当地部落动态的据点。",h="蓝色沼泽是一片湿漉漉的沼泽地，位于尘泥沼泽北部，紧邻蕨墙村以东。这里不仅潜伏着极具攻击性的湿地掠食者，也成为了塞拉摩渗透者监控当地部落动态的据点。",kw={"蓝色沼泽","蕨墙","鳄鱼","尘泥","沼泽","塞拉摩渗透者"},ang={["faction:Alliance"]="尽管野生野兽使旅行变得危险，但塞拉摩侦察兵利用蓝色沼泽茂密的植被，密切监视着附近的食人魔营地。",["faction:Horde"]="蓝色沼泽位于蕨墙村以东，对部落勇士构成了双重威胁：凶猛的沼泽野兽，以及监视你们的石槌盟友的警惕的塞拉摩渗透者。"},sec={{t="充满争议的沼泽",b="蓝色沼泽位于蕨墙村的石槌食人魔据点以东，体现了尘泥沼泽未被驯服的危险特质。这片潮湿的沼泽地里到处都是掠食性野兽，包括迅猛龙、巨型蜘蛛、食腐鸟类和潜伏的鳄鱼。除了自然界的掠食者，旅行者还必须提防那些在阴暗地形中潜行、监视部落并试图将人类影响力深入沼泽地带的塞拉摩渗透者。"}},faq={{q="蓝色沼泽位于何处？",a="蓝色沼泽位于尘泥沼泽北部，就在蕨墙村以东。",al={"蓝色沼泽位置","蓝色沼泽在哪里","蓝色沼泽地图"}},{q="在蓝色沼泽能遇到什么威胁？",a="这片沼泽到处都是危险的野生动物，包括蜘蛛、鳄鱼、迅猛龙和沼泽鸟类。此外，隐秘的塞拉摩渗透者也会在此巡逻，对部落的旅行者构成威胁。",al={"蓝色沼泽敌人","蓝色沼泽有什么生物","蓝色沼泽怪物"}},{q="为什么塞拉摩侦察兵会出现在蓝色沼泽？",a="塞拉摩渗透者以蓝色沼泽为据点，监视着尘泥沼泽北部，观察邻近的蕨墙村石槌食人魔定居点，并巡逻着沼泽中充满争议的道路。",al={"塞拉摩渗透者","为什么联盟会在这里","塞拉摩间谍"}}},fp="7,259,15.437.0,25.85.0,37.198.0,43.196.0"}
P.entries["subzone:bluegill-marsh"] = {n="蓝腮沼泽",s="蓝腮沼泽是位于湿地西部的一片泥泞沼泽，是敌对的蓝腮鱼人部落大举定居的地方。这些水栖人形生物在被称为“戈布勒”的野蛮首领统治下，对水道和棚屋进行了严密的防御。前往西部沼泽的旅行者必须小心穿行，以免被困在浅滩中遭到包围。",h="蓝腮沼泽是位于湿地西部的一片泥泞沼泽，是敌对的蓝腮鱼人部落大举定居的地方。这些水栖人形生物在被称为“戈布勒”的野蛮首领统治下，对水道和棚屋进行了严密的防御。前往西部沼泽的旅行者必须小心穿行，以免被困在浅滩中遭到包围。",kw={"蓝腮","蓝腮沼泽","戈布勒","米奈希尔","鱼人","沼泽","湿地"},ang={["faction:Alliance"]="由于地理位置距离米奈希尔港不远，好战的蓝腮鱼人对穿过湿地西部的旅行者和补给线构成了持续的麻烦。"},sec={{t="蜂拥而至的威胁",b="蓝腮沼泽坐落在湿地西部的泥泞平原之中，这里到处都是淤泥、芦苇，以及当地鱼人刺耳的战吼声。蓝腮部落在死水中建立了粗糙的原始营地，宣称这片领土属于他们。与沼泽中那些孤立的野兽不同，这些鱼人以紧密的群体为单位生活和狩猎。米奈希尔港的谨慎游侠和侦察兵都知道，贸然进入他们的领地会引来四面八方的迅速伏击，尤其是当强大的首领戈布勒在浑浊的浅滩中徘徊时。"}},faq={{q="蓝腮沼泽是什么地方？",a="蓝腮沼泽是湿地西部的一个泥泞子区域。这里是好战的蓝腮鱼人部落的主要居所和筑巢地。",al={"蓝腮沼泽在哪里","这个地方是什么","湿地鱼人沼泽"}},{q="谁在统治这片沼泽？",a="蓝腮部落由一个强大而凶残的鱼人戈布勒领导，他守护着密集的营地，并会击杀任何踏入他们水域的陆行者。",al={"湿地鱼人首领","戈布勒","谁领导蓝腮鱼人"}},{q="为什么独自在此旅行很危险？",a="这里的鱼人很少单独行动。它们通常两三个结成紧密的小队聚集在棚屋和岸边，使得落单的旅行者很容易在深陷减速的泥地中被淹没。",al={"为什么这里有这么多鱼人","蓝腮沼泽难吗","鱼人仇恨"}},{q="为什么旅行者要冒险进入蓝腮沼泽？",a="来自米奈希尔港等附近定居点的侦察兵和冒险者经常被派往沼泽，以削减好战的鱼人数量，并找回被抢到营地中的货物。",al={"为什么要去这里","蓝腮沼泽任务","访问原因"}}},fp="14,179,17.370.0,23.133.0,25.153.0,41.165.0,45.182.0"}
P.entries["subzone:bolgan-s-hole"] = {n="波尔甘的洞穴",s="波尔甘的洞穴是一个位于凄凉之地吉尔吉斯村南面悬崖中的地下洞穴。它是吉尔吉斯半人马部族的圣所，也是其最高酋长和神圣大地圣物的所在地。",h="波尔甘的洞穴是一个位于凄凉之地吉尔吉斯村南面悬崖中的地下洞穴。它是吉尔吉斯半人马部族的圣所，也是其最高酋长和神圣大地圣物的所在地。",kw={"波尔甘的洞穴","半人马","凄凉之地","吉尔吉斯","沙卡可汗","瑟莱德丝之泪"},ang={["class:Shaman"]="这个洞穴残酷地展示了当崇拜大地与瑟莱德丝公主的暴力遗产挂钩，而非与自然的灵魂平衡挂钩时，信仰会如何被扭曲。"},sec={{t="吉尔吉斯的权力中心",b="波尔甘的洞穴开凿在俯瞰吉尔吉斯营地的崎岖峭壁深处，是该部族的Command Center。统治部族的可汗就在这里召集部下，周围环绕着经验丰富的卫兵和部族中最有影响力的萨满祭司。这个洞穴不仅是天然的堡垒，还能抵御敌对部族，尤其是东面嗜血的玛格拉姆半人马。"},{t="大地公主之泪",b="除了军事上的重要性外，这个洞穴对吉尔吉斯人还有着深远的宗教意义。被称为瑟莱德丝之泪的发光蓝色矿物结构从潮湿的岩壁上生长出来。吉尔吉斯萨满狂热地采集并守卫着这些晶体，将其视为神圣的祝福，认为它们能带来半人马种族的原始土元素之母——瑟莱德丝公主的地下庇护。"}},faq={{q="波尔甘的洞穴位于何处？",a="波尔甘的洞穴是一处位于吉尔吉斯村南部的洞穴，隐藏在凄凉之地南部的山丘中。",al={"波尔甘的洞穴位置","波尔甘的洞穴在哪里","波尔甘洞穴入口"}},{q="谁居住在波尔甘的洞穴里？",a="洞穴内居住着吉尔吉斯半人马的高层领导，包括他们的部族可汗——例如沙卡可汗——以及他们的核心护卫和神秘的萨满祭司。",al={"谁在波尔甘的洞穴里","波尔甘的洞穴首领","吉尔吉斯可汗位置"}},{q="洞穴里的发光蓝色晶体是什么？",a="这些晶体被称为瑟莱德丝之泪。吉尔吉斯人将它们视为大地之母恩赐的有形体现，认为这些石头能为拥有它们的人提供神秘的保护。",al={"波尔甘的洞穴里的蓝色晶体","瑟莱德丝之泪","波尔甘的洞穴岩石"}},{q="玩家可以安全地进入波尔甘的洞穴吗？",a="默认情况下，洞穴内的吉尔吉斯半人马对局外人抱有敌意。然而，通过屠杀他们不共戴天的死敌——玛格拉姆部族，与吉尔吉斯人结盟的旅行者可以获得声望，从而得以平静地进入洞穴。",al={"波尔甘的洞穴有敌意吗","吉尔吉斯声望友好","我可以进入波尔甘的洞穴吗"}}},fp="13,217,24.365.0,27.409.0,31.116.0,31.173.0,51.204.0,39.230.0"}
P.entries["subzone:bones-of-grakkarond"] = {n="格拉卡隆之骨",s="格拉卡隆之骨是一具巨大的青铜龙骸骨，在希利苏斯中部的烈日下显得苍白。这头倒下的巨龙在远古的流沙之战中被杀，如今成为了异种虫的阿努比萨斯哨兵们视为神圣的肃穆纪念碑。",h="格拉卡隆之骨是一具巨大的青铜龙骸骨，在希利苏斯中部的烈日下显得苍白。这头倒下的巨龙在远古的流沙之战中被杀，如今成为了异种虫的阿努比萨斯哨兵们视为神圣的肃穆纪念碑。",kw={"阿努比萨斯","格拉卡隆之骨","青铜龙","格拉卡隆","无疤者奥斯里安","希利苏斯","流沙之战"},ang={["race:NightElf"]="这具骸骨是对流沙之战的冷峻提醒，在那场战争中，卡多雷和四大巨龙军团并肩作战，抵御了其拉虫人的猛烈进攻。"},sec={{t="流沙之战的纪念碑",b="在希利苏斯中部风沙肆虐的沙丘上，横卧着格拉卡隆那巨大的肋骨和头骨。这是一头在远古流沙之战中丧生的青铜龙。在那场千年前的天启般冲突中，这头伟大的巨龙被“无疤者”奥斯里安击倒，这是一名被这座城市王国的黑暗力量所提拔的阿努比萨斯战士。对于阿努比萨斯来说，这个战场战利品是他们凌驾于巨龙军团之上的神圣证明，他倒下的地方至今未曾被触动。"}},faq={{q="这些是谁的骨头？",a="这是青铜龙军团中一头伟大的青铜龙——格拉卡隆的遗骸。一千年前，在流沙之战期间，他倒在了对抗安其拉虫族军队的战斗中。",al={"格拉卡隆是谁","哪头龙死在这里","希利苏斯巨龙骸骨"}},{q="谁杀死了格拉卡隆？",a="格拉卡隆是被阿努比萨斯战士“无疤者”奥斯里安所杀。奥斯里安战胜了这头青铜巨龙，为他赢得了巨大的声望以及来自安其拉主宰们的黑暗祝福。",al={"谁杀了那条龙","格拉卡隆是怎么死的"}},{q="为什么阿努比萨斯崇拜这个地方？",a="阿努比萨斯认为这具骨架是神圣的，因为它纪念了他们对一支强大的巨龙军团的决定性胜利。它矗立在开阔的沙丘上，象征着他们在面对那些企图将他们封印的人时所展现出的强大力量。",al={"为什么骨头是神圣的","阿努比萨斯骸骨"}}},fp="19,269,32.494.0,22.205.0,22.185.0,39.228.0"}
P.entries["subzone:booty-bay"] = {n="藏宝海湾",s="藏宝海湾是一座庞大的海盗避风港，修建在荆棘谷南端的陡峭海崖之上，由热砂港的黑水掠夺者负责运营。陆路入口位于一具巨鲨残骸的大张口中，这里作为中立港口受到严密的治安管理，在装备精良的地精打手虎视眈眈的监视下，联盟和部落成员在此和平共处。",h="藏宝海湾是一座庞大的海盗避风港，修建在荆棘谷南端的陡峭海崖之上，由热砂港的黑水掠夺者负责运营。陆路入口位于一具巨鲨残骸的大张口中，这里作为中立港口受到严密的治安管理，在装备精良的地精打手虎视眈眈的监视下，联盟和部落成员在...",kw={"黑水掠夺者","血帆海盗","藏宝海湾","棘齿城","里维加兹","salty sailor tavern","卡拉·海角","热砂港","荆棘谷"},ang={["class:Rogue"]="作为众所周知的无赖天堂，藏宝海湾充斥着地下交易人、销赃者、锁箱和秘密情报贩子，他们随时准备用秘密换取金币。",["faction:Alliance"]="在暴风城受保护的边界以南很远的地方，藏宝海湾为联盟旅行者提供了稀有的中立设施、飞行路线和直达卡利姆多的航线。"},sec={{t="无赖与利润的巢穴",b="最初，这里被称为黑水湾，曾是一处人类定居点，后来被丛林巨魔占领，最终被热砂港的地精夺回。如今，这里是一个国际贸易枢纽，也是无赖、放逐者和商人的避风港。在大财主里维加兹和舰队指挥官卡拉·海角的管理下，他们坐镇在Salty Sailor Tavern的阳台上，这座港口看似无法无天，实则管理严格：只要遵守财团的和平协议并缴纳港口费用，任何人都可以尽情饮酒、交易或雇佣雇佣兵。"},{t="水上的威胁",b="藏宝海湾繁忙的码头将东部王国与横跨无尽之海的棘齿城直接相连，使其成为贸易和跨大陆旅行的重要枢纽。然而，其巨大的财富也引来了不断的敌意。该镇的主要宿敌是血帆海盗，这是一支极具侵略性的海盗舰队，他们不断劫掠黑水港的船只，在荆棘谷海岸巡航，并积极策划彻底摧毁和洗劫这座地精港口。"}},faq={{q="谁统治着藏宝海湾？",a="该港口由热砂港的重要人物大财主里维加兹统治，他与黑水掠夺者的牛头人指挥官舰队指挥官卡拉·海角紧密合作。两人的办公地点都在俯瞰港口的Salty Sailor Tavern上层甲板上。",al={"藏宝海湾领袖","谁掌管藏宝海湾","藏宝海湾老板"}},{q="为什么联盟和部落玩家可以在这里和平共处？",a="藏宝海湾由中立的热砂港控制，该组织将利润和商业置于阵营冲突之上。财团维持着严格的中立性，欢迎任何拥有金币的人，并会对任何胆敢在此挑起争斗的人祭出精锐的地精打手。",al={"为什么藏宝海湾是中立的","藏宝海湾安全区","部落可以在这里攻击联盟吗"}},{q="血帆海盗是什么人？",a="血帆海盗是一个敌对的亡命之徒集团，与黑水掠夺者处于水火不容的战争状态。他们控制着荆棘谷南海岸的船只，并积极策划攻占藏宝海湾，攫取其利润丰厚的港口。",al={"血帆海盗","为什么血帆海盗仇恨藏宝海湾","血帆海盗背景故事"}},{q="藏宝海湾的船只驶向哪里？",a="从下层码头出发的客船横跨无尽之海，直达贫瘠之地的棘齿城港口小镇，这是连接东部王国南部与卡利姆多的主要中立交通路线。",al={"藏宝海湾船只目的地","船去哪里","前往卡利姆多的船"}},{q="海湾入口处伫立的巨大雕像是什么？",a="这座身份不明的地精张开双臂的巨大雕像矗立在港口外侧的加尼罗哨站。它既是导航灯塔，也是欢迎进港商船和海盗船员的地标。",al={"藏宝海湾雕像","藏宝海湾巨像","岛上的雕像"}}},fp="9,361,30.547.0,20.455.0,20.281.0,55.273.0,33.237.0,38.224.0,56.223.0"}
P.entries["subzone:bough-shadow"] = {n="大树荫",s="大树荫是位于灰谷东北角落的一片隐蔽的林地，在林歌神殿的东面。它的中心是一棵巨大的古树，树根盘踞在一个通往翡翠梦境的古老传送门之上。",h="大树荫是位于灰谷东北角落的一片隐蔽的林地，在林歌神殿的东面。它的中心是一棵巨大的古树，树根盘踞在一个通往翡翠梦境的古老传送门之上。",kw={"灰谷","大树荫","龙人","梦境追猎者","翡翠梦境","大树","绿龙","幻影","传送门"},ang={["class:Druid"]="大树荫对德鲁伊来说是神圣的土地，这里有连接艾泽拉斯与绿龙军团领域及翡翠梦境的实体入口之一。",["race:NightElf"]="这棵巨大的古树及其沉睡的传送门位于林歌神殿深处，象征着卡多雷与翡翠梦境之间紧密联系的活生生的见证。"},sec={{t="通往梦境的门户",b="大树荫坐落着罕见的大树之一，其根系深深扎入大地，围绕着一个通往翡翠梦境的天然交汇点。如今，这片宁静而威严的林地由绿龙军团严密把守。幻影和梦境追猎者等翡翠幼龙在树冠上方盘旋，而翡翠龙人巡逻队和先知们则对底部旋转的绿色传送门保持着警惕而坚定的监视，驱逐任何未经许可靠近的凡人。"}},faq={{q="这里发光的绿色传送门是什么？",a="大树根部旋转的漩涡是一个直接通往艾泽拉斯未受干扰的灵界——翡翠梦境的门户。这是散布在世界各地的几个此类天然交汇点之一。",al={"大树荫传送门","大树荫里的传送门是什么","灰谷绿色传送门"}},{q="为什么绿龙要守护大树荫？",a="伊瑟拉的绿龙军团负责守护翡翠梦境及其通往物质世界的直接通道。翡翠幼龙和龙人巡逻大树荫，以确保没有腐化势力或入侵者溜过这个临界点。",al={"为什么灰谷里有龙","绿龙军团 大树荫","为什么绿龙在这里"}},{q="玩家可以进入传送门吗？",a="不能。这个门户对物质世界的凡人来说仍然是严密封闭的，靠得太近会招致周围精英龙族守卫的愤怒。",al={"我可以穿过传送门吗","进入大树荫传送门","如何进入梦境传送门"}}},fp="12,156,22.380.0,38.169.0,44.207.0,29.108.0"}
P.entries["subzone:boulder-gor"] = {n="博德戈尔",s="博德戈尔是一座位于阿拉希高地西部的崎岖山丘，坐落在废墟般的人类王国激流堡正北方。它是巨石拳食人魔及其不同寻常的盟友——枯木森林巨魔的活跃营地。",h="博德戈尔是一座位于阿拉希高地西部的崎岖山丘，坐落在废墟般的人类王国激流堡正北方。它是巨石拳食人魔及其不同寻常的盟友——枯木森林巨魔的活跃营地。",kw={"阿拉希高地","博德戈尔","巨石拳","食人魔","激流堡","枯木"},ang={["faction:Alliance"]="对于寻求收复激流堡的联盟军队来说，博德戈尔构成了潜伏在这个陨落王国北门口的严重威胁。",["race:Troll"]="来访高地的暗矛巨魔在这里找不到亲缘关系：博德戈尔的枯木森林巨魔对所有外来者——包括其他巨魔部族——都怀有深远的古老仇恨。"},sec={{t="食人魔与巨魔的巢穴",b="博德戈尔耸立在激流堡破败的城墙以北，是一座被巨石拳氏族占领的陡峭断崖。其阴影中坐落着Boulderfist Outpost土丘，使其成为巨石拳食人魔在整个高地权力的中心堡垒。独特的是，这里的食人魔与枯木部族的森林巨魔共享营火与防御工事，其中包括向氏族的蛮力提供黑暗魔法支持的阴影施法者。这种相互合作对任何路过阿拉希中部道路的旅人构成了持续的威胁。"},{t="周边领地",b="博德戈尔周围的山坡俯瞰着阿拉希西部开阔的高地。博德戈尔被夹在辛迪加渗透的激流堡废墟与平原上狂野的元素之地之间，依然是一个守备森严的敌对据点，展现着部落团结，对抗着联盟和部落的漫游者。"}},faq={{q="什么是博德戈尔？",a="博德戈尔是阿拉希高地激流堡以北的一座高地和营地。这里聚居着大量的巨石拳食人魔和枯木森林巨魔。",al={"博德戈尔在哪里","博德戈尔信息","这是什么地方"}},{q="为什么森林巨魔会和食人魔住在这里？",a="枯木巨魔和巨石拳食人魔在阿拉希维持着一种务实的同盟关系。双方都寻求保持对高地的统治并抵御敌对派系，将巨魔的暗影法术与食人魔的蛮力结合在了一起。",al={"为什么这里有巨魔","枯木食人魔联盟","巨魔与食人魔"}},{q="博德戈尔附近有什么主要地标？",a="博德戈尔位于激流堡的正北方，而Boulderfist Outpost的食人魔土丘就坐落在山丘之中。",al={"附近地点","博德戈尔旁边有什么","地标"}},{q="博德戈尔对部落或联盟友好吗？",a="都不友好。博德戈尔的巨石拳食人魔和枯木巨魔对联盟和部落完全敌对，他们会积极地从外来者手中捍卫自己的山丘。",al={"我可以安全地去那里吗","博德戈尔是敌对的吗"}}},fp="11,249,25.542.0,21.312.0,20.171.0,50.216.0,42.122.0,49.174.0"}
P.entries["subzone:boulder-lode-mine"] = {n="石矿洞",s="石矿洞是一处开凿在贫瘠之地东北部丘陵中的大型矿坑。虽然兽人的旗帜和瞭望塔表明这里最初是由部落建立的，但现在它已经被冷酷无情的荆棘谷地精牢牢掌控并运营。",h="石矿洞是一处开凿在贫瘠之地东北部丘陵中的大型矿坑。虽然兽人的旗帜和瞭望塔表明这里最初是由部落建立的，但现在它已经被冷酷无情的荆棘谷地精牢牢掌控并运营。",kw={"boss copperplug","石矿洞","迪兹维格","矿工的财富","主动式负载平衡器说明书","贫瘠之地","荆棘谷地精"},ang={["faction:Horde"]="看到荆棘谷地精在带有部落标志的防御工事中运作，这令人恼火地提醒着人们这个地精卡特尔组织是如何在卡利姆多土地上激进扩张的。",["profession:Mining"]="深邃的挖掘隧道直接切入干旱的丘陵，露出了丰富的矿脉，荆棘谷地精正在无情地掠夺这些资源。"},sec={{t="企业所有权",b="石矿洞洞口残留的风化兽人建筑表明，部落曾经拥有或建立了这里。然而如今，这里到处都是在Boss Copperplug指挥下工作的荆棘谷地精监工和执行者。为了搜寻珍贵的矿石、高产的宝石和工业机械，这个地精辛迪加组织在峡谷中进行露天开采，完全不顾及当地的生态环境或工人的死活。"},{t="宝石与蓝图",b="石矿洞开采出财富的消息已经传到了棘齿城。码头管理员迪兹维格已经派遣雇佣兵去窃取传说中在矿洞里发现的一颗巨大绿宝石，而那些试图理解复杂地精机械的工程师们也知道，Boss Copperplug将关键的操作手册藏在了他的营地里。"}},faq={{q="谁控制着石矿洞？",a="这座矿井由荆棘谷地精在Boss Copperplug的直接授权下运营，并由全副武装的企业执行者和劳工监工守卫。",al={"谁经营石矿洞","石矿洞首领","谁在石矿洞里"}},{q="部落最初拥有这座矿井吗？",a="幸存的兽人木制结构、瞭望塔和风化的部落旗帜有力地表明，在荆棘谷地精介入并夺取控制权之前，部落最初建立或占领了该地点。",al={"石矿洞的兽人旗帜","部落矿井","为什么会有部落旗帜"}},{q="为什么码头管理员迪兹维格对这个地方感兴趣？",a="迪兹维格听说石矿洞里的一名矿工挖出了一颗异常巨大且珍贵的绿宝石，于是他雇佣了冷酷的自由职业者潜入矿洞，试图将其偷走以分一杯羹。",al={"迪兹维格矿井任务","贫瘠之地绿宝石任务","矿工的财富"}},{q="Boss Copperplug与主动式负载平衡器有什么联系？",a="Boss Copperplug拥有附近发现的神秘主动式负载平衡器机械的基本操作手册，棘齿城的工程师们派遣冒险者从他的手下那里取回这本书及其散页。",al={"石矿洞主动式负载平衡器说明书","copperplug的说明书","里里·格里希戈布矿井"}}},fp="17,158,15.288.0,19.272.0,31.119.0,39.154.0,53.152.0,56.177.0"}
P.entries["subzone:boulderfist-hall"] = {n="石拳大厅",s="石拳大厅是一座防御严密的食人魔土丘，坐落在阿拉希高地的南部丘陵中，位于萨多尔大桥以北。它是石拳食人魔当地的据点，在科格雷什·冷怒的指挥下，他们对邻近的贸易路线和山谷施加着残暴的影响力。",h="石拳大厅是一座防御严密的食人魔土丘，坐落在阿拉希高地的南部丘陵中，位于萨多尔大桥以北。它是石拳食人魔当地的据点，在科格雷什·冷怒的指挥下，他们对邻近的贸易路线和山谷施加着残暴的影响力。",kw={"阿拉希高地","石拳","石拳大厅","科格雷什·冷怒","食人魔土丘","法拉纳克斯","萨多尔大桥"},ang={["faction:Alliance"]="由于石拳食人魔的位置恰好在萨多尔大桥上方，他们对从铁炉堡向北进入阿拉希的联盟信使和增援部队构成了持续的伏击威胁。",["faction:Horde"]="确保阿拉希高地的安全需要打破食人魔的独立势力，清理南部的山脊以保障落锤镇的部落移动安全。"},sec={{t="残暴力量的堡垒",b="石拳大厅开凿在阿拉希高地崎岖的南面悬崖中，是该地区石拳氏族的主要堡垒。在土制防御工事和深邃洞穴的掩护下，食人魔蛮兵和法师在此维持着一个防御森严的定居点，距离枯木村和萨多尔大桥的战略要地仅几步之遥。在土丘深处，盘踞着他们的区域首领科格雷什·冷怒，以及像法拉纳克斯这样的执行者。从这座据点出发，食人魔对周围的道路施加了暴力控制，使得任何往来于阿拉希和湿地之间的和平通行对旅行者和补给商队而言都充满危险。"}},faq={{q="石拳大厅是什么地方？",a="这是一座防御严密的食人魔土丘和洞穴综合体，位于阿拉希高地南部，是石拳氏族在该领土上的行动基地。",al={"这是什么地方","石拳土丘","阿拉希食人魔洞穴"}},{q="谁统治着石拳大厅？",a="该据点由食人魔首领科格雷什·冷怒领导，他与像法拉纳克斯这样的勇士一起，在土丘内部的深处洞穴中指挥着他的氏族。",al={"谁领导石拳大厅","阿拉希食人魔首领","科格雷什"}},{q="为什么这个地点具有战略重要性？",a="它靠近萨多尔大桥，这使得石拳食人魔能够威胁连接阿拉希高地与卡兹莫丹的重要陆路路线，切断交通并猎杀过往的旅人。",al={"为什么食人魔在这里","萨多尔大桥的危险"}},{q="石拳食人魔与附近的枯木巨魔结盟了吗？",a="没有记录显示有正式结盟。石拳食人魔与枯木村的森林巨魔比邻而居；而在高地的其他地方，在博德戈尔，枯木巨魔甚至与食人魔共享地盘。双方对所有阵营的外来者都保持敌对态度。",al={"食人魔和巨魔是盟友吗","枯木氏族联盟"}}},fp="16,315,27.633.0,25.157.0,27.153.0,45.188.0,61.274.0"}
P.entries["subzone:boulderfist-outpost"] = {n="Boulderfist Outpost",s="Boulderfist Outpost是坐落于阿拉希高地博德戈尔食人魔聚居地深处的一座堡垒土丘。它作为内部巢穴和关押区，栖息着好战的Boulderfist食人魔以及少数枯木巨魔。",h="Boulderfist Outpost是坐落于阿拉希高地博德戈尔食人魔聚居地深处的一座堡垒土丘。它作为内部巢穴和关押区，栖息着好战的Boulderfist食人魔以及少数枯木巨魔。",kw={"阿拉希","博德戈尔","boulderfist","俘虏","kovork","食人魔土丘","囚犯","枯木"},ang={["faction:Alliance"]="在阿拉希旅行的联盟斥候应该避开这座土丘，因为里面的Boulderfist执法者会攻击任何看到的入侵者。",["faction:Horde"]="Boulderfist食人魔不区分阵营，它们攻击部落流浪者和攻击联盟对手一样毫不手软。"},sec={{t="土丘之中的要塞",b="Boulderfist Outpost开凿在阿拉希西部的土地与岩石之中，是博德戈尔的核心。虽然粗暴的执法者统治着地表的聚居地，但前哨站内部集中了部落的核心力量，并提供了一个阴暗的地下庇护所。少数枯木巨魔巫医偶尔会混在食人魔中，暗示了脆弱的部落间合作。"}},faq={{q="Boulderfist Outpost位于何处？",a="Boulderfist Outpost是位于阿拉希高地西部大范围区域内，博德戈尔大型食人魔聚居地中的一处内部土丘。",al={"boulderfist outpost位置","boulderfist outpost在哪里","boulderfist土丘入口"}},{q="为什么食人魔前哨站里会有巨魔？",a="枯木森林巨魔居住在阿拉希高地附近，偶尔会与Boulderfist食人魔共享地盘。几名枯木巫医可以在前哨站深处与食人魔一同钻研他们的法术。",al={"为什么枯木巨魔在这里","boulderfist里的巨魔","阿拉希的枯木巨魔"}},{q="谁被关押在前哨站里？",a="目前已知没有被点名的俘虏被关押在前哨站中。其潮湿的走廊属于Boulderfist执法者和少数枯木巫医，任何闯入内部的人都应该做好战斗准备，而不是去营救什么人。",al={"boulderfist俘虏","谁被困在boulderfist","阿拉希食人魔手中的俘虏"}},{q="谁领导着前哨站内的食人魔？",a="虽然该氏族的粗暴执法者在内部巡逻，但一只名为Kovork的异常凶猛的食人魔潜伏在土丘中，是一个值得注意的威胁。",al={"kovork","阿拉希boulderfist首领","boulderfist稀有"}}},fp="19,239,29.390.0,37.154.0,44.240.0,33.219.0,39.150.0"}
P.entries["subzone:boulderslide-cavern"] = {n="滚岩洞穴",s="滚岩洞穴是位于石爪山脉滚岩峡谷最深处的一处地下巢穴。这里是当地滚岩狗头人的主要巢穴和挖掘场，他们执着地挖掘着，寻找发光的矿物结构。",h="滚岩洞穴是位于石爪山脉滚岩峡谷最深处的一处地下巢穴。这里是当地滚岩狗头人的主要巢穴和挖掘场，他们执着地挖掘着，寻找发光的矿物结构。",kw={"滚岩","洞穴","土灵","goggeroc","狗头人","共鸣晶石","石爪山脉"},ang={["class:Shaman"]="共鸣晶石和沉睡的土灵Goggeroc都与原始大地魔法产生了共鸣，这是世界古老造石者留下的回响。",["profession:Mining"]="滚岩氏族的狗头人正在洞穴中疯狂地工作，他们不停地挖掘，试图发现发着光的魔法共鸣晶石矿脉。"},sec={{t="共鸣晶石挖掘场",b="滚岩狗头人深入石爪山脉的岩缝中，将滚岩洞穴建成了他们的据点。与那些仅仅寻求栖身之所的普通害虫不同，这些狗头人疯狂地挖掘着“共鸣晶石”，这是一种嵌在岩石中、稀有且会发光的紫色水晶。这些晶石散发着残留的土灵魔法，让这些生物陷入了一种防御性的狂乱，对抗任何接近他们挖掘场地的入侵者。"},{t="沉睡的巨人",b="在洞穴更深处，鲁莽的挖掘行动揭开了一些古老的秘密。嵌入地下岩层中的是一个共鸣晶石容器，里面装着来自远古时代的沉睡土灵Goggeroc。狗头人在这个神秘遗物周围进行着无休止的挖掘，这可能会唤醒这个被原始岩石魔法灌注的存在，从而对整个峡谷构成突如其来的危险。"}},faq={{q="狗头人在这里挖掘什么？",a="狗头人正在挖掘共鸣晶石，这是一种嵌在洞穴岩壁中的稀有紫色水晶。这种矿石嗡嗡作响，带有微弱的土灵魔法痕迹，使它成为一种宝贵的战利品，也让狗头人们狂热地守卫着他们的藏宝处。",al={"什么是共鸣晶石","石爪山脉的紫色水晶","狗头人为什么挖掘"}},{q="Goggeroc是谁？",a="Goggeroc是一位古老的土灵，沉睡在洞穴深处的一个共鸣晶石容器中。狗头人在他安息之处周围的挖掘行动可能会打扰他长达数个世纪的沉睡。",al={"goggeroc背景故事","滚岩洞穴里的土灵","洞穴里的沉睡巨人"}},{q="滚岩洞穴在哪里？",a="洞穴入口位于滚岩峡谷的最尽头，坐落在石爪山脉南部多岩的山区中，就在通往贫瘠之地的道路东北方。",al={"滚岩洞穴位置","如何找到滚岩洞穴","洞穴在哪里"}},{q="为什么部落会对这个洞穴感兴趣？",a="部落监视着这个洞穴，以遏制向峡谷蔓延的、极具侵略性的狗头人，同时也是出于对他们挖掘出的共鸣晶石的魔法特性的兴趣。",al={"部落滚岩洞穴任务","为什么派我去滚岩洞穴"}}},fp="19,146,16.272.0,20.259.1,33.160.0,16.173.1,37.155.0,43.151.0"}
P.entries["subzone:boulderslide-ravine"] = {n="滚岩峡谷",s="滚岩峡谷是一条崎岖偏僻的峡谷，隐藏在石爪山脉的中央山峰之中，通过蛛网小径即可到达。这里基本上避开了部落与联盟之间的直接冲突，它是通往滚岩洞穴的岩石通道，依然是野生山地野兽的栖息地。",h="滚岩峡谷是一条崎岖偏僻的峡谷，隐藏在石爪山脉的中央山峰之中，通过蛛网小径即可到达。这里基本上避开了部落与联盟之间的直接冲突，它是通往滚岩洞穴的岩石通道，依然是野生山地野兽的栖息地。",kw={"滚岩洞穴","滚岩峡谷","峭壁风暴者","山羊","石爪","蛛网小径"},ang={["profession:Mining"]="峡谷陡峭的岩壁是观察因山脉岩石移动而暴露出来的矿脉的可靠地点。",["race:Tauren"]="小侧洞内褪色的艺术品带有明显的牛头人部落标记，暗示了穿越石爪山脉高地的祖先足迹。"},sec={{t="宁静的山间小径",b="滚岩峡谷隐藏在蛛网小径之外，是石爪山脉高地上一道狭窄的岩石裂缝。尽管伐木工、暗夜精灵和部落在该地区为木材和圣林争斗不休，但这条崎岖的山口却相对未受到军事力量的干扰。野生山羊和诸如峭壁风暴者之类的游荡岩石野兽是这里的当地动物，它们在险峻的岩架和陡峭的石墙间穿行。勘探者们也密切关注着峡谷，因为沿着通往洞穴网络深处的岩石斜坡上经常会出现丰富的矿脉。"},{t="岩石上的痕迹",b="滚岩洞穴入口对面有一个安静的小洞穴，俯瞰着峡谷。洞穴内点着粗糙的火把，堆放着风化的补给木桶，内壁上绘有原始的部落画作。这些粗糙的艺术品与古代牛头人的设计惊人地相似，暗示着在现代冲突席卷这些山脉之前，土著部落早已在这些岩脊中旅行或寻求过临时避难所。"}},faq={{q="滚岩峡谷位于哪里？",a="滚岩峡谷位于石爪山脉。沿着蛛网小径进入更高的岩脊即可到达。",al={"滚岩峡谷位置","如何前往滚岩峡谷","滚岩峡谷在哪里"}},{q="什么生物栖息在滚岩峡谷？",a="峡谷内主要居住着当地的野生动物，特别是山羊和危险的岩石潜伏者，例如峭壁风暴者。",al={"滚岩峡谷怪物","滚岩峡谷里有什么"}},{q="滚岩洞穴对面那个废弃的洞穴是什么？",a="洞穴入口对面是一个小凹室，里面点着火把，存放着旧木桶。其石墙上展示着部落象形图，类似于传统的牛头人艺术，表明过去曾有当地的流浪者或猎人在此使用过。",al={"滚岩废弃洞穴","滚岩峡谷中的洞穴","石爪牛头人洞穴"}},{q="滚岩峡谷有什么重要意义？",a="它是通往深藏于山中的地下巢穴滚岩洞穴的天然通道，并为途经此地的旅行者提供了宝贵的矿石露头。",al={"滚岩峡谷的作用","滚岩峡谷用途"}}},fp="19,276,21.430.0,19.349.0,37.110.0,43.113.0,59.228.0,39.178.0"}
P.entries["subzone:brackenwall-village"] = {n="蕨墙村",s="蕨墙村是部落在尘泥沼泽的主要前哨站，坐落在该区域西北角的沼泽地带中。在巨龙摧毁了他们位于南部的原始定居点后，幸存的石槌食人魔建立了这座村庄。它目前是一个脆弱的据点，周围环绕着联盟间谍、逃兵和黑龙军团。",h="蕨墙村是部落在尘泥沼泽的主要前哨站，坐落在该区域西北角的沼泽地带中。在巨龙摧毁了他们位于南部的原始定居点后，幸存的石槌食人魔建立了这座村庄。它目前是一个脆弱的据点，周围环绕着联盟间谍、逃兵和黑龙军团。",kw={"蕨墙村","德拉兹辛比","尘泥沼泽","渗透者","莫格穆洛克大王","食人魔","帕瓦尔·里瑟","石槌"},ang={["faction:Alliance"]="蕨墙村深入敌对领土，但关于失踪外交官和流氓塞拉摩逃兵的调查将把大胆的特工直接带到食人魔营地的边缘。",["faction:Horde"]="蕨墙村是你在沼泽中唯一的庇护所和飞行连接点；保卫它能确保部落维持一个重要的监听哨站，并作为防御塞拉摩的侧翼。"},sec={{t="石槌的避难所",b="当黑龙人将石槌食人魔赶出他们位于南部沼泽的古老家园——石槌村时，他们的领袖莫格穆洛克大王——雷克萨的继任者——带领幸存者向北进入沼泽，建立了蕨墙村。该定居点围绕着传统的土墩、茅屋和一座旧的守望塔而建，为饱受磨难的氏族提供了一个可以防御的避难所。尽管与部落结盟，但该村庄正遭受内部腐化的困扰：莫格穆洛克大王无所作为，囤积物资并拒绝面对龙族的威胁，将氏族的精神和战术指导留给了食人魔巫师德拉兹辛比和部落特使等人物。"},{t="沼泽中的眼睛",b="除了内部机能障碍外，蕨墙村还受到外部威胁的困扰。塞拉摩的渗透者不断潜伏在丛林中，窥探村庄的动向并向那座岛屿堡垒报告。与此同时，一名被废弃哨塔驱逐的塞拉摩逃兵帕瓦尔·里瑟被怀疑从前哨站偷走了重要物资。在东面警惕的目光和南部徘徊的黑龙夹击下，蕨墙村成为了部落孤立的集结地，用以抵御联盟和奥妮克希亚的子嗣。"}},faq={{q="为什么会有效忠部落的食人魔在这里？",a="这些是石槌食人魔，这是一个在杜隆塔尔建国期间由勇士雷克萨引入现代部落的荣誉氏族。雷克萨在击败了他们以前的领袖后成为了他们的酋长，在将领导权移交给莫格穆洛克大王之前，将该氏族束缚在萨尔大酋长的新联盟中。",al={"为什么有部落食人魔","石槌氏族背景故事","这些食人魔是谁"}},{q="为什么石槌食人魔定居在这里而不是留在他们旧的家园？",a="他们位于尘泥沼泽南部的祖传定居点被黑龙军团占领并夷为平地。莫格穆洛克大王带领流离失所的幸存者向北进入沼泽，将蕨墙村建立为一个坚固的避难所。",al={"石槌村发生了什么","为什么是蕨墙村","食人魔难民"}},{q="谁负责蕨墙村？",a="莫格穆洛克大王领导着这个定居点，但他的统治遭到了广泛的怨恨。他没有号召族人夺回家园或对抗巨龙，而是蜷缩在村庄里，迫使食人魔巫师德拉兹辛比和部落使节来处理日常危机。",al={"蕨墙村领袖","谁管理蕨墙村","莫格穆洛克大王"}},{q="为什么村外有塞拉摩间谍？",a="尽管塞拉摩和奥格瑞玛之间存在脆弱的停战协议，但吉安娜·普罗德摩尔的军队对尘泥沼泽内任何部落部队的动向都保持着严密的监视。渗透者在蕨墙村的周边潜行，报告食人魔的兵力和部落的行动。",al={"尘泥沼泽的联盟间谍","塞拉摩渗透者","为什么塞拉摩在监视"}}},fp="19,343,23.633.0,15.527.1,47.294.0,71.229.0,40.263.0,50.262.0"}
P.entries["subzone:brackwell-pumpkin-patch"] = {n="布莱克威尔南瓜田",s="布莱克威尔南瓜田是艾尔文森林东南部的一处被占据的农庄。这里曾是布莱克威尔家族的家园，如今农田和农舍已被迪菲亚潜行者彻底霸占，作为其行动据点。这里不仅是潜行同谋者的碰头点，还是走私赃金的中转站。",h="布莱克威尔南瓜田是艾尔文森林东南部的一处被占据的农庄。这里曾是布莱克威尔家族的家园，如今农田和农舍已被迪菲亚潜行者彻底霸占，作为其行动据点。这里不仅是潜行同谋者的碰头点，还是走私赃金的中转站。",kw={"布莱克威尔","迪菲亚","艾尔文","埃尔兰·德鲁格莫尔","收货人莫根","公主","南瓜田","苏瑞娜·卡蕾顿"},ang={["class:Warlock"]="农场的棚屋里藏着逃亡的学徒苏瑞娜·卡蕾顿，她偷走的血石颈环是召唤虚空行者所必需的物品。",["faction:Alliance"]="这片被占领的南瓜田是迪菲亚潜行者在艾尔文森林内最靠东的行动基地之一，直接威胁着附近的农场和贸易路线。"},sec={{t="强盗的避风港",b="布莱克威尔农场位于斯通菲尔德农场东南方，曾经是艾尔文森林一片高产的农田。如今，合法的农场主已不知所踪，他们要么是被日益猖獗的犯罪势力赶走，要么遭遇了更糟的命运。在他们离开后，迪菲亚潜行者占据了农场结实的农舍和杂草丛生的田地。这里成为了他们的藏身处和转运站，让强盗们得以在远离闪金镇巡逻队监视的地方重整旗鼓。像收货人莫根这样的重要共谋者，利用这片偏僻的地块接收从森林矿坑中非法开采并偷运出的黄金。"},{t="猪与黑暗魔法",b="除了迪菲亚潜行者，在这片南瓜藤中游荡的麻烦制造者还不止这些。布莱克威尔一家留下了一头巨大的获奖母猪，名叫公主，它在南瓜田里四处游荡，不断骚扰着邻近的农场。与此同时，农舍的阁楼和附属建筑掩盖着危险的个人交易：强盗埃尔兰·德鲁格莫尔引诱了苏瑞娜·卡蕾顿，这是一位术士学徒，她从暴风城的导师那里逃走，并偷走了一件血石饰品，从而将黑暗术士的注意力引向了这个藏身处。"}},faq={{q="布莱克威尔一家发生了什么？",a="他们的具体下落至今仍是个谜。当迪菲亚潜行者在艾尔文森林东南部扩大势力时，布莱克威尔一家要么被迫逃离，要么惨遭杀害，将他们的南瓜田和农舍留给了这些强盗。",al={"布莱克威尔一家在哪里","谁住在布莱克威尔农场","布莱克威尔家族的命运"}},{q="为什么迪菲亚潜行者要使用这个农场？",a="这个农场提供了一个靠近森林边缘的偏僻基地。它允许兄弟会储存赃物并协调走私行动，例如通过收货人莫根这样的信使接收偷来的矿金，且远离暴风城卫兵的视线。",al={"为什么迪菲亚在这里","强盗在南瓜田做什么","布莱克威尔的迪菲亚"}},{q="公主是谁？",a="公主是一头体型巨大的获奖母猪，最初由布莱克威尔一家饲养。农场沦陷时它被遗弃在此，由于经常闯入附近的斯通菲尔德农场偷吃他们珍贵的作物，它的体型变得更加庞大。",al={"巨型猪","猪公主","为什么这里有一头巨大的野猪"}},{q="为什么术士会来到南瓜田？",a="苏瑞娜·卡蕾顿是暴风城术士训练师黑暗缚灵者加科因的学徒，她偷走了一件强大的血石颈环，并潜逃到农场，与她的情人——迪菲亚强盗埃尔兰·德鲁格莫尔躲藏在一起。加科因派遣术士新手来到这里除掉她并取回这件圣物。",al={"布莱克威尔术士任务","苏瑞娜·卡蕾顿","加科因虚空行者任务"}}},fp="23,203,14.413.0,19.414.1,38.209.0,46.259.0,16.192.0,42.244.0"}
P.entries["subzone:brambleblade-ravine"] = {n="刺刃峡谷",s="刺刃峡谷是一条切入红云台地东北边缘的崎岖峡谷。它是刺鬃野猪人部落的坚固巢穴，他们不断袭击附近的牛头人定居点——纳拉其营地。年轻的牛头人勇士被派往此处，以证明他们的实力并保护家园免受这些凶猛入侵者的侵扰。",h="刺刃峡谷是一条切入红云台地东北边缘的崎岖峡谷。它是刺鬃野猪人部落的坚固巢穴，他们不断袭击附近的牛头人定居点——纳拉其营地。年轻的牛头人勇士被派往此处，以证明他们的实力并保护家园免受这些凶猛入侵者的侵扰。",kw={"刺刃","刺鬃","纳拉其营地","莫高雷","野猪人","峡谷","红云台地","棘幔"},ang={["faction:Horde"]="清除刺刃峡谷中极具侵略性的刺鬃野猪人，有助于巩固部落在莫高雷早期的立足点。",["race:Tauren"]="对于在纳拉其营地进行Coming of Age的年轻牛头人来说，深入刺刃峡谷是他们为保卫部落而进行的最初的武力和精神耐力测试之一。"},sec={{t="台地之刺",b="刺刃峡谷刻在红云台地那被烈日灼烧的土地上，峡谷中塞满了茂密多刺的荆棘和野猪人的营地。刺鬃部落将这一天然要塞作为袭击纳拉其营地的集结地，威胁着正在进行Coming of Age的年轻牛头人的安全。刺鬃萨满和战士在首领利牙·棘幔的带领下，与驯养的战猪一起居住在峡谷深处。对于舒哈鲁人来说，深入峡谷中心既是一场关键的成人礼，也是保卫平原的冷酷必要之举。"}},faq={{q="什么是刺刃峡谷？",a="刺刃峡谷是位于莫高雷红云台地东北边缘的一条峡谷。这里居住着大量的刺鬃野猪人，是他们当地的据点。",al={"刺刃峡谷","什么是刺刃峡谷","莫高雷刺刃峡谷"}},{q="为什么刺鬃野猪人从这里发起进攻？",a="刺鬃野猪人领地意识极强，并将牛头人的存在视为对其所宣称土地的侵犯。他们以刺刃峡谷为据点，频繁对附近的定居点纳拉其营地发起袭击。",al={"为什么野猪人发起进攻","刺鬃野猪人的动机","野猪人纳拉其营地"}},{q="谁领导着刺刃峡谷的野猪人？",a="这里的野猪人由首领利牙·棘幔领导，他是一位强大的酋长，居住在峡谷后方的一间大屋子里。",al={"刺刃峡谷首领","莫高雷野猪人头目","首领利牙·棘幔"}},{q="为什么年轻的牛头人要前往峡谷？",a="纳拉其营地的牛头人长者和酋长派遣初出茅庐的勇士进入峡谷，以击退刺鬃野猪人的威胁，削减其数量，并击败其首领，从而保障台地的安全。",al={"牛头人刺刃任务","为什么要前往刺刃峡谷","纳拉其营地任务"}}},fp="19,199,26.456.0,28.127.0,53.139.0,46.122.0,41.179.0"}
P.entries["subzone:bramblescar"] = {n="迅猛龙平原",s="迅猛龙平原是位于南贫瘠之地的一处防御森严的刺鬃野猪人定居点。茂密而多刺的荆棘屏障保护着这座营地，里面的居民正在与黄金之路对面的竞争对手刺棘部族进行着残酷的战争。",h="迅猛龙平原是位于南贫瘠之地的一处防御森严的刺鬃野猪人定居点。茂密而多刺的荆棘屏障保护着这座营地，里面的居民正在与黄金之路对面的竞争对手刺棘部族进行着残酷的战争。",kw={"阿迦玛戈","贫瘠之地","迅猛龙平原","刺棘","黄金之路","野猪人","刺鬃"},ang={["faction:Horde"]="确保黄金之路免受来自迅猛龙平原的野猪人突袭，对于维持十字路口、陶拉祖营地以及南部边境之间的安全通道至关重要。"},sec={{t="荆棘堡垒",b="迅猛龙平原开凿在南贫瘠之地参差不齐的巨大荆棘丛中，是刺鬃野猪人至关重要的防御堡垒。这些防御性的荆棘丛生长得又厚又尖，足以阻挡随意的游荡者，但里面的野猪人绝非善类。他们领地意识极强，对外人充满敌意，不断袭击任何靠近其边界的人，将所有非野猪人的生物视为对其古老野猪神所祝福土地的侵犯者。"},{t="部落血仇",b="迅猛龙平原与黄金之路对面的阿迦玛戈始终处于紧张对峙状态，后者是敌对的刺棘部族所据守的营地。这两个派系为了争夺对南贫瘠之地的统治权，陷入了一场无休止的部落战争。除了要击退沿大路行进的部落旅行者，还要抵御刺棘部族的突袭队，迅猛龙平原的刺鬃战士们始终保持着持续且暴力的戒备状态。"}},faq={{q="谁住在迅猛龙平原？",a="迅猛龙平原居住着刺鬃部族的野猪人，他们守卫着这片荆棘丛生的营地，以对抗其他敌对的野猪人以及任何路过的旅行者。",al={"这里有什么人","迅猛龙平原怪物","迅猛龙平原野猪人"}},{q="为什么这里的野猪人在自相残杀？",a="迅猛龙平原的刺鬃野猪人和路对面阿迦玛戈的刺棘野猪人是死敌，他们为了争夺对南贫瘠之地的控制权，陷入了激烈的领土血仇之中。",al={"为什么他们处于战争状态","刺鬃与刺棘","野猪人战争"}},{q="迅猛龙平原在哪里？",a="迅猛龙平原位于贫瘠之地的南部平原，坐落在黄金之路东侧，与阿迦玛戈隔路相望。",al={"迅猛龙平原位置","迅猛龙平原在哪里","如何找到迅猛龙平原"}},{q="这里的野猪人对部落有敌意吗？",a="是的。刺鬃野猪人将部落视为侵犯他们神圣部落领地的入侵者，他们会攻击任何靠近的旅行者。",al={"迅猛龙平原友好吗","部落与迅猛龙平原声望"}}},fp="11,145,17.362.0,17.331.0,25.146.0,46.170.0,29.114.0,43.117.0"}
P.entries["subzone:brewnall-village"] = {n="烈酒村",s="烈酒村是坐落在寒风峡谷，靠近诺莫瑞根入口处的一处小型矮人定居点。由麦酒家族建立，这个前哨站既是进行大胆酿酒实验的试验场，也是抵御野生野兽入侵的区域防线。尽管被称为“村”，它在丹莫罗积雪覆盖的侏儒低地中实际上更像是一个粗犷的营地。",h="烈酒村是坐落在寒风峡谷，靠近诺莫瑞根入口处的一处小型矮人定居点。由麦酒家族建立，这个前哨站既是进行大胆酿酒实验的试验场，也是抵御野生野兽入侵的区域防线。尽管被称为“村”，它在丹莫罗积雪覆盖的侏儒低地中实际上更像是一个粗犷...",kw={"麦酒家族","啤酒","烈酒村","寒风峡谷","丹莫罗","诺莫瑞根","黑啤酒"},ang={["race:Dwarf"]="对矮人而言，麦酒家族对终极配方的追求是一项崇高的事业，延续了铁炉堡最优秀的传统之一。",["race:Gnome"]="该村庄坐落在诺莫瑞根附近，是深处丹莫罗西部侏儒峡谷中一处意想不到的矮人前哨站。"},sec={{t="峡谷中的苦酒",b="烈酒村隐藏在寒风峡谷的积雪中，位于丹莫罗西部的传统侏儒领地内。这个定居点是麦酒氏族的家园，这些坚定的矮人酿酒师致力于完善古老的配方并酿造出终极烈性黑啤酒。虽然被称为村庄，但该前哨站主要由帐篷和户外酿酒设备组成，而非永久性的石质建筑。在测试实验性麦酒批次和抵御当地凶猛的狼群与熊群之余，麦酒家族非常依赖过往的登山者来收集稀有原料并确保峡谷的安全。"}},faq={{q="烈酒村是什么地方？",a="烈酒村是位于丹莫罗西部、诺莫瑞根正东方寒风峡谷内的一个小型矮人营地。它是麦酒氏族进行新啤酒配方实验和管理当地野生动物威胁的前哨站。",al={"烈酒村在哪里","烈酒村是什么","烈酒村信息"}},{q="既然没有建筑物，为什么叫它村庄？",a="尽管名字里带个“村”字，但该地点本质上是一个由帐篷和补给桶组成的露天营地。麦酒家族为了在这种寒冷气候下进行酿酒作业，并没有建造正式的石屋。",al={"为什么是营地","房子在哪里","烈酒村建筑"}},{q="为什么在侏儒领地会有矮人定居点？",a="虽然丹莫罗的西半部环绕着诺莫瑞根，主要居住着侏儒，但铁炉堡和侏儒之间紧密的联盟使得共同居住变得很常见。麦酒家族在寒风峡谷定居，是为了不受干扰地追求他们的技艺。",al={"诺莫瑞根附近的矮人","为什么矮人在那","侏儒领地的矮人营地"}},{q="居民们面临什么问题？",a="营地经常面临来自峡谷中凶猛野生动物的袭击，尤其是石腭怪、熊和霜狼。此外，麦酒家族也在不断寻找稀有和奇异的原料，以发明出更新、更棒的佳酿。",al={"烈酒村任务","麦酒家族需要什么","村庄问题"}}},fp="16,145,27.379.0,25.196.0,53.162.0,57.186.0,36.155.0"}
P.entries["subzone:brightwater-lake"] = {n="澈水湖",s="澈水湖是提瑞斯法林地最大的水域，横跨布瑞尔东北部那片迷雾笼罩的低地。这片湖泊曾是洛丹伦王国一处宁静的度假地，如今湖水却变得阴冷昏暗，环绕着一座中央岛屿，一位被放逐的死灵法师正在那里进行着他那禁忌的研究。",h="澈水湖是提瑞斯法林地最大的水域，横跨布瑞尔东北部那片迷雾笼罩的低地。这片湖泊曾是洛丹伦王国一处宁静的度假地，如今湖水却变得阴冷昏暗，环绕着一座中央岛屿，一位被放逐的死灵法师正在那里进行着他那禁忌的研究。",kw={"澈水湖","布瑞尔","冈瑟尔·阿坎努斯","冈瑟尔的居所","死灵法师","血色十字军哨岗","提瑞斯法林地","亡灵"},ang={["class:Mage"]="湖上的岛屿保留着叛逃法师冈瑟尔·阿坎努斯所展现出的独特且未经引导的精湛技艺。",["race:Undead"]="对于被遗忘者来说，确保澈水湖的安全对于保卫布瑞尔的东侧防线以及评估这位独立的死灵法师冈瑟尔·阿坎努斯究竟会成为资产还是敌人至关重要。"},sec={{t="北方的水域",b="澈水湖横跨布瑞尔镇和血色十字军哨岗之间的北部平原，是提瑞斯法林地中心地带一处安静而诡异的地标。在洛丹伦王国统治的和平年代，这里曾是一处风景秀丽的乡村避风港。如今，就像林地的其他地方一样，它纯净的特质早已荡然无存。瘟疫之地就在东边不远处，浑浊而冰冷的湖水只能映照出灰暗的天空、枯萎的树木，以及时刻威胁着这里的鱼人游荡者和充满敌意的亡灵。"},{t="隐士的居所",b="澈水湖中央升起一座名为冈瑟尔的居所的岛屿。冈瑟尔·阿坎努斯靠自己的力量挣脱了巫妖王的控制，但他认为其他所有亡灵依然是天灾军团的奴隶。他将自己与世隔绝，并派遣亡灵仆从守卫他的居所。比索·埃斯沙德试图向他的老友证明，被遗忘者也拥有自由意志。在冒险者证明了自己反对天灾军团的立场后，冈瑟尔同意加入被遗忘者。"}},faq={{q="澈水湖在哪里？",a="澈水湖位于提瑞斯法林地东北部，就在被遗忘者据点布瑞尔的东北方。它位于崎岖的北部海岸正南方，西临血色十字军哨岗，后者守卫着通往西瘟疫之地的山口。",al={"澈水湖位置","澈水湖在哪里","寻找澈水湖"}},{q="住在湖中心岛上的人是谁？",a="中央岛屿被称为冈瑟尔的居所。一位与世隔绝的死灵法师和他的亡灵仆从居住在那里，这引起了附近布瑞尔和幽暗城的被遗忘者的兴趣。",al={"岛上住着谁","冈瑟尔·阿坎努斯","澈水湖岛屿npc"}},{q="水域周围有什么威胁？",a="沿着湖岸旅行的人经常会遇到好斗的鱼人和在岸边搜寻食物的怪鱼。接近中央岛屿时，那些发誓保护冈瑟尔·阿坎努斯免受入侵者伤害的亡灵仆从会带来危险。",al={"湖中怪物","澈水湖敌人","澈水湖的危险"}},{q="为什么布瑞尔的卫兵会谈论这里的夏令营？",a="布瑞尔的死亡卫兵会冷冷地开玩笑说，被遗忘者曾试图在澈水湖岸边开办一个儿童夏令营，但因为蒙面变态狂在营地里恐吓他人而被迫关闭——这是一个模仿人类篝火故事的病态本地笑话。",al={"夏令营传闻","布瑞尔卫兵关于湖的笑话","蒙面变态营地"}}},fx={["010a8c36"]={q="澈水湖是什么地方？",a="澈水湖是提瑞斯法林地最大的水域，位于布瑞尔东北方，东侧毗邻通往血色十字军哨岗的丘陵。湖水幽暗，中央有一座醒目的岛屿，名为冈瑟尔的居所，周围还散布着一些较小的露出水面的岩地。",al={"澈水湖是什么地方","澈水湖的背景故事","介绍澈水湖"}},["5d21e80d"]={q="澈水湖有着怎样的历史？",a="瘟疫爆发前，澈水湖是洛丹伦王国一处宁静的乡间胜地。如今，冰冷的湖水环绕着冈瑟尔的居所，亡灵法师冈瑟尔·阿坎努斯藏身于此，远离尘世。",al={"澈水湖的历史","澈水湖发生过什么","澈水湖的往事"}}},fp="16,194,19.347.0,19.415.1,34.218.0,50.169.0,41.124.0,57.224.0"}
P.entries["subzone:brightwood-grove"] = {n="阳光树林",s="阳光树林是一片位于暮色森林夜色镇正西方的阴影笼罩的林地。这里曾经是该地区宁静的农耕景观的一部分，现在却被野蛮的夜行狼人所占据，它们在废弃的农舍中安营扎寨，并袭击任何靠得太近的旅行者。",h="阳光树林是一片位于暮色森林夜色镇正西方的阴影笼罩的林地。这里曾经是该地区宁静的农耕景观的一部分，现在却被野蛮的夜行狼人所占据，它们在废弃的农舍中安营扎寨，并袭击任何靠得太近的旅行者。",kw={"阳光树林","夜色镇","暮色森林","守夜人","夜行者","狼人"},ang={["class:Hunter"]="树林阴暗的丛林为追踪凶残的夜行狼人提供了艰难的地形，考验着猎人在树线后潜伏的伏击面前的警觉性。",["faction:Alliance"]="阳光树林紧邻夜色镇大门，因此铲除其中的狼人狼群对于防止这座饱受摧残的城镇与西部隔绝至关重要。"},sec={{t="阴影中的树林",b="阳光树林位于夜色镇周边视野范围内，代表着威胁该镇边界的步步紧逼的危险。曾经划分出宁静农田的农舍和栅栏现在已经坍塌腐朽。取而代之的是，夜行狼人在杂草丛生的林间空地上搭建了粗陋的营地。这些狼兽的临近对城镇构成了持续的威胁，迫使守夜人和过往的冒险者不断地削减它们的数量，以免定居点被它们淹没。"}},faq={{q="阳光树林在哪里？",a="阳光树林位于暮色森林东部，就在夜色镇西侧，紧邻主要道路。",al={"阳光树林位置","阳光树林在哪里","暮色森林阳光树林"}},{q="什么生物栖息在阳光树林？",a="这片树林里盘踞着大量野蛮的夜行狼人。这些被诅咒的狼人已经在废墟建筑中建立了粗陋的营地，并会袭击任何靠近的人。",al={"阳光树林中的怪物","阳光树林的敌人","阳光树林住着什么"}},{q="为什么这片树林对夜色镇来说很危险？",a="由于阳光树林紧邻夜色镇西侧，潜伏在灌木丛中的好斗狼群对城镇巡逻队、补给线以及任何沿路抵达的旅行者构成了直接威胁。",al={"为什么阳光树林很危险","夜色镇阳光树林威胁"}},{q="树林里有友好的定居点吗？",a="没有。树林边缘仅存的几座石屋和农舍完全沦为废墟，被遗弃在荒野中，并被游荡的狼人占据。",al={"阳光树林里有友方单位吗","阳光树林城镇"}}},fp="16,83,17.330.0,26.87.0,40.130.0,40.157.0,48.154.0"}
P.entries["subzone:brill"] = {n="布瑞尔",s="布瑞尔是提瑞斯法林地中心地带主要的被遗忘者定居点，位于洛丹伦废墟正北方。这里曾是一座繁荣的人类城镇，如今已成为新苏醒的亡灵离开丧钟镇后的行政与军事枢纽。",h="布瑞尔是提瑞斯法林地中心地带主要的被遗忘者定居点，位于洛丹伦废墟正北方。这里曾是一座繁荣的人类城镇，如今已成为新苏醒的亡灵离开丧钟镇后的行政与军事枢纽。",kw={"布瑞尔","被遗忘者","恐惧之末","洛丹伦","执政官塞弗伦","提瑞斯法林地","飞艇"},ang={["faction:Horde"]="镇外的飞艇停靠点是北方部落在洛丹伦与卡利姆多及东部王国各盟友据点之间的主要交通枢纽。",["race:Undead"]="对于从丧钟镇出发的被遗忘者来说，布瑞尔是他们见到的第一处文明，也是向黑暗女王证明忠诚的起点。"},sec={{t="从瘟疫之地到堡垒",b="第三次战争前，布瑞尔是一个在巴罗夫和阿曼德家族等当地贵族统治下生机勃勃的村庄。当克尔苏加德选择此地作为诅咒教派最初的亡灵瘟疫实验场时，这种繁荣便戛然而止。毁灭性的瘟疫迅速席卷了整个居民区，当地民兵被驱逐，留下了一大片广阔的乱葬岗。\n\n如今，在执政官塞弗伦的领导下，城镇已被被遗忘者重建，保留了洛丹伦饱经风霜的建筑风格，笼罩在冷酷的目标氛围之中。布瑞尔作为地区指挥中心，负责协调防御血色十字军的入侵、游荡的天灾余孽以及被死灵腐化扭曲的当地野兽。"},{t="北洛丹伦的十字路口",b="除了本地防御，布瑞尔还是连接提瑞斯法林地与部落更广阔领土的重要十字路口。城镇上空，地精运营的飞艇塔提供前往南方的杜隆塔尔以及深入荆棘谷的交通服务。在定居点内，恐惧之末旅店不仅是旅客黑暗的避风港，也是临时的实验室，被俘的血色狂热者会在此接受审讯和药剂师的测试。"}},faq={{q="谁在统治布瑞尔？",a="执政官塞弗伦代表Sylvanas Windrunner女士和被遗忘者监管布瑞尔的民政与当地防御事务。",al={"布瑞尔领袖","谁负责布瑞尔","布瑞尔执政官"}},{q="为什么布瑞尔外有如此巨大的墓地？",a="克尔苏加德在布瑞尔进行了他最早的一些亡灵瘟疫活体实验。瘟疫以惊人的速度消灭了当地人类人口，因此必须建立一个乱葬岗来安葬受害者，以免他们复生为天灾军团。",al={"布瑞尔墓地","布瑞尔附近的公墓","为什么有那么多坟墓"}},{q="恐惧之末旅店是做什么用的？",a="除了为疲惫的旅客提供住宿外，旅店的地下室还是药剂师的基地，他们在此对被俘的血色十字军狂热者进行化学和毒理学实验。",al={"恐惧之末旅店","布瑞尔旅店","布瑞尔旅店里发生了什么"}},{q="布瑞尔外的飞艇塔通往哪里？",a="由地精团队运营的飞艇塔将洛丹伦与奥格瑞玛外的卡利姆多直接连接起来，同时还通往南方的荆棘谷格罗姆高营地。",al={"布瑞尔飞艇目的地","布瑞尔的飞艇去哪","布瑞尔飞行航线"}}},fx={["0490a2ec"]={q="布瑞尔是什么地方？",a="布瑞尔是提瑞斯法林地的中心聚居地，位于洛丹伦废墟正北方。它曾是一个沉寂的人类村庄，如今则是被遗忘者重要的军事枢纽和前哨站。从丧钟镇启程的新兵会到这里报到，协助希尔瓦娜斯·风行者女士的部队守卫周边林地，抵御不断逼近的威胁。",al={"布瑞尔是什么地方","布瑞尔概况","布瑞尔城镇"}},["3209731c"]={q="布瑞尔过去发生过什么？",a="第三次战争期间，巫妖克尔苏加德在提瑞斯法林地展开黑暗试验，布瑞尔成为最早遭受亡灵瘟疫侵袭的村庄之一。守军不敌来袭的敌人，幸存者被迫逃离，随后阿尔萨斯王子前来调查此地。天灾军团席卷王国后，被遗忘者收复了这座废弃的聚居地，并将其重建为首都以北的主要要塞枢纽。",al={"布瑞尔的历史","布瑞尔发生过什么","布瑞尔的背景故事"}},fbdb53db={q="布瑞尔危险吗？",a="布瑞尔境内有警惕的亡灵卫兵和执政官塞弗伦严密防守。然而，城镇之外危机四伏：毫无理智的天灾军团在乡野间徘徊，凶残的腐皮豺狼人搜寻附近的水道，狂热的血色十字军则在林地各处发动无休止的战争，企图彻底消灭聚居地里的所有生者。",al={"布瑞尔安全吗","布瑞尔面临的威胁","布瑞尔危险吗"}}},fp="5,198,29.552.0,32.284.0,16.121.0,52.235.0,37.137.0,54.130.0"}
P.entries["subzone:brill-town-hall"] = {n="布瑞尔城镇大厅",s="布瑞尔城镇大厅是位于提瑞斯法林地中部布瑞尔定居点的行政中心。作为镇上最显眼的建筑，它是被遗忘者管理当地领地并协调林地防御的市政总部。",h="布瑞尔城镇大厅是位于提瑞斯法林地中部布瑞尔定居点的行政中心。作为镇上最显眼的建筑，它是被遗忘者管理当地领地并协调林地防御的市政总部。",kw={"布瑞尔","被遗忘者","洛丹伦","执政官塞弗伦","塞弗伦","提瑞斯法林地","城镇大厅"},ang={["faction:Horde"]="抵达提瑞斯法的部落盟友可以访问城镇大厅，以了解被遗忘者如何在他们黑暗的家园中维持民事权威和军事秩序。",["race:Undead"]="对于从丧钟镇出发探索的被遗忘者来说，这座城镇大厅代表了他们在希尔瓦娜斯女王统治下第一次体验到有组织的市政管理，当地的防御和收复工作都在这里被正式组织起来。"},sec={{t="被遗忘者的市政中心",b="尽管洛丹伦的大部分地区已破碎废弃，但布瑞尔城镇大厅在亡灵的统治下依然作为一座正常运作的市政中心屹立不倒。执政官塞弗伦在室内指挥镇务，并向被遗忘者的冒险者发布重要的任务和指令。除了阿拉希高地的污染者之穴外，它是已知世界中为数不多由被遗忘者积极运营的公认城镇大厅，既是对旧洛丹伦市政官僚体制的一种阴暗嘲讽，也是其职能的延续。"}},faq={{q="布瑞尔城镇大厅有什么用途？",a="它作为布瑞尔定居点的当地政府驻地。被遗忘者的领导层，特别是执政官塞弗伦，利用这座建筑来协调当地防御、发布法令，并为旅行者和新苏醒的亡灵分配重要任务。",al={"布瑞尔城镇大厅的用途","这是什么建筑","为什么要访问布瑞尔城镇大厅"}},{q="这里由谁负责？",a="执政官塞弗伦在讲台上主持城镇大厅的工作，代表被遗忘者管理市政事务，并指挥提瑞斯法林地中部的各项行动。",al={"谁管理布瑞尔城镇大厅","布瑞尔城镇大厅领导者","执政官是谁"}},{q="为什么这个城镇大厅比其他的更值得注意？",a="城镇大厅通常是人类王国遗留的古迹。布瑞尔城镇大厅之所以引人注目，是因为它是少数由被遗忘者维护和运营的活跃市政厅之一，仅与阿拉希高地的污染者之穴等地点相似。",al={"独特的被遗忘者城镇大厅","还有其他被遗忘者城镇大厅吗"}}},fp="15,161,26.391.0,37.206.0,22.166.0,49.168.0"}
P.entries["subzone:broken-hall"] = {n="Broken Hall",s="Broken Hall是位于悲伤沼泽的沉没的神庙中被淹没的外部入口。当伟大的巨龙守护者伊瑟拉和她的龙群将这座宏伟的祖尔金字塔拖入水下时，这里变得支离破碎。随着阿塔莱狂热者撤退到更深处的圣殿，这片废墟如今已荒废无人。",h="Broken Hall是位于悲伤沼泽的沉没的神庙中被淹没的外部入口。当伟大的巨龙守护者伊瑟拉和她的龙群将这座宏伟的祖尔金字塔拖入水下时，这里变得支离破碎。随着阿塔莱狂热者撤退到更深处的圣殿，这片废墟如今已荒废无人。",kw={"阿塔莱","broken hall","hall of masks","泪水之池","沉没的神庙","悲伤沼泽","阿塔哈卡神庙"},ang={["race:Troll"]="对于崇敬洛阿神的巨魔来说，Broken Hall是一个严酷的提醒，时刻铭记着那些违抗同族去侍奉剥魂者哈卡的阿塔莱狂热者所遭受的毁灭。"},sec={{t="被淹没的入口",b="当绿龙军团将愤怒降临在阿塔莱祭司身上，并将他们邪恶的祖尔金字塔沉入泪水之池下时，最外层的建筑首当其冲，承受了这场灾难。Broken Hall的地面彻底坍塌，导致浑浊的沼泽水淹没了整个房间。由于损毁和淹没，巨魔邪教徒放弃了这个入口大厅，撤退到了建筑群的更深处。进入沉没的神庙的冒险者必须穿过这些浸水的废墟，然后登上台阶才能到达Hall of Masks。"}},faq={{q="Broken Hall是什么？",a="它是阿塔哈卡神庙最外层的入口房间，位于泪水之池下被水淹没的入口之后。",al={"broken hall 概况","这是什么地方","神庙入口大厅"}},{q="为什么Broken Hall会被淹没并遭到破坏？",a="当绿龙军团为了阻止血神哈卡的召唤，将整个神庙拖入沼泽水下时，这个房间遭到了破坏，地面崩塌，大厅被淹没。",al={"为什么 broken hall 会潮湿","为什么 broken hall 会被淹没","是谁破坏了大厅"}},{q="还有阿塔莱巨魔住在那个大厅里吗？",a="Broken Hall本身基本上已经被遗弃了。在上层神庙被淹没后，阿塔莱邪教徒撤退到了建筑群内部更干燥、防御性更强的地方。",al={"broken hall 中的敌人","broken hall 是空的吗"}},{q="Broken Hall里的楼梯通向哪里？",a="沿着从被淹没的Broken Hall通出的石阶向上走，探险者可以直接进入Hall of Masks。",al={"broken hall 的楼梯","broken hall 出口","从 broken hall 出发去哪里"}}},fp="11,304,17.555.0,24.141.0,42.193.0,49.184.0,44.115.0"}
P.entries["subzone:broken-pillar"] = {n="破碎石柱",s="破碎石柱是一处风化严重的古代巨魔遗迹，从加基森南部的沙丘中突兀而出。它成为了地精勘探员兼科学家玛尔冯·瑞文斯克的孤立研究站，他在那里研究掩埋在周围沙地下的神秘神器。",h="破碎石柱是一处风化严重的古代巨魔遗迹，从加基森南部的沙丘中突兀而出。它成为了地精勘探员兼科学家玛尔冯·瑞文斯克的孤立研究站，他在那里研究掩埋在周围沙地下的神秘神器。",kw={"破碎石柱","加基森","加兹瑞迪安","玛尔冯·瑞文斯克","棘齿城","塔纳利斯","巨魔遗迹"},ang={["race:Gnome"]="驱使玛尔冯·瑞文斯克研究未知遗物特性的好奇心反映了侏儒的学术野心，尽管他的研究方法仍带有独特的地精风格。",["race:Troll"]="这些破碎的石柱是祖先巨魔建筑的庄严标志，回响着那个帝国对卡利姆多南部的统治被时间和沙尘所摧毁之前的时代。"},sec={{t="日晒褪色的岩石",b="破碎石柱从加基森南部、危险的深沙平原东部的沙海中升起，标志着早已被塔纳利斯吞没的古代巨魔建筑的残余。尽管周围环境荒凉且有沙漠野兽出没，但该遗址为探索这片大陆的史前文明提供了珍贵的线索。玛尔冯·瑞文斯克是一位原本驻扎在棘齿城的地精研究员，他在破碎的石雕旁建立了一个孤零零的营地，以研究散布在荒野中、被称为“加兹瑞迪安”的奇特遗物。"}},faq={{q="破碎石柱是什么？",a="破碎石柱是一处位于塔纳利斯中部、加基森南部以及深沙平原东部的古代巨魔遗迹。除了风化的石柱和半埋在流沙中的碎片外，原来的结构几乎所剩无几。",al={"破碎石柱 塔纳利斯","破碎石柱是什么","石柱遗迹"}},{q="谁在破碎石柱扎营？",a="来自棘齿城、充满好奇心的地精科学家兼勘探员玛尔冯·瑞文斯克在遗迹中设立了一个单独的研究营地。他正在调查埋藏在周围沙漠各处的神秘“加兹瑞迪安”饰品。",al={"谁在破碎石柱","破碎石柱npc","玛尔冯·瑞文斯克位置"}},{q="这里的原始遗迹是谁建造的？",a="这些石雕具有古代巨魔的设计风格，其历史可以追溯到古代巨魔帝国统治卡利姆多南部地区的时代，远在沙漠吞没该地区之前。",al={"谁建造了破碎石柱","破碎石柱历史","破碎石柱起源"}},{q="什么是加兹瑞迪安遗物？",a="“加兹瑞迪安”是埋藏在塔纳利斯沙地中的古代石制神器和雕刻面具。玛尔冯·瑞文斯克在他的破碎石柱营地研究这些物品，试图解开那个消失的帝国工艺中所蕴含的秘密与力量。",al={"加兹瑞迪安","什么是加兹瑞迪安","玛尔冯任务物品"}}},fp="13,279,18.526.0,26.242.0,35.228.0,34.177.0,28.228.0"}
P.entries["subzone:bronzebeard-encampment"] = {n="铜须营地",s="铜须营地是位于希利苏斯南部的一处坚固的矮人前哨站，坐落在巨大的甲虫之墙以东。该营地由探险者协会的坚韧探险家和研究人员负责，是调查古老其拉符文和埋藏在沙漠黄沙之下的久远谜团的行动基地。",h="铜须营地是位于希利苏斯南部的一处坚固的矮人前哨站，坐落在巨大的甲虫之墙以东。该营地由探险者协会的坚韧探险家和研究人员负责，是调查古老其拉符文和埋藏在沙漠黄沙之下的久远谜团的行动基地。",kw={"铜须营地","死亡之钳","探险者协会","弗兰卡尔·石桥","格里布","鲁特加尔·雕石","甲虫之墙","希利苏斯"},ang={["faction:Alliance"]="对于在希利苏斯阴郁荒原上穿行的联盟旅行者来说，这座偏远的营地提供了一处远在塞纳里奥要塞以南、值得信赖的友好哨点。",["race:Dwarf"]="这座前哨站展示了探险者协会坚定不移的韧性，证明了对于寻求历史真相的铁炉堡矮人来说，没有任何贫瘠的沙漠是无法征服的。"},sec={{t="流沙中的落脚点",b="铜须营地背靠希利苏斯荒凉的南部悬崖，为这片危机四伏的荒原提供了一处难得的矮人避难所。该营地建立在铁炉堡考古事业的赞助之下，与高耸的甲虫之墙遥遥相望。在这里，像鲁特加尔·雕石和弗兰卡尔·石桥这样的研究人员不畏灼人的酷热、蝎形虫以及不断逼近的其拉虫群，致力于研究被遗忘的文明所留下的独特铭文和纪念碑。"},{t="符文与绝望",b="在营地里的生活绝非一场平静的挖掘。随着其拉虫人的威胁从横跨荒原的地下巢穴中蔓延开来，以及像可怕的巨型蝎形虫“死亡之钳”这样的危险怪物在附近的沙地上徘徊，这个前哨站必须在严谨的学术研究与艰难的生存之间保持平衡。研究人员非常依赖前来造访的冒险者去获取晦涩符文的拓片，破译古老的虫族语言，并寻找那些深入沙漠疯狂之中而失踪的同伴。"}},faq={{q="铜须营地在哪里？",a="该营地位于希利苏斯南部，坐落在巨大的甲虫之墙以东，南部山脊以北。",al={"铜须营地在哪里","铜须营地位置","如何找到铜须营地"}},{q="谁在管理铜须营地？",a="营地由矮人探险者协会的成员和相关人员组成，包括符文研究员鲁特加尔·雕石、弗兰卡尔·石桥以及他们的同伴格里布。",al={"谁在铜须营地","铜须营地npc","谁领导铜须营地"}},{q="矮人们在这里研究什么？",a="研究人员致力于破译古老的石刻符文，理解其拉虫人的交流系统，并挖掘卡利姆多南部深埋已久的秘密。",al={"矮人为什么在希利苏斯","鲁特加尔在研究什么","铜须营地的目的"}},{q="营地附近潜伏着什么威胁？",a="营地周围的沙漠中游荡着富有攻击性的其拉虫人、沙蝎，以及臭名昭著的巨型蝎形虫“死亡之钳”，它就在东南方向筑巢。",al={"铜须营地附近的危险","死亡之钳位置","铜须营地怪物"}}},fp="22,331,32.498.0,22.486.0,44.131.0,36.178.0,35.176.0,38.187.0"}
P.entries["subzone:browman-mill"] = {n="布洛米尔",s="布洛米尔是一座被枯萎病侵蚀的锯木厂，位于东瘟疫之地圣光之愿礼拜堂的北面。它曾是洛丹伦木材贸易中欣欣向荣的一部分，如今却在天灾军团的铁腕统治下，到处充斥着亡灵爪牙。它曾经的主人，斯蒂芬·布洛曼，在死后仍被困在他那破败的工场之中。",h="布洛米尔是一座被枯萎病侵蚀的锯木厂，位于东瘟疫之地圣光之愿礼拜堂的北面。它曾是洛丹伦木材贸易中欣欣向荣的一部分，如今却在天灾军团的铁腕统治下，到处充斥着亡灵爪牙。它曾经的主人，斯蒂芬·布洛曼，在死后仍被困在他那破败的工场...",kw={"憎恶","女妖","布洛米尔","东瘟疫之地","圣光之愿礼拜堂","锯木厂","天灾军团","斯蒂芬·布洛曼"},ang={["class:Paladin"]="被亵渎的锯木厂残骸以及在此地游荡的受折磨的灵魂，代表了圣职者们致力于从洛丹伦清除的一切邪恶。",["race:Undead"]="斯蒂芬·布洛曼的被奴役，鲜明地提醒了人们所有巫妖王的受害者所共同面临的命运——他们没能像被遗忘者那样获得自由意志。"},sec={{t="荒废的产业",b="在第三次战争之前，布洛米尔为洛丹伦周边的城镇和农庄提供服务，加工从东威尔德富饶森林中采伐的木材。当天灾瘟疫席卷王国时，这座锯木厂同该省的其他地区一样陷落了。如今，腐朽的木梁和破碎的轮轴闲置在那里，而憎恶、女妖和骷髅怪在周边巡逻。由于它紧邻圣光之愿礼拜堂，这使得它成为了亡灵大军紧逼银色黎明家门口的一个持续且危险的警示。"},{t="监管者的命运",b="锯木厂最初的主人，斯蒂芬·布洛曼，遭遇了与洛丹伦无数平民同样的惨淡命运。当被天灾军团入侵时，他被谋杀，并被复活成了贪婪的食尸鬼。他的人性被剥夺，沦为巫妖王意志的奴隶。布洛曼徘徊在他曾经的锯木厂的黑暗深处，守卫着他毕生心血的破碎废墟。"}},faq={{q="布洛米尔位于哪里？",a="布洛米尔位于东瘟疫之地的最东侧，坐落在圣光之愿礼拜堂的正北方。",al={"布洛米尔位置","布洛米尔在哪里","如何找到布洛米尔"}},{q="什么类型的敌人盘踞在锯木厂？",a="这片区域遍布天灾军团的势力，包括巨大的憎恶、哀嚎的女妖、骷髅怪和游荡的食尸鬼。",al={"布洛米尔怪物","谁在布洛米尔","布洛米尔有什么生物"}},{q="斯蒂芬·布洛曼是谁？",a="斯蒂芬·布洛曼是这座锯木厂最初的人类所有者和经营者。他在洛丹伦陷落期间被杀害，并被复活为一个亡灵食尸鬼，被迫守卫他那破败的建筑。",al={"斯蒂芬·布洛曼是谁","斯蒂芬·布洛曼背景故事","布洛曼食尸鬼"}},{q="为什么布洛米尔对旅行者来说很危险？",a="这里聚集了大量的强力亡灵，使其成为一个致命的危险地带，尤其是因为它距离银色黎明在圣光之愿礼拜堂的据点仅有很短的路程。",al={"为什么布洛米尔危险","布洛米尔的威胁"}}},fp="12,323,17.538.0,19.371.0,30.125.0,38.134.0,24.196.0,43.175.0"}
P.entries["subzone:bulwark"] = {n="亡灵壁垒",s="亡灵壁垒是一座横跨在提瑞斯法林地与西瘟疫之地边界上的防御前哨站。它由被遗忘者和中立的银色黎明共同维护，是部落对抗天灾军团的第一道防线，也是向被污染的东方地区派遣远征军的主要出发点。",h="亡灵壁垒是一座横跨在提瑞斯法林地与西瘟疫之地边界上的防御前哨站。它由被遗忘者和中立的银色黎明共同维护，是部落对抗天灾军团的第一道防线，也是向被污染的东方地区派遣远征军的主要出发点。",kw={"银色黎明","亡灵壁垒","寒风营地","被遗忘者","天灾军团","提瑞斯法","西瘟疫之地"},ang={["faction:Horde"]="亡灵壁垒是部落对应联盟寒风营地的据点，作为进入瘟疫之地进行各项行动的主要入口和作战基地。",["race:Undead"]="对于被遗忘者来说，亡灵壁垒是一个关键的咽喉要道，它阻止了巫妖王的军队直接向布瑞尔和幽暗城进军。"},sec={{t="对抗天灾军团的护盾",b="亡灵壁垒位于提瑞斯法林地的东部边缘，是保卫被遗忘者核心领土免受西瘟疫之地枯萎恐怖侵害的最后一道屏障。如今，粗糙的木制栅栏和全副武装的卫兵把守着隘口，抵御着游荡的亡灵。这是一个虽然不安但却必要的合作，被遗忘者部队与银色黎明在此协作，招募部落的精锐勇士，在巫妖王的爪牙涌入提瑞斯法之前将其击退。"}},faq={{q="亡灵壁垒的目的是什么？",a="亡灵壁垒是部落对抗天灾军团的首要防御驻地和集结地。它保护着提瑞斯法林地和幽暗城免受西瘟疫之地涌出的入侵，同时也驻扎着协调进攻污染地区的银色黎明和被遗忘者指挥官。",al={"为什么会有亡灵壁垒","亡灵壁垒的用途","这是什么地方"}},{q="联盟角色可以前往亡灵壁垒与银色黎明交谈吗？",a="不可以。尽管驻扎在那里的银色黎明代表是中立的，但该营地驻扎着大量的被遗忘者卫兵。任何踏入栅栏范围内的联盟成员都会立即遭到攻击。",al={"联盟可以使用亡灵壁垒吗","联盟在亡灵壁垒","亡灵壁垒是部落专属吗"}},{q="对于离开提瑞斯法的年轻冒险者来说，亡灵壁垒安全吗？",a="不安全。虽然大门直接连接着提瑞斯法林地，但外面的西瘟疫之地充满了致命的高等级亡灵和瘟疫锅。新手旅行者如果越过栅栏，将面临迅速死亡的危险。",al={"低等级可以越过亡灵壁垒吗","低等级进入瘟疫之地"}}},fx={["3800d924"]={q="亡灵壁垒是什么地方？",a="亡灵壁垒是一座坚固的前哨站，坐落在提瑞斯法林地与西瘟疫之地的交界处。它是被遗忘者东部防线的一环，守卫着提瑞斯法林地的入口，抵御天灾军团无休止的恐怖威胁。在这里，被遗忘者哨兵与银色黎明的使者并肩协作，共同部署防御、阻挡亡灵入侵，并派遣能干的勇士深入前方的疫病之地。",al={"亡灵壁垒是什么地方","亡灵壁垒概况","亡灵壁垒介绍"}},["7098c368"]={q="谁驻守亡灵壁垒？",a="这座前哨站由效忠希尔瓦娜斯女王的被遗忘者士兵，以及中立组织银色黎明的成员共同驻守。被遗忘者负责守卫边境、保卫北方王国，银色黎明则在此招募经验丰富的部落冒险者，派遣他们前往瘟疫之地打击巫妖王的爪牙。",al={"谁在管理亡灵壁垒","谁驻守亡灵壁垒","亡灵壁垒的居民"}},a92b042c={q="为什么叫亡灵壁垒？",a="这座要塞因其职责而得名：它是一道真正的壁垒，用于保护被遗忘者的领地免遭入侵。它正处于提瑞斯法林地与瘟疫之地的交界处，厚重的路障构成了最后一道防线，阻挡天灾军团的怪物大军。",al={"为何称作亡灵壁垒","亡灵壁垒名称的含义","亡灵壁垒为何得名"}}},fp="7,192,28.348.0,35.254.0,72.168.0,59.173.0"}
P.entries["subzone:burning-blade-coven"] = {n="火刃集会所",s="火刃集会所隐藏在试炼谷北部的悬崖中，是一个受腐蚀的洞穴网络，威胁着部落的新兵。堕落的邪教徒和被召唤的恶魔潜伏其中，将一个古老的矿洞变成了杜隆塔尔家门口施展黑暗魔法的基地。",h="火刃集会所隐藏在试炼谷北部的悬崖中，是一个受腐蚀的洞穴网络，威胁着部落的新兵。堕落的邪教徒和被召唤的恶魔潜伏其中，将一个古老的矿洞变成了杜隆塔尔家门口施展黑暗魔法的基地。",kw={"火刃集会所","恶魔","杜隆塔尔","小鬼","塔兹利尔","试炼谷","亚罗格·碎影"},ang={["class:Warlock"]="这里的恶魔小鬼和黑暗仪式是一个早期的警示，让人一窥当邪能被鲁莽地使用并公然反抗部落时会发生什么。",["race:Orc"]="火刃氏族邪教在如此靠近试炼谷的地方出现，是对萨尔的新部落不可容忍的侮辱，也是兽人们竭力想要摆脱的恶魔崇拜的严酷提醒。"},sec={{t="试炼场上的阴影",b="环绕试炼谷的尘土飞扬的红色山脉，曾经只是年轻的兽人和暗矛巨魔为部落服务时进行初步试炼的荒野。然而近来，黑暗仪式占据了北部的洞穴。小鬼和低阶恶魔从洞口涌出，搅乱局势并威胁着新兵。在暗影术士亚罗格·碎影的带领下，火刃氏族邪教已深入其中，将原本例行的训练场变成了对抗恶魔腐蚀的活跃战场。"},{t="岩石中的腐蚀",b="在恶魔扎根之前，这些洞穴曾吸引了当地监工的注意，他们希望在此为定居点开采原材料。工头塔兹利尔深入洞穴进行矿产勘探，却被仓促赶出，丢下了宝贵的装备，因为邪教徒暴露了他们的存在。现在，击退碎影的集会所成为了有抱负的战士、潜行者和施法者在被认为有资格前往更广阔的杜隆塔尔之前，必须完成的终极试炼。"}},faq={{q="火刃集会所位于哪里？",a="洞穴嵌入在试炼谷北缘的红色高岩脊中，位于杜隆塔尔。",al={"集会所位置","火刃集会所在哪","山谷洞穴位置"}},{q="是谁领导着这里的邪教徒？",a="这个集会所由一名叫作亚罗格·碎影的术士领导，他指挥着当地的仪式并统领着被召唤的恶魔。",al={"集会所首领","谁领导火刃集会所","亚罗格"}},{q="里面潜伏着什么样的敌人？",a="洞穴里到处都是堕落的小鬼、低阶恶魔仆从，以及效忠于暗影火刃氏族邪教的凡人侍僧。",al={"洞穴里有什么怪物","集会所怪物","试炼谷里的恶魔"}},{q="为什么新兵要进入这个洞穴？",a="勇敢地深入洞穴的黑暗深处，找回工头塔兹利尔的矿工镐等遗失工具，并击杀亚罗格·碎影，这是兽人和巨魔冒险者在离开山谷前最后的入会仪式。",al={"为什么要去集会所","集会所目的","集会所最终考验"}}},fp="19,251,33.431.0,23.421.0,41.122.0,28.101.0,34.108.0,37.194.0"}
P.entries["subzone:caer-darrow"] = {n="凯尔达隆",s="凯尔达隆是一座位于西瘟疫之地达隆米尔湖上的堡垒岛屿。它曾是贵族巴罗夫家族的领地，后来岛上的要塞被秘密卖给了克尔苏加德，并被改造为通灵学院，使得地表的城镇中充满了游荡的幻影。",h="凯尔达隆是一座位于西瘟疫之地达隆米尔湖上的堡垒岛屿。它曾是贵族巴罗夫家族的领地，后来岛上的要塞被秘密卖给了克尔苏加德，并被改造为通灵学院，使得地表的城镇中充满了游荡的幻影。",kw={"巴罗夫","凯尔达隆","the cult of the damned","达隆米尔湖","加丁","符文石","萨尔科夫","通灵学院","幽灵精华"},ang={["faction:Alliance"]="对于联盟而言，凯尔达隆代表了两次深重的背叛：第二次战争期间奥特兰克私掠船的伏击揭露了佩瑞诺德国王的叛国行径，以及巴罗夫家族将他们的祖宅卖给了克尔苏加德。",["race:Human"]="人类旅行者会认出这座岛屿曾是巴罗夫家族的领地，在他们的贪婪导致与The Cult of the Damned签订契约之前，该家族曾是洛丹伦最富有的贵族家庭之一。"},sec={{t="战争与背叛的遗产",b="在天灾军团出现很久之前，凯尔达隆是洛丹伦的一处战略要塞，守护着一块古老的精灵符文石。第二次战争期间，部落洗劫了这座要塞，并将符文石切开，用以建造古尔丹的风暴祭坛。当光明使者乌瑟尔乘船前来向幸存者提供援助时，他的舰队遭到了奥特兰克私掠船的伏击——这一背信弃义的行为向联盟揭露了奥特兰克的背叛。"},{t="巴罗夫家族的没落",b="凯尔达隆在第二次战争后得以重建，作为巴罗夫家族奢华的庄园，他们拥有横跨布瑞尔、塔伦米尔和南海镇的大片土地契约。随着年岁渐长，为了保住财富和永恒的生命，巴罗夫家族与克尔苏加德达成了一笔交易。The Cult of the Damned在要塞之下扎根，建立了通灵学院。甚至在第三次战争席卷洛丹伦之前，一场预备性的瘟疫就已经在岛上的仆人和城镇居民中爆发了。民众们纷纷丧命，被诅咒永远徘徊在残破的要塞中，化作挥之不去的余音。"}},faq={{q="什么是凯尔达隆？",a="凯尔达隆是一座位于西瘟疫之地达隆米尔湖中的堡垒岛屿。它曾是富有的巴罗夫家族引以为傲的祖宅，如今却成了一片阴森的废墟，其地下墓穴中坐落着被称为通灵学院的亡灵法术学院。",al={"凯尔达隆概况","这里是什么地方","凯尔达隆背景故事"}},{q="为什么这座城镇会被废弃并成为废墟？",a="巴罗夫家族与克尔苏加德进行了交易，将他们的庄园卖给了The Cult of the Damned以换取永生。该教派利用要塞的仆人进行早期的亡灵法术实验，并在针对洛丹伦的大规模入侵开始前，向整个定居点散布了一场致命的瘟疫。",al={"凯尔达隆为何被毁","凯尔达隆发生了什么","凯尔达隆历史"}},{q="为什么我在镇上看不到鬼魂？",a="凯尔达隆被谋杀的居民徘徊在此，变成了被困在最后时刻的游荡之魂。若没有特殊的魔法视觉，普通双眼无法看见它们，例如使用由伊娃和卢森·萨尔科夫的灵魂所提供的幽灵精华。",al={"鬼魂在哪里","凯尔达隆的隐形人","如何看见鬼魂"}},{q="这里曾经有过什么符文石？",a="在第二次战争期间，凯尔达隆曾安置着一块古老的高等精灵符文石。部落袭击了该岛，并将这块神圣的石头凿成碎片，古尔丹利用这些碎片建造了风暴祭坛，以此为食人魔法师引导能量。",al={"凯尔达隆的符文石","精灵符文石","风暴祭坛之石"}},{q="要塞之下有什么？",a="要塞之下坐落着通灵学院，这是The Cult of the Damned的总部和训练基地。在黑暗院长加丁的领导下，学院内的亡灵法师和侍僧们研究黑暗艺术并对死者进行实验。",al={"凯尔达隆之下有什么","地下室里有什么","凯尔达隆下的地下城"}}},fp="11,317,28.424.0,23.548.1,20.236.0,37.298.0,39.248.1,44.232.0,32.217.0"}
P.entries["subzone:calmbreeze-inn"] = {n="Calmbreeze Inn",s="Calmbreeze Inn是指遍布泽风岛各地、提供住所与服务的首要场所，在申达尔村和Valaanar均有分布。它们是探索岛屿的旅行者必不可少的休憩之所，驻有当地的商业训练师、旅店老板，并陈列着历史文物。",h="Calmbreeze Inn是指遍布泽风岛各地、提供住所与服务的首要场所，在申达尔村和Valaanar均有分布。它们是探索岛屿的旅行者必不可少的休憩之所，驻有当地的商业训练师、旅店老板，并陈列着历史文物。",kw={"calmbreeze inn","coriella calmbreeze","eldre'thalas","申达尔村","valaanar","泽风岛"},ang={["class:Rogue"]="Miriann Mistblade在申达尔村Calmbreeze Inn的壁炉旁提供潜行者指导。",["profession:Herbalism"]="访问申达尔村的草药师可以在Calmbreeze Inn内寻找Halassa Fernbreeze，以磨练他们的采集技艺。"},sec={{t="岛上休憩",b="Calmbreeze Inn在泽风岛蜿蜒的道路中提供了一处避难所。在申达尔村，这家旅店由Coriella Calmbreeze打理，同时也是岛上商人们的聚集中心，包括草药学、剥皮和附魔训练师。在不远处的Valaanar，另一家Calmbreeze Inn为当地旅人提供住宿，并收藏着珍稀古玩，其中包括一颗记录着Eldre'Thalas远古反抗史的声音水晶。"}},faq={{q="Calmbreeze Inn位于何处？",a="在泽风岛上，申达尔村和Valaanar均设有Calmbreeze Inn。",al={"calmbreeze inn位置","calmbreeze inn在哪里","calmbreeze inn地图"}},{q="谁经营着申达尔村的旅店？",a="申达尔村的旅店由旅店老板Coriella Calmbreeze负责，为岛上的居民和旅行者提供热情接待。",al={"calmbreeze旅店老板","谁经营calmbreeze inn"}},{q="旅店里有哪些训练师？",a="在申达尔村的旅店里，驻有草药学训练师Halassa Fernbreeze、剥皮训练师Mendalass Tattermend、附魔训练师Nasalanna Windsinger以及潜行者训练师Miriann Mistblade。",al={"calmbreeze训练师","申达尔旅店训练师"}},{q="Valaanar楼上的声音水晶里记录着什么？",a="在Valaanar旅店的楼上放着一颗声音水晶，里面记录了《Eldre'Thalas的反抗》的第三部分，讲述了这座远古上层精灵城市的重要历史事件。",al={"valaanar声音水晶","eldre'thalas的反抗水晶"}}},fx={["043ce63b"]={q="Calmbreeze Inn是什么地方？",a="Calmbreeze Inn指的是一系列服务于泽风岛旅客的旅店，分别设在瓦拉纳尔和申达尔村。这些旅店是重要的社区聚集地，为疲惫的旅客提供休息之所，让他们结识当地的商贩和训练师，并收集岛上的各方消息。",al={"calmbreeze inn是什么地方","calmbreeze inn的背景故事","介绍calmbreeze inn"}},c8344be2={q="Calmbreeze Inn危险吗？",a="不危险。Calmbreeze Inn的各处分店都是申达尔村和瓦拉纳尔各自聚居地中的宁静庇护所。里面住着友善的居民，旅店老板和专业技能训练师，而没有充满敌意的威胁。",al={"calmbreeze inn安全吗","calmbreeze inn的危险"}}},fp="14,286,16.458.0,38.92.0,37.139.0,38.183.0,53.166.0"}
P.entries["subzone:camp-aparaje"] = {n="阿帕拉耶营地",s="阿帕拉耶营地曾是一个坐落在石爪山脉东部高地的宁静牛头人村庄。如今，它被敌对的恐怖图腾氏族占领，他们屠杀了原本的居民，并将这里变成了自己的前哨站。",h="阿帕拉耶营地曾是一个坐落在石爪山脉东部高地的宁静牛头人村庄。如今，它被敌对的恐怖图腾氏族占领，他们屠杀了原本的居民，并将这里变成了自己的前哨站。",kw={"阿帕拉耶营地","恐怖图腾","恐怖图腾岗哨","格伦迪格·黑云","卡雅·扁蹄","玛卡巴·扁蹄","石爪山脉"},ang={["faction:Horde"]="清除阿帕拉耶营地的恐怖图腾既是为了复仇也是为了防御，确保这个背信弃义的部族因在石爪山脉屠杀无辜的部落成员而受到惩罚。",["race:Tauren"]="阿帕拉耶营地的废墟提醒着人们玛加萨的恐怖图腾部族是何等残忍，这证明并非所有大地母亲的孩子都认同凯恩·血蹄关于荣誉与和平的愿景。"},sec={{t="悲剧的覆灭",b="阿帕拉耶营地坐落在石爪山脉的岩架上，由渴望在高原安静生活的宁静牛头人所建立。这份宁静在附近的恐怖图腾岗哨发起的袭击中被打破了，袭击由格伦迪格·黑云率领，是一场残暴且无端的突袭。村民们被屠杀或赶走，像玛卡巴·扁蹄这样的幸存者在哀悼家园毁灭的同时，也为被俘亲人的命运感到恐惧。"},{t="在恐怖图腾的统治下",b="如今，阿帕拉耶营地已完全被恐怖图腾战士占据，成为了该部族在该地区的进攻前哨。与悬挂蓝色标记的典型恐怖图腾定居点不同，立在阿帕拉耶的巨大图腾上刻着深红色的油漆。"}},faq={{q="谁曾经住在阿帕拉耶营地？",a="在被入侵之前，阿帕拉耶营地居住着隶属于部落和血蹄部族的和平牛头人，包括玛卡巴·扁蹄和他的女儿卡雅。",al={"谁住在这里","阿帕拉耶营地的原始居民","玛卡巴·扁蹄的村庄"}},{q="为什么这个营地对部落玩家充满敌意？",a="这个村庄被恐怖图腾氏族暴力夺取，这是一个排外且背信弃义的牛头人氏族，他们拒绝效忠凯恩·血蹄，并积极攻击包括部落成员在内的外来者。",al={"为什么牛头人攻击我","谁控制着阿帕拉耶营地","为什么阿帕拉耶营地是红色的"}},{q="谁领导了对阿帕拉耶营地的袭击？",a="这次突袭由格伦迪格·黑云带头，他是恐怖图腾岗哨的一名残暴的恐怖图腾酋长，试图扩大他部族对石爪山脉的暴力控制。",al={"谁袭击了阿帕拉耶","格伦迪格·黑云","这里的领袖是谁"}},{q="幸存的村民遭遇了什么？",a="大多数居民在袭击中丧生。少数人成功逃脱，而其他人，比如年轻的卡雅·扁蹄，被恐怖图腾俘虏并关押在附近的恐怖图腾岗哨。",al={"卡雅·扁蹄","幸存者在哪里","有幸存者吗"}}},fp="12,173,17.333.0,20.209.0,33.168.0,41.174.0,36.143.0,41.141.0"}
P.entries["subzone:camp-e-thok"] = {n="伊索克营地",s="伊索克营地是位于千针石林西北部的一个伽拉克半人马定居点。这个富有侵略性的半人马部族将这处峡谷营地作为据点，伏击下方河道中经过的商队。",h="伊索克营地是位于千针石林西北部的一个伽拉克半人马定居点。这个富有侵略性的半人马部族将这处峡谷营地作为据点，伏击下方河道中经过的商队。",kw={"伊索克营地","半人马","伊索克","伽拉克","千针石林","维兹罗"},ang={["race:Tauren"]="伊索克营地的伽拉克半人马那不懈的侵略性，时刻提醒着人们牛头人与半人马之间在整个南卡利姆多地区持续不断的祖辈战争。"},sec={{t="伽拉克据点",b="伊索克营地坐落于千针石林崎岖的西北部边缘，是敌对的伽拉克半人马的重要定居点。正如他们在卡利姆多各处的同族一样，伽拉克半人马生性残暴，会对任何误入峡谷阴影的旅行者下手。该营地因策划针对商队的劫掠而臭名昭著，尤其是伏击了地精维兹罗并夺走了他的货物——不过他那珍贵的小装置在凶猛的宠物黑豹的守护下，幸免于难，未落入他们手中。"}},faq={{q="谁住在伊索克营地？",a="该营地由伽拉克氏族半人马占据，这是一个统治着千针石林西北部部分地区的侵略性部族。",al={"谁在伊索克营地","伊索克营地居民","谁控制着伊索克营地"}},{q="维兹罗在这里遭遇了什么？",a="地精维兹罗的商队遭到了来自伊索克营地的伽拉克半人马的伏击。虽然他们洗劫了商队，但未能夺走维兹罗最珍视的小装置，因为它被拴在他那只凶猛的宠物黑豹的项圈上。",al={"维兹罗遇袭","地精商队遇袭","半人马从维兹罗那里偷走了什么"}},{q="伊索克营地在哪里？",a="伊索克营地位于千针石林西北部，坐落在峡谷壁的底部。",al={"伊索克营地位置","伊索克营地在哪里","伊索克营地地图"}}},fx={["740a44e0"]={q="伊索克营地是什么地方？",a="伊索克营地是加拉克半人马部族的一处常驻营地，位于千针石林西北部的峡谷中。半人马以这座设防营地为据点，在下方峡谷中伏击并袭击旅人和商队。",al={"伊索克营地是什么","伊索克营地传说","介绍伊索克营地"}},["7ec291b4"]={q="伊索克营地危险吗？",a="伊索克营地极其危险。居住在此的加拉克半人马会一见到外来者就发动攻击，掠夺胆敢穿越峡谷的商队。任何闯入营地的人都会遭遇敌对的战士、萨满，以及他们用暴力掠夺来的战利品。",al={"伊索克营地有敌意吗","伊索克营地有多危险","伊索克营地的危险"}}},fp="11,231,18.508.0,25.127.0,42.256.0,29.101.0"}
P.entries["subzone:camp-kosh"] = {n="柯什营地",s="柯什营地是位于荒芜之地北部的一个食人魔营地，居住着凶猛的尘牙食人魔。该营地坐落在关键的交通要道附近，其蛮兵会劫掠路过的商队，并搜刮旅行者在严酷沙漠中留下的任何装备。",h="柯什营地是位于荒芜之地北部的一个食人魔营地，居住着凶猛的尘牙食人魔。该营地坐落在关键的交通要道附近，其蛮兵会劫掠路过的商队，并搜刮旅行者在严酷沙漠中留下的任何装备。",kw={"荒芜之地","柯什营地","尘牙","食人魔","西格鲁·铁斧","奥达曼"},ang={["faction:Alliance"]="沿北部通道前往灼热峡谷的联盟侦察兵在经过柯什营地附近时必须保持警惕，因为那些蛮兵随时准备伏击路过的补给商队。",["race:Dwarf"]="柯什营地的食人魔拾荒者掠夺了西格鲁·铁斧陷入困境的奥达曼探险队留下的重要口粮和武器储备。"},sec={{t="拾荒者的巢穴",b="柯什营地坐落在荒芜之地的北部荒野，是尘牙食人魔最北端的定居点，这些食人魔还占据着博夫、卡格和沃格等周边营地。驻扎在此的食人魔利用紧邻道路的便利，劫掠前往卡加斯或向西进入灼热峡谷的脆弱补给线。当西格鲁·铁斧带领的矮人勘探者被迫逃离奥达曼的挖掘现场时，柯什营地的蛮兵迅速洗劫了他们遗弃的货车，并将珍贵的口粮和武器搬回了尘土飞扬的营地中。"}},faq={{q="谁住在柯什营地？",a="柯什营地居住着尘牙食人魔，这是一个凶残的食人魔部落，在荒芜之地的干旱地区控制着几个小型营地。",al={"柯什营地怪物","柯什营地里是谁","柯什营地食人魔"}},{q="为什么柯什营地建在这里？",a="其北部的位置使尘牙食人魔能够伏击在灼热峡谷、奥达曼和部落前哨站卡加斯之间往来的补给商队和毫无防备的旅行者。",al={"为什么有柯什营地","柯什营地位置"}},{q="食人魔从矮人那里偷走了什么？",a="当西格鲁·铁斧的矮人探险队从奥达曼内部的危险中撤退时，他们在沙漠中遗弃了补给货车。柯什营地的食人魔搜刮了残骸，并抢走了成箱的食物和武器货物。",al={"柯什营地矮人补给","西格鲁·铁斧补给","奥达曼货车"}}},fp="9,250,19.583.0,23.138.0,30.177.0,42.227.0"}
P.entries["subzone:camp-mojache"] = {n="莫沙彻营地",s="莫沙彻营地是部落在菲拉斯的主要前哨站，它是一座加固的牛头人定居点，坐落于汇入狂风湖的水域旁。对于那些需要应对这片未被驯服的荒野、凶猛的野生动物以及深林中古老废墟的旅行者来说，这里提供了栖身之所、补给品和飞行连接点。",h="莫沙彻营地是部落在菲拉斯的主要前哨站，它是一座加固的牛头人定居点，坐落于汇入狂风湖的水域旁。对于那些需要应对这片未被驯服的荒野、凶猛的野生动物以及深林中古老废墟的旅行者来说，这里提供了栖身之所、补给品和飞行连接点。",kw={"勇士","莫沙彻营地","菲拉斯","飞行管理员","戈多克","牛头人","狂风湖","木爪"},ang={["faction:Horde"]="作为部落在菲拉斯唯一的加固枢纽，莫沙彻是你休息、补充物资和确保在深林中快速交通的唯一避难所。",["race:Tauren"]="莫沙彻营地代表了你们的民族在卡利姆多的传统工艺和定居点所能到达的最南端，在茂密的雨林中开辟出一片和谐之地。"},sec={{t="雨林中的牛头人堡垒",b="莫沙彻营地位于菲拉斯东部，坐落于一条汇入狂风湖的湍急溪流旁。这是一座牛头人定居点，旨在为部落在这片狂野的南部森林中稳固立足。虽然茂密的丛林中潜伏着危险——从野蛮的野生动物到戈多克食人魔和好斗的木爪豺狼人——但这座营地仍是一座安全的避风港。这里配备了住所、贸易商和双足飞龙管理员，是部落勇士在该地区行动的重要后勤枢纽。"},{t="边境前哨站",b="营地的猎手和勇士以勇气和坚韧著称，时刻保持警惕，防御来自周围荒野的袭击。对部落而言，守住莫沙彻营地对于在菲拉斯保持影响力至关重要，同时也能够牵制沿海的暗夜精灵以及潜伏在厄运之槌中的黑暗势力。"}},faq={{q="莫沙彻营地是什么？",a="莫沙彻营地是部落在菲拉斯的主要行动基地。它主要由牛头人建造和维护，横跨一条流入狂风湖的溪流，提供休息设施、贸易物资和飞行交通服务。",al={"莫沙彻营地的目的","这个营地是什么","菲拉斯的牛头人城镇"}},{q="谁领导或保卫这座营地？",a="该定居点由经验丰富的牛头人勇士负责保卫，他们防范着当地野兽群、戈多克食人魔以及在南部丘陵中徘徊的好斗的木爪豺狼人的入侵。",al={"莫沙彻营地的守卫","谁保卫莫沙彻","谁负责莫沙彻营地"}},{q="当地的飞行管理员可以去往哪里？",a="从营地的双足飞龙栖木出发，旅行者可以到达诸如雷霆崖、贫瘠之地的十字路口、凄凉之地的葬影村以及塔纳利斯加基森等邻近前哨站等中心枢纽。",al={"莫沙彻营地飞行路线","我能从莫沙彻营地飞往哪里"}},{q="莫沙彻营地周围有哪些主要威胁？",a="营地周围的森林里栖息着南部的木爪豺狼人氏族、北部和南部的戈多克食人魔，以及在远方西海岸羽月要塞活动的联盟部队。",al={"菲拉斯莫沙彻营地的危险","莫沙彻营地附近的威胁","莫沙彻附近的敌人"}}},fp="12,306,34.478.0,16.347.0,21.230.0,30.192.0,42.204.0,41.211.0"}
P.entries["subzone:camp-narache"] = {n="纳拉其营地",s="纳拉其营地是一座隐蔽的村落，坐落在莫高雷南部的红云台地上。它是鹰风部族的祖居地，也是年轻的牛头人开始训练的试炼场。营地高踞于平原之上，在保持古老传统的同时，时刻警惕着入侵的野猪人和徘徊的半人马威胁。",h="纳拉其营地是一座隐蔽的村落，坐落在莫高雷南部的红云台地上。它是鹰风部族的祖居地，也是年轻的牛头人开始训练的试炼场。营地高踞于平原之上，在保持古老传统的同时，时刻警惕着入侵的野猪人和徘徊的半人马威胁。",kw={"钢鬃","鹰风酋长的母亲","鹰风","莫高雷","纳拉其","红云台地","灵魂之屋","牛头人"},ang={["class:Shaman"]="年轻的萨满祭司在此踏上灵魂之旅的第一步，通过试炼来获得他们的大地图腾，并与台地的元素直接沟通。",["race:Tauren"]="对于牛头人来说，纳拉其营地代表着童年的终结——在这里，在鹰风部族长者的注视下，你将举行第一次狩猎仪式，并与祖先之灵建立感应，这就是那片神圣的土地。"},sec={{t="鹰风部族的心脏",b="纳拉其营地位于高耸的红云台地北缘，是鹰风部族的主要定居点。村落由几座大型皮制小屋和凉亭组成，包括供受伤勇士使用的公共帐篷、军械库、烘焙帐篷，以及用于冥想和祖先交流的灵魂之屋。在营地中央，部族长者和修行导师围成一圈，受人尊敬的鹰风酋长的母亲仍在此提供指引，引导刚刚入门的年轻人们踏上他们作为大地母亲守护者的道路。"},{t="受威胁的试炼场",b="尽管有台地陡峭的悬崖作为天然屏障，纳拉其营地仍面临着持续的动荡。来自刺刃峡谷的钢鬃野猪人不断侵扰鹰风部族的土地，而半人马斥候也在远处徘徊。年轻的猎人、萨满祭司、德鲁伊和战士们在此证明自己的实力，通过猎杀好斗的当地野生动物、保卫村庄的水井，并在沿大路下行进入莫高雷广阔的谷地之前击退野猪人袭击者。"}},faq={{q="什么是纳拉其营地？",a="纳拉其营地是年轻牛头人的新手村，坐落在莫高雷南部的红云台地上。它是鹰风部族的核心营地，也是初出茅庐的猎人、战士、德鲁伊和萨满祭司在前往血蹄村和雷霆崖之前磨练技艺的避风港。",al={"什么是纳拉其营地","纳拉其背景故事","牛头人新手村"}},{q="谁领导着这个村庄？",a="鹰风酋长负责引导部族的勇士并协调台地的防御，部族受人尊敬的长者鹰风酋长的母亲也在此协助。部族的导师和长者们聚集在营地中心，教导年轻的冒险者们。",al={"谁领导纳拉其营地","纳拉其营地酋长","鹰风部族首领"}},{q="营地面临着什么样的威胁？",a="营地不断受到东面刺刃峡谷中钢鬃野猪人的袭扰。除了在周边台地徘徊的凶猛战猪和陆行鸟外，掠夺成性的半人马部族所带来的潜在危险也让鹰风勇士们时刻保持警惕。",al={"纳拉其营地的敌人","谁袭击纳拉其营地","台地威胁"}},{q="旅行者能轻易离开台地吗？",a="红云台地四面环绕着陡峭的悬崖。通往莫高雷大平原的唯一路径是一条向北延伸的山道，由鹰风勇士守卫，以防止敌对野兽和野猪人伏击旅行者。",al={"离开红云台地","离开纳拉其营地","下台地的路径"}}},fp="12,280,27.381.0,29.413.0,21.305.0,22.200.0,32.163.0,36.191.0"}
P.entries["subzone:camp-taurajo"] = {n="陶拉祖营地",s="陶拉祖营地是一个宁静的牛头人定居点，坐落在南贫瘠之地，位于通往西侧莫高雷的山口边上。它是一个重要的前哨避难所，为疲惫的旅者提供旅店、补给、专业导师以及往返于平原和卡利姆多中部之间的双足飞龙交通。",h="陶拉祖营地是一个宁静的牛头人定居点，坐落在南贫瘠之地，位于通往西侧莫高雷的山口边上。它是一个重要的前哨避难所，为疲惫的旅者提供旅店、补给、专业导师以及往返于平原和卡利姆多中部之间的双足飞龙交通。",kw={"贫瘠之地","血蹄村","陶拉祖营地","莫高雷山口","南贫瘠之地","陶拉祖","牛头人前哨站"},ang={["faction:Horde"]="陶拉祖营地确保了一个关键的陆路交叉口和飞行航线，将莫高雷与部落控制下的卡利姆多中部紧密联系在一起。",["race:Tauren"]="对于第一次走出莫高雷的牛头人来说，陶拉祖营地是在严酷的贫瘠之地平原上遇到的第一个友好避难所。"},sec={{t="赤色石的前线",b="陶拉祖营地坐落在通往莫高雷山口的东口，通常是年轻牛头人离开血蹄村后，第一次窥见广阔贫瘠之地的地方。营地被干燥的灌木丛和崎岖的台地所环绕，既是一个前哨站也是一个贸易枢纽。它为猎人、制皮师和野外药草师提供庇护，同时维持着通往雷霆崖、十字路口以及深处南方的乱风岗的双足飞龙航线。"}},faq={{q="什么是陶拉祖营地？",a="陶拉祖营地是位于南贫瘠之地的一个牛头人前哨站和定居点，是莫高雷家园与贫瘠之地干旱灌木丛之间的关键中转站。",al={"陶拉祖营地概述","什么是陶拉祖","陶拉祖背景故事"}},{q="往西的路通向哪里？",a="沿着陶拉祖营地以西的泥土小径穿过山口，即可进入莫高雷，直达血蹄村和雷霆崖。",al={"陶拉祖西侧山口","陶拉祖营地以西的道路","通往莫高雷的路径"}},{q="从陶拉祖营地出发的双足飞龙飞向哪里？",a="当地的飞行管理员负责协调双足飞龙航线，将营地与北部的十字路口、西部的雷霆崖以及南部的千针石林乱风岗直接连接起来。",al={"陶拉祖飞行管理员","陶拉祖飞行航线","陶拉祖飞行连接"}}},fp="12,184,25.411.0,21.122.0,30.121.0,47.147.0"}
P.entries["subzone:camp-wurg"] = {n="瓦格营地",s="瓦格营地是坐落在荒芜之地干旱区域的一处食人魔营地。它是宣称占领了荒芜之地大部分地区的尘贝尔彻食人魔所建立的几座前哨站之一。",h="瓦格营地是坐落在荒芜之地干旱区域的一处食人魔营地。它是宣称占领了荒芜之地大部分地区的尘贝尔彻食人魔所建立的几座前哨站之一。",kw={"荒芜之地","托格鲁恩头目","博夫营地","卡格营地","柯什营地","瓦格营地","尘贝尔彻","食人魔","瓦格"},sec={{t="尘贝尔彻要塞",b="瓦格营地坐落在荒芜之地的岩架之间，是尘贝尔彻食人魔建立的四个主要营地之一，另外三个分别是卡格营地、博夫营地和柯什营地。驻扎在此的食人魔凶猛地守卫着他们崎岖的领地，在残酷的荒漠中搜寻一切可以利用的资源。虽然普通的粗鲁武士和执法者居住在瓦格营地那简陋的篝火和粗糙的兽皮帐篷旁，但他们的首领，托格鲁恩头目并没有在这里设立常驻点，而是游荡在荒芜之地的道路上，时刻监视着他所有的营地。"}},faq={{q="谁住在瓦格营地？",a="瓦格营地居住着尘贝尔彻食人魔，这是一个凶猛且领地意识极强的部落，他们在整个荒芜之地都建立了定居点。",al={"瓦格营地怪物","谁在瓦格营地","谁住在这里"}},{q="营地的首领在哪里？",a="尘贝尔彻食人魔的首领，托格鲁恩头目，并没有被困在瓦格营地。相反，他在瓦格、卡格、博夫和柯什营地之间的荒芜之地开阔小径上巡逻。",al={"瓦格营地首领","托格鲁恩头目位置","谁领导瓦格营地"}},{q="这个部落还有其他什么营地？",a="尘贝尔彻食人魔在整个荒芜之地控制着四个主要要塞：瓦格营地、卡格营地、博夫营地和柯什营地。",al={"尘贝尔彻营地","荒芜之地其他食人魔营地","荒芜之地食人魔定居点"}}},fp="9,194,24.521.0,23.132.0,32.175.0,38.119.0"}
P.entries["subzone:canals-stormwind-city"] = {n="Canals (Stormwind City)",s="运河是穿过暴风城的一系列石砌水道，将城市的不同区域分隔开来。它们既是行人和垂钓者安静的通道，也暗藏着危险，还是暴风城监狱的入口。",h="运河是穿过暴风城的一系列石砌水道，将城市的不同区域分隔开来。它们既是行人和垂钓者安静的通道，也暗藏着危险，还是暴风城监狱的入口。",kw={"运河区","运河","鳄鱼","加利纳","下水道","监狱","暴风城","水道"},ang={["faction:Alliance"]="运河见证了首都的重建，它们从第一次战争的废墟中恢复，成为了这座功能完善、风景如画的城市的一部分。",["profession:Cooking"]="安静的运河岸边为有志向的厨师提供了便利的垂钓地点，他们无需离开首都城墙的安全范围，就能捕获新鲜的鱼类。"},sec={{t="首都的动脉",b="运河连接并界定了暴风城的各个区域，将贸易区的繁华市场与老城区、大教堂花园以及矮人区的老旧小巷隔离开来。石桥、拱门和水边步道环绕着加利纳酒庄、裁缝店和宁静的民居等建筑。除了为当地商人和休闲垂钓者提供便利外，这些水道还隐蔽着监狱的坚固入口，暴风城最危险的罪犯和叛乱分子就关押在街道下方。"},{t="惨痛的历史与潜伏的阴影",b="水道平静的表面掩盖了其暴力的过去。在第一次战争中，当部落洗劫暴风城时，城市化为废墟，运河直到第二次战争后重建首都时才得以修复。如今，虽然河道已经清理和修复，但深处仍弥漫着神秘的气息，城市中关于码头下方潜伏着一只巨大白化鳄鱼的传闻更是加剧了这种神秘感。"}},faq={{q="第一次战争期间运河发生了什么？",a="当兽人部落在第一次战争中征服并洗劫暴风城时，这座城市及其水道化为废墟。在第二次战争后暴风城重建时，运河也随之修复。",al={"运河历史","第一次战争运河","暴风城洗劫运河"}},{q="暴风城的运河里真的有怪物吗？",a="没人能给出肯定的答案。流传已久的都市传说称，水道中潜伏着一只巨大的白色鳄鱼。城市卫兵和居民通常将其视为酒馆闲谈，但相关报道从未间断，冒险者们也被警告不要掉进水里。",al={"暴风城鳄鱼","运河短吻鳄","下水道野兽","白化鳄鱼"}},{q="监狱的入口在哪里？",a="监狱的入口位于环绕法师区运河的最北段，由暴风城卫兵重兵把守。",al={"监狱在哪里","监狱入口","如何进入监狱"}},{q="玩家可以通过在运河里游泳在暴风城内穿行吗？",a="在运河中游泳完全可行，但要回到街道上，需要找到沿水岸分布的石阶或码头。",al={"在运河中游泳","暴风城水路交通","暴风城水上路线"}}},fp="23,100,23.400.0,38.255.0,49.169.0,50.225.0,46.127.0,63.114.0"}
P.entries["subzone:canals-undercity"] = {n="Canals (Undercity)",s="幽暗城的运河是一条阴暗、环形的护城河，蜿蜒穿过幽暗城各区之间。里面流淌的不是清水，而是极其不自然、散发着恶臭的绿色粘液，它既是排污系统，也是被遗忘者这座地下要塞的冷酷象征。",h="幽暗城的运河是一条阴暗、环形的护城河，蜿蜒穿过幽暗城各区之间。里面流淌的不是清水，而是极其不自然、散发着恶臭的绿色粘液，它既是排污系统，也是被遗忘者这座地下要塞的冷酷象征。",kw={"运河","钓鱼","被遗忘者","绿色粘液","洛丹伦","淤泥","有毒","幽暗城"},ang={["class:Shaman"]="元素无法对填满幽暗城水道的污染泥浆产生太大影响，导致诸如水上行走之类的常规法术完全失效。",["race:Undead"]="对于被遗忘者而言，这些肮脏的运河对其非生命的生理结构完全无害，它们作为功能性的护城河和化学径流渠道，非常适合他们的地下国度。"},sec={{t="毒液护城河",b="运河开凿于洛丹伦废墟之下的深处，环绕着幽暗城的核心地带，用宽阔的绿色污泥水道将各个区域隔开。虽然凡人的城市会引入流动的河水来清洁街道，但被遗忘者却用工业废料、化学径流和炼金废物填满了这些石质管道。这种液体散发着微弱的病态光芒和恶臭的蒸气，使得通过水上行走等常规魔法手段穿越它变得不可能。尽管这些泥浆具有致命性，但绝望的垂钓者偶尔还是能从淤泥中打捞出奇特而扭曲的玩意儿。"}},faq={{q="运河里的绿色液体是什么？",a="这是一种炼金淤泥，由收集在幽暗城排水系统中的有毒径流、瘟疫副产品和工业废料组成。与清水不同，它明显是受到污染且有毒的。",al={"幽暗城绿水","幽暗城的粘液是什么","绿色粘液河"}},{q="能在幽暗城的运河里钓鱼吗？",a="可以，耐心的垂钓者可以将鱼线抛入这些污泥之中。除了病态、受污染的鱼类之外，人们偶尔还会捞起废弃的垃圾，包括来自洛丹伦覆灭往昔的旧人类头骨。",al={"幽暗城钓鱼","这里可以钓鱼吗","在绿色粘液中钓鱼"}},{q="为什么水上行走在运河上无效？",a="这种浓稠的化学淤泥与自然水体的性质不同。其恶臭的粘性和非自然的成分使得萨满祭司和其他施法者无法通过传统的水上行走魔法维持表面张力。",al={"幽暗城水上行走","萨满水上行走错误","为什么我不能在幽暗城水上行走"}}},fx={dc46e6d3={q="幽暗城的运河是什么地方？",a="运河是穿行于幽暗城各个区域之间的下沉式水道。它们在地下城市中绕成宽阔的环形，将一条缓慢流淌的污浊绿浆河引入深石渠中；水道既分隔了各个城区，也将这座幽暗的下层城市连为一体。",al={"幽暗城运河","运河是什么地方","幽暗城运河系统"}},c0800d9e={q="运河危险吗？",a="运河里潜伏的掠食者不会造成太大的直接威胁，但浑浊的绿色深水绝非干净之处。黏稠的污泥中可能藏着遗弃的骨头、人类头骨，以及病态变异的水生生物；不慎跌入其中，滋味定然糟透了。",al={"运河的危险","在幽暗城运河里游泳安全吗","幽暗城运河安全吗"}}},fp="18,147,12.411.0,39.184.0,37.172.0,45.170.0"}
P.entries["subzone:cape-of-stranglethorn"] = {n="荆棘谷海角",s="荆棘谷海角是荆棘谷被太阳炙烤的南端，从古拉巴什竞技场向南一直延伸到海边的悬崖。这片区域以广阔的海盗港口藏宝海湾为中心，是地精、血帆海盗、古老的丛林巨魔以及不断入侵的野生生物激烈争夺的战场。",h="荆棘谷海角是荆棘谷被太阳炙烤的南端，从古拉巴什竞技场向南一直延伸到海边的悬崖。这片区域以广阔的海盗港口藏宝海湾为中心，是地精、血帆海盗、古老的丛林巨魔以及不断入侵的野生生物激烈争夺的战场。",kw={"大财主里维加兹","blackwater raiders","血帆海盗","藏宝海湾","荆棘谷海角","古拉巴什竞技场","南海","荆棘谷"},ang={["class:Rogue"]="这里是私掠者、无赖和亡命之徒的避风港，提供了无穷无尽的机会来行窃、走私沿海违禁品，或者挑拨Blackwater Raiders与血帆海盗之间的关系。",["profession:Cooking"]="周围的南海和沿海水域拥有宝贵的渔场，藏宝海湾的鱼贩和港口厨师独家出售珍稀食谱。"},sec={{t="大陆边缘",b="在古拉巴什竞技场这座古老斗兽场的南面，茂密的丛林逐渐过渡到被称为荆棘谷海角的海岸线。这里星罗棋布地分布着朱布瓦尔废墟和阿博拉兹废墟等破败的巨魔定居点，荆棘谷海角早已脱离了古拉巴什帝国的控制。如今，这里的海滩、海湾和丛林空地上聚集着危险的掠食者、鱼人营地，以及为了贸易路线和埋藏的财宝而互相交战的敌对海盗船员，一片混乱。"},{t="藏宝海湾与海盗战争",b="荆棘谷海角的主导势力是Blackwater Raiders，由大财主里维加兹和舰队指挥官卡拉·海角在海盗城市藏宝海湾领导。这座中立港口直接开凿在南部海湾的悬崖中，通过往返棘齿城的蒸汽船连接东部王国和卡利姆多。然而，地精的控制权依然岌岌可危。血帆海盗活跃在南部浅滩和外岛，他们劫掠补给线，并公开策划推翻藏宝海湾，以夺取对南海的全面统治。"}},faq={{q="荆棘谷和荆棘谷海角有什么区别？",a="荆棘谷海角特指荆棘谷较大区域的南部，涵盖了从古拉巴什竞技场以南一直到藏宝海湾的陆地和海岸。",al={"海角与荆棘谷的区别","荆棘谷地理","海角在哪里"}},{q="谁统治着荆棘谷海角？",a="没有单一的势力控制整个海角。藏宝海湾及其周边水域由大财主里维加兹和地精支持的Blackwater Raiders统治，而血帆海盗、娜迦和残存的巨魔则控制着各处的海滩和内陆废墟。",al={"谁领导藏宝海湾","海角统治者","谁控制着海角"}},{q="部落和联盟都能使用藏宝海湾吗？",a="是的。藏宝海湾是一个由热砂港维护的开放式中立港口。只要旅行者保持武器入鞘，且在城市范围内维护和平，联盟和部落的冒险者都可以使用其码头、商人、飞行管理员和拍卖行。",al={"藏宝海湾是中立的吗","联盟与部落在藏宝海湾","部落可以进入藏宝海湾吗"}},{q="什么是古拉巴什竞技场？",a="古拉巴什竞技场是位于海角北缘的一座古代巨魔斗兽坑，战斗者们汇聚于此进行试炼。",al={"古拉巴什宝箱","竞技场规则","荆棘谷pvp竞技场"}},{q="旅行者如何往返于荆棘谷海角和卡利姆多之间？",a="一艘地精运营的蒸汽船定期往返于藏宝海湾码头和贫瘠之地的港口城市棘齿城之间，提供了横跨南海的少数几种远洋客运航线之一。",al={"前往棘齿城的船","前往卡利姆多的交通工具","藏宝海湾的船"}}},fp="21,323,21.466.0,31.516.0,80.184.0,36.256.0,42.271.0,28.132.0,51.196.0"}
P.entries["subzone:capital-gardens"] = {n="Capital Gardens",s="Capital Gardens构成了位于菲拉斯的古老精灵遗迹厄运之槌的西区。这里曾经是一座宁静优美的卡多雷贵族公园，如今却已枯萎成一片荒凉的林地，游荡着被腐蚀的古树、幽灵以及辛德拉的残部。",h="Capital Gardens构成了位于菲拉斯的古老精灵遗迹厄运之槌的西区。这里曾经是一座宁静优美的卡多雷贵族公园，如今却已枯萎成一片荒凉的林地，游荡着被腐蚀的古树、幽灵以及辛德拉的残部。",kw={"图书馆区","capital gardens","厄运之槌西区","埃雷萨拉斯","菲拉斯","伊莫塔尔","辛德拉"},ang={["class:Mage"]="尽管已经荒废，花园中依然保留着通往图书馆区的路径，那里是卡利姆多现存的、关于大分裂前魔法理论最伟大的宝库之一。",["race:NightElf"]="对于暗夜精灵来说，走在Capital Gardens那荒芜的铺路石上，是一次关于上层精灵狂妄自大以及奥术成瘾所带来的灾难性代价的惨痛警示。"},sec={{t="腐朽的圣所",b="一万年前，埃雷萨拉斯曾是卡多雷帝国最璀璨的明珠之一。Capital Gardens作为其户外区域，拥有繁茂的魔法植被和宏伟的大理石露台，是上层精灵法师们辩论和休憩的地方。大分裂之后，这片飞地陷入了绝境。由于失去了永恒之井，留守的辛德拉转而通过黑暗魔法来维持永生，任由花园枯萎。如今，灰暗扭曲的枝干和被腐蚀的树人布满了破碎的庭院，残留的魔法腐化使得这片森林永远无法真正愈合。"},{t="图书馆区与监狱",b="穿过杂草丛生的小径和充满敌意的古树，Capital Gardens通向辛德拉堡垒的深处。道路直达上层精灵法庭和图书馆区——那里保存着数个世纪以来的奥术知识和被遗忘的典籍。更深处则是伊莫塔尔的监狱，幸存的精灵在那里束缚了一只恶魔以吸取其力量，这种绝望的举动将周边的花园扭曲成了如今梦魇般的景象。"}},faq={{q="什么是Capital Gardens？",a="Capital Gardens是厄运之槌的西区，位于菲拉斯中部的埃雷萨拉斯遗迹内。它曾经是这座城市上层精灵精英们居住的原始公共公园。",al={"什么是capital gardens","厄运之槌西区花园","埃雷萨拉斯公园"}},{q="为什么这里的树木和古树会受到腐蚀？",a="永恒之井被毁后，幸存的辛德拉通过吸取被召唤的恶魔伊莫塔尔体内的邪能来维持生存。由此产生的动荡魔法泄露缓慢地扭曲了当地的植被，并使当地的古树陷入了狂暴的疯狂之中。",al={"为什么这里的古树是邪恶的","树木发生了什么","为什么这里一片荒凉"}},{q="这个区域通向哪里？",a="花园通往厄运之槌西区建筑群的更深处，连接着上层精灵法庭、学术性的图书馆区以及关押恶魔伊莫塔尔的内部圣所。",al={"capital gardens通往哪里","它通向何处"}},{q="花园里还有友好的精灵吗？",a="游荡在小径上的大多数上层精灵都是敌对的灵魂或疯狂的守卫。不过，在附近的图书馆区内，仍有一些辛德拉学者留存，他们愿意交换古老的知识或用失落的精灵法典进行交易。",al={"里面有盟友吗","谁居住在capital gardens"}}},fp="15,263,19.609.0,28.475.1,28.195.0,46.280.0,26.182.0,49.232.0"}
P.entries["subzone:cathedral-of-light"] = {n="Cathedral of Light",s="Cathedral of Light是暴风城的精神核心，也是圣光教会的主要圣所。它高耸于Cathedral Square之上，是人类牧师和白银之手骑士团的中央堡垒。",h="Cathedral of Light是暴风城的精神核心，也是圣光教会的主要圣所。它高耸于Cathedral Square之上，是人类牧师和白银之手骑士团的中央堡垒。",kw={"本尼迪塔斯","cathedral of light","cathedral square","达索瑞恩·拉尔","圣光","劳瑞娜","沙东布瑞克","白银之手","暴风城"},ang={["class:Paladin"]="Cathedral of Light是你在暴风城的主要职业大厅，像达索瑞恩·拉尔和格雷森·沙东布瑞克公爵这样的导师会引导你完成《勇气之书》和《神圣之书》的神圣试炼。",["class:Priest"]="作为圣光教会在南部王国的最高驻地，大教堂是高阶牧师劳瑞娜和大主教本尼迪塔斯培养你的精神虔诚和神圣治疗艺术的地方。"},sec={{t="信徒的圣所",b="在第一次战争中遭到破坏后，在大主教阿隆苏斯·法奥和当时还是主教的本尼迪塔斯的指导下，Cathedral of Light得以重建，成为了一座高耸的坚韧灯塔。随着第三次战争中洛丹伦陷落于天灾军团，教会的中心南移至暴风城。如今，大主教本尼迪塔斯就在这座宏伟的大厅里引导信徒，为整个联盟提供精神指引。"},{t="虔诚与武备大厅",b="除了作为祈祷和治疗的场所外，大教堂还是白银之手骑士团在南部王国残部的主要总部。格雷森·沙东布瑞克公爵和达索瑞恩·拉尔等高阶人物，通过《勇气之书》和《神圣之书》的神圣试炼来训练有前途的侍从。与他们一同，高阶牧师劳瑞娜引导虔诚的侍僧领悟圣光最深奥的教义，培养圣光勇士以抵御迪菲亚潜行者和天灾军团日益增长的威胁。"}},faq={{q="谁在大教堂内领导教会？",a="大主教本尼迪塔斯是圣光教会的领袖。在洛丹伦沦陷和大主教阿隆苏斯·法奥去世后，本尼迪塔斯便在暴风城的讲坛上承担起了重组后的教会的精神领导职责。",al={"大教堂领袖","谁是大主教","谁领导教会"}},{q="大教堂与圣骑士有何关联？",a="大教堂是白银之手骑士团在暴风王国的主要作战总部。格雷森·沙东布瑞克公爵和达索瑞恩·拉尔等著名的圣骑士在此指导新晋侍从，授予神圣典籍，并指挥十字军对抗王国的敌人。",al={"白银之手暴风城","暴风城圣骑士职业大厅","为什么圣骑士在这里"}},{q="大教堂的地板下面是什么？",a="主圣所下方是大教堂的地下墓穴，那是受人尊敬的英雄、牧师和圣骑士的安息之所。",al={"大教堂地下室","大教堂墓穴","大教堂下面有什么"}}},fp="18,203,25.417.0,26.474.0,42.188.0,51.228.0,38.123.0"}
P.entries["subzone:cathedral-square"] = {n="Cathedral Square",s="Cathedral Square是暴风城的精神与市政中心，雄伟的Cathedral of Light坐落于此。除了作为礼拜和祈祷的场所，这个繁华的广场还容纳了市政厅、城市孤儿院以及银色黎明在该地区的总部等市政机构。",h="Cathedral Square是暴风城的精神与市政中心，雄伟的Cathedral of Light坐落于此。除了作为礼拜和祈祷的场所，这个繁华的广场还容纳了市政厅、城市孤儿院以及银色黎明在该地区的总部等市政机构。",kw={"银色黎明","cathedral of light","cathedral square","市政厅","圣职区","孤儿院","圣骑士","牧师","暴风城"},ang={["class:Paladin"]="对于圣骑士来说，Cathedral Square是信仰和职责的源泉，这里汇聚了导师、神圣誓言以及专为圣战勇士量身打造的特制护甲商。",["class:Priest"]="广场上宁静的大厅和高耸的尖塔为牧师提供了一个与圣光沟通、推进灵性研究以及服务暴风城市民的安宁圣所。"},sec={{t="圣职区",b="Cathedral Square位于Trade District西北方，Dwarven District东南方，是暴风城王国的信仰中心。矗立在天际线上的是Cathedral of Light，这是艾泽拉斯所有圣光信徒最重要的圣所。牧师、圣骑士和治疗者汇聚于此进行学习、祈祷和训练。市民、朝圣者以及由校长丹娜带领的当地学童经常在广场上交流和沉思。"},{t="市政中心与圣职秩序",b="该区域不仅仅用于祈祷；它也是首都最繁忙的市政中心之一。广场内设有暴风城孤儿院和市政厅，是王国行政生活的基石。专为圣战者服务的特殊护甲商和武器匠，例如Righteous Plates和Just Maces，都在街道两旁开店。它同时也是银色黎明在暴风城的行动基地，招募人员和代表在此协调救援工作，并集结勇士以应对北部王国天灾军团的威胁。"}},faq={{q="什么是Cathedral Square？",a="Cathedral Square是暴风城的一个主要区域，以Cathedral of Light为中心。它既是圣光修行者的精神枢纽，也是容纳了市政厅、当地孤儿院和各类商铺的重要市政中心。",al={"大教堂区","圣职区","这是什么地方"}},{q="谁在Cathedral Square进行训练？",a="联盟的牧师和圣骑士来到Cathedral Square和Cathedral of Light磨练技能并研习神圣教义。医疗人员和护理员也在此接受急救训练师的指导。",al={"职业训练师","谁在这里训练","圣骑士牧师训练师"}},{q="为什么银色黎明设在这里？",a="银色黎明在Cathedral Square设有一个重要的办事处，旨在招募有能力的勇士，并协调暴风城的后勤支援，以支持他们在瘟疫之地对抗天灾军团的持久圣战。",al={"暴风城银色黎明","银色黎明驻地"}},{q="Cathedral Square通向哪里？",a="桥梁和运河通道将Cathedral Square与东南方繁华的Trade District、西北方工业气息浓厚的Dwarven District以及西南方宁静的法师区花园直接相连。",al={"连接区域","这里通向哪里"}}},fp="16,161,17.386.0,26.392.0,25.157.0,31.152.0,36.147.0,33.158.0"}
P.entries["subzone:cauldron"] = {n="大熔炉",s="大熔炉是一处巨大的露天挖掘场，占据了灼热峡谷的中心地带。这座火热的采石场由黑铁部族运营，受尽折磨的奴隶在残暴的监工和游荡的元素生物的监视下，日夜不停地在此劳作。",h="大熔炉是一处巨大的露天挖掘场，占据了灼热峡谷的中心地带。这座火热的采石场由黑铁部族运营，受尽折磨的奴隶在残暴的监工和游荡的元素生物的监视下，日夜不停地在此劳作。",kw={"大熔炉","黑铁矮人","挖掘","熔岩元素","采石场","灼热峡谷","奴隶工人","奴隶"},ang={["profession:Mining"]="大熔炉中巨大的机械挖掘机和露天梯田展现了黑铁部族挖掘工程的工业规模，这些工程直接开凿在不稳定的火山地壳之上。",["race:Dwarf"]="亲眼目睹黑铁矮人的堕落——在火元素之中将有知觉的俘虏当作可随意消耗、破碎不堪的劳动力来使用——让铁炉堡矮人感到深深的厌恶。"},sec={{t="熔岩采石场",b="大熔炉深深刻在灼热峡谷那焦灼的土地上，是在索瑞森大帝灾难性地召唤出拉格纳罗斯后加固而成的。巨大的黑铁挖掘机械喷吐着浓烟，环绕在峡谷四周，从阴燃的岩石中刮取矿石。在燃烧的裂隙深处，活生生的火焰与熔岩元素与黑铁工头一同徘徊，而地底的热气正不断地从山腹中涌出。"},{t="破碎的劳工",b="在矿坑深处，被俘的奴隶工人在黑铁监工的鞭笞下，忍受着残酷而无尽的轮班。在无情的劳作、闷热的高温和折磨下，许多劳工已经彻底疯狂。他们不再能分辨敌友，会猛烈攻击任何打扰他们劳作的局外人——即使对方可能是来给予他们获得自由机会的人。"}},faq={{q="大熔炉是什么？",a="大熔炉是一座巨大的露天矿场和挖掘场，位于灼热峡谷的中心。它由黑铁部族建造并加固，是用于在极其不稳定的火山环境下开采石料和矿石的工业中心。",al={"大熔炉背景故事","大熔炉是什么","灼热峡谷采石场"}},{q="谁在控制挖掘作业？",a="黑铁部族控制着整个场地。他们使用重型挖掘机和武装监工来监督作业，对矿坑及其劳工维持着残酷的统治。",al={"谁在运营大熔炉","大熔炉主人"}},{q="为什么奴隶会攻击试图提供帮助的冒险者？",a="这些奴隶已被残酷的折磨、灼人的热浪和无休止的疲惫所击垮。在主人的虐待和艰苦的生存环境下，他们早已陷入疯狂，破碎的精神使他们将任何对工作的干扰都视为威胁，从而攻击附近的任何人。",al={"为什么奴隶具有敌意","奴隶工人的攻击","可以解放奴隶吗"}},{q="矿坑里住着什么样的生物？",a="除了黑铁监工和他们的奴隶劳工外，大熔炉那充满火焰的裂隙中爬满了不稳定的火元素和熔岩元素，这些都是由峡谷的火山特性所释放出来的。",al={"大熔炉怪物","大熔炉里有什么","大熔炉中的怪物"}}},fp="8,243,17.465.0,20.403.0,21.253.0,28.169.0,53.254.0,44.188.0"}
P.entries["subzone:cavern-of-mists"] = {n="Cavern of Mists",s="Cavern of Mists是通往哀嚎洞穴深处的宽阔外室。受从岩石中喷涌而出的地下间歇泉滋养，其中心的池塘和悬浮的迷雾中栖息着奇怪、变异的野生生物，它们就在副本传送门入口外游荡。",h="Cavern of Mists是通往哀嚎洞穴深处的宽阔外室。受从岩石中喷涌而出的地下间歇泉滋养，其中心的池塘和悬浮的迷雾中栖息着奇怪、变异的野生生物，它们就在副本传送门入口外游荡。",kw={"贫瘠之地","cavern of mists","间歇泉","雷霆蜥蜴","鞭笞者特里格","哀嚎洞穴"},ang={["class:Druid"]="在浓雾中繁衍的扭曲野生生物给了塞纳里奥德鲁伊们最初的警示，让他们意识到纳拉雷克斯的翡翠梦境交流已经偏离了轨道，堕落得有多深。",["faction:Horde"]="这片迷雾坐落在贫瘠之地的中心，清除潜伏在这里的掠食性野兽，对于保障十字路口周围的贸易路线和前哨站至关重要。"},sec={{t="梦魇的门槛",b="在进入哀嚎洞穴真正的核心之前，旅行者必须先穿过Cavern of Mists。浓厚而温暖的蒸汽终年弥漫在空气中，这些蒸汽源自洞穴底部喷涌而出并汇入中央深池的天然间歇泉。尽管这里只是一个入口，但远非宁静之地。成群的迅猛龙、毒蛇、软泥怪和半水生的雷霆蜥蜴在岩架和水域中徘徊，还有像九头蛇“鞭笞者特里格”这样的臭名昭著的野兽。它为冒险者们提供了一个不祥的预兆，预示着深处滋生的不自然生长物。"}},faq={{q="Cavern of Mists在哪里？",a="Cavern of Mists构成了哀嚎洞穴的外部洞穴系统，位于贫瘠之地十字路口的西南方。它是玩家在到达副本传送门前必须穿过的非副本区域。",al={"cavern of mists位置","cavern of mists在哪里","哀嚎洞穴入口洞穴"}},{q="为什么叫它Cavern of Mists？",a="活跃的间歇泉不断从石质地面喷涌而出，汇入中央池塘，并使地下空气中充满了沉重、潮湿的迷雾。",al={"为什么有雾","cavern of mists名称由来"}},{q="这里生活着哪些生物？",a="这个洞室里生活着迅猛龙、软泥怪、风蛇、毒蛇、蟾蜍和栖息在池塘里的雷霆蜥蜴，偶尔还能见到稀有的九头蛇鞭笞者特里格。",al={"cavern of mists里的怪物","cavern of mists怪物"}},{q="鞭笞者特里格是谁？",a="鞭笞者特里格是一只危险的稀有九头蛇，偶尔会发现它与洞室中央水池里的雷霆蜥蜴一起游动。",al={"特里格","哀嚎洞穴稀有九头蛇"}}},fx={["923aae57"]={q="Cavern of Mists是什么地方？",a="Cavern of Mists也被称为哀嚎洞穴，是哀嚎洞穴深处之前的一处外围地下洞室。活跃的间歇泉从石质地面喷涌而出，洞穴中央有一片苍翠的水池，温暖的水流与蒸汽交融，让封闭的地下空间常年笼罩在浓重雾气中。",al={"cavern of mists是什么地方","cavern of mists的背景","关于cavern of mists"}},["8ec0c6f8"]={q="Cavern of Mists危险吗？",a="危险，粗心的旅人会在这处洞室遭遇险境。凶猛的迅猛龙、蠕动的软泥怪、毒蛇和会咬人的风蛇都在雾蒙蒙的岸边和浑浊的水中游荡。中央深池中栖息着掠食性的棘齿龙，此外还有名为“鞭笞者特里高尔”的隐秘多头蛇等可怕威胁。",al={"cavern of mists危险吗","cavern of mists的危险","cavern of mists里的威胁"}}},fp="15,268,30.540.0,29.223.0,37.134.0,25.180.0,26.141.0"}
P.entries["subzone:caverns-of-time"] = {n="时光之穴",s="时光之穴坐落在塔纳利斯东部的悬崖峭壁中，是诺兹多姆和青铜龙军团的神秘巢穴。在蜿蜒曲折的深处，巨龙们监视并守护着艾泽拉斯脆弱的时间线，防止任何凡人的闯入或对时间的篡改。",h="时光之穴坐落在塔纳利斯东部的悬崖峭壁中，是诺兹多姆和青铜龙军团的神秘巢穴。在蜿蜒曲折的深处，巨龙们监视并守护着艾泽拉斯脆弱的时间线，防止任何凡人的闯入或对时间的篡改。",kw={"阿纳克洛斯","青铜龙军团","时光之穴","诺兹多姆","塔纳利斯","时间的","时间线"},ang={["class:Mage"]="洞穴中充斥的时间魔法远超凡人的时空奥术，让人在这些超越奥术操纵的强大力量面前感到谦卑。",["race:NightElf"]="卡多雷对巨龙军团守护者们的古老契约记忆犹新，他们认为诺兹多姆的职责对于世界的生存至关重要。"},sec={{t="蜿蜒的时间线",b="时光之穴深凿于荒漠悬崖之下，是历史洪流汇聚的枢纽。在世界诞生之初，泰坦赋予了永恒者诺兹多姆和他的青铜龙军团神圣的职责，让他们成为这些走廊的永恒守卫。在内部，时间流向变幻莫测；过去与未来的碎片在隐秘的裂隙中穿梭，从遥远时代被取回的遗物散落在沙地上。虽然巨龙阿纳克洛斯在入口附近守望，但较小的青铜幼龙也在蜿蜒的通道中巡逻，凶猛地保护着唯一的一条真实时间线。"},{t="时代的宝库",b="这里不仅是过去与未来的交汇点，也是一座奇特的宝库。千百年来，青铜龙军团从艾泽拉斯的各个角落收集了历史碎片：古老的矮人建筑、来自洛丹伦的岗哨塔、兽人氏族的酋长营房，以及可追溯到斯托姆加德第一位国王时期的盔甲。然而，尽管偶尔有旅行者敢于溜过守卫一睹这些奇观，但内部的门户依然紧闭，等待着龙军团认为凡人干预成为必要的那一天。"}},faq={{q="我现在能进入时光之穴吗？",a="不能。通往洞穴的道路依然封锁，青铜龙军团不接待任何凡人。你必须小心在入口处巡逻的幼龙；虽然年长的青铜龙阿纳克洛斯对旅行者不屑一顾，但他的同伴会攻击任何靠得太近的凡人。",al={"可以进入时光之穴吗","如何进入时光之穴","时光之穴开放吗"}},{q="谁统治着时光之穴？",a="洞穴属于永恒者诺兹多姆，他是泰坦赋予力量用以监管时间的巨龙军团守护者。日常的监管和入口守卫工作通常由他的主要后裔阿纳克洛斯，以及青铜龙军团的卫士们共同承担。",al={"时光之穴由谁领导","时光之穴首领","谁住在时光之穴"}},{q="为什么里面会有随意的建筑物和手工艺品？",a="诺兹多姆花费了数个时代来编目和收集艾泽拉斯历史上的实物遗迹。洞穴中散落着错位的宝藏，包括一座完整的洛丹伦岗哨塔、矮人建筑、兽人结构，以及来自早已被遗忘的凡人王国的武器。",al={"为什么时光之穴里有人类塔楼","时光之穴的文物"}},{q="青铜龙军团在此处的目的是什么？",a="泰坦赋予他们神圣的职责，即守护时间的流动并维护历史的完整性。他们确保凡人的篡改或外界的破坏不会扰乱那些定义世界的事件。",al={"青铜龙在这里做什么","青铜龙军团的目的"}}},fp="15,275,20.575.0,15.538.0,46.289.0,35.254.0,52.279.0,52.219.0"}
P.entries["subzone:cenarion-enclave"] = {n="塞纳里奥区",s="塞纳里奥区是达纳苏斯西北部郁郁葱葱的区域，它是塞纳里奥议会在首都的核心聚会地和权力中心。在大德鲁伊玛法里奥·怒风沉睡于翡翠梦境期间，大德鲁伊范达尔·鹿盔便在这片树林的巨大树洞和生机勃勃的枝干间领导着暗夜精灵德鲁伊们。",h="塞纳里奥区是达纳苏斯西北部郁郁葱葱的区域，它是塞纳里奥议会在首都的核心聚会地和权力中心。在大德鲁伊玛法里奥·怒风沉睡于翡翠梦境期间，大德鲁伊范达尔·鹿盔便在这片树林的巨大树洞和生机勃勃的枝干间领导着暗夜精灵德鲁伊们。",kw={"塞纳里奥议会","塞纳里奥区","达纳苏斯","德鲁伊","范达尔·鹿盔","夜刃豹","泰达希尔"},ang={["class:Druid"]="对于暗夜精灵德鲁伊来说，塞纳里奥区是你们在泰达希尔的组织民事中心，在大德鲁伊范达尔·鹿盔的严厉指导下提供训练和指引。",["class:Hunter"]="猎人们聚集在该区域东侧的枝干上，与饲养首都夜刃豹的兽王们一起磨练他们的射击技巧和荒野知识。"},sec={{t="议会之心",b="塞纳里奥区位于神殿花园上方的一处高台上，由刻有符文树皮的古老橡树和白蜡树塑造而成。塞纳里奥议会的成员们聚集在直接由活木和岩石塑造的建筑中。由于玛法里奥·怒风身陷翡翠梦境，大德鲁伊范达尔·鹿盔在此主持大局，他不顾与高阶女祭司泰兰德·语风之间挥之不去的政治摩擦，竭力推行他那关于泰达希尔的雄心壮志。除了在溪流间冥想的德鲁伊外，该区域也是首都精灵猎人的聚集地，这里的马厩里，技艺精湛的骑手们会学习如何驯服达纳苏斯夜刃豹。"},{t="枝叶间的阴影",b="虽然这里以宁静的自然保护区而闻名，但该区域也隐藏着一些秘密活动。在最西侧枝干的中空根部下方，坐落着达纳苏斯潜行者们的地下避难所，他们在上方沙沙作响的树冠掩护下，悄无声息地进行着自己的勾当。"}},faq={{q="谁在领导塞纳里奥区？",a="大德鲁伊范达尔·鹿盔目前领导着这片树林以及居住在达纳苏斯的暗夜精灵德鲁伊。塞纳里奥议会的最高领导者玛法里奥·怒风依然被困在翡翠梦境中，陷入了一种无法解释的深沉睡眠，这使得鹿盔成为了实际的权威。",al={"这里的主事人是谁","塞纳里奥区领导者","范达尔·鹿盔"}},{q="什么职业在这里训练？",a="该区域是首都德鲁伊训练师的主要驻地，他们在活树间指导新手。东侧的枝干是城内猎人训练师的所在地，而西侧枝干下方的根部区域则隐藏着一处安静的潜行者训练师巢穴。",al={"塞纳里奥区的训练师","达纳苏斯德鲁伊训练师","达纳苏斯猎人训练师"}},{q="我在哪里可以购买夜刃豹坐骑？",a="照看达纳苏斯珍贵豹类坐骑的骑术训练师和饲养员驻扎在树林入口附近的东侧树木底部，他们为符合条件的联盟旅行者提供骑术训练和夜刃豹坐骑。",al={"夜刃豹训练师","暗夜精灵坐骑训练师","达纳苏斯骑术训练师"}},{q="塞纳里奥议会对联盟的立场是什么？",a="虽然该区域位于联盟首都境内，并由坚定主张民族主义的范达尔·鹿盔领导，但作为一个更广泛的组织，塞纳里奥议会始终致力于维护自然秩序，而非参与派系战争。然而，由于鹿盔的存在，这个特定的区域在立场上强烈倾向于暗夜精灵的区域利益。",al={"塞纳里奥议会是联盟吗","德鲁伊是联盟专属吗"}}},fp="16,238,19.556.0,21.230.0,31.273.0,24.244.0,35.209.0,57.284.0"}
P.entries["subzone:cenarion-hold"] = {n="塞纳里奥要塞",s="塞纳里奥要塞是塞纳里奥议会在希利苏斯严酷沙漠中建立的坚固据点。为了监视埋藏在沙土之下的古老威胁，它被建立起来，成为了卡利姆多最大的德鲁伊定居点之一，也是这片荒凉之地中罕见的安全避难所。",h="塞纳里奥要塞是塞纳里奥议会在希利苏斯严酷沙漠中建立的坚固据点。为了监视埋藏在沙土之下的古老威胁，它被建立起来，成为了卡利姆多最大的德鲁伊定居点之一，也是这片荒凉之地中罕见的安全避难所。",kw={"塞纳里奥议会","塞纳里奥要塞","德鲁伊","卡利姆多","流沙之战","异种虫","希利苏斯"},ang={["class:Druid"]="作为月光林地之外最大的德鲁伊飞地之一，塞纳里奥要塞体现了塞纳里奥议会维护自然平衡、抵御宇宙恐怖的誓言。",["race:NightElf"]="对于暗夜精灵来说，这座堡垒纪念着数千年前那场灾难性的流沙之战中做出的古老牺牲。"},sec={{t="沙丘中的堡垒",b="坐落在希利苏斯荒凉的沙地之中，塞纳里奥要塞作为塞纳里奥议会的南部指挥中心而存在。穿过安戈洛环形山蜿蜒的小径即可到达此地。这座堡垒是在流沙之战的历史性事件结束后，为了监控被封印在沙漠地下的沉睡威胁而建立的。在布满虫群异种虫和沙暴的荒凉广袤之地，这座要塞为监视那些被囚禁的过往恐怖的暗夜精灵和牛头人德鲁伊提供了至关重要的庇护、贸易和后勤支持。"},{t="中立领地",b="因为守护世界免受古老邪恶侵害的职责高于凡人的纷争，塞纳里奥要塞在严格的塞纳里奥议会中立原则下运作。联盟和部落的旅行者都可以进入其城墙之内，受到当地补给线依然岌岌可危的军需官和守望者的欢迎。通过连接菲拉斯、塔纳利斯和安戈洛环形山前哨站的飞行路线，该要塞成为了那些敢于调查沙漠中日益动荡局势的凡人冒险者的唯一集结地。"}},faq={{q="谁控制着塞纳里奥要塞？",a="这座要塞完全由玛法里奥·怒风创立的德鲁伊组织——塞纳里奥议会管理和驻守。它保持完全中立，欢迎联盟和部落的成员。",al={"谁在管理塞纳里奥要塞","塞纳里奥要塞阵营","塞纳里奥要塞中立吗"}},{q="为什么这座堡垒要建在沙漠里？",a="它是在流沙之战后建立的，旨在监视封印在希利苏斯深处的古老邪恶，并压制该地区泛滥的异种虫群的复苏。",al={"为什么塞纳里奥要塞在希利苏斯","塞纳里奥要塞的目的","德鲁伊为何在此建立基地"}},{q="如何前往塞纳里奥要塞？",a="步行者通常会走那条从安戈洛环形山向西北方向蜿蜒而上的陡峭山路。飞行网络也将要塞与加基森、安戈洛和菲拉斯的飞行管理员连接起来。",al={"如何前往塞纳里奥要塞","塞纳里奥要塞路径","进入希利苏斯"}},{q="两个阵营的成员都能在这里使用服务吗？",a="是的。塞纳里奥要塞内的商人和飞行管理员与任何愿意勇敢面对沙漠的冒险者进行自由贸易，无论其政治立场如何。",al={"部落在这里安全吗","联盟可以在这里休息吗","塞纳里奥要塞商人"}}},fp="13,294,22.529.0,14.518.0,27.212.0,50.202.0,35.190.0,47.158.0"}
P.entries["subzone:chamber-of-atonement"] = {n="Chamber of Atonement",s="Chamber of Atonement是血色修道院内墓地区域阴森的入口大厅。在这里，在悬挂着铁链的石拱顶下，血色十字军会对被俘的亡灵和其他被视为异教徒的对象进行残酷的审讯和拷打，随后将他们的残骸扔进外面的回廊中。",h="Chamber of Atonement是血色修道院内墓地区域阴森的入口大厅。在这里，在悬挂着铁链的石拱顶下，血色十字军会对被俘的亡灵和其他被视为异教徒的对象进行残酷的审讯和拷打，随后将他们的残骸扔进外面的回廊中。",kw={"chamber of atonement","forlorn cloister","墓地","审讯员韦沙斯","血色修道院","拷打","vorrel sengutz"},ang={["class:Priest"]="对神圣誓言的亵渎在这里体现得淋漓尽致，十字军的审讯官们将神圣的纪律扭曲成了肉体的屠杀和残忍的折磨。",["race:Undead"]="Chamber of Atonement代表了血色十字军对你的人民最残酷的一面，这里是像Vorrel Sengutz这样的被遗忘者俘虏仅仅因为他们的存在而受到系统性拷打的地方。"},sec={{t="苦痛大厅",b="作为通往Forlorn Cloister的入口，Chamber of Atonement绝非一处安静祈祷的圣地。相反，血色十字军将这座宏伟的门厅改造成了一座刑讯室，里面布满了拷问架、镣铐和燃烧的火盆。狂热的审讯官利用这些刑具来逼供并折磨俘虏，他们认为极度的痛苦是这些邪恶生物唯一应得的赎罪方式。大厅内回荡着受难者的哀嚎，残酷的监工们在这里监督着一切，确保那些进入此地的人极少能完整地走出去。"},{t="审讯官的领域",b="这座大厅由审讯员韦沙斯掌管，他是十字军中最残忍的胁迫手段实施者之一。韦沙斯以击垮任何胆敢踏入修道院边界的人的意志为荣，其行径令人发指。他最“珍视”的受害者之一是被遗忘者俘虏Vorrel Sengutz，他在韦沙斯手中忍受了数周无尽的折磨。这些墙壁内上演的残酷行径向外界证明，血色十字军所谓的纯净圣战已经扭曲成了肆意的虐待狂行径。"}},faq={{q="Chamber of Atonement有何用途？",a="它是血色十字军在修道院墓地区域内设置的审讯和拷打侧厅。俘虏，主要是被遗忘者和其他被视为敌人的对象，会被带到这里，在被扔进墓地之前，他们会受到残酷刑具的审讯、摧残和折磨。",al={"大厅用途","为什么这里有刑具","chamber of atonement发生了什么"}},{q="谁控制着这个大厅？",a="这个房间由血色十字军的审讯员韦沙斯指挥，他是一名残忍的拷问者，以从受害者的痛苦中获得快感而臭名昭著。",al={"谁是这里的首领","chamber of atonement领袖","谁负责刑讯室"}},{q="这个房间通往哪里？",a="这是墓地区域的最外层大厅，直接通往Forlorn Cloister，那里是阵亡十字军战士和不安的亡灵安息的露天墓地。",al={"大厅出口","chamber of atonement通往何处","atonement之后的区域"}},{q="谁被关押在这里？",a="一名名为Vorrel Sengutz的被遗忘者俘虏已被关押在室内，并受到审讯员韦沙斯长达数周的拷打。",al={"谁是这里的囚犯","vorrel sengutz","被拷打的囚犯"}}},fx={["5cd82fbf"]={q="什么是Chamber of Atonement？",a="Chamber of Atonement是血色修道院墓地区的最外侧大厅。它正对着Forlorn Cloister和露天墓地，是一处阴森的门槛，血色十字军会把俘虏拖到这里，施以残酷审讯。",al={"什么是chamber of atonement","chamber of atonement介绍","关于chamber of atonement"}},f468ffff={q="Chamber of Atonement危险吗？",a="这里极其危险。审讯员韦沙斯率领一群狂热的血色十字军施刑者驻守此处，周围满是骇人的刑具。任何闯入者，或被视为亡灵同情者的人，都会立刻遭到攻击，并承受与囚犯同样无情的折磨。",al={"chamber of atonement危险吗","chamber of atonement的威胁","chamber of atonement有多危险"}},["1937bc67"]={q="为什么叫Chamber of Atonement？",a="血色十字军以此命名，是因为他们扭曲地认为，任何被亡灵之力污染或反对他们圣战的生灵，都必须忏悔并以痛苦偿还罪孽。在审判官看来，刀下的苦难与折磨才是赎罪的唯一正途。",al={"为什么叫chamber of atonement","chamber of atonement名称含义","为什么叫赎罪厅"}}},fp="20,317,15.566.0,25.480.0,42.292.0,26.157.0,26.171.0,31.128.0"}
P.entries["subzone:champions-hall"] = {n="勇士大厅",s="勇士大厅坐落在Old Town的南端，是暴风城中为联盟的荣誉老兵提供的军官军营和物资仓库。在其入口之后，军需官会为该阵营久经考验的战士分发特制的武器、板甲和徽章。只有在战场上展现出勇气的军官才能进入此地，入口处守卫森严。",h="勇士大厅坐落在Old Town的南端，是暴风城中为联盟的荣誉老兵提供的军官军营和物资仓库。在其入口之后，军需官会为该阵营久经考验的战士分发特制的武器、板甲和徽章。只有在战场上展现出勇气的军官才能进入此地，入口处守卫森严。",kw={"勇士大厅","大元帅","骑士","军官军营","old town","pvp商人","军需官","暴风城"},ang={["class:Warrior"]="对于前线作战人员来说，这座大厅代表了最终的军事储备库，提供仅供久经考验的战场领袖使用的重型作战装备和军械。",["faction:Alliance"]="这座大厅是联盟在暴风城军事功绩的最高象征，旨在向那些致力于抵御部落入侵的人们致敬。"},sec={{t="联盟军官军营",b="勇士大厅隐藏在Old Town一处守卫森严的入口之后，是联盟最杰出的战士们的禁地。军事指挥官们聚集在这里，在艾泽拉斯的战略地图上商讨正在进行的战役，四周陈列着军械和代表军衔的宏伟徽记。只有在联盟等级制度中达到军官级别——具体来说是骑士或更高军衔——的士兵才被允许进入。在内部，军事军需官为久经沙场的士兵提供精英武器、护甲和坐骑，这些装备专为在世界各地的争夺区域扭转与部落的战局而打造。"}},faq={{q="勇士大厅在哪里？",a="勇士大厅位于暴风城Old Town的南部，隐藏在一处有守卫的入口后方。",al={"勇士大厅在哪里","暴风城pvp商人位置","如何找到勇士大厅"}},{q="谁被允许进入勇士大厅？",a="只有在战场上赢得了骑士或更高军事军衔的联盟老兵才能获得通过入口的许可。未经考验的新兵和平民会被阻挡在门外。",al={"谁能进入","勇士大厅进入要求","为什么我不能进入勇士大厅"}},{q="勇士大厅里有什么？",a="大厅内有提供军官级武器、护甲、徽章和特制战争坐骑的军需官。联盟的战术家和将军们也会聚集在摆放着艾泽拉斯区域地图的战术桌旁。",al={"勇士大厅里有什么","勇士大厅有哪些商人","勇士大厅奖励"}},{q="这个建筑的部落对应物是什么？",a="部落的对应建筑是位于奥格瑞玛的传说大厅，它为部落的荣誉战士提供相同的军事物资服务。",al={"部落的勇士大厅","奥格瑞玛pvp房间","部落pvp军营"}}},fp="15,189,31.377.0,37.87.0,42.161.0,35.178.0,46.125.0"}
P.entries["subzone:charred-vale"] = {n="焦炭谷",s="焦炭谷是位于石爪山脉西南部的一处闷烧山谷，被荆棘谷地精鲁莽的滥砍滥伐和重型机械摧毁。这里曾经是树人和奇美拉的繁荣栖息地，如今却被火焰、游荡的元素生物和充满敌意的鹰身人所吞噬。",h="焦炭谷是位于石爪山脉西南部的一处闷烧山谷，被荆棘谷地精鲁莽的滥砍滥伐和重型机械摧毁。这里曾经是树人和奇美拉的繁荣栖息地，如今却被火焰、游荡的元素生物和充满敌意的鹰身人所吞噬。",kw={"焦黑的远古树人","血怒","焦炭谷","奇美拉","火元素","石爪","烈日石居","荆棘谷地精"},ang={["class:Druid"]="这里的破坏是一个严酷的警告，昭示着当自然平衡被无节制的贪婪打破时会发生什么，这也使该山谷成为了复垦工作的重点。",["faction:Horde"]="部落军队以烈日石居为基地，与塞纳里奥盟友密切合作，以遏制 Elemental Unrest，并击退荆棘谷地精留下的腐化后患。"},sec={{t="焦黑的林地",b="不久之前，这个西南部的盆地还是一片繁茂的高山森林，由雄伟的树人守护，并栖息着当地的奇美拉和鹰身人。它的毁灭始于荆棘谷地精的到来。这群贪婪的地精利用爆炸性机械砍伐森林，腐化了守护者，并唤醒了混乱的火元素。尽管树人们最终迫使地精撤退，但这片土地已经破碎不堪，布满了火烧的痕迹，并被撤退的伐木工留下的各种污秽装置所污染。"},{t="重生的挣扎",b="如今，焦黑的远古树人在烟雾和灰烬中盲目地游荡，与愤怒的元素生物并肩而行。血怒鹰身人在枯树残枝上筑巢，捍卫着它们残存的领地。尽管山谷充满了敌意，但来自烈日石居的德鲁伊拒绝放弃这片区域，他们派遣旅行者播下附魔种子并照料那些被腐化的远古树人，坚持不懈地试图收复这片焦土。"}},faq={{q="为什么焦炭谷会燃起大火？",a="这场灾难是由荆棘谷地精残酷的伐木作业造成的。他们破坏性的机械和激进的砍伐行为激怒了这片土地的原始灵魂，并释放出了席卷整个山谷的毁灭性火元素。",al={"为什么在燃烧","是谁烧毁了焦炭谷","焦炭谷发生了什么"}},{q="焦炭谷的森林还能恢复吗？",a="附近烈日石居的牛头人德鲁伊相信可以。他们委托旅行者安抚狂暴的树人，并在灰烬中播下附魔的大地种子，希望能从废墟般的土壤中催生出绿色的嫩芽。",al={"焦炭谷正在恢复吗","焦炭谷的德鲁伊"}},{q="焦炭谷栖息着哪些生物？",a="这个盆地里到处都是充满敌意的火元素之灵、焦黑且复仇心切的远古树人、焦灼的蛇怪和野生的奇美拉。此外，这里还深受血怒鹰身人的困扰。",al={"焦炭谷的怪物","焦炭谷有什么生物"}},{q="在被烧毁之前，焦炭谷叫什么名字？",a="它最初的名字已经随着时间流逝而遗失了，但在地精的斧头抵达之前，它曾以茂密的森林保护区而闻名。",al={"焦炭谷的旧称","焦炭谷的最初名字"}}},fp="12,212,19.517.0,20.346.0,32.218.0,48.222.0,40.166.0,50.134.0"}
P.entries["subzone:chill-breeze-valley"] = {n="寒风峡谷",s="寒风峡谷是位于丹莫罗西部的一处崎岖雪径，连接着矮人定居点卡拉诺斯和饱受战火蹂躏的诺莫瑞根城。虽然其主干道是年轻旅行者和难民常走的路，但其偏僻的角落里却潜藏着危险的野兽和血腥的巢穴。",h="寒风峡谷是位于丹莫罗西部的一处崎岖雪径，连接着矮人定居点卡拉诺斯和饱受战火蹂躏的诺莫瑞根城。虽然其主干道是年轻旅行者和难民常走的路，但其偏僻的角落里却潜藏着危险的野兽和血腥的巢穴。",kw={"洞穴","寒风峡谷","丹莫罗","诺莫瑞根","卡拉诺斯","t字形","雪怪"},ang={["race:Dwarf"]="登山者和年轻的矮人猎人会通过清理那些威胁到连接丹莫罗中部与西部高地重要通道的凶猛雪怪来磨练自己的意志。",["race:Gnome"]="对于从诺莫瑞根的浩劫中逃亡，寻求卡拉诺斯和铁炉堡庇护的侏儒难民来说，穿越寒风峡谷那布满掠食者的外围区域是生存下去的关键第一步。"},sec={{t="冰雪与利爪的交汇处",b="寒风峡谷在丹莫罗西部的群山中形成了一道T字形的沟壑。其东西走向的主路常有往返于卡拉诺斯和诺莫瑞根郊区的矮人与侏儒新手在此穿行。然而，误入峡谷南北两侧的分支则是另一回事了。这些阴暗的区域布满了血迹和残缺的尸骸，栖息着凶猛的掠食者——尤其是那些盘踞在深层冰洞中，以任何胆敢踏入其猎场者为食的野蛮雪怪。"}},faq={{q="寒风峡谷位于哪里？",a="寒风峡谷位于丹莫罗西部，坐落在东侧繁忙的矮人枢纽卡拉诺斯和西侧侏儒科技之城诺莫瑞根之间。",al={"寒风峡谷位置","寒风峡谷在哪里","寒风峡谷地图"}},{q="为什么穿过峡谷如此危险？",a="虽然卡拉诺斯和诺莫瑞根之间的主路相对安全且常有人迹，但峡谷北侧和南侧的岔路却是掠食野兽的猎场。那里的积雪被鲜血和撕碎的尸块染红，通往凶残且领地意识极强的雪怪所居住的洞穴。",al={"寒风峡谷怪物","寒风峡谷的危险","为什么这里有骨头"}},{q="这里有哪些野兽筑巢？",a="峡谷的深处是凶猛雪怪的家园，其中甚至还有一只体型庞大、力量惊人的雪怪将其中一个洞穴占为己有。",al={"寒风峡谷的雪怪","寒风峡谷里有什么生物"}}},fp="19,194,30.379.0,37.104.0,49.239.0,42.137.0"}
P.entries["subzone:chillwind-camp"] = {n="寒风营地",s="寒风营地坐落于从奥特兰克山脉通往西瘟疫之地的南部山口。该营地由联盟分遣队与银色黎明共同驻守，是通往洛丹伦废墟前的最后一个安全补给点。坐镇于这一险要的前哨站，指挥官们在此策划对附近天灾军团据点和瘟疫锅炉的打击行动。",h="寒风营地坐落于从奥特兰克山脉通往西瘟疫之地的南部山口。该营地由联盟分遣队与银色黎明共同驻守，是通往洛丹伦废墟前的最后一个安全补给点。坐镇于这一险要的前哨站，指挥官们在此策划对附近天灾军团据点和瘟疫锅炉的打击行动。",kw={"奥特兰克山脉","andorhal","银色黎明","阿什拉姆·瓦洛菲斯特","瘟疫锅炉","寒风营地","冰风岗","西瘟疫之地"},ang={["class:Paladin"]="有前途的圣骑士会被暴风城的格雷森·沙东布瑞克公爵指引至此，以协助瓦洛菲斯特指挥官，并将白银之手的神圣愤怒带给亡灵部队。",["faction:Alliance"]="寒风营地是联盟收复北洛丹伦努力的前锋，提供安全避难所、狮鹫运输以及针对天灾军团的行动指令。"},sec={{t="凋零之缘",b="寒风营地隐藏在从冰风岗蜿蜒而下的岩石隘口中，是联盟军队推进西瘟疫之地的第一道防线和主要作战基地。尽管高耸的山脊将其与最严重的腐化隔离开来，但北方死寂的寒意依然沉重地笼罩着营地的帐篷和栅栏。在阿什拉姆·瓦洛菲斯特指挥官的率领下，一小支由士兵、斥候和银色黎明专家组成的卫戍部队试图遏制在国王之路沿线徘徊的恐怖生物，并收集收复洛丹伦沦陷土地所需的关键情报。"},{t="消耗战",b="由于缺乏对安多哈尔或通灵学院这座亡灵要塞发动全面进攻所需的正规军队，寒风营地严重依赖于各地的勇士和雇佣兵。此处的行动专注于外科手术式的游击打击：收集关于The Cult of the Damned的情报，中和毒害土地的炼金瘟疫锅炉，并确保通往圣光之愿礼拜堂等东部前哨的补给线畅通。随着天灾军团盘踞在北面的废墟中，而被遗忘者加强了西部边境的防御，营地的守军战斗的目的仅仅是为了防止山口被敌军压制。"}},faq={{q="寒风营地的目的是什么？",a="寒风营地是联盟和银色黎明在西瘟疫之地边界的主要南部据点。它为在安多哈尔对天灾军团发动游击战以及中和区域内瘟疫锅炉的行动提供了安全的基地。",al={"为什么会有寒风营地","寒风营地的目的","什么是寒风营地"}},{q="如何从南海镇前往寒风营地？",a="从希尔斯布莱德丘陵的南海镇出发，向北前往塔伦米尔，然后沿着山间小径进入奥特兰克山脉的最东端。道路经过冰风岗的巨魔遗迹，随后向北穿过一条峡谷直接抵达营地。",al={"如何前往寒风营地","寒风营地路线","去寒风营地的路径"}},{q="这个前哨站有部落对应的版本吗？",a="部落对应的据点是亡灵壁垒，位于提瑞斯法林地和西瘟疫之地之间的西部边境。这两个前哨站都是针对区域内天灾军团作战的坚固补给基地。",al={"部落的寒风营地","寒风营地的部落版本","有部落版的寒风营地吗"}},{q="谁负责指挥寒风营地的部队？",a="阿什拉姆·瓦洛菲斯特指挥官领导着寒风营地的驻军，协调联盟志愿者、白银之手骑士团和银色黎明联络员在周边的废墟和被污染的农场开展行动。",al={"寒风营地的领导者","谁负责寒风营地","寒风营地指挥官"}}},fp="14,373,22.595.0,18.620.0,38.269.0,48.261.0,45.221.0,42.213.0"}
P.entries["subzone:chillwind-point"] = {n="冰风岗",s="冰风岗是一处位于奥特兰克山脉、希尔斯布莱德丘陵和西瘟疫之地之间高地边缘的岩石高地，也是一座古老的巨魔遗迹。它的名字来源于从北方被腐蚀的土地吹向山口的凛冽寒风。如今，这里是一个荒凉的瞭望点，主要住着一位孤独的巨魔神秘学家。",h="冰风岗是一处位于奥特兰克山脉、希尔斯布莱德丘陵和西瘟疫之地之间高地边缘的岩石高地，也是一座古老的巨魔遗迹。它的名字来源于从北方被腐蚀的土地吹向山口的凛冽寒风。如今，这里是一个荒凉的瞭望点，主要住着一位孤独的巨魔神秘学家。",kw={"奥特兰克","捕风者巴斯拉","寒风","冰风岗","希尔斯布莱德","瘟疫之地","巨魔遗迹","捕风者"},ang={["class:Shaman"]="山口中狂野的汇聚气流使冰风岗成为了一个元素汇聚之地，吸引着修行者前来向隐士捕风者巴斯拉学习。",["faction:Alliance"]="这些古老的遗迹位于寒风营地边防哨所的正南方，标志着争议不断的丘陵地带与恐怖的瘟疫之地之间的分界线。"},sec={{t="苦涩的十字路口",b="冰风岗位于希尔斯布莱德通往奥特兰克和被瘟疫侵蚀的北方地区的边缘地带，俯瞰着直通西瘟疫之地的山谷。在洛丹伦占领这些山口很久之前，远古巨魔就在这些高地上建造了石质建筑，这些遗迹至今仍屹立在那里，饱经风霜。今天，寒风穿过峡谷向南吹去，将陷落的北方大地的寒意带到了下方的丘陵地带。"},{t="捕风者",b="尽管这里环境恶劣且邻近天灾军团肆虐的土地，冰风岗并非完全荒无人烟。古老的石砌建筑为捕风者巴斯拉提供了庇护。他是一位丛林巨魔隐士，与穿过山口的狂暴大风进行沟通。前往北方的旅行者和萨满祭司经常会在废墟中寻找他的隐居营地，以学习山间气流的秘密。"}},faq={{q="什么是冰风岗？",a="冰风岗是一座古老的巨魔遗迹，坐落在一处高地上，俯瞰着希尔斯布莱德、奥特兰克和西瘟疫之地之间的山口。它的名字取自不断在邻近峡谷中呼啸而过的刺骨寒风。",al={"冰风岗概览","冰风岗在哪里","这是什么地方"}},{q="冰风岗和寒风营地是同一个地方吗？",a="不是，虽然它们经常被混淆。寒风营地是联盟和银色黎明在边界以北、西瘟疫之地内设立的防御前哨，而冰风岗则是稍微靠南一点的巨魔废墟高地。",al={"冰风岗与寒风营地的区别","寒风营地的不同之处","这是寒风营地吗"}},{q="谁住在冰风岗？",a="废墟中唯一的居住者是捕风者巴斯拉，一位友好的丛林巨魔，他研究风向，并帮助那些勇敢穿过山口的元素探索者和萨满祭司。",al={"谁在这里","那个巨魔是谁","巴斯拉"}},{q="为什么这里这么冷？",a="该据点直接毗邻一条狭窄的山谷，这条山谷将来自北部高海拔地区和西瘟疫之地被腐蚀的广袤土地上的冰冷气流汇聚并吹向较低的丘陵地带。",al={"为什么这里很冷","寒风","冰冷的风"}}},fp="15,245,19.408.0,15.358.0,24.210.0,46.185.0,29.156.0,23.170.0"}
P.entries["subzone:circle-of-aquementas"] = {n="Circle of Aquementas",s="Circle of Aquementas是一个神秘的直立石圈，位于塔纳利斯东海岸，落帆海湾以南。它是一个仪式场所，旅行者可以在这里召唤元素之灵Aquementas。",h="Circle of Aquementas是一个神秘的直立石圈，位于塔纳利斯东海岸，落帆海湾以南。它是一个仪式场所，旅行者可以在这里召唤元素之灵Aquementas。",kw={"aquementas","circle of aquementas","元素","落帆海湾","直立石块","塔纳利斯"},ang={["class:Shaman"]="石圈聚集原始能量并锚定元素之灵的能力，使它成为了任何漫步在塔纳利斯海岸的萨满祭司眼中极具吸引力的奇观。"},sec={{t="海边的石圈",b="Circle of Aquementas隐匿在塔纳利斯风沙弥漫的东海岸，位于落帆海湾海盗据点以南。这个非同寻常的地点由呈环形排列的、历经风雨的直立石块组成，在沙漠海岸边散发着阵阵元素能量。它是召唤Aquementas的焦点，这是一位与古代神器息息相关的元素实体。尽管周围的海滩上爬满了南海海盗和游荡的海洋生物，但石圈本身依然是沙丘中一处肃穆的仪式之地。"}},faq={{q="Circle of Aquementas是什么？",a="它是一座位于塔纳利斯东南海岸的直立石圈，用于召唤元素实体Aquementas。",al={"这个石环是什么","circle of aquementas的用途","塔纳利斯的直立石块"}},{q="石圈位于何处？",a="石圈位于塔纳利斯东岸，就在落帆海湾的悬崖和入口正南方。",al={"circle of aquementas在哪里","如何找到circle of aquementas","circle of aquementas位置"}},{q="Aquementas是谁？",a="Aquementas是一个与涉及奇怪神器的古代任务线相关的元素之灵，可以直接在石圈中被召唤出来。",al={"aquementas是谁","aquementas背景故事"}},{q="石圈有海盗守卫吗？",a="虽然南海海盗在落帆海湾及周边海岸线附近徘徊，但石圈本身主要是一个孤立的召唤点。",al={"这里有海盗吗","石圈附近的南海海盗"}}},fp="20,246,17.546.0,33.154.0,28.119.0,18.139.0,33.146.0"}
P.entries["subzone:circle-of-east-binding"] = {n="东部禁锢法阵",s="东部禁锢法阵是一处神秘的古代仪式地点，位于阿拉希高地的东部边缘，就在落锤镇的西南方。该地点由东部禁锢之石固定，这里一直处于激烈的争夺之中，并由被称为涌动流放者的漫游水元素所守卫。",h="东部禁锢法阵是一处神秘的古代仪式地点，位于阿拉希高地的东部边缘，就在落锤镇的西南方。该地点由东部禁锢之石固定，这里一直处于激烈的争夺之中，并由被称为涌动流放者的漫游水元素所守卫。",kw={"阿拉希高地","东部禁锢法阵","涌动流放者","元素生物","落锤镇","东部禁锢之石"},ang={["class:Shaman"]="阿拉希的禁锢石代表了粗糙或古老的元素压制方法，这与萨满追求的元素平衡与沟通形成了鲜明对比。",["faction:Horde"]="法阵周围不稳定的水之灵位于落锤镇附近的一条路上，对部落的巡逻队和补给线造成了持续的领土困扰。"},sec={{t="东部结界",b="东部禁锢法阵位于斯托姆加德以东崎岖的高地之中，是散布在阿拉希盆地各处的若干古代力量据点之一。其中心矗立着东部禁锢之石，这是一座散发着强大元素魔法的神秘纪念碑。被称为涌动流放者的旋涡水元素在周围的土地上徘徊，并凶猛地抵御着任何胆敢靠近的凡人。"},{t="元素禁锢",b="阿拉希各处的法阵石并非仅仅是自然异常现象；它们发挥着古代禁锢结界的作用，旨在压制和囚禁不稳定的元素力量。东部法阵周围焦躁不安的水之灵显露出了这些结界所承受的压力，因为被法阵之石的魔法所吸引或困住的实体，会攻击那些在前往落锤镇的道路上经过的旅行者和冒险者。"}},faq={{q="东部禁锢法阵位于哪里？",a="东部禁锢法阵位于阿拉希高地的东部地区，大路以南，落锤镇部落营地的西南方。",al={"东部禁锢法阵位置","东部禁锢法阵在哪里","东部禁锢法阵地图"}},{q="这里有哪些生物？",a="法阵中充斥着极具攻击性的水元素，即不断守卫着东部禁锢之石的涌动流放者。",al={"东部禁锢法阵怪物","东部禁锢法阵有哪些怪物","涌动流放者"}},{q="为什么高地里会有水元素？",a="散布在阿拉希各处的石头作为古代元素禁锢存在。这里出现水元素表明，通过东部结界石引导的水元素能量在此受到了抑制或吸引。",al={"阿拉希的水元素原因","东部禁锢法阵元素背景"}},{q="东部禁锢之石的用途是什么？",a="东部禁锢之石是阿拉希高地各处一系列协同禁锢石网络的一部分，旨在锚定、引导并锁住不稳定的元素实体。",al={"东部禁锢之石用途","东部禁锢之石的作用"}}},fp="22,286,16.417.0,22.389.0,44.169.0,30.124.0,48.219.0,49.180.0"}
P.entries["subzone:circle-of-inner-binding"] = {n="内禁锢法阵",s="内禁锢法阵是一圈古老的仪式石阵，位于阿拉希高地南部的丘陵地带，就在激流堡的东面。这里由充满敌意的土元素守卫，它是禁锢着深埋地底的元素公主Myzrael最强大的封印——内禁锢之石的所在地。",h="内禁锢法阵是一圈古老的仪式石阵，位于阿拉希高地南部的丘陵地带，就在激流堡的东面。这里由充满敌意的土元素守卫，它是禁锢着深埋地底的元素公主Myzrael最强大的封印——内禁锢之石的所在地。",kw={"阿拉希高地","内禁锢法阵","土元素","myzrael","轰鸣的流放者","内禁锢之石","激流堡"},ang={["class:Mage"]="石阵的几何排列构成了一个复杂且持久的收容场，能够引导并固定巨大的地下魔法压力。",["class:Shaman"]="涌动在内禁锢法阵中的原始土元素能量表明这里存在着古老而沉重的元素羁绊，然而当地土元素精神不自然的躁动也预示着地表之下存在着腐化。"},sec={{t="核心封印",b="内禁锢法阵坐落在大路南边的一处高原上，它是将Myzrael封印在阿拉希地下的最强古老结界的核心。高耸的石板环绕着中央的内禁锢之石，这块石头正散发着浓郁的地脉魔力。巨大的轰鸣土元素在此无休止地巡逻，或是受此地共鸣吸引，或是被束缚于此担任守卫。尽管有这些强大的结界，但这道内部封印上的裂痕还是让被困在高地之下的实体能够进行心灵感应，向那些接触过其石片碎块的无知漫游者低语求救。"}},faq={{q="内禁锢法阵的目的是什么？",a="该法阵内存放着内禁锢之石，它是锚定Myzrael地下监狱的主要且最强大的结界。它与散布在阿拉希高地各处的其他元素法阵协同作用，将该生物禁锢在地表之下。",al={"为什么这里有这个法阵","内禁锢法阵的作用是什么","内禁锢法阵背景故事"}},{q="什么生物守卫着这个法阵？",a="该法阵由强大的土元素严密守护，主要是轰鸣的流放者。这些岩石巨兽会猛烈攻击任何靠近仪式石阵的人。",al={"这里有什么敌人","内禁锢法阵怪物","轰鸣的流放者"}},{q="是谁在石头中低语？",a="通过禁锢碎片传出的声音属于Myzrael，这是一位被囚禁在地底深处的古老而强大的元素公主。她的心灵感应已经穿透了这道破碎的封印，试图与凡人的思想取得联系。",al={"是谁在这里和你说话","myzrael的声音","低语之石"}},{q="内禁锢法阵位于何处？",a="它位于阿拉希高地的南部，坐落在激流堡废墟以东的一处高耸山脊上。",al={"内禁锢法阵位置","内禁锢法阵在哪里","如何找到内禁锢法阵"}}},fp="23,327,13.590.0,51.274.0,33.169.0,36.239.0,45.152.0"}
P.entries["subzone:circle-of-west-binding"] = {n="西部禁锢法阵",s="西部禁锢法阵是散布在阿拉希高地的几处古老仪式地点之一，坐落于索拉丁之墙附近。这道奥术圆环围绕着西部禁锢之石，现在已经被束缚于此地的烈焰元素生物所占领。",h="西部禁锢法阵是散布在阿拉希高地的几处古老仪式地点之一，坐落于索拉丁之墙附近。这道奥术圆环围绕着西部禁锢之石，现在已经被束缚于此地的烈焰元素生物所占领。",kw={"阿拉希高地","燃烧的流放者","西部禁锢法阵","元素","ruul onestone","西部禁锢之石","索拉丁之墙"},ang={["class:Mage"]="阿拉希的禁锢之石为奥术修行者提供了关于古代法师和萨满如何锚定并制服位面元素生物的见解。",["class:Shaman"]="燃烧的流放者那动荡的存在揭示了与这些古老阿拉希基石相连的挥之不去的Elemental Unrest。"},sec={{t="西部基石",b="西部禁锢法阵依偎在索拉丁之墙附近崎岖的山坡上，是分散在整个阿拉希高地更广泛的仪式地点网络的一部分。它的中心坐落着西部禁锢之石，这是一件与元素禁锢相关的远古遗物。这片区域到处都是燃烧的流放者——那些不遗余力守卫着外围的暴躁火元素，这使得任何靠近这块石头的人对于穿越西部平原的旅行者来说都是一场危险的冒险。"}},faq={{q="什么是西部禁锢法阵？",a="它是一处位于阿拉希高地西部的古老仪式地点，坐落于索拉丁之墙附近。它存放着西部禁锢之石，并由敌对的火元素严密守卫。",al={"西部禁锢法阵","西部禁锢之石"}},{q="为什么这里会有火元素？",a="燃烧的流放者栖息并守卫着西部禁锢之石。它们是被吸引或被束缚在阿拉希高地各处所建造的远古魔法焦点上的元素力量。",al={"阿拉希燃烧的流放者","为什么西部禁锢法阵有火元素","西部禁锢法阵的元素"}},{q="Ruul Onestone是谁？",a="Ruul Onestone是一只徘徊在该地点的石拳食人魔，与其说他是禁锢之石的学者，不如说他是一个罕见而危险的蛮族。",al={"ruul onestone","ruul","西部禁锢法阵的矮人"}}},fp="22,253,20.472.0,35.174.0,35.173.0,21.132.0"}
P.entries["subzone:clean-zone"] = {n="Clean Zone",s="Clean Zone是一个防御森严的去污隔离区，坐落在诺莫瑞根废墟内，就在上层Hall of Gears的后面。它是这处受辐射设施中唯一的避风港，未受感染的侏儒部队在此坚守阵地，抵御周围的穴居人和麻风侏儒。在这里，战地医疗兵、技师和特制的Sparklematic机器在充满放射性的废墟中提供休整和打捞作业。",h="Clean Zone是一个防御森严的去污隔离区，坐落在诺莫瑞根废墟内，就在上层Hall of...",kw={"clean zone","dormitory","诺莫瑞根","hall of gears","辐射","sparklematic 5200","tink sprocketwhistle","穴居人"},ang={["profession:Engineering"]="可运作的Sparklematic 5200装置和商人Tink Sprocketwhistle的存在，使这个哨所成为了从受辐射的垃圾中搜寻稀有图纸和机械零件的关键地点。",["race:Gnome"]="对侏儒来说，站在Clean Zone既是对家园陷落的严酷提醒，也是一种坚定的希望之光，象征着诺莫瑞根的技术仍能从穴居人手中夺回。"},sec={{t="废料场中的堡垒",b="虽然诺莫瑞根的大部分地区因梅卡托克灾难性的放射性废料排放而沦陷，但Clean Zone却未受污染。它处于下方穴居人出没的Dormitory和上方争夺激烈的Hall of Gears走廊之间的战略要地，充当前线防御基地。坚定的侏儒守卫、技师和战地医疗兵日夜坚守着路障，确保联盟探险队有一个稳定的据点来重整旗鼓、包扎伤口和维护机械。"},{t="Sparklematic 5200型",b="除了作为军事据点外，Clean Zone还是打捞这座失落之城的中心。侏儒工程师安装了Sparklematic 5200装置，对从城市充满放射性的腹地中拖出的沾满污垢的遗物进行化学洗涤和清洁。技师和像Tink Sprocketwhistle这样的商人处理这些回收的齿轮和饰品，在为冒险者提供装备的同时，研究困扰着深层隧道的残留毒素。"}},faq={{q="为什么这个区域没有像诺莫瑞根的其他地方那样受到辐射？",a="Clean Zone收容了未受摧毁诺莫瑞根的辐射影响的侏儒。相关记录并没有解释为什么这个小区域能幸免于难。",al={"为什么clean zone没有受辐射","为什么这里安全","clean zone辐射"}},{q="Sparklematic 5200机器有什么作用？",a="Sparklematic 5200是特制的侏儒清洗和去污装置。冒险者可以将从穴居人和麻风侏儒身上获得的沾满污垢的物品投入其中，洗去放射性污垢，从而获得有用的矿石、宝石、硬币或工程学小玩意。",al={"sparklematic 5200","什么是sparklematic","清洗污垢"}},{q="谁在控制和保卫Clean Zone？",a="一支由未受感染的侏儒守卫、战地医疗兵和技师组成的精锐分队负责保卫外围。他们击退了从Dormitory入侵的穴居人以及从上层涌下的麻风侏儒，以确保这个补给站的安全。",al={"clean zone里有什么人","clean zone守卫","谁控制着clean zone"}},{q="玩家可以在这里安全地休息或修理装备吗？",a="是的。Clean Zone是诺莫瑞根深处的一个战地营地，为在前线后方活动的冒险者提供工程学补给、由商人Tink Sprocketwhistle提供的修理服务，甚至还有一个功能完好的邮箱。",al={"clean zone修理","能在clean zone休息吗","诺莫瑞根里的邮箱"}}},fp="10,243,21.370.0,21.371.0,59.158.0,42.269.0,40.220.0,39.178.0"}
P.entries["subzone:cleft"] = {n="大断崖",s="大断崖是位于泰达希尔，多兰纳尔西北方的一处阴暗洼地。这里曾经是枝叶间静谧的一角，如今却被堕落的棘鬃熊怪所占据。他们以此为据点，伏击沿主干道前往达纳苏斯的旅行者。",h="大断崖是位于泰达希尔，多兰纳尔西北方的一处阴暗洼地。这里曾经是枝叶间静谧的一角，如今却被堕落的棘鬃熊怪所占据。他们以此为据点，伏击沿主干道前往达纳苏斯的旅行者。",kw={"大断崖","达纳苏斯","多兰纳尔","熊怪","棘鬃","哨兵阿玛拉·夜行者"},ang={["class:Druid"]="堕落的棘鬃熊怪威胁着前往达纳苏斯路上的旅行者的安全。",["race:NightElf"]="大断崖代表了暗夜精灵的一场痛苦悲剧，他们眼看着长期的熊怪盟友陷入疯狂并攻击旅行者。"},sec={{t="堕落的巢穴",b="大断崖位于多兰纳尔和达纳苏斯之间的公路旁，现已成为世界之树上最危险的巢穴之一。受泰达希尔蔓延的邪恶腐蚀影响，居住于此的棘鬃熊怪已经陷入疯狂，并加固了这个洼地。这些疯狂的野兽以此为堡垒恐吓当地道路，威胁着要切断多兰纳尔与首都之间的联系。"},{t="路上的伏击者",b="大断崖带来的威胁已变得十分严峻，哨兵阿玛拉·夜行者和她的哨兵们被迫在入口外的道路沿线建立防御哨所。对于哨兵而言，肃清大断崖对于确保连接泰达希尔各村庄与达纳苏斯的主干道安全至关重要。"}},faq={{q="什么是大断崖？",a="大断崖是位于泰达希尔枝叶间的一处熊怪巢穴，坐落在多兰纳尔西北方，紧邻通往达纳苏斯的主干道。",al={"什么是大断崖","泰达希尔大断崖","大断崖位置"}},{q="谁控制着大断崖？",a="它被充满敌意的棘鬃熊怪占据，这些熊怪已成为泰达希尔逐渐蔓延的腐蚀的牺牲品。",al={"谁住在大断崖","大断崖敌人","谁统治大断崖"}},{q="暗夜精灵为什么要在这里战斗？",a="大断崖里的棘鬃熊怪一直在伏击前往达纳苏斯路上的旅行者。哨兵阿玛拉·夜行者和哨兵们致力于保障这条道路的安全。",al={"为什么要攻击大断崖","大断崖暗夜精灵任务","通往达纳苏斯的道路"}},{q="大断崖与暗影裂口有关吗？",a="没有。尽管名字相似，这个大断崖是泰达希尔的一处熊怪洞穴，而暗影裂口是位于部落主城奥格瑞玛内部的黑暗地下洞穴。",al={"与暗影裂口的联系","大断崖与暗影裂口"}}},fp="5,72,19.297.0,21.210.1,18.84.0,23.95.0,38.126.0,44.102.0"}
P.entries["subzone:cleft-of-shadow"] = {n="Cleft of Shadow",s="Cleft of Shadow隐藏在奥格瑞玛地下的洞穴深处，是城中潜行者、法师和术士的聚集地。这里远离萨尔所提倡的尚武精神，却成为了部落潜行者和术士在阴影中开展活动的必要避风港。",h="Cleft of Shadow隐藏在奥格瑞玛地下的洞穴深处，是城中潜行者、法师和术士的聚集地。这里远离萨尔所提倡的尚武精神，却成为了部落潜行者和术士在阴影中开展活动的必要避风港。",kw={"cleft of shadow","暗火议会","奥格瑞玛","怒焰裂谷","潜行者","暗影迅捷兄弟会","术士"},ang={["class:Rogue"]="暗影迅捷兄弟会与毒药商人和开锁专家在此聚集，使这处阴暗的凹地成为了部落潜行特工的主要巢穴。",["class:Warlock"]="暗火议会为部落术士提供了一个在奥格瑞玛下方召唤恶魔和束缚邪能的准许之地，而不会招致萨满和战士们的直接愤怒。"},sec={{t="地下庇护所",b="虽然萨尔领导的新部落推崇荣誉、萨满教义和武装力量，但务实的领导层仍需为更隐秘的技艺保留一席之地。Cleft of Shadow开凿在首都下方的潮湿石洞中，聚集了潜行者组织“暗影迅捷兄弟会”和术士组织“暗火议会”。远离山谷地区熙熙攘攘的日常活动，这个阴暗的角落让钻研毒药和邪能的修行者可以在避开公众视线的同时，依然处于奥格瑞玛领导层的监视之下。"},{t="危险的边缘",b="除了作为秘密教学和魔法试剂的中心之外，Cleft of Shadow还直通怒焰裂谷。这片火热的火山洞穴网络如同蜂巢般遍布在奥格瑞玛下方，构成了持续的安全威胁，将勇敢的保卫者和险恶的邪教徒一同引向洞穴边缘。"}},faq={{q="为什么术士和潜行者被安置在这里的地下？",a="萨尔努力在光荣的萨满教义和战士传统下团结部落。虽然术士和潜行者的效用得到了认可，但他们的做法受到许多兽人民众的怀疑。将他们限制在地下洞穴中，可以对危险的邪能和非法活动进行有效控制和监控。",al={"为什么会有cleft of shadow","为什么术士在奥格瑞玛地下","cleft of shadow背景"}},{q="在Cleft of Shadow可以找到哪些主要的训练师和服务？",a="该洞穴是奥格瑞玛主要的潜行者和术士训练师中心。此外，这里还有毒药供应商、试剂商以及魔杖和法杖商人。",al={"cleft of shadow里的训练师","谁在cleft of shadow"}},{q="洞穴底部是什么入口？",a="通往洞穴底部的深渊连接着怒焰裂谷，这是一个位于奥格瑞玛下方、充满岩浆管道的危险地下网络，里面充斥着穴居人、炽热元素生物和邪恶的邪教徒。",al={"cleft of shadow里的地下城","cleft的洞穴入口","这里有什么副本"}}},fp="15,160,24.338.0,21.197.0,50.231.0,69.131.0,49.155.0"}
P.entries["subzone:cliffspring-falls"] = {n="峭壁之泉",s="峭壁之泉是黑海岸壁泉河那壮观的源头，河水从东部的悬崖倾泻而下，奔涌进沿海的森林中。这里长期以来都被视为该地区洁净饮用水的主要来源，但其水质最近却遭受了邪恶且不断扩散的污染。为瀑布供水的地下洞穴已经被充满敌意的纳迦和阴暗的暮光之锤教徒所占据。",h="峭壁之泉是黑海岸壁泉河那壮观的源头，河水从东部的悬崖倾泻而下，奔涌进沿海的森林中。这里长期以来都被视为该地区洁净饮用水的主要来源，但其水质最近却遭受了邪恶且不断扩散的污染。为瀑布供水的地下洞穴已经被充满敌意的纳迦和阴暗的...",kw={"奥伯丁","峭壁之泉","壁泉河","黑海岸","费伍德森林","纳迦","暮光之锤","水污染"},ang={["class:Druid"]="塞纳里奥议会的德鲁伊们密切监测着这条河流，努力查明并净化那威胁要扼杀这片荒野的非自然腐烂。",["race:NightElf"]="对于奥伯丁的卡多雷来说，峭壁之泉的腐化是一场环境和精神上的危机，污染了滋养黑海岸古老森林的生命之水。"},sec={{t="被污染的源头",b="峭壁之泉从黑海岸东部边缘高耸岩壁上的洞穴中倾泻而出，汇入壁泉河，随后向西蜿蜒穿过树林注入大海。传统上，这条瀑布为当地的暗夜精灵定居点提供了最纯净的饮用水。然而近来，河水变得污浊不堪，导致疾病和生态衰退在整个流域蔓延。调查此事的博物学者们发现，瀑布源头的洞穴网络被邪恶的纳迦和黑暗教徒所占据，他们潜伏在阴影中密谋作恶，而来自邻近费伍德森林的恶魔腐蚀正威胁着要穿过高地的基岩渗入此地。"}},faq={{q="峭壁之泉是什么？",a="峭壁之泉是黑海岸东部的一处主要瀑布，它构成了壁泉河的源头。在历史上，它为周围的森林提供了主要的淡水饮用水源。",al={"峭壁之泉","峭壁之泉是什么"}},{q="为什么从瀑布流出的水会被污染？",a="据怀疑，原因来自两股邪恶势力：从腐化的费伍德森林穿过山脉渗出的恶魔污染，以及潜伏在为瀑布供水的洞穴内、极其活跃的暮光之锤教徒与敌对的纳迦。",al={"水为什么会被污染","壁泉河腐化","污染水源"}},{q="是谁占据了瀑布后的洞穴？",a="瀑布上方及后方的洞穴中布满了在淹没的密室中蜿蜒穿行的敌对纳迦，以及隶属于末日教派暮光之锤的教徒。",al={"洞穴里是谁","峭壁之泉洞穴怪物","谁住在峭壁之泉"}},{q="为什么峭壁之泉对黑海岸如此重要？",a="壁泉河贯穿了黑海岸北部的中心地带。由于它是该地区主要的淡水来源，其遭受的污染直接危及了野生动物、古老的树林以及当地暗夜精灵的栖息地。",al={"黑海岸为何在意","峭壁之泉的重要性"}}},fp="17,220,16.552.0,26.180.0,49.144.0,42.94.0,51.176.0"}
P.entries["subzone:clockwerk-run"] = {n="Clockwerk Run",s="Clockwerk Run是通往堕落的诺莫瑞根核心地带的主要入口走廊。这条受损的走廊位于Train Depot和Hall of Gears之间，充斥着有毒的辐射尘埃，并被受辐射的穴居人所占领。",h="Clockwerk Run是通往堕落的诺莫瑞根核心地带的主要入口走廊。这条受损的走廊位于Train Depot和Hall of Gears之间，充斥着有毒的辐射尘埃，并被受辐射的穴居人所占领。",kw={"clockwerk run","诺莫瑞根","hall of gears","受辐射的穴居人","train depot","穴居人"},ang={["profession:Engineering"]="沿途废弃的机械和坍塌的基础设施让人清楚地看到，当工业规模的侏儒机械遭受灾难性的爆炸和辐射破坏时会发生什么。",["race:Gnome"]="穿过Clockwerk Run是一个关于首都沦陷的苦涩提醒，它直接展示了那个试图净化城市的孤注一掷的计策是如何让入侵者发生变异，而不是将其消灭的。"},sec={{t="一处废墟之门",b="Clockwerk Run曾是Gnomeregan从外部Train Depot进入的主要门户，也是侏儒物流和交通繁忙的枢纽。当大工匠梅卡托克下令排放放射性废料以遏制穴居人入侵时，这条走廊变成了一个致命的陷阱。爆炸和随后的战斗导致走廊部分坍塌。如今，这条通道充斥着有毒气体和游荡的受辐射穴居人，使它成为任何探险队要到达上层Hall of Gears都必须杀出一条血路的危险前线。"}},faq={{q="Clockwerk Run通向哪里？",a="Clockwerk Run将深层拱顶外的Train Depot与Gnomeregan内部上层的Hall of Gears直接连接起来。",al={"clockwerk run位置","这条走廊通往哪里","clockwerk run入口"}},{q="为什么这里有这么多穴居人？",a="地下的穴居人在最初入侵期间涌入了Gnomeregan的下层通道。那些在Clockwerk Run游荡的穴居人吸收了大量排放出的放射性废料，变异成了凶猛的受辐射穴居人，攻击任何试图进入这座城市的人。",al={"为什么有穴居人","clockwerk run敌人"}},{q="为什么走廊部分坍塌了？",a="Gnomeregan沦陷期间的激烈战斗以及灾难性的有毒反制措施的释放，导致整个周边区域结构严重受损，使走廊部分坍塌。",al={"clockwerk run坍塌","为什么它破损了"}}},fp="13,115,18.430.0,34.108.0,34.189.0,39.137.0"}
P.entries["subzone:cold-hearth-manor"] = {n="炉灰庄园",s="炉灰庄园是一处荒废的农庄，位于布瑞尔以西，紧邻提瑞斯法林地的主要道路。这里曾是一处繁华好客的庄园，以丰收的农作物而闻名，但亡灵天灾的爆发夺走了所有居民的生命，使周边的田野里充斥着毫无理智的亡灵生物。如今，被遗忘者已经占领了主屋，将其作为旅行者的前哨站和中转站。",h="炉灰庄园是一处荒废的农庄，位于布瑞尔以西，紧邻提瑞斯法林地的主要道路。这里曾是一处繁华好客的庄园，以丰收的农作物而闻名，但亡灵天灾的爆发夺走了所有居民的生命，使周边的田野里充斥着毫无理智的亡灵生物。如今，被遗忘者已经占领...",kw={"布瑞尔","炉灰庄园","农庄","被遗忘者","天灾军团","提瑞斯法林地","僵尸"},ang={["faction:Horde"]="这座庄园在布瑞尔与提瑞斯法东部区域之间的道路上提供了一个安全的制高点，为穿行于这片被瘟疫侵袭的乡村的旅行者提供了一个安全的补给站。",["race:Undead"]="对于被遗忘者而言，收复炉灰庄园这样的地方是苦涩的提醒，让他们想起自己失去的凡人生活，将昔日人类的避风港改造成对抗天灾军团和血色十字军的阴森防御前哨。"},sec={{t="冰冷的炉火",b="在第三次战争之前，这座庄园以温馨好客而闻名，是洛丹伦腹地的丰饶粮仓。当瘟疫席卷王国时，整户人家和他们的劳工都未能幸免，死后又作为天灾军团的行尸走肉复活。虽然野性的亡灵仍在荒废的田野间徘徊，但被遗忘者的部队成功将那些毫无理智的死尸赶出了主屋，收复了这座建筑，使之成为通往东部林地道路上的贸易点和立足点。"}},faq={{q="住在这里的人们发生了什么事？",a="当亡灵瘟疫席卷洛丹伦时，照料庄园的农夫和工人们全都被杀害了。他们死后并未获得安息，而是被复活成了毫无理智的僵尸，至今仍在周边的田野中徘徊。",al={"谁住在炉灰庄园","庄园背景故事","这家人发生了什么"}},{q="为什么叫它炉灰庄园？",a="这座庄园最初以其温馨的氛围和迎接客人的炉火而闻名。这个阴森的名字很可能是被遗忘者所取的，是对其往日时光的一种讽刺，意在彰显这座农场如今是多么寒冷、死寂和荒芜。",al={"炉灰庄园名字含义","为什么叫炉灰"}},{q="现在谁控制着这座庄园？",a="被遗忘者已经控制了主屋，将其作为往返布瑞尔的旅行者和商人的安全驻点。然而，庄园周边的开阔田野和谷仓依然被敌对的天灾军团所盘踞。",al={"谁拥有炉灰庄园","炉灰庄园友好吗"}},{q="为什么被遗忘者不清理那些田野？",a="在提瑞斯法林地的被遗忘者兵力不足，他们既要对抗毫无理智的天灾残党，又要抵御血色十字军的圣战者。确保主屋和主路的安全能提供直接的效用，而田野里散落的死尸只是碍事，而非对布瑞尔构成的直接威胁。",al={"为什么田野里有僵尸","为什么天灾军团在这里"}}},fp="17,214,16.537.0,43.178.0,35.178.0,33.164.0,44.274.0"}
P.entries["subzone:coldridge-pass"] = {n="寒脊山小径",s="寒脊山小径是一条崎岖且被积雪覆盖的隧道，横穿丹莫罗南部的山脊。它是连接与世隔绝的寒脊山谷训练场和王国其他地区的唯一陆路通道，出口靠近繁华的卡拉诺斯小镇。由于敌对的穴居人已经占领了这条通道，任何试图穿越的旅行者都必须杀出一条血路，或者孤注一掷冲向另一端。",h="寒脊山小径是一条崎岖且被积雪覆盖的隧道，横穿丹莫罗南部的山脊。它是连接与世隔绝的寒脊山谷训练场和王国其他地区的唯一陆路通道，出口靠近繁华的卡拉诺斯小镇。由于敌对的穴居人已经占领了这条通道，任何试图穿越的旅行者都必须杀出一...",kw={"安威玛尔","寒脊山小径","寒脊山谷","丹莫罗","卡拉诺斯","山路","穴居人","隧道"},ang={["race:Dwarf"]="对于矮人山地猎人和新兵来说，穿越寒脊山小径意味着你将从安威玛尔的新手训练毕业，开始在铁炉堡的领地内服役。",["race:Gnome"]="寻求援助联盟的流亡侏儒必须穿过这个被穴居人盘踞的咽喉要道，才能到达卡拉诺斯，进而走上通往铁炉堡的高地之路。"},sec={{t="离开山谷的门户",b="对于刚踏出寒脊山谷的年轻矮人新兵和侏儒新手来说，寒脊山小径是一场严酷的成人礼。这条直接凿穿岩石的隧道是连接刚完成训练的冒险者通往东部卡拉诺斯前哨枢纽的主要通道。这里曾经是一条安全的山中走廊，如今却变成了一个危险的咽喉要道，里面充斥着从地下深处涌出的凶猛穴居人，威胁着每一个试图往返于避风山谷和广阔丹莫罗地区的人。"}},faq={{q="寒脊山小径通向哪里？",a="这条小径连接了西南部的寒脊山谷和广大的丹莫罗地区，出口位于卡拉诺斯小镇西侧的雪山丘陵中。",al={"寒脊山小径通往哪里","寒脊山小径目的地","如何离开寒脊山谷"}},{q="为什么寒脊山小径里会有穴居人？",a="穴居人最近从丹莫罗地下的深层裂隙中涌出，占领了该地区的黑暗洞穴和隧道。寒脊山小径为它们提供了庇护所，也成为了伏击山地旅行者的便利地点。",al={"为什么这里有穴居人","寒脊山小径怪物","穴居人入侵"}},{q="穿过寒脊山小径安全吗？",a="不，不安全。隧道里到处都是敌对的穴居人，这意味着新兵和旅行者必须砍杀这些野兽，或者在黑暗中奔跑，才能到达另一端。",al={"寒脊山小径危险吗","我可以穿过寒脊山小径吗"}},{q="谁在守卫或维护这条小径？",a="山地猎人会监视山谷和道路出口，但隧道内部仍然处于争夺状态且未被清理，旅行者在穿越时只能自求多福。",al={"寒脊山小径的矮人守卫","谁控制了这条小径"}}},fp="14,80,29.327.0,31.136.0,39.175.0,41.125.0,33.141.0"}
P.entries["subzone:coldridge-valley"] = {n="寒脊山谷",s="寒脊山谷是一个隐蔽的、覆盖着白雪的山谷，位于丹莫罗的西南部高地。它以安威玛尔村落为中心，是年轻的矮人和诺莫瑞根流亡者初次拿起武器为铁炉堡效力时的训练场。一条名为寒脊山小径的隧道连接着这片与世隔绝的山谷和广阔的山区。",h="寒脊山谷是一个隐蔽的、覆盖着白雪的山谷，位于丹莫罗的西南部高地。它以安威玛尔村落为中心，是年轻的矮人和诺莫瑞根流亡者初次拿起武器为铁炉堡效力时的训练场。一条名为寒脊山小径的隧道连接着这片与世隔绝的山谷和广阔的山区。",kw={"安威玛尔","寒脊山小径","寒脊山谷","丹莫罗","霜鬃巨魔","铁炉堡","新手区","石腭怪"},ang={["race:Dwarf"]="作为铜须登山者和牧师的传统训练地，山谷代表了一个矮人离开炉火，投身服务于铁炉堡的第一步。",["race:Gnome"]="对于被迫离开诺莫瑞根的侏儒流亡者来说，寒脊山谷的雪地为他们提供了一个安全的避难所，让他们能够与矮人东道主一起掌握法术和机械技术。"},sec={{t="一处与世隔绝的试炼场",b="寒脊山谷被陡峭的山崖环绕，与丹莫罗繁忙的贸易路线基本隔绝。在它的中心坐落着安威玛尔，那是一座坚固的石制大厅和村落，经验丰富的矮人教官和流离失所的侏儒学者们在那里训练新兵，教导他们战斗、潜行和魔法的艺术。在安威玛尔的炉火温暖之外，谷底覆盖着厚厚的积雪，野猪和饥饿的冬狼在此徘徊，为新手们提供了他们初次体验边境生存的机会。"},{t="逼近的敌人",b="尽管寒脊山谷相对孤立，但它正面临来自两个冷酷敌人的直接威胁。当地的霜鬃巨魔已经建立了诸如Frostmane Hovel之类的营地，他们与登山者发生冲突，并为了保卫祖先的领地而抵御矮人的入侵。更糟糕的是，野蛮的石腭怪已经占领了寒脊山谷通往卡拉诺斯的唯一自然通道——寒脊山小径。如果不击退这些来自地下的野蛮生物，旅行者和补给就无法在山谷和铁炉堡高地之间自由通行。"}},faq={{q="如何离开寒脊山谷？",a="离开山谷的唯一陆路是穿过寒脊山小径，这是一条向东北方向穿过山脊的雪地隧道。穿过小径后，道路直接向东通往卡拉诺斯镇，并继续前往铁炉堡的宏伟大门。",al={"离开寒脊山谷","如何出去","通往卡拉诺斯的路径"}},{q="为什么侏儒会和矮人一起在这里开始冒险？",a="在诺莫瑞根悲剧性地落入石腭怪手中并遭受辐射污染后，幸存的侏儒作为难民逃往了丹莫罗。大工匠梅卡托克的子民受到了国王麦格尼·铜须的欢迎，这使得许多流亡的侏儒学徒能够在安威玛尔与年轻的矮人并肩受训。",al={"寒脊山谷的侏儒","为什么侏儒在这里","侏儒新手区"}},{q="有哪些威胁在困扰着山谷？",a="山谷面临两大主要威胁：敌对的霜鬃巨魔，他们反感矮人在其山地领土上的定居；以及粗野的石腭怪，它们从地底深处爬上来，封锁了寒脊山小径。此外，狼和野猪等当地掠食者也会袭击不谨慎的旅行者。",al={"寒脊山谷的敌人","山谷的威胁","谁在攻击"}},{q="什么是安威玛尔？",a="安威玛尔是寒脊山谷的核心堡垒和定居点。它容纳了职业训练师、锻造大师以及协调山谷防御并为新晋冒险者踏入广阔世界做准备的当地登山者军官。",al={"安威玛尔镇","这里的城镇是什么"}}},fp="16,264,25.331.0,16.327.0,34.199.0,47.257.0,38.286.0,17.241.0"}
P.entries["subzone:command-center"] = {n="Command Center",s="Command Center，通常被称为Stormwind Barracks，坐落在Old Town的中心地带，是该市军事官员的作战总部。在和平时期，这里驻扎着常备军，但由于Stormwind的军队被派往遥远的边境，它目前仅由一小队经验丰富的骨干人员负责训练新兵和当地民兵。",h="Command Center，通常被称为Stormwind Barracks，坐落在Old...",kw={"ander germaine","兵营","command center","old town","暴风城兵营","战士训练师","wu shen"},ang={["class:Warrior"]="Command Center是暴风城战士训练的主要枢纽，像Ander Germaine和Wu Shen这样的老兵在这里将新兵磨练成纪律严明的火线士兵。"},sec={{t="脆弱的防线",b="Command Center位于Old Town那饱经风霜的街道内，是暴风城王国主要的驻军和军事训练场。该设施通常挤满了正规步兵和高级军官，但现在却异常空旷。由于大部分皇家军队都投入了海外战役，兵营现在依靠一批经验丰富的教官——包括Ander Germaine和武术家Wu Shen——来训练新战士，以加强城市的防御。"},{t="Old Town的武术中心",b="整个暴风城的卫兵在人们寻求重型武器和战术格斗指导时，通常会将他们指引向“兵营”。这座建筑靠近Pig and Whistle Tavern，同时也靠近Old Town其他区域那些阴暗的行动，这使它成为了这个以酒馆斗殴和流氓活动著称的区域中，维持秩序的关键支柱。"}},faq={{q="为什么Command Center这么空？",a="大部分暴风城的常备军已被部署到世界各地遥远的前哨站和外国战场。Command Center目前只保留了一小队经验丰富的退伍军人来指导新兵和组织当地防御。",al={"为什么这里卫兵很少","暴风城军队在哪里","兵营空了"}},{q="Command Center和Stormwind Barracks是同一个地方吗？",a="是的。虽然官方名称是Command Center，但城市卫兵和当地居民在指路时习惯称该建筑为Stormwind Barracks。",al={"暴风城兵营","指挥中心和兵营是同一个吗","兵营位置"}},{q="谁负责这里的训练？",a="Ander Germaine与Wu Shen和Ilsa Corbin等教官一起协调并训练该市的战士。",al={"谁在这里训练战士","指挥中心战士训练师","谁管理兵营"}},{q="Command Center位于哪里？",a="Command Center位于Old Town，靠近Pig and Whistle Tavern，处于该区训练设施的中心位置。",al={"指挥中心在哪里","指挥中心位置","如何找到指挥中心"}}},fp="14,224,22.264.0,22.284.0,35.179.0,57.145.0,28.114.0,36.112.0"}
P.entries["subzone:commons"] = {n="Commons",s="平民区是铁炉堡充满活力的商业中心，它直接连接着城市入口与广阔的洞穴。这里挤满了商人、旅客和银行家，是矮人首都最繁忙的通道，也是整个联盟的核心市场。",h="平民区是铁炉堡充满活力的商业中心，它直接连接着城市入口与广阔的洞穴。这里挤满了商人、旅客和银行家，是矮人首都最繁忙的通道，也是整个联盟的核心市场。",kw={"拍卖行","银行","平民区","铁炉堡","市场","stonefire tavern","vault of ironforge"},ang={["faction:Alliance"]="平民区实际上充当了联盟交易大厅的角色，吸引着来自泰达希尔、暴风城和诺莫瑞根的英雄们前来拍卖珍贵的战利品并储备补给。",["race:Dwarf"]="对于铜须矮人来说，平民区是他们的骄傲，证明了矮人的好客、勤劳和商业繁荣可以在冰封的山脉深处蓬勃发展。"},sec={{t="山脉的商业枢纽",b="平民区位于铁炉堡大门东北方，是进入这座山中王国的旅客所见到的第一个城区。这条繁华的商业街直接在岩石中开凿而成，这里不仅有主要的联盟拍卖行、Stonefire Tavern，还有位于Vault of Ironforge内的城市中心银行。宽阔的大道将其与Great Forge、Mystic Ward和Military Ward顺畅地连接起来，确保了山城内几乎所有的行人流量都会经过其繁忙的店面。"},{t="联盟的十字路口",b="得益于铁炉堡在东部王国大陆的中心位置，以及连接暴风城的矿道地铁，平民区成为了联盟主要的贸易枢纽。冒险者们聚集于此，交易从艾泽拉斯各个角落带来的货物，从Steelfury's Weapon Emporium购买武器，从Barim处购买施法材料，或者在踏入卡兹莫丹的漫天风雪之前，于当地旅店温暖的灯光下会面。"}},faq={{q="是什么让平民区相比其他城区如此拥挤？",a="平民区拥有联盟主要的拍卖行、位于Vault of Ironforge的城市主银行，以及繁华的Stonefire Tavern。它位于主大门内的优越地理位置，使其成为了整个王国最便利的聚集和交易场所。",al={"为什么平民区很忙","为什么这里玩家很多","铁炉堡贸易枢纽"}},{q="平民区通向哪里？",a="平民区连接着铁炉堡几乎所有主要的城区。向西南方走会回到城市大门，向东北方连接Great Forge，向东方延伸至Military Ward，向北方则通往Mystic Ward。",al={"平民区出口","如何离开平民区","平民区方向"}},{q="这里有哪些关键的商店和服务？",a="除了拍卖行和银行，平民区还设有铁炉堡游客中心、Steelfury's Weapon Emporium、铁炉堡军械库、Barim的施法材料店以及Fizzlespinner杂货店。",al={"平民区商人","平民区服务","铁炉堡平民区便利设施"}},{q="银行位于这里吗？",a="是的。Vault of Ironforge位于平民区拍卖行的对面，是该市的主要银行。",al={"铁炉堡银行在哪里","铁炉堡金库","银行位置"}}},fp="7,203,34.338.0,29.400.0,62.180.0,28.171.0,43.190.0,25.103.0"}
P.entries["subzone:corin-s-crossing"] = {n="考林路口",s="考林路口是一座位于东瘟疫之地中南部主要十字路口的被毁人类定居点。这里曾经是斯坦索姆、提尔之手、达隆郡和Andorhal之间一个繁荣的中转站，如今这座满目疮痍的城镇已被天灾军团完全占领。其破败的市政厅和铁匠铺中潜伏着挥之不去的恐怖，包括隐形的幽灵看守者。",h="考林路口是一座位于东瘟疫之地中南部主要十字路口的被毁人类定居点。这里曾经是斯坦索姆、提尔之手、达隆郡和Andorhal之间一个繁荣的中转站，如今这座满目疮痍的城镇已被天灾军团完全占领。其破败的市政厅和铁匠铺中潜伏着挥之不...",kw={"考林路口","东瘟疫之地","魔刃之痕","米雷达尔湖","看不见的仆从"},ang={["class:Paladin"]="考林路口的废墟代表了洛丹伦中心地带的彻底亵渎，这里作为一个邪恶的天灾据点，嘲弄着沿路更前方的圣地堡垒斯坦索姆。",["class:Rogue"]="在这里不要相信你的影子。看不见的仆从在巷子里游荡，凡人肉眼无法看见它们，而且它们能直接看穿你的潜行，这使得在城镇广场随意行走等同于自寻死路。"},sec={{t="破碎的十字路口",b="Before the Third War, Corin's Crossing served as a central junction for travel across eastern Lordaeron. Positioned between the shimmering waters of Lake Mereldar and what has now become the blighted chasm of the Infectis Scar, its thoroughfares once bore merchants, couriers, and pilgrims traveling between the great bastion of Stratholme and the southern strongholds. When the plague swept through the province, the settlement stood directly in the path of destruction, collapsing swiftly beneath the sheer weight of the undead vanguard."},{t="被诅咒者的避难所",b="如今，考林路口已完全沦陷于天灾军团之手。漫无目的的亡灵充斥着泥泞的街道，腐烂的尸骸和食尸鬼则徘徊在空荡荡的铁匠铺和市政厅内。对于侦察兵来说，这座城镇尤其危险：隐形的“看不见的仆从”在废墟中游荡，凡人的肉眼根本无法察觉。它们能洞穿普通的潜行，伏击任何试图绕过主力部队而不被发现的旅行者。"}},faq={{q="瘟疫发生前考林路口是什么样的地方？",a="它曾是洛丹伦东部一个繁荣的枢纽城镇。以市政厅和铁匠铺为中心，在天灾军团屠杀其居民之前，它曾为往来于斯坦索姆、提尔之手、达隆郡和Andorhal之间的旅客提供服务。",al={"考林路口历史","考林路口背景故事","考林路口曾经是什么"}},{q="为什么考林路口对潜行者来说如此危险？",a="这座城镇被“看不见的仆从”——一群效忠于天灾军团的隐形幽灵所困扰。这些幽灵可以毫不费力地识破魔法和普通的潜行，让粗心大意的潜行者或侦察兵猝不及防，并引来附近的亡灵。",al={"考林路口潜行","看不见的仆从","潜行者考林路口"}},{q="城镇周围有哪些主要地标？",a="考林路口位于东瘟疫之地的中南部。被荒废的魔刃之痕深沟就在附近，米雷达尔湖则沿其边界延伸。",al={"考林路口位置","考林路口在哪里"}},{q="谁现在控制着考林路口？",a="天灾军团完全统治着这些废墟。镇上没有任何活着的守军，整个定居点到处都是游荡的亡灵士兵和幽灵。",al={"谁拥有考林路口","考林路口阵营"}}},fp="16,358,22.539.0,21.419.0,44.228.0,60.222.0,39.180.0,36.169.0"}
P.entries["subzone:corrahn-s-dagger"] = {n="考兰之匕",s="考兰之匕是耸立在希尔斯布莱德丘陵北部，四座山脊状山脉中的第二座。这片高地是辛迪加盗贼的藏身处。",h="考兰之匕是耸立在希尔斯布莱德丘陵北部，四座山脊状山脉中的第二座。这片高地是辛迪加盗贼的藏身处。",kw={"考兰","考兰之匕","匕首","四指","希尔斯布莱德","辛迪加"},ang={["race:Dwarf"]="这座山脊是辛迪加的藏身处，因此穿越北部丘陵的矮人旅行者应该做好遇到强盗而非盟友的心理准备。",["race:Undead"]="占据山脊的辛迪加匪徒对在希尔斯布莱德活动的被遗忘者抱有敌意。"},sec={{t="北部据点",b="考兰之匕陡峭地耸立在希尔斯布莱德丘陵北部，是当地被称为“希尔斯布莱德之指”的四座岩石突起中的第二座。这座山脊被辛迪加的匪徒占据，他们利用这一高处俯瞰下方的山谷。"}},faq={{q="谁控制着考兰之匕？",a="这座山脊由辛迪加的人类叛徒占据，他们将这里作为藏身处。",al={"考兰之匕有什么人","考兰之匕所属阵营","谁住在这里"}},{q="什么是希尔斯布莱德之指？",a="希尔斯布莱德之指是从北部山脉向南延伸至希尔斯布莱德山谷的四座突出的手指状山脊。考兰之匕是这些地貌中的第二座。",al={"希尔斯布莱德四指","希尔斯布莱德四山脊","希尔斯布莱德之指"}}},fp="16,146,22.207.0,30.85.0,34.163.0"}
P.entries["subzone:craftsmen-s-terrace"] = {n="工匠区",s="工匠区是达纳苏斯北部一处熙熙攘攘的工匠区域。它是这座暗夜精灵首都的主要贸易和制造中心，坐落着各种工作室、专业训练师和一家热闹的旅店。该区域还接待外部代表，其中包括一个为中立组织银色黎明设立的使馆。",h="工匠区是达纳苏斯北部一处熙熙攘攘的工匠区域。它是这座暗夜精灵首都的主要贸易和制造中心，坐落着各种工作室、专业训练师和一家热闹的旅店。该区域还接待外部代表，其中包括一个为中立组织银色黎明设立的使馆。",kw={"银色黎明","工匠","工匠区","达纳苏斯","泰达希尔","训练师"},ang={["faction:Alliance"]="联盟的游客会发现这里是达纳苏斯最受欢迎的区域之一，它在提供熟悉的商业物资、公会管理和住宿的同时，还有外来代表驻扎。",["race:NightElf"]="对于卡多雷而言，这里证明了他们的社会在泰达希尔上自给自足，将古老的工艺与新首都日常生活的需求融合在了一起。"},sec={{t="达纳苏斯的工匠之心",b="工匠区横跨这座树冠之城的北缘，聚集了维持达纳苏斯运转的各种贸易。木工、制皮师、炼金师和其他工匠在这里经营着他们的店铺，将古典的暗夜精灵工艺与实用技艺相结合。该区域还提供必要的社区设施，包括一家旅店、一位公会会长和公会注册商。桥梁将该平台与西侧的塞纳里奥区和南侧的战士区直接相连。"},{t="外部联系与被遗忘的知识",b="尽管卡多雷在历史上一直处于孤立状态，但工匠区却容纳了对外联系，最引人注目的是银色黎明建立的一座使馆，旨在与北方盟友协调对抗天灾军团。游览该区域各个工作室的游客偶尔也能发现散落的学术书籍，内容从上古之战的历史记载，到第二次战争的编年史，再到关于上古之神的深奥论述，应有尽有。"}},faq={{q="在工匠区可以找到哪些服务？",a="该区域容纳了城里大部分的商业专业训练师、商业物资商人、一家旅店以及公会注册服务。对于想要在达纳苏斯学习或练习实用技能的旅行者来说，这里是商业中心。",al={"工匠区服务","工匠区里有什么","达纳苏斯训练师"}},{q="为什么银色黎明会出现在工匠区？",a="银色黎明在该区域设有一座使馆，以便与暗夜精灵联络并招募援助以对抗天灾军团。他们的存在为西部的联盟军队与饱受战争蹂躏的洛丹伦土地之间架起了一座外交桥梁。",al={"达纳苏斯的银色黎明","银色黎明使馆","为什么银色黎明在这里"}},{q="如何到达工匠区？",a="该平台占据了达纳苏斯的北部。你可以通过从战士区向北或从塞纳里奥区向东的桥梁到达这里。",al={"如何前往工匠区","工匠区位置","寻找工匠区"}},{q="在工作室周围可以找到哪些值得注意的书籍？",a="学术书籍散落在各个工作室中，其中包括上古之战的历史、第二次战争后的局势，以及存放在银色黎明驻地内的一份关于上古之神的研究资料。",al={"工匠区书籍","达纳苏斯背景书籍","工匠区的书籍"}}},fp="19,166,30.378.0,31.293.0,51.187.0,58.209.0,41.144.0,53.184.0"}
P.entries["subzone:crag-of-the-everliving"] = {n="Crag of the Everliving",s="Crag of the Everliving 是位于哀嚎洞穴深处的一处葱郁的洞穴室。这里被茂密且受到腐蚀的植物群和捕食性植物生物所占据，是尖牙领主皮萨斯领主的领地。其高耸的上层区域庇护着这座岩穴以其命名的那尊古老存在。",h="Crag of the Everliving 是位于哀嚎洞穴深处的一处葱郁的洞穴室。这里被茂密且受到腐蚀的植物群和捕食性植物生物所占据，是尖牙领主皮萨斯领主的领地。其高耸的上层区域庇护着这座岩穴以其命名的那尊古老存在。",kw={"贫瘠之地","crag of the everliving","变异蹒跚者","尖牙德鲁伊","皮萨斯","瑟芬迪斯","永生者沃尔丹","哀嚎洞穴"},ang={["class:Druid"]="对塞纳里奥德鲁伊来说，目睹 Crag of the Everliving 的景象是一次悲剧性的教训，因为纯粹的自然生命力和元素守护力量已经被扭曲成了梦魇的致命工具。",["profession:Herbalism"]="岩穴内不自然且葱郁的地下环境滋养了稀有的地下根茎和蘑菇，它们在潮湿、充满梦境气息的土壤中繁茂生长。"},sec={{t="腐蚀的林冠",b="虽然哀嚎洞穴的大部分区域都是由潮湿的地下岩石开凿而成，但 Crag of the Everliving 却因受到腐蚀纳拉雷克斯睡梦的梦魇影响，而爆发出了肆意生长的扭曲植被。高耸的苔藓平台和蜿蜒的小径上挤满了变异蹒跚者——潜伏在灌木丛中的活体植物巨怪。纳拉雷克斯堕落的弟子之一，皮萨斯领主，正看守着这处岩穴的中心区域，他已经抛弃了自己高贵的德鲁伊誓言，转而信奉尖牙德鲁伊的毒性仪式。"},{t="远古守护者",b="这处洞穴室的名字来源于永生者沃尔丹，这是一位居住在岩穴高处的巨大原始植物元素。受到笼罩着洞穴的翡翠梦魇腐蚀，永生者沃尔丹现在已不再是和平的自然守护者，而是成为了一道可怕的防线。在他高耸的身躯之后，潜伏着瑟芬迪斯领主，他是自封的尖牙领袖，负责监督该教派堕入蛇蝎般的疯狂。"}},faq={{q="这个区域的名字是从何而来？",a="这处洞穴室是以永生者沃尔丹的名字命名的，他是一位居住在岩穴最高台地上的古老而巨大的植物野兽。虽然他曾经是自然永恒活力的化身，但现在已经屈服于折磨着洞穴的梦魇。",al={"为什么叫 crag of the everliving","永生者名字由来","岩穴名称"}},{q="谁控制着洞穴的这一部分？",a="皮萨斯领主，主要的尖牙领袖之一，直接管辖着这处岩穴。在他上方的更高岩架上，潜伏着永生者沃尔丹和尖牙德鲁伊的首领瑟芬迪斯领主。",al={"谁在管理这里","岩穴首领","此处的尖牙领袖"}},{q="在 Crag of the Everliving 中通常能发现哪些生物？",a="这处岩穴到处都是变异蹒跚者——从受腐蚀的泉水中诞生的蹒跚植物恐怖——此外还有扭曲的蛇类和狂热的尖牙德鲁伊。",al={"岩穴中的怪物","岩穴敌人","这里有什么生物"}},{q="为什么植物能在如此深的地下茂盛生长？",a="暗夜精灵德鲁伊纳拉雷克斯利用地下泉水来恢复贫瘠之地。当他的仪式被翡翠梦魇捕获后，野生植物便疯狂生长，并扭曲成了敌对的畸形植被。",al={"为什么地下会有植物","为什么这里如此葱郁","受到腐蚀的植被"}}},fx={["6a6b08ee"]={q="Crag of the Everliving是什么地方？",a="Crag of the Everliving是哀嚎洞穴深处一处郁郁葱葱的地下洞窟。受腐化的自然能量滋养，这里植物繁茂、生长狂乱，岩架高耸。",al={"crag of the everliving是什么","crag of the everliving信息","关于crag of the everliving"}},cca8a755={q="Crag of the Everliving危险吗？",a="危险。这里是洞穴中最致命的区域之一。变异践踏者在过度生长的台地间徘徊，山崖由尖牙德鲁伊守卫，皮萨斯领头，瑟芬迪斯的巢穴也近在咫尺。",al={"crag of the everliving有多危险","crag of the everliving危险吗","crag of the everliving的威胁"}}},fp="22,298,18.491.0,20.427.0,34.261.0,38.196.0,64.170.0,47.219.0"}
P.entries["subzone:cragpool-lake"] = {n="峭壁湖",s="峭壁湖是一片隐匿于石爪山脉狂风峭壁之中的水域。在其深邃的水面之上，耸立着一座由荆棘谷地精建造的巨大木质结构。",h="峭壁湖是一片隐匿于石爪山脉狂风峭壁之中的水域。在其深邃的水面之上，耸立着一座由荆棘谷地精建造的巨大木质结构。",kw={"峭壁湖","格伦佐·扳鸣","石爪山脉","荆棘谷地精","狂风峭壁"},ang={["class:Druid"]="峭壁湖周围的径流、木质平台和破坏行为如同石爪山脉上的一道丑陋伤疤，扭曲了当地的生态系统并驱逐了原生野生动物。",["profession:Engineering"]="峭壁湖上方高耸的木制脚手架和悬臂式机械，堪称地精工业实用主义的教科书式展示——建造迅速，负荷沉重，且对自然地形漠不关心。"},sec={{t="工业侵蚀",b="峭壁湖坐落在狂风峭壁之中，正下方就是荆棘谷地精建造的庞大伐木装置。一座巨大的木质结构横跨水面，是格伦佐·扳鸣监督整个山谷作业的视察点。荆棘谷地精的工人们占据着上方的平台。"}},faq={{q="悬在湖面上的大型木质结构是什么？",a="这是一座由荆棘谷地精建造的工业上层建筑，旨在管理他们在狂风峭壁的大规模伐木和采矿工作。它连接着横跨湖面的平台与重型机械。",al={"荆棘谷地精平台","峭壁湖脚手架","峭壁湖大桥"}},{q="谁在监督峭壁湖的作业？",a="荆棘谷地精的一名关键干事格伦佐·扳鸣将自己的视察点设在高耸的脚手架顶端，以监督整个狂风峭壁的森林砍伐和资源开采工作。",al={"谁在此领导荆棘谷地精","谁是这里的老大","格伦佐·扳鸣"}},{q="峭壁湖周围有哪些危险？",a="荆棘谷地精在湖面上的平台上进行作业。其武装工人的存在使得这处工业地点对入侵者来说十分危险。",al={"峭壁湖里有什么"}},{q="荆棘谷地精放弃峭壁湖了吗？",a="没有。荆棘谷地精的工人和格伦佐·扳鸣仍然占据着湖面上方的建筑。",al={"荆棘谷地精离开了吗","谁住在峭壁湖"}}},fp="13,103,23.261.0,59.161.0,45.188.0,36.125.0,48.90.0"}
P.entries["subzone:crossroads"] = {n="十字路口",s="十字路口是部落在卡利姆多中部交通往来的心脏，位于南北走向的黄金之路与从棘齿城通往石爪山脉的道路交汇处。这里是一个繁忙的贸易前哨站、军事补给点，也是往返于杜隆塔尔、莫高雷和北方前线的旅客们的中转枢纽。",h="十字路口是部落在卡利姆多中部交通往来的心脏，位于南北走向的黄金之路与从棘齿城通往石爪山脉的道路交汇处。这里是一个繁忙的贸易前哨站、军事补给点，也是往返于杜隆塔尔、莫高雷和北方前线的旅客们的中转枢纽。",kw={"贫瘠之地","十字路口","迪弗拉克","黄金之路","迅猛龙","棘齿城","石爪山脉","双足飞龙"},ang={["faction:Alliance"]="直接打击十字路口可以切断往返于奥格瑞玛、莫高雷和灰谷争议边界之间的部落增援部队的流动。",["faction:Horde"]="十字路口是你羽翼未丰的民族的核心试炼场和交通枢纽，连接着兽人、牛头人和巨魔的家园，同时统筹着卡利姆多各地的补给。"},sec={{t="稀树草原上的交通要道",b="十字路口名副其实，正处于黄金之路与从地精港口棘齿城通往石爪山脉的东西向路线的交汇处。尽管这里设施简陋，但该前哨站却是一个繁忙的区域枢纽。双足飞龙管理员、商人、铁匠和训练师们在岗哨塔下常驻。对于从杜隆塔尔或莫高雷出发的年轻战士来说，这个定居点往往是他们首次见证将新部落紧密联系在一起的庞大、多战线后勤体系的地方。"},{t="处于围攻之下的边境哨所",b="维护十字路口的秩序是一场永无休止的斗争。当地的野生生物——包括胆大到敢从岗哨塔掠夺军饷银币的平原迅猛龙——构成了持续的困扰，而鹰身人、野猪人和半人马部落则不断对周边地区施加压力。除了贫瘠之地本土的威胁外，该定居点靠近中立的棘齿城和饱受争议的灰谷，使其成为联盟侦察小队入侵的首要目标，导致其防御路障外经常发生小规模冲突。"}},faq={{q="为什么十字路口对部落如此重要？",a="它是卡利姆多中部主要交通动脉的锚点。每一位往返于杜隆塔尔、莫高雷、棘齿城、石爪山脉或灰谷的陆路旅客都必须经过或靠近十字路口，这使其成为后勤和增援的主要枢纽。",al={"为什么十字路口很重要","十字路口的作用","为什么十字路口意义重大"}},{q="谁在十字路口提供飞行运输服务？",a="迪弗拉克担任十字路口的飞行管理员，负责管理该定居点的双足飞龙栖息地，并将旅客直接送往卡利姆多各地的哨所，包括奥格瑞玛和雷霆崖。",al={"十字路口飞行管理员","这里谁提供双足飞龙","十字路口的飞行管理员"}},{q="为什么联盟如此频繁地袭击十字路口？",a="因为十字路口是部落交通的中心，且处于北部灰谷和东部中立港口棘齿城的易攻距离之内，联盟突袭队经常将该前哨站作为目标，以破坏部落的补给线。",al={"为什么联盟袭击十字路口","十字路口的联盟pvp","对十字路口的袭击"}},{q="前哨站的军饷银币发生了什么事？",a="贫瘠之地的迅猛龙袭击了十字路口的岗哨塔，并抢走了一批本应发给该定居点守卫的军饷银币，将它们散落到了周围的稀树草原上。",al={"十字路口军饷失窃","谁拿走了银币","十字路口的银币被盗"}}},fp="10,226,32.363.0,28.356.0,48.225.0,48.140.0,58.171.0,46.187.0"}
P.entries["subzone:crown-guard-tower"] = {n="皇冠哨塔",s="皇冠哨塔是一座位于东瘟疫之地南部的洛丹伦废弃侦察塔。在第三次战争期间，天灾军团入侵了洛丹伦并摧毁了它，自那以后，它破碎的石块便一直矗立在枯萎之地中。",h="皇冠哨塔是一座位于东瘟疫之地南部的洛丹伦废弃侦察塔。在第三次战争期间，天灾军团入侵了洛丹伦并摧毁了它，自那以后，它破碎的石块便一直矗立在枯萎之地中。",kw={"皇冠哨塔","东瘟疫之地","洛丹伦","天灾军团","侦察塔","瞭望塔"},ang={["faction:Alliance"]="对于联盟来说，这处损毁的皇冠哨塔提醒着人们，天灾军团曾以何等彻底的方式摧毁了洛丹伦王国的防线。"},sec={{t="坍塌的堡垒",b="皇冠哨塔曾是洛丹伦王国防御体系的一部分，也是一座监视东洛丹伦大地的侦察塔。当天灾军团横扫该王国时，这座塔被摧毁并化为废墟，成为了散落在如今东瘟疫之地上的众多倒塌塔楼之一。它焦黑的石块依然矗立在这片亡灵仍旧占据的土地上。"}},faq={{q="皇冠哨塔最初的用途是什么？",a="在第三次战争之前，它曾作为洛丹伦人类王国的区域军事瞭望塔和侦察前哨，负责守卫道路以防入侵。",al={"皇冠哨塔历史","为何而建","洛丹伦塔楼"}},{q="这座塔为什么会损毁？",a="这座塔是在天灾军团入侵洛丹伦期间被摧毁的，当时如潮水般的亡灵冲垮了王国的防线，将这座建筑夷为瓦砾。",al={"谁摧毁了皇冠哨塔","这里发生了什么"}}},fp="17,225,16.354.0,48.157.0,24.151.0"}
P.entries["subzone:crusader-outpost"] = {n="十字军前哨",s="十字军前哨是一座设在提瑞斯法林地东部崎岖山丘顶端的加固岗哨。这里驻扎着血色十字军的狂热成员，守卫着通往他们大本营——血色修道院的入口。从这一高处，十字军监视着道路上的往来，并随时准备击退任何被遗忘者的入侵。",h="十字军前哨是一座设在提瑞斯法林地东部崎岖山丘顶端的加固岗哨。这里驻扎着血色十字军的狂热成员，守卫着通往他们大本营——血色修道院的入口。从这一高处，十字军监视着道路上的往来，并随时准备击退任何被遗忘者的入侵。",kw={"瓦松队长","十字军前哨","血色十字军","血色修道院","侦察塔","提瑞斯法林地","岗哨"},ang={["faction:Horde"]="在提瑞斯法东部的山径中穿行需要谨慎，因为这座山丘上的血色哨兵会迅速攻击任何向修道院方向行进的人。",["race:Undead"]="这座岗哨坐落在被遗忘者领地的边缘，时刻提醒着人们，这些狂热的生者十字军在林地中仍然保留着自己的据点。"},sec={{t="提瑞斯法之眼",b="十字军前哨建在俯瞰东部道路的悬崖上，是血色十字军主要的预警站。从这座高塔上，哨兵们监视着布瑞尔与洛丹伦东部地区之间的动向，确保在游荡的亡灵或侦察小队到达修道院大门前就能被发现。这座塔还使驻军能够对任何试图沿山谷向其圣所进军的部队进行战术侧翼打击。"},{t="黑暗女王眼中的芒刺",b="在诸如瓦松队长这样的血色十字军军官指挥下，驻扎在此的守军时刻保持着警惕。他们眼中的周围森林并非被遗忘者的领土，而是被怪物从人类手中窃取的亵渎之地。对于效忠于幽暗城的旅行者来说，这座前哨站是一个随时可能遭遇伏击的地方，任何过于靠近悬崖的人都会遭到弩箭和净化之刃的攻击。"}},faq={{q="什么是十字军前哨？",a="这是一座由血色十字军占据的加固侦察塔，位于提瑞斯法林地东部。它监视着下方经过的道路，并保护着通往血色修道院的南部入口。",al={"这座塔是什么","提瑞斯法十字军前哨","血色岗哨"}},{q="谁控制着这座前哨站？",a="这座前哨站由在瓦松队长指挥下的血色十字军狂热者驻守。他们视所有亡灵为必须当场消灭的憎恶。",al={"谁拥有十字军前哨","谁住在这里","血色十字军前哨站"}},{q="为什么这座塔要建在这些山丘上？",a="其高处的地理位置提供了对提瑞斯法林地东部主干道的清晰视野。这使得十字军能够尽早发现被遗忘者的部队调动，并对任何试图进攻血色修道院的部队进行侧翼攻击。",al={"为什么建在这里","前哨位置","战术目的"}},{q="这里的守卫会攻击我吗？",a="是的。血色十字军认为所有外来者——尤其是被遗忘者及其部落盟友——都是必须用圣火净化其罪恶的敌人。",al={"十字军前哨有敌意吗","他们具有攻击性吗"}}},fp="16,172,18.340.0,31.316.0,29.163.0,26.131.0,41.192.0,31.130.0"}
P.entries["subzone:crusader-s-armory"] = {n="Crusader's Armory",s="Crusader's Armory是一处位于Scarlet Monastery Armory侧厅内的防御性大厅。这里堆满了弹药、火药和炮弹，是守卫通往The Inner Sanctum路径的狂热者们的集结地。在它那道锁住的铁门后，便是Hall of Champions。",h="Crusader's Armory是一处位于Scarlet Monastery Armory侧厅内的防御性大厅。这里堆满了弹药、火药和炮弹，是守卫通往The Inner...",kw={"军械库","crusader's armory","火药","hall of champions","血色十字军钥匙","血色修道院"},ang={["faction:Horde"]="对于被遗忘者和部落来说，Crusader's Armory中的爆炸性物资直接威胁着提瑞斯法林地的边界和幽暗城的城门。",["profession:Blacksmithing"]="这里储备的武器和弹药展示了洛丹伦昔日铁匠的高超技艺和军事纪律，现在已全然转变为狂热的盲信。"},sec={{t="狂热者的军械库",b="Crusader's Armory坐落于Footman's Armory和宏伟的Hall of Champions之间，展示了血色十字军充分的军事准备。与外面的训练场不同，这些狭窄的石制走廊从地面到天花板堆满了易燃的火药箱、成堆的炮弹，以及随时准备击退入侵者的全副武装的十字军。血色十字军已将一处修道院建筑群转变为一座严阵以待的堡垒，将每一处可用的大厅都贡献给了全面战争的工具。军械库的最尽头矗立着一扇沉重的铁锁门，除非持有血色十字军钥匙，否则无法进入内部的密室。"}},faq={{q="Crusader's Armory是什么？",a="Crusader's Armory是血色修道院Armory侧厅的一个内部区域。它作为Footman's Armory和Hall of Champions之间的弹药库和防御走廊使用。",al={"crusaders armory","crusaders armory是什么","修道院军械库房间"}},{q="为什么尽头的门是锁着的？",a="Crusader's Armory尽头的门守卫着通往Hall of Champions和指挥官营地的通道。血色十字军对此处严加看守，必须使用在修道院Library侧厅中发现的血色十字军钥匙才能将其打开。",al={"军械库锁着的门","如何打开军械库门","血色十字军钥匙军械库"}},{q="为什么这里有这么多炮弹和火药箱？",a="血色十字军在整个提瑞斯法林地维持着活跃的围攻态势和炮兵防御。这座军械库是他们大炮和爆炸性军火的中央存储库，确保他们的部队在对抗天灾军团和被遗忘者时拥有充足的补给。",al={"军械库火药箱","修道院里的大炮","为什么有火药"}},{q="谁在守卫这个区域？",a="该大厅由经验丰富的血色十字军士兵防守，包括驻扎在弹药堆中的步兵、十字军和弓箭手，旨在阻止任何试图深入该建筑群的入侵者。",al={"军械库怪物","crusaders armory里有什么人"}}},fx={["2e345cd4"]={q="Crusader's Armory 危险吗？",a="这里极其危险。军械库里挤满了狂热的血色十字军战士，他们一发现入侵者就会发动攻击，把所有外来者都视为腐化势力或天灾军团的爪牙。更危险的是，整条走廊堆满了烈性炸药，包括易燃的火药桶和成堆的火炮弹药，供他们在提瑞斯法林地进行旷日持久的战争。",al={"crusader's armory 的危险","crusader's armory安全吗","crusader's armory 的威胁"}},["9c475e8e"]={q="为什么叫 Crusader's Armory？",a="这间军械室以驻守于此并在其中储存攻城装备的血色十字军战士命名。它位于血色修道院军事区深处，在步兵军械库之后，里面存放着火炮弹药、火药和武器，供血色十字军的老练战士使用，他们正准备进攻周边的瘟疫之地。",al={"为什么叫 crusader's armory","crusader's armory 名称由来","crusader's armory 的含义"}}},fp="17,293,15.621.0,30.194.0,34.252.0,60.275.0,21.196.0"}
P.entries["subzone:crusader-s-outpost"] = {n="Crusader's Outpost",s="Crusader's Outpost 是一座由血色十字军驻守的防御型侦察塔，位于提瑞斯法林地西部。它毗邻索利丹农场，是十字军在整个洛丹伦最西端的据点。由于它距离血色十字军的主要堡垒过于遥远，导致其驻军被孤立在充满敌意的被遗忘者领地的中心地带。",h="Crusader's Outpost...",kw={"crusader's outpost","血色十字军","侦察塔","索利丹农场","提瑞斯法林地","提尔之手"},ang={["faction:Horde"]="这座前哨站是一个痛苦的提醒，展示了血色十字军疯狂地拒绝将提瑞斯法拱手让给被遗忘者及其部落盟友的决心。",["race:Undead"]="对于从丧钟镇走出的新晋被遗忘者来说，这座附近的塔楼以及守护它的血色狂热分子，构成了紧邻他们边境的直接生存威胁。"},sec={{t="一座孤独的瞭望塔",b="这座石塔栖身于丧钟镇北部的提瑞斯法西部丘陵之中，代表了血色十字军在洛丹伦最远的影响力范围。驻扎于此的守军与附近索利丹农场幸存的人类劳工协同工作，试图抵挡不断侵蚀的亡灵。从塔顶望去，守望者们监视着周围的南瓜田和林间小路，时刻警惕着游荡的天灾军团恶魔以及来自幽暗城的巡逻队。"},{t="身陷敌后的孤岛",b="坚守西部边境风险极高。由于切断了与血色修道院主要据点以及远在东方的提尔之手的联系，这座前哨站的十字军如果遭遇攻击，无法指望迅速获得增援。任何由聚集在提瑞斯法各处的被遗忘者部队发动的围攻，都意味着他们要么独自守住塔楼，要么在援军到来之前面临彻底的覆灭。"}},faq={{q="为什么血色十字军会出现在提瑞斯法西部的这里？",a="这座塔楼作为提瑞斯法西部丘陵沿线的预警哨所和防御工事。它负责保护索利丹农场的在世人类农民，并监视西部通道，以防范野性的天灾军团和被遗忘者的先遣侦察兵。",al={"血色十字军为什么在这里","提瑞斯法西部的血色十字军","十字军前哨站的目的"}},{q="如果前哨站遭到攻击，援军能抵达这里吗？",a="很难。该前哨站是洛丹伦最西端的血色十字军据点。他们的主要堡垒位于遥远的东方，即血色修道院和提尔之手，这使得一旦被遗忘者部队包围，该驻军将彻底陷入孤立无援的境地。",al={"血色十字军能否增援","前哨站援助","援军距离多远"}},{q="这座塔楼与索利丹农场之间是什么关系？",a="十字军与索利丹农场剩余的人类农民结成了同盟。士兵们为他们提供抵御行尸走肉的保护，以换取食物补给，并在洛丹伦的边缘地带获得一个忠诚的后勤据点。",al={"与索利丹农场的联系","为什么十字军在农场","十字军与农民"}},{q="该地区还有其他类似的塔楼吗？",a="是的。这座塔楼是血色十字军在提瑞斯法林地建立的四座类似的 Crusader's Outpost 之一，用于侦察和巡逻周边土地。",al={"其他十字军前哨站","更多的血色塔楼"}}},fp="18,233,19.392.0,27.366.0,68.234.0,58.251.0,66.207.0,47.136.0"}
P.entries["subzone:crypt-badlands"] = {n="Crypt (Badlands)",s="在荒芜之地尘土飞扬的山丘高处，隐匿着一座被称为“墓穴”的偏僻地下陵墓。内部安息着一位古代战士的静默遗骸：一具身披盔甲的骸骨端坐在石王座上，身旁散落着骨灰瓮、宝箱和一把巨大的遗物之剑。",h="在荒芜之地尘土飞扬的山丘高处，隐匿着一座被称为“墓穴”的偏僻地下陵墓。内部安息着一位古代战士的静默遗骸：一具身披盔甲的骸骨端坐在石王座上，身旁散落着骨灰瓮、宝箱和一把巨大的遗物之剑。",kw={"荒芜之地","野蛮人国王","墓穴","铁趾挖掘场","剑","王座"},ang={["class:Warrior"]="对于战士们来说，这座墓穴提供了一个机会，让他们能在一个身穿板甲、至死仍紧握强大兵刃的陨落冠军面前表达片刻的敬意。",["race:Dwarf"]="虽然它坐落在活跃的矮人考古挖掘场附近，但其建筑风格和骸骨王座所指向的奥秘，显然早于铁炉堡近期的挖掘工作。"},sec={{t="野蛮人国王之墓",b="这座荒芜之地墓穴位于铁趾挖掘场的东南方，沿着一条沿山坡向上延伸的无名土路即可到达，过往的行人很容易错过它。在黑暗的石室深处，一具身着盔甲的骸骨端坐在王座之上。遗骸旁倚靠着野蛮人国王之剑，周围散落着零星的尸骨、骨灰瓮和被遗忘的宝箱。尽管矿工和冒险者经常出没于周边的沟壑，搜寻着矮人的遗迹和财宝，但这位坐姿君主的真实起源和历史，依然是埋没在干旱荒原中的未解之谜。"}},faq={{q="墓穴位于荒芜之地的什么地方？",a="入口位于铁趾挖掘场的东南方。若要到达那里，请沿着一条蜿蜒向上、通往挖掘场上方山脊的无名小径前行。",al={"荒芜之地墓穴位置","如何找到荒芜之地墓穴","荒芜之地墓穴入口"}},{q="王座上的那具骸骨是谁？",a="这具披甲骸骨通常被称为野蛮人国王。没有任何现存的当地文献记载过他的统治或身份，使他成为了荒芜之地那个早已被遗忘的远古时代留下的一件神秘遗物。",al={"王座上的骸骨","谁是野蛮人国王","墓穴骸骨身份"}},{q="王座旁的那把剑是什么？",a="它被称为野蛮人国王之剑。它静静地靠在骸骨统治者的身旁，作为庄严肃穆的墓碑，见证着他那充满战火的过去。",al={"野蛮人国王之剑","墓穴之剑","荒芜之地王座之剑"}},{q="有与这座墓穴相关的任务吗？",a="没有指引冒险者前往该墓穴的标准任务。它主要作为一个令人毛骨悚然的隐藏发现，供那些搜寻悬崖的旅行者探寻。",al={"荒芜之地墓穴任务","为什么要前往荒芜之地墓穴"}}},fp="16,266,30.542.0,43.147.0,49.202.0,37.162.0,48.151.0"}
P.entries["subzone:crypt-stromgarde-keep"] = {n="Crypt (Stromgarde Keep)",s="在激流堡的废墟深处坐落着皇家墓穴，它位于密室教堂之后，处于幸存的激流堡保卫者所掌控的核心区域。这里安放着已故国王索拉斯·托尔贝恩的陵墓以及他王朝的祖传宝藏。在加林王子和忠诚的看守者的严密守卫下，这处拱顶在破碎的王国中依然是一片彰显皇家荣耀的圣所。",h="在激流堡的废墟深处坐落着皇家墓穴，它位于密室教堂之后，处于幸存的激流堡保卫者所掌控的核心区域。这里安放着已故国王索拉斯·托尔贝恩的陵墓以及他王朝的祖传宝藏。在加林王子和忠诚的看守者的严密守卫下，这处拱顶在破碎的王国中依然...",kw={"阿拉希","墓穴","加林","密室","激流堡","索拉斯","托尔卡拉","托尔贝恩"},ang={["faction:Alliance"]="激流堡的皇家墓穴是联盟在阿拉希的最后堡垒之一，它顽强地抵御着强盗、食人魔和部落的侵袭。",["race:Human"]="对于联盟的人类而言，这座陵墓代表了七大王国之一的激流堡那悲剧性的衰落，也是联盟最勇猛的战时领袖之一的神圣安息地。"},sec={{t="索拉斯·托尔贝恩之墓",b="这处地下墓穴隐藏在激流堡密室的下方，是索拉斯·托尔贝恩国王的最终安息之所，这位武力非凡的君王曾带领激流堡度过了第二次战争。尽管这座城市遭受了毁灭性的打击——被辛迪加盗贼和巨石食人魔瓜分——但留守的激流堡民兵依然死死守卫着这个区域。加林·托尔贝恩王子亲自与尽职的皇家看守者们一同看管着这些墓穴，确保他父亲的遗体和遗产不会受到外界拾荒者和敌人的侵扰。"},{t="托尔卡拉之库",b="除了安放皇家逝者外，这处墓穴还守护着托尔贝恩家族珍贵的文物。其中最重要的圣物就是托尔卡拉，这把古老的符文巨剑是在几个世纪前为屠杀巨魔而锻造的。在阿拉里克、内夫林和韦斯顿等发誓守护的看守者的保护下，这间墓室及其宝藏被强大的防护措施所封存。加林和他的忠诚部下不懈地守护着陵墓，因为他们深知阿拉希各处的敌对派系和仇视人类的巨魔都觊觎着这把利刃的古老力量。"}},faq={{q="谁被埋葬在墓穴中？",a="激流堡已故的统治者，索拉斯·托尔贝恩国王安葬于此。他的儿子，加林·托尔贝恩王子，在这座荒废的城市中守卫着陵墓。",al={"谁葬在这里","这是谁的陵墓","墓穴 陵墓"}},{q="什么是托尔卡拉？",a="托尔卡拉是托尔贝恩家族的古老传家宝剑。它的名字在古代语言中的意思是“巨魔杀手”，最初是为了对抗阿拉希盆地的森林巨魔而锻造的。",al={"托尔卡拉之剑","托尔贝恩之剑","什么是托尔卡拉"}},{q="谁在守卫墓穴？",a="墓穴由加林·托尔贝恩王子和激流堡的皇家看守者（包括阿拉里克、内夫林和韦斯顿）共同保卫。他们守护着墓室，抵御辛迪加窃贼和巨石食人魔的入侵。",al={"墓穴守卫","谁在保卫墓穴","看守者"}},{q="墓穴位于何处？",a="它位于阿拉希高地的激流堡内，坐落在密室区域的深处，就在城堡教堂的后面，处于激流堡忠诚派依然掌控的区域内。",al={"墓穴位置","如何找到墓穴","激流堡墓穴在哪"}}},fp="23,394,28.570.0,23.518.0,27.153.0,19.219.0,21.212.0,27.176.0"}
P.entries["subzone:crystal-lake"] = {n="水晶湖",s="水晶湖是位于艾尔文森林中心地带、闪金镇以东的一片水域。这里曾经是一个宁静的地方，但现在其湖岸已被好斗的鱼人占领，成为当地村民和过往旅客经常面临的危险之地。",h="水晶湖是位于艾尔文森林中心地带、闪金镇以东的一片水域。这里曾经是一个宁静的地方，但现在其湖岸已被好斗的鱼人占领，成为当地村民和过往旅客经常面临的危险之地。",kw={"水晶海藻","水晶湖","艾尔文","闪金镇","鱼人","威廉·匹斯特"},ang={["faction:Alliance"]="鱼人在闪金镇附近的泛滥，凸显了王国在保卫核心领土方面的兵力是何等捉襟见肘。",["profession:Herbalism"]="淡水浅滩中生长着水晶海藻，不过它主要是从栖息在湖底并采集海藻的鱼人身上获得的。"},sec={{t="动荡的湖岸",b="水晶湖距离Lion's Pride Inn仅几步之遥，本应是一处宁静的乡村休憩之所，却饱受危险野生生物的困扰。成群的淡水鱼人占据了湖岸和浅滩，袭击任何过于靠近的人。当地的炼金术师威廉·匹斯特经常雇佣过往的冒险者前往水边，指引他们击败这些生物，并收集它们身上携带的水晶海藻，用于他的实验性药剂。"}},faq={{q="水晶湖在哪里？",a="水晶湖位于艾尔文森林中心地带，闪金镇的东侧，从村庄郊区步行即可轻松抵达。",al={"水晶湖位置","水晶湖在哪里","寻找水晶湖"}},{q="为什么鱼人会聚集在水晶湖？",a="和艾尔文森林中的许多水道一样，水晶湖为鱼人提供了筑巢和觅食的天然淡水栖息地。由于暴风城当地卫兵兵力吃紧，靠近闪金镇的鱼人数量激增。",al={"为什么鱼人在水晶湖","闪金镇的鱼人问题","水晶湖鱼人"}},{q="冒险者需要从水晶湖获得什么？",a="威廉·匹斯特是一位在闪金镇的Lion's Pride Inn工作的药剂师，他雇佣冒险者去猎杀湖岸边的鱼人，以此收集他制造隐形药水所需的水晶海藻。",al={"威廉·匹斯特水晶湖","水晶海藻任务水晶湖","艾尔文森林隐形药水"}}},fp="12,118,16.314.0,30.94.0,41.149.0,43.167.0"}
P.entries["subzone:crystal-shore"] = {n="水晶海岸",s="水晶海岸是位于荆棘谷东南边缘的一片沙质海岸线，受南海波涛的冲刷。这片沙滩隐匿在陡峭的海岸悬崖之下，位于古老的阿博拉兹废墟以南，与哈圭罗岛隔水相望。",h="水晶海岸是位于荆棘谷东南边缘的一片沙质海岸线，受南海波涛的冲刷。这片沙滩隐匿在陡峭的海岸悬崖之下，位于古老的阿博拉兹废墟以南，与哈圭罗岛隔水相望。",kw={"水晶海岸","哈圭罗岛","薄雾山谷","阿博拉兹废墟","南海","荆棘谷","蛮荒海岸"},sec={{t="一片与世隔绝的海岸带",b="水晶海岸沿着荆棘谷的东南边界延伸，构成了茂密的热带内陆与开阔的南海海域之间的一道天然边界。这片沙滩本身被陡峭的山脊与内陆丛林隔开，只留下了几条崎岖的通道，供那些试图在海岸与更深处的薄雾山谷荒野之间往来的旅人通行。北面是阿博拉兹废墟那摇摇欲坠的巨魔建筑，而蛮荒海岸则沿着海岬的南侧曲线延伸。由于其地理位置，这里成为了一处安静且饱受风吹的边缘地带，远离喧嚣的藏宝海湾码头。"}},faq={{q="水晶海岸位于何处？",a="水晶海岸坐落在荆棘谷的最东南海岸。它沿着面朝南海的海域延伸，位于阿博拉兹废墟以南，蛮荒海岸的东北方向。",al={"水晶海岸位置","水晶海岸在哪里","水晶海岸地图"}},{q="如何从内陆前往水晶海岸？",a="一道陡峭的山脊将沙滩与内陆丛林隔开。不过，高耸的悬崖间有几条狭窄的天然通道，其中包括一条直接通往薄雾山谷的小径。",al={"如何到达水晶海岸","去往水晶海岸的路径","抵达水晶海岸"}},{q="附近有哪些地标？",a="在海岸北面矗立着古老的阿博拉兹废墟，西南方向隔着水道则是哈圭罗岛。沿海岸线向南更远的地方是蛮荒海岸。",al={"水晶海岸附近的地标","水晶海岸附近有什么"}},{q="有任何阵营在水晶海岸定居吗？",a="没有任何正式阵营在水晶海岸设有城镇或定居点。这里依然是一片未经开发的海岸，被原生野生动物、北面的古代巨魔废墟以及南海的拍岸浪潮所占据。",al={"谁居住在水晶海岸","水晶海岸定居点","水晶海岸城镇"}}},fp="13,270,24.627.0,35.208.0,48.186.0,26.187.0,44.218.0"}
P.entries["subzone:crystal-vale"] = {n="水晶谷",s="水晶谷坐落于希利苏斯的西北远角，是一处偏僻的峡谷，满是参差不齐的矿物尖塔和盘旋的元素力量。土元素和风元素徘徊在岩石平原上，守护着丰富的矿脉。这里也是强大的召唤魔法之地，与远古的元素领主有着深厚的联系。",h="水晶谷坐落于希利苏斯的西北远角，是一处偏僻的峡谷，满是参差不齐的矿物尖塔和盘旋的元素力量。土元素和风元素徘徊在岩石平原上，守护着丰富的矿脉。这里也是强大的召唤魔法之地，与远古的元素领主有着深厚的联系。",kw={"水晶谷","元素生物","德米提恩","暮光营地废墟","希利苏斯","瑟银","thunderaan"},ang={["class:Shaman"]="此处土元素与风元素灵魂之间产生的剧烈摩擦，有力地提醒着人们希利苏斯各地那些不受束缚的元素所带来的混乱。",["profession:Mining"]="水晶谷崎岖的边缘和峡谷岩壁据说是富瑟银矿脉的所在地，使其成为高等级矿工眼中一处有利可图但也充满危险的目的地。"},sec={{t="石与风的交汇处",b="水晶谷与希利苏斯南部的贫瘠沙漠截然不同。盆地四周环绕着陡峭的悬崖，布满了闪烁的晶体结构、徘徊的土元素和咆哮的活体旋风。丰富的瑟银矿藏偶尔会吸引胆大的勘探者，但这里绝非安宁之地。此地的元素生物对入侵者有着天然的敌意，它们守护着这片仿佛沉浸在艾泽拉斯原始冲突中的领域。"},{t="逐风者的沉睡",b="除了矿物和原生灵魂外，水晶谷对远古的元素力量而言意义深远。德米提恩在此徘徊，守护着逐风者桑德兰王子的秘密。那些收集了这位陨落王子断裂的元素束缚以及最稀有锻造金属的勇士们会被指引至此山谷，被囚禁的风元素领主可以从束缚中被唤出，并接受公开的挑战。"}},faq={{q="水晶谷位于何处？",a="水晶谷位于希利苏斯的西北边缘，坐落在接壤沙漠的山缘之间。",al={"水晶谷在哪里","水晶谷地图","水晶谷位置"}},{q="山谷里居住着什么生物？",a="峡谷里主要栖息着具有攻击性的风元素和土元素，它们在矿层周围漂浮和踩踏。",al={"水晶谷怪物","水晶谷有什么生物","水晶谷的元素生物"}},{q="德米提恩是谁，他为什么在这里？",a="德米提恩是一位居住在山谷中的隐士，掌握着关于桑德兰王子的深奥知识。他会帮助那些有能力重聚逐风者束缚并召唤这位元素王子的勇士。",al={"德米提恩是谁","水晶谷的德米提恩","德米提恩位置"}},{q="什么是暮光营地废墟？",a="那是山谷内一座暮光之锤营地的残骸，已被占据峡谷的狂暴元素居民摧毁并夷为平地。",al={"水晶谷的暮光营地废墟","山谷里的暮光营地","被摧毁的暮光营地"}}},fp="12,325,30.472.0,29.437.1,34.134.0,35.122.0,45.208.0,34.148.0"}
P.entries["subzone:crystalvein-mine"] = {n="水晶矿洞",s="水晶矿洞是位于荆棘谷中部的一个洞穴，毗邻古老的祖玛维废墟。洞穴中蕴藏着宝贵的“歌唱水晶”，但好斗的本土蛇怪已经完全占据了此地，将那些意图采矿的人变成了坚硬的石头。",h="水晶矿洞是位于荆棘谷中部的一个洞穴，毗邻古老的祖玛维废墟。洞穴中蕴藏着宝贵的“歌唱水晶”，但好斗的本土蛇怪已经完全占据了此地，将那些意图采矿的人变成了坚硬的石头。",kw={"蛇怪","克兰克·菲兹巴布","水晶矿洞","歌唱水晶","荆棘谷","荆棘谷地精","祖玛维"},ang={["profession:Mining"]="受歌唱水晶的诱惑而来的矿工必须小心行事，因为洞穴中本土蛇怪的数量使得在这里勘探成为荆棘谷最危险的活动之一。"},sec={{t="一个诱人的陷阱",b="水晶矿洞隐藏在祖玛维附近的丛林丘陵中，拥有稀有的歌唱水晶矿藏。这是一种独特的矿石，在南部贸易港口能卖出高价。在巨额利润的诱惑下，荆棘谷地精将目光投向了这些矿脉。然而，矿洞的原住民对生意来说是灾难性的。当地的蛇怪以这些奇特的晶体为食，这硬化了它们的鳞片，使它们变得异常致命。在洞口外，巨魔和人类的石化雕像矗立在那里，无声地证明了荆棘谷地精远征队的失败。"}},faq={{q="水晶矿洞为何具有价值？",a="这座矿洞储藏着稀有的“歌唱水晶”，这是一种仅能在荆棘谷发现的暴利矿石。克兰克·菲兹巴布等地精因其声学价值和货币价值而对其趋之若鹜，驱使勘探者们冒险进入危险的洞穴。",al={"为什么水晶矿洞很重要","水晶矿洞里有什么","歌唱水晶"}},{q="为什么矿洞外有石像？",a="这些雕像是倒霉的当地巨魔和荆棘谷地精劳工被石化后的残骸。居住在这里的蛇怪以这些共鸣晶体为食，增强了它们石质的皮，并将任何愚蠢到侵入它们觅食地的人变成石头。",al={"水晶矿洞里的石化者","水晶矿洞里的结晶巨魔","荆棘谷的石体"}},{q="谁目前控制着水晶矿洞？",a="尽管荆棘谷地精声称拥有开采该洞穴的权利，但他们实际上并未占领此处。蛇怪的泛滥非常严重，以至于地精们无法在深处建立有效的采矿作业。",al={"谁拥有水晶矿洞","水晶矿洞阵营","水晶矿洞的荆棘谷地精"}}},fp="16,265,16.596.0,37.239.0,45.252.0,40.224.0"}
P.entries["subzone:cut-throat-alley"] = {n="Cut-Throat Alley",s="Cut-Throat Alley是暴风城中一个僻静且无人居住的角落，藏在运河商店后方。它位于Dwarven District边缘一家名为Shady Lady的店面后方，由一个安静的庭院和一处与城市日常人流隔绝的空宅组成。",h="Cut-Throat Alley是暴风城中一个僻静且无人居住的角落，藏在运河商店后方。它位于Dwarven District边缘一家名为Shady Lady的店面后方，由一个安静的庭院和一处与城市日常人流隔绝的空宅组成。",kw={"cathedral square","cut-throat alley","dwarven district","秘密小巷","shady lady","暴风城运河"},ang={["class:Rogue"]="只能通过一家阴暗运河商店的后门进入，这个无人巡逻的死胡同为那些希望避开暴风城卫兵视线的人提供了一个理想的藏身处。"},sec={{t="一个僻静的角落",b="Cut-Throat Alley是暴风城最安静、最隐秘的角落之一。虽然在地图上它被划归为Dwarven District，但这里既没有该区喧嚣的熔炉之火，也没有浓重的煤烟。这条小巷无法通过城市的主要街道进入；唯一的通道是穿过位于Cathedral Square南侧桥边运河旁的小店Shady Lady。店门外是一个铺设过的小型死胡同，堆放着货物箱、废弃的木桶，还有一栋无人居住的两层住宅。这里完全避开了过往的卫兵和普通市民，在首都的喧嚣中显得格外寂静。"}},faq={{q="如何前往Cut-Throat Alley？",a="前往Dwarven District边缘的运河岸边，就在通往Cathedral Square的人行桥南侧。寻找一家名为Shady Lady的商店。径直穿过这家店的后门，就能直接进入这条隐蔽的小巷。",al={"寻找cut throat alley","cut throat alley位置","cut-throat alley在哪里","如何进入cut-throat alley"}},{q="为什么地图将此地标为Dwarven District？",a="这条小巷位于Dwarven District的范围内，通常被视为该区的一部分，尽管它并没有该区的烟雾，也不与该区的街道相连。唯一的入口是运河岸边的Shady Lady。",al={"小地图dwarven district","为什么显示为dwarven district","cut-throat alley名称错误"}},{q="有人住在Cut-Throat Alley吗？",a="没有。这条小巷及其唯一的两层住宅完全被废弃了。除了堆放的货物箱和空木桶外，这里没有居民、店主或驻守的城市卫兵。",al={"cut throat alley的npc","谁住在cut throat alley","cut throat alley的空房子"}},{q="Cut-Throat Alley里有什么任务吗？",a="没有任务或市政指派会将玩家引向这条小巷。它仅仅是首都中一个被忽视的僻静背景地。",al={"cut throat alley的任务","cut throat alley剧情"}}},fp="16,165,15.496.0,35.178.0,48.207.0,37.201.0,41.123.0"}
P.entries["subzone:dabyrie-s-farmstead"] = {n="达比雷农场",s="达比雷农场是位于阿拉希高地北部的一个联盟阵营乡村定居点。在这个被第三次战争摧毁，并充斥着辛迪加不法之徒和枯木巨魔的国度里，这片庄园仍是斯托姆加德公民在肯娜塔·达比雷领导下的一座顽强堡垒。",h="达比雷农场是位于阿拉希高地北部的一个联盟阵营乡村定居点。在这个被第三次战争摧毁，并充斥着辛迪加不法之徒和枯木巨魔的国度里，这片庄园仍是斯托姆加德公民在肯娜塔·达比雷领导下的一座顽强堡垒。",kw={"阿拉希","卡洛","达比雷","法德尔","农场","肯娜塔","马塞尔","斯托姆加德"},ang={["faction:Alliance"]="对于联盟旅行者来说，这座农场是一个罕见且令人欣慰的提醒，告诉人们即便身处四面楚歌的境地，斯托姆加德的人民依然在为自己的土地生存和战斗。",["race:Undead"]="对于被遗忘者来说，这处繁荣的家园简直是个令人恼火的讽刺，里面的活人囤积着从第三次战争中死难家族那里抢来的财物。"},sec={{t="高地堡垒",b="达比雷农场坐落在阿拉希高地的北部原野上，是破碎的斯托姆加德王国中为数不多仍在运作的人类家园之一。农场由肯娜塔·达比雷拥有，她与两个儿子法德尔和马塞尔共同经营，并由当地的一支家族民兵武装拼死保卫。这片农场被凶猛的野生动物、伺机而动的强盗以及北部近在咫尺的被遗忘者势力所包围，成为了人类在这一荒芜之地顽强生存的象征。"},{t="苦涩仇怨",b="在阿拉希，生存往往伴随着苦涩的仇怨。这座庄园招致了被遗忘者的强烈愤怒，尤其是曾在大战中失去家园和亲人的前贵族女士吉娜维·卡洛。卡洛指责达比雷家族在瘟疫肆虐的混乱时期劫掠了她家族的珍贵传家宝，使这座原本简朴的农场成为了部落雇佣兵寻求清算旧日北部恩怨的目标。"}},faq={{q="谁住在达比雷农场？",a="这座农场是肯娜塔·达比雷和她的儿子法德尔与马塞尔的家。他们是忠于联盟的斯托姆加德人类公民，并受到当地民兵誓死保护。",al={"谁拥有达比雷农场","达比雷家族","肯娜塔·达比雷"}},{q="为什么部落要针对这个农场？",a="一名叫吉娜维·卡洛的被遗忘者对达比雷一家怀恨在心。她声称在第三次战争中她的亲人罹难时，达比雷一家洗劫了她家族的庄园，并抢走了她幸存的传家宝。",al={"为什么要杀达比雷","吉娜维·卡洛任务","部落达比雷任务"}},{q="达比雷农场属于斯托姆加德吗？",a="是的。达比雷一家视自己为斯托姆加德王国的臣民和广大联盟的盟友，尽管南方的主城已经陷落，他们依然坚守于此。",al={"达比雷是联盟吗","斯托姆加德农场"}},{q="农场周围有哪些威胁？",a="农场所处的位置十分危险，紧邻充满敌意的高地掠食者、四处游荡的辛迪加割喉者，以及从北方边境步步紧逼的被遗忘者部队。",al={"达比雷的威胁","达比雷农场附近的危险"}}},fp="19,277,26.482.0,12.437.1,33.168.0,37.215.0,42.184.0,36.162.0"}
P.entries["subzone:dagger-hills"] = {n="匕首岭",s="匕首岭是一道横跨西部荒野南部、紧邻荒废的月溪镇后方的崎岖山脊。这片岩石高地长期被皇室所忽视，成了不法之徒、强盗和潜伏的恐怖生物的聚集地，威胁着周边的平原。",h="匕首岭是一道横跨西部荒野南部、紧邻荒废的月溪镇后方的崎岖山脊。这片岩石高地长期被皇室所忽视，成了不法之徒、强盗和潜伏的恐怖生物的聚集地，威胁着周边的平原。",kw={"匕首岭","迪菲亚潜行者","葛瑞姆·雷酒","莱普瑞瑟斯","月溪镇","雷酒","西部荒野"},ang={["faction:Alliance"]="这些山丘代表了西部荒野南部法律的彻底崩溃，格里安·斯托曼的人民民兵必须在此奋战，以夺回因暴风城缺席而丧失的领土。",["race:Dwarf"]="葛瑞姆·雷酒独自一人守在这片暴露的山脊上，展现了矮人酿酒师那种为了寻找不受干扰的空间来完善技艺而展现出的顽固执着。"},sec={{t="强盗的避风港",b="匕首岭高耸于月溪镇破败的定居点之上，构成了西部荒野南部崎岖的边缘。由于暴风城不再派遣官方巡逻队，这片干旱的高地已成为迪菲亚潜行者的天然堡垒。指节火枪手、探路者和强盗潜伏在岩脊与灌木丛中，伏击毫无防备的旅行者，并监视着通往下方据点的道路。"},{t="山脊上的阴影",b="除了凡人罪犯外，匕首岭在夜幕掩盖下还带有一种诡异的名声。每当夕阳西下，人们就会看到令人不安的幽灵——游荡的食尸鬼莱普瑞瑟斯在荒凉的高地上徘徊。除了游荡的罪犯和徘徊的亡灵，唯一愿意冒着风险待在这道山脊上的居民就是葛瑞姆·雷酒，一位矮人酿酒师。他无视附近的危险，在这片崎岖的荒野中搭建起了他的蒸馏设备。"}},faq={{q="匕首岭在哪里？",a="匕首岭构成了西部荒野南部高耸的岩石边界，位于被遗弃的月溪镇正后方。",al={"匕首岭位置","匕首岭在哪里","如何前往匕首岭"}},{q="谁控制着匕首岭？",a="迪菲亚潜行者在这道山脊上保持着强大的势力，派遣强盗、探路者和指节火枪手守卫着南部丘陵。",al={"匕首岭迪菲亚潜行者","谁住在匕首岭","匕首岭的敌人"}},{q="为什么会有矮人在这里酿酒？",a="葛瑞姆·雷酒在这片寂寥的高地上建立了他的酿酒厂，为了酿造出烈性矮人啤酒，他不惜冒着被强盗和野兽袭击的风险，只为了那口好酒。",al={"葛瑞姆·雷酒 西部荒野","匕首岭的矮人","葛瑞姆·雷酒背景故事"}},{q="莱普瑞瑟斯是什么？",a="莱普瑞瑟斯是一只臭名昭著的食尸鬼，经常在匕首岭的岩壁间徘徊，令任何在黑暗中不幸撞见它的旅行者或强盗心惊胆战。",al={"莱普瑞瑟斯刷新","匕首岭的食尸鬼","匕首岭的亡灵"}}},fp="12,160,14.266.0,20.276.0,35.81.0,30.117.0,36.117.0,18.122.0"}
P.entries["subzone:dalaran"] = {n="达拉然",s="达拉然曾是肯瑞托辉煌的魔法王国首都，坐落在洛丹米尔湖南岸。在第三次战争中被天灾军团和恶魔领主阿克蒙德摧毁，幸存的法师们正在重建这座城市，并在重建初期移除了其保护性的紫色护盾。",h="达拉然曾是肯瑞托辉煌的魔法王国首都，坐落在洛丹米尔湖南岸。在第三次战争中被天灾军团和恶魔领主阿克蒙德摧毁，幸存的法师们正在重建这座城市，并在重建初期移除了其保护性的紫色护盾。",kw={"奥特兰克","阿克蒙德","六人议会","达拉然","穹顶","肯瑞托","洛丹米尔","护盾","紫罗兰城堡"},ang={["class:Mage"]="达拉然是人类和高等精灵巫术的历史摇篮。看到它那传奇的尖塔仍在重建中，这让人庄严地想起法师们在第三次战争中遭受的惨重损失。",["faction:Alliance"]="达拉然是最初洛丹伦联盟的七个创始王国之一，肯瑞托正在重建其沦陷的首都。"},sec={{t="魔法王国的陨落",b="达拉然由阿拉索帝国的巫师在古老的巨魔战争后建立，几个世纪以来一直是人类研究奥术的首要圣地。在六人议会的领导下，肯瑞托积累了庞大的魔法档案，并将强大的神器守卫在紫罗兰城堡中。那段辉煌的时代在第三次战争中戛然而止。叛徒王子阿尔萨斯率领天灾军团穿过城门夺取了麦迪文之书，此后不久，恶魔领主阿克蒙德将达拉然高耸的尖塔摧毁成废墟。"},{t="重建魔法王国",b="在军团战败后，肯瑞托幸存的巫师回到了他们满目疮痍的家园。他们拒绝将祖地让给天灾军团或拾荒者，在城市中心上方竖起了一道无法逾越的闪烁紫色屏障。护盾此后已被移除，但重建工作仍在继续。法师们继续重建他们沦陷的圣地，可以在紫罗兰城堡找到大法师安斯雷姆·鲁因维沃尔。"}},faq={{q="达拉然的保护护盾怎么了？",a="肯瑞托在达拉然于第三次战争中被毁后竖起了一道魔法护盾。护盾现已被移除，城市仍在重建中。",al={"紫色气泡","紫色护盾奥特兰克","那个穹顶是什么","达拉然穹顶"}},{q="玩家可以进入达拉然吗？",a="可以，虽然重建工作仍在进行，大法师安斯雷姆·鲁因维沃尔也居住在紫罗兰城堡。不过，肯瑞托站在联盟一边：部落在他们眼中是仇恨对象，在城中会被立刻攻击，但部落团队仍然可以挑战达拉然城地下城。",al={"我能进入达拉然吗","如何进入达拉然","越过达拉然护盾"}},{q="是谁摧毁了达拉然？",a="达拉然遭到了阿尔萨斯王子及其天灾军团的攻击，他们从金库中偷走了麦迪文之书。不久之后，恶魔领主阿克蒙德召唤黑暗魔法将这座城市化为废墟。",al={"达拉然是如何陷落的","是谁炸毁了达拉然","为什么达拉然是一片废墟"}},{q="谁统治达拉然？",a="这座城市由肯瑞托治理，这是一个由被称为六人议会的统治集会领导的精英魔法机构。",al={"谁管理达拉然","达拉然领导层","谁领导肯瑞托"}}},fp="7,308,21.539.0,24.459.0,43.163.0,26.275.0,22.202.0,18.118.0"}
P.entries["subzone:dalson-s-tears"] = {n="达尔松之泪",s="达尔松之泪是一处位于西瘟疫之地中心地带的荒废农庄。这片土地曾被称为达尔松果园，在第三次战争期间被占领，并被改造为天灾军团存放有毒瘟疫大锅的集结地。农场主人死后的亡灵残骸至今仍在田野和外屋游荡。",h="达尔松之泪是一处位于西瘟疫之地中心地带的荒废农庄。这片土地曾被称为达尔松果园，在第三次战争期间被占领，并被改造为天灾军团存放有毒瘟疫大锅的集结地。农场主人死后的亡灵残骸至今仍在田野和外屋游荡。",kw={"大熔炉领主马尔维尼斯","达尔松果园","达尔松之泪","达尔松先生","达尔松夫人","瘟疫大锅","西瘟疫之地"},ang={["class:Paladin"]="被亵渎的田野和达尔松一家受苦的灵魂，证明了圣光的圣武士们誓要将洛丹伦从挥之不去的邪恶中净化干净。",["race:Undead"]="这座荒废的农庄是一个鲜明的提醒，让人想起在Sylvanas Windrunner打破巫妖王对被遗忘者的控制之前，许多洛丹伦人民共同的命运。"},sec={{t="被毒化的收成",b="在第三次战争之前，这片庄园曾是达尔松果园，是洛丹伦粮仓中一片多产的农田。如今，这片田野充斥着腐烂的气息，被重新命名为达尔松之泪。在废弃农场的中心矗立着一口巨大的铁锅，源源不断地向周围散发着剧毒的绿色瘟疫蒸汽。该装置由大熔炉领主马尔维尼斯监管，并由一群凋零僵尸、腐烂尸体和效忠于巫妖王的骸骨恐怖怪防守。"},{t="达尔松一家的命运",b="当瘟疫席卷该地区时，农场的原主人遭遇了悲惨的结局，但死亡并没有给他们带来解脱。达尔松夫人作为一具毫无思想的骷髅在被毒化的土地上游荡，手里紧握着农场外屋的钥匙。在那间小屋里潜伏着可怕的食尸鬼，那正是达尔松先生本人，他在夫妻二人都彻底屈服于天灾军团的诅咒之前，被绝望的妻子锁在了里面。"}},faq={{q="达尔松之泪在瘟疫爆发前叫什么名字？",a="在第三次战争摧毁洛丹伦之前，这处房产是一块繁荣的农业用地，被称为达尔松果园。",al={"达尔松果园","原名","这个农场原来叫什么"}},{q="为什么农场中间会有一个巨大的大锅？",a="天灾军团在洛丹伦的农田各处竖起了巨大的瘟疫大锅，用来持续熬煮剧毒毒素。这些蒸汽飘散在整个地区，污染了大地，毒害了水源，并腐蚀了任何接触到它们的生物。",al={"达尔松大锅","绿烟大锅","这里为什么有个大锅"}},{q="谁在看守达尔松之泪的大锅？",a="这口瘟疫大锅由大熔炉领主马尔维尼斯保护，他是效忠于天灾军团的亡灵指挥官，身边还有成群的凋零僵尸、骸骨恐怖怪和腐烂尸体随从。",al={"大熔炉领主","这里的老大是谁","大熔炉领主马尔维尼斯"}},{q="关于那个锁住的外屋有什么了解？",a="那个锁住的外屋是废弃农场的一部分。达尔松夫人的日记为调查这一家人遭遇的任何人提供了线索。",al={"外屋怪物","外屋里有什么","达尔松先生"}}},fp="14,329,18.487.0,23.399.1,49.118.0,56.245.0,42.181.0,40.137.1"}
P.entries["subzone:dandred-s-fold"] = {n="达伦德农场",s="达伦德农场是一处隐秘的农舍和庄园，坐落在奥特兰克山脉洛丹米尔湖薄雾缭绕的西北岸。这里现在已被辛迪加占领，成为了奥里登·匹瑞诺德领主及其同谋者的安全避难所。部落和联盟出于完全不同的原因，都密切关注着这处湖畔据点。",h="达伦德农场是一处隐秘的农舍和庄园，坐落在奥特兰克山脉洛丹米尔湖薄雾缭绕的西北岸。这里现在已被辛迪加占领，成为了奥里登·匹瑞诺德领主及其同谋者的安全避难所。部落和联盟出于完全不同的原因，都密切关注着这处湖畔据点。",kw={"奥里登·匹瑞诺德","阿古斯唤醒者","达伦德农场","艾丽萨","洛丹米尔湖","纳格兹","辛迪加","高地"},ang={["faction:Alliance"]="联盟无法容忍人类不法之徒与恶魔般的阿古斯唤醒者结盟，因此赫尼·马雷布镇长下令对该庄园进行外科手术式的打击。",["faction:Horde"]="对于部落来说，潜入达伦德农场有着深刻的私人原因。大酋长萨尔希望夺回塔蕾莎·福克斯顿的项链。"},sec={{t="沦为不法之徒巢穴的贵族避风港",b="达伦德农场位于高地的西缘，拥有通往洛丹米尔湖水域的私人通道，曾经是一处宁静的乡村庄园，可能由一位名为达伦德的奥特兰克贵族所拥有。王国覆灭后，这里变成了辛迪加的防御性飞地。辛迪加的刺客和暴徒如今巡逻在围栏和码头周围，保护着那些没落贵族，使其免受南海镇当局和湖对岸被遗忘者的窥探。"},{t="阴谋的中心",b="庄园紧闭的大门后，酝酿着危险的阴谋。辛迪加公认的领袖奥里登·匹瑞诺德领主将达伦德农场作为其大本营，与他的情妇艾丽萨一同在此运筹帷幄。然而，这些不法之徒并不孤单，一名来自阿古斯唤醒者的暗影议会兽人术士纳格兹也已潜伏于此，与这群人类强盗进行着黑暗的交易。这种危险的联盟使达伦德农场成为了南海镇镇长和部落勇士共同的目标。"}},faq={{q="谁控制着达伦德农场？",a="该庄园由辛迪加占领，这是一个由奥特兰克被废黜的贵族所领导的贵族犯罪网络。辛迪加刺客和暴徒守卫着庄园，效忠于奥里登·匹瑞诺德领主。",al={"谁在达伦德农场","谁住在达伦德农场","达伦德农场的怪物"}},{q="为什么部落关心这座庄园？",a="部落针对这座庄园进行打击，旨在铲除奥里登·匹瑞诺德领主并夺回一件被窃取的纪念品：曾经属于塔蕾莎·福克斯顿的传家宝项链，她是萨尔童年时的救命恩人和知己。",al={"部落与达伦德农场","为什么部落要前往达伦德农场"}},{q="为什么联盟会派遣冒险者前往这里？",a="南海镇的赫尼·马雷布镇长指派联盟特工前往此地，消灭阿古斯唤醒者邪教的一名危险成员纳格兹，此人正与辛迪加不法之徒相互勾结。",al={"联盟与达伦德农场","马雷布镇长达伦德农场任务"}},{q="达伦德是谁？",a="有关达伦德的身份并无记载。庄园冠以其名，但没有任何确切的记录能指明其最初的所有者。",al={"谁是达伦德","达伦德背景故事"}}},fx={e469c160={q="达伦德农场是什么地方？",a="达伦德农场是一处隐蔽的农场庄园，坐落在奥特兰克山脉西部高地，毗邻洛丹米尔湖雾气笼罩的湖岸。这里曾是一处宁静的贵族庄园，如今已成为辛迪加的防御据点和行动基地。",al={"达伦德农场是什么","奥特兰克的达伦德农场","关于达伦德农场"}},b8b5cedb={q="达伦德农场发生了什么？",a="奥特兰克王国覆灭后，这座湖畔农场落入辛迪加之手。艾登·匹瑞诺德领主将这处偏僻庄园改造成自己的据点和隐居之所，并与阿古斯之潮等神秘组织建立了危险的联系。",al={"达伦德农场的历史","达伦德农场发生了什么"}},fc1f4fab={q="达伦德农场危险吗？",a="独自旅行的人在这里会面临极大的危险。庄园由技艺娴熟的辛迪加执法者、潜行杀手和阿古斯之潮的秘密特工把守，他们都忠于艾登·匹瑞诺德领主，并对外来入侵者怀有敌意。",al={"达伦德农场危险吗","达伦德农场的危险","谁在达伦德农场"}}},fp="14,352,36.473.0,20.477.1,28.201.0,42.198.1,44.172.0,16.121.0"}
P.entries["subzone:dark-portal"] = {n="黑暗之门",s="黑暗之门是一座巨大的石制门户，矗立在诅咒之地的南缘。它最初由麦迪文和古尔丹联手施展法术强行开启，是旧部落进入艾泽拉斯的宿命通道，并引发了第一次战争。",h="黑暗之门是一座巨大的石制门户，矗立在诅咒之地的南缘。它最初由麦迪文和古尔丹联手施展法术强行开启，是旧部落进入艾泽拉斯的宿命通道，并引发了第一次战争。",kw={"黑色沼泽","诅咒之地","黑暗之门","德拉诺","大传送门","古尔丹","卡德加","麦迪文"},ang={["faction:Alliance"]="对联盟来说，该门户是第一次战争和古老的暴风城陷落的庄严纪念碑，因此守望堡的法师们必须进行永恒的守望。",["race:Orc"]="这道门户是你的人民过去的痛苦门槛——旧部落在恶魔主人的奴役下行军穿过这道大门，为了战争抛弃了他们的祖居之地。"},sec={{t="跨越现实的裂隙",b="在它开启之前，这片区域曾是黑色沼泽的一部分，是一片横跨南方的潮湿湿地。当被萨格拉斯附身的麦迪文将提瑞斯法法术与德拉诺的古尔丹的邪能法术结合在一起时，一切都改变了。这场仪式耗尽了无数生命，撕裂了现实的结构。旧部落建造了巨大的石制建筑来锚定裂隙，并从其入口处行军，在第一次战争中击碎了暴风城王国。门户散发的邪能从根本上腐蚀了周围的地形，将茂密的沼泽变成了今天所见的红色石化荒地。"},{t="休眠的警惕",b="洛丹伦联盟在第二次战争中获胜后，大法师卡德加利用强大的魔法击碎了石制门框，希望永远切断与德拉诺的联系。然而，底下的空间撕裂实际上是不可摧毁的。联盟在附近建立了守望堡来监视这道伤疤，而恶魔和暗影议会的残党仍在被炸毁的火山口中潜行。今天，这座门户虽然已经重组但处于休眠状态，成为了世界之间一道双方都不敢遗弃的无声伤痕。"}},faq={{q="我现在能穿过黑暗之门吗？",a="不能。门户的石制框架依然完好，但其中的裂隙处于休眠状态。目前没有任何旅行者可以穿越这道门槛。",al={"我可以进入黑暗之门吗","黑暗之门开启了吗","通往外域的传送门"}},{q="谁最初建造了黑暗之门？",a="它是由艾泽拉斯的人类守护者麦迪文和垂死世界德拉诺的术士古尔丹共同施展仪式所创造的，这次仪式策划了点燃第一次战争的入侵行动。",al={"谁创造了黑暗之门","麦迪文古尔丹传送门","黑暗之门创造者"}},{q="为什么守望堡要监视它？",a="在第二次战争后，大法师卡德加击碎了门户最初的框架，并说服联盟监视其废墟。守望堡正是由联盟建立的，旨在维持对该地点的永久监视，以防威胁再次出现。",al={"为什么守望堡在这里","守望堡传送门守望","为什么是守望堡"}},{q="为什么门户周围的地面是红色且贫瘠的？",a="诅咒之地曾经是一片被称为黑色沼泽的肥沃湿地。为了突破现实而消耗的巨大邪能，加上来自德拉诺和恶魔野兽的腐蚀，毒害了土壤并使生态系统石化。",al={"为什么诅咒之地是死地","传送门腐蚀","为什么诅咒之地是红色的"}}},fp="11,264,23.601.0,17.516.0,47.126.0,37.192.0,40.257.0,51.236.0"}
P.entries["subzone:darkcloud-pinnacle"] = {n="黑云峰",s="黑云峰是一个坚固的牛头人定居点，坐落在千针石林升降梯以东的几座相互连接的平顶山上。这个空中据点由好战的恐怖图腾氏族把守，是他们进行区域骚扰和阴谋勾当的行动基地。",h="黑云峰是一个坚固的牛头人定居点，坐落在千针石林升降梯以东的几座相互连接的平顶山上。这个空中据点由好战的恐怖图腾氏族把守，是他们进行区域骚扰和阴谋勾当的行动基地。",kw={"阿纳克·恐怖图腾","黑云峰","恐怖图腾","哈布·邪山","平顶山","千针石林"},ang={["faction:Horde"]="占据这座平顶山的恐怖图腾氏族充当了敌对势力，威胁着从升降梯深入千针石林的旅人。",["race:Tauren"]="恐怖图腾氏族在这些平顶山上的背叛行径，与凯恩·血蹄为各部落之间力争维持的团结与和平构成了鲜明的对比。"},sec={{t="悬崖之上的堡垒",b="黑云峰横跨三座由绳桥连接的主要平顶山，俯瞰着下方的峡谷盆地。通往这些高地的路径非常有限，只能通过从峡谷底部通向木桥的陡峭天然斜坡，或者通过靠近剃刀高地附近的一处高地通道到达。在这些风吹雨打的岩石之上，恐怖图腾氏族监视着整个山谷，不仅避开了寻常的袭击，也与广大的牛头人部落隔绝开来。"},{t="平顶山上的阴谋",b="该定居点由阿纳克·恐怖图腾和哈布·邪山等首领指挥，绝非一个简单的哨站。在平顶山上发现的秘密信件表明，恐怖图腾氏族正在与一股黑暗且未知的力量积极勾结，其追求的野心与凯恩·血蹄在雷霆崖所建立的和平背道而驰。"}},faq={{q="谁控制着黑云峰？",a="这座堡垒属于恐怖图腾氏族，这是一个好战且孤僻的牛头人派系，他们公开敌视大多数外来者，并对部落抱有极深的猜忌。",al={"谁住在黑云峰","黑云峰的主人","黑云峰里有什么人"}},{q="如何到达黑云峰？",a="可以通过从峡谷底部攀爬相邻平顶山的天然坡道并穿过木制绳桥，或者经过剃刀高地附近的一座桥梁到达黑云峰。",al={"如何登上黑云峰","黑云峰路径","黑云峰入口"}},{q="是谁在此领导恐怖图腾氏族？",a="该定居点的行动由几位重要的恐怖图腾人物负责监管，其中包括阿纳克·恐怖图腾和哈布·邪山。",al={"黑云峰首领","谁领导着黑云峰","恐怖图腾首领"}},{q="恐怖图腾氏族在此策划着什么？",a="黑云峰的恐怖图腾氏族与一股未知的黑暗势力保持着秘密通讯，致力于实现威胁到千针石林稳定的阴暗目标。",al={"黑云峰发生了什么","恐怖图腾阴谋"}}},fx={["0ab7147f"]={q="黑云峰是什么地方？",a="黑云峰是牛头人村落，坐落在千针石林峡谷底部上方的高处，就在升降梯以东。村落横跨三座有人居住的台地，彼此由悬空的绳桥相连。这里是恐怖图腾部族的重要据点。这个好斗而孤立的牛头人部族严密守护自己的领地，不让外人靠近。",al={"黑云峰是什么","黑云峰信息","关于黑云峰"}},["44a431c5"]={q="黑云峰危险吗？",a="非常危险。占据黑云峰的恐怖图腾牛头人对擅闯者怀有强烈敌意，并在整个村落严密布防。这里台地高耸、绳桥狭窄，战斗时随时可能坠入下方峡谷；部族的萨满和战士也已准备好杀死任何沿山坡闯上来的人。",al={"黑云峰的危险","黑云峰有多危险","黑云峰危险吗"}}},fp="18,273,21.385.0,20.328.1,32.157.0,36.177.0,29.121.0,37.170.1"}
P.entries["subzone:darkened-bank"] = {n="暗色河滩",s="暗色河滩是暮色森林的北岸，与将这片阴影笼罩的树林与艾尔文森林分隔开来的河流接壤。它从遥远的西边一直延伸至东边的赤脊山，标志着北方相对安全地带与森林中黑暗恐怖之间的边界。",h="暗色河滩是暮色森林的北岸，与将这片阴影笼罩的树林与艾尔文森林分隔开来的河流接壤。它从遥远的西边一直延伸至东边的赤脊山，标志着北方相对安全地带与森林中黑暗恐怖之间的边界。",kw={"暗色河滩","暮色森林","艾尔文森林","拉尔斯","河流","河岸","斯温·约根"},ang={["faction:Alliance"]="对于离开艾尔文森林的联盟冒险者来说，暗色河滩是他们深入暮色森林那被诅咒的核心地带之前的初期集结地。"},sec={{t="危险的边界",b="暗色河滩沿着河流南岸延伸，与艾尔文森林隔河相望，构成了暮色森林的北缘。它从西侧的河湾处向东延伸，一直到通往赤脊山的石桥。尽管在暮色森林诅咒的笼罩下，这里的景色显得阴郁晦暗，但这片河岸通常是冒险者从艾尔文森林向南进发时的第一个立足点。在河滩的最西端坐落着一个临时的营地，流离失所的难民，包括斯温·约根和拉尔斯，在此避难，勉强处于深林威胁的边缘之外。"}},faq={{q="暗色河滩位于何处？",a="暗色河滩沿着河流横跨暮色森林的整个北岸，与艾尔文森林隔水相望。它从该区域的最西端一直延伸到通往赤脊山的桥梁。",al={"暗色河滩位置","暗色河滩在哪里","暮色森林暗色河滩"}},{q="谁居住在暗色河滩？",a="在河滩的最西端有一个简陋的避难营地，由斯温·约根和拉尔斯占据。他们被迫离开了原本在领地深处的生活，将这片北部的河岸当作一个脆弱的避风港，同时寻求帮助以对抗暮色森林的威胁。",al={"暗色河滩的营地","谁在暗色河滩","暗色河滩npc"}},{q="旅行者通常如何到达此区域？",a="旅行者可以从艾尔文森林的西南部游过河流到达暗色河滩的西段，或者沿着赤脊山大桥向西沿河岸行进。",al={"如何前往暗色河滩","前往暗色河滩"}}},fp="13,187,21.404.0,35.188.0,34.221.0,41.169.0"}
P.entries["subzone:darkmist-cavern"] = {n="黑雾洞穴",s="黑雾洞穴是一座位于尘泥沼泽西北部、被人遗弃的矿坑，现在完全被捕食性的巨型蜘蛛所占据。洞穴外摇摇欲坠的废墟暗示着这里曾经有过一个不幸的定居点，但最终被沼泽的危险吞噬。当地人对于究竟是洞穴因蜘蛛得名，还是蜘蛛因洞穴得名，仍各执一词。",h="黑雾洞穴是一座位于尘泥沼泽西北部、被人遗弃的矿坑，现在完全被捕食性的巨型蜘蛛所占据。洞穴外摇摇欲坠的废墟暗示着这里曾经有过一个不幸的定居点，但最终被沼泽的危险吞噬。当地人对于究竟是洞穴因蜘蛛得名，还是蜘蛛因洞穴得名，仍各...",kw={"黑雾洞穴","黑雾蜘蛛","尘泥沼泽","矿坑遗迹","蜘蛛矿坑","沼眼贾尔"},ang={["profession:Cooking"]="古怪的隐士“沼眼”贾尔认为黑雾蜘蛛那邪恶的眼睛是制作美味沼泽炖菜的主要配料，尽管沼泽外很少有人能接受这种口味。",["profession:Mining"]="显然，这处洞穴是过去的矿工开凿出来的，但任何想要在其岩石深处勘探的人，都必须先杀出一条血路，穿过成群结队的巢居蜘蛛。"},sec={{t="矿坑中的蛛群",b="黑雾洞穴坐落在尘泥沼泽的西北边缘，看起来曾经是一处活跃的采矿点。如今，人类的足迹早已消逝，只在入口外留下破败不堪的棚屋，而内部的隧道网络则被厚厚的蛛网所覆盖。洞穴被黑雾蜘蛛所占据，这些捕食性的恐怖生物毒性极强且体型巨大，让这里成了大意行人的死亡禁区。沼泽居民们至今仍在争论，究竟是该洞穴以潜伏其中的邪恶蛛群命名，还是蜘蛛取了这个阴森洞穴的名字。"},{t="隐士的储藏室",b="尽管这里危险重重，但偶尔还是会有拾荒者和古怪的沼泽居民造访。隐士“沼眼”贾尔因经常派遣旅行者深入蛛网密布的洞穴去采集这些巨型蜘蛛的眼睛而闻名，他坚称那是熬制肉汤的上好食材。除了这种古怪的烹饪需求外，大多数明智的旅行者都会对那布满蛛网的入口敬而远之。"}},faq={{q="什么是黑雾洞穴？",a="这是一座位于尘泥沼泽西北部的废弃矿坑，如今已完全被名为黑雾蜘蛛的剧毒巨型蜘蛛所占据。",al={"什么是黑雾洞穴","黑雾洞窟","尘泥沼泽蜘蛛洞"}},{q="洞穴外的废墟里曾住着什么人？",a="残存的小木屋遗迹表明这里曾有一个定居点或采矿营地，但其曾经的居民身份已不可考。",al={"这里曾住着谁","黑雾洞穴外的房屋","黑雾废弃村庄"}},{q="为什么当地人要冒险进入黑雾洞穴？",a="极少有人会自愿进入其中，但那个古怪的隐士“沼眼”贾尔会雇佣大胆的冒险者潜入隧道，取回蜘蛛眼来炖煮他那古怪的沼泽乱炖。",al={"为什么去黑雾洞穴","黑雾洞穴任务"}},{q="是蜘蛛还是洞穴先得的名？",a="尘泥沼泽的居民们对于究竟是蜘蛛以洞穴命名，还是洞穴以蜘蛛命名各执一词。目前还没有定论能说明哪个名字出现得更早。",al={"蜘蛛命名来源","为什么叫黑雾"}}},fp="15,322,21.557.0,15.381.0,24.155.0,40.125.0,43.179.0,49.182.0"}
P.entries["subzone:darkshire"] = {n="夜色镇",s="夜色镇，原名大汉姆莱特，是暮色森林东部一座饱经风霜的定居点。由于常年笼罩在不自然的阴霾之下且被暴风城所忽视，这座城镇只能依靠守夜人的警惕和镇民们顽强的韧性勉强维持。",h="夜色镇，原名大汉姆莱特，是暮色森林东部一座饱经风霜的定居点。由于常年笼罩在不自然的阴霾之下且被暴风城所忽视，这座城镇只能依靠守夜人的警惕和镇民们顽强的韧性勉强维持。",kw={"亮木","夜色镇","暮色森林","埃伯洛克","大汉姆莱特","守夜人","猩红乌鸦酒馆"},ang={["class:Paladin"]="随着周围墓地里死者不断复生，而恐惧的当地人几乎快要遗忘圣光，圣光勇士们会发现村庄外围总有清理不完的邪恶枯萎。",["faction:Alliance"]="夜色镇是王国破碎边疆的一个鲜明写照。联盟的英雄们在这里会受到镇民的感激，但同时也能感受到他们对暴风城那毫无作为的贵族们发自内心的苦涩怨恨。"},sec={{t="一座被遗弃的城镇",b="这里曾是一片名为大汉姆莱特的宁静林地定居点，但在第一次战争期间被旧部落夷为平地，后来才得以重建。麦迪文在卡拉赞的陨落令当地局势彻底恶化，他死前那漫长的挣扎诅咒了周围的森林，使其化作如今昏暗荒凉的暮色森林。尽管名义上属于暴风城王国，但市政厅实际上几乎得不到王室的任何援助。暴风城内政治上的瘫痪导致驻军撤离，边境无人巡逻，这迫使艾尔罗·埃伯洛克公爵和当地议会只能在阴影中自行维持残酷而封闭的治理。"},{t="黑暗中的防线",b="在西部墓地游荡的行尸和在林间出没的野性狼人的环伺下，夜色镇只能沿着木栅栏苦苦支撑。城镇的主要屏障是由阿尔泰娅·埃伯洛克指挥的平民志愿民兵组织——守夜人。这些疲惫的哨兵以镇中心为据点，在漆黑的道路上巡逻，确保道路畅通，并将潜伏在林边的恐怖生物拒之门外。抵达Scarlet Raven Tavern的旅人会发现，当地人不仅多疑、恐惧，而且急切地想要寻找任何能够挥舞武器的雇佣兵。"}},faq={{q="这座城镇为什么要改名大汉姆莱特？",a="该定居点在这一地区还是阳光明媚的森林时，最初被称为大汉姆莱特。在守护者麦迪文于附近的卡拉赞死亡后，黑暗魔法席卷了整片森林，遮蔽了阳光并唤醒了死者。随着森林逐渐腐化为暮色森林，这片被诅咒的残酷现实促使居民将村庄改名为夜色镇。",al={"为什么叫夜色镇","大汉姆莱特更名","夜色镇历史"}},{q="为什么暴风城不协助保卫夜色镇？",a="在瓦里安·乌瑞恩国王失踪后的政治动荡中，暴风城从暮色森林撤走了军队。镇民们组建了守夜人来抵御王室不再负责的威胁。",al={"暴风城军队在哪","为什么暮色森林没有守卫","为什么暴风城抛弃了夜色镇"}},{q="谁在领导夜色镇？",a="城镇的治理权掌握在艾尔罗·埃伯洛克公爵和夜色镇议会手中，他们与书记员达尔塔一同在市政厅办公。军事防卫则由艾尔罗的女儿，指挥官阿尔泰娅·埃伯洛克领导，她指挥着名为守夜人的志愿民兵组织。",al={"谁负责夜色镇","夜色镇领导层","夜色镇镇长"}},{q="什么是守夜人？",a="守夜人是阿尔泰娅·埃伯洛克出于必要而组建的当地平民民兵组织。由于暴风城军队拒绝向暮色森林部署兵力，当地镇民只能拿起武器，在阴暗的道路上巡逻，保卫边境，并击退食尸鬼的入侵和流窜的野兽。",al={"什么是守夜人","夜色镇守卫","谁保卫夜色镇"}},{q="摩根·拉迪莫尔是谁？",a="摩根·拉迪莫尔是一位老兵，他在第三次战争后回到家乡，却发现家园已毁，家人下落不明。他的寻找过程将他带到了夜色镇；关于他故事的后续，当地的记录中有所保留。",al={"摩根拉迪莫尔背景","拉迪莫尔夜色镇","拉迪莫尔是谁"}}},fp="9,162,16.603.0,20.464.0,43.311.0,45.189.0,20.208.0,24.224.0,24.200.0"}
P.entries["subzone:darkshire-town-hall"] = {n="Darkshire Town Hall",s="Darkshire Town Hall坐落在城镇广场西侧，是暮色森林当地的行政中心。在这座灯光昏暗的大厅内，镇长艾尔罗·埃伯洛克公爵和他的议会试图管理这个被蔓延的黑暗和亡灵怪物所包围的定居点。",h="Darkshire Town Hall坐落在城镇广场西侧，是暮色森林当地的行政中心。在这座灯光昏暗的大厅内，镇长艾尔罗·埃伯洛克公爵和他的议会试图管理这个被蔓延的黑暗和亡灵怪物所包围的定居点。",kw={"书记员达尔塔","议会","夜色镇","暮色森林","艾尔罗·埃伯洛克","市政厅"},ang={["faction:Alliance"]="对于联盟的旅行者来说，市政厅代表了王国南部边境脆弱的权威，展现了暴风城的保护在孤立的定居点是多么薄弱。"},sec={{t="夜色镇的权力中心",b="市政厅位于主城镇广场的正西侧，是夜色镇民政领导聚集并管理这片日益孤立的领地的地方。在饱经风霜的墙壁内，镇长艾尔罗·埃伯洛克公爵正努力维持社会秩序并保护民众，而暴风城几乎无法提供任何军事援助。与镇长一起工作的还有书记员达尔塔等市政官员，他们负责追踪当地记录以及那些敢于穿越暮色森林危险道路的旅行者，尽管在如此危险的时期，保持账目更新是一项严峻而艰巨的任务。"}},faq={{q="谁在这座建筑里领导这个城镇？",a="艾尔罗·埃伯洛克公爵担任夜色镇镇长，并在市政厅内主持镇议会。他指挥当地的防御工作，并向来访的冒险者寻求帮助，因为该镇几乎得不到来自王国首都的任何增援。",al={"谁是镇长","谁管理夜色镇","市政厅里有谁"}},{q="市政厅内保留了哪些记录？",a="书记员达尔塔负责维护城镇登记册，记录居住在夜色镇以及途经此地的旅行者。由于暮色森林中混乱和频繁的危险，他的许多日志和记录都有些过时了。",al={"书记员达尔塔的记录","达尔塔负责什么","城镇登记册"}},{q="为什么市政厅对暮色森林的生存如此重要？",a="由于暮色森林与暴风城的直接军事支持切断了联系，市政厅成为了夜色守卫和当地权威机构的运营中心。议会在这里协调平民防御，并向这片阴影笼罩的地区派遣援助。",al={"为什么市政厅很重要","夜色镇议会的角色"}}},fp="19,136,21.426.0,38.240.0,43.170.0,57.227.0"}
P.entries["subzone:darkspear-strand"] = {n="暗矛海滩",s="暗矛海滩是杜隆塔尔南部的一片海岸线，暗矛巨魔在被驱逐出回音群岛后，在此处登陆。这片海滩紧邻森金村，标志着该部落在沃金的领导下在大陆寻求庇护的艰苦开端。",h="暗矛海滩是杜隆塔尔南部的一片海岸线，暗矛巨魔在被驱逐出回音群岛后，在此处登陆。这片海滩紧邻森金村，标志着该部落在沃金的领导下在大陆寻求庇护的艰苦开端。",kw={"暗矛","暗矛海滩","杜隆塔尔","回音群岛","森金村","沃金","扎拉赞"},ang={["faction:Horde"]="在失去了他们的岛屿定居点后，这片海滩标志着暗矛巨魔在卡利姆多大陆与他们的兽人盟友并肩扎根的南部海岸。",["race:Troll"]="对于暗矛巨魔来说，踏上这片海岸不仅带来了扎拉赞背叛的刺痛，也承载着他们死里逃生并建立森金村的苦涩回忆。"},sec={{t="流亡之岸",b="当巫医扎拉赞发疯并夺取了回音群岛的控制权后，幸存的暗矛巨魔被迫放弃了他们海外的家园。绝望的难民们渡过狭窄的水域，登上了这片被阳光灼烤的海岸。幸存者们没有分散到杜隆塔尔那充满敌意的红色荒原中，而是聚拢在距离海岸线仅几码远的地方，建造了森金村。今天，这片海滩静静地提醒着他们曾经流离失所的过去，隔着海浪眺望着他们仍渴望夺回的群岛。"}},faq={{q="暗矛海滩发生了什么？",a="这片海岸线是暗矛巨魔在逃离回音群岛后的登陆点。当扎拉赞对他的族人施展黑魔法时，幸存者们撤离并渡海来到这里，随即在附近聚集建立了森金村。",al={"为什么叫暗矛海滩","暗矛海滩背景故事","这片海滩是什么"}},{q="暗矛部族为什么要离开回音群岛？",a="巫医扎拉赞背叛了他的族人，并利用黑暗巫毒奴役了同胞的思想。沃金酋长率领其余未受腐蚀的暗矛巨魔逃离了群岛以躲避完全的奴役，并在这片海滩上岸。",al={"巨魔为什么离开回音群岛","扎拉赞流亡","回音群岛撤离"}},{q="暗矛海滩旁边有什么聚居地？",a="森金村位于距离海滩仅几码远的内陆。它是由难民在登上这片海滩后立即建立的，也是暗矛在杜隆塔尔的主要前哨站和精神中心。",al={"暗矛海滩附近的村庄","海滩旁边的城镇","森金村位置"}}},fp="16,197,16.370.0,34.190.0,43.261.0,52.163.0"}
P.entries["subzone:darkwhisper-gorge"] = {n="暗语峡谷",s="暗语峡谷是一道地势险峻、恶魔横行的峡谷，开凿在冬泉谷的南部高地上。当阿克蒙德在第三次战争的高潮中被消灭时，破碎的燃烧军团残部逃离了海加尔山的斜坡，并在这些崎岖的深渊中固守下来。如今，强大的恶魔在山岭间徘徊，守护着古老的矿产和黑暗的位面圣物。",h="暗语峡谷是一道地势险峻、恶魔横行的峡谷，开凿在冬泉谷的南部高地上。当阿克蒙德在第三次战争的高潮中被消灭时，破碎的燃烧军团残部逃离了海加尔山的斜坡，并在这些崎岖的深渊中固守下来。如今，强大的恶魔在山岭间徘徊，守护着古老的矿...",kw={"燃烧军团","暗语峡谷","地语者弗兰扎尔","暗影之眼","赫德瑞恩","赫德瑞恩女士","海加尔山","维'艾尔","冬泉谷"},ang={["class:Warlock"]="在这些洞穴中潜行的赫德瑞恩恶魔掌握着至关重要的位面组件，这使得该峡谷成为术士们磨练召唤仪式（例如召唤末日守卫）技艺的主要试炼场。",["profession:Mining"]="险峻的峡谷隐藏着丰富的真银和富瑟银矿脉，足以奖励那些敢于潜行绕过精英恶魔的胆大矿工。"},sec={{t="雪原中的军团据点",b="在海加尔山顶阿克蒙德战败后，燃烧军团幸存的恶魔四散逃往周边山脉。一支纪律严明的先遣队在暗语峡谷避难，将冬泉谷的南部边界变成了一个致命的据点。在赫德瑞恩女士的领导下，赫德瑞恩恶魔（包括致命的法力追猎者、屠戮者和见习者）在此盘踞，他们誓死保卫着地下的隧道和火热的营地。除了这些精英居民带来的直接威胁外，在峡谷的最低点还有一道阴森的密封拱门，暗示着通往神圣山脉更高处的封闭通道。"},{t="隐藏的试剂与稀有的知识",b="尽管存在巨大的危险，勇敢的冒险者和投机者仍会为了极其丰厚的财富而闯入峡谷。峡谷中盛产真银和密集的瑟银矿。在阴暗的洞穴深处，一些不寻常的居民在此苟延残喘，例如贩卖魔布和格罗姆之血等邪能试剂的维'艾尔，以及难以捉摸的高等精灵地语者弗兰扎尔，他掌握着关于熔炼稀有源质的古老冶金知识。"}},faq={{q="为什么冬泉谷会有这么多恶魔？",a="暗语峡谷中的恶魔是第三次战争期间燃烧军团入侵海加尔山后的幸存者。在阿克蒙德在世界之树被击杀后，他残破的军队并没有被完全消灭，而是撤退到了这些深渊中重整旗鼓。",al={"这里的恶魔来源","暗语峡谷军团背景","恶魔从哪里来"}},{q="峡谷后方的密封大门是什么？",a="在峡谷南部深处，矗立着一道刻满符文的拱门和一道活跃的魔法屏障。它守卫着直接通往海加尔山的山口；旅行者可以通过从永望镇飞行前往海加尔山的污染山麓。",al={"暗语峡谷传送门","冬泉谷副本入口","海加尔山大门"}},{q="这里的恶魔由谁领导？",a="营地由一群被称为赫德瑞恩的恶魔入侵者所控制，看起来是由赫德瑞恩女士指挥。他们与被称为法力追猎者的地狱犬、屠戮者和见习者一起在峡谷中巡逻。",al={"暗语峡谷首领","赫德瑞恩领袖","谁统治暗语峡谷"}},{q="为什么冒险者要冒险进入暗语峡谷？",a="该地区极其危险，需要协同作战的小队才能安全通行。然而，这里吸引了寻求位面绑定的术士、寻找稀有掉落物“暗影之眼”的牧师、寻找富瑟银矿脉的铁匠和矿工，以及寻找隐居的地语者弗兰扎尔的学者。",al={"为什么去暗语峡谷","暗语峡谷任务","暗语峡谷奖励"}}},fp="17,388,29.628.0,34.498.0,45.261.0,49.238.0,26.211.0,55.285.0"}
P.entries["subzone:darnassus"] = {n="达纳苏斯",s="在泰达希尔那连绵起伏的枝叶高处，坐落着卡多雷的避难之都——达纳苏斯。它依傍着宁静的水域和葱郁的林地而建，是暗夜精灵的精神核心，也是联盟在卡利姆多北部的关键堡垒。大祭司泰兰德·语风与大德鲁伊范达尔·鹿盔在此坐镇，指引着他们的人民度过刚刚获得凡人寿命后的重重考验。",h="在泰达希尔那连绵起伏的枝叶高处，坐落着卡多雷的避难之都——达纳苏斯。它依傍着宁静的水域和葱郁的林地而建，是暗夜精灵的精神核心，也是联盟在卡利姆多北部的关键堡垒。大祭司泰兰德·语风与大德鲁伊范达尔·鹿盔在此坐镇，指引着他们...",kw={"主城","达纳苏斯","卡多雷","鹿盔","泰达希尔","temple of the moon","泰兰德"},ang={["faction:Alliance"]="对于来自东部王国的旅客而言，达纳苏斯是一处与世隔绝、宁静祥和的避风港，也是联盟在卡利姆多大陆上不可或缺的锚点。",["race:NightElf"]="达纳苏斯是卡多雷的文化与政治中心，也是你们的人民在经历第三次战争的惨痛牺牲后，重新开始并获得主权庇护的地方。"},sec={{t="枝头上的避难所",b="达纳苏斯兴建于第三次战争之后，旨在纪念暗夜精灵在失去了神圣的世界之树诺达希尔所赋予的永恒寿命后依然得以幸存。与铁炉堡或暴风城那密集坚固的石质都市不同，达纳苏斯是一座开放且安详的定居点，处处可见木质建筑、闪烁的神龛，以及横跨晶莹湖泊的拱桥。警惕的哨兵、高耸的战争古树和塑造树木的德鲁伊们守护着这里的道路，确保大自然的宁静能在这座城市中得以保存。"},{t="分裂的领导层",b="虽然达纳苏斯代表了卡多雷的统一，但其治理结构却反映出微妙的分歧。大祭司泰兰德·语风在艾露恩神殿中主持民政与军事事务，身边环绕着艾露恩姐妹会。与此同时，塞纳里奥议会的事务则由大德鲁伊范达尔·鹿盔掌管，他曾主张种植泰达希尔以恢复精灵们失去的永恒寿命。由于玛法里奥·怒风在翡翠梦境深处陷入了神秘的沉睡，鹿盔对于种族未来的激进设想，常与性格更为沉稳的祭司阶层产生摩擦。"}},faq={{q="谁统治达纳苏斯？",a="大祭司泰兰德·语风在艾露恩神殿中作为暗夜精灵社会的主要领袖，统领着哨兵部队。德鲁伊事务则由大德鲁伊范达尔·鹿盔指挥，在玛法里奥·怒风缺席期间，由他领导塞纳里奥议会。",al={"达纳苏斯领袖","谁在管理达纳苏斯","暗夜精灵领袖"}},{q="旅客如何从泰达希尔外部到达达纳苏斯？",a="由于达纳苏斯坐落在巨大的世界之树岛屿的枝干之上，船只和飞行航线仅能抵达树根处的鲁瑟兰村。从鲁瑟兰村出发，有一座魔法传送门可以将访客传送至城内。",al={"如何前往达纳苏斯","达纳苏斯入口","进入达纳苏斯"}},{q="为什么达纳苏斯建城时间这么晚？",a="在第三次战争中海加尔山遭到破坏后，暗夜精灵失去了他们的永恒寿命和古老的生活方式。范达尔·鹿盔及其盟友在卡利姆多海岸外种植了泰达希尔，达纳苏斯便在其枝干上扎根，成为他们人民的一处新避难所。",al={"为什么达纳苏斯是新的","达纳苏斯是什么时候建造的","达纳苏斯历史"}},{q="玛法里奥·怒风在哪里？",a="大德鲁伊玛法里奥·怒风下落不明，他的灵魂被困在翡翠梦境中，陷入了一场深沉且原因未明的沉睡。他的缺席使得达纳苏斯的塞纳里奥议会完全交由范达尔·鹿盔领导。",al={"玛法里奥在哪里","玛法里奥在达纳苏斯吗","玛法里奥状态"}}},fp="9,344,23.465.0,20.562.0,20.203.0,57.204.0,38.279.0,29.190.0"}
P.entries["subzone:darrow-hill"] = {n="达隆山",s="达隆山是一片位于希尔斯布莱德丘陵北部，紧邻海角下方，地势较高的崎岖草原。山狮和雄鹿在开阔的山坡上吃草，而凶猛的雪人则潜伏在点缀着山腰的丘陵洞穴内。这里蕴藏着丰富的奥特兰克花岗岩矿脉，是一个危险的前线，野兽和敌对的旅行者在此不断冲突。",h="达隆山是一片位于希尔斯布莱德丘陵北部，紧邻海角下方，地势较高的崎岖草原。山狮和雄鹿在开阔的山坡上吃草，而凶猛的雪人则潜伏在点缀着山腰的丘陵洞穴内。这里蕴藏着丰富的奥特兰克花岗岩矿脉，是一个危险的前线，野兽和敌对的旅行者在...",kw={"奥特兰克花岗岩","达隆山","丘陵洞穴","海角","希尔斯布莱德丘陵","雪人"},ang={["class:Hunter"]="这些山丘是山狮和雄鹿在奥特兰克林木线和下层草原之间移动时的绝佳狩猎场。",["profession:Mining"]="贯穿达隆山的洞穴网络，特别是丘陵洞穴，拥有丰富的奥特兰克花岗岩和区域矿脉，前提是你能够对付附近筑巢的雪人。"},sec={{t="危险的前线",b="达隆山坐落在海角下方北部的山脉脚下，连接着希尔斯布莱德南部的起伏牧场与奥特兰克崎岖寒冷的高地。山狮和雄鹿在高高的草丛中潜行，与从丘陵洞穴中涌出的高大雪人共享着这些岩石坡地。除了凶猛的野生动物，洞穴墙壁还隐藏着致密的奥特兰克花岗岩矿床，吸引着采石工、矿工和冒险者陷入危险之中。由于身处相互竞争的地区主张之间，其道路对于毫无防备的任何阵营的旅行者来说都极其危险。"}},faq={{q="达隆山位于何处？",a="达隆山位于希尔斯布莱德丘陵的北部边缘，坐落在被称为海角的岩石峭壁正南侧，以及通往奥特兰克的主要山路以东。",al={"达隆山位置","达隆山在哪里","达隆山地图"}},{q="哪些生物威胁着达隆山附近的旅行者？",a="开阔的山坡上有雄鹿和山狮徘徊，而野蛮的雪人则在丘陵洞穴周围和内部出没。",al={"达隆山怪物","达隆山有什么生物"}},{q="丘陵洞穴里有什么？",a="丘陵洞穴里到处是凶猛的雪人，岩石洞壁中还嵌有珍贵的奥特兰克花岗岩矿脉。",al={"丘陵洞穴","达隆山洞穴","洞穴里有什么"}},{q="为什么这个地区被认为对旅行者来说非常危险？",a="除了凶猛的野生动物和雪人巢穴外，直接邻近争议道路的开阔地理位置使达隆山成为了一个臭名昭著的冲突点，联盟和部落的漫游者经常在此相互伏击。",al={"为什么达隆山很危险","达隆山pvp","达隆山的危险"}}},fp="11,238,22.471.0,29.153.0,53.111.0,46.117.0,55.176.0"}
P.entries["subzone:darrowmere-lake"] = {n="达隆米尔湖",s="达隆米尔湖是一片广阔的淡水湖，位于西瘟疫之地的东南部。在湖心坐落着凯尔达隆的要塞岛，其废墟之下隐藏着The Cult of the Damned令人恐惧的通灵学院：通灵学院。",h="达隆米尔湖是一片广阔的淡水湖，位于西瘟疫之地的东南部。在湖心坐落着凯尔达隆的要塞岛，其废墟之下隐藏着The Cult of the Damned令人恐惧的通灵学院：通灵学院。",kw={"巴罗夫","凯尔达隆","达隆米尔","达隆米尔湖","普罗德摩尔舰队","通灵学院","索多里尔河","西瘟疫之地"},ang={["faction:Alliance"]="对于联盟老兵来说，达隆米尔湖是一处关键的海战前线，普罗德摩尔的舰队曾在此与旧部落交战。",["race:Undead"]="该湖泊标志着凯尔达隆的边界，生前的巴罗夫家族曾在此与巫妖王交易，将他们的家园变成了令人恐惧的通灵学院。"},sec={{t="一段传奇的内陆海",b="达隆米尔湖是东部王国最大的内陆水域之一，其边缘环绕着受瘟疫侵蚀的洛丹伦森林，由索多里尔河和达隆米尔河补给。在第二次战争期间，这些深邃的水域见证了部落与海军上将戴林·普罗德摩尔舰队之间激烈的海战。部落还袭击了位于湖心的凯尔达隆要塞，洗劫了它并夺走了那里的古老符文石。这里曾是巴罗夫家族繁荣的水路和贸易动脉，如今已变成瘟疫之地中心地带一片阴森、笼罩在迷雾中的盆地。"},{t="水面上的阴影",b="统治着湖中心的是凯尔达隆，这里曾是巴罗夫家族引以为傲的祖居地。在其破败的地基之下坐落着通灵学院，这是天灾军团主要的死灵法术与黑暗艺术学院。围绕着岛屿的水域停滞不前且危机四伏，反映了The Cult of the Damned黑暗的遗产。横渡湖面的冒险者不仅要面对瘟疫肆虐的乡野带来的危险，还必须抵御那座位于湖心堡垒所散发出的无尽恐惧。"}},faq={{q="达隆米尔湖位于哪里？",a="达隆米尔湖位于西瘟疫之地的东南角，北连索多里尔河，南接达隆米尔河。",al={"达隆米尔位置","达隆米尔湖在哪里","如何前往达隆米尔"}},{q="湖中心的岛上有什么？",a="岛上是凯尔达隆，这是一座古老的定居点，曾由贵族巴罗夫家族统治。在荒废的城镇之下坐落着通灵学院，这是一所由The Cult of the Damned运营的庞大黑暗魔法学院。",al={"达隆米尔岛屿","岛上有什么","凯尔达隆位置"}},{q="达隆米尔湖在第二次战争中扮演了什么角色？",a="该湖泊曾是一片充满争议的水域，普罗德摩尔的舰队在此与部落进行过海战。部落还突袭了位于湖心岛的凯尔达隆，洗劫了要塞并夺取了其古老的符文石。",al={"第二次战争达隆米尔","达隆米尔海战","达隆米尔历史"}},{q="船只还能驶入达隆米尔湖吗？",a="虽然在第二次战争期间大型海军舰队曾在此航行，但连接湖泊的河流如今出现了陡峭的瀑布和浅滩，使得大型船只无法从海上驶入。",al={"达隆米尔船只通行","船只能否到达达隆米尔"}}},fp="15,258,20.589.0,24.493.0,33.173.0,48.202.0,53.220.0,42.196.0"}
P.entries["subzone:darrowshire"] = {n="达隆郡",s="达隆郡是位于东瘟疫之地南部群山中的一座废墟村庄，曾经是洛丹伦一个宁静的小村落。在第三次战争期间，这里的居民为了对抗势不可挡的天灾军团，进行了一场绝望而悲壮的抵抗。如今，在寂静之中，这里只剩下残垣断壁、躁动的灵魂和苦涩的记忆。",h="达隆郡是位于东瘟疫之地南部群山中的一座废墟村庄，曾经是洛丹伦一个宁静的小村落。在第三次战争期间，这里的居民为了对抗势不可挡的天灾军团，进行了一场绝望而悲壮的抵抗。如今，在寂静之中，这里只剩下残垣断壁、躁动的灵魂和苦涩的记...",kw={"达隆郡之战","达隆郡","东瘟疫之地","食尸鬼","蹂躏者霍古斯","洛丹伦","玛杜克·布莱克伍德"},ang={["class:Paladin"]="达隆郡的悲惨命运不断呼唤着圣骑士们将净化的圣光带到瘟疫之地，既是为了消灭亡灵，也是为了让受尽折磨的灵魂得到安息。",["race:Human"]="对于联盟的人类来说，达隆郡是洛丹伦所遭受的毁灭性打击的严肃见证，这里曾经有普通民众为了保卫家人而进行过一场毫无希望的抵抗。"},sec={{t="悲壮的抵抗",b="在瘟疫吞噬北部洛丹伦之前，达隆郡曾是一个坐落在南部悬崖下的简朴乡村。当第三次战争期间天灾军团南下时，由死亡骑士玛杜克·布莱克伍德和食尸鬼领主蹂躏者霍古斯率领的部队围攻了这座城镇。村民和当地的守卫者英勇奋战，在绝境中暂时守住了防线。最终，防线崩溃，全镇上下惨遭屠戮，无一幸免。达隆郡许多阵亡的守卫者死后不仅没能得到安宁，反而被复活成了食尸鬼，成为了加强天灾军团实力的工具，使这座村庄成为了一座阴森、空旷、缅怀逝去勇气的纪念地。"},{t="战斗的回响",b="尽管早已被生者遗弃，达隆郡却远非空无一物。那场屠杀留下的沉重精神压力沉重地笼罩着这片山谷，将镇民的灵魂残片困在废墟之中。路过的旅人报告说这里会出现奇怪的现象，包括令人毛骨悚然的重现——那场悲惨的战斗会在幽灵般的寂静中再次上演。这片土地依然浸透着哀伤，成为了天灾军团从王国手中夺走一切的凄凉见证。"}},faq={{q="达隆郡发生了什么事？",a="达隆郡在第三次战争中被摧毁，当时一支庞大的天灾军团军队袭击了这座城镇。在死亡骑士玛杜克·布莱克伍德和食尸鬼领主蹂躏者霍古斯的带领下，亡灵淹没了城镇的守卫者并屠杀了所有居民，使这里沦为一片废墟。",al={"达隆郡历史","达隆郡为何被毁","这里发生了什么"}},{q="领导天灾军团袭击达隆郡的领袖是谁？",a="这次袭击由死亡骑士玛杜克·布莱克伍德和狰狞的食尸鬼领主蹂躏者霍古斯共同领导。他们的部队合力击溃了村庄的守卫者，使这里走向了毁灭。",al={"谁袭击了达隆郡","达隆郡的恶棍","霍古斯和玛杜克"}},{q="为什么达隆郡会有鬼魂出没？",a="那场屠杀发生得太过突然且惨绝人寰，导致阵亡者的灵魂依然被束缚在这片土地上。除了在破败的建筑中徘徊的鬼魂幻影外，据说那场残酷的战斗还会以幽灵的形式周期性地重演，将死者困在他们生命最后那悲惨的时刻。",al={"达隆郡的幽灵","为什么达隆郡会有灵魂"}},{q="那些保卫城镇而死的村民后来怎么样了？",a="大多数守卫者被当场屠杀，他们的尸体中有许多被通灵师复活成了毫无思想的食尸鬼，被迫为摧毁了他们家园的天灾军团效力。",al={"达隆郡村民","达隆郡的守卫者"}}},fp="11,245,14.578.0,20.354.0,29.246.0,58.184.0,27.224.0,57.147.0"}
P.entries["subzone:dawning-isles"] = {n="黎明岛",s="黎明岛是位于银松森林东缘、洛丹米尔湖内的一群低洼小岛。这里曾是风景优美的度假胜地，但如今已遭受亡灵瘟疫的侵蚀，并被好斗的鱼人所占据。",h="黎明岛是位于银松森林东缘、洛丹米尔湖内的一群低洼小岛。这里曾是风景优美的度假胜地，但如今已遭受亡灵瘟疫的侵蚀，并被好斗的鱼人所占据。",kw={"黎明岛","洛丹伦","洛丹米尔湖","银松森林","邪鳍"},ang={["faction:Alliance"]="这些受瘟疫侵蚀的岛屿沉重地提醒着人们，天灾军团的腐化究竟蔓延到了洛丹伦多么秀丽的水域。",["race:Undead"]="受瘟疫侵蚀的黎明岛位于洛丹米尔湖上，在幽暗城的西侧入口处清晰可见，而占据此地的邪鳍鱼人数量每年都在增加。"},sec={{t="湖中瘟疫",b="在第三次战争之前，黎明岛以洛丹米尔湖平静清澈水域上的风景胜地而闻名。当亡灵瘟疫席卷洛丹伦时，腐化渗入了湖泊的浅滩。植被变得苍白腐烂，昔日的宁静也随之消散。今天，邪鳍鱼人部落占据了泥泞的海岸和丛生的灌木丛，并凶猛地保卫着他们不断扩张的领地，阻拦任何试图横渡湖泊的人。"},{t="鱼人据点",b="鱼人并非岛上唯一的威胁。曾经有沼泽兽与它们一起在这些受瘟疫侵蚀的小岛上徘徊，但沼泽兽此后便消失了。随着它们的消失，邪鳍鱼人的数量激增，以至于鱼人现在彻底控制了这些岛屿，将原本宁静的岛链变成了它们在洛丹米尔湖上的据点。"}},faq={{q="黎明岛位于何处？",a="黎明岛位于洛丹米尔湖中，毗邻银松森林的东部边界，坐落在洛丹伦废墟的正西面。",al={"黎明岛位置","黎明岛在哪里","黎明岛地图"}},{q="黎明岛上栖息着哪些生物？",a="这些岛屿主要被邪鳍鱼人部落所盘踞，它们在受腐蚀的海岸线上繁衍生息。过去，危险的沼泽兽也会在这些小岛上徘徊，不过随着鱼人数量的泛滥，它们已基本绝迹。",al={"黎明岛怪物","黎明岛上的生物"}},{q="为什么这里的树木和海岸在腐烂？",a="在第三次战争期间，当亡灵瘟疫席卷洛丹伦时，这些岛屿受到了污染。水和土壤吸收了瘟疫，导致植被中毒，使得这些小岛变得阴暗、病态且腐朽。",al={"为什么黎明岛被瘟疫腐蚀","洛丹米尔湖瘟疫黎明岛"}}},fp="13,217,18.461.0,19.256.0,36.125.0,41.178.0,42.216.0"}
P.entries["subzone:dawning-wood-catacombs"] = {n="黎明墓穴",s="黎明墓穴深凿于乌鸦岭墓地之下，是一座黑暗的迷宫，里面充满了暮色森林中最凶猛的不死生物。那些敢于进入这些地下隧道的人，将面临成群结队的骷髅守卫和食肉食尸鬼的围攻。",h="黎明墓穴深凿于乌鸦岭墓地之下，是一座黑暗的迷宫，里面充满了暮色森林中最凶猛的不死生物。那些敢于进入这些地下隧道的人，将面临成群结队的骷髅守卫和食肉食尸鬼的围攻。",kw={"地下室","黎明墓穴","暮色森林","食尸鬼","乌鸦岭墓地","骷髅","不死生物"},ang={["class:Paladin"]="这座墓穴是王国陨落者的冷酷见证，它呼唤着圣光的愤怒来净化这些被亵渎的陵墓。",["class:Priest"]="在乌鸦岭的石拱顶下，不安的灵魂和腐烂的尸体呼喊着寻求最终的安息，使得墓穴成为了对信仰的严峻考验。"},sec={{t="乌鸦岭下方",b="在暮色森林笼罩在暮光诅咒之前很久，黎明墓穴曾是周边森林逝者的安息之所。如今，这些深埋在破败的乌鸦岭墓地之下的黑暗石廊，囚禁着该地区最致命的不死生物。墓穴分为两个截然不同的地下侧翼：西侧通道由守护先祖陵墓的骷髅卫兵把守，而东侧通道则通向一个充满饥饿、携带瘟疫的食尸鬼的恶臭巢穴。独自前来的旅行者很少能从其深处生还。"}},faq={{q="黎明墓穴位于何处？",a="墓穴位于暮色森林最西端的乌鸦岭墓地正下方。入口位于地面上纵横交错的墓碑和破败的地下室之间。",al={"墓穴位置","黎明墓穴在哪里","如何前往墓穴"}},{q="墓穴中潜伏着什么？",a="墓穴中盘踞着暮色森林中最密集、最凶猛的不死生物。西侧侧翼由全副武装的骷髅战士守卫，而东侧隧道则遍布着野蛮且身染瘟疫的食尸鬼。",al={"墓穴敌人","黎明墓穴里有什么","墓穴怪物"}},{q="墓穴最初为何建造？",a="早在该地区还是一片葱郁之时，墓穴作为当地家族和名人的大型墓葬拱顶而被开凿。后来吞噬森林的黑暗诅咒使得那些被埋葬的人重新复活了。",al={"墓穴历史","为什么要建造墓穴","墓穴的原始用途"}},{q="独自探索墓穴安全吗？",a="独自冒险进入墓穴是非常危险的。幽闭的隧道几乎没有撤退的空间，不死生物会密集成群，以极具侵略性的攻势压垮落单的旅行者。",al={"我可以单刷墓穴吗","墓穴危险性","墓穴难度高吗"}}},fp="22,149,18.517.0,45.162.0,32.191.0,48.192.0,42.161.0"}
P.entries["subzone:dead-acre"] = {n="死亡农地",s="死亡农地是一片位于西部荒野东南部，靠近通往暮色森林的河桥处，早已荒废且冒着余烟的农庄。在迪菲亚潜行者于乡间发动起义时，这里被付之一炬，如今焦黑的田地已被人们遗弃，只剩下失控的收割傀儡在徘徊。",h="死亡农地是一片位于西部荒野东南部，靠近通往暮色森林的河桥处，早已荒废且冒着余烟的农庄。在迪菲亚潜行者于乡间发动起义时，这里被付之一炬，如今焦黑的田地已被人们遗弃，只剩下失控的收割傀儡在徘徊。",kw={"烧毁的农场","死亡农地","迪菲亚","农场","收割守望者","西部荒野"},ang={["faction:Alliance"]="死亡农地是暴风城忽视西部荒野的凄凉写照，让忠诚的农民在面对迪菲亚潜行者的暴力掠夺时毫无防卫能力。"},sec={{t="边境的灰烬",b="死亡农地位于连接哨兵岭与暮色森林的道路北侧，曾经是西部荒野众多粮仓农场中颇有产出的一处家园。当迪菲亚潜行者发动叛乱并驱逐了当地地主时，这座农场遭到了毁灭性的打击。农舍及其周边的作物被付之一炬，只留下焦黑的木材、冒烟的土地，以及依然在荒芜的土地上收割作物的机械收割守望者。"}},faq={{q="这个地方为什么叫死亡农地？",a="迪菲亚潜行者在控制西部荒野时，将该农庄及其周边的田地夷为平地。正是因为他们留下的焦黑废墟和冒烟的土地，才让这里获得了这样一个阴森的名字。",al={"为什么叫死亡农地","死亡农地发生了什么","它为什么被烧毁"}},{q="为什么会有机械收割守望者在这里徘徊？",a="像西部荒野各地的许多农场一样，当定居者逃离或死亡时，他们留下了用于照料庄稼的机械收割机。由于损坏或缺乏看管，这些自动化的收割守望者继续在烧焦的田地里无休止地巡逻，并攻击任何靠近的人。",al={"死亡农地的收割傀儡","为什么这里有傀儡","收割守望者"}},{q="死亡农地在哪里？",a="死亡农地坐落在西部荒野东南部，紧邻通往暮色森林阴影边境的桥梁北侧主路旁。",al={"死亡农地位置","死亡农地在哪里","如何找到死亡农地"}}},fp="9,210,19.364.0,39.156.0,51.218.0,31.99.0"}
P.entries["subzone:dead-field"] = {n="亡者农场",s="亡者农场位于银松森林北部，是一处荒废、被枯萎病侵蚀的农庄。这里曾经是宁静的乡村农田，但现在已被腐皮豺狼人占据，并被改造成了天灾军团的前线集结地。被遗忘者多次尝试清剿该地区，却都在女妖夜刃的指挥下无功而返。",h="亡者农场位于银松森林北部，是一处荒废、被枯萎病侵蚀的农庄。这里曾经是宁静的乡村农田，但现在已被腐皮豺狼人占据，并被改造成了天灾军团的前线集结地。被遗忘者多次尝试清剿该地区，却都在女妖夜刃的指挥下无功而返。",kw={"女妖","亡者农场","死亡猎手","夜刃","腐皮","银松森林","图勒·鸦爪"},ang={["class:Rogue"]="死亡猎手侦察小队密切监视着农场；渗透进豺狼人的队伍并打击其指挥系统是一项关键的战术重点。",["race:Undead"]="对被遗忘者而言，天灾军团在亡者农场的立足点对连接瑟伯切尔和洛丹伦北部的道路构成了直接威胁，必须尽快将其清除。"},sec={{t="一处受枯萎病侵蚀的集结地",b="位于银松森林北部的这片农庄早已所剩无几，其原本的居民在第三次战争中早已丧生。如今，这片废墟成了腐皮豺狼人的行动基地，他们甘愿充当天灾军团的走卒。随着这些豺狼人的数量不断增加，路过该地区的死亡猎手斥候发现了他们即将进行军事动员的迹象，这威胁到了被遗忘者的补给线和哨所。被遗忘者对该农场进行的小规模突袭屡屡失败，每当她的豺狼人奴仆陷入险境，女妖夜刃这只哀嚎的幽灵就会现身将其击退。"},{t="鸦爪的野心",b="腐皮豺狼人并非孤军奋战。他们在亡者农场的行动是由驻扎在芬里斯岛的死灵法师图勒·鸦爪在幕后策划的。为了确立天灾军团对银松森林的统治并以此将希尔瓦娜斯的军队逐出洛丹伦，鸦爪将魔法幻象投射到农场，以视察他的亡灵爪牙并向闯入的被遗忘者发出警告。"}},faq={{q="什么是亡者农场？",a="亡者农场位于银松森林北部，是一处破败不堪、受枯萎病侵蚀的农庄。它曾是一座普通的人类农场，如今已沦为废墟，并被效忠于天灾军团的腐皮豺狼人所占据。",al={"亡者农场 银松森林","亡者农场在哪里","亡者农场发生了什么"}},{q="为什么农场里有豺狼人？",a="这些腐皮豺狼人受到天灾军团的控制。他们将这处农庄当作前线集结地，用以集结兵力，准备袭击银松森林北部的被遗忘者阵地。",al={"为什么有腐皮豺狼人","腐皮豺狼人 亡者农场","天灾军团豺狼人"}},{q="夜刃是谁？",a="夜刃是天灾军团的一名女妖，负责指挥农场里的腐皮豺狼人。每当被遗忘者的突击部队进攻营地时，她就会现身保卫她的奴仆，击退了以往多次收复该地区的尝试。",al={"夜刃 女妖","亡者农场里的女妖","谁在保护豺狼人"}},{q="这里的天灾军团由谁指挥？",a="这个营地听命于图勒·鸦爪，他是一位强大的死灵法师，驻扎在附近的芬里斯岛。他通过幻象和魔法监视来协调豺狼人的行动，以此骚扰被遗忘者的扩张。",al={"谁控制着亡者农场","图勒·鸦爪 亡者农场","谁负责指挥"}}},fp="10,187,25.490.0,20.276.1,23.189.0,33.154.0,17.186.0,37.200.1"}
